local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["item:stalker-claws"] = {n="Stalker Claws",s="Stalker Claws är klorna från präriejägare som strövar över The Rolling Plains i Mulgore. Taurenschamaner använder dem som viktiga delar när de snidar traditionella reningstotemer för att rena förorenade vattenkällor.",h="Stalker Claws är klorna från präriejägare som strövar över The Rolling Plains i Mulgore.",kw={"reningstotem","mulgore","mull thunderhorn","präriejägare","stalker claws","thunderhorn-totem","vattenkälla"},ang={["class:Shaman"]="Klor från vilda slättrovdjur fångar naturens vilda renhet och är ett oumbärligt material för att binda samman och stärka reningstotemer.",["race:Tauren"]="Att samla in klorna hjälper din stam att fullgöra sin heliga plikt att återställa de heliga vattnen som förgiftats av vårdslösa inkräktare från industrin."},sec={{t="Slättens rovdjur",b="Mulgore gräsbevuxna stäpper är hem åt dödliga rovdjur, däribland de smygande präriejägarna. Dessa bestar överlever med rå instinkt och dödlig precision, en viktig balans i Moder Jordas skapelse. Mull Thunderhorn vill läka det fördärvade landet och behöver klorna, inte av illvilja mot djuren, utan för att deras rena, naturliga jaktvildhet har den andliga kraft som krävs för att motverka konstgjord förorening."},{t="Reningen av källorna",b="När gobliners företag började borra och gräva efter malm i centrala Kalimdor sipprade kemiska gifter djupt ner i grundvattnet som försörjer taurenfolkets förfäders vattenkällor. I synnerhet Thunderhorn Water Well föll offer för en vidrig förorening. Genom att binda samman Stalker Claws och Cougar Claws i en Thunderhorn Cleansing Totem skapar stamschamaner en andlig kanal som kan skura bort smutsen och det onaturliga slammet från jordens naturliga källor."}},faq={{q="Var hittar man Stalker Claws?",a="De samlas in genom jakt på präriejägare bland Mulgore gräsbevuxna kullar, främst öster och väster om Bloodhoof Village.",al={"var hittar man stalker claws","vem släpper stalker claws","stalker claws källa"}},{q="Varför behöver Mull Thunderhorn klorna?",a="Mull Thunderhorn använder klorna tillsammans med klor från slättens pumor för att tillverka en Thunderhorn Cleansing Totem. De inhemska jägarnas medfödda renhet och styrka behövs för att rena de förgiftade vattenkällorna.",al={"varför samla stalker claws","mull thunderhorns syfte","användning av stalker claws"}},{q="Varför är Thunderhorn Water Well förorenad?",a="Källan lider av onaturliga industriföroreningar från goblinernas verksamhet i Mulgore, som rubbar den naturliga balansen och förgiftar den lokala grundvattennivån.",al={"vem förgiftade källan","varför är thunderhorn-källan förorenad","förorening i thunderhorn"}},{q="Vad händer när klorna har samlats in?",a="När klorna har samlats in snidar Mull dem till en reningstotem, som sedan måste bäras direkt till Thunderhorn Water Well för att driva bort den kvarvarande föroreningen.",al={"what comes next","nästa steg efter klorna","ritual för reningstotem"}}},fx={a496bd75={q="Vad är Stalker Claws?",a="Stalker Claws är de naturliga klor som tas från prairie stalkers, våldsamma kattdjur som jagar på Mulgore-slätterna. För en utomstående är de bara enkla jakttroféer, men tauren-schamaner ser dem som uttryck för varelsens naturliga jaktinstinkt och samhörighet med landet.",al={"vad är stalker claws","stalker claws: föremål","stalker claw"}}},fp="13,150,23.389.0,19.363.0,33.139.0,43.178.0,42.141.0,42.175.0"}
P.entries["item:steelgrill-s-tools"] = {n="Steelgrill's Tools",s="Steelgrill's Tools är en särskild uppsättning mekanikerverktyg som beställts åt Beldin Steelgrill, chefsteknikern på Steelgrill's Depot. Beldin är känd för att pressa belägringsmaskiner och sin egen utrustning till bristningsgränsen. Han har ofta sönder verktyg och förlitar sig på leveranser från närliggande Kharanos för att hålla verkstaden igång.",h="Steelgrill's Tools är en särskild uppsättning mekanikerverktyg som beställts åt Beldin Steelgrill...",kw={"beldin","förråd","kharanos","ratchet","belägringsmaskin","skiftnyckel","steelgrill","verktyg"},ang={["profession:Engineering"]="Alla ingenjörer kan förstå Beldins dilemma, eftersom reparationer med högt vridmoment på tunga belägringsmaskiner regelbundet sliter ut arclight-nycklar och ömtåliga skiftnycklar.",["race:Dwarf"]="Att underhålla Alliansens bepansrade belägringsmaskiner är en fråga om dvärgisk stolthet, och om Beldin har de verktyg han behöver förblir Ironforges bepansrade förtrupp redo för strid."},sec={{t="En hårdhänt hantverkare",b="Beldin Steelgrill anses allmänt vara en av de främsta teknikerna för belägringsmaskiner i Dun Morogh, men hans hårdhänta reparationsmetoder är ökända bland lokala köpmän. Beldin arbetar outtröttligt med bepansrade stridsvagnar och mekaniska konstruktioner, men har sönder ömtålig utrustning nästan lika snabbt som den kan smidas. Han knäcker arclight-nycklar och sliter ut fang-spärrskaft, så mekanikern beställer ständigt nya verktyg från Kharanos för att hålla reparationsbänkarna utrustade."},{t="Hålla maskinerna igång",b="Den här verktygsleveransen är avgörande för att Ironforges krigsmaskiner ska fungera. På sitt förråd nordost om Kharanos servar Beldin stridsfordon åt erfarna förare som Pilot Stonegear. Utan nytillförda skiftnycklar och spärrskaft skulle viktiga belägringsmaskiner stå halvmonterade i snön och både förrådet och det lokala försvaret bli stillastående."}},faq={{q="Vad används Steelgrill's Tools till?",a="De är ersättningsverktyg för mekaniker som levereras till Beldin Steelgrill på Steelgrill's Depot. Beldin behöver dem för att rusta upp tung dvärgisk maskinutrustning, särskilt den skadade belägringsmaskinen som tillhör Pilot Stonegear.",al={"vad är det här för verktyg","steelgrill tools användning"}},{q="Varför gör Beldin Steelgrill av med så många verktyg?",a="Beldin är en ovanligt hårdhänt mekaniker som pressar sin utrustning till bristningsgränsen. Enligt leverantörer i Kharanos knäcker han arclight-nycklar och har sönder fang-spärrskaft nästan snabbare än lokala hantverkare hinner tillverka nya.",al={"varför trasiga verktyg","varför behöver beldin verktyg"}},{q="Varifrån kommer den här verktygslådan?",a="Leveransen sätts ihop och skickas från den närliggande bosättningen Kharanos innan den lämnas över till resande som beger sig nordost mot Steelgrill's Depot.",al={"var får jag tag på verktyg","verktygsleveransens ursprung"}},{q="Vem är Beldin Steelgrill?",a="Beldin är en mästermekaniker av dvärgfolk som äger och driver Steelgrill's Depot, nordost om Kharanos. Han anses vara regionens främsta tekniker för belägringsmaskiner.",al={"vem är beldin","beldin steelgrill bakgrund"}}},fx={["8eb066d8"]={q="Vad är Steelgrill's Tools?",a="Steelgrill's Tools är en nyförpackad beställning med tung mekanisk utrustning, bland annat arclight-nycklar och fang-spärrar. Den är förberedd för direkt leverans till Beldin Steelgrill, den främste teknikern för belägringsmaskiner som arbetar från Steelgrill's Depot nära Kharanos.",al={"vad är steelgrill's tools","steelgrill's tools verktygslåda"}},["11454cb4"]={q="Varför behöver Beldin Steelgrill den här verktygslådan?",a="Beldin är en expertmekaniker, men han kör sin utrustning till bristningsgränsen när han servar tunga maskiner. Han har just knäckt sin sista fang-spärr och behöver omgående den här nya leveransen för att utföra kritiska reparationer på belägringsmaskiner, som Pilot Stonegears.",al={"varför vill beldin ha verktyg","varför behövs steelgrill's tools","varför behövs verktygen"}}},fp="18,182,24.349.0,27.287.0,37.180.0,52.151.0,40.99.0,25.147.0"}
P.entries["item:steelsnap-s-rib"] = {n="Steelsnap's Rib",s="Steelsnap's Rib är en dyster trofé från kadavret efter den våldsamma hyenan Steelsnap i Thousand Needles. När den förs tillbaka till Thunder Bluff blir den ett fysiskt bevis på att en varelse som anses stå utanför Jordmoderns välsignelse har fällts.",h="Steelsnap's Rib är en dyster trofé från kadavret efter den våldsamma hyenan Steelsnap i Thousand Needles.",kw={"camp e'thok","hunter rise","hyena","melor stonehoof","steelsnap","steelsnap's rib","thousand needles","thunder bluff"},ang={["class:Hunter"]="Att ta revbenet från en flockledare på toppen av näringskedjan prövar jägarens förmåga att spåra farligt villebråd och undanröja hot som rubbar vildmarkens balans.",["race:Tauren"]="För tauren innebär det att föra tillbaka den här trofén att fullgöra en plikt mot Jordmodern genom att fördriva en varelse vars tygellösa grymhet fläckar den heliga balansen."},sec={{t="En jakt utanför välsignelsen",b="De flesta tauren-jakter bedrivs för föda, för ärans skull eller för att söka harmoni med naturen. Steelsnap är däremot ett annat slags villebråd. Den här våldsamma alfahyenan strövar omkring på kanjonens botten i Thousand Needles, söder om Camp E'thok, där den terroriserar fredliga djur och hetsar flockar av mindre rovdjur till meningslös blodsutgjutelse. När jaktmästaren Melor Stonehoof på Hunter Rise utser Steelsnap till ett mål som ska dödas, kräver han ett kraftigt ben – Steelsnap's Rib – som obestridligt bevis på att tyrannen har dräpts och att kanjonen befriats från sin plåga."}},faq={{q="Vad används Steelsnap's Rib till?",a="Revbenet förs till Melor Stonehoof på Hunter Rise i Thunder Bluff för att slutföra jakten på Steelsnap. Det är ett påtagligt bevis på att den våldsamma hyenan har besegrats.",al={"steelsnap's rib-uppdrag","vem vill ha steelsnap's rib","vad gör jag med steelsnap's rib"}},{q="Var hittar jag Steelsnap för att få tag på revbenet?",a="Steelsnap strövar omkring i den nordvästra delen av Thousand Needles, på kanjonens botten söder om Camp E'thok, vanligtvis med trogna flockmedlemmar vid sin sida.",al={"steelsnap-plats","var finns steelsnap","hitta steelsnap"}},{q="Varför vill Melor Stonehoof att Steelsnap dödas?",a="Melor anser att Steelsnap är en onaturlig tyrann som står utanför Jordmoderns välsignelse. Till skillnad från vanliga rovdjur, som jagar för att överleva, sprider Steelsnap omotiverat våld och skräck bland fredliga djur, så han måste förgöras.",al={"varför döda steelsnap","melor stonehoofs motiv","steelsnap-bakgrund"}},{q="Vem är Melor Stonehoof?",a="Melor Stonehoof är en erfaren tauren-jägare på Hunter Rise i Thunder Bluff. Han ger blivande spårare i uppdrag att hitta farliga bestar runtom i Kalimdor.",al={"vem är melor","melor stonehoofs plats","melor på hunter rise"}}},fx={["27efcb35"]={q="Vad är Steelsnap's Rib?",a="Det är ett tungt ben från kadavret efter Steelsnap, en ökänd och vild hyena som terroriserar ravinerna i Thousand Needles. I stället för att vara användbart hantverksmaterial eller kött tjänar det som ett obestridligt fysiskt bevis på att det våldsamma odjuret har fällts.",al={"vad är steelsnap's rib","steelsnaps ben"}},["57ae26da"]={q="Var kommer Steelsnap's Rib ifrån?",a="Revbenet kommer direkt från kvarlevorna efter Steelsnap, en ovanligt våldsam hyena som strövar på de torra slätterna i Thousand Needles söder om The Barrens. För att få tag på det måste en jägare spåra upp odjuret och besegra både Steelsnap och hans flock.",al={"var får man tag på steelsnap's rib","steelsnap's ribs ursprung","vilken fiende släpper steelsnap's rib"}},["4a69fb67"]={q="Varför vill Melor Stonehoof ha Steelsnap's Rib?",a="Melor Stonehoof ber om revbenet som fysiskt bevis på Steelsnaps död. Till skillnad från jakter som bedrivs för mat eller ära skickar Melor jägare för att utrota Steelsnap, eftersom odjuret står utanför Jordmoderns välsignelse och sprider blodspillan och rädsla bland fredligare varelser. När benet återlämnas bekräftar det att ravinen har renats från denna smitta.",al={"varför lämna steelsnap's rib till melor","varför behöver melor revbenet","varför samla in steelsnap's rib"}}},fp="15,188,27.407.0,33.104.0,42.121.0,47.182.0,23.142.0"}
P.entries["item:stolen-silver"] = {n="Stolen Silver",s="Vid The Crossroads har en kista med silver från Horden försvunnit från vakttornet. Sunscale-raptorer bar mynten till sina bon vid Raptor Grounds söder om Ratchet.",h="Vid The Crossroads har en kista med silver från Horden försvunnit från vakttornet.",kw={"löneutbetalning i the barrens","the crossroads","gazrog","raptor grounds","silverfyllt kassaskrin","stolen silver","sunscale-raptor"},ang={["faction:Horde"]="The Crossroads är hjärtat i Hordens närvaro i The Barrens. Att återta lönen håller de lokala fotsoldaterna mätta, avlönade och redo att hålla stånd mot kentaurernas och Alliansens intrång."},sec={{t="Ett bestialiskt rån",b="Sunscale-raptorer bar en kista med silver från vakttornet vid The Crossroads. Mynten var avsedda som lön åt garnisonens vakter. Raptorerna släpade lådan till sina gemensamma bon vid Raptor Grounds, söder om Ratchet. Gazrog och de andra tillsyningsmännen kan inte förklara varför rovdjuren tog den. Stölden får dem att undra om raptorerna värdesätter glänsande saker eller besitter en list utöver vanliga vilda djurs."}},faq={{q="Vad är Stolen Silver?",a="Stolen Silver är en tung låda med mynt som ska betala vakterna vid The Crossroads. Raptorer stal den från vakttornet och bar den till sina boplatser.",al={"vad är stolen silver","vad är silvret"}},{q="Varför stal raptorerna ett kassaskrin med mynt?",a="Inte ens Gazrog kan förklara varför raptorerna tog lådan. De kan ha lockats av dess glänsande metall, eller så ledde deras ovanliga list dem till att bära den djupt in i sitt näste.",al={"varför vill raptorer ha silver","raptorernas intelligens","varför silver"}},{q="Vart fördes silvret?",a="Raptorerna tog lådan till Raptor Grounds, en karg kanjon med bon söder om Ratchet i östra The Barrens.",al={"stolen silver plats","var finns silvret"}},{q="Vem letar efter Stolen Silver?",a="Gazrog, en orch stationerad vid The Crossroads, letar efter kistan. Silvret motsvarar en hel månadslön för utpostens hårt ansatta försvarare.",al={"vem vill ha silvret","vem lämnar in stolen silver"}}},fp="13,175,15.431.0,26.160.0,41.182.0,27.117.0,37.144.0"}
P.entries["item:stone-of-relu"] = {n="Stone of Relu",s="Stone of Relu är en forntida arkeologisk relik som återfunnits i Wetlands. Archaeologist Flagongut tror att den är nyckeln till att väcka slumrande krafter i urtidsfossil. Den försvann en kort tid när lokala rovfåglar överföll forskaren på vägen.",h="Stone of Relu är en forntida arkeologisk relik som återfunnits i Wetlands.",kw={"archaeologist flagongut","explorers' league","fossil","fläckig rovfågel","prospector whelgar","stone of relu","wetlands"},ang={["faction:Alliance"]="Alliansens expeditioner i Menethil Harbor förlitar sig på återfunna artefakter som Stone of Relu för att rättfärdiga de mödosamma utgrävningarna i de förrädiska träskmarkerna.",["race:Dwarf"]="För Explorers' League är Stone of Relu ett viktigt verktyg för att pussla ihop det forntida livets ursprung och världens bortglömda arv."},sec={{t="En nyckel till forntida reliker",b="Stone of Relu upptäcktes under Explorers' League-uppdrag och tros ha kraften att tyda förhistoriska fossil från Kalimdor och Eastern Kingdoms. Archaeologist Flagongut identifierade föremålet som katalysatorn som krävs för att frigöra hemligheterna i både hans egna fynd från Wetlands och fossilet som Prospector Remtravel grävde fram i Darkshore."},{t="Förlorad i träskmarkerna",b="När Flagongut färdades längs vägarna i Wetlands för att möta Prospector Whelgar överföll en flock fläckiga rovfåglar honom. I tumultet försvann reliken och svaldes av ett av de glupska djuren, vilket tvingade ligan att ta hjälp av äventyrare för att jaga träskens rovfåglar och skära ut den forntida stenen ur deras svalg."}},faq={{q="Vad är Stone of Relu?",a="Stone of Relu är ett forntida föremål som Archaeologist Flagongut söker efter. Han tror att den fungerar som en kodnyckel eller katalysator som kan låsa upp de dolda mysterierna och krafterna som slumrar i förhistoriska fossil.",al={"stone of relu","vad är den här stenen","relu-artefakt"}},{q="Hur hamnade stenen inuti en rovfågel?",a="Archaeologist Flagongut bar reliken längs vägen genom Wetlands för att möta Prospector Whelgar när fläckiga rovfåglar anföll hans sällskap. I kaoset försvann stenen och svaldes av ett av asätarna.",al={"varför har rovfåglar den","vem tappade stenen","hur gick den förlorad"}},{q="Vad tänker Flagongut göra med stenen?",a="Flagongut tänker använda stenen tillsammans med sitt återfunna fossil och fossilet som Prospector Remtravel hittade i Darkshore för att tyda och frigöra deras slumrande magiska hemligheter.",al={"vad vill flagongut","stone of relu syfte"}}},fp="13,150,23.277.0,19.287.0,26.160.0,41.179.0,48.168.0"}
P.entries["item:stonetalon-sap"] = {n="Stonetalon Sap",s="Stonetalon Sap är ett klibbigt och kraftfullt ämne som utvinns direkt ur de trögfotade savbestarna som strövar omkring på Stonetalon Mountains klippiga höjder. Det är ett viktigt reagens för Darkspear Witch Doctor Jin'Zil, som använder dess råa skogsegenskaper för att koka ihop en illvillig brygd.",h="Stonetalon Sap är ett klibbigt och kraftfullt ämne som utvinns direkt ur de trögfotade savbestarna som...",kw={"jin'zil","malaka'jin","mirkfallon lake","savbest","stonetalon peak","stonetalon sap"},ang={["race:NightElf"]="Att en häxdoktor från Horde vanhelgar Stonetalon-trakternas inhemska krafter för att förgifta tillfångatagna alver är en skymf mot naturen och Elune.",["race:Troll"]="Witch Doctor Jin'Zil visar hur Darkspear-folket kan förvandla fiendens älskade omgivning till ett dödligt voodoo-redskap."},sec={{t="En bitter skörd",b="Den här trögflytande vätskan droppar från savbestarna nära Mirkfallon Lake och Stonetalon Peak och bär på den koncentrerade essensen från bergens uråldriga flora. I sitt naturliga, vilande tillstånd är den harmlös, men en erfaren alkemist eller häxdoktor kan lätt förvandla saven till något långt mörkare. Jin'Zil från Malaka'jin vill ha den för att brygga det han hånfullt kallar ”skogsmagi” – en dödlig dryck som ska plåga hans tillfångatagna Night Elf-fångar med själva essensen av deras älskade vildmark."}},faq={{q="Vilka varelser bär på Stonetalon Sap?",a="Den samlas in från savbestar, de märkliga skogsvarelser som finns nära Mirkfallon Lake och högre upp längs sluttningarna mot Stonetalon Peak.",al={"var får man tag på stonetalon sap","vem släpper stonetalon sap","savbestar"}},{q="Vad använder Witch Doctor Jin'Zil saven till?",a="Jin'Zil blandar saven med courserögon, skymningsmorrhår och en Fey Dragon Scale för att skapa en giftig brygd som han använder mot sina tillfångatagna Night Elf-fångar.",al={"varför vill jin'zil ha sav","jin'zils recept på skogsmagi"}},{q="Var hittar man lättast savbestar?",a="Savbestar lever i dungarna runt Mirkfallon Lake och längs de frodiga stigarna upp mot Stonetalon Peak.",al={"savbestarnas plats","savbestar vid mirkfallon lake"}},{q="Är saven magisk i sig?",a="Den är naturligt genomsyrad av den uråldriga livskraften från Stonetalon-bergen, men det krävs trollmagi och särskilda reagenser för att förvandla den till ett dödligt gift.",al={"är stonetalon sap magisk","stonetalon saps egenskaper"}}},fx={b24da591={q="Vad är Stonetalon Sap?",a="Stonetalon Sap är ett klibbigt, naturligt harts som samlas från savbestarna som strövar i Stonetalon Mountains, särskilt kring platser som Mirkfallon Lake och Stonetalon Peak. Det är tjockt, trögflytande och fullt av rå naturkraft, vilket gör det till en idealisk ingrediens i brygder och voodoo-elixir som använder den säregna magin i den lokala vildmarken.",al={"vad är stonetalon sap","föremålet stonetalon sap","om stonetalon sap"}},["7615d27b"]={q="Var kommer Stonetalon Sap ifrån?",a="Den här bärnstensfärgade saven utvinns direkt från de levande savbestarna som vandrar genom skogarna och längs sjöstränderna i Stonetalon Mountains. Den tillverkas eller destilleras inte av någon dödlig hantverkare, utan utsöndras naturligt av dessa besynnerliga, uråldriga växtvarelser.",al={"stonetalon saps källa","var hittar man sav","stonetalon saps ursprung"}}},fp="14,161,16.265.1,36.94.0,47.141.1,43.96.0,30.127.0"}
P.entries["item:stormpike-banner"] = {n="Stormpike Banner",s="Stormpike Banner är ett baner som gömts djupt inne i den förrädiska Icewing Cavern i Alterac Valley. Alliansens rekryter måste trotsa vilda harpyor för att hämta det som ett inträdesprov och visa att de förtjänar att bära Stormpikes insignier.",h="Stormpike Banner är ett baner som gömts djupt inne i den förrädiska Icewing Cavern i Alterac Valley.",kw={"alterac valley","dun baldar","haggerdin","icewing caverns","insignier","inträdesprov","stormpike banner"},ang={["faction:Alliance"]="När du hämtar baneret blir du formellt medlem i Stormpike Guard och får rätt att bära deras stridsinsignier mot Frostwolf Clan.",["race:Dwarf"]="Baneret står för Ironforges suveräna anspråk och Stormpike-klanens heliga uppdrag att hitta reliker från sitt förflutna i hela dalen."},sec={{t="Ett inträdesprov",b="För att officiellt ansluta sig till Stormpike-expeditionen i Alterac Valley måste blivande rekryter visa vad de går för innan de ens drabbar samman med Frostwolf-orcherna. Lieutenant Haggerdin skickar nyanlända soldater från Alliansen till Icewing Caverns, sydväst om Dun Baldar. Stormpike Banner står djupt inne i den frusna underjordiska hålan och fungerar som ett prov: den som vågar möta de harpyor som bor där, ta baneret och återvända med livet i behåll får rang och insignier som rekryt i Stormpike Guard."}},faq={{q="Var finns Stormpike Banner?",a="Baneret står djupt inne i Icewing Caverns, ett isande grottsystem sydväst om Dun Baldar i Alterac Valley.",al={"banerets plats","var finns stormpike banner","hur hittar man baneret"}},{q="Varför måste rekryterna hämta baneret?",a="Lieutenant Haggerdin kräver att alla rekryter från Alliansen visar sitt mod innan de ansluter sig till stridslinjerna. Den som hämtar tillbaka baneret från den farliga grottan, full av harpyor, får sin första Stormpike Insignia.",al={"inträdesprov","varför hämta baneret","haggerdins uppdrag"}},{q="Vilka faror vaktar baneret inne i grottan?",a="Icewing Caverns försvaras hårt av vilda lokala harpyor som går till våldsamt angrepp mot alla inkräktare som söker efter baneret.",al={"monster nära baneret","fiender i icewing cavern"}},{q="Vem ska jag lämna tillbaka baneret till när jag hittat det?",a="Lämna det återhämtade baneret till Lieutenant Haggerdin, Alliansens officer som är stationerad utanför ingången i Alterac Mountains.",al={"lämna in baneret","inlämning av baneret"}}},fx={["27f01085"]={q="Vad är Stormpike Banner?",a="Stormpike Banner är en militär fana som representerar Stormpike Guard, dvärgexpeditionen som för närvarande utkämpar ett krig i Alterac Valley. Fanan har rests djupt inne i de farliga, harpystinna Icewing Caverns sydväst om Dun Baldar och fungerar som ett prövningsmärke. Rekryter måste ta sig in i det frusna djupet, trotsa de vilda bestarna därinne och återta fanan för att bevisa sin duglighet och att de förtjänar att bära Stormpike-insignian.",al={"vad är stormpike banner","stormpike banners bakgrund","om stormpike banner"}}},fp="16,160,19.299.0,38.96.0,44.169.0,46.84.0,41.125.0"}
P.entries["item:stormpike-s-request"] = {n="Stormpike's Request",s="Mountaineer Stormpike skickar en skriftlig beställning från Loch Modan till Stormwind City. Han ber Furen Longbeard att smida en sköld av exceptionell dvärgkvalitet åt honom.",h="Mountaineer Stormpike skickar en skriftlig beställning från Loch Modan till Stormwind City.",kw={"smed","dun morogh","dwarven district","furen longbeard","beställning","sköld","stormpike","stormwind"},ang={["profession:Blacksmithing"]="Stormpikes beställning visar vilken ställning mästarrustningssmeder har: uppdragsgivare i andra riken söker skickliga dvärgsmeder.",["race:Dwarf"]="Som dvärg för du samman klan och hantverk mellan bergsvakterna som försvarar Khaz Modan och hantverkarna som bor utomlands i människornas städer."},sec={{t="En beställning från norr",b="Mountaineer Stormpike behöver en stadig sköld medan han är stationerad i Loch Modan. Han litar inte på arbetet åt någon vanlig smed och ber Furen Longbeard, vars hantverk han beundrar djupt. Furen bor numera bland människorna i Stormwinds Dwarven District efter att ha lämnat Ironforge. Stormpike antar att en kunglig lösensumma lockade honom söderut, så resande äventyrare för beställningen mellan rikena."},{t="Stormpike-klanens anseende",b="Furen Longbeard tar emot Stormpikes brev i Stormwinds Dwarven District och går med på att tillverka skölden. Som en stolt och etablerad medlem av Stormpike-klanen, känd i hela Khaz Modan för sin stridsduglighet och rikedom, välkomnar Furen nyheter och affärer från sitt nordliga hemland. Han sätter igång med bergsvaktens beställning."}},faq={{q="Vad är Stormpike's Request?",a="I sitt brev från Loch Modan ber Mountaineer Stormpike Furen Longbeard att smida en sköld av hög kvalitet åt honom.",al={"vad är det här för brev","stormpikes beställningsföremål","stormpikes beställning"}},{q="Vem skrev brevet?",a="Mountaineer Stormpike skrev brevet. Han är en dvärgisk väktare som bevakar bergspassen i Loch Modan och beundrar Furen Longbeards smide djupt.",al={"vem skickade stormpikes beställning","vem skrev det","mountaineer stormpike"}},{q="Vart ska brevet?",a="Brevet är adresserat till Furen Longbeard vid hans smedja i Stormwind Citys Dwarven District.",al={"var lämnar jag stormpikes beställning","vem ska få brevet","lämna stormpikes beställning"}},{q="Varför anlitar Stormpike en smed ända borta i Stormwind?",a="Stormpike anser att ingen kan mäta sig med Furens skicklighet och godtar ingen annan rustningssmed. Furen lämnade Ironforge för att arbeta bland människorna i söder.",al={"varför furen","varför inte smida i ironforge","varför skicka till stormwind"}}},fx={["181a24c8"]={q="Varför vill Furen Longbeard ha Stormpike's Request?",a="Den här skriftliga beställningen gäller en fint tillverkad dvärgsköld. Furen Longbeard, en rustningssmed i Stormwinds Dwarven District, uppskattar affärer från den berömda Stormpike-klanen. Han vet att familjen inte bara är stolt och högt ansedd i hela Khaz Modan, utan också rik nog att betala ordentligt för enastående hantverk.",al={"varför vill furen ha den här","varför vill man ha stormpike's request","varför behövs stormpike's request"}}},fp="19,161,21.380.0,18.322.0,28.103.0,22.143.0,34.93.0,57.137.0"}
P.entries["item:stormwind-armor-marker"] = {n="Stormwind Armor Marker",s="Stormwind Armor Marker låter dem som hjälper riket hämta utrustning från godkända hantverkare. Sara Timberlain tar emot den vid Eastvale Logging Camp.",h="Stormwind Armor Marker låter dem som hjälper riket hämta utrustning från godkända hantverkare.",kw={"rustningsmarkör","rustning av tyg och läder","eastvale logging camp","elwynn forest","rekvisition","sara timberlain","stormwind armor marker"},ang={["faction:Alliance"]="Som medlem i Alliansen kan du se hur Eastvale Logging Camp knyter gränsbosättningar till Stormwinds militära befäl."},sec={{t="Militära rekvisitioner",b="Stormwinds befälhavare utfärdar rustningsmarkörer till dem som tjänar riket. Att upprätthålla lag och ordning i hela Elwynn Forest tänjer på Stormwinds resurser, så befälhavarna använder ibland dessa officiella rekvisitionssedlar i stället för att dela ut standardutrustning vid militärposteringar. En markör bekräftar bärarens tjänst och ger lokala hantverkare med kontrakt tillstånd att tillverka anpassad rustning."},{t="Förnödenheter vid Eastvale",b="Vid Eastvale Logging Camp arbetar Sara Timberlain och andra hantverkare på uppdrag av Stormwind-armén. Lägrets ligger vid Elwynns östra gräns, där de använder lokala material för att tillverka skyddande plagg av tyg och läder. Visa upp en markör där för att få skräddarsytt skydd för att vakta de omgivande skogarna."}},faq={{q="Vad används Stormwind Armor Marker till?",a="Stormwind Armor Marker är en officiell militär värdehandling för dem som hjälper Stormwinds vakter. Den bevisar att du har tjänat och låter dig hämta skyddande rustning från en hantverkare med kontrakt hos armén.",al={"vad är en rustningsmarkör","markörens syfte","använda stormwind-markör"}},{q="Vem tar emot markören?",a="Sara Timberlain tar emot markören vid Eastvale Logging Camp, strax österut på andra sidan floden i Elwynn Forest. Hon har kontrakt med Stormwind-armén om att tillhandahålla skräddarsydd utrustning av tyg och läder.",al={"vem tar emot markören","var lämnar man in markören","sara timberlain markör"}},{q="Varför använder Stormwind markörer i stället för att dela ut rustning direkt?",a="Stormwind använder markörer eftersom avlägsna vaktposter kan sakna förvaringsutrymme och utrustning för smide eller sömnad, så att rekryter kan utrustas på plats. Befälhavare i fält kan skicka rekryter till lokala hantverkare som Sara Timberlain, som har egna verkstäder.",al={"varför polletter i stället för rustning","varför armémarkörer","militära värdehandlingar elwynn"}},{q="Vilken sorts utrustning ger markören?",a="Markören låter bäraren välja en nytillverkad rustningsdel av tyg eller läder, skräddarsydd av en arméleverantör med kontrakt.",al={"vilken rustning får jag","markörbelöningar","tyg eller läder"}}},fx={e5398b12={q="Vad är Stormwind Armor Marker?",a="Det är en officiell militär rekvisition utfärdad på Stormwind-arméns vägnar. I stället för att släpa skrymmande skyddsutrustning genom Elwynn Forest utfärdar lokala befälhavare denna symbol som en garanti för rekvisition. Den ger bäraren rätt att hämta nygjord tyg- eller läderrustning hos en auktoriserad rustningssmed.",al={"vad är stormwind armor marker","rustningsmärket","vad är märket"}},["3e7f2980"]={q="Varifrån kommer Stormwind Armor Marker, och vem tillverkade den?",a="Märket utfärdas på Stormwind-arméns vägnar av Guard Thomas vid hans post nära den östra bron i Elwynn. Det tilldelas försvarare som visar prov på klokhet och mod. Det bär kungarikets armés auktoritet och ger lokala hantverkare i uppdrag att förse rekryter med utrustning på kronans bekostnad.",al={"vem tillverkade rustningsmärket","varifrån kommer märket","vem utfärdar rustningsmärket"}},["618263b5"]={q="Varför vill Sara Timberlain ha Stormwind Armor Marker?",a="Stormwind-armén har gett Sara Timberlain i uppdrag att utrusta sina rekryter och frivilliga med tyg- och läderrustning. Hon behöver märket som officiellt bevis på sitt tillstånd innan hon lämnar ut sin handgjorda utrustning, så att kungarikets förråd bara går till erkända försvarare.",al={"varför vill sara ha märket","varför ta märket till eastvale","varför behövs rustningsmärket"}}},fp="22,177,21.341.0,21.324.0,50.195.0,23.195.0,69.244.0,47.128.0"}
P.entries["item:stoutmantle-s-response-to-solomon"] = {n="Stoutmantle's Response to Solomon",s="Gryan Stoutmantle skickar ett hårt svar från Sentinel Hill till Lakeshire. Hans meddelande berättar för Magistrate Solomon att People's Militia inte kan avvara en enda soldat till Redridge Mountains.",h="Gryan Stoutmantle skickar ett hårt svar från Sentinel Hill till Lakeshire.",kw={"gryan","lakeshire","brev","magistrate solomon","budbärare till westfall","people's militia","redridge","solomon","stoutmantle","westfall"},ang={["faction:Alliance"]="För Alliansen visar brevet hur avlägsna bosättningar vädjar till varandra om hjälp medan huvudstaden håller sina styrkor tillbaka.",["race:Human"]="Som mänsklig försvarare ser du hur Westfall och Redridge delar en desperat kamp för att överleva utan Stormwinds kungliga vakter."},sec={{t="En vädjan avslås",b="Magistrate Solomon i Lakeshire ber Sentinel Hill om förstärkningar när Blackrock-orcher och gnoller tränger sig på staden. Gryan Stoutmantle svarar skriftligen och beklagar Lakeshires förluster, men Westfall står inför ett eget krig. People's Militia bildades ur desperation efter att kronan drog tillbaka sin garnison. Bönder och frivilliga strider nu ensamma mot Defias Brotherhood. Stoutmantles styrkor blöder redan och är hårt pressade, utan några män att avvara till ännu en övergiven gränsbygd."},{t="Kungarikets försummelse",b="Redridge och Westfall delar ett dystert öde: båda har övergivits av hovet i Stormwind City. Kung Varian Wrynn är försvunnen, och rikets stående armé hålls av okänd anledning borta från provinsernas gränser. Avlägsna städer måste bilda frivilliga vakter eller gå under. Solomon tar emot det förseglade svaret och inser att ingen av städerna kan rädda den andra. Riket faller sönder medan huvudstaden tiger."}},faq={{q="Vad står det i Stoutmantles svar?",a="Gryan Stoutmantle skriver att Westfall utkämpar ett brutalt krig mot Defias Brotherhood och, precis som Redridge, har förlorat Stormwinds armé. Han sörjer de stupade försvararna men avslår Magistrate Solomons begäran om förstärkningar.",al={"vad står det i brevet","innehållet i stoutmantles brev","texten i svaret till solomon"}},{q="Varför bad Solomon Westfall om hjälp från början?",a="Lakeshire utsätts för hårda angrepp från gnoller och Blackrock-orcher, och Magistrate Solomons vädjan till General Marcus Jonathan i Stormwind har inte lett till några trupper. Utan officiell hjälp ber Solomon People's Militia i Elwynn om stöd från andra gränsförsvarare.",al={"varför be westfall om hjälp","solomon ber stoutmantle","varför bad lakeshire milisen om hjälp"}},{q="Varför kan People's Militia inte avvara några trupper?",a="People's Militia är en frivillig armé som kämpar för att hålla Sentinel Hill och de omgivande slätterna mot Defias Brotherhood. Förlusterna ökar dagligen, och utan stöd från den reguljära armén skulle trupper till Lakeshire lämna Westfall försvarslöst.",al={"varför hjälper inte milisen","kan westfall hjälpa redridge","varför avslå solomon"}},{q="Varför skyddar inte Stormwind-armén de här städerna?",a="Ingen i de båda städerna vet varför Stormwind-armén är frånvarande. Stoutmantle skriver att Stormwind drog tillbaka sina trupper och lämnade Westfall försvarslöst, medan Solomon undrar vad som kan kalla bort armén från dess folk. Båda regionerna måste förlita sig på lokala frivilliga.",al={"var är stormwind-armén","varför hjälper inte stormwind","stormwinds övergivande"}}},fx={["399f6159"]={q="Vad är Stoutmantle's Response to Solomon?",a="Det är ett officiellt skriftligt meddelande från Gryan Stoutmantle, befälhavare för Folkets milis i Sentinel Hill, adresserat till Magistrate Solomon i Redridge. Brevet kommer med det dystra beskedet att Westfall är indraget i sitt eget desperata krig mot Defias Brotherhood och inte kan skicka soldater eller förnödenheter för att hjälpa Lakeshire.",al={"vad är stoutmantle's response","stoutmantles brev till solomon","gryan svarar lakeshire"}},["945d8c3a"]={q="Varifrån kommer Stoutmantle's Response to Solomon, och vem skrev det?",a="Det skrevs av Gryan Stoutmantle själv i Sentinel Hill i Westfall. Efter att ha läst Magistrate Solomons vädjan om förstärkningar skrev Stoutmantle sitt svar och anförtrodde det åt dig, så att du kan föra det genom kungariket tillbaka till Redridge Mountains.",al={"vem skrev stoutmantle's response","vem skrev stoutmantle's response to solomon","varifrån kommer stoutmantles response"}},c46920a1={q="Varför vill någon ha Stoutmantle's Response to Solomon?",a="Magistrate Solomon väntar på svaret i Lakeshire och hoppas på militär hjälp för att hålla den svartstensorkiska invasionen som hotar Redridge stången. Han behöver Stoutmantles besked för att veta om Folkets milis kan rida till Lakeshires försvar eller om staden måste möta farorna ensam.",al={"vem vill ha stoutmantle's response","varför leverera stoutmantles brev","varför ta svaret till solomon"}}},fp="33,116,13.458.0,21.393.1,42.230.0,57.236.0,48.253.0,52.254.0"}
P.entries["item:strange-smelling-powder"] = {n="Strange Smelling Powder",s="Strange Smelling Powder är en gåtfull rest som hittats under utredningen av misstänkt sabotage kring Loch Modan. Den befaras vara ett instabilt sprängämne, och därför skickar Chief Engineer Hinderweir en brådskande kurir norrut för att söka upp en sprängämnesexpert.",h="Strange Smelling Powder är en gåtfull rest som hittats under utredningen av misstänkt sabotage kring Loch...",kw={"ett mörkt hot tornar upp sig","ashlan stonesmirk","dun modr","hinderweir","loch modan","strange smelling powder","thandol span"},ang={["profession:Engineering"]="Ingenjörer känner igen lukten av svavelhaltiga, instabila sprängblandningar som inte liknar standardformlerna vid Alliansens gruvutposter.",["race:Dwarf"]="För dvärgarna är det av största vikt att skydda Loch Modans stenverk och vattenmagasin. Därför blir varje tecken på fiendesprängämnen genast en kris för klanen."},sec={{t="Ett flyktigt fynd",b="Detta märkliga pulver upptäcktes bland tecken på sabotage mot Loch Modans infrastruktur och väckte genast oro hos Chief Engineer Hinderweir. Den starka lukten och fina konsistensen tyder på en tillverkad sprängblandning snarare än vanligt sprängpulver för gruvdrift. Eftersom Hinderweir inte känner till blandningens kemiska natur eller ursprung vägrar han att själv röra den. Han vet att minsta gnista kan utlösa en katastrof."},{t="Vägen norrut",b="Dvärgiska ingenjörer tar inga risker med instabila reagenser, så Hinderweir skickar pulverprover genom Algaz Gate till Wetlands. Där, vid Dun Modr nära Thandol Span, får den erfarna sprängämnesexperten Ashlan Stonesmirk i uppdrag att undersöka kornen och avgöra vilken sorts katastrofal explosion sabotörerna förbereder."}},faq={{q="Vad är Strange Smelling Powder?",a="Det är en misstänkt kemisk rest som återfanns i Loch Modan under utredningen av lokalt sabotage. Den starka stanken och sammansättningen får dvärgiska ingenjörer att misstänka att det är ett sprängämne.",al={"vad är strange smelling powder","vad är det här pulvret","pulver i loch modan"}},{q="Varför vill Chief Engineer Hinderweir att pulvret undersöks?",a="Hinderweir misstänker att pulvret är ett specialiserat sprängämne. För att förstå omfattningen av och hotet från planen mot Loch Modan behöver han en professionell analys från någon med djup kunskap om sprängningar.",al={"varför undersöka pulvret","hinderweirs pulver","vem behöver pulvret"}},{q="Vem kan identifiera pulvret?",a="Chief Engineer Hinderweir ber resande att ta provet till Ashlan Stonesmirk, en sprängämnesexpert som är stationerad långt norrut med regementet vid Dun Modr, nära Thandol Span.",al={"vem identifierar pulvret","vart ska jag ta pulvret","pulverexpert"}},{q="Varför är det farligt att transportera pulvret?",a="Utöver den inneboende flyktigheten hos ett okänt sprängämne måste den som bär provet trotsa den farliga färden genom Algaz Gate och vidare längs Wetlands sumpiga, fientliga vägar.",al={"är pulvret farligt","varför farligt"}}},fp="23,168,20.322.0,14.284.1,32.196.0,52.153.0,28.158.0,41.130.0"}
P.entries["item:strangely-marked-box"] = {n="Strangely Marked Box",s="En Strangely Marked Box är en lastlåda som hittats i selar fastspända på döda havssköldpaddor längs Darkshores kust. Dess gåtfulla utsida bär nagas slingrande runskrift och ger Night Elf-lärda bevis för att dessa havsdjur inte strandade av en slump.",h="En Strangely Marked Box är en lastlåda som hittats i selar fastspända på döda havssköldpaddor längs...",kw={"auberdine","vagn","darkshore","greymist","gwennyth bly'leggonde","naga","havssköldpadda","strangely marked box"},ang={["class:Priest"]="Genom att säkra reliker från stranden hjälper du Temple of the Moons lärda i Auberdine att skydda kusten från havets korrumperande inflytande.",["race:NightElf"]="När naga-förrådslådor hittas fastspända på inhemska havssköldpaddor längs Darkshore får kaldorei en varning: deras uråldriga, muterade släktingar tränger systematiskt upp ur Stora havet."},sec={{t="Troféer från djupet",b="Medan flera jättelika havssköldpaddor och havsdjur helt enkelt spolas upp på Darkshores dimhöljda stränder, berättar andra en långt mer illavarslande historia. På vissa kadaver finns rester av söndersplittrade ridselar och övergivna vagnar som varit fastspända direkt på skalen. I ruinerna av dessa buckliga fordon ligger förseglade behållare täckta av främmande, slingrande runor. Asätande Greymist-murlocker bosätter sig ofta i de ihåliga bröstkorgarna och trasiga vagnarna, där de kalasar på kadavren och vaktar kvarlevorna."},{t="Bevis på nagas expansion",b="När lådan visas för Gwennyth Bly'Leggonde, en forskare som företräder Temple of the Moon i Auberdine, avslöjar märkningarna dess verkliga ursprung. Skriften och de fastspända vagnarna tillhör naga, som använder jättelika sköldpaddor som lastdjur för att frakta förnödenheter och krigsmateriel upp på land. Upptäckten av dessa förrådslådor bekräftar att naga medvetet opererar längs de norra stränderna och kan vara på väg söderut mot Ashenvale med sina riddjur. Därför skickar prästerskapet i Auberdine relikerna direkt till Darnassus för vidare studier."}},faq={{q="Var hittas Strangely Marked Box?",a="Lådan hittas i övergivna vagnar som varit fastspända på skalen hos strandade havssköldpaddor längs Darkshores kust. Kadavren omringas och vaktas ofta av Greymist-murlocker som äter av dem.",al={"var hittar man strangely marked box","lådans plats","låda i sköldpaddsvagn"}},{q="Vem tillverkade Strangely Marked Box?",a="Lådan och dess inskrifter skapades av naga. De fäster lastvagnar på levande havssköldpaddor för att frakta proviant, vapen och utrustning från havets djup upp till Kalimdors stränder.",al={"vem tillverkade lådan","märkningar på lådan","runor på lådan","vad betyder märkningarna"}},{q="Vem vill ha lådan i Auberdine?",a="Gwennyth Bly'Leggonde, en forskare som arbetar i Auberdine på uppdrag av Temple of the Moon, samlar in lådan för att analysera de märkliga strandningarna och förstå det växande hotet från naga.",al={"vem ska jag lämna den till","lämna in lådan","vem vill ha lådan"}},{q="Varför bar havssköldpaddorna lådorna?",a="Naga tämjer eller förslavar jättelika havssköldpaddor och använder dem som lastdjur. De spänner selar och vagnar på deras ryggar för strid och för att frakta förnödenheter upp på land. Gwennyth misstänker att en sådan sköldpadda dödades på väg längre söderut, kanske mot Ashenvale.",al={"varför har sköldpaddor lådor","sköldpaddsvagnar","varför är sköldpaddorna fastspända"}},{q="Vad händer med lådan när du lämnar den till Gwennyth?",a="Gwennyth Bly'Leggonde skickar lådan och resten av kustundersökningens fynd vidare till Temple of the Moon i Darnassus, så att Night Elf-ledarna kan studera omfattningen av nagas intrång.",al={"vart skickas lådan","lådan skickas till darnassus"}}},fx={["981461f5"]={q="Vad är Strangely Marked Box?",a="Det är en last som upptäcktes i en bucklig vagn fastspänd på skalet av en strandad havssköldpadda längs Darkshores kust. Lådan är märkt med märkliga runor och utgör ett fysiskt bevis på organiserad sjötransport längs kusten. Den övergavs efter att transportdjuret dog och därefter blev övermannat av asätare.",al={"vad är den märkta lådan","vad är strangely marked box","föremålet strangely marked box"}},b4ce745f={q="Varför vill Gwennyth Bly'Leggonde ha Strangely Marked Box?",a="Gwennyth Bly'Leggonde söker lådan på uppdrag av Temple of the Moon för att undersöka varför enorma havsvarelser strandar på Darkshore. Om märkningarna tyds bekräftar det att fientliga naga spände fast sköldpaddorna och använde dem som lastdjur för att transportera förnödenheter inåt land. Hon skickar dessa ledtrådar direkt till lärda i Darnassus.",al={"varför vill gwennyth ha lådan","varför leverera strangely marked box","den märkta lådans syfte"}}},fp="20,166,20.333.0,26.406.1,40.167.0,34.173.0,32.145.0,46.234.0,52.166.0"}
P.entries["item:strigid-owl-feather"] = {n="Strigid Owl Feather",s="Strigid Owl Feathers samlas in från vilda strigid-ugglor som häckar bland Teldrassils grenar. Deras fjädrar är vanliga skogsfynd, men de eftertraktas av skumma typer som söker råmaterial för sina hemliga affärer.",h="Strigid Owl Feathers samlas in från vilda strigid-ugglor som häckar bland Teldrassils grenar.",kw={"dolanaar","ingredienser","strigid-uggla","strigid owl feather","strigid-skrikuggla","teldrassil","zenn foulhoof"},ang={["class:Druid"]="Druiderna vördar Teldrassils rovfåglar, så det känns obehagligt att se deras fjädrar samlas in under falska förespeglingar för misstänkta ingredienser.",["race:NightElf"]="Ugglorna i Teldrassil anses vara Elunes skapelser. Därför är det en förolämpning mot den heliga skogen när en satyr som Zenn Foulhoof utnyttjar dem."},sec={{t="Skogsfjädrar och skumma affärer",b="Teldrassils trädkronor är hem åt strigid-ugglor och strigid-skrikugglor, inhemska rovfåglar som jagar över hela Crown of the Earth. Deras dun och fjädrar är vanliga rester på skogsmarken, men ibland lockar de blickarna hos utövare som söker organiska ingredienser. Utanför Dolanaar utnyttjar den avfälliga satyren Zenn Foulhoof oerfarna resenärer som färdas längs vägen från Shadowglen. Han lurar dem att samla strigid-fjädrar, spindelsilke och nightsaber-huggtänder åt hans skumma verksamhet."}},faq={{q="Var hittar jag Strigid Owl Feathers?",a="Fjädrarna samlas från strigid-ugglor och strigid-skrikugglor i skogarna kring Dolanaar och på andra håll i Teldrassil.",al={"fjäderplats","var faller strigid owl feathers","ugglfjäderfarm"}},{q="Vem vill ha Strigid Owl Feathers?",a="En satyr vid namn Zenn Foulhoof, som lurar längs leden in mot Dolanaar, ber godtrogna äventyrare att hämta dem tillsammans med webwood-silke och nightsaber-huggtänder.",al={"vem behöver ugglefjädrar","lämna in ugglefjädrar","zenn ugglefjäder"}},{q="Vad använder Zenn Foulhoof fjädrarna till?",a="Zenn påstår att de är ingredienser som krävs för hans hemliga verksamhet i skogen, men han tycker mest om att lura godtrogna rekryter att göra grovjobbet åt honom.",al={"varför vill zenn ha fjädrar","zenns syfte med ingredienserna"}}},fx={c56fcaa2={q="Vad är en Strigid Owl Feather?",a="En Strigid Owl Feather är en fjäder från de rovlevande strigidugglor som hör hemma bland Teldrassils grenar. De ser ut som vanliga fågelfjädrar, men är kraftfulla naturliga reagenser för dem som ägnar sig åt hantverk, alkemi eller mörkare skogsriter.",al={"strigid owl feather","vad är strigid owl feather","uggelfjäder från teldrassil"}},["91562481"]={q="Var kommer en Strigid Owl Feather ifrån?",a="De här fjädrarna samlas direkt från strigidugglor och strigid skriugglor som häckar i Teldrassils skogar, särskilt kring Dolanaar. Som naturligt biologiskt material som fälls eller tas från skogens fågelrovdjur växer de fram av naturen och skapas inte av dödliga händer.",al={"varifrån kommer strigid owl feathers","strigid owl feathers källa","vem tillverkade strigid owl feather"}}},fp="19,121,32.314.1,38.133.0,31.125.0,45.158.1"}
P.entries["item:sturdy-dragonmaw-shinbone"] = {n="Sturdy Dragonmaw Shinbone",s="Stadiga Dragonmaw Shinbone är slitstarka skeletttroféer från de utbrytarorcher av Dragonmaw-klanen som finns i Wetlands. Rustningssmeden Velora Nitely i Undercity behöver dem som förstärkningsstag i måttbeställda rustningar för krigare.",h="Stadiga Dragonmaw Shinbone är slitstarka skeletttroféer från de utbrytarorcher av Dragonmaw-klanen som finns...",kw={"angerfang encampment","dragonmaw shinbone","benskenor","sturdy dragonmaw shinbone","undercity","velora nitely","wetlands"},ang={["class:Warrior"]="Genom att skaffa och pröva de här täta orchbenen med bara händerna visar en krigare sin fysiska styrka och samlar samtidigt in delar till stommen i en specialtillverkad rustning.",["race:Undead"]="Velora Nitely visar prov på typisk pragmatism hos de Förkastade och gör om sina fienders ben till användbar utrustning åt Mörka damens mästare."},sec={{t="Ben till stommen",b="När smeder smider brutala benskenor åt krigare i frontlinjen behöver de råmaterial som tål hårda slag. I Undercity värdesätter Velora Nitely den täta benstommen hos utbrytarorcherna av Dragonmaw-klanen, som håller till i Angerfang Encampment i centrala Wetlands. Dragonmaw-orcher är kända för sin kraftiga, stadiga benstomme, vilket gör deras skenben väl lämpade som förstärkningar i stommen. Men alla ben som samlas in håller inte måttet. Krigarna måste pröva varje ben med bara händerna och kasta bort dem som knäcks under tryck."}},faq={{q="Vad gör de här skenbenen stadigare än vanliga skenben?",a="Dragonmaw-orcher har naturligt kraftiga benstommar, men små sprickor eller sköra ben gör många exemplar oanvändbara till rustningar. För att kontrollera att ett ben är stadigt böjer en krigare det råa benet med bara händerna. Bara ben som står emot och inte går av anses starka nog att användas i stommen till benskenor.",al={"varför stadiga skenben","dragonmaw-benens styrka","pröva skenben"}},{q="Vem vill ha stadiga Dragonmaw Shinbone?",a="Velora Nitely, en rustningssmed i Undercity, vill ha dem. Hon använder dem som bärande stag när hon tillverkar brutala benskenor åt lovande krigare i Horde.",al={"vem behöver skenben","velora nitely ben","lämna in dragonmaw shinbone"}},{q="Var samlas de här benen in?",a="De tas från utbrytarorcherna av Dragonmaw-klanen som håller till i Wetlands söder om Arathi Highlands, framför allt vid Angerfang Encampment i kullarna sydväst om Thandol Span.",al={"var hittar man dragonmaw shinbone","dragonmaw shinbone plats","angerfang-ben"}},{q="Varför använder Velora Nitely orchben till rustningar?",a="De Förkastades hantverkare blandar ofta ben, senor och metall till krigsutrustning som är makaber men mycket slitstark. Dragonmaw-klanen är fortfarande fientlig mot Thralls Horde, så deras kvarlevor är lovligt byte för de Förkastades smeder som söker tåligt material för krävande hantverk.",al={"varför orchben","de förkastades benrustning","veloras bentillverkning"}}},fp="25,165,19.301.0,58.176.0,37.166.0,31.189.0,47.185.0"}
P.entries["item:sully-balloo-s-letter"] = {n="Sully Balloo's Letter",s="Sully Balloo's Letter är ett vattenmättat, ömsint brev som återfanns bland de sjunkna lämningarna efter en dvärgsoldat under Thandol Span. Det är adresserat till hans hustru Sara i Ironforge och vittnar om de stillsamma, personliga tragedier som dröjer sig kvar under Khaz Modans storslagna konflikter.",h="Sully Balloo's Letter är ett vattenmättat, ömsint brev som återfanns bland de sjunkna lämningarna efter en...",kw={"arathi highlands","ironforge","brev","sara balloo","sully balloo","thandol span","vattenmättat kuvert","wetlands"},ang={["faction:Alliance"]="Att lämna brevet skänker en sorgsen stund av medkänsla och ser till att en fallen soldats sista tankar når hans änka i stället för att glömmas under bron.",["race:Dwarf"]="För dvärgarna står brevet för de hjärtskärande uppoffringar som vanliga bergsbor och soldater gör för att skydda Khaz Modans höga broar och bergspass."},sec={{t="Ett sista farväl under vågorna",b="Under de väldiga stenpelarna i Thandol Span, som förbinder Wetlands med Arathi Highlands, ligger kvarlevorna av en dvärg, fastkilad djupt under det strömmande vattnet. I hans grepp finns ett skört, vattenmättat kuvert med brevet inuti. Det skrevs med stor omsorg under hans sista dagar eller timmar och börjar med de gripande orden: ”Min kära Sara....” Pergamentet har legat länge under vatten, men bläcket bär fortfarande spår av den okuvliga kärleken hos en dvärgförespråkare som aldrig kom hem till Ironforge."},{t="Leverans till Ironforge",b="Att lämna brevet till Sara Balloo i Ironforge ger ett sorgset och förkrossande avslut. Sara bor i dvärgarnas huvudstad och uthärdar den plågsamma ovisshet som delas av så många vars närstående drog ut i krig. När hon läser sin make Sullys sista tankar bekräftas hennes värsta farhågor: han dog långt hemifrån, under det nordliga övergångsställets iskalla strömmar. Ändå bevarar brevet hans hängivenhet bortom döden."}},faq={{q="Var hittas Sully Balloo's Letter?",a="Brevet hämtas ur ett vattenmättat kuvert som hålls i handen på ett skelett av en dvärg, nedsänkt på botten under Thandol Span, som skiljer Wetlands från Arathi Highlands.",al={"brevets plats","var finns sullys brev","var hittar man sully balloos brev"}},{q="Vem var Sully Balloo?",a="Sully Balloo var en dvärgsoldat som miste livet nära Thandol Span när han försvarade den viktiga norra övergången. Hans kvarlevor blev kvar under flodströmmarna.",al={"vem är sully balloo","sully balloos historia","vad hände med sully"}},{q="Vem är brevet adresserat till?",a="Brevet är adresserat till Mrs. Sara Balloo, Sullys sörjande hustru, som bor i den stora dvärgastaden Ironforge inne i berget.",al={"vem får brevet","vem är sara balloo","var lämnar man in sullys brev"}},{q="Vad händer när du lämnar brevet till Sara Balloo?",a="När Sara Balloo får brevet blir hon förkrossad över att få veta att hennes make ligger död och fastkilad under det iskalla vattnet. Samtidigt värdesätter hon chansen att läsa hans sista ord, kärleksfullt skrivna till henne.",al={"sara balloos reaktion","att lämna in brevet","slutföra uppdraget med sullys brev"}}},fx={efe638b9={q="Vad är Sully Balloo's Letter?",a="Det är ett ömt, krigshärjat brev som skrevs med stor omsorg av en dvärgsoldat vid namn Sully Balloo. Det hittades bevarat under det iskalla vattnet vid Thandol Span och innehåller de sista innerliga orden han skrev till sin hustru i Ironforge före sin död i strid.",al={"vad är sullys brev","sully balloos brev","om sully balloo's letter"}},b8624ec6={q="Varifrån kommer Sully Balloo's Letter, och vem skrev det?",a="Brevet skrevs av Sully Balloo, en soldat i Alliansen som tjänstgjorde vid frontlinjen på Thandol Span mellan Wetlands och Arathi Highlands. Det överlevde under vatten i ett genomblött kuvert, som hölls i greppet på hans nedsänkta kvarlevor under den väldiga bron.",al={"vem skrev sully balloo's letter","varifrån kom sully balloo's letter","skaparen av sully balloo's letter"}},b54d6872={q="Varför vill någon ha Sully Balloo's Letter?",a="Brevets mottagare, Sara Balloo, bor i Ironforge utan att känna till sin makes tragiska död. När du överlämnar brevet uppfyller du en fallen soldats sista önskan och ger ett bitterljuvt avslut åt en sörjande änka som väntar på nyheter om sin älskade.",al={"varför lämna över sully balloo's letter","vem vill ha sully balloo's letter","varför lämna brevet till sara balloo"}}},fp="21,158,34.417.0,21.302.1,37.168.0,21.155.0,31.82.0,56.160.1"}
P.entries["item:sunscorched-shell"] = {n="Sunscorched Shell",s="Sunscorched Shells är de tåliga resterna av wyvernägg som samlas under Highperchs boplatser i Thousand Needles. Den hårda ökenhettan gör dem eftertraktade bland skickliga rustningsmakare, som kan förädla dem till en skyddande lack för ringbrynjor.",h="Sunscorched Shells är de tåliga resterna av wyvernägg som samlas under Highperchs boplatser i Thousand...",kw={"darnassus","furen longbeard","highperch","ringbrynja","mathiel","sunscorched shell","thousand needles","wyvern"},ang={["class:Warrior"]="Krigare som söker skräddarsytt skydd i ringbrynja hjälper Mathiel att samla in de här tåliga äggskalen för att tillverka förstärkta rustningar.",["profession:Blacksmithing"]="Skalen visar hur uppfinningsrika smeder ser bortom vanliga malmer och förädlar naturliga mineralbeläggningar till skyddande lack för ringrustningar."},sec={{t="Ökenkullar",b="Högt uppe bland de nålvassa mesas i södra Kalimdor lägger Highperchs wyverner ägg som står emot den obevekliga ökensolen och de brännande vindarna. Kasserade skalbitar samlas under deras boplatser, där det torra klimatet bakar dem ovanligt hårda. För en vanlig vandrare ser de kanske bara ut som sprött avfall, men de här solbrända resterna har en naturlig hållfasthet som gör dem till en intressant ingrediens för specialiserade hantverkare."},{t="En hantverkares lack",b="I Darnassus studerar rustningsmakaren Mathiel tillverkningsmetoder som hans kollega, dvärgasmiden Furen Longbeard, har utvecklat. Mathiel lockas av Furens upptäckter och använder skalen för att skapa en fin lack som kan förstärka ringbrynjor. När den bearbetas och appliceras på rätt sätt fäster den mineralrika beläggningen vid metallringarna och ger dem avsevärt större tålighet utan att tynga ner bäraren."}},faq={{q="Var hittar man Sunscorched Shells?",a="De ligger utspridda på marken under wyvernbon runt Highperch, en hög mesa som reser sig från kanjonbottnen i västra Thousand Needles.",al={"sunscorched shell plats","var hitta skal","highperchskal"}},{q="Vilken varelse kommer skalen från?",a="De är krossade äggskal från Highperchs wyverner, som har sina boplatser uppe på platåerna i Thousand Needles.",al={"vad lade äggen","wyvernägg","skalens ursprung"}},{q="Varför vill Mathiel ha Sunscorched Shells?",a="Mathiel vill pröva rustningssmidestekniker som Furen Longbeard upptäckt. Han förädlar de hårdnade skalen till en tålig lack som täcker och förstärker ringarna i ringbrynjor.",al={"mathiels skal","vad används skal till","rustningslack"}},{q="Vem är Furen Longbeard och hur är han inblandad?",a="Furen Longbeard är kollega till Mathiel inom järnsmide och håller till i Dwarven District i Stormwind. Hans experiment med ovanliga ingredienser och härdningstekniker inspirerade Mathiel att experimentera med lack av wyverns skal.",al={"furens koppling","furen longbeards skal"}}},fx={f589915a={q="Vad är Sunscorched Shell?",a="Sunscorched Shell är det tåliga, kasserade äggskalet från en wyvern i Highperch. Skalen hittas soltorkade under den hårda solen i Thousand Needles, nedanför varelsernas högt belägna bon. De har en anmärkningsvärd naturlig styrka som gör dem eftertraktade bland skickliga rustningsmakare.",al={"vad är sunscorched shell","föremålet sunscorched shell","solbränt äggskal"}}},fp="17,157,15.252.0,21.258.0,35.126.0,40.102.0,41.151.0,46.212.0"}
P.entries["item:super-reaper-6000-blueprints"] = {n="Super Reaper 6000 Blueprints",s="Super Reaper 6000 Blueprints är de tekniska ritningarna till en enorm mekanisk skogshuggare som Venture Company använder i Stonetalon Mountains. Den har konstruerats under uppsikt av gnomingenjören Gerenzo Wrenchwhistle, och hans missnöjda rivaler bland goblinerna åtrår ritningarna starkt.",h="Super Reaper 6000 Blueprints är de tekniska ritningarna till en enorm mekanisk skogshuggare som Venture...",kw={"ritningar","gerenzo","sputtervalve","stonetalon","super reaper 6000","venture company","windshear crag","ziz fizziks"},ang={["profession:Engineering"]="Ritningarna visar en märklig blandning av rå goblinföretagsmakt och noggrann gnomisk mekanisk formgivning. De tekniska schemana förbryllar vanliga mekaniker.",["race:Gnome"]="Gerenzo Wrenchwhistles ritningar visar att även skoningslösa goblinsyndikat som Venture Company i slutändan förlitar sig på gnomisk uppfinningsrikedom för att bygga komplicerade tunga maskiner."},sec={{t="Industrispionage i Windshear Crag",b="Venture Companys skoningslösa kalhuggning i Windshear Crag bygger på enorma mekaniska timmermaskiner som kallas Super Reapers. Till traditionella gobliningenjörers stora förtret satte företaget en gnom vid namn Gerenzo att utforma modellen Super Reaper 6000. Ritningarna innehåller scheman till maskinen och bärs av Venture Co.-operatörer som arbetar med maskinerna runt klippan. När gobliningenjören Ziz Fizziks kastades ut ur verksamheten anställdes han snabbt av Sputtervalve för att stjäla ritningarna. Men att tyda Gerenzos täta, excentriska tekniska anteckningar på gnomiska visar sig vara nästan lika svårt som att ta ritningarna med våld."}},faq={{q="Vad är Super Reaper 6000?",a="Det är en enorm mekanisk skogshuggarmaskin som utvecklats för Venture Companys kalhuggning i Stonetalon Mountains. Den fäller och bearbetar timmer med skoningslös industriell effektivitet.",al={"vad är super reaper","super reaper-maskin"}},{q="Vem utformade Super Reaper 6000?",a="Ritningarna utarbetades under ledning av Gerenzo Wrenchwhistle, en gnomingenjör som Venture Company anställde för att leda deras mekaniska verksamhet i Windshear Crag, till de lokala goblinmekanikernas stora förtret.",al={"vem gjorde ritningarna","vem utformade super reaper"}},{q="Varför vill Ziz Fizziks ha ritningarna?",a="Ziz fick sparken från Venture Company och anställdes genast av Sputtervalve. Att stjäla ritningarna till Super Reaper är Ziz chans att bevisa sitt värde och sitt mekaniska geni för sin nya chef.",al={"varför vill ziz ha ritningarna","vem vill ha ritningarna"}},{q="Vem bär ritningarna i Windshear Crag?",a="De fysiska ritningarna bärs av Venture Co.-operatörer som övervakar maskinerna och avverkar timmer runtom i Windshear Crag.",al={"var får man ritningarna","vem släpper ritningarna"}}},fp="28,277,38.564.0,30.135.0,35.217.0,43.156.0,43.116.0"}
P.entries["item:supplies-for-sven"] = {n="Supplies for Sven",s="Supplies for Sven är ett knippe livsviktiga förnödenheter som packats i Darkshire och ska till Sven Yorgens avskilda läger.",h="Supplies for Sven är ett knippe livsviktiga förnödenheter som packats i Darkshire och ska till Sven Yorgens...",kw={"läger","carevin","darkshire","duskwood","proviant","supplies for sven","sven yorgen"},ang={["class:Paladin"]="De fromma ser Svens orubbliga motstånd mot mörkret i Duskwood som ett sant verk av Ljuset. Därför är dessa förnödenheter en livsviktig tjänst åt en trosbroder.",["faction:Alliance"]="Night Watch är hårt ansatt i försvaret av Darkshire, så resenärer från Alliance fungerar ofta som den enda pålitliga kurirförbindelsen till avlägsna utposter som Svens läger."},sec={{t="En livlina till lägret",b="Att föra överlevnadsutrustning och basförnödenheter genom Duskwood är ingen enkel uppgift. Sven Yorgen och hans fåtaliga följeslagare slår läger i skogens nordvästra vildmark, långt från tryggheten i Darkshire. De är så få och deras vakthållning så krävande att de inte kan avvara en enda kämpe för att ta sig till staden. Paketet är en livlina från familjen Carevin och ser till att det isolerade lägret får mat, bandage och material som behövs för att hålla stånd."}},faq={{q="Vem skickade förnödenheterna?",a="Förnödenheterna skickas genom familjen Carevin i Darkshire. De inser hur desperat Sven Yorgen kämpar i vildmarken och ordnar proviant till hans läger.",al={"vem skickade supplies for sven","vem packade svens förnödenheter","familjen carevins förnödenheter"}},{q="Varför kan inte Sven hämta sina egna förnödenheter?",a="Svens grupp är alltför hårt ansatt. Bara några få överlevande följeslagare vaktar lägret i nordvästra Duskwood mot odjur och odöda, så de kan inte avvara någon som går längs de farliga vägarna till Darkshire.",al={"varför hämtar inte sven mat","varför leverans till sven","varför behövs förnödenheter"}},{q="Var ligger Svens läger?",a="Svens läger ligger längs Duskwoods nordvästra utkant, undangömt bland kullarna långt utanför Night Watchs direkta beskydd.",al={"var finns sven yorgen","svens lägerplats","hitta sven i duskwood"}},{q="Vem är Sven Yorgen?",a="Sven Yorgen är en nybyggare och hängiven troende på Ljuset som en gång brukade jord i Duskwood. Efter att en tragedi drabbat hans gård upprättade han ett beväpnat läger vid gränslandet för att slå tillbaka mot de mörka krafter som plågar trakten.",al={"vem är sven","sven yorgens bakgrund"}}},fx={["0c0166a3"]={q="Vad är Supplies for Sven?",a="Det här är ett stödpaket som samlats ihop åt Sven Yorgen och hans lilla grupp anhängare, som håller stånd i Duskwood. Familjen Carevin förbereder regelbundet sådan hjälp så att dessa hängivna korsfarare kan fortsätta utföra Ljusets arbete mot fasorna i den mörka skogen utan att överge sin vakt.",al={"vad är supplies for sven","vad är sven's supplies","föremålet supplies for sven"}}},fp="17,169,23.310.0,24.132.0,38.196.0,29.114.0,19.227.0"}
P.entries["item:surena-s-choker"] = {n="Surena's Choker",s="I Stormwind söker Gakin the Darkbinder efter halskedjan han gav sin före detta lärling, Surena Caledon. Efter att Surena flydde för att ansluta sig till Defias Brotherhood skickade Gakin aspirerande akolyter för att ta tillbaka den med våld.",h="I Stormwind söker Gakin the Darkbinder efter halskedjan han gav sin före detta lärling, Surena Caledon.",kw={"bloodstone choker","brackwell pumpkin patch","erlan drudgemoor","gakin the darkbinder","slaughtered lamb","surena caledon","surena's choker"},ang={["class:Warlock"]="För en mänsklig eller gnomisk häxmästare är återhämtandet av Surena Caledons halskedja ett grundläggande prov. Det visar att sentimentalitet inte hör hemma i jakten på demonisk makt."},sec={{t="En mästares förlorade investering",b="Gakin the Darkbinder verkar i tysthet under Slaughtered Lamb i Stormwind, där han tog sig an Surena Caledon som en lovande elev i de mörka konsterna. Fängslad av hennes ungdomliga charm och magiska fallenhet gav han henne en värdefull Bloodstone Choker för att hjälpa henne med studierna. Surena övergav sin utbildning och flydde med Erlan Drudgemoor, en skurk som stod i förbund med Defias Brotherhood. Gakin tänker inte låta en förrädare behålla en mäktig artefakt. Han skickar noviser som söker mästerskap över tomrummet för att hitta Surena vid Brackwell Pumpkin Patch och återta halskedjan med våld. Deras handling ska visa var den sanna lojaliteten finns."}},faq={{q="Varför vill Gakin the Darkbinder ha tillbaka Surena's Choker?",a="Gakin gav Surena halskedjan av blodsten när hon var hans lärling. Hon övergav sina studier och flydde med en medlem av Defias Brotherhood, men Gakin tänker inte låta en förrädare behålla en eftertraktad artefakt med mörk magi.",al={"varför vill gakin ha halskedjan","gakin surena halsband","varför ta tillbaka halskedjan"}},{q="Vem är Surena Caledon?",a="Surena Caledon är en före detta lärlingshäxmästare i Stormwind, där hon visade naturlig talang under Gakin the Darkbinder. Hon vände sig bort från sin läromästare och flydde med Erlan Drudgemoor. Nu gömmer hon sig bland Defias laglösa i Elwynn Forest.",al={"vem är surena","surena caledons bakgrund","vem har halskedjan"}},{q="Var finns halskedjan?",a="Surena Caledon bär halskedjan vid Brackwell Pumpkin Patch i östra Elwynn Forest, där hon håller sig gömd bland Defias banditer.",al={"var är surena","halskedjans plats","var är surena caledon"}},{q="Vad används halskedjan till när den har återtagits?",a="Att ta tillbaka halskedjan visar att en akolyt är hänsynslös och lojal mot Gakin the Darkbinder. Han säger inte vad han ska göra med den. Han sörjer Surenas bortkastade talang och hoppas att hans investering i den nya eleven ger andra resultat.",al={"vad gör gakin med halskedjan","halskedjans syfte","varför behöver häxmästare halskedjan"}}},fx={["195efbf9"]={q="Vad är Surena's Choker?",a="Det är ett utsmyckat halsband av blodsten som ursprungligen ägdes av Gakin the Darkbinder, mästerhäxmästaren som håller till på Slaughtered Lamb i Stormwind. Gakin gav det dyrbara smycket till sin före detta lärling Surena Caledon, när han var förtrollad av hennes ungdom och skönhet, innan hon förrådde honom.",al={"vad är surena's choker","vad är surena's choker för något","bloodstone choker"}},["7b9593ae"]={q="Varifrån kommer Surena's Choker, och vem tillverkade det?",a="Det är okänt vem som tillverkade halsbandet, men det tillhörde ursprungligen Gakin the Darkbinder. Gakin gav blodstenshalsbandet till sin unga elev Surena Caledon medan hon studerade för honom, långt innan hon rymde med en Defias-rövare till pumpaplatsen i Elwynn.",al={"vem tillverkade surena's choker","surena's choker ursprung","varifrån kom halsbandet"}}},fp="15,236,26.570.0,56.212.0,22.220.0,30.138.0,50.235.0"}
P.entries["item:swoop-gizzard"] = {n="Swoop Gizzard",s="En swoop kräva är en kroppsdel som samlas in från rovfåglarna som svävar över Mulgore. Den är mycket eftertraktad inom traditionell folkmedicin och är en viktig ingrediens för att rena kroppen från dödliga gifter.",h="En swoop kräva är en kroppsdel som samlas in från rovfåglarna som svävar över Mulgore.",kw={"bloodhoof village","kräva","maur raincaller","mazzranache","mulgore","botemedel","swoop"},ang={["race:Tauren"]="För taurenjägare och schamaner är insamlingen av sådana delar ett sätt att hedra traditionen att använda allt från Mulgore vilda djur för att försörja och läka stammen."},sec={{t="En sällsynt ingrediens inom folkmedicin",b="Swoops är rovfåglar som hör hemma på Mulgore slätter och platåberg. De är kända för sin skarpa syn och vana att äta as. Deras fjädrar och kött används till vardags av tauren, men deras inre organ, särskilt krävan, är högt värderade av örtmedicinare och helare. Tillsammans med andra kraftfulla djurrester, som cougarben och varghjärtan, hjälper den täta muskelvävnaden till att neutralisera giftiga bett och hejda infektioner som sprider sig i kroppen."},{t="Ett botemedel mot Mazzranaches bett",b="I Bloodhoof Village blev medicinarbetaren Maur Raincaller offer för den legendariska plainstridern Mazzranache och fick ett svårt, giftigt sår i axeln. Giftet spred sig och fick Maur att bli omtöcknad. Han förlitar sig på en swoop kräva, ett prairie wolf heart, ett Flatland Cougar Femur och en Plainstrider Scale för att blanda ett läkande omslag som kan driva ut odjurets dödliga gift."}},faq={{q="Vad används en swoop kräva till?",a="Det är en viktig medicinalingrediens som Maur Raincaller behöver i Bloodhoof Village. Tillsammans med tre andra djurdelar blir den ett botemedel som kan rena infektionen från den giftiga plainstridern Mazzranaches våldsamma bett.",al={"användning av swoop kräva","varför behöver jag swoop kräva","syftet med swooporgan"}},{q="Var kommer swoop krävor ifrån?",a="De samlas in från olika swooparter som glider över Mulgore slätter, däribland vanliga swoops, spensliga swoops och kloswoops.",al={"var hittar man swoop kräva","vad släpper swoop kräva","swoopjakt"}},{q="Varför behöver Maur Raincaller just den här kroppsdelen?",a="Maur blev biten av Mazzranache, en ovanligt våldsam plainstrider vars bett sprider ett gift som orsakar hög feber och mardrömmar. Taurenernas traditionella läkekonst använder kraftfulla djurdelar, däribland krävan, för att motverka de särskilda gifterna i hans blod.",al={"maurs botemedel","varför en kräva","botemedel mot mazzranache"}},{q="Används krävan till något annat än Maurs botemedel?",a="Nej. Förutom Maur Raincallers särskilda folkmedicin i Bloodhoof Village har swoop krävor inga vanliga användningsområden inom matlagning, alkemi eller hantverk.",al={"andra användningar av swoop kräva","tillaga swoop kräva","alkemi med swoop kräva"}}},fx={["8f6be1e3"]={q="Vad är Swoop Gizzard?",a="Swoop Gizzard är ett inre organ från rovfåglarna som kallas swoops och glider fram över Mulgore-slätterna. Liksom många fågelorgan hjälper det till att bryta ner segt byte. I traditionell taurenmedicin värdesätts sådana kraftfulla, specialiserade djurdelar för sina naturliga egenskaper och används som ingredienser i örtmediciner och stärkande brygder.",al={"vad är swoop gizzard","föremålet swoop gizzard","vad är en swoop gizzard"}}},fp="13,114,22.349.0,31.337.0,33.225.0,34.128.0,49.218.0,56.147.0"}
P.entries["item:tablet-of-verga"] = {n="Tablet of Verga",s="I Skull Rock ligger Tablet of Verga i Burning Blades händer. Warlocks i Orgrimmar söker dess demoniska runor.",h="I Skull Rock ligger Tablet of Verga i Burning Blades händer.",kw={"burning blade","cleft of shadow","durotar","gan'rul bloodeye","skull rock","tablet of verga","voidwalker"},ang={["class:Warlock"]="Som warlocklärling i Orgrimmar visar du med återtagandet av tavlan att du är värdig Horde och tar ett steg mot att lära dig binda en voidwalker som försvarstjänare.",["faction:Horde"]="Som medlem av Horde möter du Burning Blade nära Orgrimmars portar. När du tar stulna reliker från kulten slår du mot dess inflytande över Thralls unga nation."},sec={{t="En stulen relik",b="Tablet of Verga bär rituella runor för att åkalla varelser från Nether och böja dem efter en mästares vilja. Kulten Burning Blade stal stenen och gömde den i en kista inne i Skull Rock, strax öster om Orgrimmar. Warlocks i The Cleft of Shadow söker den för att studera tecknen och lära sig att åkalla en voidwalker. Om du återtar den hindrar du också kulten från att få samma fördel."}},faq={{q="Var finns Tablet of Verga?",a="Tablet of Verga är gömd i en Burning Blade Stash inne i Skull Rock, ett grottkomplex som kryllar av kultister strax öster om Orgrimmar i Durotar.",al={"tablet of verga plats","var hittar man tablet of verga","var finns verga tablet"}},{q="Vem vill att Tablet of Verga återtas?",a="Gan'rul Bloodeye, en mästerwarlock i The Cleft of Shadow under Orgrimmar, skickar lärlingar för att hämta tavlan så att han kan lära dem att åkalla mäktigare tjänare.",al={"vem behöver tablet of verga","vem ska jag lämna tablet of verga till","gan'ruls tavla"}},{q="Vilken kraft innehåller tavlan?",a="Stenen bär uråldriga runor som behövs för att åkalla och binda en voidwalker, en varelse från Twisting Nether.",al={"vad gör tavlan","tablet of verga bakgrund","tablet of verga runor"}},{q="Varför stal Burning Blade den?",a="Kulten Burning Blade försöker störa Horde och öka sin demoniska makt. När du stjäl tavlan undanhåller du Orgrimmars utövare viktig ritualkunskap, medan kulten behåller den för egen del.",al={"varför har burning blade tavlan","burning blade verga"}}},fx={["5fa1e5b5"]={q="Vad är Tablet of Verga?",a="Tablet of Verga är en relik med inristad mystisk kunskap om häxmästare, särskilt runorna och ritualerna som krävs för att åkalla och binda en voidwalker. Den stals av kultister från Burning Blade och innehåller mörka hemligheter som häxmästare värdesätter när de vill bemästra Twisting Nether och kalla demoner till sin tjänst.",al={"vad är tablet of verga","tablet of verga","verga-tabletten"}}},fp="15,114,14.381.0,37.148.0,40.163.0,35.112.0,35.191.0"}
P.entries["item:tainted-heart"] = {n="Tainted Heart",s="Tainted Heart är en vanhelgad blomkärna som utvunnits ur Teldrassils fördärvade växtlighet. Botanisten Denalan ger den till äventyrare. Den måste renas med magi och näring för att bli fri från kvarvarande onda energier.",h="Tainted Heart är en vanhelgad blomkärna som utvunnits ur Teldrassils fördärvade växtlighet.",kw={"rening","fördärv","denalan","lake al'ameth","planteringskruka","tainted heart","teldrassil"},ang={["class:Druid"]="För cenariska druider ger arbetet med att rena Tainted Heart direkt insikt i det smygande fördärv som hotar det unga världsträdets hälsa.",["profession:Herbalism"]="Örtalister och botanister kan uppskatta Denalans hantverk när han blandar särskilt berikad jord som kan dra ut onaturlig röta ur levande växtmaterial."},sec={{t="En Corrupted Core",b="Teldrassils naturliga balans lider av en onaturlig sjukdom som förvrider dess inhemska växter och djur. Efter att ha avlägsnat den onda mossan som klamrade sig fast vid en vanhelgad växt visar Denalan upp kärnan som blivit kvar: Tainted Heart. Även om den befriats från sin yttre röta genomsyrar mörkret fortfarande vävnaden. Denalan vill ta reda på om särskilt berikad, näringsrik jord kan motverka den kvarvarande smittan och återställa livet i det som fördärvats."},{t="Denalans botemedel",b="När hjärtat placeras i Denalans förtrollade planteringskruka uppvisar det en märklig, kvardröjande livskraft. Det borrar sig ivrigt ner i den näringsrika jorden och tar upp de läkande ämnena. Inom några ögonblick bränner jorden bort fördärvet, och det renade hjärtat kommer fram levande och pulserande av ren energi, ivrigt att försvara dem som helade det."}},faq={{q="Vad är Tainted Heart?",a="Det är den inre kärnan från en fördärvad växt på Teldrassil. Botanisten Denalan avlägsnade den yttre, onda mossan, men själva hjärtat är fortfarande genomsyrat av fördärv tills det renas.",al={"vad är tainted heart","föremålet tainted heart"}},{q="Vem renar Tainted Heart?",a="Denalan ber äventyrare att plantera det i hans särskilt förberedda planteringskruka vid Lake Al'Ameth. Den näringsrika jorden renar naturligt hjärtat och sköljer bort dess onaturliga fördärv.",al={"vem renar det","hur rena tainted heart"}},{q="Vad händer efter att det planterats?",a="Hjärtat borrar sig aktivt ner i planteringskrukans jord. Några ögonblick senare kommer det upp igen, helt renat och pulserande av livskraft, redo att knyta an till den som återställde det.",al={"vad händer med hjärtat","resultat av planterat hjärta"}},{q="Varför är hjärtat fördärvat från början?",a="En märklig farsot har spridit sig över världsträdet Teldrassil och fördärvat dess inhemska växter, timberlings och djurliv bland grenarna.",al={"varför fördärvat","teldrassils fördärvade hjärta"}}},fx={ae8829e0={q="Varför vill Denalan att du planterar Tainted Heart?",a="Denalan har lyckats skrapa bort den vidriga mossan som täcker hjärtat, men dess inre kärna är fortfarande djupt fördärvad. Han hoppas att den näringsrika jorden i den specialpreparerade planteringslådan ska läka skadan, dra ut fördärvet och återställa det levande fröet till sin forna kraft.",al={"varför plantera tainted heart","tainted hearts syfte","varför vill denalan ha tainted heart"}}},fp="13,186,16.335.0,16.285.1,26.171.0,31.179.0,33.144.1,46.137.0"}
P.entries["item:tainted-keg"] = {n="Tainted Keg",s="Tainted Keg är en tunna med stulet dvärgstout spetsat med en dödlig Forsaken-brygd som Apothecary Lydon har blandat till.",h="Tainted Keg är en tunna med stulet dvärgstout spetsat med en dödlig Forsaken-brygd som Apothecary Lydon har...",kw={"apothecary lydon","tillfångatagna bönder","dun garok","elixir of agony","shindigger stout","tainted keg","tarren mill"},ang={["race:Human"]="Massakern på tillfångatagna lantarbetare med spetsat öl visar de fasansfulla, skoningslösa metoder som de levande kvarlevorna i Hillsbrad ställs inför.",["race:Undead"]="För Royal Apothecary Society är det förgiftade ölet ett praktiskt framsteg i utvecklingen av biologiska vapen som kan utrota mänskligheten."},sec={{t="En dödlig årgång",b="Tunnan började som en tunna Shindigger Stout, plundrad från dvärgarnas gevärsskyttar som förskansat sig i Dun Garok. I stället för att dricka ölet förgiftade Apothecary Lydon det mustiga ölet med sitt nyförfinade Elixir of Agony. Genom att spetsas en vanlig dryck skapade Forsaken ett lömskt sätt att sprida giftet, utformat för att undgå misstankar och förvandla något välbekant för de levande till en snabb dödsdom."},{t="Prövning på de dödsdömda",b="Flera mänskliga bönder hölls fångna på övervåningen i värdshuset i Tarren Mill efter att High Executor Darthalia misstänkt att en militärstrateg från Stormwind gömde sig bland dem. När beskedet kom att strategen hade dött någon annanstans blev de tillfångatagna arbetarna förbrukningsbara. Darthalia överlämnade dem till Lydon, som ordnade ett grymt firande genom att låta ställa den förgiftade tunnan på mattan i deras rum. Törstiga och desperata drack fångarna obehindrat och bevisade elixirets omedelbara, dödliga verkan."}},faq={{q="Vad finns i Tainted Keg?",a="Den innehåller Shindigger Stout, ett mustigt dvärgårt stulet från Dun Garok, blandat med Elixir of Agony, ett experimentellt gift som Apothecary Lydon skapade i Tarren Mill.",al={"innehållet i tainted keg","vilket gift finns i tunnan","vad finns i tunnan"}},{q="Varifrån kom ölet ursprungligen?",a="Grundbrygden togs från dvärgarnas bergsjägare och gevärsskyttar som höll Dun Garok, en välförsvarad dvärgfästning i sydöstra Hillsbrad Foothills.",al={"vem tillverkade ölet","var stals ölet","shindigger stout ursprung"}},{q="Vem dricker ur tunnan?",a="En grupp mänskliga bönder som hålls som gisslan i ett rum på övervåningen i värdshuset i Tarren Mill dricker ur tunnan, faller ihop och dör nästan omedelbart av den förgiftade brygden.",al={"vem dricker det","offer för tainted keg","tillfångatagna bönder"}},{q="Varför hölls bönderna fångna?",a="High Executor Darthalia grep dem eftersom hon misstänkte att en militärstrateg från Alliansen i Stormwind gömde sig i deras led. När det bekräftades att strategen hade dött i Plaguelands ansågs de tillfångatagna bönderna vara värdelösa och överlämnades till apotekarna.",al={"varför fångna bönder","varför grep darthalia bönder","varför finns bönder i tarren mill"}}},fx={fd5e0197={q="Vad är Tainted Keg?",a="Tainted Keg är en tunna med stulet dvärgöl av sorten Shindigger Stout, spetsat med en dödlig brygd som Forsaken har blandat till. Apothecary Lydon skapade den här förgiftade satsen som ett praktiskt försök i sin pågående alkemiska forskning.",al={"vad är tainted keg","föremålet tainted keg","vad är det här för tunna"}},["5c778a45"]={q="Varför vill Apothecary Lydon att Tainted Keg används?",a="Apothecary Lydon vill få tunnan levererad för att pröva effekten av sin nyfärdiga Elixir of Agony. High Executor Darthalia har överlämnat tillfångatagna mänskliga bönder åt honom. Genom att bjuda dem på förgiftat öl får Royal Apothecary Society ett bekvämt sätt att på nära håll studera giftets dödliga effekter.",al={"varför använda tainted keg","varför vill lydon ha tainted keg","tainted kegs syfte"}}},fp="11,232,16.285.0,24.469.1,31.167.0,39.141.0,24.127.1,41.262.0"}
P.entries["item:tainted-letter"] = {n="Tainted Letter",s="Drusilla La Salle skickar Tainted Letter till mänskliga häxmästaradepter nära Northshire Abbey. Det bär hennes sigill och uppmanar dem att söka hennes undervisning i hemlighet.",h="Drusilla La Salle skickar Tainted Letter till mänskliga häxmästaradepter nära Northshire Abbey.",kw={"drusilla la salle","elwynn forest","northshire abbey","tainted letter","twisting nether","häxmästare"},ang={["class:Warlock"]="Som häxmästare får du Tainted Letter som din introduktion till den skuggfyllda konsten i kungariket Stormwind. Makt över Nether kräver ständig vaksamhet och diskretion.",["race:Human"]="Som människa lever du i ett samhälle som i stort värnar det heliga ljuset. Utövare av mörk magi tränar i hemlighet i utkanterna av platser som Northshire Abbey."},sec={{t="En hemlig kallelse",b="Tainted Letter bär Drusilla La Salles insignier och når adepter som återvänder från närliggande koboldläger. Medan präster, paladiner och soldater tränar öppet på Northshire Abbeys gräsmattor måste utövare av felmagi hålla sin väg hemlig. Brevet uppmanar novisa häxmästare att söka upp sin mentor nära klosterområdet utan att dra till sig stadsvakternas eller prästernas uppmärksamhet."},{t="Ambitionens pris",b="Drusilla La Salle träffar sina elever i utkanterna, där vakter är mindre benägna att snoka. Elwynns vanliga folk misstror häxmästare, så brevet inleder en lektion i disciplin. Arkana och magi från Nether innebär risk för fördärv. De som samtalar med varelser från Twisting Nether måste tygla sin ambition med tålmodig självbehärskning."}},faq={{q="Vem skickade Tainted Letter?",a="Drusilla La Salle, häxmästartränaren nära Northshire Abbey, skickade brevet.",al={"vem skrev tainted letter","drusillas brev","avsändaren av tainted letter"}},{q="Varför anses brevet vara besmittat?",a="Brevet bär Drusilla La Salles insignier och spår av felmagi, vilket visar att det är verk av en utövare av demoniska konster.",al={"varför är det besmittat","vad gör brevet besmittat","besmittat sigill"}},{q="Varför håller vakterna i Northshire Drusilla La Salle under uppsikt?",a="Northshires vakter och präster misstror felmagi och demonisk frammaning. Drusilla håller sig i klostrets utkanter för att undvika myndigheternas noggranna uppsikt.",al={"drusilla och vakterna","varför misstänker vakterna drusilla","häxmästare gömmer sig i northshire"}},{q="Vilka råd ger Drusilla när man läser brevet?",a="Drusilla varnar för att umgänge med väsen från Twisting Nether medför frestelser och fördärv. Hon uppmanar sina elever att visa självbehärskning och eftertanke samtidigt som de håller fast vid sin ambition.",al={"drusillas råd","vad säger drusilla","drusillas undervisning"}}},fx={["63258adc"]={q="Vad är Tainted Letter?",a="Tainted Letter är ett förseglat meddelande som lämnats åt dig när du återvänder till Northshire Abbey, stämplat med Drusilla La Salles omisskännliga personliga sigill. Det är adresserat till nybörjare inom mörka konster och kallar dig skyndsamt till ett personligt samtal med henne. Det bär svaga spår av felkorruption, vilket tydligt skiljer det från den fromma och ordnade utövningen av det Heliga Ljuset innanför klostrets murar.",al={"vad är tainted letter","tainted letters identitet","om tainted letter"}},["3c923280"]={q="Varför får du Tainted Letter?",a="Du får brevet så att du kan ta kontakt med din tränare, Drusilla La Salle, så snart dina första uppgifter i Northshire är avklarade. Drusilla verkar i det tysta i klostrets utkanter och håller utkik efter blivande häxmästare. Brevet ber dig söka upp henne innan andra ärenden i klostret kommer emellan, så att hon kan ge dig viktiga varningar om självbehärskning, ambition och Twisting Nethers fördärvande natur.",al={"varför behöver jag tainted letter","vem vill ha tainted letter","varför ge tainted letter"}}},fp="14,130,16.336.0,21.323.0,28.78.0,37.117.0,53.145.0,55.187.0"}
P.entries["item:tainted-memorandum"] = {n="Tainted Memorandum",s="Tainted Memorandum är en diskret lapp som ges till unga gnomiska häxmästare i Coldridge Valley. Häxmästarläraren Alamar Grimm har skrivit den och uppmanar läsaren att överge traditionella vägar och söka den sanna kraft som de mörka konsterna erbjuder.",h="Tainted Memorandum är en diskret lapp som ges till unga gnomiska häxmästare i Coldridge Valley.",kw={"alamar grimm","anvilmar","coldridge valley","gnomisk häxmästare","gnomeregan","tainted memorandum"},ang={["class:Warlock"]="Lappen markerar din formella introduktion till häxmästarträning under Alamar Grimm och framställer mörk åkallan som en nödvändig strävan efter kontroll och makt.",["race:Gnome"]="Grimms budskap spelar på gnomernas bitterhet över förlusten av Gnomeregan och deras upplevda ställning som beroende flyktingar i dvärgarnas länder."},sec={{t="En diskret kallelse",b="I den kyliga dvärgiska utposten Anvilmar är utövare av felmagi varken hyllade eller särskilt betrodda. För unga gnomer som prövar förbjudna konster fungerar Tainted Memorandum som en inbjudan från Alamar Grimm. Budskapet avvisar beroendet av det heliga ljuset eller vanligt stridsstål och pekar i stället på Gnomeregans fall som bevis för att traditionella metoder och uppfinningsrikedom har svikit deras folk. För Grimm leder det ingenstans att förlita sig på dvärgisk välgörenhet. Gnomer måste ta obestridlig makt i egna händer och kalla fram lydiga tjänare om de någonsin ska kunna säkra sin egen framtid."}},faq={{q="Vem skrev Tainted Memorandum?",a="Memorandumet skrevs av Alamar Grimm, den gnomiska häxmästarläraren som är stationerad i Anvilmar i Coldridge Valley.",al={"författare tainted memorandum","vem skickade tainted memorandum","alamar grimm lapp"}},{q="Varför anses memorandumet vara ”besudlat”?",a="Det handlar direkt om förbjuden häxmästarmagi. Titeln speglar misstron och stigmat kring demonisk kraft och felkraft i Dun Morogh, där de dvärgiska värdarna håller utövarna på avstånd.",al={"varför besudlad","tainted letter bakgrund"}},{q="Vad säger Alamar Grimm om Gnomeregan?",a="Grimm känner bitterhet över den gnomiska huvudstadens fall och skyller på traditionell arkana magi och vårdslöst experimenterande för att ha fört deras folk nära utrotning. Han tror att dvärgarna ser gnomer som andra klassens medborgare och uppmanar häxmästare att finna sin egen absoluta kraft i stället för att vänta på hjälp från Alliansen.",al={"alamar grimm gnomeregan","alamar grimms åsikter"}}},fx={["0c729b68"]={q="Vad är Tainted Memorandum?",a="Tainted Memorandum är ett diskret, personligt meddelande till lovande gnombaserade häxmästare som just har påbörjat sin träning i Coldridge Valley. Allierade på ytan förmedlar lappen i hemlighet. Den bjuder in dig att se bortom Heliga Ljusets traditioner och fysisk strid, och i stället söka upp likasinnade, fördomsfria utövare av mörka konster.",al={"vad är tainted memorandum","tainted memorandum","vad är det här för lapp"}},e7be2e4a={q="Varför vill någon att du ska ha Tainted Memorandum?",a="Memorandumet ges till dig för att rekrytera dig till häxmästarnas krets. Häxmästartränaren Alamar Grimm skickar det för att hitta nybörjare som förkastar vanliga dvärg- och gnomdogmer. Han uppmanar dig att träffa honom i Anvilmar för att bemästra lydiga, åkallade bundsförvanter och upptäcka den sanna källan till demonisk kraft.",al={"varför fick jag memorandumet","varför tainted memorandum","vem vill ha tainted memorandum"}}},fp="18,125,18.486.0,33.82.0,43.180.0,44.277.0"}
P.entries["item:talisman-of-corruption"] = {n="Talisman of Corruption",s="Talisman of Corruption är en vidrig demonisk prydnad som satyren Xabraxxis använder för att förgifta Blackwoodfurbolgernas sinnen i Darkshore. Den bärs i satyrens personliga pung och fungerar som en magisk kanal som binder stammen till kaos från avgrunden.",h="Talisman of Corruption är en vidrig demonisk prydnad som satyren Xabraxxis använder för att förgifta...",kw={"auberdine","blackwood","darkshore","furbolg","satyr","talisman of corruption","thundris windweaver","xabraxxis"},ang={["class:Druid"]="Druider ser föremål som talismanen som direkta förvrängningar av naturens ordning. De förvandlar heliga bestar till vilda brickor åt Burning Legions kvarvarande tjänare.",["race:NightElf"]="För Kaldorei i Auberdine är det ett viktigt steg mot att befria sina furbolgallierade från demonisk förnedring och läka landet att återfinna talismanen."},sec={{t="En kanal till vansinne",b="Nattalverna i Auberdine har länge försökt förstå varför Blackwoodfurbolgerna vände sig så aggressivt mot sina forna allierade. Thundris Windweaver upptäckte att stammens fall inte var en naturlig utveckling, utan ett medvetet sabotage utfört av satyrerna. Med talismaner som den här sprider demoniska agenter fördärvande trolldom över vildmarken, förgiftar matförråd och förvandlar fridfulla skogsandar till ursinniga bestar. Genom att kanalisera vidrig magi direkt genom dessa föremål håller satyrerna ett obevekligt grepp om de lokala stammarnas sinnen och vilja."},{t="Bryta greppet",b="För att locka fram den ansvariga satyren måste äventyrare rena prover av furbolgernas mat med välsignat månskensbrunnsvatten och rena lägret tillräckligt länge för att reta upp dess övervakare. När Xabraxxis dödas bryts hans omedelbara grepp, och hans demonväska blir deras byte. Talismanen ligger inuti. Om talismanen lämnas till Thundris Windweaver i Auberdine kan Kaldorei oskadliggöra dess vidriga utstrålning och undersöka hur den demoniska plåga som härjar i skogen kan upphävas för gott."}},faq={{q="Vad är Talisman of Corruption?",a="Det är ett demoniskt föremål som satyren Xabraxxis använder för att kanalisera vidrig magi och fördärva Blackwoodfurbolgernas sinnen och matförråd i Darkshore.",al={"vad är talisman of corruption","talismanens syfte","vad gör talismanen"}},{q="Vem bär talismanen?",a="Den förvaras i demonväskan som bärs av Xabraxxis, en satyr som övervakar det norra Blackwoodfurbolglägret nära Cliffspring River.",al={"vem droppar talisman of corruption","var hittar man talisman of corruption","hur får man tag på talismanen"}},{q="Hur lockar du fram talismanens ägare?",a="Du måste samla prover av furbolgernas frukt, säd och nötter, blanda dem med månskensbrunnsvatten i en reningsskål och ställa fram offret vid bålet nära floden. När furbolgerna renas blir Xabraxxis rasande och går till attack.",al={"hur tillkallar man xabraxxis","hur hittar man xabraxxis","tillkalla satyr i darkshore"}},{q="Vad händer med talismanen när den återfunnits?",a="Den lämnas över till Thundris Windweaver i Auberdine. Han säkrar artefakten för att den ska kunna förstöras och studerar den för att lära sig hur furbolgerna kan befrias från demoniskt fördärv för gott.",al={"vem ska jag lämna talismanen till","lämna in talisman of corruption","thundris windweaver talisman"}}},fp="22,205,20.427.0,17.356.1,35.130.0,25.124.0,46.211.0,51.160.0"}
P.entries["item:tallonkai-s-jewel"] = {n="Tallonkai's Jewel",s="Tallonkai's Jewel är en lysande smaragd som stals från en förtrollad druidsk talisman på Teldrassil. Den dyrkas av furbolgmystikern Ferocitas the Dream Eater och är den avgörande mittstenen som krävs för att laga Emerald Dreamcatcher.",h="Tallonkai's Jewel är en lysande smaragd som stals från en förtrollad druidsk talisman på Teldrassil.",kw={"dolanaar","emerald dreamcatcher","ferocitas the dream eater","gnarlpine-mystiker","starbreeze village","tallonkai swiftroot","tallonkai's jewel"},ang={["class:Druid"]="Smaragden är en druidisk komponent som är avstämd för att genljuda med The Emerald Dream. Att missbruka den är därför en kränkning av balansen.",["race:NightElf"]="När juvelen återtas bidrar det till att återställa ordningen på Teldrassil genom att rycka heligt hantverk ur händerna på de framryckande Gnarlpine."},sec={{t="En stulen kärna",b="Tallonkai Swiftroot fick Emerald Dreamcatcher av Gaerolas Talvethen, druidernas väktare i Ban'ethil Barrow Den, som ett kraftfullt fokus som suger åt sig energi från The Emerald Dream. När hans talisman skadades bändes den strålande smaragden i mitten loss och fördes bort till östra Teldrassils vildmarker. Juvelen hamnade i Ferocitas the Dream Eaters klor, en korrumperad ledare för Gnarlpine som gjorde den glänsande stenen till ett personligt halsband. Den gröna stenen spred ett kusligt sken i skogens mörker, men dess verkliga, harmoniska resonans var helt oanvändbar för furbolgen och fungerade bara som en trofé tills den återtogs."}},faq={{q="Vad är Tallonkai's Jewel?",a="Det är en förtrollad, lysande smaragd som utgör mittstenen i Emerald Dreamcatcher, ett druidiskt fokus som Gaerolas Talvethen gav till Tallonkai Swiftroot i Dolanaar.",al={"vad är juvelen","tallonkai jewel berättelse"}},{q="Vem stal Tallonkai's Jewel?",a="Den stals av Ferocitas the Dream Eater, en ledare bland de korrumperade Gnarlpine-mystikerna som bor norr om Starbreeze Village.",al={"vem har juvelen","vem stal den","vem tog tallonkai's jewel"}},{q="Kan Gnarlpine-furbolgarna använda juvelens kraft?",a="Nej. Ferocitas bar smaragden runt halsen som en lysande prydnad, men Tallonkai säger att stenens druidiska kraft är helt oanvändbar för de korrumperade furbolgarna.",al={"kan ferocitas använda den","gnarlpine smaragdens kraft"}},{q="Vart förs juvelen när den återtas?",a="Stenen återlämnas till Tallonkai Swiftroot på den övre nivån i Dolanaar, där han använder den för att återställa och laga Emerald Dreamcatcher helt.",al={"vad händer med juvelen","laga dreamcatcher"}}},fx={["4dd99e12"]={q="Varför vill någon ha Tallonkai's Jewel?",a="Tallonkai Swiftroot behöver desperat få tillbaka den lysande smaragden för att kunna laga sin skadade Emerald Dreamcatcher. Ferocitas the Dream Eater, den fördärvade mystikern bland Gnarlpine-furbolgerna, tog den för att bära den som ett glänsande halsband. Han lockades av dess magiska sken utan att förstå att dess drömbundna kraft är helt värdelös i hans händer.",al={"varför vill någon ha tallonkai's jewel","varför vill tallonkai ha juvelen","varför stjäla tallonkai's jewel"}}},fp="17,163,13.592.0,26.166.0,28.119.0,49.113.0,46.137.0"}
P.entries["item:taming-rod"] = {n="Taming Rod",s="I Durotar hjälper Taming Rods nybörjarjägare att lära sig styra bestar. Tränare ger dem till elever så att de kan öva innan de knyter varaktiga band till djurkamrater.",h="I Durotar hjälper Taming Rods nybörjarjägare att lära sig styra bestar.",kw={"bepansrad skorpion","vildsvin med mörka fläckar","jägarens husdjur","razor hill","taming rod","taming the beast","thotar"},ang={["class:Hunter"]="Som jägare använder du Taming Rod för att öva innan du kan knyta varaktiga band till vildbestar.",["faction:Horde"]="I Durotar och Mulgore använder tränare som Thotar Taming Rods för att pröva om unga rekryter har disciplin nog att bemästra Kalimdors hårda vildmark."},sec={{t="En vägledares träningsredskap",b="I Razor Hill ger tränare som Thotar Taming Rods till blivande jägarna bland orcher och troll. De förtrollade verktygen hjälper nybörjare som ännu inte kan binda en vild varelse för gott. En stav lugnar ett rovdjur från trakten, som ett dire mottled boar eller en armored scorpid, så att jägaren kan öva på att ge order och slåss tillsammans med en djurkamrat. Bandet varar bara en kort stund, så eleven kan lära sig utan att knyta ett varaktigt band till besten."},{t="Ett steg mot mästerskap",b="Magin i varje Taming Rod försvinner efter en kort stund, och varje stav är anpassad för särskilda sorters vildbestar. Nybörjare ställs inför flera prov mot bestar med olika temperament, från fogliga födosökare till aggressiva giftiga jägare. När en elev har visat att hen kan styra dem går staven tillbaka till tränaren. Tränaren lär sedan eleven att tämja, kalla på och avvisa livslånga följeslagare utan en artefakt."}},faq={{q="Vad används en Taming Rod till?",a="Jägare använder en Taming Rod för att öva på att styra en best i strid. Tränaren ger den till en ung jägare, och dess magi lugnar och förtrollar varelsen en kort stund.",al={"vad gör en taming rod","använda taming rod","varför har jag en taming rod"}},{q="Behåller jag husdjuret jag tämjer med staven?",a="Nej. En best som påverkas av en Taming Rod är där endast för träning, och bandet upphör när magin klingar av eller du lämnar tillbaka staven. Efter dina prov lär du dig att tämja en varaktig följeslagare.",al={"är husdjuret permanent","behåller jag vildsvinet","behåller jag skorpionen"}},{q="Kan jag använda vilken Taming Rod som helst på vilket djur som helst?",a="Nej. Varje Taming Rod är anpassad för en viss målvarelse i sitt träningsskede, som ett dire mottled boar eller en armored scorpid.",al={"fungerar staven på alla djur","mål för taming rod"}},{q="Får jag behålla Taming Rod efter träningen?",a="Nej. Du lämnar tillbaka Taming Rod till din jägartränare efter ditt uppdrag. Efter ditt sista prov lär tränaren dig att tämja, kalla på och avvisa bestar på egen hand.",al={"behålla taming rod","kan jag spara staven"}}},fx={c3dba9d3={q="Vad är Taming Rod?",a="Taming Rod är ett träningsredskap som tränare ger åt nybörjarjägare. Den är förtrollad så att den tillfälligt kan böja en vild varelses vilja efter din, och fungerar som ett hjälpmedel under träningen. Med den får en blivande jägare uppleva den fina balans som krävs för att styra vilda djur i strid, utan att knyta ett permanent band innan grundkunskaperna är helt inlärda.",al={"vad är taming rod","föremålet taming rod","taming rods bakgrund"}},da578f9f={q="Varför vill en jägare ha Taming Rod?",a="Nybörjarjägare behöver spöet för att visa att deras förmåga att styra naturen växer. När du lyckas kuva farliga bestar som vildsvin eller skorpider visar du den beslutsamhet och självbehärskning som krävs för att kontrollera ett vilt sinne. När du har visat din tränare att du kan styra dessa varelser i strid får du lära dig konsten att knyta ett varaktigt band till bestar.",al={"varför behöver man taming rod","taming rods syfte","varför använda taming rod"}}},fp="10,173,28.452.0,21.407.0,30.162.0,38.190.0,39.138.0,56.172.0"}
P.entries["item:taragaman-the-hungerer-s-heart"] = {n="Taragaman the Hungerer's Heart",s="Under Orgrimmar söker Neeru Fireblade efter Taragaman the Hungerer's Heart som bevis på att den demoniska närvaron har utplånats. Den makabra trofén kommer från demonvakten som härskar i djupet av Ragefire Chasm.",h="Under Orgrimmar söker Neeru Fireblade efter Taragaman the Hungerer's Heart som bevis på att den demoniska...",kw={"felguard","hjärta","hungerer","neeru fireblade","orgrimmar","ragefire chasm","searing blade","taragaman"},ang={["class:Warlock"]="Som häxmästare känner du till den känsliga väven av skuggor och svek som råder i Cleft of Shadow. Att göra upp med Neeru Fireblade och ta hand om demoniska kvarlevor är välbekanta saker.",["faction:Horde"]="Som medlem av Horde hjälper du till att skydda Orgrimmar från inre fördärv. Odjurets avhuggna hjärta vittnar om Hordes vaksamhet."},sec={{t="En trofé av svek",b="Taragaman the Hungerer's ångande hjärta bevisar att demonvakten har fallit. Neeru Fireblade berättar för Thrall och ivriga äventyrare att Taragaman leder Searing Blade-kultisterna i Ragefire Chasm. Att lämna hjärtat till Neeru verkar uppfylla krigshövdingens order att skydda Orgrimmar mot demonisk förvrängning. Att skylla på en brutal demonvakt för att ha lett kulten håller också de dödligas nätverk under staden utom synhåll."}},faq={{q="Vem vill ha Taragaman the Hungerer's Heart?",a="Neeru Fireblade, en orcisk häxmästare i Orgrimmars Cleft of Shadow, ber dig hämta hjärtat som bevis på att demonen har dödats.",al={"vem tar taragamans hjärta","lämna in taragamans hjärta","vem vill ha hjärtat"}},{q="Var får jag tag på hjärtat?",a="Du tar hjärtat från Taragaman the Hungerer's lik i de centrala magmakamrarna i Ragefire Chasm under Orgrimmar. Den respektingivande demonvakten håller till där.",al={"hur får man tag på taragamans hjärta","var får man taragamans hjärta","taragamans hjärta plats"}},{q="Får Thrall någonsin se hjärtat?",a="Nej. Du tar hjärtat direkt till Neeru Fireblade. Han säger att han ska ta hand om de demoniska kvarlevorna och berätta för krigshövding Thrall om segern åt dig.",al={"får thrall hjärtat","ge hjärtat till thrall","thrall taragamans hjärta"}},{q="Var Taragaman verkligen ledare för Searing Blade?",a="Neeru Fireblade pekar ut Taragaman the Hungerer som ledare för Searing Blade och säger att det kommer att blidka Thrall om du dödar honom och tar tillbaka hans hjärta.",al={"är taragaman ledaren","vem leder searing blade","taragaman verklig boss"}}},fx={a71e3ad9={q="Vad är Taragaman the Hungerer's Heart?",a="Det är det utskurna hjärtat från Taragaman the Hungerer, en väldig felguard som lurar i de brinnande djupen av Ragefire Chasm under Orgrimmar. Äventyrare har burit ut det ur grottorna. Det är ett fysiskt bevis på att demonen som Neeru Fireblade kallar Searing Blades ledare har fällts.",al={"vad är taragaman the hungerer's heart","taragaman the hungerer's heart","taragaman the hungerer's heart bakgrund"}},d8388abb={q="Varifrån kommer Taragaman the Hungerer's Heart?",a="Hjärtat har skurits ut ur bröstet på Taragaman the Hungerer, en enorm felguard som håller till djupt inne i Ragefire Chasm. Kultisterna från Searing Blade åkallade Taragaman och höll honom i tunnlarna under Orgrimmar. Hjärtat är en kvarleva från den demoniska korruption som infekterar stadens underjord.",al={"taragaman the hungerer's heart ursprung","varifrån kom hjärtat","vem tillverkade taragaman the hungerer's heart"}}},fp="30,182,18.408.1,41.130.0,29.153.0,31.144.0,52.144.1"}
P.entries["item:tattered-manuscript"] = {n="Tattered Manuscript",s="Tattered Manuscript består av lösa, skändade sidor som rivits ur det enda exemplaret av Tome of the Cabal. Undangömd i södra Kalimdors dammiga djup rymmer denna slitna del av texten magiska hemligheter som är oumbärliga för häxmästare som vill bemästra feljägare.",h="Tattered Manuscript består av lösa, skändade sidor som rivits ur det enda exemplaret av Tome of the Cabal.",kw={"feljägare","jorah annison","krom stoutarm","moldy tome","splithoof hold","tattered manuscript","thousand needles","tome of the cabal"},ang={["class:Warlock"]="Att hämta manuskriptet är en viktig övergångsrit för blivande häxmästare och ger dem kunskapen som krävs för att kuva rovgiriga feljägare."},sec={{t="Ett skändat grimoar",b="Tome of the Cabal var en gång en hel och unik volym som förvarades i det fallna kungariket Lordaeron. Vid något tillfälle slet en okänd vandalisatör nästan halva skriften direkt ur dess bindning. Medan den bevarade ryggen och resten av boken, som nu kallas Moldy Tome, skeppades söderut mot Khaz Modan och försvann till havs, drev dessa sönderrivna pergamentblad långt över Stora havet till Kalimdor, där de till slut hamnade hos Galak-kentaurerna i Splithoof Hold."},{t="Återta orden",b="Manuskriptet förvarades i en sliten kista djupt inne i Splithoof Holds labyrintiska grottor och överlevde Thousand Needles hårda, torra vindar. Trots sitt sköra och sönderrivna skick vågar utövare av de mörka konsterna, både allianshäxmästare som arbetar med Krom Stoutarm i Ironforge och hordens utövare som hjälper Jorah Annison i Undercity, möta de aggressiva kentaurerna för att förena de förlorade bladen med Moldy Tome. När de sammanförts innehåller den fullständiga skriften de mörka ritualer som krävs för att åkalla och binda en demonisk feljägare."}},faq={{q="Vad är Tattered Manuscript?",a="Det är en samling sönderrivna pergamentblad som utgör ungefär halva Tome of the Cabal, ett legendariskt och unikt grimoar om demonologi.",al={"lore om tattered manuscript","vad är manuskriptet","sidor ur tome of the cabal"}},{q="Hur hamnade de här sidorna i Thousand Needles?",a="Efter att grimoaren skändats i Lordaeron korsade de bortrivna sidorna på något sätt havet och hamnade hos Galak-kentaurerna, som gömde dem i en kista i Splithoof Hold.",al={"varför i splithoof hold","kentaur och tome","manuskript i thousand needles"}},{q="Vad används manuskriptet till?",a="Häxmästare måste återförena Tattered Manuscript med den vattendränkta Moldy Tome för att återskapa hela Tome of the Cabal och låsa upp ritualen för att åkalla en feljägare.",al={"varför behöver jag manuskriptet","feljägaruppdragets sidor"}},{q="Vem slet sönder originalboken?",a="Den skyldige är fortfarande okänd. Både Krom Stoutarm i Ironforge och Jorah Annison i Undercity beklagar skändningen och kan inte förstå vem som skulle begå en sådan handling mot ett unikt lärdomsverk.",al={"vem slet sönder tome","vem skändade tome of the cabal"}}},fp="19,178,21.399.0,20.415.0,32.126.0,47.167.0,32.166.0,56.168.0"}
P.entries["item:tazan-s-satchel"] = {n="Tazan's Satchel",s="Nära Ratchet bär Tazan på en låst väska medan han gör upp med pirater längs kusten. The Shattered Hand vill åt den hemliga informationen därinne.",h="Nära Ratchet bär Tazan på en låst väska medan han gör upp med pirater längs kusten.",kw={"the barrens","cleft of shadow","gamon","ratchet","shattered hand","tazan","tazan's satchel","therzok"},ang={["class:Rogue"]="Som rogue i Horde måste du hämta väskan och ta nyckeln från Gamon för att förtjäna din plats i The Shattered Hand.",["faction:Horde"]="I Orgrimmar söker The Shattered Hand fördelar i det fördolda medan hövding Thrall följer en mer återhållsam kurs."},sec={{t="The Barrens hemligheter",b="Tazan gör upp med pirater som slagit läger längs The Barrens kust nära Ratchet. Therzok, en skråmästare i The Shattered Hand under Orgrimmar i The Cleft of Shadow, får upp ögonen för honom. Skrået söker dold makt bortom hövding Thralls försiktiga diplomati och märker ut Tazan för döden för att lägga beslag på uppgifterna i hans väska."},{t="Ett invecklat lås",b="Väskans lås gör den svår att öppna ute i fält. Tazan gav nyckeln till Gamon, sin kompanjon, som är ett fyllo och ett välbekant inslag på en krog i Orgrimmar. Rogues som är ute efter väskan måste ta nyckeln ur Gamons ficka utan att väcka uppmärksamhet. Sedan kan de läsa Tazans loggbok."}},faq={{q="Vem tillhör den här väskan?",a="Väskan tillhör Tazan, en troll som gör upp med pirater nära Ratchet i The Barrens.",al={"vem är tazan","tazans ägare","väskans ägare"}},{q="Varför vill Shattered Hand ha Tazan's Satchel?",a="Therzok och The Shattered Hand vill åt uppgifterna om Tazans affärer med kustpirater för att utöka sitt nätverk och återta sin krigiska stolthet i skuggorna.",al={"varför vill therzok ha den","shattered hands väska","varför stjäla väskan"}},{q="Var finns nyckeln som öppnar väskan?",a="Tazan lämnade nyckeln hos sin kompanjon Gamon, en berusad gäst på en krog i Orgrimmar.",al={"hur öppnar man väskan","tazans nyckel","var finns nyckeln"}},{q="Vad finns i Tazan's Satchel?",a="Tazans loggbok ligger i den låsta väskan och beskriver hans hemliga affärer och band till kustens sjörövare.",al={"väskans innehåll","vad finns i påsen","tazans loggbok"}}},fp="15,142,22.319.0,14.274.1,32.89.0,49.163.0,37.85.1,31.109.1"}
P.entries["item:tear-of-the-moons"] = {n="Tear of the Moons",s="Vid Bael Modan i södra Barrens har dvärgiska utgrävare grävt fram Tear of the Moons. Dess märkliga kraft driver Feegly in i besatthet, medan General Twinbraid fruktar vad kristallen kan göra.",h="Vid Bael Modan i södra Barrens har dvärgiska utgrävare grävt fram Tear of the Moons.",kw={"bael modan","bael'dun keep","the barrens","utgrävning","feegly","tear of the moons","trogg","twinbraid"},ang={["faction:Horde"]="Som medlem av horden hjälper du till att återta reliken från Bael'dun Keep och stör därmed Ironforges militära närvaro, som tränger in på taurenfolkets förfäders marker.",["race:Dwarf"]="Som dvärg varnar Feeglys öde för faran med vad expeditionen vid Bael'dun riskerar att väcka under Kalimdor."},sec={{t="En uppgrävd relik",b="Dvärgiska utgrävare grävde fram Tear of the Moons under den första utgrävningen vid Bael Modan. Kristallens märkliga sken fängslade gruvarbetarna, särskilt Feegly. Han hävdade att den gav honom stor styrka, men blev sedan instabil och vände sig mot sina kamrater. General Twinbraid, expeditionens befälhavare, fruktade relikens inflytande och förklarade den förbannad. Han tog kristallen och låste in den i sin personliga kassaskrin på Bael'dun Keep. Sedan förvisade han Feegly till Barrens."},{t="Besatthetens pris",b="Den förvisade Feegly kan inte tygla sitt begär efter kristallens kraft. Han ber förbipasserande resenärer ur horden att hjälpa honom bryta sig in i dvärgarnas fästning och ta kristallen ur Twinbraids valv. När Feegly får tag på Tear och gnider den undslipper märkliga grymtningar honom. Kristallen faller ur hans händer och krossas mot marken. Feegly förvandlas till en trogg och dör kort därefter."}},faq={{q="Varifrån kom Tear of the Moons?",a="Dwarven Prospectors och utgrävare grävde fram Tear of the Moons vid Bael Modan, en arkeologisk utgrävningsplats i södra Barrens.",al={"tears ursprung","var hittades tear","bakgrund om tear of the moons"}},{q="Varför låstes kristallen in i Bael'dun Keep?",a="General Twinbraid fruktade att kristallen var förbannad efter att Feegly blivit besatt av den och vänt sig mot sina medgruvarbetare. Han låste in den i sitt kassaskrin på Bael'dun Keep för att skydda expeditionen.",al={"varför låstes den in","twinbraids kassaskrin och tear","varför tog twinbraid den"}},{q="Vad händer när Feegly får tillbaka Tear?",a="Feegly gnider kristallen, som faller ur hans händer och krossas. Han förvandlas till en trogg och dör kort därefter.",al={"feegly förvandlas till trogg","vad händer med feegly","feeglys troggförvandling"}},{q="Går det att rädda eller laga Tear of the Moons?",a="Tear krossas när Feegly får tillbaka den. Berättelsen säger inget om att någon lagar den efteråt.",al={"kan man behålla tear","krossad tear","laga tear of the moons"}}},fx={f703febe={q="Vad är Tear of the Moons?",a="Tear of the Moons är en mystisk, lysande kristall som dvärgiska utgrävare grävde fram under sin expedition i Bael Modan i södra Barrens. Den hyllades som platsens första stora upptäckt, men artefakten visade sig vara mycket instabil. Den utstrålade en fördärvande kraft som förvrängde sinnet hos dvärgen som höll i den och fick expeditionens ledning att låsa in den.",al={"tear of the moons","vad är tear of the moons","vad är tåren"}}},fp="17,197,17.475.0,22.353.1,42.133.0,48.194.0,44.115.1,47.103.1"}
P.entries["item:tear-of-tilloa"] = {n="Tear of Tilloa",s="I Duskwood växer Tear of Tilloa på godset Mistmantle nära Darkshire. Dess användning inom alkemi väcker intresse hos dem som söker sällsynta reagenser.",h="I Duskwood växer Tear of Tilloa på godset Mistmantle nära Darkshire.",kw={"en brygd åt adeln","darkshire","mistmantle","stalvan","tear of tilloa","tilloa","wishock","zardeth"},ang={["class:Warlock"]="Som häxmästare kanske du känner till Tear of Tilloa som en reagens som ockulta agenter under huvudstaden söker efter till brygder avsedda att tysta nyfikna adelsmän.",["profession:Herbalism"]="Som örtmästare kan du hitta Tear of Tilloa växande i Duskwoods sargade jord, långt från de vanliga frodiga fälten."},sec={{t="En trädgård i dunklet",b="Tear of Tilloa växer på ägorna kring Stalvan Mistmantles gods utanför Darkshire. Duskwoods jord har blivit ogästvänlig för frisk växtlighet, men den lilla vita blomman håller sig kvar bland de skuggiga odlingslotterna. Den växer sällan och på en undangömd plats, vilket lockar dem som söker ovanliga reagenser utanför lagliga marknader."},{t="En brygd åt adeln",b="Under Stormwinds gator söker Zardeth of the Black Claw Tear of Tilloa för att brygga en dryck åt Lord Wishock. Wishock är medlem av House of Nobles och hotar att undersöka skumma verksamheter under huvudstaden. Zardeth blandar blomman med Musquash Root från området under Stonewrought Dam för att skapa en brygd som ska distrahera och oskadliggöra Wishock innan en officiell undersökning kan inledas."}},faq={{q="Var växer Tear of Tilloa?",a="Blomman växer i utkanten av Darkshire i Duskwood, i den igenvuxna trädgården på familjen Mistmantles gods.",al={"tear of tilloa plats","var finns tear of tilloa","tilloa plats"}},{q="Vem vill ha Tear of Tilloa?",a="Zardeth of the Black Claw söker blomman medan han verkar i hemlighet under Stormwind City, där han behöver den till en särskild dryck.",al={"vem behöver tear of tilloa","uppdragsgivare för tear of tilloa","vem vill ha den"}},{q="Vad används blomman till?",a="Blomman blandas med Musquash Root för att skapa en brygd som ska oskadliggöra Lord Wishock och tysta hans krav på en undersökning av mörka förehavanden under huvudstaden.",al={"tear of tilloa användning","vad gör tear of tilloa","blomma till adelsbrygd"}},{q="Vem är Lord Wishock?",a="Lord Wishock är en adelsman i Stormwinds House of Nobles. När han fick höra talas om omstörtande verksamhet under staden började han uppmana rådet att undersöka saken.",al={"wishock","vem är wishock","lord wishock"}}},fx={e7b72a0d={q="Vad är Tear of Tilloa?",a="Tear of Tilloa är en skir, sällsynt vit blomma som blommar i Duskwood. Den växer särskilt i den vanskötta Garden of Stalvan i utkanten av Darkshire. Denna stillsamma växt har kraftfulla egenskaper som eftertraktas av utövare av mörk magi långt borta i tunnlarna under Stormwind.",al={"vad är tear of tilloa","tear of tilloa-blomma","tear of tilloa"}},d8c5f010={q="Var kommer Tear of Tilloa ifrån?",a="Blomman växer naturligt i den igenvuxna Garden of Stalvan, strax utanför Darkshires skydd i Duskwoods skuggiga skog. Ingen dödlig hantverkare skapade den. Den blommar helt enkelt ostört på ägorna till det forna hemmet för familjen Mistmantle, där tragedin en gång slog till.",al={"var kommer tear of tilloa ifrån","vem skapade tear of tilloa","tear of tilloas ursprung"}}},fp="14,135,21.284.0,27.398.1,35.115.0,29.124.0,28.155.1,20.162.0"}
P.entries["item:techbot-s-memory-core"] = {n="Techbot's Memory Core",s="Techbot's Memory Core är det polariserade centrala lagret i Tinkmaster Oversparks mekaniska assistent Techbot. Den återfanns i den felande automaten, djupt inne i det fördärvade Gnomeregan, och innehåller viktiga data som Overspark hoppas kunna använda för att häva maskinens omvända negatroniska beteende.",h="Techbot's Memory Core är det polariserade centrala lagret i Tinkmaster Oversparks mekaniska assistent Techbot.",kw={"hjärna","gnomeregan","minneskärna","negatronisk","overspark","positronisk","techbot","tinker town"},ang={["profession:Engineering"]="Ingenjörer kan uppskatta de märkliga riskerna med positronisk polarisering, där en enda elektrisk kortslutning kan vända en automats logikrutiner helt.",["race:Gnome"]="För gnomerna är Techbot ännu ett tragiskt offer för Gnomeregans fall och en symbol för hur lysande ingenjörskonst från fredstid gått förlorad i kaos och ruiner."},sec={{t="En polariserad hjärna",b="Innan katastrofen tvingade gnomerna i exil tjänade Techbot Tinkmaster Overspark och hans uppfinnarkollegor som en oumbärlig assistent, fullpackad med manicker och encyklopediska kunskaper. När Gnomeregan föll träffades automaten av en elektrisk urladdning, som vände dess positroniska hjärna till ett fientligt negatroniskt tillstånd. Galen av omkastningen vandrar Techbot nu genom stadens förgiftade salar och anfaller alla som kommer i sikte. Att återfå minneskärnan är Oversparks enda hopp om att analysera felet och återställa hans älskade skapelse till sina sinnens fulla bruk."}},faq={{q="Vad är Techbot's Memory Core?",a="Det är Techbots främsta datalager och beräkningscentral. Techbot är en automat byggd av Tinkmaster Overspark. Kärnan innehåller maskinens kunskap och registrerar den elektriska störning som förvred dess beteende när Gnomeregan föll.",al={"techbots minneskärna","techbots hjärnpryl","vad är techbots kärna"}},{q="Vem vill ha Techbot's Memory Core?",a="Tinkmaster Overspark söker efter kärnan. Han har tagit sin tillflykt till Tinker Town i Ironforge tillsammans med andra gnomer i exil. Där ber han modiga äventyrare att bege sig till Gnomeregan, oskadliggöra Techbot och ta med kärnan tillbaka så att han kan försöka reparera den.",al={"vem behöver techbots minneskärna","vem lämnar in techbots kärna","var lämnar jag techbots kärna"}},{q="Varför blev Techbot våldsam?",a="När Gnomeregan föll träffades Techbots positroniska hjärna av en elektrisk gnista. Den plötsliga strömstöten polariserade mekanismen och gjorde den negatronisk. Automatens personlighet och protokoll vändes helt från hjälpsamma till våldsamt ursinniga.",al={"varför är techbot fientlig","vad hände med techbot","techbot har blivit galen"}},{q="Var får man tag på kärnan?",a="Kärnan tas från Techbot själv, som strövar omkring i de övre mekaniska korridorerna och entréerna till den fallna staden Gnomeregan i Dun Morogh.",al={"var får man techbots minneskärna","techbots plats","hur får man tag på techbots hjärna"}}},fx={a503508b={q="Var kommer Techbot's Memory Core ifrån, och vem skapade den?",a="Minneskärnan kommer från Techbot, en avancerad mekanisk konstruktion som Tinkmaster Overspark byggde i Gnomeregan. Overspark utformade maskinen för att hjälpa honom och hans uppfinnarkollegor med ett outsinligt förråd av data och mojänger. När Gnomeregan föll för troggarna träffades Techbot dock av en okontrollerad elektrisk stöt. Den polariserade dess positroniska hjärna till ett negatroniskt tillstånd och drev maskinen till vansinne.",al={"vem skapade techbot's memory core","techbots ursprung","vem byggde techbot"}}},fp="21,108,17.433.0,30.204.0,32.231.0,27.207.0,27.116.0"}
P.entries["item:telescopic-lens"] = {n="Telescopic Lens",s="Gazlowe behöver Telescopic Lens för att färdigställa observatorieteleskopet ovanför Ratchets hamn. Southsea-pirater tog den från ett skepp, och linsen finns kvar i deras läger söder om staden.",h="Gazlowe behöver Telescopic Lens för att färdigställa observatorieteleskopet ovanför Ratchets hamn.",kw={"låda","gazlowe","observatorium","ratchet","southsea freebooters","stulet byte","telescopic lens"},ang={["profession:Engineering"]="Som ingenjör kan du se det fina optiska hantverket i den här linsen. Den behövs för att fokusera observationsmekanismer på långt håll utan sfärisk aberration.",["race:Gnome"]="Som gnom kanske du hånler åt goblinernas raketteknik, men Gazlowes hängivenhet åt optisk astronomi visar att gobliningenjörskonst inte bara handlar om sprängämnen."},sec={{t="Blick mot himlen",b="Ratchet är främst känt för hänsynslös handel, men dess förvaltare och chefsingenjör, Gazlowe, har större mekaniska ambitioner. Hans observatorium reser sig ovanför hamnen och rymmer ett teleskop för att hålla uppsikt över sjötrafiken och stjärnorna. Den större linsen kom säkert landvägen från Durotar. Den mindre, oumbärliga linsen färdades till sjöss, där Southsea Freebooters jagar handelsskepp utanför The Barrens kust."},{t="Piratbyte",b="Southsea Freebooters tog allt av värde när de plundrade transportfartyget, inklusive den ömtåliga optiken. Piraterna kan ha lämnat linsen bland bråten i sitt strandläger söder om Ratchet eftersom de inte kunde uppskatta dess hantverk eller inte visste hur de skulle sälja den vidare. Gazlowe behöver få tillbaka det felfria glaset så att observationsdäcket kan ställas in i fokus."}},faq={{q="Varför behöver Gazlowe linsen?",a="Gazlowe behöver Telescopic Lens för att färdigställa teleskopet i Ratchets observatorium. Den större linsen kom landvägen från Durotar, men den mindre linsen gick förlorad till havs.",al={"gazlowes lins","vad linsen används till","varför teleskoplins"}},{q="Vem stal Telescopic Lens?",a="Southsea Freebooters stal Telescopic Lens. De är opportunistiska pirater, både människor och gastar, som jagar handelsskepp nära The Merchant Coast, och de förvarar linsen i en märkt låda i sitt kustläger söder om Ratchet.",al={"vem tog linsen","vem har linsen","telescopic lens plats"}},{q="Var kom linsen ursprungligen ifrån?",a="Telescopic Lens skeppades till Ratchet, medan dess motsvarighet kom landvägen från Durotar. Leveranser till hamnen kommer ofta från andra sidan Great Sea eller från sydliga goblinbosättningar som Booty Bay.",al={"var linsen tillverkades","linsens ursprung","var gazlowe beställde linsen"}},{q="Är linsen oskadd trots att den stals?",a="Mirakulöst nog klarade sig linsen oskadd. En låda märkt ”Ömtåligt – tappa inte” skyddade precisionsglaset från piraternas hårdhänta hantering.",al={"är linsen trasig","låda märkt ömtåligt tappa inte"}}},fx={ddcd39c0={q="Vad är Telescopic Lens?",a="Det är en precisionsslipad optisk lins avsedd för ett observatorieteleskop. Gazlowe beställde två speciallinser till teleskopet på toppen av sitt torn i Ratchet. Denna mindre sekundära lins skeppades över havet innan Southsea Freebooters lade beslag på den.",al={"vad är telescopic lens","föremålet telescopic lens","vad är den här linsen"}}},fp="15,183,15.397.0,14.379.0,32.170.0,30.228.0,40.219.0,43.150.0"}
P.entries["item:teronis-journal"] = {n="Teronis' Journal",s="Teronis' Journal är en fältanteckningsbok som återfanns bland kvarlevorna efter en Night Elf-spejare i Ashenvale. Den hittades intill den dödade utredaren och dokumenterar hans sökande efter en mystisk ädelsten. Den utgör viktig bevisning för Sentinels i Astranaar.",h="Teronis' Journal är en fältanteckningsbok som återfanns bland kvarlevorna efter en Night Elf-spejare i...",kw={"ashenvale","astranaar","glowing gem","raene wolfrunner","raenes rening","sentinels","teronis","teronis' journal"},ang={["faction:Alliance"]="Om du tar med Teronis' fältanteckningar tillbaka till Astranaar kan garnisonen samordna hjälp och återfinna sin fallne spejares kvarlevor.",["race:NightElf"]="Dagboken vittnar om de farofyllda uppgifter som Night Elf-spejare tar på sig när de försöker skydda Ashenvales urgamla skogar från en annalkande korruption."},sec={{t="En spejares sista anteckningar",b="Teronis, en gammal vän till Raene Wolfrunner som hjälpte Sentinels, gav sig ut i Ashenvales vildmark för att söka efter en ädelsten till en stav. Han trodde att staven kunde hejda furbolgarnas attacker mot hans folk. Uppdraget fick ett abrupt slut när han föll i fält, omringad av aggressiva varelser nära stranden. Dagboken återfanns bland hans personliga tillhörigheter och är i förvånansvärt gott skick trots hans våldsamma död. Den redogör för hans fynd om en strålande ädelsten som en gång var en del av staven. Astranaars försvarare får därmed det viktiga spår de behöver för att slutföra hans oavslutade uppdrag."}},faq={{q="Vem tillhörde dagboken?",a="Dagboken tillhörde Teronis, en Night Elf och vän till Raene Wolfrunner i Astranaar. Han sökte i Ashenvale efter ett sätt att hejda furbolgarnas attacker. Han dödades i vildmarken innan han hann återvända med sina fynd.",al={"vem skrev dagboken","vem är teronis","teronis bakgrund"}},{q="Var hittar man dagboken?",a="Dagboken får du genom att leta igenom Teronis' tillhörigheter efter att ha hittat hans döda kropp i Ashenvales vildmark, nära stränderna där traktens murlocs håller till.",al={"var hittar man dagboken","teronis dagboks plats","hur får man tag på dagboken"}},{q="Varför ska man ta med dagboken till Astranaar?",a="När du återlämnar dagboken till Raene Wolfrunner får Astranaar veta att Teronis har dött. Sentinels får också anteckningarna de behöver för att fortsätta hans sökande efter staven som han hoppades skulle hejda furbolgarnas attacker.",al={"varför lämna dagboken till raene","vem ska jag ge dagboken till","lämna in dagboken"}},{q="Vilket föremål letade Teronis efter under sitt uppdrag?",a="Teronis sökte efter en glödande ädelsten, en av delarna till en stav som den döde magikern Dartol hade tillverkat. Hans undersökning tydde på att murlocs i närheten kan ha rotat åt sig föremålet.",al={"vad jagade teronis","vilken ädelsten sökte han efter","teronis ädelsten"}}},fx={["5fb93f8f"]={q="Vad är Teronis' Journal?",a="Teronis' Journal är en personlig anteckningsbok som tillhörde nattalvsspejaren Teronis. Den hittades bland hans tillhörigheter intill hans kropp i Ashenvale. Den beskriver hans uppdrag och de första spaningsinsatserna kring en märklig ädelsten som han skickades för att hitta innan han mötte sin för tidiga död.",al={"vad är teronis' journal","föremålet teronis' journal","om teronis' journal"}}},fp="16,120,22.472.0,31.224.0,27.149.0,57.185.0,59.156.0"}
P.entries["item:tharil-zun-s-head"] = {n="Tharil'zun's Head",s="Den här makabra trofén är det avhuggna huvudet från Tharil'zun, ledaren för Blackrock-orchernas Outrunners som ockuperar Stonewatch. Marshal Marris kräver det som obestridligt bevis på att befälhavaren som terroriserat Redridges tillfartsvägar har dödats.",h="Den här makabra trofén är det avhuggna huvudet från Tharil'zun, ledaren för Blackrock-orchernas Outrunners...",kw={"blackrock outrunners","lakeshire","marshal marris","stonewatch","stonewatch keep","tharil'zun","tharil'zun's head"},ang={["faction:Alliance"]="Varje dödad Blackrock-hövding lättar trycket på den hårt ansatta staden Lakeshire, som kämpar för sin överlevnad utan officiella förstärkningar från Stormwind."},sec={{t="Stonewatchs trofé",b="Blackrock-orcherna som slagit sig ner i Stonewatch Keep har utsatt Lakeshire för skoningslöst tryck genom att plundra gårdar och överfalla resande längs vägarna. I spetsen för dessa plundringståg stod Blackrock Outrunners, som leddes av Tharil'zun. Eftersom garnisonen i Lakeshire inte har råd att agera på rykten eller halva segrar kräver Marshal Marris konkreta bevis på ledarens död. Att föra honom Tharil'zuns avhuggna huvud visar att de samordnade bakhållen från borgen har fått ett hårt slag."}},faq={{q="Vem var Tharil'zun?",a="Tharil'zun var en slug och våldsam Blackrock-orkbefälhavare stationerad i Stonewatch Keep. Han ledde Blackrock Outrunners, som genomförde ihärdiga bakhåll tillsammans med Renegades mellan Lakeshire och borgen.",al={"tharil'zuns bakgrund","vem är tharil'zun","tharil'zuns ledare"}},{q="Varför vill Marshal Marris ha hans huvud?",a="Eftersom Stormwind håller inne med större militär hjälp till Redridge förlitar sig Marshal Marris och Lakeshires vakter på legosoldater för att slå ut viktiga hot. Marris kräver obestridliga bevis på Tharil'zuns död för att försäkra sig om att Outrunners ledning verkligen är krossad.",al={"varför tharil'zuns huvud","marris bevis huvud","marris belöning"}},{q="Var finns Tharil'zun?",a="Tharil'zun håller Stonewatch Keep i de östra kullarna i Redridge Mountains, omgiven av Blackrock-orcher och gnoller.",al={"tharil'zuns plats","var finns tharil'zun","hitta tharil'zun"}},{q="Tar hotet från Blackrock slut när Tharil'zuns huvud tas?",a="Nej. Att döda Tharil'zun stör visserligen Outrunners bakhåll, men Blackrock-klanen har fortfarande en stor förskansad styrka i Stonewatch Keep och över hela Redridge Mountains.",al={"har orcherna försvunnit","räddade vi redridge","efter tharil'zun"}}},fx={a015b31b={q="Vad är Tharil'zun's Head?",a="Det här avhuggna huvudet är ett fysiskt bevis på att Tharil'zun, befälhavaren bakom svartklippiga orkers bakhåll kring Stonewatch Keep, har dödats. När det förs tillbaka till Lakeshire visar det stadens hårt ansatta vakter att en av svartklippaklanens farligaste fältledare i Redridge Mountains inte längre kommer att terrorisera vägarna.",al={"föremålet tharil'zun's head","historien om tharil'zuns huvud"}},f673cecf={q="Var kommer Tharil'zun's Head ifrån?",a="Det tas direkt från liket efter Tharil'zun, en framstående svartklippig orkledare som utgår från ruinerna av Stonewatch Keep. När han stupar i strid mot dig eller Lakeshires försvarare tas huvudet som ett obestridligt trofé och ett bistert bevis på hans död.",al={"vem tog tharil'zun's head","tharil'zuns huvuds ursprung","varifrån kom tharil'zuns huvud"}}},fp="17,162,20.425.0,19.188.0,38.256.0,26.111.0,55.167.0"}
P.entries["item:tharnariun-s-hope"] = {n="Tharnariun's Hope",s="Tharnariun's Hope är en specialfälla som nattalven Tharnariun Treetender tillverkat i Darkshore. Den är utformad för att lugna sjuka vilda djur i stället för att skada dem och sprider ett rogivande ljus som ska tämja rabiata tisteltaggarbjörnar, så att de kan undersökas i jakten på ett botemedel.",h="Tharnariun's Hope är en specialfälla som nattalven Tharnariun Treetender tillverkat i Darkshore.",kw={"darkshore","plågade länder","rabiat tisteltaggarbjörn","tharnariun","tharnariun's hope","tisteltaggarbjörn","fälla"},ang={["class:Druid"]="Fällan förkroppsligar Cenarion-idealet att bevara i stället för att utrota. Den visar en ovilja att slå ner korrumperade bestar så länge det finns en chans att rädda dem.",["race:NightElf"]="Förfallet hos Darkshores älskade tisteltaggarbjörnar slår mot kärnan i kaldoreiernas band till naturen och gör fällan till en gripande symbol för desperat medkänsla."},sec={{t="En mild snara",b="En mystisk åkomma sprider sig genom Darkshore, och områdets tisteltaggarbjörnar har blivit alltmer ursinniga och våldsamma. I stället för att beordra att de sjuka djuren ska avlivas tillverkade druiden Tharnariun Treetender den här unika fällan i hopp om att kunna studera och bota sjukdomen. När den läggs på marken avger Tharnariun's Hope ett lugnande sken. En rabiat tisteltaggarbjörn som kliver in i fällans ljus blir tillfälligt av med sitt raseri och så tam att en äventyrare kan leda den tillbaka till Tharnariuns läger för behandling."},{t="Det svårfunna botemedlet",b="Fällan lyckas kuva de ursinniga djuren utan att utgjuta blod, men den underliggande korruptionen visar sig vara mycket våldsammare än väntat. När Tharnariun kanaliserar sin läkande magi in i den fångade björnen kolliderar den återställande kraften våldsamt med den virulenta infektionen, så att det sjuka djuret faller ihop och dör. Trots att hans första försök slutar i hjärtesorg hävdar Tharnariun att hans beslutsamhet inte ska svikta förrän skogens sjukdom har avslöjats."}},faq={{q="Vad gör Tharnariun's Hope?",a="Det är en förtrollad markfälla som är utformad för att lugna en rabiat tisteltaggarbjörn. När den placeras på skogsmarken skapas ett ljusfält som tillfälligt lugnar en björn som går in i det, så att den lugnt kan ledas tillbaka till Tharnariun Treetender.",al={"använda tharnariun's hope","hur fungerar fällan","vad är det här för fälla"}},{q="Varför vill Tharnariun fånga en levande björn?",a="Tharnariun tror att sjukdomen som drabbat Darkshores vilda djur kan botas i stället för att bekämpas genom slakt. Han behöver ett levande försöksdjur för att pröva sina renande kurer direkt.",al={"varför fånga tisteltaggarbjörn","varför fånga en rabiat björn","vad vill tharnariun"}},{q="Kan du få en ny fälla om du tappar bort den?",a="Ja. Tharnariun försäkrar resenärer om att hans hopp är evigt. Om en fälla utlöses i onödan eller försvinner i vildmarken får du en ny av honom när du återvänder, så att du kan slutföra uppdraget.",al={"tappat bort tharnariun's hope","misslyckad fälla","fällan försvunnen"}},{q="Vad händer med björnen när den förs tillbaka?",a="När björnen anländer kastar Tharnariun en läkande förtrollning för att driva ut korruptionen. Den vidriga sjukdomen har tyvärr fått för djupt fäste. Magin överväldigar besten, som dör inom några ögonblick.",al={"överlever björnen","kan tharnariun bota björnen","björnen dör hos tharnariun"}}},fx={["820181a1"]={q="Vad är Tharnariun's Hope?",a="Tharnariun's Hope är en förtrollad snara som Tharnariun Treetender har utformat. När den läggs på marken utstrålar den ett lugnande sken som tillfälligt kan stilla de drabbade, rabiata tistlebjörnarna som strövar omkring i Darkshore. Den rogivande förtrollningen gör ett rasande odjur milt och villigt att följa med dig tillbaka till Auberdine.",al={"vad är tharnariun's hope","föremålet tharnariun's hope","tharnariuns fälla"}},["88ba9e19"]={q="Var kommer Tharnariun's Hope ifrån, och vem skapade den?",a="Fällan tillverkades och förtrollades av Tharnariun Treetender, en nattalvsnaturkännare som är stationerad i Darkshore. Förfärad över den mystiska sjukdom som driver skogens djur till vansinne skapade han den här anordningen med mild magi för att kuva smittade bestar utan att skada dem ytterligare.",al={"vem skapade tharnariun's hope","tharnariun's hopes ursprung","vem skapade tharnariuns fälla"}},c80e933b={q="Varför vill någon ha Tharnariun's Hope?",a="Tharnariun behöver att fällan används för att fånga en levande, rabiat tistlebjörn så att han kan studera fördärvet som härjar i Darkshore. Vanlig jakt skulle bara döda besten, men den här snarans lugnande verkan håller djuret stilla tillräckligt länge för att du ska kunna leda det säkert till Tharnariun, i hopp om att hitta ett botemedel.",al={"varför använda tharnariun's hope","varför behövs tharnariuns fälla","syftet med tharnariun's hope"}}},fp="17,155,14.418.0,18.410.1,31.184.0,46.170.0,40.122.0,49.144.1"}
P.entries["item:the-book-of-ur"] = {n="The Book of Ur",s="The Book of Ur är en lärd magisk avhandling, författad av den avlidne Dalaran-magikern Ur. Den beskriver hans forskning om märkliga varelser från andra dimensioner. Den lämnades kvar i Shadowfang Keep och hamnade i Archmage Arugals händer, innan Forsaken-forskare i Undercity började intressera sig för den.",h="The Book of Ur är en lärd magisk avhandling, författad av den avlidne Dalaran-magikern Ur.",kw={"apothecarium","arugal","the book of ur","dalaran","keeper bel'dugur","shadowfang keep","silverpine","ur"},ang={["class:Mage"]="Urs skrifter påminner om Dalarans lärdomars räckvidd i andra världar och om de dödliga följderna när ambitiösa magiker som Arugal missbrukar den förbjudna kunskapen.",["race:Undead"]="Att säkra Urs verk hjälper direkt den Mörka damens lärda i Apothecarium. Den försiktige mänsklige magikerns forskning blir därmed till praktisk makt för Forsaken."},sec={{t="Magikern från Dalaran",b="Innan Dalaran föll för Scourge var Ur känd bland Kirin Tor för sina esoteriska undersökningar av andra existensplan och utomvärldsliga varelser. Trots sin fascination för magi från andra plan lät sig Ur vägledas av försiktighet och etisk återhållsamhet. Han valde att dokumentera sina upptäckter i stället för att vårdslöst bryta igenom slöjan mellan världarna. När Scourge angrep den violetta staden räckte hans magiska skicklighet och moraliska tvekan tragiskt nog inte för att rädda honom."},{t="Forsakens ambitioner",b="Efter Urs död hamnade hans skrifter hos Archmage Arugal, som använde forskningen för att kalla monstruösa worgen till Silverpine Forest. Boken står nu i Shadowfang Keeps bokhyllor. Ryktet om att den fanns fångade Keeper Bel'dugurs intresse i Undercitys Apothecarium. Till skillnad från sin ursprunglige författare tvekar Forsaken inte inför att använda farlig, obehindrad magi för att säkra sin överlevnad och erövring."}},faq={{q="Vem var Ur?",a="Ur var en framstående mänsklig magiker från Dalaran före det tredje kriget. Han forskade ingående om andra dimensioner och varelser från andra plan, men vägrade att kalla på dem eftersom de utgjorde en enorm fara.",al={"vem skrev the book of ur","ur magiker från dalaran"}},{q="Var finns The Book of Ur?",a="Boken står på en hylla inne i Shadowfang Keep i Silverpine Forest, närmare bestämt i kammaren där det väldiga odjuret Fenrus håller till.",al={"the book of ur plats","var finns the book of ur"}},{q="Varför vill Keeper Bel'dugur ha boken?",a="Keeper Bel'dugur samlar in Urs skrifter åt intresserade i Undercity. Forsaken anser att Urs moraliska samvete hindrade honom från att nå verklig makt. De vill använda hans forskning om andra plan utan etiska begränsningar för att stärka sin egen makt.",al={"keeper bel'dugur the book of ur","varför vill undercity ha boken"}},{q="Hur hamnade boken i Shadowfang Keep?",a="Efter att Ur dött när Dalaran föll fick Archmage Arugal tag på hans forskning. I sin desperation att försvara sig mot Scourge förde Arugal anteckningarna till Silverpine Forest och använde Urs teorier om frammaning för att locka worgen till Azeroth.",al={"arugal och the book of ur","hur fick arugal tag på boken"}}},fx={["62a01830"]={q="Vad är The Book of Ur?",a="The Book of Ur är en lärd skrift med den esoteriska forskningen från Ur, en framstående magiker från Dalaran. Den beskriver hans omfattande studier av andra världar och farliga mystiska fenomen. Kunskapen var så kraftfull att ärkemagikern Arugal senare använde Urs skrifter för att kalla fram de monstruösa varulvarna i Silverpine Forest.",al={"vad är the book of ur","historien om the book of ur"}},["905bb2c4"]={q="Var kommer The Book of Ur ifrån, och vem skrev den?",a="Boken skrevs i det magiska kungariket Dalaran av magikern Ur innan staden förstördes av Scourge. Ur dokumenterade sina mystiska teorier och utforskningar av andra dimensioner, men arbetet övergavs efter hans död under Dalarans fall.",al={"vem skrev the book of ur","the book of urs ursprung","varifrån kom the book of ur"}}},fp="14,195,19.393.0,17.356.1,11.166.0,32.128.0,40.215.0,43.216.0"}
P.entries["item:the-collector-s-schedule"] = {n="The Collector's Schedule",s="Nära Brackwell Pumpkin Patch anger The Collector's Schedule när olovliga guldsändningar passerar genom Elwynn Forest. Gnoller bär den handskrivna resplanen, och Marshal Dughan känner igen namnet som står där.",h="Nära Brackwell Pumpkin Patch anger The Collector's Schedule när olovliga guldsändningar passerar genom Elwynn...",kw={"brackwell","the collector","dughan","elwynn","guld","goldshire","gruvor","schema"},ang={["faction:Alliance"]="Som medlem i Alliansen kan du se hur liten kontroll Stormwind har över sitt eget territorium när obehöriga arbetslag tar dess resurser nära huvudstaden.",["profession:Mining"]="Som gruvarbetare kan du se att Elwynns gruvor inte ligger öde: rika guldfyndigheter bryts och fraktas bort."},sec={{t="Stulet guld och hemliga sändningar",b="The Collector's Schedule anger datum och tider för guldsändningar från Elwynns gruvor. Stormwind har inte bedrivit officiell gruvdrift där på flera månader, efter att ha drivits bort av banditer och varelser som trängt in i området, men malm förs fortfarande bort i ett ordnat flöde. Resplanen anger vilka dagar och tider en person som kallas The Collector tar emot varje sändning. Spåren leder till ett läger nära Brackwell Pumpkin Patch i östra Elwynn Forest. När Marshal Dughan ser schemat känner han igen namnet på The Collector. Vem som betalar för det stulna guldet är fortfarande okänt."}},faq={{q="Vad är The Collector's Schedule?",a="The Collector's Schedule anger när guldsändningar lämnar Elwynn Forests övergivna gruvor för en agent som kallas The Collector.",al={"vad är den här anteckningen","föremålet the collector's schedule","guldplan"}},{q="Varifrån kommer schemat?",a="Gnoller bär schemat längs Elwynn Forests flodbankar och sluttningar. De kan ha tagit det från en kurir eller vara inblandade i att transportera guldet.",al={"vem släpper schemat","var hittar man schemat"}},{q="Vem är The Collector?",a="The Collector är en agent stationerad nära Brackwell Pumpkin Patch i östra Elwynn Forest. Marshal Dughan känner igen namnet men vet inte vem agenten tjänar.",al={"vem är the collector","the collectors identitet"}},{q="Varför oroar sig Marshal Dughan över schemat?",a="Marshal Dughan oroar sig eftersom Stormwind inte har haft några officiella gruvarbetare i Elwynns gruvor på flera månader, men betydande guldsändningar lämnar dem fortfarande. Det tyder på en organiserad, olaglig gruvverksamhet inom kungariket.",al={"varför bryr sig dughan","guld i elwynns gruvor"}}},fp="24,216,32.467.0,33.129.0,33.150.0,21.170.0,47.231.0"}
P.entries["item:the-embalmer-s-heart"] = {n="The Embalmer's Heart",s="The Embalmer's Heart är en ohelig relik som bultar i Elizas odöda kropp, djupt begravd i Duskwood. Den tillhörde en gång en sorgtyngd alkemist känd som the Embalmer. Genom mörk magi transplanterade han hjärtat för att återuppliva sin avlidna hustru, och det blev källan till hans förvridna kraft.",h="The Embalmer's Heart är en ohelig relik som bultar i Elizas odöda kropp, djupt begravd i Duskwood.",kw={"the embalmers brud","darkshire","duskwood","eliza","ello ebonlocke","embalmer's heart","the embalmer"},ang={["class:Warlock"]="Att transplantera ett fortfarande bultande, själsbundet organ som ankare för nekromantisk odödlighet är en djärv, om än kaotisk, bedrift inom köttkonst och själsmanipulation.",["race:Human"]="Den vänlige alkemistens tragiska fall är en mörk varning som viskas bland Duskwoods hårt prövade invånare."},sec={{t="En kärlek som trotsade döden",b="Enligt Darkshires folklore var the Embalmer en gång en mild alkemist vars sinne brast när hans älskade hustru Eliza dog. Desperat att återta henne från graven tog han sin tillflykt till vidrig trolldom och skar ut sitt eget hjärta. Han placerade det i Elizas livlösa bröst. Den oheliga överföringen väckte hennes lik till odödlighet, men uppståndelsen förvandlade henne till ett glupskt monster med en omättlig hunger efter levande människokött. Den skräckslagne alkemisten tvingades begrava henne på nytt."},{t="En sköld för Darkshire",b="Trots att hjärtat slets ur hans bröst är det fortfarande källan till the Embalmer's bestående mörka kraft, och det fortsätter att slå i Elizas grav. Borgmästare Ello Ebonlocke inser att det enda sättet att beröva the Embalmer hans trolldom är att krossa den återupplivade bruden och ta hjärtat. Genom att säkra hjärtat medan det fortfarande slår hoppas Darkshires ledare vända nekromantikerns egen ondskefulla magi mot honom och använda dess kraft som skydd mot hans fasor."}},faq={{q="Varför har Eliza the Embalmer's hjärta?",a="The Embalmer, förkrossad av sin hustru Elizas död, använde förbjuden magi för att placera sitt eget bultande hjärta i hennes lik och återuppliva henne. Ritualen väckte henne till liv, men förbannade henne med en omättlig hunger efter människokött.",al={"varför har eliza hjärtat","embalmer-hjärtat i eliza","vem satte hjärtat i eliza"}},{q="Varför vill borgmästare Ebonlocke att hjärtat förs tillbaka till Darkshire?",a="Borgmästare Ello Ebonlocke tänker använda den mörka magi som fortfarande genljuder i det bultande hjärtat för att skapa ett skyddande värn över Darkshire. På så sätt kan han neutralisera the Embalmer's kraft och göra den till ett skydd för staden.",al={"varför vill ello ha hjärtat","ebonlockes plan för hjärtat","vad gör darkshire med hjärtat"}},{q="Hur överlever the Embalmer utan sitt hjärta?",a="Med hjälp av den mörka trolldom han utövade band the Embalmer sin livskraft och makt direkt till det transplanterade hjärtat. Därför kan han bestå trots att organet slår i hans hustrus begravda kvarlevor.",al={"lever the embalmer","hur lever embalmer utan hjärta"}},{q="Var finns hjärtat?",a="Hjärtat finns i Eliza, som fortfarande ligger begravd på en undangömd gravplats i Duskwood. Det går bara att ta genom att möta och besegra den glupska, återupplivade bruden.",al={"var finns embalmer-hjärtat","var ligger elizas grav","hur får man embalmer-hjärtat"}}},fx={cac9cdef={q="Vad är The Embalmer's Heart?",a="Det är den upproriske alkemisten som kallas Embalmerns verkliga, magiskt vidmakthållna, bultande hjärta. Förblindad av sorgen över sin hustru Elizas död skar han ut sitt eget hjärta och lade det i hennes lik för att återuppliva henne. Även när hjärtat är skilt från hans bröst fungerar det som kärlet och kanalen för hans nekromantiska kraft. Det upprätthåller både Elizas förbannade odöda tillstånd och hans egen oheliga livskraft.",al={"vad är the embalmer's heart","historien om embalmers hjärta","the embalmer's heart"}}},fp="20,176,24.408.0,22.361.1,41.173.0,66.113.0,48.156.0,29.167.0"}
P.entries["item:the-general-s-response"] = {n="The General's Response",s="General Marcus Jonathan skickar besked till Lakeshire medan Redridge väntar på hjälp. Hans skrivelse bekräftar att han tagit emot Magistrate Solomons vädjan om hjälp mot Blackrock-orcherna och gnollerna, men erbjuder inga omedelbara förstärkningar från Stormwind.",h="General Marcus Jonathan skickar besked till Lakeshire medan Redridge väntar på hjälp.",kw={"general marcus jonathan","lakeshire","magistrate solomon","budbärare till stormwind","redridge","stormwind","generalens svar"},ang={["faction:Alliance"]="Stormwinds svar visar påfrestningarna inom Grand Alliance. Lakeshire blöder medan hovet verkar märkligt ointresserat av dess svåra situation.",["race:Human"]="För människor i de södra rikena visar det försenade svaret den växande sprickan mellan folket i provinserna, som kämpar för sin överlevnad, och den avskilda adeln i Stormwind Keep."},sec={{t="En diplomatisk låsning",b="Magistrate Solomon skickar en brådskande vädjan till Stormwind City om trupper som kan försvara Redridge mot de samlande Blackrock-orchstammarna och gnollernas krigarskaror. General Marcus Jonathan svarar att vädjan har vidarebefordrats till tronen, men att inga soldater skickas just nu. Han beordrar att brevet skickas tillbaka till Lakeshire. Solomon oroar sig över Stormwinds dröjsmål och misstänker att något är fel bland dess ledare."}},faq={{q="Vad står det i The General's Response?",a="General Marcus Jonathan sörjer de döda och säger att han ska göra kungen uppmärksam på Lakeshires svåra situation. Han hoppas kunna ta dit förstärkningar och anförtro sig åt Solomon om att Hans Majestät har varit svår att få tag på och betett sig märkligt.",al={"brevets innehåll","vad står det i brevet","generalens brev"}},{q="Varför kan General Marcus Jonathan inte skicka trupper till Lakeshire?",a="General Jonathan inväntar kungens svar innan han lovar förstärkningar. I förtroende berättar han för Solomon att Hans Majestät har varit svår att få tag på och betett sig märkligt.",al={"varför inga förstärkningar","varför hjälper stormwind inte lakeshire","varför ingen hjälp"}},{q="Hur reagerar Magistrate Solomon på brevet?",a="Magistrate Solomon blir djupt skakad av skrivelsen. Stormwinds långsamhet är obegriplig för honom när Lakeshire står inför en sådan fara, och han fruktar att försummelsen tyder på ännu värre problem i kungariket.",al={"solomons reaktion","vad tycker solomon","solomons svar"}}},fx={["3ebc4cbb"]={q="Vad är The General's Response?",a="Det är ett officiellt, förseglat brev skrivet av General Marcus Jonathan, befälhavare för Stormwind Citys garde, och adresserat till Magistrate Solomon i Redridge. Budbärare för brevet mellan huvudstaden och Lakeshire. Det innehåller överkommandots formella svar på Redridges desperata vädjan om kungliga förstärkningar.",al={"vad är the general's response","föremålet the general's response","vad är det här brevet"}},["174955dc"]={q="Var kommer The General's Response ifrån, och vem skrev den?",a="Brevet skrevs direkt av General Marcus Jonathan i Stormwind City. Efter att ha tagit emot Magistrate Solomons brådskande vädjan vid Valley of Heroes skriver Jonathan detta formella svar medan han väntar på besked från det kungliga hovet. Han anförtror dig uppgiften att ta tillbaka det till magistraten i Lakeshire.",al={"vem skrev the general's response","varifrån kom the general's response","vem skickade the general's response"}},d0ef00e9={q="Varför vill någon ha The General's Response?",a="Magistrate Solomon väntar otåligt på brevet för att få veta om Stormwind tänker skicka soldater för att rädda Lakeshire från svartklippiga orker och gnoller. När du levererar det får den hårt ansatta stadens ledning ett tydligt besked om vilken hjälp kungariket kan eller inte kan erbjuda.",al={"varför vill solomon ha brevet","vem vill ha the general's response","varför leverera the general's response"}}},fp="22,235,21.365.0,42.193.0,59.176.0,48.190.0"}
P.entries["item:the-lich-s-spellbook"] = {n="The Lich's Spellbook",s="The Lich's Spellbook är en volym med nekromantisk kunskap som förvaras i en kista på ön i Brightwater Lake. Bethor Iceshard i Undercity fick tag på boken, som avslöjar den tillbakadragne odöde lichens sanna identitet och enorma magiska kraft. Han bor strax norr om de Fördömdas huvudstad.",h="The Lich's Spellbook är en volym med nekromantisk kunskap som förvaras i en kista på ön i Brightwater Lake.",kw={"bethor iceshard","brightwater lake","gunther arcanus","lich","nekromanti","besvärjelsebok","tirisfal glades","undercity"},ang={["class:Mage"]="Besvärjelseboken utgör en sällsynt länk mellan Dalarans klassiska magi och mörk nekromanti. Den visar hur dödliga magiker utvecklade sina konster kraftigt efter att ha dukat under för odöden.",["race:Undead"]="Boken visar att alla som bröt sig fria från Lich King inte genast anslöt sig till de Fördömda. Den belyser den kvardröjande misstron bland förrymda odöda som överlevt och spritts över Tirisfal."},sec={{t="En tillbakadragen mästares böcker",b="På en isolerad ö i Brightwater Lake står en gåtfull lich omgiven av skelettväktare. Trots sin fria vilja misstror denne trollkarl omvärlden, tror att alla andra odöda är plågans trälbundna tjänare och befaller sina undersåtar att förgöra alla som närmar sig. Bethor Iceshard söker begåvade nekromantiker för att stärka de Fördömdas led under drottning Sylvanas Windrunner. Han gav ett sändebud i uppdrag att infiltrera lägret på ön och hämta lichens besvärjelsebok. Genom att studera den hoppades Bethor kunna bedöma mästarens magiska förmåga och ta reda på vem han var innan döden tog Lordaeron."},{t="Avslöjandet av Gunther Arcanus",b="När Bethor Iceshard öppnade de glödande sidorna i den återfunna besvärjelseboken gjorde han en häpnadsväckande upptäckt: den tillbakadragne var hans gamle vän och vapendragare från tiden före det tredje kriget, Gunther Arcanus. Gunthers skrifter visade att hans nekromantiska konster, som redan i livet varit enastående, hade blivit ännu mäktigare i odöden. Bethor insåg att Gunthers lojalitet skulle ge de Fördömda en ovärderlig mästare i mörka konster, om någon kunde övertyga den misstänksamme lichen om att de Fördömda verkligen är fria från Lich Kings grepp."}},faq={{q="Var hittar man The Lich's Spellbook?",a="Besvärjelseboken ligger i en behållare med namnet Gunther's Books, i lägret på den centrala ön i Brightwater Lake i norra Tirisfal Glades.",al={"var finns boken","besvärjelsebokens plats","gunther's books"}},{q="Vem äger den här besvärjelseboken?",a="Den tillhör lichen på ön i Brightwater Lake, som lever tillbakadraget och har fri vilja. Bethor Iceshard hoppas att en studie av bokens sidor ska avslöja ägarens identitet och förmågor.",al={"vems bok är det här","lichens identitet","vem skrev besvärjelseboken"}},{q="Varför vill Bethor Iceshard ha boken?",a="Bethor Iceshard sökte efter boken för att lista ut den mystiske lichens identitet och bedöma hans kunskaper i nekromanti. Han hoppades kunna rekrytera den tillbakadragne till Lady Sylvanas och de Fördömdas tjänst.",al={"varför hämta boken","bethors skäl för uppdraget","varför vill undercity ha den här"}},{q="Varför attackerar lichen besökare på sin ö?",a="Lichen tror att alla andra odöda i trakten fortfarande är viljelösa slavar under plågan. Förlamad av misstänksamhet befaller han sina undersåtar att angripa alla som närmar sig hans helgedom.",al={"varför är gunther fientlig","varför attackerar undersåtarna","fientlig vid brightwater lake"}},{q="Vad hoppas Bethor få veta om författaren?",a="Bethor hoppas få veta vem den isolerade lichen var i livet och om hans nekromantiska kunskaper kan hjälpa de Fördömda.",al={"vad får bethor veta","studie av lichens författarskap","bethors studie av besvärjelseboken"}}},fx={["44ee6981"]={q="Var kommer The Lich's Spellbook ifrån, och vem skrev den?",a="Besvärjelseboken tillhör den tillbakadragna, självständiga lich som bor på ön i Brightwater Lake. Han skrev och underhöll själv boken och fyllde dess lysande sidor med sina nekromantiska konster, både i livet och efter sin förvandling till en lich. Bethor Iceshard vill ha den för att ta reda på vem lichen var.",al={"vem skrev the lich's spellbook","the lich's spellbooks ursprung","varifrån kom the lich's spellbook"}}},fp="20,148,26.473.0,25.437.1,36.140.0,24.154.1,39.143.0,48.149.0,48.117.1"}
P.entries["item:the-state-of-lakeshire"] = {n="The State of Lakeshire",s="The State of Lakeshire är en brådskande skriftlig rapport från Magistrate Solomon, som beskriver den desperata militära kris som plågar Lakeshire. Den är direkt riktad till General Marcus Jonathan i Stormwind och vädjar till huvudstaden att skicka förstärkningar från kungens armé innan bosättningen i Redridge faller.",h="The State of Lakeshire är en brådskande skriftlig rapport från Magistrate Solomon, som beskriver den...",kw={"rapport","magistrate solomon","marcus jonathan","redridge","förstärkningar","lakeshires tillstånd","stormwind"},ang={["faction:Alliance"]="Rapporten visar hur sårbara rikets utposter är och hur politisk tröghet just nu fördröjer militär hjälp från huvudstaden.",["race:Human"]="För rikets människor understryker det att bära detta dokument de allt svagare banden mellan vanligt folk i Redridge och den avlägsna kronan i Stormwind."},sec={{t="Ett rop på hjälp",b="Magistrate Solomon skrev ”The State of Lakeshire” under de oupphörliga attackerna mot Redridge. Rapporten beskriver de svåra omständigheter som hotar samhället. Lakeshire är belägrat av fientliga Blackrock-orcher och gnoller och saknar lokal mansstyrka för att hålla gränserna hur länge som helst. Kurirer som färdas västerut mot Elwynn Forest har fått i uppdrag att bära med sig Solomons formella begäran om att Stormwind Army ska ingripa och bevara rikets östra gräns."},{t="Byråkrati och dödläge",b="När rapporten levereras till General Marcus Jonathan vid Stormwinds portar erkänner generalen Solomons höga ställning och rapportens allvar. Jonathan kan dock inte mobilisera armén på egen hand. Truppförflyttningar kräver kronans uttryckliga samtycke, så Lakeshires brådskande vädjan måste invänta rådslag på hög nivå med den unge kungen och regenten Bolvar Fordragon."}},faq={{q="Vad är The State of Lakeshire?",a="Det är en officiell skriftlig rapport av Magistrate Solomon, som beskriver den militära fara som hotar Lakeshire och ber Stormwind om truppförstärkningar.",al={"dokument om lakeshires tillstånd","vad är den här rapporten","solomons meddelande"}},{q="Vem ska ta emot rapporten?",a="Rapporten är direkt riktad till General Marcus Jonathan, befälhavare för Stormwinds stadsvakt och kungliga styrkor, som är stationerade vid Stormwinds portar.",al={"vem får rapporten","vem ska den levereras till","rapport till marcus jonathan"}},{q="Varför behöver Lakeshire förstärkningar från kungamakten?",a="Bosättningen är ständigt belägrad av Blackrock-orcher, Shadowhide-gnoller och lokala murlocer, vilket pressar stadsvakten bortom dess gränser.",al={"varför är lakeshire i fara","vad hotar redridge"}},{q="Skickar General Marcus Jonathan hjälp omedelbart?",a="Nej. Generalen håller med om att krisen är allvarlig, men han kan inte sätta in armén utan kungens formella godkännande. Därför måste begäran först granskas av kungamakten.",al={"hjälper stormwind","skickar jonathan trupper"}}},fx={["629511cc"]={q="Var kommer The State of Lakeshire ifrån, och vem skrev den?",a="Magistrate Solomon, Lakeshires ledare och domare, skrev denna viktiga rapport. Staden är utsatt för obevekliga angrepp från fientliga styrkor. Solomon skrev själv brevet för att formellt beskriva Redridges farliga läge och be Stormwinds överkommando om omedelbar militär hjälp.",al={"vem skrev the state of lakeshire","författaren till the state of lakeshire"}},["09d61feb"]={q="Varför behövs The State of Lakeshire så brådskande?",a="Lakeshire är under ständig belägring, och Magistrate Solomon vet att staden inte kan hålla stånd ensam utan kungliga förstärkningar. General Marcus Jonathan behöver den officiella redogörelsen för att motivera att delar av Stormwind-armén skickas ut och för att lägga fram Lakeshires desperata situation direkt inför kungen och Highlord Bolvar Fordragon.",al={"varför behövs the state of lakeshire","varför leverera the state of lakeshire","varför vill marcus jonathan ha the state of lakeshire"}}},fp="22,191,13.311.0,24.305.0,31.151.0,41.150.0,45.157.0,51.164.0"}
P.entries["item:theramore-medal"] = {n="Theramore Medal",s="Vid Northwatch Hold visar Theramore Medal att marinsoldater och officerare har tjänstgjort för att försvara utposten längs The Merchant Coast. Märket bär Theramores symbol och identifierar Alliansens garnison.",h="Vid Northwatch Hold visar Theramore Medal att marinsoldater och officerare har tjänstgjort för att försvara...",kw={"the barrens","captain fairmount","the merchant coast","northwatch hold","thalo'thas brightsun","theramore medal"},ang={["faction:Alliance"]="För Alliansens lojala visar Theramore-medaljer som samlats in som blodspengar hur isolerat och aggressivt Northwatch Hold har blivit vid Kalimdors gräns.",["faction:Horde"]="För hordäventyrare är dessa medaljer bevis på Alliansens växande militära närvaro vid The Barrens stränder."},sec={{t="Northwatchs brickor",b="Marinsoldater, skarpskyttar, kommandosoldater och officerare som tjänstgör från Northwatch Hold bär stämplade medaljer med Theramores symbol. Soldaterna är lojala mot Lady Jaina Proudmoores rike. För människotrupperna på klipporna ovanför The Barrens visar medaljerna att deras tjänst är legitim och att deras auktoritet kommer från Theramore. Andra ser dessa märken som troféer från en överdrivet nitisk utländsk garnison, som betraktar varje fartyg på väg mot kusten som ett dödligt hot."},{t="Piratisk hämnd",b="Northwatch Holds kanonbatterier hotar fartyg längs The Merchant Coast och beskjuter ofta både kapare och handelsfartyg. Efter att ha förlorat fartyg till kanonerna söker Ratchet-kaparen Captain Thalo'thas Brightsun medaljerna. Han vill ha bevis för att Northwatchs avfyrningsglada led har betalat med blod för att ha sänkt hans fartyg, och att de ansvariga soldaterna har dödats som hämnd."}},faq={{q="Vad är en Theramore Medal?",a="En Theramore Medal är ett märke som bärs av Theramores militärpersonal i tjänst vid Northwatch Hold. Den identifierar bäraren som en aktiv marinsoldat, sjöman eller officer i Alliansens garnison i The Barrens.",al={"theramore medal","vad är theramore-medaljer","northwatch-medalj"}},{q="Vem bär dessa medaljer?",a="Marinsoldater, prickskyttar, däcksmän, kommandosoldater, seniora kanonjärer och officerare som tjänstgör vid Northwatch Hold bär dessa medaljer längs The Merchant Coast.",al={"vem har theramore-medaljer","vem släpper theramore-medaljer","var kommer theramore-medaljer ifrån"}},{q="Varför vill Captain Thalo'thas Brightsun ha dem?",a="Northwatch Holds artilleri har beskjutit passerande fartyg, däribland fartyg som tillhör Captain Thalo'thas Brightsun flotta. Han kräver medaljerna som bevis för att de ansvariga soldaterna har dödats som hämnd.",al={"varför vill ratchet ha medaljer","brightsuns medaljer","varför samla theramore-medaljer"}},{q="Varför anfaller Northwatch Hold förbipasserande skepp?",a="Northwatch Holds garnison är paranoid vid gränsen till hordterritorium. Dess kanonjärer har blivit vårdslösa och avfyrningsglada och skjuter mot nästan alla fartyg som närmar sig deras kustnära enklav.",al={"varför skjuter northwatch på skepp","northwatchs aggression","varför anfaller northwatch ratchet"}}},fp="15,204,20.467.0,16.383.0,26.206.0,25.150.0,48.222.0,47.193.0"}
P.entries["item:thick-bear-fur"] = {n="Thick Bear Fur",s="Thick Bear Fur är ett eftertraktat skinn från de köldtåliga björnar som strövar bland snödrivorna i Dun Morogh. Det håller värmen väl och används ofta av spejare och soldater på resa för att tillverka isolering och varma bäddar mot den bitande alp kylan.",h="Thick Bear Fur är ett eftertraktat skinn från de köldtåliga björnar som strövar bland snödrivorna i Dun...",kw={"bellowfiz","dun morogh","the grizzled den","ice claw bear","jetsteam","steelgrill's depot","thick bear fur"},ang={["class:Hunter"]="När unga jägare ger sig ut i den kalla snårskogen för att spåra björnarna i Dun Morogh lär de sig att ta sig fram bland farliga bergsdjur och ta till vara på hållbara material från vildmarken.",["race:Gnome"]="Förare av belägringstankar som Bellowfiz, verksam kring Steelgrill's Depot, måste förlita sig på praktisk jakt i dvärgarnas trakter för att hålla sina maskiner funktionsdugliga under långa alpina fälttåg."},sec={{t="Värme mot bergsfrosten",b="Björnarna som stryker omkring på åsarna i Dun Morogh uthärdar några av de hårdaste snövidderna i Eastern Kingdoms. Deras tjocka, tåliga päls skyddar dem mot snöstormar och gör skinnen till en ovärderlig resurs för både lokalbor och resande. I stället för att kastas som avfall tas de tunga skinnen regelbundet till vara av jägare och används till att fodra kläder, isolera dragiga utposter och stoppa kalla sovrullar."},{t="Bäddar åt belägringsbrigaden",b="När Pilot Bellowfiz började utrusta sin belägringstank, Jetsteam, vid Steelgrill's Depot, insåg han att han skulle få tillbringa en hel månad ute i fält på ett långt uppdrag för Siege Brigade. Kallt järn ger föga tröst i snödrivor på hög höjd, så han gav lokala spejare i uppdrag att samla in tjock björnpäls från snöfälten söder om The Grizzled Den och tillverka varma bäddar åt hans hytt."}},faq={{q="Varifrån kommer Thick Bear Fur?",a="Thick Bear Fur kommer från de inhemska björnarna i Dun Morogh, särskilt Young Black Bears och Ice Claw Bears. De jagar över de snötäckta tundrorna och tallskogarna söder om The Grizzled Den.",al={"var får man tag på thick bear fur","vem släpper thick bear fur","björnpälsens plats"}},{q="Varför behöver Pilot Bellowfiz den här pälsen?",a="Pilot Bellowfiz utrustar sin tank, Jetsteam, för ett månadslångt uppdrag för Siege Brigade. Han behöver tunga pälsar för att tillverka varma bäddar inuti metallchassit och uthärda de bitande kalla nätterna i bergen.",al={"bellowfiz päls","varför behöver bellowfiz päls","samla päls åt jetsteam"}},{q="Vilka varelser i Dun Morogh ger detta skinn?",a="Både Young Black Bears och de större, våldsammare Ice Claw Bears som strövar omkring i höglandets snö har den täta päls som behövs för tunga vinterbäddar och isolering.",al={"vilka björnar släpper päls","björnarter i dun morogh"}}},fx={a2edc513={q="Vad är Thick Bear Fur?",a="Thick Bear Fur är den tjocka, isolerande päls som tas från de vilda björnarna som strövar bland Dun Moroghs iskalla klippor och snödrivor. Den täta huden har utvecklats för att stå emot bitande snöstormar långt under noll och ger livsviktig värme och skydd mot Khaz Modans obevekliga alpkyla.",al={"thick bear fur","vad är den här pälsen","björnpäls från dun morogh"}}},fp="14,164,33.281.0,29.350.0,36.162.0,39.213.0,45.160.0"}
P.entries["item:thistlenettle-s-badge"] = {n="Thistlenettle's Badge",s="Thistlenettle's Badge är en officiell insignia för dvärgarnas Explorers' League, som Foreman Thistlenettle en gång bar med stolthet in i The Deadmines djup. Efter ett katastrofalt ras och ett rövarinfall är märket allt som återstår för att bekräfta förmannens tragiska öde för hans överlevande bror i Stormwind.",h="Thistlenettle's Badge är en officiell insignia för dvärgarnas Explorers' League, som Foreman Thistlenettle en...",kw={"the deadmines","explorers' league","moonbrook","oh brother","thistlenettle","thistlenettle's badge","westfall","wilder"},ang={["faction:Alliance"]="När insignian återbördas får en sörjande dvärg i Stormwinds Dwarven District ett avslut.",["race:Dwarf"]="Foreman Thistlenettle förde Explorers' Leagues fana och märke till Westfall. När märket återtas glöms inte en fallen son av Ironforge bort i mörkret."},sec={{t="Explorers' League i The Deadmines",b="Innan Defias Brotherhood stängde Moonbrook och de väldiga tunnlarna under byn, grävde dvärgiska guldletare med band till Ironforges Explorers' League i Westfalls gamla guldgruvor. Foreman Thistlenettle och hans arbetslag arbetade djupt under jord tills en plötslig tunnelkollaps skilde gruppen åt. Medan hans bror Wilder lyckades fly till Stormwind City, blev förmannen och flera arbetare kvar i mörkret under jord."},{t="En dyster bekräftelse",b="I stället för en hedervärd begravning eller en flyktväg dukade Foreman Thistlenettle under för de mörka faror som frodades i de osäkrade tunnlarna och reste sig som ett viljelöst odött vidunder bland de rasade schakten utanför huvudgjuteriet. Hans Explorers' League-märke låg fortfarande i hans hand och blev det enda obestridliga beviset på hans död när det återfanns och överlämnades till hans sörjande bror."}},faq={{q="Vem tillhör märket?",a="Märket tillhörde Foreman Thistlenettle, en dvärgisk gruvarbetare och medlem av Explorers' League som blev instängd djupt under Westfall vid en plötslig tunnelkollaps.",al={"vem ägde thistlenettles badge","ägare till thistlenettles badge"}},{q="Var hittar man märket?",a="Det bärs av Foreman Thistlenettle i The Deadmines övre korridorer, fulla av monster, utanför huvudingången till Defias fäste.",al={"märkets plats","hur får man thistlenettles badge","var hittar man thistlenettle"}},{q="Vem vill ha Thistlenettle's Badge?",a="Märket lämnas till Wilder Thistlenettle, förmannens bror, som för närvarande bor i Dwarven District i Stormwind City och väntar på besked om sin släktings öde.",al={"vem tar emot thistlenettles badge","vem lämnar in oh brother","wilder thistlenettles plats"}},{q="Varför var bröderna Thistlenettle i The Deadmines?",a="Bröderna undersökte och letade efter fyndigheter i de vidsträckta, mineralrika grottorna under Moonbrook på uppdrag av Explorers' League, innan fientliga rövare och ras förstörde deras expedition.",al={"varför var dvärgar i the deadmines","thistlenettles uppdrag i the deadmines"}}},fp="21,326,38.447.0,19.414.1,30.179.0,25.148.0,32.165.0,53.213.0"}
P.entries["item:thresher-eye"] = {n="Thresher Eye",s="Thresher Eye är biologiska prover som samlas in från threshers som stryker omkring i Darkshores kustvatten. De efterfrågas av den excentriske gnomingenjören Wizbang Cranktoggle för att serva hans automatiserade fältapparater, kallade Buzzboxes.",h="Thresher Eye är biologiska prover som samlas in från threshers som stryker omkring i Darkshores kustvatten.",kw={"auberdine","buzzbox 411","darkshore","darkshore thresher","thresher eye","wizbang cranktoggle"},ang={["profession:Engineering"]="Wizbangs vana att laga komplicerade mekaniska reläer med råa djurdelar ger en förbryllande men humoristisk inblick i gnomernas oortodoxa manicker.",["race:Gnome"]="Wizbang Cranktoggle står för de vildare ytterkanterna av gnomisk uppfinningsrikedom. Han pysslar med fältmaskiner i Kalimdors vildmark mellan koppar crawler wine."},sec={{t="Ekologiska prover till gnomernas manicker",b="Utanför Darkshores dimmiga stränder jagar vattenlevande rovdjur som kallas Darkshore Threshers i bränningarna och de yttre grunden. De är farliga för lokala fiskare och resenärer, men dessa bestar har stora ögonorgan som väckt Wizbang Cranktoggles märkliga intresse. Den gnomiske ingenjören håller till i närheten och är mycket förtjust i crawler wine. Han kräver ögonen som nödvändiga delar för att reparera Buzzbox 411, en av hans fjärrkommunikationsmaskiner, som står på stranden norr om Auberdine."},{t="Ögonens syfte",b="Wizbang förklarar aldrig riktigt hur slemmiga ögon från havsdjur kan reparera ömtåliga mekaniska apparater. Kanske fungerar de som grova optiska linser, kemiska ämnen eller esoteriska biologiska kugghjul. Oavsett den tvivelaktiga ingenjörslogiken återställer maskinen sin kommunikationslänk när tre insamlade ögon matas in i underhållsluckan på Buzzbox 411. Då kan Wizbang dela ut belöningar genom brusiga sändningar."}},faq={{q="Var kommer Thresher Eye ifrån?",a="Thresher Eye samlas in från Darkshore Threshers och Elder Darkshore Threshers som simmar i havet utanför Darkshores kust, särskilt nära Auberdine.",al={"var får man thresher eye","hur får man thresher eye","källa till thresher eye"}},{q="Varför vill Wizbang Cranktoggle ha Thresher Eye?",a="Wizbang hävdar att ögonen behövs för att reparera Buzzbox 411, en gnomisk manick på strandkanten norr om Auberdine. När de stoppas in i maskinens lucka aktiveras dess system igen.",al={"varför behövs thresher eye","ögon till buzzbox 411","vad används thresher eye till"}},{q="Hur kan ett öga laga en maskin?",a="Gnomisk ingenjörskonst trotsar ofta vanlig logik, särskilt när Wizbang Cranktoggles berusade planer styr arbetet. Oavsett om han använder näthinnorna för optisk fokusering eller helt enkelt bygger in organiska delar i sina excentriska konstruktioner, tar apparaten emot dem och slås på igen.",al={"varför ögon i en maskin","gnomisk maskin biologiska delar"}},{q="Vad är Buzzbox 411?",a="Buzzbox 411 är en av flera kommunikations- och övervakningsapparater som Wizbang Cranktoggle har placerat ut i Darkshore. När den laddats med de efterfrågade materialen kan Wizbang kommunicera på distans och dela ut förnödenheter.",al={"buzzbox 411 syfte","vem byggde buzzbox 411"}}},fx={eb2ee385={q="Vad är ett Thresher Eye?",a="Ett Thresher Eye är det ögonorgan som tas från rovfiskarna threshers, som simmar i kustvattnen utanför Darkshore. För de flesta är det bara vanlig biologisk materia, men den excentriske uppfinnaren Wizbang Cranktoggle hittar märkliga mekaniska eller kemiska användningsområden för dem när han reparerar sina maskiner för fjärrkommunikation, så kallade buzzboxar.",al={"vad är thresher eye","thresher-ögon"}}},fp="12,143,38.358.0,23.312.0,33.128.0,48.158.0,30.214.0,20.205.0"}
P.entries["item:thule-s-head"] = {n="Thule's Head",s="Thule's Head är det makabra bevis som Forsaken kräver för att bekräfta att Thule Ravenclaw, befälhavaren för Scourge-styrkorna på Fenris Isle, har dödats. När trofén förs till High Executor Hadrec vid The Sepulcher befästs Forsakens grepp om Silverpine Forest.",h="Thule's Head är det makabra bevis som Forsaken kräver för att bekräfta att Thule Ravenclaw, befälhavaren för...",kw={"fenris","hadrec","nekromantiker","ravenclaw","scourge","the sepulcher","thule"},ang={["faction:Horde"]="När Thule Ravenclaw oskadliggörs säkras Silverpine Forests östra gränser och Horde:s nyvunna områden skyddas från Scourge-infall.",["race:Undead"]="För Forsaken innebär det att hugga av Thules huvud både en militär seger och personlig hämnd på Lich Kings grepp om Lordaeron."},sec={{t="Trofé från Fenris Isle",b="Fenris Isle är Lich Kings främsta fäste för Scourge i Silverpine Forest. Djupt inne i Fenris Keep leder nekromantikern Thule Ravenclaw sina legioner av rot hides och odöda undersåtar. De hotar direkt Forsakens utposter, som The Sepulcher. High Executor Hadrec kräver full visshet om att den mörke befälhavaren har fallit och godtar inget vittnesmål som inte styrks av Thules avhuggna huvud. Den våldsamma urladdningen av mörk magi när Ravenclaw dog kändes genom skogen, men hans huvud är fortfarande det fysiska bevis Hadrec behöver för att förklara Fenris Isle besegrat."}},faq={{q="Vem vill ha Thule's Head?",a="High Executor Hadrec, som leder Forsakens militära operationer vid The Sepulcher i Silverpine Forest, kräver Thule's Head för att bekräfta att Scourge-ledaren har oskadliggjorts.",al={"vem behöver thules huvud","vem lämnade in thules huvud till","vem tar thules huvud"}},{q="Vem var Thule Ravenclaw?",a="Thule Ravenclaw är en mäktig nekromantiker som leder Scourge på Fenris Isle. Från hjärtat av Fenris Keep organiserar han attacker mot Forsaken och använder ondskefulla förtrollningar som Hex of the Ravenclaw.",al={"thules historia","vem är thule","thule ravenclaws bakgrund"}},{q="Varför kräver Forsaken just hans huvud?",a="Forsaken har inte råd att låta Scourge-hot dröja kvar i Silverpine. Eftersom nekromantiker är ökända för bedrägeri och mörka återuppståndelser godtar High Executor Hadrec inget mindre än fysiska, obestridliga bevis på att Thule är fullständigt förintad.",al={"varför thules huvud","varför vill de ha hans huvud"}},{q="Vad händer när Thule Ravenclaw dödas?",a="När Thule besegras sprider sig en våldsam våg av nekrotisk energi över regionen. Den är så kraftfull att Forsakens lärda och apotekare vid The Sepulcher kan känna den magiska chockvågen på avstånd.",al={"vad händer när thule dör","energi som frigörs när thule dör"}}},fx={["3fe7e40b"]={q="Var kommer Thule's Head ifrån?",a="Det här avhuggna huvudet kommer direkt från nekromantikern Thule Ravenclaw i salarna i Fenris Keep. Thule ledde Scourge-styrkorna som intog Fenris Isle i norra Silverpine Forest och förvandlade fästet till ett tillhåll för de odöda, tills du fällde honom.",al={"thule's head ursprung","var får man tag på thule's head","thule's head källa"}}},fp="12,217,21.435.1,23.154.0,24.198.0,49.197.0,43.167.1"}
P.entries["item:thunder-lizard-blood"] = {n="Thunder Lizard Blood",s="I södra Barrens tar jägare med sig Thunder Lizard Blood tillbaka som bevis på att de överlevt. Blodet kommer från de väldiga bestar som strövar över slätterna.",h="I södra Barrens tar jägare med sig Thunder Lizard Blood tillbaka som bevis på att de överlevt.",kw={"the barrens","camp taurajo","jorn skyseer","stormhide","stormsnout","thunder lizard blood","thunderhead"},ang={["class:Hunter"]="Som jägare behöver du stadigt fotfäste och smidighet för att överlista en åsködla. Att ta dess blod bevisar att du behärskar savannens största bestar.",["race:Tauren"]="Som taurenjägare från Camp Taurajo möter du åsködlor i ett traditionellt överlevnadsprov, sida vid sida med ditt hemlands väldiga jättar."},sec={{t="Jaktens trofé",b="Åsködlor kallas Stormsnouts, Stormhides och Thunderheads ute på slätterna. Deras tunga steg får marken att skaka, och deras krossande tyngd kan platta till oförsiktiga jägare. Att ta med sig deras blod tillbaka visar skickligheten att jaga dem och uthålligheten att överleva under deras dånande fötter."}},faq={{q="Vilka varelser ger detta blod?",a="Stormsnouts, Stormhides och Thunderheads ger blodet. Dessa fullvuxna åsködlor strövar på savannen kring Camp Taurajo i södra Barrens.",al={"vem släpper thunder lizard blood","var får man thunder lizard blood","vilka åsködlor"}},{q="Varför är Thunder Lizard Blood eftertraktat?",a="Jorn Skyseer i Camp Taurajo ber jägare samla blodet som en del av prövningar runt om i The Barrens. Att ta med det tillbaka oskadat visar att en jägare kan möta Kalimdors största stampande bestar.",al={"vem vill ha thunder lizard blood","syftet med thunder lizard blood"}},{q="Var brukar man hitta åsködlorna?",a="Åsködlor strövar på gräsmarkerna norr, öster och söder om Camp Taurajo, där de betar sida vid sida med de andra stora djuren i södra Barrens.",al={"åsködlornas platser","var finns stormsnouts"}}},fx={["25735f1e"]={q="Vad är Thunder Lizard Blood?",a="Thunder Lizard Blood är en livsviktig vätska som tas från de enorma åsködlorna som strövar omkring i södra The Barrens. De väldiga bestarna får slätterna att skaka vid varje steg, och deras blod är ett obestridligt bevis på att en jägare hade skickligheten och uthålligheten att fälla sådana mäktiga varelser utan att bli krossad under deras fötter.",al={"vad är thunder lizard blood","föremålet thunder lizard blood","om thunder lizard blood"}},d2820178={q="Var kommer Thunder Lizard Blood ifrån, och vem tillverkade det?",a="Blodet tappas naturligt från de mäktiga åsködlorna i södra The Barrens, särskilt de raser som kallas Stormsnouts, Stormhides och Thunderheads. Det tillverkas eller skapas inte av dödliga händer, utan tas direkt från dessa kolossala bestar av jägare som vågar möta deras trampande hovar på savannen.",al={"var kommer thunder lizard blood ifrån","vem tillverkade thunder lizard blood","thunder lizard blood ursprung"}}},fp="20,146,18.296.0,34.152.0,41.186.0,46.142.0"}
P.entries["item:thunder-lizard-horn"] = {n="Thunder Lizard Horn",s="I The Barrens söker Brewmaster Drohn ett Thunder Lizard Horn till Chen Stormstouts legendariska brygd.",h="I The Barrens söker Brewmaster Drohn ett Thunder Lizard Horn till Chen Stormstouts legendariska brygd.",kw={"the barrens","brewmaster drohn","chen stormstout","owatanka","ratchet","stormsnout","stormstout","thunder lizard horn","thunderhead"},ang={["class:Hunter"]="Som jägare bör du vara försiktig när du spårar åsködlor över den öppna savannen. Deras blixtar gör dem dödligare än vanliga kodoer eller slättlöpare i The Barrens.",["profession:Cooking"]="Som kock kan du tycka att Dohns recept är ovanligt: det blandar slättlöparinälvor, rovdjursbetar och ett odjurshorn till en berusande dryck."},sec={{t="En kraftfull bryggingrediens",b="Åsködlor strövar omkring i The Barrens, med kammarprydda kroppar som knastrar av blixtar. Brewmaster Drohn i Ratchet värdesätter deras horn som ingrediens i Stormstout-öl. Hans mentor lärde sig receptet av den kringvandrande pandaren Brewmaster Chen Stormstout och förde det vidare till Drohn. Hornet ger drycken dess kraftiga sting."}},faq={{q="Vad används hornet till?",a="Brewmaster Drohn i Ratchet använder hornet som ingrediens i brygden som Chen Stormstout gjorde berömd.",al={"användning av thunder lizard horn","vad används thunder lizard horn till","varför behöver jag thunder lizard horn"}},{q="Vilka bestar lämnar efter sig ett Thunder Lizard Horn?",a="Thunderheads, stormsnouts, thunderstomps, stormhides och den svårfångade Owatanka kan ge ett thunder lizard horn.",al={"var hittar man thunder lizard horn","vem lämnar thunder lizard horn","källor till thunder lizard horn"}},{q="Vem är Brewmaster Drohn?",a="Brewmaster Drohn brygger i Ratchet. Hans tidigare mentor lärde sig Stormstout-receptet av Chen Stormstout och förde det vidare till honom.",al={"vem är drohn","brewmaster drohns historia","drohn ratchet"}},{q="Är thunder lizards farliga att jaga för deras horn?",a="Åsködlor kan avge blixtar och släppa loss dånande tramp när de blir provocerade, vilket gör dem farliga att jaga ensam.",al={"hur tåliga är thunder lizards","jakt på thunder lizards"}}},fx={["6ace69b3"]={q="Vad är ett Thunder Lizard Horn?",a="Ett Thunder Lizard Horn är en stadig naturtrofé från de stora åsködlorna som strövar omkring på The Barrens slätter. De imponerande reptilerna, som är knutna till stormar, leder elektrisk energi genom sina väldiga kroppar. Därför är hornen en kraftfull naturkomponent som uppskattas av sällsynta hantverkare med ovanliga recept.",al={"vad är thunder lizard horn","information om thunder lizard horn","om thunder lizard horn"}},["1dc3a738"]={q="Var kommer ett Thunder Lizard Horn ifrån?",a="Det är inte konstgjort, utan ett horn som tas direkt från de fruktade åsködlorna i The Barrens, däribland stormsnouts, thunderheads och den svårfångade Owatanka. När du fäller en av dessa väldiga bestar kan du ta hornet utan att skada det.",al={"var kommer thunder lizard-horn ifrån","vem tillverkar thunder lizard horn","thunder lizard horn källa"}}},fp="19,98,24.320.0,26.99.0,41.111.0,24.130.0,54.121.0"}
P.entries["item:thunderhawk-saliva-gland"] = {n="Thunderhawk Saliva Gland",s="I The Barrens ger större åskhökar en körtel som Brewmaster Drohn värdesätter. Han behöver den för att återskapa Chen Stormstouts eldiga Trogg Ale.",h="I The Barrens ger större åskhökar en körtel som Brewmaster Drohn värdesätter.",kw={"the barrens","drohn","körtel","fat","ratchet","saliv","thunderhawk","trogg ale"},ang={["faction:Horde"]="Som medlem av Horde kan du bevisa ditt värde genom att jaga vildsinta åskhökar över The Barrens medan du färdas genom Kalimdor.",["profession:Cooking"]="Som kock kanske du drar dig för att använda spottkörtlar, men uppfinningsrika bryggmästare värdesätter märkliga djuresser för deras kryddiga smak och kraft."},sec={{t="En vild ingrediens",b="Större åskhökar jagar över The Barrens torra savanner. Dessa bevingade ormar är kända för att tygla stormar, och de äldre, farligare exemplaren producerar en spottkörtel laddad med naturlig kraft. Resenärer håller sig undan de dödliga bestarna, men bryggmästare värdesätter körteln som en sällsynt bas för exotiska drycker."},{t="Chens hemliga recept",b="Brewmaster Drohn slog sig ner utanför Ratchet efter att Chen Stormstout rest genom Kalimdor. Drohn studerar den kringvandrande bryggmästarens jäsningsmetoder och behöver en färsk åskhöks spottkörtel, stormhide lightning glands och kodo liver för att brygga Trogg Ale. Den eldiga drycken har ett omisskännligt sting och är tänkt att stärka härdade äventyrare."}},faq={{q="Var hittar du en Thunderhawk Saliva Gland?",a="Större åskhökar jagar över The Barrens öppna savanner, och deras spottkörtlar skördas där.",al={"byte från thunderhawk saliva gland","var får man tag på spottkörtel","thunderhawk-körtelns plats"}},{q="Vad används spottkörteln till?",a="Brewmaster Drohn utanför Ratchet behöver körteln för att brygga Trogg Ale, ett kraftfullt recept som Chen Stormstout lämnade efter sig.",al={"spottkörtelns användning","vad används thunderhawk saliva gland till","thunderhawk-spottkörtelns syfte"}},{q="Vem är Brewmaster Drohn?",a="Brewmaster Drohn bor nära Ratchets hamn. Han lärde sig exotisk bryggning av den kringvandrande resenären Chen Stormstout och byter till sig kraftfulla ölsorter från äventyrare som trotsar det lokala djurlivet för att få tag på ingredienser.",al={"drohn ratchet","vem är drohn","brewmaster drohns historia"}},{q="Vad är Trogg Ale?",a="Chen Stormstout skapade Trogg Ale som en ytterst kraftfull dryck. Brewmaster Drohn gör den med en större åskhöks spottkörtel, lightning glands och kodo liver.",al={"trogg ales historia","vad är trogg ale","chens trogg ale"}}},fx={bfe8bf39={q="Vad är en Thunderhawk Saliva Gland?",a="Det är ett organ som tas från fullvuxna, rovgiriga greater thunderhawks, som svävar över The Barrens torra slätter. Körteln är fylld av dessa fågelbestars naturliga energier och giftiga vätskor. Den ger en skarp och flyktig utsöndring som uppskattas av djärva bryggare som söker ovanliga blandningar med tydlig verkan.",al={"vad är thunderhawk saliva gland","berättelsen om thunderhawk saliva gland","om thunderhawk saliva gland"}},dda65d1e={q="Var kommer en Thunderhawk Saliva Gland ifrån?",a="Det är ingen tillverkad vara, utan ett biologiskt organ från greater thunderhawks som strövar över The Barrens öppna himmel och klippor. Jägare måste spåra upp dessa kraftfulla bevingade rovdjur och försiktigt ta ut körteln hel ur deras kroppar.",al={"thunderhawk saliva gland ursprung","var kommer thunderhawk saliva glands ifrån","vem tillverkade thunderhawk saliva gland"}}},fp="24,141,17.312.0,21.342.0,45.111.0,34.112.0,24.195.0,18.166.0"}
P.entries["item:thunderhawk-wings"] = {n="Thunderhawk Wings",s="Över centrala och södra Barrens tar jägare Thunderhawk Wings från vindormarna som svävar ovanför. I Camp Taurajo tar Jorn Skyseer emot dem som bevis på en jägares styrka, list och uthållighet.",h="Över centrala och södra Barrens tar jägare Thunderhawk Wings från vindormarna som svävar ovanför.",kw={"the barrens","camp taurajo","jorn skyseer","sergra darkthorn","thunderhawk","vindorm","vingar"},ang={["class:Hunter"]="Som jägare markerar det en övergångsrit att ta vingarna från en thunderhawk som svävar högt. Det prövar din spårningsförmåga, ditt tålamod och din träffsäkerhet mot snabba luftburna bestar.",["race:Tauren"]="Som tauren hedrar du savannens ande genom att skörda dessa vingar och visa respekt för Jordmoderns våldsamma varelser."},sec={{t="Jaktens trofé",b="Jägare som är stationerade i Camp Taurajo värdesätter ett par hela Thunderhawk Wings. Vindormar, som de lokala jägarna kallar thunderhawks, är våldsamma bevingade reptiler som slår till snabbt från ovan. Att spåra dem över de öppna slätterna och ta deras vingar i strid prövar jägarens skicklighet. För en lärling bevisar vingarna att hen är redo att följa den livslånga vägen som fullärd jägare."}},faq={{q="Var hittar man Thunderhawk Wings?",a="Thunderhawk Wings kommer från thunderhawks som glider över åsarna och slätterna i centrala och södra Barrens, särskilt kring Camp Taurajo.",al={"var hittar man vingarna","thunderhawk wings plats","hur får man thunderhawk wings"}},{q="Vem vill ha vingarna?",a="Jorn Skyseer, en erfaren taurenjägare stationerad i Camp Taurajo, ber om vingarna som bevis på att en lärling har bemästrat savannens jaktriter.",al={"vem tar thunderhawk wings","lämna in thunderhawk wings","jorn skyseer vingar"}},{q="Vad betyder det att ta vingarna?",a="Att ta vingarna till Jorn Skyseer fullbordar en krävande övergångsrit. Det visar att jägaren har styrkan, modet och tålamodet att möta våldsamma luftburna rovdjur.",al={"varför jaga thunderhawk","vingarnas syfte","betydelsen av thunderhawkjakten"}}},fx={["1074baa7"]={q="Vad är Thunderhawk Wings?",a="Dessa vingar tas från thunderhawks, de ståtliga fjäderklädda vindormarna som svävar över södra The Barrens slätter. Thunderhawks är vilda och stolta rovdjur, och tauren vördar dem som symboler för styrka och vild storhet. Man tar inte deras vingar lättvindigt; de är ett konkret bevis på jägarens skicklighet, mod och respekt när hen möter ett av himlens mäktigaste odjur.",al={"vad är thunderhawk wings","berättelsen om thunderhawk wings","thunderhawk-vingar"}},dd263964={q="Var kommer Thunderhawk Wings ifrån?",a="Vingarna tas direkt från dödade thunderhawks som strövar på den öppna himlen kring Camp Taurajo. Dessa bevingade ormar har naturlig blixtkraft och stor smidighet. De är rovdjur som hör hemma i luften över The Barrens, så vingarna är naturliga troféer från slutet av en krävande jakt.",al={"var kommer thunderhawk wings ifrån","thunderhawk wings källa","vilka fäller thunderhawk wings"}}},fp="17,218,18.398.0,34.145.0,22.154.0,37.168.0"}
P.entries["item:thunderhorn-cleansing-totem"] = {n="Thunderhorn Cleansing Totem",s="Thunderhorn Cleansing Totem är ett välsignat rituellt redskap som Mull Thunderhorn har tillverkat i Bloodhoof Village. Det är laddat med förfädernas magi för att rena det förorenade vattnet i Thunderhorn Water Well.",h="Thunderhorn Cleansing Totem är ett välsignat rituellt redskap som Mull Thunderhorn har tillverkat i Bloodhoof...",kw={"bloodhoof","rening","mulgore","mull","ritual","thunderhorn","totem","vattenbrunn"},ang={["class:Shaman"]="Schamaner förstår att reningstotemer fungerar som kanaler som stillar upprörda naturandar och återställer balansen där elementens energier har blivit bittra.",["race:Tauren"]="För tauren är reningen av förfädernas brunnar inte bara en syssla, utan en helig plikt gentemot Jordmodern och klanens förfäder, som vakar över Mulgore."},sec={{t="Reningen av Thunderhorn Well",b="Över Mulgore's vidsträckta slätter förgiftas jordens livsblod av en osedd korruption. Taurenstammarnas förfädersbrunnar ger hjordarna och jaktmarkerna livsviktig näring, men illasinnade agenter har besmittat vattnet. På uppdrag av den äldre Mull Thunderhorn bär äventyrare denna förberedda totem norr om Bloodhoof Village för att driva bort föroreningen som lagt sig över Thunderhorn-klanens heliga källa. Genom en rituell åkallan lugnar totemen vattnets upprörda andar och renar förfädernas plats."}},faq={{q="Vad är syftet med Thunderhorn Cleansing Totem?",a="Totemen är särskilt förberedd för att rena det förorenade vattnet i Thunderhorn Water Well, norr om Bloodhoof Village. När du använder den drivs det onda inflytandet som förgiftar brunnen bort, och förfädernas andar som vakar över den blir nöjda.",al={"vad gör totemen","varför använda thunderhorn totem","reningstotemens syfte"}},{q="Vem tillverkade totemen?",a="Totemen har tillverkats och skänkts av Mull Thunderhorn, en äldre person som bor i Bloodhoof Village, vakar över landets välmående och talar med förfäderna.",al={"vem gjorde totemen","vem ger thunderhorn totem","mull thunderhorns totem"}},{q="Var måste totemen användas?",a="Totemen måste användas vid själva Thunderhorn Water Well, norr om Bloodhoof Village i centrala Mulgore.",al={"var använder jag totemen","totemens plats","var ligger thunderhorn well"}},{q="Vad händer när ritualen är utförd?",a="När brunnen renas får Thunderhorn-klanens förfädersandar frid. Mull Thunderhorn får i en dröm syner av deras tacksamhet, och de lovordar den som renade deras marker och skänker förfädersgåvor.",al={"efter att brunnen renats","ritualens resultat","förfädernas reaktion"}}},fx={["0770e0ea"]={q="Vad är Thunderhorn Cleansing Totem?",a="Thunderhorn Cleansing Totem är ett invigt ritualföremål som skapats särskilt för att rena Thunderhorn Water Well i Mulgore från den korrumperande smittan. Det är fyllt av förfädersmagi och elementarmagi och fungerar som en helig kanal som leder andliga energier direkt till den förorenade källan, så att dess rena, livgivande vatten återställs för de lokala tauren.",al={"vad är thunderhorn cleansing totem","vad är thunderhorn totem","berättelsen om thunderhorn cleansing totem"}},d3c4386d={q="Varför behövs Thunderhorn Cleansing Totem?",a="Thunderhorn-klanens förfädersbrunn har drabbats av en onaturlig korrumpering som hotar landet och djuren som dricker därifrån. Vanliga metoder kan inte häva en sådan förbannelse. Mull Thunderhorn förberedde denna förtrollade totem så att ett sändebud kan utföra den högtidliga ritual som krävs för att driva bort smittan och blidka förfädernas andar som vakar över brunnen.",al={"varför behövs thunderhorn totem","varför behöver jag cleansing totem","thunderhorn cleansing totems syfte"}}},fp="27,155,30.362.0,55.202.0,22.158.0,29.91.0,43.188.1"}
P.entries["item:thurman-s-remains"] = {n="Thurman's Remains",s="Thurman's Remains är de kroppsliga kvarlevorna efter Thurman Agamand, återfunna i familjens förstörda kvarnar i norra Tirisfal Glades. En gång var han en förmögen kvarnägare som övertalade sina arbetare att stå emot Scourge, men Thurman föll för pesten och vandrar nu omkring på sin forna egendom som en odöd träl.",h="Thurman's Remains är de kroppsliga kvarlevorna efter Thurman Agamand, återfunna i familjens förstörda kvarnar...",kw={"agamand","agamand mills","coleman farthing","familjens döda","thurman agamand","thurman's remains","tirisfal glades"},ang={["race:Undead"]="För Forsaken är återtagandet av dessa kvarlevor en bister uppgörelse med aristokratiska herrar vars övermod ledde arbetarna rakt i Scourges våld."},sec={{t="Ett arv av förstörelse",b="Före det tredje kriget var familjen Agamand de mest välmående jordägarna i Tirisfal Glades. De drev omfattande kvarnar och hade dussintals lokala arbetare anställda. När Scourge svepte över Lordaeron befäste Thurman Agamand och hans släkt sin egendom i stället för att fly. Övertygade om att deras rikedom och befästa kvarnar skulle stå emot anfallet övertalade de sina trogna arbetare att ta till vapen vid deras sida. Försvaret misslyckades totalt. Agamandfamiljen och deras arbetare slaktades och förvandlades till Lich Kings viljelösa tjänare. I dag kräver Coleman Farthing, en före detta anställd som återuppstått som Forsaken, att hans forna herrar ska förgöras. Han söker Thurmans kvarlevor som bevis på att den dåraktige patriarken har fått betala för att ha dömt sitt hushåll till undergång."}},faq={{q="Vem var Thurman Agamand?",a="Thurman Agamand var en framstående medlem av den välbärgade Agamanddynastin, som ägde Agamand Mills i norra Tirisfal Glades. När Scourge slog till mot Lordaeron fick hans stolthet honom att övertala sina arbetare att stanna och slåss. Det ledde till att alla på egendomen slaktades och återuppväcktes.",al={"thurman agamand","vem är thurman","vem var thurman"}},{q="Varför vill Coleman Farthing ha Thurmans kvarlevor?",a="Coleman Farthing var en kvarnarbetare som litade på Agamandfamiljen och dog när han försvarade deras egendom. Nu tillhör Coleman Forsaken och hyser djup bitterhet mot sina forna arbetsgivare för att de dömde arbetarna till ett liv som odöda. Han söker Thurmans kvarlevor för att få sin hämnd.",al={"varför coleman vill ha kvarlevor","coleman farthings motiv","varför döda thurman"}},{q="Hade Thurman fri vilja när han förgjordes?",a="Nej. Till skillnad från Forsaken i Undercity förblev Thurman Agamand mentalt kontrollerad av Scourge efter sin död. Han tjänade som en tanklös undersåte tills han förgjordes vid kvarnarna.",al={"hade thurman fri vilja","var thurman scourge","är thurman forsaken"}},{q="Vilka andra i Agamandfamiljen är måltavlor?",a="Förutom Thurman söker Coleman Farthing förgöra Gregor Agamand och Nissa Agamand och återta deras kvarlevor. Därmed gör han slut på blodslinjen som en gång härskade över kvarnarna.",al={"andra i agamandfamiljen","medlemmar av agamandfamiljen","måltavlor bland familjens döda"}}},fx={["559ae8e6"]={q="Vad är Thurman's Remains?",a="Det här är de fysiska kvarlevorna efter Thurman Agamand, som återfanns sedan hans rastlösa odöda gestalt hade fällts vid Agamand Mills. Thurman tillhörde en gång den välbärgade Agamand-ätten, som ägde kvarnarna i området. Han föll offer för Plague of Undeath och blev kvar som en viljelös träl under Scourge tills han till slut fälldes.",al={"vad är thurman's remains","föremålet thurman's remains","vem är thurman's remains"}},["0ea47aa9"]={q="Var kommer Thurman's Remains ifrån?",a="De tas direkt från Thurman Agamands förstörda lik vid Agamand Mills i norra Tirisfal Glades. När Scourge drog genom landet befäste Thurman och hans släkt sin egendom och övertalade arbetarna att göra motstånd. Försvaret misslyckades, och familjen förvandlades till bestar i Scourge innan deras kroppar till slut slogs sönder.",al={"var får man tag på thurman's remains","thurman's remains ursprung","hur skapas thurman's remains"}}},fp="17,200,16.686.0,24.264.0,49.216.0,49.189.0,51.169.0"}
P.entries["item:thurman-s-sewing-kit"] = {n="Thurman's Sewing Kit",s="Hos Larson Clothiers behövs Thurman's Sewing Kit i hans skrädderiarbete. Verktygen tillhör den unge lärlingen Thurman Schneider, som lämnade dem hemma hos sin familj vid kanalen för att slippa en lång dag med sömnad.",h="Hos Larson Clothiers behövs Thurman's Sewing Kit i hans skrädderiarbete.",kw={"larson clothiers","mage quarter","rema schneider","sykit","stormwinds kanaler","thurman schneider","thurman's sewing kit"},ang={["profession:Tailoring"]="Varje skräddare känner till det träliga med den tidiga lärlingstiden, men få går så långt som den unge Thurman Schneider och lämnar saxarna bakom sig."},sec={{t="En motvillig lärlings verktyg",b="Thurman's Sewing Kit innehåller en skräddarlärlings vardagliga verktyg: nålar, saxar och tråd. Den unge Thurman Schneider studerar skrädderi hos Larson Clothiers, djupt inne i Stormwinds Mage Quarter nära Mage Tower. Hans mor, Rema Schneider, vet att han inte kan utföra sitt arbete utan kitet, så hon ber förbipasserande längs kanalerna att bära det till butiken. När Thurman får verktygen visar hans reaktion att han lämnade dem med flit, i hopp om att byta ut en dag med sömnad av kläder mot lite ledighet."}},faq={{q="Vad finns i Thurman's Sewing Kit?",a="Kitet innehåller nålar, saxar och tråd, verktygen som Thurman Schneider behöver i sitt skrädderiarbete hos Larson Clothiers.",al={"vad finns i kitet","sykitets innehåll","thurmans saxar"}},{q="Vem tillhör sykitet?",a="Kitet tillhör Thurman Schneider, en ung lärling som arbetar under familjen Larson i Stormwinds Mage Quarter.",al={"vem äger kitet","thurmans ägare","vem är thurman"}},{q="Varför lämnades kitet hemma hos Thurman?",a="Rema trodde att Thurman hade skyndat iväg och glömt kitet, men han lämnade det med flit i hopp om att slippa dagens arbete hos Larson Clothiers.",al={"varför glömde thurman sitt kit","glömde thurman det med flit","varför lämna sykit"}},{q="Vart ska kitet levereras?",a="Ta kitet till Larson Clothiers, djupt inne i Stormwind Citys Mage Quarter nära Mage Tower.",al={"vart ska jag ta kitet","var ligger larson clothiers","var finns thurman"}}},fx={["128c9147"]={q="Varför vill Rema Schneider att Thurman's Sewing Kit ska levereras?",a="Thurman är skräddarlärling hos Larson Clothiers i Mage Quarter. Hans mor, Rema Schneider, ber dig leverera sybehören så att han kan utföra sina dagliga skräddaruppgifter. Men Thurman lämnade i hemlighet kvar sina verktyg med flit, i hopp om att slippa dagens sysslor och smita från arbetet.",al={"varför leverera thurman's sewing kit","varför behöver thurman sitt sykit","varför vill någon ha sykitet"}}},fp="20,191,30.450.0,36.101.0,35.124.0,46.139.0,41.87.0"}
P.entries["item:timberling-seed"] = {n="Timberling Seed",s="Timberling Seeds är botaniska frön som skördas från de upprörda växtvarelser som bebor Teldrassil. Naturkunniga och druider studerar fröna för att förstå varför skogens växtliv har blivit ovanligt aggressivt.",h="Timberling Seeds är botaniska frön som skördas från de upprörda växtvarelser som bebor Teldrassil.",kw={"fördärvelse","darnassus","denalan","lake al'ameth","rellian greenspyre","teldrassil","timberling","timberling seed"},ang={["class:Druid"]="De fläckade fröna är tidiga varningstecken på en onaturlig fördärvelse som sprider sig bland Teldrassils växtvarelser, ett allvarligt bekymmer för Cenarion Enclaves beskyddare.",["profession:Herbalism"]="För botaniker och örtsamlare visar studiet av fröna hur starkt jordmånen och den omgivande fördärvelsen påverkar vildfloran."},sec={{t="Frön från en rastlös skog",b="Teldrassils timberlings är naturandar vars temperament återspeglar Världsträdets balans. På senare tid har dessa varelser blivit fientliga och arga, till nattalvernas bekymmer när de vårdar grenarna. Örtkunniga som Denalan vid Lake Al'Ameth tror att problemet har sina rötter i jorden. De samlar frön från vilda timberlings i hopp om att de ska gro till fogliga avkommor om de får växa under kontrollerade, renade förhållanden."},{t="En rotad fördärvelse",b="Försöken att odla milda timberlings möter en dyster verklighet. När fröprover undersöks av cenariska lärda som Rellian Greenspyre i Darnassus, uppdagas djupare problem. Fröna bär på fläcken från sina fördärvade föräldrar, vilket tyder på att oron bland Teldrassils växtandar inte bara beror på dålig tillväxt, utan på en underliggande fördärvelse som får fäste i det stora trädets ekosystem."}},faq={{q="Vad är ett timberlingfrö?",a="Ett Timberling Seed är en timberlings fortplantningsfrö, en växtlik naturande som finns över hela Teldrassil. Naturkunniga samlar in dem för att studera timberlingars tillväxt och ekologi.",al={"timberlingfrön","vad är timberlingfrön","timberlingens frön"}},{q="Var samlas fröna in?",a="De samlas in från vilda timberlings och sumpbestar som strövar längs Lake Al'Ameths stränder och grund.",al={"var får man tag på frön","timberling seed byte","vem släpper timberling seed"}},{q="Varför vill Denalan ha Timberling Seeds?",a="Denalan misstänker att olämplig jord driver timberlings till raseri. Han hoppas kunna plantera vilda frön i särskilt preparerad jord och se om han kan få fogliga, ofördärvade timberlings att gro.",al={"denalans syfte","varför samla frön","denalans plan"}},{q="Vad upptäcker Rellian Greenspyre om fröna?",a="Rellian upptäcker att en fördärvelse har fått fäste i timberlings, och att fröna bär på föräldrarnas fläck. Han inser att det ligger bortom hans förmåga att läka dem, så hoppet står till Denalans trädgårdsexperiment.",al={"rellians fröstudie","vad upptäckte rellian","är fröna fläckade"}}},fp="15,186,26.382.0,19.283.1,26.185.0,31.97.0,39.160.0,54.173.1"}
P.entries["item:timberling-sprout"] = {n="Timberling Sprout",s="Timberling Sprouts är unga, nybildade växtandar som slår rot nära Lake Al'Ameths stränder i Teldrassil. Redan tidigt visar de tecken på fördärv, så nattalvernas väktare drar upp dem innan de växer till aggressiva timberlings.",h="Timberling Sprouts är unga, nybildade växtandar som slår rot nära Lake Al'Ameths stränder i Teldrassil.",kw={"aldrassil","fördärv","lake al'ameth","shadowglen","teldrassil","timberling","timberling sprout"},ang={["class:Druid"]="För druider som står i samklang med Kalimdors växtliv och elementarer är det ett dystert omen för Teldrassils framtid att se naturliga skogsandar gro ur jorden redan fördärvade.",["race:NightElf"]="Unga nattalver som påbörjar sin träning i Shadowglen får i uppdrag att rensa bort groddarna för att skydda sitt nya skogshem."},sec={{t="Fördärvade groddar",b="Timberlings är växtandar med stark koppling till Teldrassils naturliga livskraft, men groddarna längs Lake Al'Ameth har oroat de lokala nattalverna. I stället för att växa fram friska och i harmoni med vildmarken slår de rot redan fördärvade och aggressiva. Eftersom dessa späda groddar verkar omöjliga att rena eller läka på naturlig väg måste vårdarna vid Lake Al'Ameth samla in och förstöra dem, så att fientliga timberlings inte sprider sig okontrollerat över den nyplanterade världsträdets sköra grenar."}},faq={{q="Var finns Timberling Sprouts?",a="Timberling Sprouts växer nära vattenbrynet längs Lake Al'Ameths stränder, söder om Dolanaar i Teldrassil.",al={"groddarnas plats","var finns timberling sprouts","hitta groddar"}},{q="Varför drar nattalverna upp Timberling Sprouts?",a="Groddarna slår rot fördärvade redan från början. Om de lämnas åt sitt öde växer de till våldsamma timberlings som hotar Teldrassils trygghet och balans. Eftersom de anses vara bortom all hjälp tar vårdarna bort dem medan de fortfarande är små.",al={"varför döda groddar","timberling sprouts syfte","varför förstöra groddar"}},{q="Vad får groddarna att bli fördärvade?",a="En mystisk sjukdom har börjat drabba Teldrassils djurliv och växtandar. Den exakta källan till fördärvet är fortfarande en olöst gåta för botanisten Denalan, men det påverkar unga timberlings från det ögonblick de slår rot.",al={"varför är timberlings fördärvade","vad fördärvar dem","groddsjuka"}},{q="Vem ber om att Timberling Sprouts ska samlas in?",a="Denalan, botanisten som sköter Lake Al'Ameth, ber äventyrare att samla in och rensa bort groddarna från sjökanten för att hålla marken ren.",al={"vem vill ha groddar","uppdragsgivare för groddar","lämna in timberling sprouts"}}},fx={f13cc7b7={q="Vad är en Timberling Sprout?",a="En Timberling Sprout är en ung timberling, en liten växtliknande elementarvarelse som slår rot längs de fuktiga stränderna vid Lake Al'Ameth. Om skotten lämnas i fred växer de så småningom upp till fullvuxna timberlings. Tyvärr är skotten som spirar kring sjön smittade och aggressiva, så botanisten Denalan vid Lake Al'Ameth vill att de rycks upp innan de växer till farliga hot.",al={"vad är timberling sprout","vad är timberling sprouts","information om timberling sprout"}}},fp="17,154,18.420.0,35.99.0,63.206.0,46.185.0,48.139.0"}
P.entries["item:tirisfal-pumpkin"] = {n="Tirisfal Pumpkin",s="Tirisfal Pumpkins växer i de plöjda tegarna på Solliden Farmstead, där överlevande levande människor kämpar för att klara sig i de fördärvade gläntorna. The Forsaken plundrar regelbundet fälten för att förse Royal Apothecary Society med organiskt material till sina pågående kemiska brygder.",h="Tirisfal Pumpkins växer i de plöjda tegarna på Solliden Farmstead, där överlevande levande människor kämpar...",kw={"apothecary johaan","brill","deathguard simmer","sorgens fält","pumpa","reagens","solliden farmstead","tirisfal pumpkin"},ang={["faction:Alliance"]="Pumporna som odlas på Solliden Farmstead vittnar om Lordaerons överlevande invånares desperata försök att föda sig själva medan Forsaken ständigt gör intrång.",["race:Undead"]="Att plundra odlingen på Solliden fyller två syften: att beröva de kvarvarande levande dödliga deras föda och att förse Apothecary Johaan med testmaterial till Forsakens mörka forskning."},sec={{t="Skörd i ett fördärvat land",b="Trots att fördärvet breder ut sig över Lordaeron spirar grödor fortfarande på något vis i fälten väster om Brill. På Solliden Farmstead klamrar sig levande mänskliga bönder fast vid sin jord och odlar jättelika orangea pumpor under vaksam bevakning från närbelägna Scarlet Crusade. För dessa dödliga är skörden livsviktig föda. För Brills närbelägna Forsaken är pumporna däremot både ett lockande mål för sabotage och en riklig källa till organiska råreagenser som Apothecary Johaan behöver."},{t="Reagenser till apoteket",b="Deathguard Simmer skickar ut unga Forsaken på de omstridda fälten för att stjäla pumporna mitt framför näsan på bönderna. Grönsakerna blir inte föda åt de döda, utan hamnar i Royal Apothecary Societys kokande kittlar. Apotekarna testar ofta hur naturlig flora reagerar på deras farsoter och experimentblandningar och vänder Lordaerons återstående jordbruk mot de levande."}},faq={{q="Var hittar man Tirisfal Pumpkins?",a="De växer i odlingarna på Solliden Farmstead, väster om Brill och strax norr om Deathknell i Tirisfal Glades.",al={"pumpans plats","var finns pumporna","pumpor på solliden farmstead"}},{q="Varför vill Forsaken ha de här pumporna?",a="Deathguard Simmer beordrar att de stjäls för att beröva de överlevande människorna och Scarlet Crusade deras resurser och för att leverera dem till Apothecary Johaan i Brill som organiska råreagenser till apotekets forskning.",al={"varför stjäla pumpor","johaan pumpa","vad används pumporna till"}},{q="Kan spelare äta eller laga mat med Tirisfal Pumpkins?",a="Nej. De samlas uteslutande som ett uppdragsreagens åt Royal Apothecary Society och har inget kulinariskt användningsområde för äventyrare.",al={"kan man äta tirisfal-pumpor","pumpa som matlagningsingrediens"}},{q="Vem odlar dem just nu?",a="Levande mänskliga bönder brukar fortfarande jorden på Solliden Farmstead, där de får ett visst skydd av Scarlet Crusade, som är stationerad vid det närbelägna vakttornet.",al={"vem äger gården","bönderna på solliden"}}},fx={dab4ae64={q="Vad är en Tirisfal Pumpkin?",a="En Tirisfal Pumpkin är en härdig kalebass som odlas av de överlevande mänskliga bönderna vid Solliden Farmstead i Tirisfal Glades. I ett förött rike där levande växtlighet kämpar för att överleva är kalebasserna värdefull föda för de levande och viktiga alkemiska ingredienser för Forsaken.",al={"vad är tirisfal pumpkin","tirisfal pumpkin","vad är tirisfal pumpkins"}}},fp="16,148,26.356.0,19.346.0,37.95.0,42.196.0,47.108.0,30.134.0"}
P.entries["item:token-of-thievery"] = {n="Token of Thievery",s="Token of Thievery är ett bevis på skicklighet som nybörjartjuvar återfår under sin träning i Redridge Mountains. Det ligger i en låst kista vid Alther's Mill, som hotas av orcher, och utgör det slutprov som den erfarne tjuven Lucius har satt upp för att visa att de behärskar lås dyrkning.",h="Token of Thievery är ett bevis på skicklighet som nybörjartjuvar återfår under sin träning i Redridge...",kw={"alther's mill","certificate of thievery","lakeshire","låsdyrkning","lucius","redridge","tjuvverktyg","token of thievery"},ang={["class:Rogue"]="Token of Thievery markerar en viktig övergångsrit för Alliansens tjuvar och visar att de kan använda låsdyrkar effektivt utan att väcka uppmärksamhet i ruiner som patrulleras av fienden."},sec={{t="Ett prov på finess",b="Alla skurkar har inte en medfödd känsla för att hantera låsmekanismer och obemärkt lirka upp spärrar. I Lakeshire låter den skurkaktige instruktören Lucius lovande agenter pröva sin skicklighet genom att testa deras klipskhet och verktyg ute i fält. I stället för att hålla sina prov i lugna gränder gömmer Lucius Token of Thievery i en stadig låsbox bland ruinerna vid Alther's Mill, rakt i vägen för framryckande Blackrock-orcher. Att hämta tokenet visar att en lärling kan dyrka upp ett säkert lås under dödlig fara och belönas med sitt formella Certificate of Thievery."}},faq={{q="Vad är Token of Thievery?",a="Det är ett övningstoken som Lucius har låst in vid Alther's Mill. Tjuvlärlingar måste dyrka upp låset på hans kista för att hämta det och visa att de har den finess som krävs för att dyrka upp lås under farliga förhållanden.",al={"användning av token of thievery","vad är token of thievery","lucius token"}},{q="Vem lägger tokenet i låsboxen?",a="Lucius, en erfaren tjuvmentor verksam i Lakeshire, lade det där som en del av sitt långvariga träningsprogram för unga tjuvar.",al={"vem äger tokenet","ägare till lucius låsbox","vem gömde tokenet"}},{q="Varför står kistan vid Alther's Mill?",a="Alther's Mill ligger längs vägen från Lakeshire och har blivit ett farligt område på grund av Blackrock-orcher som stryker omkring. Lucius använder platsen så att hans elever lär sig dyrka upp lås snabbt och tyst medan de tar sig fram genom fientligt territorium.",al={"varför alther's mill","orsak till låsboxen vid kvarnen","fara vid kvarnen"}},{q="Vad får du i utbyte mot tokenet?",a="När tjuven återlämnar tokenet till Lucius får hen sitt Certificate of Thievery, ett erkännande av sin grundläggande utbildning i låsdyrkning.",al={"belöning för tokenet","vad ger lucius dig","certificate of thievery"}}},fp="17,174,17.303.0,30.138.0,34.124.0,41.177.0,46.126.0"}
P.entries["item:tome-of-the-cabal-quest-item"] = {n="Tome of the Cabal (quest item)",s="Häxmästare i Ratchet får Tome of the Cabal av Strahad Farsan efter att ha samlat farliga komponenter. På dess sidor finns besvärjelserna som kallar en felhunter genom Twisting Nether och binder den.",h="Häxmästare i Ratchet får Tome of the Cabal av Strahad Farsan efter att ha samlat farliga komponenter.",kw={"felhunter","ratchet","strahad farsan","frambesvärjningscirkel","bindningen","tome of the cabal"},ang={["class:Warlock"]="Som häxmästare måste du bemästra den här boken för att få en felhunter som följeslagare och vinna herravälde över demonisk magi."},sec={{t="En port till Nether",b="En felhunter är ett vildsint odjur från det kaotiska Twisting Nether, fruktat för att sluka mana. Att kuva en är ett steg på vägen för erfarna häxmästare. Tome of the Cabal innehåller ritualerna för att öppna en väg till en sådan demon. Strahad Farsan, en erfaren besvärjare i Ratchet, ger boken till en aspirant först efter att denne samlat de sällsynta och farliga komponenter som dess magi kräver."},{t="Kallelsens ritual",b="Strahad Farsan upprättar den huvudsakliga åkallandecirkeln i sin helgedom, medan hans akolyter använder kanaliseringsstavar för att skapa en större skyddande gräns. Häxmästaren läser upp bokens exakta besvärjelser och drar in felhuntern i vår värld. Demonen måste bekämpas genast och kuvas, så att den binds till häxmästarens vilja."}},faq={{q="Vad används Tome of the Cabal till?",a="Tome of the Cabal innehåller besvärjelserna för att åkalla en felhunter från Twisting Nether till en förberedd cirkel i Ratchet, där en häxmästare kan möta och binda demonen.",al={"vad gör tome of the cabal","syftet med tome of the cabal","tome felhunter"}},{q="Vem tillhandahåller Tome of the Cabal?",a="Strahad Farsan, en häxmästare som bor i kullarna ovanför Ratchet i The Barrens, tillhandahåller boken när en utövare har slutfört de mödosamma förberedelserna.",al={"vem ger tome of the cabal","var får man tome of the cabal","strahads bok"}},{q="Behåller du boken efter att ritualen är slutförd?",a="Nej. När du har besegrat den åkallade felhuntern och bevisat din skicklighet återlämnar du Tome of the Cabal till Strahad Farsan som bevis på din framgång.",al={"behåller jag boken","belöning från tome of the cabal","behålla tome of the cabal"}},{q="Kan du frammana felhuntern var som helst i världen?",a="Nej. Du måste läsa upp besvärjelserna i Strahad Farsans helgedom ovanför Ratchet, där han och hans akolyter upprätthåller de större och mindre åkallandecirklar som behövs för att hålla det anländande odjuret fånget.",al={"frammana felhunter var som helst","var läsa tome","plats för tomeritualen"}}},fx={["42bf8406"]={q="Vad är Tome of the Cabal?",a="Tome of the Cabal är en esoterisk grimoar med särskilda demoniska ritualer och besvärjelser. Strahad Farsan ovanför Ratchet anförtror boken åt erfarna häxmästare. Den beskriver de farliga ritualer som krävs för att öppna en port till Nether och tvinga en våldsam felhunter att lyda dig.",al={"vad är tome of the cabal","berättelsen om tome of the cabal","om tome of the cabal"}},a251072b={q="Var kommer Tome of the Cabal ifrån, och vem skapade den?",a="Boken skrevs av den första grupp häxmästare som lyckades frammana en felhunter utan hjälp. Den fanns en gång i Lordaeron, men vandaliserades och delades i en Moldy Tome och ett Tattered Manuscript. En häxmästare hittar delarna vid Hillsbrads kust och hos centaurerna i Thousand Needles och tar sedan den återställda boken till Strahad Farsan.",al={"vem skapade tome of the cabal","var kommer tome of the cabal ifrån","skaparen av tome cabal"}},["03fa6157"]={q="Varför vill någon ha Tome of the Cabal?",a="Blivande häxmästare söker efter Tome of the Cabal eftersom den innehåller den exakta besvärjelse som krävs för att kalla fram en feljägare i en förberedd kallelsecirkel. Utan bokens exakta ord vore det i det närmaste omöjligt att kuva en av dessa farliga, manaslukande vidunder.",al={"varför vill någon ha tome of the cabal","varför vill häxmästare ha tome of the cabal","syftet med tome of the cabal"}}},fp="30,206,23.376.0,20.323.0,39.175.0,35.157.0,49.145.0,51.193.0"}
P.entries["item:top-of-gelkak-s-key"] = {n="Top of Gelkak's Key",s="Top of Gelkak's Key är en av tre krossade delar av en mekanisk nyckel som tillhörde den skeppsbrutne gnomen Gelkak Gyromast. När hans skepp förliste utanför Darkshores kust plockades den här taggiga mässingsdelen upp av en jättelik foreststrider som strövade i skogarna i närheten.",h="Top of Gelkak's Key är en av tre krossade delar av en mekanisk nyckel som tillhörde den skeppsbrutne gnomen...",kw={"darkshore","styrman","foreststrider","gelkak","gyromast","nyckel","pirat","återhämtning"},ang={["profession:Engineering"]="Nyckeln är konstruerad för att dra upp och aktivera en urverksautomat och visar den sinnrika och robusta mekaniska hantverksskicklighet som är typisk för gnomuppfinnare.",["race:Gnome"]="Att se en gnom överleva ett katastrofalt skeppsbrott tack vare ren excentricitet och urverksmanicker är en välbekant och älskvärd syn."},sec={{t="En krossad mekanism",b="När Gelkak Gyromasts skepp anfölls och sänktes av glupska threshadons utanför Darkshores kust spolades gnomen upp på land med uppdragningsnyckeln till sin mekaniska styrman i famnen. Smällen mot kustklipporna bröt sönder nyckeln i tre delar. Innan den omtumlade piraten hann samla sig började de inhemska bestarna söka igenom vraket, och en jättelik foreststrider bar i väg med den här utsmyckade övre delen in i den dimmiga skogen."},{t="Återställa styrmannen",b="Nyckeln behövs för att dra upp och aktivera Gelkaks mekaniska styrman, en automat som den strandade gnomen tänker använda för att hämnas på traktens djurliv. Om Gyromast får tag i den här delen och mitt- och bottendelen, som stals av strandmurlocker respektive revkrypare, kan han sätta ihop apparaten och väcka sin konstruktion till liv."}},faq={{q="Vad används Top of Gelkak's Key till?",a="Det är en av tre trasiga delar som den skeppsbrutne gnompiraten Gelkak Gyromast behöver för att laga sin mekaniska uppdragningsnyckel. När den är ihopsatt används nyckeln för att återaktivera hans mekaniska styrman.",al={"vad gör gelkaks nyckel","användning av top of gelkaks key","gelkaks nyckels syfte"}},{q="Hur fick en foreststrider tag i den här nyckeldelen?",a="När Gelkak led skeppsbrott och spolades upp på Darkshores stränder slogs hans nyckel sönder mot klipporna. Nyfikna bestar började genast rota bland vrakdelarna, och en jättelik foreststrider svalde eller bar i väg med mässingsdelen från toppen till skogen nordost om stranden.",al={"varför har tallstriders nyckeln","vem tog toppen av gelkaks nyckel","hur fick foreststrider tag i nyckeln"}},{q="Var finns nyckelns andra delar?",a="Mittdelen snappades upp av Greymist-murlocker som hemsöker skeppsvraket i närheten, medan bottendelen bars i väg av krabborna som letar längs strandkanten.",al={"var finns nyckelns andra delar","gelkaks nyckels mitt och botten","gelkaks nyckelfragment"}},{q="Vem är Gelkak Gyromast?",a="Gelkak Gyromast är en excentrisk gnompirat som blev strandad längs Darkshores kust efter att threshadons slog sönder hans skepp. Han är strandsatt och rasande och smider planer på hämnd mot kustens varelser.",al={"vem är gelkak","gelkak gyromasts bakgrund"}}},fx={["7697c1f6"]={q="Vad är Top of Gelkak's Key?",a="Det är ett av tre trasiga fragment av en specialnyckel som tillhör skeppsbrutne gnomem Gelkak Gyromast. När hans fartyg gick under utanför Darkshores kust splittrades nyckeln mot den klippiga strandlinjen. Just den här övre delen plockades upp av traktens jättelika skogsvandrare som strövar omkring i skogarna intill.",al={"top of gelkak's key","vad är gelkak's keys topp","gelkak's key-fragment"}}},fp="19,189,21.376.0,24.303.1,41.179.0,50.201.0,38.126.0,23.163.0"}
P.entries["item:torch-of-the-dormant-flame"] = {n="Torch of the Dormant Flame",s="Vid Shrine of the Dormant Flame gör en schaman sig redo att tända Torch of the Dormant Flame. Den släckta facklan väntar på en eldandens glöd, som du vinner på en bergstopp i Durotar.",h="Vid Shrine of the Dormant Flame gör en schaman sig redo att tända Torch of the Dormant Flame.",kw={"call of fire","durotar","fire sapta","schaman","shrine of the dormant flame","telf joolam","torch of the dormant flame"},ang={["class:Shaman"]="Som schaman börjar du med en oprövad fackla. Besegra en levande eldmanifestation för att tända den och förtjäna rätten att åkalla en Fire Totem."},sec={{t="Uppvaknandets kärl",b="En schaman som söker eldens gunst bär den släckta Torch of the Dormant Flame uppför bergstopparna ovanför Durotar. Fire sapta låter schamanen se en Minor Manifestation of Fire på bergstoppen och utmana den. När anden faller lägger schamanen dess Glowing Ember i den väderbitna fyrfatet vid Shrine of the Dormant Flame. Schamanen för facklans huvud mot den vitglödgade lågan, och träet vaknar som ett brinnande tecken på elementär mästerskap."}},faq={{q="Vad är syftet med Torch of the Dormant Flame?",a="Schamaner som genomför prövningen Call of Fire får den släckta ceremoniella facklan. När en eldmanifestation har besegrats läggs dess glöd i helgedomens fyrfat, och facklan doppas i de vitglödgade lågorna för att tändas med elementär kraft.",al={"vad är torch of the dormant flame","varför har jag en otänd fackla","vad gör facklan"}},{q="Var tänds facklan?",a="Facklan tänds på bergstoppen nära Telf Joolam i Durotar, vid fyrfatet i Shrine of the Dormant Flame, efter att Minor Manifestation of Fire har besegrats.",al={"var tänder man torch of the dormant flame","shrine of the dormant flame fackla","hur tänder man den slumrande facklan"}},{q="Vem ger den otända facklan?",a="Kranal Fiss, schamanen som bor norr om The Crossroads, ger noviser den släckta facklan och skickar dem till Telf Joolam, som vakar över Shrine of the Dormant Flame. Telf Joolam känner igen den som ett tecken på att någon försöker tämja elden.",al={"vem ger torch of the dormant flame","den slumrande facklans ursprung","vem ger facklan i call of fire"}}},fx={["5b4644ae"]={q="Vad är Torch of the Dormant Flame?",a="Det är en ceremoniell, otänd fackla tillverkad för en schamans prövning under Call of Fire. Den är gjord för att ta emot den vilda essensen från elementareld och förblir helt kall och slumrande tills den sänks ner i den vigda eldfatet högst upp vid Shrine of the Dormant Flame, där den tänds av essensen från en besegrad elduppenbarelse.",al={"torch of the dormant flame","vad är torch of the dormant flame","facklan med den slumrande lågan"}},c6982489={q="Varför behöver Telf Joolam Torch of the Dormant Flame?",a="Facklan fungerar som ett kärl för att fånga in och bevisa att du behärskar elden. När du tänder dess slumrande spets i det heliga eldfatet med glöden från en besegrad uppenbarelse binder du den elementära gnistan till en låga som går att bära med sig. När du bär tillbaka den nytända facklan fullbordar du din andliga förening med eldelementet.",al={"varför behövs torch of the dormant flame","varför vill någon ha den slumrande facklan","syftet med facklan med den slumrande lågan"}}},fp="26,180,19.432.0,54.247.0,30.165.0,29.231.0"}
P.entries["item:torn-fin-eye"] = {n="Torn Fin Eye",s="Torn Fin Eyes är ögonorgan som skördas från Torn Fin-murlocer som stryker längs Hillsbrad Foothills kust. De är en viktig reaktiv ingrediens i Royal Apothecary Societys mörka alkemiska forskning om nya plågor.",h="Torn Fin Eyes är ögonorgan som skördas från Torn Fin-murlocer som stryker längs Hillsbrad Foothills kust.",kw={"apothecary lydon","elixir of agony","hillsbrad foothills","murloc","royal apothecary society","torn fin","torn fin eye","undercity"},ang={["faction:Horde"]="Insamling av dessa kustreagenser bidrar till Hordens krigsinsats i Hillsbrad Foothills och stärker Forsakens fäste mot fientliga Alliance-intrång från Southshore.",["race:Undead"]="Att skaffa organiska katalysatorer som Torn Fin Eyes för Royal Apothecary Society närmare sin yttersta ambition: att fullända en plåga som utplånar både Scourge och de levande."},sec={{t="Ett reagens för fördärv",b="Royal Apothecary Society låter sällan någon vidrig biologisk beståndsdel gå till spillo i sin strävan att utveckla Forsaken's New Plague. Torn Fin Eyes, som skördas från de saltstänkta murlocer som stryker längs Western Strand i Hillsbrad Foothills, har särskilda organiska egenskaper som behövs för att aktivera flyktiga alkemiska föreningar. Tillsammans med Daggerspine-nagfjäll, återställande trollbrygder och gnollslam hjälper ögonvävnaden till att stabilisera och utlösa giftiga blandningar, framställda för att sprida död över fiendens områden."},{t="Att brygga pina",b="I Undercitys Apothecarium upptäckte mästeralkemister att tillsats av ruttnande kolloider till Mudsnout-blandningar krävde katalysatorer som bara fanns längs Hillsbrads kust. Apothecary Lydon i Tarren Mill förlitar sig på dessa skördade ögon för att katalysera sin ökända Elixir of Agony. Brygden är ett av Forsakens obevekliga experiment för att framställa förödande biologiska vapen mitt framför näsan på närliggande mänskliga bosättningar."}},faq={{q="Vad används ett Torn Fin Eye till?",a="Torn Fin Eyes är en alkemisk katalysator som Royal Apothecary Society söker efter. Apothecary Lydon i Tarren Mill använder dem tillsammans med Daggerspine Scales och en Strong Troll's Blood Elixir för att aktivera de förorenande ämnena i en flyktig Mudsnout Mixture och föra sin forskning om nya dödliga plågor framåt.",al={"torn fin eye användning","varför samla torn fin eyes","torn fin eye syfte"}},{q="Var hittar du Torn Fin Eyes?",a="De skördas från Torn Fin-murlocer som lever vid Western Strand i Hillsbrad Foothills, längs kusten väster om människornas stad Southshore.",al={"var få tag på torn fin eyes","torn fin eye plats","vem släpper torn fin eye"}},{q="Vem beordrar att ögonen samlas in?",a="Forsaken-forskare i Undercity och Apothecary Lydon, som är stationerad i Tarren Mill, behöver dem för att färdigställa brygden som kallas Elixir of Agony.",al={"vem behöver torn fin eyes","uppdragsgivare för torn fin eye"}},{q="Varför behöver Royal Apothecary Society delar från murlocer?",a="Sällskapets forskare experimenterar ständigt med märklig lokal fauna för att hitta föreningar som aktiverar eller förstärker giftiga föroreningar. Torn Fin-murlocernas fysiologi ger ögonvätskor som kan katalysera flyktiga plågprototyper.",al={"varför murlocögon","apotekare och murlocer"}}},fx={edd43501={q="Vad är Torn Fin Eye?",a="Torn Fin Eye är ett alkemiskt reagens som utvinns från kustens murlocker som stryker längs stränderna i Hillsbrad Foothills. Dessa ögon är trögflytande och mättade av groddjurens kroppsvätskor. De används av de Fördömdas alkemister, som behöver biologiska katalysatorer för att väcka flyktiga, förorenande ämnen i sina experimentblandningar.",al={"vad är torn fin eye","information om torn fin eye","om torn fin eyes"}},["3427cbae"]={q="Var kommer Torn Fin Eyes ifrån?",a="De här organiska reagenserna skärs loss från murlockerna i Torn Fin-stammen, som bor vid Western Strand längs södra kusten i Hillsbrad Foothills, strax väster om människornas bosättning Southshore. De är naturliga kroppsdelar som tas direkt från dödade murlocker, inte tillverkade föremål.",al={"torn fin eye-källa","var får man torn fin eyes","vem släpper torn fin eye"}}},fp="12,144,18.443.0,13.345.1,32.276.0,32.133.0,39.120.0,56.184.0"}
P.entries["item:torn-murloc-fin"] = {n="Torn Murloc Fin",s="I östra Elwynn visar Torn Murloc Fins att Stormwind Army får gensvar på sin belöning. De har tagits från födosökare och lurpassare längs flodbankarna och visar att de lokala vattendragen rensas systematiskt.",h="I östra Elwynn visar Torn Murloc Fins att Stormwind Army får gensvar på sin belöning.",kw={"belöning för murlocs","murlocs i elwynn","guard thomas","murloc fin","murlocfödosökare","murloclurpassare","stone cairn lake","torn murloc fin"},ang={["faction:Alliance"]="För Alliansen skyddar rensningen av östra Elwynns vattendrag viktiga färdvägar mellan Goldshire, Lakeshire och Stormwind City.",["race:Human"]="Som människa vet du att de lokala myndigheterna allt oftare förlitar sig på legosoldater för att skydda gårdar och flodbankar från aggressiva murlocbosättningar."},sec={{t="Ett belönat hot",b="Murlocs har blivit många längs östra Elwynns bäckar och sjöar, och Stormwind Army erbjuder en belöning för att minska deras antal. Guard Thomas, som håller uppsikt över bron över den östra floden, samlar in de avskurna fenorna som bevis på dödade murlocs. Stormwinds soldater är hårt ansatta av oroligheter på hemmaplan och hot i närheten, så de lokala myndigheterna är beroende av resande som kan visa att murlocläger har rensats."}},faq={{q="Vem köper eller samlar in Torn Murloc Fins?",a="Guard Thomas samlar in Torn Murloc Fins vid Elwynn Forests östra bro åt Marshal Dughan och Stormwind Army.",al={"vem vill ha fenor","lämna in fenor","guard thomas fenor"}},{q="Var finns murlocsen som bär på de här fenorna?",a="Fenorna kommer från murlocfödosökare och lurpassare kring Stone Cairn Lake i norr och den södra bäckförgreningen nära östra Elwynns gräns.",al={"var man hittar fenor","murlocfenornas platser","fenor som byte"}},{q="Varför kräver Stormwind fenor som bevis?",a="Fenor är omisskännliga och lätta att bära, så Stormwind Army får fysiska bevis på dödade murlocs innan belöningsjägarna får betalt.",al={"varför fenor","bevis på dödade murlocs","bevis för belöning"}},{q="Varför betalar Stormwind Army för döda murlocs?",a="Murlocbyar har snabbt spridit sig längs vattendragen och hotar resande, fiskare och lokal infrastruktur, samtidigt som Stormwind Armys styrkor är upptagna på annat håll.",al={"varför belöning för murlocs","murlocproblem i elwynn"}}},fx={afa68c63={q="Vad är Torn Murloc Fin?",a="Torn Murloc Fin är en fysisk trofé som skurits loss från skinnet på murlocker som hemsöker östra Elwynn Forest. Den är varken en prydnadssak eller en alkemisk ingrediens, utan ett konkret bevis på att en kringströvande groddjursrövare har dödats. Den ger lokala myndigheter som utfärdar belöningar en tillförlitlig bekräftelse.",al={"vad är torn murloc fin","lore om torn fin","om murloc fin"}},["5ee7d3aa"]={q="Var kommer Torn Murloc Fins ifrån?",a="Fenorna tas direkt från kropparna av murlockfiskare och smygare som håller till i Elwynn Forests grunda sötvatten. Särskilt aggressiva stammar har slagit läger längs stränderna vid Stone Cairn Lake och den södra förgreningen av de östra floderna, där de hotar lokala resande och gårdar.",al={"torn murloc fin-ursprung","var kommer murlocfenor ifrån","källa till torn murloc fin"}}},fp="15,108,17.368.0,38.116.0,50.142.0,41.127.0,50.168.0"}
P.entries["item:totem-of-hawkwind"] = {n="Totem of Hawkwind",s="Totem of Hawkwind är ett snidat tecken som unga tauren bär med sig när de lämnar Camp Narache. När det överlämnas till Baine Bloodhoof i Bloodhoof Village visar det att bäraren har klarat sina första prövningar och är redo att genomgå resten av Earthmothers riter.",h="Totem of Hawkwind är ett snidat tecken som unga tauren bär med sig när de lämnar Camp Narache.",kw={"baine bloodhoof","bloodhoof village","camp narache","chief hawkwind","hawkwind","earthmothers riter","totem"},ang={["race:Tauren"]="Att bära denna totem markerar den avgörande övergången från barndomen på Red Cloud Mesa till de större stamområdena i Mulgore."},sec={{t="En hövdings intyg",b="Chief Hawkwind har snidat denna trätotem på Red Cloud Mesa. Den fungerar som en introduktion och ett bevis på att de unga har nått myndig ålder. I tauren-traditionen används formella skrivelser sällan. I stället förmedlar betydelsefulla symboler och välbekant stamhantverk en ledares avsikt. När en ung tauren klarar sina inledande prövningar i Camp Narache snidar Hawkwind denna symbol och skickar dem vidare längs vägen ut i Mulgore. De särpräglade ristningarna gör att Baine Bloodhoof känner igen bäraren och visar att hen har den anda och styrka som krävs för att möta nästa prövningar och så småningom söka Thunder Bluffs välsignelse."}},faq={{q="Vad används Totem of Hawkwind till?",a="Den fungerar som ett tecken på att bäraren har klarat sina första prövningar. Unga tauren tar den från Camp Narache till Bloodhoof Village för att visa Baine Bloodhoof att Chief Hawkwind har bedömt dem redo att fortsätta Earthmothers riter.",al={"vad gör totem of hawkwind","totem of hawkwind syfte","varför har jag den här totemen"}},{q="Vem gjorde totemen?",a="Chief Hawkwind snidar totemen själv. Han leder bosättningen på Red Cloud Mesa. Hövdingar i andra delar av Mulgore känner genast igen dess särpräglade ristningar.",al={"vem snidade totemen","totemens skapare","totem of hawkwinds ursprung"}},{q="Vem tar emot Totem of Hawkwind?",a="Den överlämnas till Baine Bloodhoof, son till Cairne Bloodhoof, som styr Bloodhoof Village öster om Red Cloud Mesa.",al={"vem ska jag ge totemen till","totemens mottagare","vart ska totemen"}},{q="Varför använda en totem i stället för ett brev?",a="Tauren-kulturen bygger i hög grad på muntlig tradition, hantverk och förfädernas symboler. En snidad totem bär personlig prägel och ande från hövdingen som format den. Bland stamhövdingar väger den därför långt tyngre än bläck på pergament.",al={"varför inte ett brev","tauren-traditioner kring tecken"}}},fx={["0f3f23e4"]={q="Vad är Totem of Hawkwind?",a="Totem of Hawkwind är en snidad introduktionsgåva som anförtros åt lovande unga taurer som har klarat sina första prövningar i Red Cloud Mesa. Den bär Chief Hawkwinds särskilda märken och visar att du är redo att lämna Camp Narache och genomgå Moder Jords vidare riter.",al={"totem of hawkwinds identitet","vad är det här totemet","hawkwind-totem"}},bb2bdc29={q="Varför vill Baine Bloodhoof ha Totem of Hawkwind?",a="Baine Bloodhoof söker efter totemet som ett otvetydigt tecken på att du är redo och har rätt karaktär. Det är snidat av Chief Hawkwind, och mönstren visar Baine att en ung aspirant har förtjänat Hawkwinds personliga rekommendation att fortsätta sina andliga prövningar och söka acceptans hos Thunder Bluffs äldste.",al={"varför vill baine ha totemet","varför ge totemet till baine","baine bloodhoofs totem"}}},fp="17,243,25.574.0,39.222.0,19.124.0,35.120.0,36.201.0"}
P.entries["item:tough-wolf-meat"] = {n="Tough Wolf Meat",s="Vargar stryker omkring i Northshire och Coldridge och lämnar efter sig rå Tough Wolf Meat åt hungriga lokalbor. Det är grovt och segt, men föder folk i Elwynn Forest och förser dvärgarnas utrustningshandlare i Dun Morogh.",h="Vargar stryker omkring i Northshire och Coldridge och lämnar efter sig rå Tough Wolf Meat åt hungriga...",kw={"dun morogh","eagan peltskinner","elwynn forest","northshire abbey","skogsvarg","tough wolf meat","ung varg"},ang={["race:Dwarf"]="Som dvärg i Coldridge Valley kan du gallra bland raggiga skogsvargar och samla kött åt de lokala utrustningshandlarna innan du ger dig av genom Dun Morogh.",["race:Human"]="Som människorekryt i Northshire Valley kan du samla vargkött åt Eagan Peltskinner utanför klostret. Det är en av de första överlevnadsuppgifterna bortom de fridfulla klostergångarna."},sec={{t="Ransoner vid gränsen",b="Vargar stryker omkring nära Northshire Valley och Dun Morogh, hotar närliggande bosättningar och erbjuder en svårfångad källa till mat. Köttet är grovt, segt och svåruggat, men folk vid gränsen med knappa resurser värdesätter det. Utanför Northshire Abbey avskyr Eagan Peltskinner de våldsamma bestarna, men tillagar deras kött till biffar. Han byter grundläggande förnödenheter och utrustning mot att någon gallrar bland flockarna."}},faq={{q="Varifrån kommer Tough Wolf Meat?",a="Genom att jaga unga vargar och skogsvargar i Northshire Valley i Elwynn Forest, samt raggiga vargar i Coldridge Valley i Dun Morogh, får man Tough Wolf Meat.",al={"tough wolf meat källa","hur får man tough wolf meat","var kan man samla tough wolf meat"}},{q="Vem vill samla in köttet i Elwynn Forest?",a="Eagan Peltskinner, utanför Northshire Abbey, samlar in köttet. Han avskyr vargarna men tillagar deras kött till biffar och byter bort utrustning som blivit över mot åtta köttbitar från nyrekryter.",al={"vem behöver vargkött","eagan peltskinner kött","lämna in vargkött"}},{q="Är köttet användbart utanför människornas länder?",a="Ja. Dvärgarnas utrustningshandlare i det iskalla Dun Morogh tar emot kött från raggiga vargar i Coldridge Valley för att hålla sina förråd fyllda.",al={"vargkött dun morogh","dvärg vargkött","dvärgarnas utrustningshandlare kött"}},{q="Används Tough Wolf Meat i vanliga matlagningsrecept?",a="Nej. Tough Wolf Meat är en belöning för lokala gränsbor som Eagan Peltskinner och utrustningshandlarna i Coldridge, inte en ingrediens i vanliga lägerrecept.",al={"kan man tillaga tough wolf meat","tough wolf meat recept"}}},fx={["877dd280"]={q="Vad är Tough Wolf Meat?",a="Det är grovt, magert kött från vilda vargar som strövar omkring i Northshires och Dun Moroghs vildmarker. Det är segt och långt ifrån mört, men utgör stadig föda för lokala fälljägare och hungriga nybyggare som vet hur de ska tillaga det till mättande stekar.",al={"vad är tough wolf meat","lore om tough wolf meat","tough wolf meat"}}},fp="15,231,16.376.0,37.157.0,48.186.0,43.127.0,50.165.0"}
P.entries["item:tourmaline-phial"] = {n="Tourmaline Phial",s="Tourmaline Phial är ett särskilt kärl av ädelsten som Corithras Moonrage ger resande i Teldrassil. Det används för att hämta välsignat vatten från månkällan vid Pools of Arlithrien, som en del av pågående ritualer för att övervaka och lugna världsträdets grenar.",h="Tourmaline Phial är ett särskilt kärl av ädelsten som Corithras Moonrage ger resande i Teldrassil.",kw={"corithras moonrage","crown of the earth","dolanaar","månkälla","pools of arlithrien","teldrassil","tourmaline phial"},ang={["class:Druid"]="Att bära särskilda ädelstensflaskor för att samla vatten från månkällor är en viktig ceremoniell plikt för unga nattalvdruider som lär sig att vårda Teldrassils känsliga ekosystem.",["race:NightElf"]="Vattnet som samlas i kärl som Tourmaline Phial står för nattalvernas beroende av Elunes nåd och druidernas vaksamhet medan Teldrassil kämpar mot korrumpering."},sec={{t="Kärlet från Arlithrien",b="Corithras Moonrage tillhandahåller Tourmaline Phial för att hjälpa till med ritualerna kring världsträdet. Druiderna i Dolanaar använder sådana särskilda ädelstensflaskor för att samla rent vatten från månkällor runt om i Teldrassil. Just den här flaskan är avsedd för månkällan vid stränderna kring Pools of Arlithrien, sydost om vägen som leder till Darnassus, ett område som allt oftare plågas av fientliga Gnarlpine furbolgs."}},faq={{q="Vad används Tourmaline Phial till?",a="Flaskan används för att samla heligt vatten från månkällan vid Pools of Arlithrien. När den har fyllts måste den återlämnas till Corithras Moonrage i Dolanaar som en del av Crown of the Earth-ritualerna.",al={"vad gör tourmaline phial","tourmaline phials syfte","använd tourmaline phial"}},{q="Vem tillhandahåller Tourmaline Phial?",a="Corithras Moonrage, en nattalvdruid stationerad i staden Dolanaar, anförtror äventyrare den tomma flaskan.",al={"vem ger tourmaline phial","var får jag tourmaline phial"}},{q="Var ligger månkällan för den här flaskan?",a="Månkällan ligger vid stränderna kring Pools of Arlithrien, sydost om huvudporten som leder till Darnassus.",al={"pools of arlithrien månkällan","var fyller jag tourmaline phial"}}},fx={["6b01991a"]={q="Vad är Tourmaline Phial?",a="Tourmaline Phial är ett tomt, ceremoniellt kärl som tillverkats för att hämta och transportera heligt vatten från månkällorna över hela Teldrassil. Du får det av Corithras Moonrage i Dolanaar. Det är särskilt avsett för att samla vatten från den avskilda månkällan nära Pools of Arlithrien.",al={"vad är tourmaline phial","lore om tourmaline phial","tourmaline-flaska"}},["001b9aba"]={q="Varför vill Corithras Moonrage att Tourmaline Phial fylls?",a="Corithras Moonrage behöver vatten från var och en av Teldrassils månkällor för att studera och bedöma världsträdets och dess helgedomars hälsa. Det har blivit farligt att hämta vatten från månkällan vid Pools of Arlithrien på grund av våldsamma Gnarlpine-furbolgers aktivitet, så han förlitar sig på dugliga resande för att hämta ett prov säkert.",al={"varför fylla tourmaline phial","tourmaline phials syfte","varför vill corithras ha flaskan"}}},fp="16,105,20.352.0,38.185.0,34.83.0,37.93.0"}
P.entries["item:toxic-fogger"] = {n="Toxic Fogger",s="Toxic Fogger är en specialanordning för spridning, fylld med dödligt gift som framställts av Forsaken Royal Apothecary Society. Den är utformad för att förorena Venture Companys lufttransporter i Stonetalon Mountains.",h="Toxic Fogger är en specialanordning för spridning, fylld med dödligt gift som framställts av Forsaken Royal...",kw={"apothecary zamah","helikopterplatta","cragpool lake","flyghamn","stonetalon","toxic fogger","venture company"},ang={["race:Tauren"]="Att förlita sig på dödliga ångor kan pröva taurenfolkets traditionella hederskod, men Venture Companys katastrofala industriella skador får många i Thunder Bluff att tolerera Zamahs hårda åtgärder.",["race:Undead"]="Toxic Fogger är ett typiskt exempel på Royal Apothecary Societys fältstrategi: att störa fiendens försörjningskedjor med gift i aerosolform och visa bundsförvanter att mörka metoder ger obestridliga resultat."},sec={{t="En lösning från Forsaken",b="Toxic Fogger innehåller ett gift som bryggts av Apothecary Lydon i Tarren Mill och skickats av Apothecary Zamah i Thunder Bluff. Den används för biologiskt sabotage direkt mot Venture Companys gruvdrift. Zamah misstänker att goblinerna använder kurirflygmaskiner för att transportera meddelanden och lätt last mellan Stonetalon och sitt högkvarter. Därför skickar hon dimspridaren för att släppa ut giftet där maskinerna landar och tankar. I stället för långdragna skärmytslingar med ändlösa legosoldater slår Forsaken-metoden mot operationens logistiska ryggrad och ser till att giftet förs direkt tillbaka till företagsledningen."},{t="Sabotage vid Cragpool Lake",b="Målet för Toxic Fogger är den avskilda helikopterplattan nära Cragpool Lake. Den ligger högt ovanför de avskogade kullarna och vaktas av företagets hantlangare. Landningsplattan fungerar som en luftburen länk mellan avlägsna arbetslag och knutpunkter utanför området. När dimspridaren utlöses sveper ett giftigt moln över uppställningsplatsen och överrumplar återvändande piloter. En del av Horde kanske ryggar tillbaka inför att ta till gift, men Zamah uppmanar sina agenter att släppa skuldkänslorna. Hon hävdar att ingen väg är för mörk om den säkrar seger över utsugarna."}},faq={{q="Vad används Toxic Fogger till?",a="Toxic Fogger används för att förgifta Venture Companys flyghamn vid Cragpool Lake i Stonetalon Mountains och förorena lätt last och kurirer på väg tillbaka till företagets högkvarter.",al={"vad gör toxic fogger","dimsprejarens syfte","varför använda toxic fogger"}},{q="Vem skapade Toxic Fogger?",a="Giftet bryggdes av Apothecary Lydon i Tarren Mill av oskyldigas blod. Apothecary Zamah, ett sändebud för Royal Apothecary Society som är stationerat vid The Pools of Vision under Thunder Bluff, skickar sedan iväg den för leverans.",al={"vem skapade dimspridaren","dimsprejarens skapare","apothecary zamahs gift"}},{q="Var ska Toxic Fogger placeras?",a="Den ska placeras ovanpå Venture Companys upphöjda helikopterplatta nära Cragpool Lake i Stonetalon Mountains, söder om det stora vattenhjulet.",al={"var ska jag placera dimspridaren","helikopterplattans plats","flyghamnens plats"}},{q="Varför tar Horde till gift mot Venture Company?",a="Venture Companys skogsavverkning och gruvdrift skövlar marken i Stonetalon svårt. Apothecary Zamah anser att vanlig strid går för långsamt och menar att Horde måste ta till hänsynslösa metoder för att utplåna goblinerna innan skadan blir oåterkallelig.",al={"varför förgifta gobliner","är gift tillåtet inom horde","forsakens metoder i stonetalon"}}},fx={["3a36a6bd"]={q="Vad är Toxic Fogger?",a="Toxic Fogger är en specialiserad spridningsanordning fylld med en dödlig blandning som tillverkats av de Fördömda. Den är utformad för att släppa ut ett giftigt moln när den används och fungerar som ett sabotagevapen avsett att förorena Venture Companys logistiknät och störa deras verksamhet i Stonetalon.",al={"vad är toxic fogger","föremålet toxic fogger","anordningen toxic fogger"}},bbff0049={q="Varför vill apotekare Zamah att Toxic Fogger används?",a="Apotekare Zamah tänker slå direkt mot Venture Companys försörjningskedja. Om du använder dimspridaren vid deras lilla luftskeppshamn kan giftet täcka flygmaskiner och last som ska ge sig av. Då förs giftet tillbaka till goblinernas högkvarter och ger dem ett förödande straff för deras ohejda exploatering.",al={"varför använda toxic fogger","varför vill någon ha toxic fogger","varför behövs toxic fogger"}}},fp="12,191,19.497.0,25.448.1,34.196.0,29.204.0,46.146.0,70.223.0"}
P.entries["item:translated-letter"] = {n="Translated Letter",s="The Translated Letter är ett dechiffrerat meddelande, skrivet av eremiten Abercrombie och översatt av Sirra Von'Indi i Darkshire till borgmästaren Ello Ebonlocke.",h="The Translated Letter är ett dechiffrerat meddelande, skrivet av eremiten Abercrombie och översatt av Sirra...",kw={"abercrombie","darkshire","letter to ello","lord ello ebonlocke","sirra von'indi","translated letter"},ang={["faction:Alliance"]="Brevet markerar en förödande stund då Alliansens resenärer i Duskwood tvingas inse att även de renaste avsikter kan användas som vapen mot Darkshires sårbara försvarare."},sec={{t="En fruktansvärd insikt",b="Det som började med barmhärtiga ärenden åt en till synes hjälplös eremit i Raven Hill tar en mörk vändning med det här pergamentet. Abercrombies meddelande till borgmästaren Ello Ebonlocke var skrivet med en svårtydd handstil och förblev en gåta tills det lämnades till Sirra Von'Indi för översättning. Den dechiffrerade texten avslöjar eremitens sanna identitet: The Embalmer. Abercrombie levde inte i ofarlig ensamhet, utan använde förnödenheterna som fördes till honom för att skapa en monstruös styggelse vid namn Stitches och släppte lös den väldiga varelsen för att trampa ihjäl och slakta Darkshires invånare."},{t="Priset för goda avsikter",b="När det översatta brevet överlämnas till Lord Ello Ebonlocke försvinner all färg från borgmästarens ansikte. Resenären erbjöd sin hjälp av genuin välvilja, men brevet bevisar att Abercrombie lurade dem och utnyttjade deras arbete för att skapa ett redskap för urskillningslös slakt. Medan stadsrådet febrilt försöker samla Night Watch blir det dechiffrerade brevet ett skrämmande vittnesmål om hur lätt välgörenhet kan förvandlas till förödelse längs Duskwoods hemsökta vägar."}},faq={{q="Vad står det i Translated Letter?",a="Det innehåller ett alarmerande meddelande från Abercrombie till Lord Ello Ebonlocke. Hela innehållet avslöjas när det översatta brevet lämnas över i Darkshire.",al={"brevets innehåll","vad skrev abercrombie","vad står det"}},{q="Vem översätter brevet?",a="Sirra Von'Indi, en lärd person som bor i Darkshire, översätter Abercrombies kryptiska handstil och varnar dig att skynda tillbaka till Lord Ello med de alarmerande nyheterna.",al={"vem översätter det","vem dechiffrerade brevet","sirra von indi brev"}},{q="Vad händer när Ello läser brevet?",a="Ello blir djupt bestört av översättningen. Ta brevet till honom för att få veta vad det innebär för Darkshire.",al={"ellos reaktion","lämna in översatta brevet","vad händer efter översättningen"}},{q="Kan jag kasta bort Translated Letter efter uppdraget?",a="Ja. När Lord Ello har granskat pergamentet och stärkt stadens försvar ligger brevet kvar i din packning som souvenir och har ingen ytterligare funktion.",al={"kan översatta brevet tas bort säkert","kan jag förstöra översatta brevet","behålla översatta brevet"}}},fx={ad927ea8={q="Vad är Translated Letter?",a="Translated Letter är ett olycksbådande brev som eremiten Abercrombie skrev och Sirra Von'Indi dechiffrerade. Det avslöjar de fasansfulla följderna av Abercrombies mörka planer i Raven Hill och är en direkt varning om den annalkande undergång som hotar folket i Darkshire.",al={"translated letter","vad är translated letter","om translated letter"}},["7688c5ef"]={q="Varför behöver Lord Ello Ebonlocke Translated Letter?",a="Lord Ello Ebonlocke, borgmästaren i Darkshire, måste läsa det dechiffrerade innehållet för att förstå den allvarliga fara som hotar hans stad. Brevet avslöjar hur fasansfullt Abercrombies verk är och varnar invånarna i förväg om att ett monstruöst vidunder släpar sig rakt mot stadsportarna.",al={"varför ta translated letter till ello","varför vill ello ha translated letter","vem behöver translated letter"}}},fp="17,150,21.549.1,28.489.1,36.156.2,26.158.0,40.96.1,55.163.0"}
P.entries["item:treshala-s-pendant"] = {n="Treshala's Pendant",s="Treshala's Pendant är ett personligt arvegods som knyter samman Treshala Fallowbrook, en Night Elf som bor i Darnassus. Hennes make Heralath bar det med sig till södra Kalimdor, där quilboar slet det från honom när han låg för döden i Razorfen Kraul.",h="Treshala's Pendant är ett personligt arvegods som knyter samman Treshala Fallowbrook, en Night Elf som bor i...",kw={"darnassus","heralath fallowbrook","livet rinner ur honom","quilboar","razorfen kraul","treshala fallowbrook","treshala's pendant"},ang={["faction:Alliance"]="När du för tillbaka den här symbolen till Darnassus får en sörjande änka i Alliansen ett sorgset avslut efter sin fallne utforskare.",["race:NightElf"]="När du återfinner hängsmycket hedrar du en kaldorei som dog långt från Teldrassils trygga grenar, under sina sista tragiska stunder."},sec={{t="En hängivenhetens symbol",b="Hängsmycket symboliserar den djupa äktenskapliga hängivenheten mellan Treshala och Heralath Fallowbrook. Innan han gav sig av på farliga resor från Teldrassil bar Heralath halsbandet nära sig, som en påminnelse om hemmet och sin älskade."},{t="Förlorat bland törnen",b="När Heralath gav sig in i Razorfen Krauls taggiga djup överföll de vilda quilboar hans grupp. En av de betandade försvararna plundrade hängsmycket från honom under hans sista plågsamma stunder. Medan livet rann ur honom önskade Heralath att en äventyrare skulle slita minnessaken från hans mördare och föra både smycket och det tragiska budskapet om hans öde hem till Darnassus."}},faq={{q="Vad är Treshala's Pendant?",a="Det är ett personligt hängsmycke som knyter samman Treshala Fallowbrook. Hennes make Heralath bar det som ett minne av deras förening innan han mötte sitt slut i Razorfen Kraul.",al={"vad är det här för föremål","hängsmycke som knyter samman","vem äger hängsmycket"}},{q="Hur hamnade hängsmycket i Razorfen Kraul?",a="Heralath Fallowbrook bar det under en expedition till Razorfen Kraul. När quilboar överföll honom och tillfogade honom dödliga sår plundrade ett av odjuren halsbandet från hans kropp.",al={"varför är det i rfk","hur gick det förlorat"}},{q="Vem ber om att hängsmycket ska återfinnas?",a="Heralath Fallowbrook själv ber förbipasserande äventyrare att hitta det stulna hängsmycket medan han ligger för döden i Razorfen Kraul. Han vädjar om att det ska återlämnas till hans hustru i Darnassus, tillsammans med beskedet om hans död.",al={"vem ger uppdraget","vem vill ha tillbaka hängsmycket"}},{q="Vem får hängsmycket när det har återfunnits?",a="Hängsmycket lämnas till Heralaths sörjande änka, Treshala Fallowbrook, som bor i Night Elf-huvudstaden Darnassus, uppe på Teldrassil.",al={"vart ska jag ta hängsmycket","vem är treshala"}}},fx={["1ac8940a"]={q="Varför vill man ha Treshala's Pendant?",a="När den döende nattalven Heralath Fallowbrook drar sina sista andetag i Razorfen Kraul är hans sista önskan att få tillbaka denna stulna minnessak. Det är ett kärlekshänge som hans hustru Treshala gav honom. Innan han dör ensam i quilboarernas fäste hoppas han att du ska hämta det från brutorna som tog det och överlämna både hänget och det sorgliga budskapet om hans död till hans hustru i Darnassus.",al={"varför hitta treshala's pendant","varför vill heralath ha hänget","treshala's pendants syfte"}}},fp="18,214,17.191.0,18.335.1,27.153.0,45.168.0,41.167.0,46.128.0"}
P.entries["item:trogg-stone-tooth"] = {n="Trogg Stone Tooth",s="En Trogg Stone Tooth är en hård, mineraliserad tand från Stonesplinter-troggerna som hemsöker kullarna i Loch Modan. Dvärgarnas försvarare använder tänderna som fysiskt bevis på att kringströvande äventyrare minskar antalet trogger vid den södra gränsen.",h="En Trogg Stone Tooth är en hård, mineraliserad tand från Stonesplinter-troggerna som hemsöker kullarna i Loch...",kw={"loch modan","rugelfuss","stonesplinter","trogg-hotet","trogg","trogg stone tooth"},ang={["faction:Alliance"]="Genom att svara på Captain Rugelfuss efterlysning avlastar du direkt viktiga handelsvägar som förbinder dvärgkungadömena med resten av Alliansen.",["race:Dwarf"]="Varje tand som återtas bidrar till att säkra Khaz Modan medan större delen av Ironforges militär är utplacerad utomlands i Alliansens tjänst."},sec={{t="Belöning vid södra porten",b="När Ironforge Reserve satts in vid Alliansfronten är de lokala dvärggarnisonerna hårt ansträngda i Khaz Modan. Vid vakttornet vid den södra porten i Loch Modan kan Captain Rugelfuss inte avvara sina soldater från deras poster för offensiva patruller mot de lurande Stonesplinter-troggerna. I stället utlyser han en stående efterlysning på frivilliga som jagar varelserna i de närliggande kullarna. För att bekräfta att hotet drivs tillbaka kräver Rugelfuss Trogg Stone Teeth som grova, obestridliga bevis på varje fälld best."}},faq={{q="Vem vill ha de här troggstenständerna?",a="Captain Rugelfuss, som är stationerad vid det södra vakttornet längs gränsen till Loch Modan, samlar in dem som bevis på att resenärer jagar Stonesplinter-troggerna.",al={"vem tar emot troggstenständer","rugelfuss tänder","vem behöver stentänder"}},{q="Varför är tänderna gjorda av sten?",a="Trogger har en jordnära, underjordisk fysiologi som speglar deras forntida ursprung i sten. Därför består deras betar och tänder av tungt mineraliserat material som liknar rå sten.",al={"varför stentand","troggers anatomi tänder","är troggtänder stenar"}},{q="Varför kan inte dvärggarnisonen jaga troggerna själva?",a="Ironforge Reserve har mobiliserats för den större krigsinsatsen för Alliansen, vilket lämnar de lokala utposterna underbemannade. Captain Rugelfuss regemente är bundet till bevakningen av den södra porten och kan inte riskera att lämna befästningen obevakad.",al={"varför rugelfuss behöver hjälp","varför slåss inte dvärgar mot trogger","ironforge reserve"}},{q="Vilka trogger har de här tänderna?",a="De samlas in från alla Stonesplinter-trogger som strövar omkring i kullarna och utgrävningarna i Loch Modan, från vanliga grävare och spejare till deras benknäckande krigare och geomantiker.",al={"var hittar man troggstenständer","vem släpper stentänder"}}},fx={d6a17ab5={q="Vad är Trogg Stone Tooth?",a="Trogg Stone Tooth är bokstavligen en stenhård tand som tagits ur käkarna på Stonesplinter-troggerna som hemsöker klipporna i Loch Modan. Tänderna speglar troggernas bisarra, jordbundna natur och tjänar de lokala dvärgförespråkarna som ett otvetydigt fysiskt bevis på att en härjande trogg har oskadliggjorts för gott.",al={"vad är trogg stone tooth","information om trogg stone tooth","troggernas stentand"}}},fp="17,187,27.438.0,34.132.0,32.137.0,58.202.0,31.155.0"}
P.entries["item:troll-charm"] = {n="Troll Charm",s="Troll Charms är heliga andliga amuletter som Darkspear-trollen bär. En samling av dem plundrades nyligen av fientliga Thistlefur-furbolger efter ett bakhåll i de norra delarna av Ashenvale.",h="Troll Charms är heliga andliga amuletter som Darkspear-trollen bär.",kw={"ashenvale","darkspear","mitsuwa","thistlefur hold","thistlefur village","troll charm","zoram'gar outpost"},ang={["faction:Horde"]="Att återta det stulna godset försvagar den aggressiva Thistlefur-stammen och hämnas Horde-resenärer som föll på Ashenvales förrädiska stigar.",["race:Troll"]="För Darkspear-trollen är det en outhärdlig förolämpning mot fallna fränders minne och andar att låta heliga amuletter förbli i vilda furbolgers klor."},sec={{t="Darkspears heliga smycken",b="För Hordens troll är andliga amuletter mycket mer än bara prydnader. Som spejaren Mitsuwa förklarar anses ett troll utan sin amulett vara lika stympat som en ork utan stridsärr. När en grupp Darkspear-fränder färdades mot Zoram'gar Outpost genom Ashenvales täta trädkronor överfölls och slaktades de av de korrumperade Thistlefur-furbolgerna. Deras andar anförtroddes åt livet efter detta, men furbolgerna plundrade de döda och förde bort deras heliga amuletter som troféer. De gömde dem i kistor djupt inne i Thistlefur Hold."}},faq={{q="Vad används Troll Charms till?",a="Troll Charms fungerar som heliga kulturella och andliga skydd för Darkspear-trollen. Att bära sådana talismaner är ett viktigt tecken på personlig och andlig värdighet bland deras folk.",al={"syftet med troll charm","troll charm i berättelsen","varför troll bär amuletter"}},{q="Var finns amuletterna?",a="De ligger inlåsta i kistor utspridda i Thistlefur Hold, ett grottsystem bakom Thistlefur Village i norra Ashenvale.",al={"var finns troll charms","hur hittar man troll charm","var finns trollkistan"}},{q="Varför har furbolgerna amuletterna?",a="En grupp Darkspear-resenärer överfölls och dödades av Thistlefur-klanen innan de hann fram till Zoram'gar Outpost. Furbolgerna genomsökte deras tillhörigheter och behöll amuletterna.",al={"varför furbolgerna har dem","vem stal amuletterna"}},{q="Vem vill ha tillbaka amuletterna?",a="Mitsuwa, ett Darkspear-troll stationerat vid Zoram'gar Outpost på Zoram Strand, vill återfå dem för att återupprätta äran för sina dödade fränder.",al={"vem tar emot amuletterna","mitsuwas uppdrag"}}},fx={["5fe70fe7"]={q="Vad är Troll Charm?",a="Troll Charm är en helig stamamulet som bärs av Darkspear-troll. Amuletterna har stor personlig och andlig betydelse bland troll, och ses som nödvändiga tecken på identitet och status. En troll utan sin amulett anses av sina likar vara som en orch utan stridsärr.",al={"vad är troll charm","föremålet troll charm","helig trollamulett"}},["6d34290e"]={q="Var kommer Troll Charms ifrån, och vem skapade dem?",a="Dessa amuletter tillverkades och bars av Darkspear-troll på väg genom Ashenvale mot Zoram'gar Outpost. Tragiskt nog överfölls och dödades resenärerna längs vägen av fientliga Thistlefur-furbolgs, som plundrade de heliga föremålen och låste in dem i kistor djupt inne i Thistlefur Hold.",al={"troll charms ursprung","vem skapade troll charms","var kommer troll charms ifrån"}},["77137dd7"]={q="Varför vill Mitsuwa ha tillbaka Troll Charms?",a="Mitsuwa i Zoram'gar Outpost sörjer de fallna resenärerna men accepterar att de kommer att återförenas i livet efter detta. Att låta råa och fientliga furbolgs behålla sådana heliga reliker ses dock som en outhärdlig förolämpning mot trollens arv. Att återta dem återupprättar äran i minnet av de stupade.",al={"varför hämta troll charms","varför vill mitsuwa ha amuletterna","varför efterfrågas troll charms"}}},fp="11,184,32.450.0,31.92.0,29.120.0,38.141.0,26.130.0"}
P.entries["item:trophy-swoop-quill"] = {n="Trophy Swoop Quill",s="En Trophy Swoop Quill är en eftertraktad jakttrofé, plockad från de stora rovfåglar som kretsar över Mulgore. Bland tauren visar insamling av dessa fjädrar på skarp blick, tålamod och jakt skicklighet.",h="En Trophy Swoop Quill är en eftertraktad jakttrofé, plockad från de stora rovfåglar som kretsar över Mulgore.",kw={"bloodhoof village","harken windtotem","mulgore","swoop-jakt","swoop-fjäder","klobeväpnad swoop","trophy swoop quill","smidig swoop"},ang={["class:Hunter"]="Att spåra luftburet byte över öppna slätter sätter grunderna i spårning, tålamod och prickskytte på prov.",["race:Tauren"]="Att jaga swoops och ta hem deras fjädrar är en traditionell syssla som kräver tålamod och klokhet i hela Mulgore, och hedrar både jägaren och klanen."},sec={{t="Jaktens trofé",b="Swoops är listiga rovfåglar som hör hemma i Mulgore. De rider på höga uppvindar och är svåra att spåra över gräsmarkerna. För unga taurenjägare och resenärer som vill bevisa sitt värde i Bloodhoof Village är det en traditionell prövning i klokhet och beslutsamhet att ta en troféfjäder från dessa fåglar. Att överlämna fjädrarna till äldste som Harken Windtotem hedrar jägarens klan och visar att man har de skarpa sinnen som krävs för att klara sig på slätterna."}},faq={{q="Vad används en Trophy Swoop Quill till?",a="Trophy Swoop Quills samlas in som bevis på jaktduglighet åt Harken Windtotem i Bloodhoof Village. Att ta med dem till honom visar beslutsamhet och skarp iakttagelseförmåga, och hedrar din ställning bland de lokala tauren.",al={"vad används swoop-fjädrar till","vem vill ha swoop-fjädrar","användning av swoop-fjädrar"}},{q="Varifrån kommer Trophy Swoop Quills?",a="Dessa fjädrar tas från olika swoops, däribland vanliga swoops, smidiga swoops och klobeväpnade swoops, som svävar över de böljande slätterna i hela Mulgore.",al={"var hittar man swoop-fjädrar","vem släpper trophy swoop quill","swoop-platser"}},{q="Varför anses swoops vara svåra att jaga?",a="Som Harken Windtotem beskriver dem är swoops listiga fåglar som kretsar högt ovanför gräset och rör sig snabbt över landskapet. Det krävs skarp blick för att upptäcka dem och snabba fötter för att hinna ifatt dem.",al={"varför jaga swoops","är swoops svåra att döda"}}},fx={["91a49961"]={q="Vad är en Trophy Swoop Quill?",a="En Trophy Swoop Quill är en uppskattad fjäder från de rovlystna swoops som svävar över Mulgore. Eftersom swoops har skarp syn och är svårfångade krävs skarpa sinnen och snabba fötter för att samla deras fjädrar. Bland tauren fungerar dessa fjädrar som ett tecken på slughet och beslutsamhet och visar att en jägare har tålamodet och skickligheten som krävs för att spåra upp och övervinna ett listigt byte.",al={"trophy swoop quill","vad är en swoop-fjäder","swoop-fjädrarnas historia"}},["62601276"]={q="Varför vill Harken Windtotem ha Trophy Swoop Quills?",a="Harken Windtotem i Bloodhoof Village ber om dessa fjädrar som ett prov på skicklighet och karaktär. Att jaga swoops är ingen lätt uppgift, och om du återvänder med en samling av deras finaste fjädrar bevisar du ditt värde för byn. När du lämnar över dem visar du att du har tålamodet och beslutsamheten som förväntas av en sann jägare, och du bringar ära åt både dig själv och din klan.",al={"varför samla swoop-fjädrar","varför vill harken ha swoop-fjädrar","syftet med swoop-jakt"}}},fp="18,159,17.325.0,38.204.0,39.119.0,44.192.0"}
P.entries["item:twilight-pendant"] = {n="Twilight Pendant",s="En Twilight Pendant bärs av skymningshammarns kultister djupt inne i Blackfathom Deeps. För Argent Dawn är dessa mörka talismaner ett avgörande bevis på kultens subversiva verksamhet längs Ashenvales kust.",h="En Twilight Pendant bärs av skymningshammarns kultister djupt inne i Blackfathom Deeps.",kw={"argent guard manados","ashenvale","blackfathom deeps","old gods","skymningen faller","twilight pendant","twilight's hammer"},ang={["faction:Alliance"]="När dessa troféer förs till Argent Guard Manados i Darnassus visar de att alliansen aktivt stöder Argent Dawns korståg mot dolda ondskor i norra Kalimdor.",["race:NightElf"]="Vanhelgandet av Blackfathom Deeps, som en gång hyste en vördad och mäktig månbrunn, gör återtagandet av dessa korruptionens symboler till en djupt helig uppgift för kaldorei."},sec={{t="De gamla gudarnas tecken",b="I Blackfathom Deeps dränkta ruiner samlas medlemmar av Twilight's Hammer med naga för att utföra avskyvärda riter till de kaotiska Old Gods ära. Kultister, från skuggmagiker och vattenmagiker till plundrare och lärdomssökare, bär dessa hängsmycken som tecken på sin hängivenhet till sina dunkla beskyddare. Eftersom kulten verkar i hemlighet under det forna Night Elf-templet är det ett av få sätt för utomstående att bedöma kultens styrka och omintetgöra dess planer."},{t="Argent Dawns vaksamhet",b="Argent Guard Manados i Darnassus söker aktivt efter dessa hängsmycken som bevis på en framgångsrik utrensning av det tilltagande mörkret. Blackfathom Deeps hyste en gång en orörd månbrunn, och dess vanhelgande av illvilliga tomhetsdyrkare utgör ett allvarligt hot mot Kalimdor. När hängsmyckena samlas in bekräftar det att kultisternas fäste i Ashenvale monteras ned innan deras mörka beskyddare kan släppa lös större fasa."}},faq={{q="Vad är ett Twilight Pendant?",a="Ett Twilight Pendant är en kännetecknande amulett som bärs av medlemmar i Twilight's Hammer-kulten, verksam i Blackfathom Deeps. Det är ett påtagligt bevis på hängivenhet till Old Gods och deras mörka riter.",al={"information om twilight pendant","vad är twilight pendants"}},{q="Varför vill Argent Guard Manados ha dessa hängsmycken?",a="Argent Guard Manados, som är stationerad i Darnassus på Argent Dawns uppdrag, söker efter dem som bevis på att Twilight's Hammer slås tillbaka i Blackfathom Deeps innan dess onda planer kan fullbordas.",al={"vem vill ha twilight pendant","varför samla twilight pendants"}},{q="Vem bär dessa hängsmycken?",a="De bärs av olika kultister i Blackfathom Deeps undervattenstempel, däribland Twilight Acolytes, Aquamancers, Shadowmages, Loreseekers, Elementalists och Reavers.",al={"vem släpper twilight pendant","varifrån kommer twilight pendants"}},{q="Vilket hot utgör Twilight's Hammer i Blackfathom Deeps?",a="I förbund med naga försöker Twilight's Hammer återuppliva dyrkan av Old Gods, vanhelga en uråldrig Night Elf-månbrunn och förbereda riter som kan sprida fasa över Kalimdor.",al={"vad gör twilight's hammer i bfd","varför finns kultister i ashenvale"}}},fp="16,170,22.425.0,24.370.0,27.159.0,50.164.0,25.130.0,65.168.0"}
P.entries["item:twilight-whisker"] = {n="Twilight Whisker",s="Twilight Whiskers samlas in från Twilight runners som strövar omkring på Stonetalon Mountains norra höjder. I bosättningen Malaka'jin vill Witch Doctor Jin'Zil åt dem som ingrediens i en grym, giftig brygd som han hånfullt kallar skogsmagi.",h="Twilight Whiskers samlas in från Twilight runners som strövar omkring på Stonetalon Mountains norra höjder.",kw={"skogsmagi","malaka'jin","stonetalon mountains","stonetalon peak","twilight runner","twilight whisker","witch doctor jin'zil"},ang={["race:NightElf"]="Skändningen av heliga skogsvarelser som Twilight runners och Fey Dragons för att förgifta tillfångatagna Night Elves förkroppsligar den brutala konflikten som rasar i Kalimdors skogar.",["race:Troll"]="Jin'Zils bruk av lokala djurreagenser speglar klassiska Darkspear-voodootraditioner och vänder skogens naturliga essens mot hans fiender."},sec={{t="En Witch Doctors reagens",b="De höga klipporna nära Stonetalon Peak är hem åt Twilight runners, rovdjur bland kattdjuren som är anpassade till de uråldriga dungarnas djupa skuggor. Jägare uppskattar deras pälsar, men Witch Doctor Jin'Zil från Malaka'jin söker deras styva morrhår för ett långt mörkare syfte. Jin'Zil vill hämnas på tillfångatagna Night Elves som en gång försvarade dessa skogar och samlar därför skogens beståndsdelar – kådrik sav, otaliga ögon, Fey Dragon Scales och Twilight Whiskers – för att brygga en dödlig dryck som ska håna och förgifta sina fångar."}},faq={{q="Var hittar man Twilight Whiskers?",a="De samlas in från Twilight runners som stryker omkring på sluttningarna runt Stonetalon Peak i norra Stonetalon Mountains.",al={"twilight whiskers plats","vem släpper twilight whiskers","var man hittar twilight whiskers"}},{q="Varför vill Witch Doctor Jin'Zil ha dem?",a="Witch Doctor Jin'Zil använder dem tillsammans med sav, courserögon och en Fey Dragon Scale för att brygga en dödlig blandning som förgiftar hans tillfångatagna Night Elves i Malaka'jin.",al={"jin'zils morrhår","varför jin'zil vill ha twilight whiskers","jin'zils ingredienser till skogsmagi"}},{q="Vad händer när Jin'Zil får morrhåren?",a="När Jin'Zil har fått ingredienserna släpper han ut sin brygd i grottan. Blandningen dödar snabbt de inspärrade Night Elf-fångarna, och deras andar frigörs som irrbloss som driver bort.",al={"skogsmagins följder","vad som händer fångarna"}}},fx={["15466f07"]={q="Vad är en Twilight Whisker?",a="En Twilight Whisker är ett stelt ansiktshår från twilight runners som stryker omkring på höjderna i Stonetalon Mountains. För de flesta är det bara djuravfall, men för utövare av voodoo och alkemi är det ett kraftfullt reagens som bär på den vilda essensen hos traktens rovdjur.",al={"vad är en twilight whisker","information om twilight whisker","vad är twilight whiskers"}},["8f61da64"]={q="Var kommer en Twilight Whisker ifrån?",a="Twilight Whiskers rycks från twilight runners, rovlystna kattdjur som hör hemma i Stonetalon Mountains. De tillverkas inte av dödliga händer, utan tas direkt från djuren som strövar nära Stonetalon Peak.",al={"twilight whiskers ursprung","var får man twilight whisker","vem lämnar twilight whisker"}}},fp="16,163,24.415.0,34.114.0,40.163.0,49.166.1"}
P.entries["item:twitching-antenna"] = {n="Twitching Antenna",s="I södra The Barrens rycker silithidernas antenner fortfarande efter att de skurits loss. Ruga Ragetotem vid Camp Taurajo vill ha dem som bevis på en ung krigares snabbhet och stridsförmåga innan nerverna slutar reagera.",h="I södra The Barrens rycker silithidernas antenner fortfarande efter att de skurits loss.",kw={"antenner","barrens","camp taurajo","field of giants","ruga ragetotem","silithid","twitching antenna"},ang={["class:Hunter"]="Som jägare spårar och dödar du silithider och samlar sedan in deras antenner medan de fortfarande rycker. Prövningen testar din snabbhet, spårningsförmåga och skicklighet i fält.",["race:Tauren"]="Som tauren vet du att jägarna i Camp Taurajo ser silithidernas plötsliga ankomst som en störning av slätternas naturliga balans. Unga krigare måste vara vaksamma."},sec={{t="Bevis på jakten",b="Silithid Grubs, Swarmers, Harvesters och Creepers har antenner som rycker efter att de skurits loss från huvudet. Kramperna avtar snart efter att insekterna dödats. En ung krigare måste jaga silithider i de södra ödemarkerna och skynda tillbaka över buskmarkerna medan antennerna fortfarande rycker. Att hinna tillbaka i tid prövar både snabbhet och skicklighet och gör jakten till en övergångsrit för hordens krigare."},{t="Hotet i söder",b="Silithidernas antenner pekar också på ett hot som oroar jägarna i Camp Taurajo. Silithider hör inte hemma i The Barrens, och deras nya grävda högar vid Field of Giants oroar lägret. Ruga Ragetotem vill ha exemplaren för att studera faran och förbereda hordens krigare på det främmande hot som tränger in på slätterna."}},faq={{q="Vilka varelser släpper ryckande antenner?",a="Silithid Grubs, Harvesters, Swarmers och Creepers kring Field of Giants i södra The Barrens har antennerna.",al={"var släpper ryckande antenner","vem släpper ryckande antenner","silithidernas antenner källa"}},{q="Varför måste antennerna rycka?",a="Ryckningarna visar att antennerna nyss skurits loss. Ruga Ragetotem använder tiden det tar för dem att sluta rycka för att pröva en aspirants snabbhet och stridsförmåga i den vilda terrängen.",al={"varför rycker de","varför så bråttom med antenner","tidsgräns för trial at field of giants"}},{q="Vem letar efter antennerna?",a="Ruga Ragetotem, en taurenkrigare vid Camp Taurajo i södra The Barrens, vill ha antennerna till prövningen vid Field of Giants.",al={"vem vill ha ryckande antenner","vem lämnar in antenner"}},{q="Var ligger Field of Giants?",a="Field of Giants ligger söder om Camp Taurajo i The Barrens. Väldiga skelettrester reser sig ur jorden där, omgivna av silithidbon.",al={"var ligger field of giants","field of giants plats"}}},fx={["47f6f8c0"]={q="Vad är en Twitching Antenna?",a="En Twitching Antenna är ett nyss avskuret känselorgan från en av de silithider som angriper södra Barrens. Dessa bisarra insektsliknande utskott fortsätter att krampa och rycka av nervös energi en kort stund efter att de skurits loss från larver, svärmare och skördemän.",al={"vad är en twitching antenna","twitching antennas historia","silithidantenn"}},["057f3d5d"]={q="Var kommer en Twitching Antenna ifrån?",a="Dessa antenner kommer från den bisarra silithidsvärm som nyligen dykt upp kring Field of Giants i södra Barrens. De skärs loss direkt från varelser som larver, svärmare, krypare och skördemän och är organiskt biologiskt material, inte tillverkade verktyg.",al={"var kommer twitching antennae ifrån","vem lämnar twitching antenna","silithiddelar"}}},fp="17,208,17.398.0,23.324.0,39.121.0,41.168.0,34.130.0,29.147.0"}
P.entries["item:ukor-s-burden"] = {n="Ukor's Burden",s="I Valley of Trials avvisas Ukors mat, och han behöver hjälp att föra tillbaka den till Razor Hill.",h="I Valley of Trials avvisas Ukors mat, och han behöver hjälp att föra tillbaka den till Razor Hill.",kw={"durotar","grosk","peon","ransoner","razor hill","ukor","valley of trials"},ang={["faction:Horde"]="Som medlem av Horde ser du hur Durotars hårda prövningar formar nya soldater. Även ett vänligt erbjudande måste ge vika för deras träning."},sec={{t="Ett välmenande misstag",b="Ukor, en orcisk arbetare, handlar sällan på egen hand, men han bar förnödenheter från värdshuset i Razor Hill för att hjälpa de unga rekryterna i Valley of Trials. Resan gick genom Durotars röda damm och bland farliga vilda djur. Tillsynsmännen och instruktörerna avvisade maten eftersom de tror att umbäranden och hunger skapar sanna krigare. Nu väntar Ukor utanför ravinens mynning, rädd för bestarna längs vägen tillbaka. Han har anförtrott säcken åt förbipasserande resenärer och bett dem lämna tillbaka den till Innkeeper Grosk."}},faq={{q="Vad finns i Ukor's Burden?",a="Ukor's Burden innehåller mat och förnödenheter från värdshuset i Razor Hill. Ukor hoppades kunna mätta de unga orcherna och trollen under träning, men förnödenheter utifrån är inte välkomna i Valley of Trials.",al={"vad finns i packningen","innehållet i ukors börda","vilken mat är det"}},{q="Varför tackade Valley of Trials nej till maten?",a="Tillsynsmännen i Valley of Trials tror att umbäranden och hunger bygger unga krigares karaktär. Innkeeper Grosk säger att hunger ger rekryterna drivkraft, så de tackar nej till välgörenhet utifrån.",al={"varför tackade valley of trials nej till maten","varför ville de inte ha maten","varför behövdes inte maten"}},{q="Vart ska bördan föras?",a="Ta tillbaka säcken till Innkeeper Grosk på värdshuset i Razor Hill. Han ställer tillbaka förnödenheterna på hyllorna och bjuder på en drink till den som lämnar tillbaka dem.",al={"vart ska jag ta ukors börda","vem vill ha ukors börda","leverans av ukors börda"}}},fx={["97aa3ffc"]={q="Vad är Ukor's Burden?",a="Ukor's Burden är en tung last med proviant och matvaror som ursprungligen samlades ihop från värdshuset i Razor Hill. En plikttrogen peon vid namn Ukor packade själv knytet, med avsikten att ge undsättning åt de unga krigare som tränar bland de hårda klipporna i Valley of Trials.",al={"vad är ukor's burden","ukor's burden","föremålet ukor's burden"}},["1b425e9c"]={q="Var kommer Ukor's Burden ifrån, och vem gjorde den?",a="Lasten kom från värdshuset i Razor Hill, där Innkeeper Grosk tog hand om den. Ukor, en välmenande orc-peon, bar den hela vägen längs vägen förbi farliga skorpioner och spindlar till prövningsplatsen, bara för att upptäcka att hans hjälp inte var önskad.",al={"varifrån kom ukor's burden","vem gjorde ukor's burden","ukor's burdens ursprung"}},["32c1e657"]={q="Varför vill någon ha Ukor's Burden?",a="Efter att tränarna i Valley of Trials tackat nej till provianten behöver Innkeeper Grosk få tillbaka maten till lagret på hyllorna i Razor Hill. Ukor är livrädd för vilddjuren som stryker omkring i Durotars vildmark och förlitar sig på förbipasserande resenärer för att få den säkert hem.",al={"varför vill grosk ha ukor's burden","varför lämna tillbaka ukor's burden","vem vill ha ukor's burden"}}},fp="13,102,26.491.0,29.184.0,45.182.0,33.157.0"}
P.entries["item:uncloven-satyr-hoof"] = {n="Uncloven Satyr Hoof",s="I Ashenvale frossar satyrerna i skogens uråldriga magi. Deras svullna hovar rymmer kraften de stjäl, och Ula'elek använder den för att smida rustning i Sen'jin Village.",h="I Ashenvale frossar satyrerna i skogens uråldriga magi.",kw={"ashenvale","durotar","handskar","klöv","satyr","sen'jin","ula'elek","okluven"},ang={["class:Warrior"]="Som en ung krigare på jakt efter ryktbarhet kan du bevisa din stridsförmåga genom att jaga Ashenvales satyrer och beställa specialrustning från hordens tränare i Sen'jin Village.",["race:Troll"]="Som troll delar du Darkspears hantverkares skicklighet i att omvandla mörka eller fientliga energier till användbar utrustning. Ula'elek suger kraft ur demoniska fiender i stället för att låta den gå till spillo."},sec={{t="Utsugen kraft",b="Satyrerna hemsöker de fördärvade dungarna i nordöstra Ashenvale och livnär sig på den uråldriga skogens magiska renhet. Ju mer de förtär, desto mer förvrider korruptionen deras demoniska kroppar. Deras hovar svullnar och förlorar sin naturliga kluvenhet, och blir täta förråd av absorberad energi. Skickliga schamaner och läderarbetare kan utvinna den flyktiga kraften."},{t="Att smida den brutala rustningen",b="I Sen'jin Village vid Durotars kust omvandlar trollrustmästaren Ula'elek demonisk korruption till styrka åt hordens mästare. Han tar hovar från satyrer som har livnärt sig på skogen och utvinner den instängda magin. Sedan kanaliserar han den stulna kraften till brutala handskar, rustning åt unga krigare som möter Kalimdors strapatser."}},faq={{q="Varför är satyrernas klövar okluvna?",a="Satyrerna i Ashenvale livnär sig på skogens heliga magi och fördärvar den medan de suger åt sig dess kraft. De som frossar mest utvecklar svullna hovar som förlorar sin kluvenhet och rymmer den täta, stulna energin.",al={"varför är de okluvna","betydelsen av okluven klöv","svullna klövar"}},{q="Var hittar man Uncloven Satyr Hooves?",a="Satyrer i de fördärvade ruinerna och besudlade dungarna i nordöstra Ashenvale bär sådana här hovar, även de nära Satyrnaar och Night Run.",al={"var kan man samla klövar","plats för satyrklövar","vilka satyrer släpper klövar"}},{q="Vem vill ha dessa klövar i Durotar?",a="Ula'elek, en rustmästare i Sen'jin Village på Durotars sydkust, ber om sju hovar så att han kan utvinna deras lagrade magi.",al={"vem behöver satyrklövar","uppdragsgivare för satyrklövar","vad gör man med klövarna"}},{q="Vad används klövarna till att tillverka?",a="Ula'elek utvinner fördärvad skogskraft ur hovarna och smider ett par stadiga, magiinfunderade brutala handskar.",al={"vad används de till","belöning för klövtillverkning","material till brutala handskar"}}},fx={["81ca4f2a"]={q="Var kommer en Uncloven Satyr Hoof ifrån?",a="Dessa hovar tas direkt från satyrerna som lurar i nordöstra Ashenvale. De tillverkas inte, utan är naturliga kroppsdelar som förvridits av mörk frosseri. Satyrerna i skogen frossar i Ashenvales rena naturliga energier, och de demoner som förbrukar störst överskott av den stulna magin utvecklar särskilt svullna, osplittrade hovar.",al={"var kommer uncloven satyr hooves ifrån","vem gjorde uncloven satyr hoof","varifrån kommer satyrhovar"}}},fp="19,174,13.343.0,25.332.0,36.215.0,41.140.0,34.131.0,34.110.0"}
P.entries["item:underbelly-whelp-scale"] = {n="Underbelly Whelp Scale",s="Underbelly Whelp Scales skördas från de yngre kullarna av Black Dragonflight som strövar omkring i Redridge Mountains. Hantverkare värdesätter dem för deras tåliga men följsamma struktur, och de fungerar som värdefullt bytesmaterial bland lokala hantverkare.",h="Underbelly Whelp Scales skördas från de yngre kullarna av Black Dragonflight som strövar omkring i Redridge...",kw={"argus","svart drakunge","lakeshire","redridge","snarlflare","bukfjäll","underbelly whelp scale","verner osgood"},ang={["faction:Alliance"]="Lakeshires isolerade försvarare är starkt beroende av byteshandel med Elwynn Forest för att hålla sig utrustade, så farliga lokala uppdrag som att skaffa drakfjäll är viktiga för att hålla stadens förråd välfyllda.",["profession:Blacksmithing"]="Hantverkare som Argus värdesätter fjällen eftersom exotiska kräldjursplåtar kan bearbetas till foder, grepp och särskilda skyddsbeslag som är långt starkare än vanligt kohud."},sec={{t="En sällsynt handelsvara",b="Drakhud och fjäll har legendarisk hållbarhet, men fullvuxna svarta drakar är oerhört dödliga för vanligt folk. I stället söker sig uppfinningsrika nybyggare och hantverkare mot himlen söder om Lake Everstill, där unga svarta drakungar bygger bo bland klipporna. En drakunges ryggplåtar är spröda eller grova, men fjällen längs den mjukare undersidan har en idealisk balans mellan smidighet och skydd. Därför betingar dessa bukfjäll ett högt värde i den regionala handeln och fungerar både som exklusivt hantverksmaterial och tillförlitlig säkerhet för skulder."},{t="Verners skuld",b="I Lakeshire måste magistratens hantverkare ofta förlita sig på byteshandel när det råder brist på mynt eller handelsvägarna är ansträngda. Verner Osgood, den lokale smeden, blev djupt skuldsatt till smeden Argus efter en leverans hästskor från Goldshire. Verner vet att Argus uppskattar sällsynta handelsvaror och förlitar sig därför på förbipasserande äventyrare som kan skörda Underbelly Whelp Scales för att betala skulden och hålla verkstaden i gott anseende."}},faq={{q="Var kommer Underbelly Whelp Scales ifrån?",a="De samlas in från svarta drakungar och fullvuxna ungar som Snarlflare, vilka håller till i de klippiga branterna och kullarna söder om Lakeshire i Redridge Mountains.",al={"vem släpper underbelly whelp scales","var man får tag på drakungefjäll","hur man hittar drakungefjäll"}},{q="Varför vill Verner Osgood ha fjällen?",a="Verner är skyldig Argus, smeden i Goldshire, för en leverans importerade hästskor. Argus tar emot drakfjäll som betalning, och eventuellt överskott ger Verner råmaterial till att tillverka tålig skyddsutrustning.",al={"varför verner behöver fjäll","verner osgood bukfjäll"}},{q="Varför föredrar man bukfjäll framför vanliga drakfjäll?",a="Bukfjällen från en ung drake är följsamma nog att skäras till, formas och sys till praktiska rustningar eller förstärkt utrustning. Ryggfjäll är däremot ofta för stela, tjocka eller skeva för vanliga tekniker inom läderarbete och smide.",al={"varför bukfjäll","vad som gör bukfjäll speciella"}},{q="Varför finns det svarta drakungar i Redridge?",a="Black Dragonflight har hållit till bland de brinnande topparna och klipporna längs gränsen mellan Burning Steppes och Redridge, där de använder de höga, otillgängliga branterna för att ruva och föda upp sina ungar.",al={"varför det finns drakar i redridge","svarta drakungar i redridge"}}},fx={["4599dc10"]={q="Vad är en Underbelly Whelp Scale?",a="Det här är smidiga fjäll från undersidan av svarta drakungar som strövar i de södra delarna av Redridge. Till skillnad från de styva, ogenomträngliga plåtarna som täcker en vuxen drakes rygg är fjällen på en drakunges buk både anmärkningsvärt hållbara och så böjliga att skickliga hantverkare kan bearbeta dem. Därför är de ett eftertraktat hantverksmaterial.",al={"vad är underbelly whelp scales","föremålet underbelly whelp scale","drakungens fjälls historia"}}},fp="22,185,22.427.0,13.421.0,43.209.0,41.209.0,63.226.0,47.189.0"}
P.entries["item:unidentified-ore"] = {n="Unidentified Ore",s="Unidentified Ore är ett märkligt mineralprov som grävdes fram under Venture Companys verksamhet i Stonetalon Mountains klippor. Den missnöjde arbetaren Piznik fick tag på det och smugglade undan det för att goblintinkern Ziz Fizziks skulle analysera det och skicka det vidare till ingenjörer i Undermine.",h="Unidentified Ore är ett märkligt mineralprov som grävdes fram under Venture Companys verksamhet i Stonetalon...",kw={"piznik","stonetalon","undermine","unidentified ore","venture company","windshear crag","ziz fizziks"},ang={["profession:Engineering"]="Goblinhantverk bygger på att hitta råämnen med unika reaktiva egenskaper, vilket gör oklassificerade malmer från otämjda klippor till utmärkt forskningsmaterial för nyskapande tinkrar.",["profession:Mining"]="Gruvarbetare som letar i Windshear Crag hittar vanliga malmådror överallt, men det här märkliga mineralprovet trotsar den gängse handelskunskapen och väcker nyfikenhet även hos Undermines främsta värderare."},sec={{t="Ett märkligt fynd i Windshear",b="Venture Companys obevekliga kalhuggning och dagbrottsbrytning i Windshear Crag skar djupt in i Stonetalon Mountains klippor och blottade ovanliga mineral lager. Platsens nya chef, Gerenzo Wrenchwhistle, beordrade att stora mängder av en märklig guldgrön malm skulle brytas. Den degraderade goblinarbetaren Piznik, som fortfarande var lojal mot sin avskedade före detta chef Ziz Fizziks, säkrade ett prov medan han planerade att lämna företaget. Provet lämnades över till en resenär på väg mot klippans västra ås och hamnade hos Ziz Fizziks, som tänkte skicka fyndet till Undermine för undersökning och behålla en liten bit för egen vinning."}},faq={{q="Vad är Unidentified Ore?",a="Det är ett oklassificerat geologiskt prov som grävdes upp under Venture Companys verksamhet i Windshear Crag. Dess exakta sammansättning är så gåtfull att den väcker nyfikenheten hos tinkern Ziz Fizziks och gruvingenjörerna i Undermine.",al={"vad är det här för malm","lore om unidentified ore","vad är det här för sten"}},{q="Vem hittade malmen?",a="Piznik, en goblin hos Venture Company som var stationerad i Windshear Crag, räddade provet. Han fruktade repressalier från företagets chefer efter de senaste missödena och tog tillfället i akt att fly och hitta ett nytt arbete.",al={"vem grävde upp den","vem ger bort malmen","piznik och malmen"}},{q="Vem försöker undersöka provet?",a="Ziz Fizziks, en företagsam goblin som slagit läger längs den västra kanten av Windshear Crag, tar emot mineralet. Han tänker skicka större delen till ingenjörer i Undermine och behålla en liten del själv.",al={"vem vill ha malmen","vem analyserar den","ziz fizziks och malmen"}},{q="Varför bryr sig Undermine om stenen?",a="Goblins letar alltid efter nya explosiva, metallurgiska eller brännbara material. Ett märkligt mineral från Kalimdors urgamla berg har enorm industriell och kommersiell potential för handelskartellerna.",al={"undermines intresse","varför vill goblins ha den"}}},fx={["4673b3b7"]={q="Var kommer Unidentified Ore ifrån?",a="Provet kommer från Venture Companys gruva i Windshear Crag i Stonetalon Mountains, där platsens nya chef, Gerenzo Wrenchwhistle, beordrade att stora mängder av en märklig guldgrön malm skulle grävas upp. Piznik, som fortfarande är lojal mot sin avskedade tidigare chef Ziz Fizziks, bröt ett prov i hemlighet så att det kunde tas till Ziz.",al={"unidentified ores ursprung","var hittades unidentified ore","var kom malmen ifrån"}}},fp="16,153,29.538.0,29.185.0,18.203.0,35.184.0,41.195.0"}
P.entries["item:unrefined-ore-sample"] = {n="Unrefined Ore Sample",s="I Thousand Needles väcker en ovanlig malm Hordens intresse. Tatternack Steelforge söker ett prov för att avgöra om råmineralet kan stärka vapnen i hövding Thralls arméer.",h="I Thousand Needles väcker en ovanlig malm Hordens intresse.",kw={"camp taurajo","gibblesnik","gravelsnout","kobold","malm","tatternack steelforge","thousand needles","unrefined ore sample"},ang={["faction:Horde"]="Som medlem av Horden vet du att varje ny mineralåder i södra Kalimdor kan hjälpa Thralls unga nation att förse sig med egna vapen medan den säkrar sina gränser.",["profession:Blacksmithing"]="Som smed kan du förstå Tatternacks frustration. Att testa ny malm för styrka och hållbarhet hjälper smeder att utrusta krigare med klingor som inte splittras i strid."},sec={{t="Bruten av ohyran",b="Söder om The Barrens gräver Gravelsnout kobolds sig genom stenen under ravinväggarna i Thousand Needles. Resenärer som återvände norrut hittade ett märkligt mineral bland dödade skadedjur, olikt de vanliga ådrorna i Kalimdor. De vägrade lämna ifrån sig sitt fynd till Horden. Kobolderna som gräver och undersöker djupen bär med sig råa malmstycken från sina utgrävningar."},{t="Smide åt krigshövdingen",b="I Camp Taurajo arbetar vapensmeden Tatternack Steelforge på uppdrag av hövding Thrall med att förbättra Hordens vapen. Resenärer som höll fyndplatsen hemlig gjorde honom vred; han såg deras vägran som en förolämpning mot Hordens krigsinsats. Med ett råprov tänker Tatternack testa mineralets styrka och härdbarhet, sedan smälta det och smida ett prototypblad för Orgrimmars godkännande."}},faq={{q="Varifrån kommer den här obearbetade malmen?",a="Gravelsnout kobolds bär malmen från ravinens djup i Thousand Needles, söder om The Barrens. Deras grävare, kartläggare och ledare Gibblesnik bor där.",al={"malmens plats","var hittar man unrefined ore sample","vem släpper obearbetad malm"}},{q="Varför vill Tatternack Steelforge ha ett prov?",a="Tatternack arbetar på uppdrag av hövdingen för att förbättra Hordens vapen. Han vill undersöka och smälta malmen för att ta reda på om den kan smidas till starkare vapen.",al={"varför vill tatternack ha malm","malmens syfte i taurajo","vad används malmen till"}},{q="Varför var resenärerna ovilliga att lämna ifrån sig den?",a="Horderesenärer som färdades genom Thousand Needles hittade malmen på en kobold och behöll den som trofé eller kuriositet. De vägrade sälja den, även när de ombads hjälpa till med Hordens smidesarbete.",al={"vilka var resenärerna","resenärer och malm i the barrens"}},{q="Finns den här malmen någonstans i The Barrens?",a="Nej. Camp Taurajo ligger i södra The Barrens, men malmen måste hämtas från kobolder längre söderut i Thousand Needles.",al={"malm i the barrens","kan man bryta den i the barrens"}}},fx={["5c1fb5e1"]={q="Vad är ett Unrefined Ore Sample?",a="Det är en bit rå, ovanlig mineral som kobolderna grävt upp ur jorden i Thousand Needles. Till skillnad från de vanliga ådrorna som bryts i hela Barrens fångar denna främmande malm smedernas intresse för sin möjliga hållbarhet, men den måste smältas och undersökas ordentligt innan någon kan avgöra om den duger till smide.",al={"vad är ett unrefined ore sample","unrefined ore sample","vad är malmprovet"}}},fp="20,190,19.361.0,24.384.0,40.159.0,45.162.0,49.189.0,42.124.0"}
P.entries["item:ur-s-treatise-on-shadow-magic"] = {n="Ur's Treatise on Shadow Magic",s="Stormwinds magiker vaktade en gång Ur's Treatise on Shadow Magic, men Morganth stal den farliga volymen och gömde den i Tower of Ilgalar.",h="Stormwinds magiker vaktade en gång Ur's Treatise on Shadow Magic, men Morganth stal den farliga volymen och...",kw={"andromath","dalaran","ilgalar","morganth","redridge","sanctum","skuggmagi","volym","avhandling","ur"},ang={["class:Mage"]="Som magiker i Stormwind hjälper du till att hålla avhandlingen under kontroll och värna om säkerheten i The Sanctum efter att en av de egna gett efter för mörka frestelser.",["faction:Alliance"]="Som resenär i Alliansen vet du att Morganths närvaro i Redridge hotar rikets östra gräns. Att återta den mäktiga artefakten är viktigt för Stormwinds säkerhet."},sec={{t="Ett farligt arv",b="Ur från Dalaran skrev en avhandling om skuggmagi och dess subtila, korrumperande natur. Magikerna i Wizard's Sanctum i Stormwind fruktade att sådana konster kunde leda de oförsiktiga till undergång och ruin, så de förseglade volymen för att hindra andra från att läsa den. Efter att Morganth gett sig hän åt mörka konster och Stormwinds magiska krets förvisat honom tog han volymen österut till Redridge Mountains, till sitt fäste i Tower of Ilgalar."},{t="De förseglade hemligheterna",b="Övermagikern Andromath fruktade att Morganth skulle kunna bemästra den mörka kunskapen i Ur's verk, så han skickade äventyrare för att tränga in i Tower of Ilgalar och återta den. Morganth hade fördjupat sig i förbjuden magi, men de skyddande sigill som Stormwinds krets satt på avhandlingen stod emot honom. Boken förblev oöppnad tills den återfanns."}},faq={{q="Vem var Ur?",a="Ur var en respekterad trollkarl och lärd från Dalaran. Han studerade varelser från andra plan, mörka konster och esoterisk magi, däribland skuggmagi.",al={"vem skrev den här boken","ur från dalaran","vem är ur"}},{q="Varför är avhandlingen så farlig?",a="Skuggmagi kan korrumpera en oerfaren utövare och leda till undergång och ruin. Övermagikern Andromath varnar för att utforska dess förbjudna djup.",al={"varför är boken farlig","vad gör boken","faror med skuggmagi"}},{q="Vem stal Ur's Treatise on Shadow Magic?",a="Morganth stal volymen efter att ha förvisats från Stormwinds magikerorden för att ha gett efter för mörk magi. Han drog sig tillbaka till Tower of Ilgalar i Redridge.",al={"vem stal boken","morganth stal boken","vem tog avhandlingen"}},{q="Lyckades Morganth läsa avhandlingen?",a="Nej. Stormwinds magiker förseglade volymen, och deras skydd höll stånd så att Morganth inte kunde öppna den innan den återfanns.",al={"läste morganth den","höll sigillen","öppnades boken"}},{q="Är det här samma verk som The Book of Ur?",a="Båda verken är skrivna av Ur och nära besläktade. The Book of Ur är en bredare grimoar som förvaras i ruinerna av Shadowfang Keep, medan Treatise on Shadow Magic verkar vara ett utdrag eller en specialiserad volym med fokus på skuggkonster.",al={"skillnaden mellan the book of ur","the book of ur shadowfang","är det här the book of ur"}}},fx={["9052da59"]={q="Vad är Ur's Treatise on Shadow Magic?",a="Det är en kraftfull och välbevakad bok som beskriver skuggmagiens förbjudna mysterier. Boken förvaras under skyddande besvärjelser av magikerna i Wizard's Sanctum i Stormwind och innehåller mäktig ockult kunskap som kan leda till undergång och fördärv för den som är dumdristig nog att studera den om sigillen bryts.",al={"vad är ur's treatise","ur's treatise on shadow magic","vad är traktaten om skuggmagi"}},["0481e4cc"]={q="Var kommer Ur's Treatise on Shadow Magic ifrån, och vem skrev den?",a="Boken skrevs av den begåvade Kirin Tor-magikern Ur från Dalaran, en lärd som ägnade sig åt att forska i mörka konster, utomvärldsliga väsen och skuggmagi. Hans farliga skrifter hamnade så småningom i Stormwind, där stadens magiker förseglade traktaten för att hålla dess hemligheter borta från de oinvigda.",al={"vem skrev ur's treatise","varifrån kom ur's treatise","ursprunget till ur's treatise on shadow magic"}},["9d095b57"]={q="Varför vill någon ha Ur's Treatise on Shadow Magic?",a="Utövare som lockats av mörka krafter söker traktaten för dess mäktiga hemligheter inom arkana konster och skuggmagi. Den avfällige magikern Morganth stal den för att stärka sin egen ockulta makt, medan High Sorcerer Andromath och magikerna i Stormwind skyndar sig att få tillbaka den så att sigillen förblir intakta och farorna säkert förseglade.",al={"varför efterfrågas traktaten","varför vill magiker ha ur's treatise","varför vill morganth ha traktaten"}}},fp="29,167,18.397.0,18.299.1,11.140.0,33.143.0,40.147.0,41.113.1,40.218.0"}
P.entries["item:urgent-message"] = {n="Urgent Message",s="Urgent Message är ett förseglat meddelande, skrivet av Brave Moonhorn, som varnar Freewind Post för att centaurernas våld ökar i Thousand Needles. Brevet bärs av resande som tar sig ner i kanjonen och uppmärksammar tauren-garnisonen på att deras försörjningsleder och spaningspatruller är hotade omedelbart.",h="Urgent Message är ett förseglat meddelande, skrivet av Brave Moonhorn, som varnar Freewind Post för att...",kw={"brave moonhorn","centaur","cliffwatcher longhorn","freewind post","the great lift","grimtotem","thousand needles","urgent message"},ang={["faction:Horde"]="Meddelandet visar hur osäkra Hordes försörjningsleder är genom södra Kalimdor, där isolerade utposter är beroende av löpare och modiga krigare för att klara sig i fientlig terräng.",["race:Tauren"]="För tauren är brevet en smärtsam påminnelse om den urgamla blodsfejden med centaurerna och om den växande oron kring deras släktingar i Grimtotem."},sec={{t="En varning från höjderna",b="Urgent Message, skrivet av Brave Moonhorn nära den stora hissen som går från The Barrens ner till Thousand Needles, utgör den första försvarslinjen för resande som korsar gränsen. Moonhorn håller uppsikt över de karga kanjonerna nedanför, där aggressiva centaurstammar åter har inlett sina skoningslösa räder mot Horde-resande. Meddelandet är adresserat till Cliffwatcher Longhorn högst uppe på Freewind Post och slår larm om allt djärvare angripare som slår till farligt nära viktiga vägar. Det uppmanar den lokala garnisonen att förbereda sig på en utdragen konflikt och att se upp för sekundära hot, som den oberäkneliga Grimtotem-klanen."},{t="Blodspillan på kanjonens botten",b="När brevet når Cliffwatcher Longhorn högst uppe på Freewind Posts väldiga platå bekräftar det bosättningens värsta farhågor. Centaurernas angrepp har gått långt bortom mindre gränsstrider. Rövare har överfallit en viktig försörjningskaravan på kanjonens botten och slaktat hela följet. Meddelandet tvingar tauren-ledarna att genast gå från vaksamt försvar till aggressiva motangrepp. De organiserar anfall för att kuva de härjande stammarna innan Freewind Post blir helt avskuret från resten av Kalimdor."}},faq={{q="Vad står det i Urgent Message?",a="Meddelandet beskriver en kraftig ökning av centaurernas räder i Thousand Needles. Det varnar för att resande och vägar är i omedelbar fara och uppmanar Freewind Post att förbereda sig för krig.",al={"vad står det i brevet","innehållet i urgent message","vad handlar meddelandet om"}},{q="Vem skrev meddelandet och vem tar emot det?",a="Det skrevs av Brave Moonhorn, som är stationerad vid The Great Lift från The Barrens, och adresserades direkt till Cliffwatcher Longhorn, befälhavaren på Freewind Post.",al={"vem skrev urgent message","avsändare av urgent message","vem får urgent message"}},{q="Varför angriper centaurerna försörjningskaravaner?",a="Centaurstammarna har länge kämpat med tauren om de torra landområdena i centrala Kalimdor. De plundrar karavaner på kanjonens botten för att röva viktiga förnödenheter och hindra Horde från att färdas tryggt genom Thousand Needles.",al={"varför angriper centaurerna","centaurernas motiv i thousand needles","varför plundrar centaurerna"}},{q="Vilken varning ger spejaren om Grimtotem?",a="Brave Moonhorn varnar alla kurirer som bär meddelandet för att hålla sig undan den närliggande Grimtotem-klanen. Klanens krigare har blivit alltmer reserverade och misstänksamma mot resten av tauren.",al={"varning om grimtotem","varför undvika grimtotem","grimtotem beter sig märkligt"}}},fx={d8ee5ef2={q="Vad är Urgent Message?",a="Urgent Message är ett förseglat skriftligt meddelande som Brave Moonhorn skrev nära gränsen till Thousand Needles. Det rapporterar en alarmerande ökning av kentaurernas aggression längs kanjonens botten och varnar tauren-myndigheterna för den växande faran som hotar resenärer och försörjningsleder i området.",al={"vad är urgent message","föremålet urgent message","brådskande meddelande"}},["1e5b60e5"]={q="Varför behövs Urgent Message vid Freewind Post?",a="Cliffwatcher Longhorn ansvarar för försvaret av Freewind Post och behöver omedelbar underrättelse om fiendens rörelser. Meddelandet varnar honom för att kentaurernas räder har trappats upp, så att han kan agera beslutsamt innan fler försörjningskaravaner och patruller överfalls och slaktas.",al={"varför leverera urgent message","vem behöver urgent message","varför cliffwatcher longhorns meddelande"}}},fp="14,302,26.615.0,29.548.1,38.187.0,43.160.0,46.218.0,57.211.0"}
P.entries["item:valdred-s-hands"] = {n="Valdred's Hands",s="Valdred's Hands är de avhuggna lemmarna från Valdred Moray, som togs efter hans död i södra Silverpine Forest. Raleigh Andrean i Undercity vill ha dem som en makaber trofé och ett bevis på hämnden för mordet på hans hustru.",h="Valdred's Hands är de avhuggna lemmarna från Valdred Moray, som togs efter hans död i södra Silverpine Forest.",kw={"en makes hämnd","deliah","the greymane wall","raleigh andrean","silverpine forest","valdred","valdred moray","valdred's hands"},ang={["race:Undead"]="Kravet på Valdred's Hands visar Forsakens kalla, hämndlystna natur. De kanaliserar ofta sin oförmåga att känna vanlig sorg till långvariga, tvångsmässiga agg."},sec={{t="En hemsk trofé efter sveket",b="Innan pesten slukade Lordaeron var Valdred Moray och Raleigh Andrean nära vänner. Det bandet bröts när Valdred mördade Raleighs hustru, Deliah. Raleigh dog och återuppstod som en av Forsaken, och hävdade att han inte kunde känna äkta sorg, men hungern efter vedergällning lämnade honom aldrig. När Valdred försökte fly söderut förbi The Greymane Wall och in i Gilneas skickade Raleigh ett sändebud för att stoppa sin forne väns flykt. Han krävde Valdreds avhuggna händer som slutgiltigt bevis på att dådet var utfört."},{t="Ett bittert minne",b="När Raleigh får de avhuggna händerna lämnar han ifrån sig sin avlidna hustrus ingraverade ring och avfärdar den som en meningslös prydnad. Eftersom Deliah har varit död för honom så länge finner han ingen tröst i sentimentala minnessaker från förr. I stället bevarar han Valdred's Hands som en bestående, kall påminnelse om sveket och den fullbordade hämnden."}},faq={{q="Vem var Valdred Moray?",a="Valdred Moray var en gång nära vän med Raleigh Andrean. Han svek deras vänskap genom att mörda Raleighs hustru, Deliah, innan han till slut försökte fly söderut mot Gilneas.",al={"vem är valdred","valdred morays bakgrund","valdreds berättelse"}},{q="Varför vill Raleigh Andrean ha just Valdreds händer?",a="Raleigh vill ha händerna eftersom det var med dem Valdred ströp eller slog ihjäl hans hustru. Som brukligt bland Forsaken bevarar han dem som en fysisk trofé över sin väns svek och den hämnd han utkrävde.",al={"varför händer","varför valdreds händer","raleighs handtrofé"}},{q="Var hittar man Valdred Moray?",a="Valdred finns i södra Silverpine Forest, där han dröjer sig kvar nära den väldiga porten i The Greymane Wall i ett försök att fly in i det isolationistiska kungariket Gilneas.",al={"var finns valdred","valdreds plats","valdred morays spawnplats"}},{q="Vad händer med händerna när man tar dem till Undercity?",a="Raleigh behåller händerna i Undercity som ett bestående minne av sin fullbordade hämnd och kastar samtidigt bort sin mördade hustrus ring som en värdelös prydnad.",al={"vad gör raleigh med händerna","lämna in valdreds händer"}}},fx={["1f1d5250"]={q="Vad är Valdred's Hands?",a="Det här är Valdred Morays avhuggna händer, tagna som bevis på hans död och som en makaber hämndtrofé. Valdred var en gång en betrodd vän till Raleigh Andrean, innan han förrådde honom och mördade Raleighs hustru Deliah. Nu är de avhuggna händerna den fysiska fullbordan av Raleighs bittra jakt på vedergällning.",al={"föremålet valdred's hands","vad är valdred's hands","valdred's hands"}},ba2ecc3a={q="Var kommer Valdred's Hands ifrån?",a="De höggs av direkt från Valdred Morays kropp. Desperat att fly från Forsaken och undkomma straff för sina brott drog sig Valdred söderut genom Silverpine Forest mot Greymane Wall, i hopp om att smita in i det muromgärdade kungariket Gilneas innan hans jägare hann fånga honom.",al={"valdred's hands ursprung","vem har valdred's hands","var kommer valdred's hands ifrån"}}},fp="15,181,29.443.0,20.253.1,22.163.0,59.188.0,29.101.0,59.146.1"}
P.entries["item:velinde-s-journal"] = {n="Velinde's Journal",s="Velinde's Journal är en personlig anteckningsbok som tillhörde prästinnan Velinde Starsong från Night Elf. Den förvaras i Sentinels kasern i Darnassus och innehåller viktiga uppgifter om hennes plikter och de mystiska omständigheterna kring hennes avfärd från staden.",h="Velinde's Journal är en personlig anteckningsbok som tillhörde prästinnan Velinde Starsong från Night Elf.",kw={"darnassus","sentinels","thyn'tel bladeweaver","tradesmen's terrace","velinde starsong","velinde's journal","velinde's key","velindes kista"},ang={["class:Priest"]="Velinde Starsong var en skicklig prästinna. Hennes hemliga uppdrag och efterföljande försvinnande avslöjar oroande prövningar för The Sisterhood of Elune.",["race:NightElf"]="En högt aktad medlem av The Sisterhood of Elune har försvunnit under mystiska omständigheter. Det berör Darnassus ledning och oroar Sentinels, som vaktar Kaldoreis huvudstad."},sec={{t="En prästinnas anteckningar",b="När prästinnan Velinde Starsong lämnade Darnassus låstes hennes personliga tillhörigheter in i en kista i Sentinels kasern på Tradesmen's Terrace. Bland föremålen finns hennes dagbok, där hon beskriver sina ansvarsområden och plikter innan hon gav sig av i hemlighet. Sentinels håller Velinde högt och antog att hon bara hade privata ärenden att sköta. Men innehållet i dagboken tyder på att hennes oförklarliga frånvaro är betydligt mer oroande än man först trodde."}},faq={{q="Var finns Velinde's Journal?",a="Dagboken finns i Velindes kista i Sentinels kasern på Tradesmen's Terrace i Darnassus. För att komma in i byggnaden måste du gå över den övre bron som leder till butiken med post och rustningar.",al={"dagbokens plats","var finns velinde's journal","velindes skåp var finns det"}},{q="Vem var Velinde Starsong?",a="Velinde Starsong var en respekterad prästinna från Night Elf som Sentinels litade djupt på. Hon lämnade Darnassus plötsligt och i tysthet, och lämnade kvar sitt skåp och sina tillhörigheter.",al={"vem är velinde","velinde-lore"}},{q="Varför bryr sig Sentinels om hennes dagbok?",a="Till en början antog Sentinels att Velinde lämnade Darnassus av giltiga personliga skäl och skulle återvända. Men ledtrådar om hennes avfärd i hennes anteckningar visar att hennes försvinnande har mörkare innebörd och behöver utredas vidare.",al={"varför vill sentinels ha dagboken","vad finns i dagboken"}},{q="Vem ber dig hämta dagboken?",a="Sentinel Thyn'tel Bladeweaver i Darnassus ger dig tillåtelse och nyckeln till Velindes kista när du berättar vad du fått veta från Tome of Mel'Thandris.",al={"vem ger uppdraget","vem är thyn'tel bladeweaver"}}},fx={["654b265d"]={q="Vad är Velinde's Journal?",a="Velinde's Journal är en skriftlig redogörelse för plikter och personliga anteckningar, förd av nattalvprästinnan Velinde Starsong. Efter hennes plötsliga avfärd förvarades den bland hennes tillhörigheter i Sentinelernas logement i Darnassus. Den innehåller den enda bevarade redogörelsen för hennes förehavanden innan hon försvann.",al={"vad är velinde's journal","velinde's journal","vem skrev journalen"}},["07b3d22b"]={q="Var kommer Velinde's Journal ifrån, och vem skrev den?",a="Prästinnan Velinde Starsong skrev själv journalen under sin tjänstgöring bland nattalverna. Efter hennes mystiska frånvaro samlades hennes tillhörigheter ihop och låstes in i en kista i Sentinelernas kvarter i Darnassus, i väntan på en ledtråd som kunde förklara hennes avfärd.",al={"vem skrev velinde's journal","velinde's journal ursprung","var kommer velinde's journal ifrån"}}},fp="17,174,20.425.0,33.179.0,25.169.0,44.217.0,37.174.0"}
P.entries["item:velinde-s-key"] = {n="Velinde's Key",s="Velinde's Key är en liten nyckel som Thyn'tel Bladeweaver i Darnassus anförtrott åt äventyrare. Den låser upp ett personligt förvaringsskåp i Sentinel-kasernen, där prästinnan Velinde Starsongs skrifter finns bevarade från tiden före hennes mystiska försvinnande.",h="Velinde's Key är en liten nyckel som Thyn'tel Bladeweaver i Darnassus anförtrott åt äventyrare.",kw={"darnassus","skåp","sentinel-kasern","thyn'tel bladeweaver","velinde starsong","velindes tillhörigheter","velinde's journal","velinde's key"},ang={["class:Priest"]="Präster som undersöker Velindes tillhörigheter följer spåren efter en hängiven syster till Elune, vars väg tog en ensam och oroande vändning.",["race:NightElf"]="För Night Elves är det en känslig sak att ta hand om Velindes tillhörigheter. Hon var en respekterad prästinna vars lojalitet mot Elune och sitt folk aldrig kunde ifrågasättas."},sec={{t="En anförtrodd nyckel",b="Thyn'tel Bladeweaver förvarar denna enkla nyckel i Darnassus. Den säkrar prästinnan Velinde Starsongs personliga tillhörigheter. Hennes världsliga ägodelar förvarades tryggt i en fotkista i Sentinel-kasernen ovanför Tradesmen's Terrace efter att hon utan förvarning lämnat Night Elf-länderna. Bladeweaver lämnar bara ut nyckeln till den som visar upp trovärdiga bevis, till exempel avslöjanden från Tome of Mel'Thandris, på ett genuint intresse för att ta reda på prästinnans öde."},{t="Det förflutna låses upp",b="Nyckeln öppnar Velindes förvaringskista, där journalen som dokumenterar hennes plikter och oroliga tankar finns bevarad. Sentinels trodde länge att Velinde helt enkelt hade gett sig av av personliga skäl och en dag skulle återvända. Skrifterna bakom låset börjar nysta upp ett mycket mörkare och mer förbryllande mysterium kring hennes ödesdigra expedition."}},faq={{q="Vad öppnar Velinde's Key?",a="Den öppnar Velinde's Locker, en kista i Sentinel-kasernen i Darnassus. Den finns på övervåningen, bortom en bro i Tradesmen's Terrace.",al={"var använder jag velinde's key","velindes skåp","vilken kista öppnar den"}},{q="Vem ger dig nyckeln?",a="Thyn'tel Bladeweaver, en Sentinel stationerad i Darnassus, anförtror dig nyckeln under utredningen av Velindes försvinnande.",al={"vem har velindes nyckel","var får man tag på velindes nyckel"}},{q="Vem är Velinde Starsong?",a="Velinde Starsong var en aktad Night Elf-prästinna som Sentinels litade på. Hon gav sig plötsligt av i egna ärenden och lämnade sina tillhörigheter i Darnassus.",al={"vem är velinde","velindes bakgrund"}},{q="Vad finns i hennes låsta kista?",a="I skåpet ligger Velinde's Journal, en personlig redogörelse för hennes plikter som kastar ljus över vad som fick henne att lämna Night Elf-länderna.",al={"vad finns i velindes skåp","innehåll i velindes skåp"}}},fx={["7f8c7b68"]={q="Vad är Velinde's Key?",a="Velinde's Key är nyckeln till kistan där prästinnan Velinde Starsongs personliga tillhörigheter förvaras. Efter hennes plötsliga avfärd anförtroddes den åt Sentinels i Darnassus. Thyn'tel Bladeweaver förvarar den för att skydda den försvunna prästinnans privata ägodelar i Sentinelernas logement.",al={"velinde's key","vad är velinde's key","nyckeln till velindes kista"}},["927d5f5e"]={q="Varför behövs Velinde's Key?",a="Du behöver nyckeln för att öppna Velindes förvaringskista i Sentinelernas logement. Efter att ha fått höra om henne från Tome of Mel'Thandris ger en granskning av hennes tillhörigheter, särskilt hennes personliga journal, den bästa chansen att ta reda på varför den vördnadsvärda prästinnan försvann och vart hennes plikter förde henne.",al={"varför behöver jag velinde's key","varför vill man ha velinde's key","syftet med velinde's key"}}},fp="13,176,15.443.0,18.300.1,29.155.0,22.137.0,24.161.0,38.128.0"}
P.entries["item:venomtail-antidote"] = {n="Venomtail Antidote",s="I Durotar behövs Venomtail Antidote omedelbart för att rädda en spejare från skorpiongift. Kor'ghan brygger botemedlet i Orgrimmar åt Rhinag, som ligger förgiftad nära Durotars nordvästra gräns.",h="I Durotar behövs Venomtail Antidote omedelbart för att rädda en spejare från skorpiongift.",kw={"motgift","cleft of shadow","botemedel","durotar","kor'ghan","orgrimmar","rhinag","scorpid","venomtail"},ang={["faction:Horde"]="Som medlem av Horde ställs du inför Durotars obarmhärtiga öken. För att rädda Rhinag krävs snabb samordning mellan spejare i vildmarken och stadens apotekare.",["race:Troll"]="Som troll vet du att stoltheten sitter djupt. Rhinag riskerar hellre att dö ensam i ödemarken än att utsättas för öppet hån i Sen'jin Village för att ha besegrats av en skorpion."},sec={{t="En kapplöpning mot giftet",b="Durotars venomtail-skorpioner kan döda en krigare inom en timme efter ett djupt stick. Rhinag, en trollspejare, blev förgiftad nära den nordvästra gränsen, långt från hjälp. Hans enda chans är ett botemedel från Kor'ghan, en apotekare i Orgrimmars Cleft of Shadow."},{t="Kor'ghans botemedel",b="För att hitta Kor'ghan måste du ta dig ned under Orgrimmar. Han kan allt om öknens gifter och starka botemedel och gör i ordning en flaska som renar bort giftet innan det blir dödligt. Brygden stoppar giftet och besparar Rhinag en förödmjukande död i vildmarken. Kor'ghan kräver ändå att spejaren genomför fler prövningar och jakter för att sona sin oförsiktighet."}},faq={{q="Vad används Venomtail Antidote till?",a="Venomtail Antidote motverkar det dödliga giftet från venomtail-skorpioner. Rhinag, en förgiftad troll nära Durotars nordvästra gräns, behöver det innan giftet dödar honom.",al={"motgiftets syfte","vem behöver venomtail antidote","vad gör venomtail antidote"}},{q="Vem brygger Venomtail Antidote?",a="Kor'ghan brygger motgiftet i Cleft of Shadow under Orgrimmar. Han känner till Durotars skorpiongifter och hur man motverkar deras stick.",al={"vem tillverkar motgiftet","var får man tag på venomtail antidote","kor'ghans motgift"}},{q="Varför är tiden så viktig när man hämtar motgiftet?",a="Venomtail-gift kan döda Rhinag inom en timme efter sticket. Du måste skaffa motgiftet och skynda tillbaka med det genom Durotar för att hindra honom från att dö.",al={"varför skynda med motgiftet","hur lång tid har rhinag kvar","venomtail-giftets tidsgräns"}},{q="Varför tvekar Rhinag att söka hjälp i Sen'jin Village?",a="Rhinag skäms över att ha fallit för en vanlig skorpion. Han fruktar att hans folk i Sen'jin Village kommer att håna hans oförsiktighet och dumhet om han återvänder försvagad.",al={"varför inte gå till sen'jin","rhinags stolthet","varför gömma sig i durotar"}}},fx={ba1b91bb={q="Vad är Venomtail Antidote?",a="Venomtail Antidote är en specialblandning som framställts för att neutralisera det dödliga giftet från Durotars venomtail-scorpider. Utan den går den som blir djupt stungen av dessa aggressiva bestar en snabb och plågsam död när giftet sprids genom blodet.",al={"vad är venomtail antidote","information om venomtail antidote","botemedel mot venomtail-gift"}}},fp="18,191,24.249.0,15.342.0,40.168.0,33.136.0,52.144.0,55.158.0"}
P.entries["item:venomtail-poison-sac"] = {n="Venomtail Poison Sac",s="I Durotar kan en skorpions gift föra en jägare nära döden, medan dess giftsäck innehåller det alkemister behöver för att framställa ett botemedel.",h="I Durotar kan en skorpions gift föra en jägare nära döden, medan dess giftsäck innehåller det alkemister...",kw={"motgift","durotar","kor'ghan","gift","rhinag","säck","skorpion","venomtail"},ang={["class:Hunter"]="Som jägare kan du ta Rhinags olycka som en varning: att jaga farliga bestar utan att känna till deras gift eller bära med sig ett botemedel kan kosta dig livet.",["faction:Horde"]="Som ung Horde-äventyrare i Durotar lär du dig att lokala gifter kan döda den som rusar oförberedd in i de röda ödemarkerna."},sec={{t="Ett dödligt gift och dess botemedel",b="Skorpider strövar omkring bland Durotars röda klippor, däribland Venomtail Scorpids, Corrupted Scorpids och Death Flayer. Deras stjärtsäckar innehåller ett snabbverkande gift som kan övermanna även erfarna krigare om det lämnas obehandlat. Samma säckar innehåller de viktigaste ämnena alkemister behöver för att framställa ett motgift. När en skorpion stack jägaren Rhinag utanför Orgrimmar behövde de lokala alkemisterna fyra färska giftsäckar för att tillreda ett botemedel och neutralisera giftet i hans ådror."}},faq={{q="Vilka varelser bär på dessa giftsäckar?",a="Skorpider i Durotar bär på giftsäckarna, främst Venomtail Scorpids nära Orgrimmar, samt Corrupted Scorpids och den sällsynta Death Flayer.",al={"vem släpper venomtail poison sac","var får man tag på venomtail poison sac","vilka skorpioner har giftsäckar"}},{q="Vad används giftsäcken till?",a="Kor'ghan i Orgrimmar använder säckarna för att destillera ett specialiserat motgift, som brådskande behövs för att behandla Rhinag efter att han blev stucken och förgiftad under jakten utan ordentliga förberedelser.",al={"vad används venomtail-säcken till","varför behöver jag venomtail poison sac"}},{q="Vem kan brygga motgiftet från säckarna?",a="Kor'ghan i Orgrimmar vet hur man förädlar det råa giftet från fyra intakta säckar till en läkande brygd innan giftet blir dödligt.",al={"vem brygger motgiftet","var lämnar man in venomtail-säckar","kor'ghan venomtail"}}},fx={["7ee9d5ba"]={q="Vad är en Venomtail Poison Sac?",a="En Venomtail Poison Sac är det giftproducerande organ som utvinns ur de farliga skorpider som stryker omkring i Durotar, framför allt venomtail-scorpiderna nära Gates of Orgrimmar. Vätskan inuti innehåller ett ovanligt potent och snabbverkande gift, vilket gör varelserna till ett dödligt hot mot varje oförsiktig jägare som vandrar genom de torra, röda ödemarkerna.",al={"vad är venomtail poison sac","venomtail poison sac i historien","om venomtail-säcken"}},c7932c21={q="Var kommer en Venomtail Poison Sac ifrån?",a="De här säckarna utvinns direkt ur de skorpider som hör hemma på Durotars hårda slätter, däribland venomtail-scorpider, corrupted-scorpider och death flayers. De är naturliga organ hos bestarna, biologiska giftreservoarer som skorpiderna utvecklat för att kuva byten och försvara sig mot rovdjur i den ogästvänliga ödemarken.",al={"var kommer venomtail poison sacs ifrån","vem släpper venomtail poison sac","venomtail poison sac ursprung"}}},fp="20,127,29.453.0,39.142.0,32.176.0,42.131.0"}
P.entries["item:venture-co-documents"] = {n="Venture Co. Documents",s="De här hårt sammanbundna pappren hittades i en låda bland resterna av en förstörd karavan i östra Mulgore. De beskriver Venture Companys verksamhet och bekräftar kartellens olagliga rovdrift i taurenfolkets hemland.",h="De här hårt sammanbundna pappren hittades i en låda bland resterna av en förstörd karavan i östra Mulgore.",kw={"morin cloudstalker","gruvdrift i mulgore","ravaged caravan","venture co documents","venture company"},ang={["profession:Mining"]="Papperen hittades packade tillsammans med råa mineralprover, vilket bevisar att fotbergen rymmer rika, orörda ådror som är redo att grävas ut.",["race:Tauren"]="Jordmoderns heliga mark vanhelgas av goblinernas maskiner. Genom att lämna in papperen kan de äldste bekräfta omfattningen av skändningen och inleda vedergällningsanfall."},sec={{t="Bevis på exploatering",b="Dokumenten hittades packade ovanpå malm och mineraler i resterna av en plundrad vagn och avslöjar omfattningen av Venture Companys intrång i Mulgore. Den goblinledda kartellen är känd över hela Kalimdor för hänsynslös skogsavverkning och okontrollerad utgrävning, och har i tysthet upprättat borr- och gruvutposter i de östra fotbergen. Morin Cloudstalker och taurenfolkets Outrunners använder de beslagtagna räkenskaperna för att bedöma hotet mot sina heliga förfädersslätter och samla jägare för att driva bort inkräktarna."}},faq={{q="Vad innehåller Venture Co. Documents?",a="Pappersbunten beskriver Venture Companys gruvdrift och utvinning i östra Mulgore och visar att goblinföretaget aktivt utvinner och forslar bort regionens naturliga mineralrikedomar.",al={"innehåll i venture co-papper","vad är venture-dokument","vad står i dokumenten"}},{q="Var hittades dokumenten?",a="De hämtas ur en förseglad låda från Venture Company, som hittades bland vrakdelarna efter en plundrad vagn vid Ravaged Caravan, öster om Bloodhoof Village.",al={"var hittar jag dokumenten","venture-dokumentens plats","låda vid ravaged caravan"}},{q="Vem behöver se de här pappren?",a="De måste lämnas till Morin Cloudstalker, en taurenjägare som är stationerad längs huvudleden öster om Bloodhoof Village och vakar över säkerheten i Mulgore.",al={"vem ska jag lämna dokumenten till","lämna in venture-dokument","morin cloudstalker dokument"}},{q="Varför gräver Venture Company i Mulgore?",a="Venture Company drivs enbart av vinstintresse och söker efter rika mineralådror och otämjda områden där värdefull malm kan brytas, helt utan hänsyn till ursprungsbefolkningens avtal, andliga seder eller miljön.",al={"varför är gobliner i mulgore","venture cos mål i mulgore","varför gräver venture co"}}},fx={["33362eae"]={q="Var kommer Venture Co. Documents ifrån, och vem skrev dem?",a="De här dokumenten handlar om Venture Companys hemliga gruvverksamhet i Mulgore östra utlöpare. De är adresserade till Supervisor Fizsprocket på uppdrag av företagets rådgivande styrelse och President Razdunk. Dokumenten packades ovanpå en låda med råmalm och mineraler som hittades nära en plundrad karavan, redo att fraktas iväg tillsammans med slätternas stulna rikedomar.",al={"venture co. documents ursprung","vem skapade venture co. documents","var kommer venture co.-handlingarna ifrån"}},f91b68fc={q="Varför vill Morin Cloudstalker ha Venture Co. Documents?",a="Tauren Outrunners som skyddar Mulgore behöver obestridliga bevis på Venture Companys intrång. Morin Cloudstalker behöver de här handlingarna för att bekräfta omfattningen av goblinernas gruvplaner. Då får försvararna av Bloodhoof Village den viktiga information de behöver för att stoppa exploateringen och plundringen av sina förfäders marker.",al={"varför vill morin ha venture co. documents","varför behålla venture co. documents","vem vill ha venture co.-handlingarna"}}},fp="21,185,24.464.0,42.176.0,38.145.0,30.149.0,46.194.0"}
P.entries["item:venture-co-engineering-plans"] = {n="Venture Co. Engineering Plans",s="Venture Co. Engineering Plans är mekaniska ritningar som förvaras i goblinernas sågverk i Windshear Crag. De har hämtats av Alliansens agenter och visar hur de tunga maskinerna som ödelägger Stonetalon Mountains fungerar.",h="Venture Co.",kw={"covert ops","cragpool lake","ingenjörsritningar","gaxim rustfizzle","stonetalon","venture co.","windshear crag"},ang={["profession:Engineering"]="Venture Companys brutala, resurskrävande maskiner kanske saknar finess, men deras ritningar ger värdefulla insikter i tunga industrimaskiner.",["race:Gnome"]="För gnomiska uppfinnare är det både en intellektuell seger och en skattkista av industriella idéer att anpassa att lägga beslag på rivalernas goblinritningar."},sec={{t="Industriella hemligheter",b="Windshear Crag är höljt i rök och fullt av skogsmaskiner när Venture Company skövlar skogarna i Stonetalon. Inne i deras sågverk söder om Cragpool Lake finns dessa konstruktionsritningar som visar exakt hur deras specialbyggda skogsmaskiner är konstruerade, vilka styrkor de har och var deras svagheter finns."},{t="Gnomisk spionverksamhet",b="Gnomingenjören Gaxim Rustfizzle samordnade en hemlig operation för att sabotera Venture Companys sågverk och säkra dokumenten. Sprängladdningar kan störa verksamheten direkt, men med ritningarna kan Alliansens hantverkare systematiskt utnyttja svagheter i goblinernas utrustning och anpassa deras nyskapande konstruktioner för Alliansens projekt."}},faq={{q="Var finns Venture Co. Engineering Plans?",a="Ritningarna förvaras i Venture Companys huvudsakliga sågverk i Windshear Crag, söder om Cragpool Lake i Stonetalon Mountains.",al={"var hittar man ingenjörsritningarna","ritningarnas plats i stonetalon","var finns ritningarna"}},{q="Vem vill ha de här ritningarna?",a="Gaxim Rustfizzle, en gnom i Alliansen som samordnar hemliga uppdrag i Stonetalon Mountains, skickar agenter för att hämta dem.",al={"vem behöver ritningarna","vem lämnar in ingenjörsritningarna","gaxim rustfizzles ritningar"}},{q="Varför är de här ritningarna viktiga för Alliansen?",a="Ritningarna avslöjar avgörande konstruktionsfel i Venture Companys skogsmaskiner. Det hjälper agenter att slå ut dem effektivare och ger samtidigt Alliansens gnomer industrikonstruktioner att införliva i sina egna uppfinningar.",al={"varför stjäla ritningarna","vad används ritningarna till"}},{q="Vilken operation har koppling till stölden av ritningarna?",a="Att säkra ritningarna är huvudmålet med Covert Ops - Alpha. Uppdraget går ut på att placera ut tändare på området, men operationen lyckas först när ritningarna återförs.",al={"covert ops alpha mål","vilket uppdrag är det här till"}}},fx={["605bae91"]={q="Vad är Venture Co. Engineering Plans?",a="De här dokumenten innehåller detaljerade tekniska scheman och ritningar som Venture Companys ingenjörer skapat i Stonetalon Mountains. De förvaras i företagets sågverk nära Cragpool Lake och beskriver konstruktionen, ledningsdragningen och driften bakom avverkningsmaskineriet och industrimaskinerna som företaget använder för att röja Windshear Crag.",al={"vad är venture co. engineering plans","venture companys ingenjörsplaner","venture co.-planerna"}},a84a85f7={q="Var kommer Venture Co. Engineering Plans ifrån?",a="Planerna kommer från Venture Companys industriella verksamhet i Windshear Crag. Företagets egna ingenjörer och operatörer tog fram dem för att övervaka avverkning och maskinbyggen. De förvarades säkert i det stora sågverket strax söder om Cragpool Lake innan de blev måltavla för Alliansens hemliga agenter.",al={"var kommer ingenjörsplanerna ifrån","vem skapade venture co. engineering plans","venture co.-planernas ursprung"}}},fp="29,160,18.274.0,17.295.1,52.157.0,34.127.0,51.184.0,47.175.0"}
P.entries["item:venture-co-letters"] = {n="Venture Co. Letters",s="Venture Co. Letters är intern korrespondens som återfanns i Windshear Mine i Stonetalon Mountains. De stals under täckmantel av explosiva avledningsmanövrer och ger Night Elf-sentinellerna avgörande underrättelser om goblinernas industriella verksamhet i området.",h="Venture Co.",kw={"kaela shadowspear","sentinels","stonetalon mountains","venture co","venture co. letters","windshear crag","windshear mine"},ang={["faction:Alliance"]="Alliance-spejare samordnar hemliga uppdrag mot Venture Company för att skydda Night Elf-bosättningar i Stonetalon från rovdrift på naturresurser.",["race:NightElf"]="Goblinernas skogsmaskiner vanhelgar Stonetalon och angriper Kalimdors vildmark i dess hjärta, så underrättelser om Venture Companys planer är livsviktiga för Sentinels."},sec={{t="Underrättelser om industrin",b="Windshear Crag har tagits över av Venture Company, vars skogsmaskiner och dagbrott skövlar den uråldriga skogen. För att få en fullständig bild av kartellens ambitioner genomförde Alliance-agenter hemlig sabotageverksamhet för att skapa avledande manövrer och infiltrera Windshear Mine. De återfunna breven innehåller privata meddelanden och logistikdokument som beskriver företagets verksamhet i området och ger ledningen för Sentinels insikt i hur The Defilers organiserar sin arbetsstyrka och sina försörjningslinjer."},{t="Överlämning till Sentinels",b="När breven väl säkrats djupt inne i gruvan skyndas de tillbaka till Sentinel-befälhavaren Kaela Shadowspear. Sentinels står under press från både goblinernas The Defilers och Hordens intrång i Stonetalon och förlitar sig på den stulna korrespondensen för att förutse Venture Companys nästa drag och skydda det som återstår av de heliga bergen."}},faq={{q="Vad är Venture Co. Letters?",a="Det är interna verksamhetsdokument och korrespondens som Venture Company förvarade i Windshear Mine i Stonetalon Mountains.",al={"venture co-brev","vad är breven","stonetalon-brev"}},{q="Var finns breven?",a="De finns bland Venture Co. Documents, som förvaras inne i Windshear Mine vid den östra änden av Windshear Crag.",al={"var finns breven","brevens plats","brev i windshear mine"}},{q="Vem vill ha breven?",a="Gnomagenten Gaxim Rustfizzle leder den hemliga operationen för att stjäla dem, och de överlämnas till slut till Kaela Shadowspear, som leder de lokala Night Elf-sentinellerna.",al={"vem får breven","vem vill ha dem","lämna in brev"}},{q="Varför behöver Sentinels den här korrespondensen?",a="Sentinels kämpar för att stoppa den hejdlösa avskogningen och utgrävningen av Stonetalon. Breven avslöjar Venture Companys logistikplanering och verksamhetsprioriteringar, vilket hjälper försvararna att planera hur de ska bekämpa dem.",al={"varför vill sentinels ha brev","sentinels intresse"}}},fx={["52f3029e"]={q="Var kommer Venture Co. Letters ifrån, och vem skrev dem?",a="Dokumenten kommer från Venture Companys gruvdrift vid Windshear Mine, längst österut i Windshear Crag. De består av intern företagskorrespondens som förvaras bland handlingarna på platsen, skriven av företagets regionala operatörer och arbetsledare för att samordna den aggressiva utvinningen och avverkningen i Stonetalon.",al={"venture co. letters ursprung","vem skrev venture co. letters","var kommer breven ifrån"}}},fp="19,203,23.392.0,25.311.1,33.146.0,28.104.0,24.157.0,46.169.0"}
P.entries["item:verdant-note"] = {n="Verdant Note",s="Verdant Note är en kallelse till unga tauren-druider i Camp Narache. Den skickas på uppdrag av druidmentorn Gart Mistrunner och uppmanar de unga lärlingarna att infinna sig för träning och börja lära sig Earthmothers riter.",h="Verdant Note är en kallelse till unga tauren-druider i Camp Narache.",kw={"camp narache","druid","earthmother","gart mistrunner","mulgore","red cloud mesa","verdant note"},ang={["class:Druid"]="Detta pergament bekräftar att du formellt har antagits till druidstudier bland tauren. Därmed börjar din livslånga resa i gemenskap med Earthmother.",["race:Tauren"]="För Shu'halo är druidismen ett förfäderskall som är direkt knutet till att återställa balansen i deras heliga jaktmarker i Mulgore."},sec={{t="En kallelse till stigen",b="Unga tauren som visar en andlig samhörighet med naturen får Verdant Note kort efter att de inlett sina prövningar på Red Cloud Mesa. Ett sändebud från Gart Mistrunner bär det korta brevet, som uppmanar lärlingen att söka upp mentorn i Camp Narache. Rastlösa andar och element i förändring har börjat plåga Mulgore, så att lära upp nya druider har blivit en brådskande uppgift för de äldste."},{t="Earthmothers läror",b="När lärlingarna svarar på kallelsen invigs de i naturens djupare mysterier. Gart Mistrunner varnar de unga druiderna för att nattalverna, trots sin gemensamma samhörighet med vildmarken, håller fast vid sin urgamla stolthet och är avvisande. Tauren-druidism kretsar helt kring vördnad för Earthmother och vägleder lärlingarna till att lyssna till landets rastlösa förfädersröster och tjäna som hennes levande redskap."}},faq={{q="Vad är Verdant Note?",a="Det är en skriftlig kallelse till unga tauren-druider i Camp Narache. Den uppmanar dem att söka upp sin lokala tränare, Gart Mistrunner, och formellt inleda sin andliga utbildning.",al={"föremålet verdant note","vad är det här brevet"}},{q="Vem skickar Verdant Note?",a="En budbärare skickar brevet på uppdrag av Gart Mistrunner, druidtränaren som är stationerad i Camp Narache på Red Cloud Mesa.",al={"vem skickade verdant note","vem skrev verdant note"}},{q="Varför kallar Gart Mistrunner på druidlärlingarna?",a="Förfädersandar i Mulgore och närliggande områden har blivit ovanligt rastlösa. Gart behöver snabbt utbilda nyväckta druider så att de kan tala med vildmarkens andar och hela det störda landet.",al={"varför vill gart träffa mig","gart mistrunners anledning"}},{q="Vad säger Gart till druiderna om nattalverna?",a="Gart varnar för att nattalverna är stolta och knappast välkomnar tauren i sina kretsar, trots deras gemensamma heliga band till naturen. Han råder lärlingarna att i stället fokusera på Earthmothers läror.",al={"nattalver och tauren-druider","vad gäller nattalverna"}}},fx={["59de7025"]={q="Varför vill Gart Mistrunner att du ska få Verdant Note?",a="Gart Mistrunner skickar dig Verdant Note för att kalla dig till din druidträning i Camp Narache. Rastlösa andar har rört sig i Mulgore och länderna bortom, och Gart behöver nya noviser som lär sig lyssna till Jordmodern och naturens andar. Anteckningen är en brådskande kallelse att träda fram och ta på dig dina plikter som naturens avatar.",al={"varför verdant note","varför skickar gart anteckningen","syftet med verdant note"}}},fp="12,158,18.328.0,28.329.0,25.135.0,27.126.0,51.162.0,53.189.0"}
P.entries["item:verdant-sigil"] = {n="Verdant Sigil",s="Verdant Sigil är en ingraverad druidisk symbol som ges till unga Night Elf-druider när de inleder sin träning i Shadowglen. Den bärs som en kallelse från druidmentorn Mardant Strongoak och markerar novisens formella inträde i Cenarion-läran under Aldrassils grenar.",h="Verdant Sigil är en ingraverad druidisk symbol som ges till unga Night Elf-druider när de inleder sin träning...",kw={"aldrassil","druid","emerald dream","ilthalaine","mardant strongoak","shadowglen","teldrassil","verdant sigil"},ang={["class:Druid"]="För unga Night Elf-druider är mottagandet av Verdant Sigil den traditionella första övergångsriten, som överbryggar klyftan mellan enkel skogsvård och disciplinerad Cenarion-undervisning.",["race:NightElf"]="Symbolen ges under Aldrassils lövverk och representerar kaldoreiernas bestående tradition att stämma sin ande med naturen och Teldrassils väktare."},sec={{t="En kallelse till stigen",b="I Shadowglens skyddade trädkronor får unga Night Elf som känner vildmarkens kallelse Verdant Sigil av Conservator Ilthalaine. Symbolen skickas via bud från tränaren Mardant Strongoak och leder noviserna upp bland grenarna i det stora trädet Aldrassil. Att bära symbolen är en formell inbjudan att lämna de enkla sysslorna bakom sig och påbörja seriös träning i gemenskap med naturandar och The Emerald Dreams djupa mysterier."},{t="Det första steget in i drömmen",b="När den unga dru iden visar upp symbolen för Mardant Strongoak inleder hen sin livslånga bana. Noviserna är ännu inte redo att vandra i The Emerald Dreams sovande trans, men när symbolen erkänns börjar mentorskapet. Under Mardants ledning lär sig de invigda att tyda vildmarkens viskningar och bemästra tidiga former av skepnadsskifte och läkekonst i Teldrassils tjänst."}},faq={{q="Vad är syftet med Verdant Sigil?",a="Verdant Sigil är en introducerande symbol som ges till Night Elf-druider under utbildning i Shadowglen. Den fungerar som en formell kallelse från tränaren Mardant Strongoak och leder de nya druiderna till honom i trädet Aldrassil, där deras formella utbildning börjar.",al={"vad gör verdant sigil","varför har jag verdant sigil","användning av verdant sigil"}},{q="Vem delar ut Verdant Sigil?",a="Conservator Ilthalaine ger symbolen till blivande druider kort efter att de börjat hjälpa honom i Shadowglen och förmedlar ett meddelande från Mardant Strongoak.",al={"vem ger verdant sigil","var får jag verdant sigil"}},{q="Vart ska jag ta symbolen när jag har fått den?",a="Du tar symbolen till Mardant Strongoak, druidtränaren i det stora trädet Aldrassils centrala salar, mitt i Shadowglen.",al={"vart ska jag ta verdant sigil","vem tar emot verdant sigil","lämna in verdant sigil"}},{q="Vad händer när jag visar upp symbolen för Mardant Strongoak?",a="Mardant tar emot symbolen och välkomnar dig formellt som sin elev. Han blir din vägledare i konsten att förena dig med naturen och lovar att förbereda dig för The Emerald Dreams invecklade mysterier när du blir starkare.",al={"vad gör mardant med symbolen","efter verdant sigil"}}},fx={e7925638={q="Vad är Verdant Sigil?",a="Verdant Sigil är en graverad symbol som druidmentorn Mardant Strongoak skickat till unga nattalvnoviser i Shadowglen. Den bärs av en budbärare till Conservator Ilthalaine och fungerar som en formell kallelse och introduktionssymbol. Den kallar lovande nybörjare att klättra upp i Aldrassils grenar och börja lära sig naturens och The Emerald Dreams vägar.",al={"vad är verdant sigil","föremålet verdant sigil","verdant sigil i historien"}},["1efc6d6b"]={q="Var kommer Verdant Sigil ifrån, och vem skapade den?",a="Sigillet kommer från Mardant Strongoak, druidtränaren som håller till i Aldrassils väldiga grenar i Shadowglen. Mardant sökte upp noviser som var redo att stämma sig med naturen och skickade symbolen med en kurir till Conservator Ilthalaine, så att den skulle nå lovande unga druider som tog sina första steg i Teldrassil.",al={"vem skapade verdant sigil","var kommer verdant sigil ifrån","verdant sigils ursprung"}},fa84d5c5={q="Varför vill någon ha Verdant Sigil?",a="Mardant Strongoak ber dig ta med sigillet till honom som bevis på att du är redo och villig att lära dig. Genom att ta emot kallelsen och återlämna det till mentorn knyter du formellt band till honom och visar att du är beredd att studera andarna, bemästra formskiftning och utforska The Emerald Dreams mysterier.",al={"varför vill man ha verdant sigil","varför vill mardant ha verdant sigil","vem vill ha verdant sigil"}}},fp="13,116,21.387.0,29.365.0,41.133.0,32.119.0,44.127.0,61.185.0"}
P.entries["item:verna-s-westfall-stew-recipe"] = {n="Verna's Westfall Stew Recipe",s="Verna's Westfall Stew Recipe följer med till Salma Saldean när familjen Furlbrow förbereder sig på att lämna sin gård. Hennes handskrivna recept ger en välbekant tröst åt dem som blir kvar.",h="Verna's Westfall Stew Recipe följer med till Salma Saldean när familjen Furlbrow förbereder sig på att lämna...",kw={"matlagning","furlbrow","recept","saldean's farm","salma saldean","verna furlbrow","westfall stew"},ang={["faction:Alliance"]="För Alliansen står receptet för lojala gårdsägare som drivs från sin mark av laglöshet medan Stormwind kämpar för att hävda sin makt.",["profession:Cooking"]="För kockar är det här handskrivna papperet en älskad del av traktens historia, som bevarar Westfalls matkultur när gårdarna faller samman."},sec={{t="En avskedsgåva",b="Verna och Farmer Furlbrow har brukat sin gård i Westfall i åratal, men Defias Brotherhood och förrymda skördegolemer härjar nu över landsbygden. De väntar på att deras vagn ska repareras så att de kan fly mot Stormwind. Medan de väntar skriver Verna ner sitt älskade recept på Westfall Stew. Hon ger receptet till resenärer på väg till vännen och grannen Salma Saldean, så att den välbekanta grytan kan fortsätta ge tröst åt dem som blir kvar."}},faq={{q="Varför ger Verna bort sitt gryt­recept?",a="Verna och hennes make flyr från Westfall eftersom banditer och förrymda maskiner har tagit över deras åkrar. När de lämnar sin gård vill Verna att vännen Salma Saldean ska fortsätta laga grytan åt dem som stannar kvar.",al={"varför verna ger bort receptet","varför receptet på westfall stew","syftet med vernas recept"}},{q="Vem är receptet avsett för?",a="Receptet är avsett för Salma Saldean, som bor strax bortom vägskälet vid Saldean Farm.",al={"vem får receptet","vem ska jag lämna receptet till","vart ska gryt­receptet"}},{q="Vart planerar familjen Furlbrow att bege sig?",a="Familjen Furlbrow väntar på att deras vagn ska repareras så att de kan fly till tryggheten i Stormwind City och undan kaoset och laglösheten som hotar landsbygden.",al={"vart ska familjen furlbrow","vart ska verna","familjen furlbrows resmål"}},{q="Vad gör Westfall Stew särskild i trakten?",a="Westfall Stew är en regional basrätt som görs möjlig av lokalt jordbruk och vilt. När maten tryter och gårdar överges hjälper delade, mättande recept överlevande jordbrukarfamiljer att klara sig.",al={"vad är westfall stew","varför westfall stew är viktig","westfall stews historia"}}},fx={["39bb19d7"]={q="Vad är Verna's Westfall Stew Recipe?",a="Det är en handskriven matlagningsguide, nedtecknad av Verna Furlbrow, med ingredienser och instruktioner för att laga mustig Westfall-gryta. Verna vill inte låta sin välkända lokala rätt gå förlorad när hon överger sitt farliga hemland, så hon skriver ner instruktionerna på pergament så att grannen kan fortsätta mätta både resenärer och lokalbor.",al={"vernas gryt-recept","vad är verna's westfall stew recipe","föremålet verna's westfall stew recipe"}},b68c02b6={q="Var kommer Verna's Westfall Stew Recipe ifrån, och vem skrev den?",a="Verna Furlbrow klottrade ner receptet vid Furlbrows gård i norra Westfall. När angreppen från Defias-banditer och asätande bestar blev allt fler skrev hon själv ner det, precis innan hon packade familjens vagn för att fly från landsbygden.",al={"vem skapade vernas gryt-recept","vernas recepts ursprung","var kommer vernas gryt-recept ifrån"}}},fp="28,152,15.463.0,41.219.0,28.106.0,39.167.0,47.172.0"}
P.entries["item:verner-s-note"] = {n="Verner's Note",s="Verner's Note är en skriftlig rekvisition, författad av Lakeshires smed Verner Osgood och förd till Smith Argus i Goldshire. Den beskriver en akut järnbrist i Redridge och ber smeden i Elwynn om hästskor i all hast.",h="Verner's Note är en skriftlig rekvisition, författad av Lakeshires smed Verner Osgood och förd till Smith...",kw={"goldshire","hästskor","lakeshire","redridge mountains","smith argus","priset för hästskor","verner osgood","verner's note"},ang={["faction:Alliance"]="Brevet visar hur hårt Stormwinds infrastruktur på landsbygden pressas och hur gränsstäder som Lakeshire måste samordna sig med byar i rikets kärnområde bara för att hålla försörjningslinjerna igång.",["profession:Blacksmithing"]="Brevet belyser gränskrigets logistik: när vapen och rustningar slukar varje tacka måste vardagliga förnödenheter som hovslagarmaterial hämtas från tryggare bosättningar som Goldshire."},sec={{t="En vädjan om järn",b="Att upprätthålla Lakeshires försvar kräver stora mängder bearbetad metall. Stormwind Guard är stationerad i staden och hårt ansatt av invaderande gnoller och lokala faror. Verner Osgood har förbrukat nästan alla sina järnförråd för att hålla soldaterna beväpnade och bepansrade. Därför har Lakeshires stall försummats och saknar till och med grundläggande hästskor till hästarna. Brevet visar hur Verner sväljer sin stolthet och ber Smith Argus i Goldshire skicka färdiga hästskor utifrån, så att stadens hästar kan fortsätta röra sig."}},faq={{q="Vad står det i Verner's Note?",a="I brevet förklarar Verner för Smith Argus att han har förbrukat sina metallförråd för att beväpna Stormwind Guards i Lakeshire. Eftersom han inte har något järn kvar att smida skor till de lokala hästarna ber han om en direktleverans av hästskor från Goldshire.",al={"innehållet i verners note","vad står det i brevet","meddelandet i verners note"}},{q="Vem är Verner Osgood?",a="Verner Osgood är den lokala smeden i Lakeshire i Redridge Mountains. Han ansvarar för att utrusta stadens försvarare och hålla utrustningen i bruksskick samt se till att riddjur får skor.",al={"vem är verner","verner osgood redridge"}},{q="Vem tar emot brevet?",a="Brevet förs västerut längs vägen till Smith Argus, stadssmeden som arbetar utanför smedjan i Goldshire i Elwynn Forest.",al={"vem får verners note","var ska jag lämna brevet","vem är smith argus"}},{q="Varför kan inte Verner tillverka hästskorna själv?",a="Lakeshire befinner sig i kris på grund av gnoller och andra regionala hot. Verner lägger all sin tid och allt sitt råjärn på att smida vapen och reparera utrustning åt Stormwind Guard, så inget blir över till stallen.",al={"varför behöver lakeshire hästskor","varför hämta hästskor från goldshire"}}},fx={["486dfee9"]={q="Vad är Verner's Note?",a="Det är ett handskrivet brev från Lakeshires lokale smed, Verner Osgood, avsett för Smith Argus i Goldshire. Brevet förklarar att Lakeshires smedja har förbrukat sina järnreserver när den utrustat de lokala Stormwind-vakterna mot de växande hoten i trakten. Därför finns inget järn kvar att tillverka hästskor till stadens stallhästar. Brevet är en officiell begäran om att Argus ska skicka en låda hästskor som hjälp.",al={"verner's note","vad är den här lappen","syftet med verner's note"}},b8effef9={q="Varifrån kommer Verner's Note, och vem skrev det?",a="Verner Osgood skrev brevet själv i sin smedja i Lakeshire, Redridge Mountains. Den hårt pressade stadsvakten behövde ständigt vapen för att stå emot gnolls och orcer i trakten, så Verner skrev brevet för att ordna en akut leverans från sin smedkollega i Elwynn Forest.",al={"vem skrev verner's note","varifrån kom verner's note","verner's notes ursprung"}},c0af4e8d={q="Varför vill någon ha Verner's Note?",a="Brevet berättar för Smith Argus att Verner Osgood har ont om järn och ber om att få låna femtio par hästskor tills Verners nästa järnleverans kommer. Om du levererar det kan Argus ordna hjälp till Lakeshires stall.",al={"varför vill argus ha verner's note","vem behöver verner's note","varför leverera verner's note"}}},fp="13,171,15.434.0,33.215.0,21.159.0,23.120.0,45.168.0"}
P.entries["item:verog-s-head"] = {n="Verog's Head",s="Regthar Deathgate söker efter Verog's Head som bevis på att Kolkar-ledaren har dött. Hövdingen befaller styrkor kring The Stagnant Oasis, och hans nederlag ska försvaga stammarna som hotar The Barrens.",h="Regthar Deathgate söker efter Verog's Head som bevis på att Kolkar-ledaren har dött.",kw={"the barrens","centaur","kolkar","regthar deathgate","the stagnant oasis","verog","verog the dervish","verog's head"},ang={["faction:Horde"]="Att besegra Verog och ta hans huvud hjälper till att säkra Hordens leder mellan The Crossroads och Southern Barrens mot centaurernas räder.",["race:Tauren"]="Som tauren känner du tyngden av Kolkars nederlag: ditt folk har uthärdat generationer av brutal krigföring mot Kalimdors centaurstammar."},sec={{t="En trofé från oasen",b="Kolkar-centaurerna hotar Horde-resenärer och försörjningsleder genom norra The Barrens. Verog the Dervish strövar omkring i det torra busklandet och lämnar sitt kommandotält vid The Stagnant Oasis oskyddat. Hordens agenter angriper hans styrkor kring paviljongen tills ett larm ljuder. Verog rusar tillbaka för att försvara sitt läger, där han dödas och halshuggs. Regthar Deathgate får hans huvud som bevis på att ännu en farlig Kolkar-hövding har fallit. Barak Kodobane's Head visas redan bredvid det."}},faq={{q="Vem var Verog the Dervish?",a="Verog the Dervish var en Kolkar-centaurisk krigsherre med bas vid The Stagnant Oasis i The Barrens. Han strövade över de torra slätterna och befällde de fientliga styrkorna kring oasens tält.",al={"vem är verog","verogs historia","verog the dervish"}},{q="Vem vill ha Verog's Head?",a="Regthar Deathgate, en orcisk veteran vid ett läger väster om The Crossroads, vill ha Verog's Head. Han samlar troféer från dödade Kolkar-krigsherrar för att försvaga deras krigshärar och moral.",al={"vem tar verogs huvud","regthar deathgate verog","lämna in verogs huvud"}},{q="Var finns Verog?",a="Verogs läger och kommandotält ligger vid The Stagnant Oasis, sydost om The Crossroads. Han återvänder för att försvara sin post när centaurvakter dödas och larmet går.",al={"var finns verog","verogs plats","tält vid stagnant oasis"}},{q="Vad händer med huvudet när det lämnas in?",a="Regthar Deathgate placerar Verog's Head bredvid Kodobane's Head. Huvudena markerar Hordens kampanj mot Kolkar-ledarna.",al={"vad gör regthar med huvudet","visning av centaurhuvuden"}}},fx={f5f2a432={q="Vad är Verog's Head?",a="Det är det avhuggna huvudet från Verog the Dervish, en av de framträdande Kolkar-centaurledarna som verkar från The Stagnant Oasis. Det är ett makabert bevis på hans död, avsett att övertyga Hordens garnison väster om The Crossroads om att hotet från den svårfångade befälhavaren är undanröjt för gott.",al={"föremålet verog's head","vad är verog's head"}},["7da1755c"]={q="Varifrån kommer Verog's Head?",a="Huvudet tas direkt från Verog the Dervish själv. Den kringvandrande Kolkar-ledaren strövar över The Barrens slätter, men när hans läger vid The Stagnant Oasis blir angripet återvänder han för att försvara sitt befälstält. Då kan du fälla honom och ta huvudet som trofé.",al={"varifrån kommer verog's head","vem släpper verog's head"}}},fp="12,202,21.496.0,26.172.0,23.179.0,21.175.0,47.122.0"}
P.entries["item:vial-of-innocent-blood"] = {n="Vial of Innocent Blood",s="En Vial of Innocent Blood är ett dystert alkemiskt reagens som samlas in av Syndicates skuggmagiker i ruinerna av Durnholde Keep. Royal Apothecary Society i Tarren Mill vill ha det, eftersom det fungerar som en viktig katalysator när experimentella gifter bryggs.",h="En Vial of Innocent Blood är ett dystert alkemiskt reagens som samlas in av Syndicates skuggmagiker i...",kw={"apothecary lydon","durnholde keep","hillsbrad foothills","oskyldigt blod","syndicate-skuggmagiker","tarren mill","vial of innocent blood"},ang={["faction:Horde"]="När Horden säkrar reagenset gynnas dess större territoriella ansträngningar mot Venture Companys skogsskövling i Stonetalon.",["race:Undead"]="Royal Apothecary Society drar sig sällan för moraliskt tvivelaktiga ingredienser och tar gärna från människobanditer för att främja sina alkemiska framsteg."},sec={{t="Ett fasansfullt reagens",b="I de sönderfallna murarna vid Durnholde Keep ägnar sig Syndicates fallna adelsmän av människosläktet åt mörka och osmakliga konster. Bland dem finns skuggmagiker som systematiskt samlar in oskyldigas blod till sina ockulta ritualer. Den makabra sedvänjan har väckt stort intresse hos Apothecary Lydon i Tarren Mill. Han behöver rent blod för att brygga ett experimentellt lugnande medel som ska neutralisera Venture Company i Stonetalon Mountains. Den föraktade apotekaren ser Syndicates dystra förråd som en bekväm genväg i sitt arbete."}},faq={{q="Vad används Vial of Innocent Blood till?",a="Apothecary Lydon i Tarren Mill använder blodet för att brygga ett specialiserat gift som ska dämpa aggressionen hos Venture Companys arbetare, som ställer till problem för Horden i Stonetalon Mountains.",al={"användning av oskyldigt blod","vad används vial of innocent blood till","användning av oskyldigas blod"}},{q="Vem bär på dessa flaskor?",a="De bärs av Syndicates skuggmagiker som är stationerade kring den förstörda fästningen Durnholde Keep i sydöstra Hillsbrad Foothills.",al={"vem släpper vial of innocent blood","var hittar man oskyldigt blod","syndicates skuggmagiker"}},{q="Varför har Syndicates skuggmagiker oskyldigt blod?",a="Syndicates människobanditer och fallna adelsmän använder skuggmagiker som samlar in och bevarar oskyldigas blod för sina egna mörka, osmakliga magiska experiment.",al={"varför har syndicate blod","syndicates blodritualer"}},{q="Varför behöver Apothecary Lydon blod från oskyldiga?",a="Lydon säger att oskyldigas blod har särskilda, sällsynta egenskaper som krävs för att framställa en brygd som kan driva våldsamheten ur sina offer och göra dem fogliga.",al={"varför oskyldigt blod","apothecary lydons blod"}}},fx={["21111c2c"]={q="Vad är Vial of Innocent Blood?",a="Det är en liten flaska med blod från oskyldiga offer, uppskattat som ett kraftfullt reagens av både mörka trollkarlar och alkemister. Det samlas inte in på hederliga eller vanliga sätt, utan tas särskilt för att driva lömska ritualer och kraftfulla kemiska blandningar.",al={"vad är vial of innocent blood","lore om vial of innocent blood","vad är det här blodet"}}},fp="22,176,18.377.0,44.168.0,24.124.0,50.139.0,52.136.0"}
P.entries["item:vial-of-phlogiston"] = {n="Vial of Phlogiston",s="En Vial of Phlogiston är ett alkemiskt ämne som mästersmeder använder för att härda ovanligt slitstark ringbrynja. Den vaktas i Razorfen Kraul, quilboarfolkets fäste, och är eftertraktad av både Alliansens och Hordens smeder, som smider särskilda stridsrustningar åt lovande krigare.",h="En Vial of Phlogiston är ett alkemiskt ämne som mästersmeder använder för att härda ovanligt slitstark...",kw={"brutal armor","fire hardened mail","furen longbeard","phlogiston","razorfen kraul","roogug","thun'grim firegaze","vial of phlogiston"},ang={["class:Warrior"]="Att skaffa en Vial of Phlogiston är ett viktigt steg mot att få ikonisk härdad rustning och visar att en krigare kan ta sig in i Razorfen Kraul.",["profession:Blacksmithing"]="Phlogiston står för avancerad specialiserad metallurgi och fungerar som ett viktigt flussmedel för härdning av legendarisk plåtringbrynja."},sec={{t="Smidets essens",b="Phlogiston är ett ytterst flyktigt, eldbärande ämne som värdesätts inom esoterisk metallurgi. Både dvärgsmeden Furen Longbeard i Stormwind och den nästan blinde orksmeden Thun'grim Firegaze i The Barrens anser att det är oumbärligt för att härda krigarrustningar bortom vanliga fysiska gränser. Utan detta alkemiska ämne går det inte att slutföra smidesteknikerna som krävs för Fire Hardened Mail eller Hordens Brutal Armor."},{t="Hämtad från snåren",b="För att få tag på en Vial of Phlogiston måste du ge dig in i Razorfen Krauls snåriga täta buskage, längst söderut i The Barrens. Phlogistonet förvaras djupt inne i det taggiga fästet av geomancern Roogug. Oavsett om du hämtar det åt Furen i Stormwind eller bär det över den dammiga marken till Thun'grims städ, kräver ämnet en farlig färd ner i fientligt quilboarterritorium."}},faq={{q="Vad används phlogiston till?",a="Mästersmeder använder phlogiston som en alkemisk härdningskatalysator. Det ger den extrema, koncentrerade hetta som behövs för att härda rå ringbrynja och järn till ovanligt slitstark krigarrustning.",al={"användning av vial of phlogiston","vad gör phlogiston","varför behöver jag phlogiston"}},{q="Vem bär på Vial of Phlogiston?",a="Flaskan bärs av Roogug, en quilboargeomancer som håller till djupt inne i Razorfen Krauls taggiga tunnlar i södra The Barrens.",al={"vem släpper vial of phlogiston","vial of phlogiston byte","var får man tag på vial of phlogiston"}},{q="Vilka smeder behöver det här materialet?",a="Både Furen Longbeard i Stormwind och Thun'grim Firegaze i The Barrens behöver en Vial of Phlogiston för att smida unika, härdade rustningar åt erfarna krigare.",al={"vem vill ha vial of phlogiston","phlogiston-uppdrag","vilka uppdrag kräver phlogiston"}}},fx={["3ab06e7f"]={q="Vad är Vial of Phlogiston?",a="Vial of Phlogiston innehåller ett ytterst sällsynt alkemiskt ämne, känt bland mästersmeder för sin intensiva hetta och sina härdande egenskaper. Specialiserade smeder i både Alliansen och Horden åtrår det. Den eldiga essensen används som en viktig katalysator när slitstark, härdad ringbrynja smids åt erfarna krigare.",al={"vad är vial of phlogiston","lore om phlogiston","föremålet vial of phlogiston"}}},fp="18,178,20.391.0,27.322.0,28.155.0,35.121.0,35.148.0"}
P.entries["item:vial-of-purest-water"] = {n="Vial of Purest Water",s="I södra Barrens välsignar Brine en flaska rent vatten åt en schamanlärling. Innehållet hjälper Islen Waterseer att bereda en Water Sapta för att se elementandar.",h="I södra Barrens välsignar Brine en flaska rent vatten åt en schamanlärling.",kw={"the barrens","brine","call of water","islen waterseer","silverpine","vial of purest water","water sapta"},ang={["class:Shaman"]="Som schaman tar du dig genom de sista stegen mot att kommunicera med vattenandar och göra anspråk på din Water Totem när du levererar det renade vattnet.",["faction:Horde"]="Som hordeschaman färdas du genom Kalimdor och Eastern Kingdoms under flaskans prövningar, och fördjupar ditt band med elementen."},sec={{t="Ett renat offer",b="Brine leder lärlingen genom prövningar i tålamod och rening innan vattnet förseglas i flaskan. Vattnet bär på en oblandad elementär renhet. Ta det genom Barrens till Islen Waterseer, som vakar vid en enslig strand. Hon behöver det för att brygga en Water Sapta. Utan så rent vatten kan en schaman inte kommunicera med andliga väktare på platser långt från de solstekta slätterna."},{t="Vägen till Water Totem",b="Islen använder det välsignade vattnet för att pröva lärlingens hängivenhet och öppna hens sinnen för dolda element. Hon blandar en del i en sapta, som blottar andar vid en avlägsen helgedom i Silverpine Forest. Hon sparar de återstående dropparna för att konfrontera och rena en vild manifestation någon annanstans. Att bära flaskan markerar en vändpunkt: lärlingen går från enkla sysslor till att direkt möta elementens verklighet."}},faq={{q="Vad används Vial of Purest Water till?",a="Flaskan innehåller vatten som renats och välsignats åt en schamanlärling. Islen Waterseer använder det för att brygga en Water Sapta, som ger den andliga syn som krävs för att uppfatta vattenelementaler, och för ytterligare rituella prövningar som krävs för att förtjäna en Water Totem.",al={"vial of purest water användning","vad gör flaskan","användning av rent vatten"}},{q="Vem bereder vattnet i flaskan?",a="Schamanen samlar vattnet under Brines ledning. Brine är en orkschaman och eremit djupt inne i södra Barrens; efter lärlingens prövningar välsignar Brine det renade vattnet och förseglar det i flaskan för transport.",al={"vem gjorde flaskan","vem fyller flaskan","brines vatten"}},{q="Vart måste flaskan föras?",a="Ta flaskan till Islen Waterseer på Barrens östra kust, strax söder om Ratchet och med utsikt över Great Sea.",al={"vem ska jag ge flaskan till","vart ska flaskan lämnas","lämna in purest water"}},{q="Vart leder ritualen efter att flaskan har lämnats över?",a="När Islen Waterseer tagit emot flaskan och bryggt saptan skickar hon schamanen över havet till Eastern Kingdoms. Helgedomen ligger i Silverpine Forest, söder om Undercity.",al={"vart går jag härnäst","nästa steg efter flaskan","silverpine vattenhelgedom"}}},fx={["3774bd18"]={q="Vad är Vial of Purest Water?",a="Vial of Purest Water är ett heligt kärl med rent vatten som väktaren Brine har välsignat och berett. Det anförtros åt shamaner under utbildning och innehåller vatten från rena källor runtom i landet, renat genom ritualer för att stämma dig med vattnets andar.",al={"vial of purest water","vad är vial of purest water"}},["273b8475"]={q="Varför vill Islen Waterseer ha Vial of Purest Water?",a="Islen Waterseer behöver det välsignade vattnet i flaskan för att brygga en Water Sapta åt dig. Om du dricker denna särskilda brygd får du andlig synförmåga och kan tala direkt med vattenelementarerna vid deras helgedom i Silverpine Forest.",al={"varför vill islen ha flaskan","varför behövs vial of purest water","syftet med vial of purest water"}}},fp="20,168,19.387.0,23.412.1,42.245.0,39.216.0,37.119.0,53.182.0"}
P.entries["item:vial-of-spider-venom"] = {n="Vial of Spider Venom",s="En Vial of Spider Venom innehåller det kraftfulla, nekrotiska gift som utvinns ur spindeldjuren som hemsöker Duskwoods mörka skogar. Madame Eva från Darkshire använder detta farliga extrakt tillsammans med odöda kvarlevor för att skapa skyddande besvärjelser mot hotande faror.",h="En Vial of Spider Venom innehåller det kraftfulla, nekrotiska gift som utvinns ur spindeldjuren som hemsöker...",kw={"darkshire","duskwood","madame eva","naraxis","eremit","spindelgift","totem of infliction","vial of spider venom"},ang={["class:Rogue"]="Även om skurkar är skickliga på att brygga subtila gifter och bestryka klingor med dem, är det här råa, ofiltrerade spindelgiftet avsett för mystiskt skydd snarare än direkt lönnmord.",["faction:Alliance"]="För Alliansens äventyrare som färdas längs Duskwoods skuggiga vägar bidrar hjälpen till Madame Evas skyddstotemer till att skydda resenärer mot skogens fasor."},sec={{t="Duskwoods giftiga hot",b="I Duskwoods skuggiga snår håller monstruösa spindeldjur till – från snabba pygméspindlar med giftväv och gröna eremiter till svarta änkor och den ökända Naraxis. Dessa varelser pumpar ett vidrigt, kraftfullt gift genom sina huggtänder, starkt nog att förlama resenärer och få kött att ruttna. Äventyrare som vågar dräpa dessa fasor kan tappa upp den trögflytande vätskan i hela flaskor."},{t="Att skapa Totem of Infliction",b="I Darkshire ser spåkvinnan Madame Eva illavarslande tecken för resenärer som beger sig ut i den mörka världen. För att skapa en vedergällningsamulett behöver hon fem flaskor av det råa giftet, tillsammans med ghoulhuggtänder och skelettfingrar. Genom hennes hantverk vänds giftets rovgiriga, bitande natur till sin motsats i Totem of Infliction, som låter skada drabba alla som angriper dess bärare."}},faq={{q="Varifrån kommer spindelgiftet?",a="Det utvinns från de olika rovspindlar som lurar runtom i Duskwood, däribland Venom Web Spiders, Carrion Recluses, Green Recluses, Black Widow Hatchlings och den monstruösa yngelmamman Naraxis.",al={"spindelgift källa","vem släpper spindelgift","var få spindelgift duskwood"}},{q="Vem vill ha Vials of Spider Venom?",a="Madame Eva, sierskan i Darkshire, ber om fem flaskor spindelgift samt skelettfingrar och ghoulhuggtänder för att tillverka en magisk amulett.",al={"vem behöver spindelgift","lämna in spindelgift duskwood","madame evas gift"}},{q="Vad används giftet till?",a="Madame Eva blandar giftet med odöda kvarlevor för att förtrolla en Totem of Infliction, en defensiv talisman utformad för att magiskt skada angripare.",al={"vad tillverkar eva","material till totem of infliction","varför samla spindelgift"}},{q="Varför behöver Madame Eva farligt gift till en skyddande amulett?",a="Eva använder ofta sympatisk magi och tar hjälp av skogens rovdjurs och odödas dödliga, vedergällande egenskaper för att skapa en amulett som låter våldet drabba angriparen.",al={"varför gift till amulett","lore om evas totemingredienser"}}},fx={cd5271e6={q="Vad är en Vial of Spider Venom?",a="Det är en liten flaska med kraftigt, frätande gift från de monstruösa spindlar som hemsöker Duskwood. Giftet är dödligt vid beröring, men sådana mörka och starka ämnen uppskattas av lokala mystiker och häxor som väver förbannelser eller förtrollar talismaner som kan vända en angripares egen illvilja mot honom.",al={"vad är spindelgift","lore om vial of spider venom","vad är vial of spider venom"}}},fp="20,143,26.258.0,32.352.0,39.177.0,32.129.0,32.136.0,63.143.0"}
P.entries["item:vicious-night-web-spider-venom"] = {n="Vicious Night Web Spider Venom",s="Vicious Night Web Spider Venom är ett kraftfullt naturligt gift från spindlarna som hemsöker östra Tirisfal Glades. Royal Apothecary Society värdesätter det för dess ovanliga förmåga att bära och bevara historiska sjukdomsstammar, vilket gör det till en avgörande ingrediens i utvecklingen av de Förkastades New Plague.",h="Vicious Night Web Spider Venom är ett kraftfullt naturligt gift från spindlarna som hemsöker östra Tirisfal...",kw={"apothecary johaan","brill","new plague","spindelgift","tirisfal glades","venomweb vale","vicious night web"},ang={["class:Rogue"]="Skurkar som är vana vid att hantera naturliga nervgifter kan uppskatta hur Royal Apothecary Society gör om farliga vilda gifter till konstruerade biologiska vapen.",["race:Undead"]="För de Förkastade är insamlingen av giftet ett direkt bidrag till Lady Sylvanas högsta uppdrag: att utveckla en pest som är mäktig nog att fälla Arthas och hans Scourge."},sec={{t="En bevarad smitta",b="Enligt forskning utförd av Apothecary Johaan i Brill beskriver gamla texter en förödande historisk pest som dödade tusentals oskyldiga offer. Märkligt nog överlevde smittämnet bakom det bortglömda utbrottet i århundraden genom att bäddas in i giftet från de lokala Night Web-spindlarna. Genom att jaga den våldsamma sorten som håller till i Venomweb Vale söder om Scarlet Monastery utvinner apotekarna den bevarade smittsamheten och använder den som en viktig katalysator i sina pågående alkemiska experiment."},{t="Bränsle till New Plague",b="De Förkastade söker ett vapen mot Scourge och de levande. Johaan tillsätter giftet som den sista beståndsdelen i sin experimentella brygd i hopp om att dess bevarade smittämne ska fungera tillsammans med blandningen."}},faq={{q="Vad gör det här giftet unikt jämfört med vanligt spindelgift?",a="Lärda skrifter som Royal Apothecary Society har studerat berättar att en forntida pestpatogen bevarades biologiskt i giftkörtlarna hos Night Web-spindlarnas släktlinje, vilket gjorde deras gift till en naturlig reservoar för smitta.",al={"varför detta gift","night web-giftets bakgrund","spindelgift och pest"}},{q="Var hittar man spindlarna som bär på det här giftet?",a="Vicious Night Web-spindlarna håller främst till i Venomweb Vale, en ravin full av spindelnät i östra Tirisfal Glades söder om Scarlet Monastery.",al={"var man hittar spindelgift","vicious night web spider-plats","spindlar i venomweb vale"}},{q="Vem i Brill vill ha det här giftet?",a="Apothecary Johaan, en alkemist stationerad vid Brills östra utkant, ber om flera prover för att slutföra sin forskning om ett nytt smittämne åt de Förkastade.",al={"vem behöver spindelgift","apothecary johaan och giftet","vem använder giftet"}},{q="Hur passar giftet in i de Förkastades forskning?",a="Johaan ber om giftet som den sista beståndsdelen i sitt experiment. Hans gamla texter beskriver en forntida pest som bevarats genom Night Web Spider Venom, och han vill pröva om dess smittämne fungerar tillsammans med hans nya brygd.",al={"gift i apotekarens forskning","beståndsdel i new plague","de förkastades spindelgift"}}},fx={["901a886f"]={q="Vad är Vicious Night Web Spider Venom?",a="Det är ett kraftfullt och dödligt gift från de våldsamma night web-spindlar som hemsöker östra Tirisfal Glades. Utöver att vara ett vanligt rovdjursgift har det en ovanlig konserverande egenskap: det bevarar styrkan hos en uråldrig, dödlig smitta i spindlarnas huggtänder.",al={"vad är vicious night web spider venom","vicious night web-gift","spindelgift i tirisfal"}},["8bf9d73e"]={q="Varifrån kommer Vicious Night Web Spider Venom, och vem framställer det?",a="Det bildas naturligt hos de våldsamma night web-spindlarna i Tirisfal Glades, särskilt i Venomweb Vale söder om Scarlet Monastery. Enligt uråldriga texter som Royal Apothecary Society har hittat tog spindlarna upp och bevarade en smittsam sjukdom som dödade tusentals för länge sedan. De bär fortfarande på denna forntida pest i sitt gift.",al={"vem framställde vicious night web-gift","varifrån kommer vicious night web-gift","night web-giftets ursprung"}}},fp="30,206,21.341.0,22.198.1,63.192.0,51.114.0,30.120.0,52.213.0"}
P.entries["item:vile-familiar-head"] = {n="Vile Familiar Head",s="Nära Burning Blade Coven är Vile Familiar Heads ett bistert prov för unga horde-warlocks. Under Ruzans ledning samlar de de makabra troféerna som bevis på att de är redo att binda sina första demoniska tjänare. Provet kräver disciplin och respekt för hur dödliga varelserna de tänker kalla på är.",h="Nära Burning Blade Coven är Vile Familiar Heads ett bistert prov för unga horde-warlocks.",kw={"burning blade coven","durotar","imp","ruzan","valley of trials","vile familiar","vile familiar head","krigsmagikeruppdrag"},ang={["class:Warlock"]="För en warlock är insamlingen av dessa huvuden ett tidigt steg mot att bemästra Nether och få rätten att frammana en imp och binda den i tjänst.",["faction:Horde"]="Även på Durotars träningsmarker övar warlocks i utkanten, medvetna om den kvardröjande misstänksamhet med vilken Horden betraktar deras demoniska förehavanden."},sec={{t="En makaber lektion i demonologi",b="I den solstekta ravinen i Valley of Trials ber Ruzan nybörjare som vill lära sig att frammana att ge honom sex Vile Familiar Heads. Vile familiars är eldsprutande imps med farligt elementärt list, och de finns utanför Burning Blade Coven. Nybörjarna måste möta och besegra dem för att visa att de kan kuva demoniska varelser i stället för att själva kuvas av dem. Warlocks tolereras knappt i Thralls Horde, så deras träning kräver försiktighet. En nybörjare som dödas av en frammannad varelse fördjupar bara den vanära och misstänksamhet som riktas mot utövarna av de mörka konsterna."}},faq={{q="Vad används Vile Familiar Heads till?",a="Huvudena bevisar att en nybörjar-warlock är redo i Valley of Trials. Ruzan kräver sex innan han lär en lärling att frammana sin första imp-tjänare.",al={"syftet med vile familiar head","vad används huvudena till","ruzan uppdragsföremål"}},{q="Var kommer de vidriga familjärerna ifrån?",a="Vile familiars samlas vid ingången till en grotta och inne i den, nordost i Valley of Trials. I grottan finns det hemlighetsfulla och illvilliga Burning Blade Coven.",al={"vile familiar plats","var hittar man vile familiars","grottan vid burning blade coven"}},{q="Varför låter Ruzan unga krigsmagiker samla in huvudena?",a="Ruzan förväntar sig att en warlock övermannar en varelse innan den frammana. Imps är bedrägliga och kastar flyktig eld, så när lärlingar besegrar dem i närstrid lär de sig hur farliga demonerna de tänker befalla är.",al={"varför samla huvuden","ruzans motiv","varför döda familjärerna först"}},{q="Hur ser Horde på krigsmagiker som samlar sådana troféer?",a="Den moderna Horden tolererar warlocks utan att omfamna dem. Förräderier med koppling till felmagi har lämnat efter sig en djup misstro, så Ruzan och andra tränare kräver att lärlingarna studerar disciplinerat och diskret.",al={"accepteras krigsmagiker","krigsmagikers rykte hos horde","misstrodda krigsmagiker"}}},fx={["07ac30a7"]={q="Vad är Vile Familiar Head?",a="Det är huvudet från en vile familiar, en av de mindre impdemoner som håller till utanför Burning Blade Coven i Valley of Trials. För en nybörjarhäxmästare under utbildning i Durotar är de makabra troféerna ett bevis på att ha besegrat en imp i direkt strid.",al={"vad är vile familiar head","föremålet vile familiar head","vile familiar-trofé"}}},fp="18,302,31.545.0,38.148.0,34.156.0,55.210.0,59.192.0"}
P.entries["item:vile-fin-scale"] = {n="Vile Fin Scale",s="Vile Fin Scale samlas in från murlocstammar som stryker längs Tirisfal Glades vattendrag och norra kuster. I Brill använder Royal Apothecary Society dessa tåliga biologiska prover i sin forskning för att skapa en förödande ny pest.",h="Vile Fin Scale samlas in från murlocstammar som stryker längs Tirisfal Glades vattendrag och norra kuster.",kw={"en ny pest","apothecary johaan","brill","murloc","royal apothecary society","tirisfal glades","vile fin scale"},ang={["faction:Horde"]="Om man röjer bort aggressiva murlocbosättningar vid kusten blir Tirisfal Glades utkanter tryggare för Hordens budbärare och resande.",["race:Undead"]="Varje Vile Fin Scale som samlas in bidrar direkt till Royal Apothecary Societys heliga uppdrag: att skapa ett vapen som säkrar Forsakens överlevnad mot de levande och Scourge."},sec={{t="Reagens för apotekare",b="Royal Apothecary Society arbetar outtröttligt med att skapa en smittsam farsot som kan utplåna både levande och Scourge. Enkla gifter är lätta nog att brygga, men en smittsam sjukdom som sprids obehindrat bland befolkningen kräver särskilda alkemiska egenskaper. Apothecary Johaan i Brill studerar särskilt Vile Fin Scale för att förstå hur deras naturliga motståndskraft och slemlager kan hjälpa till att stabilisera och sprida hans experimentella smittämnen."},{t="Hotet längs kusten",b="Vile Fin-stammen härjar längs Tirisfal Glades norra stränder och grunda vatten i väster, där den hotar resande och tränger in på Forsaken-territorium. Att samla deras fjäll fyller två syften för Undercity: det håller de vilda murlocbestånden i schack och förser Johaans laboratorium med färska organiska beståndsdelar för tester av biokemisk krigföring."}},faq={{q="Varför vill Apothecary Johaan ha fjällen?",a="Apothecary Johaan utvecklar en ny pest åt Royal Apothecary Society. Han har upptäckt att vanliga gifter inte sprids vidare, så han använder murlocfjällens unika biologiska egenskaper för att hjälpa sitt experimentella hopkok att spridas effektivt.",al={"vad gör johaan med fjäll","varför vile fin scale","johaans pestforskning"}},{q="Var finns Vile Fin-murlocer?",a="Vile Fin-murlocer lever vid kusterna i Tirisfal Glades. De samlas främst längs den norra kustlinjen och i vattnen i väster, vid Brightwater Lake och havet.",al={"var finns vile fin","murlocar i tirisfal","var får man tag på fjäll"}},{q="Varför är projektet The New Plague viktigt för Forsaken?",a="Forsaken söker ett vapen som kan utrota deras bittra rivaler, både den tanklösa Scourge och de levande folken som ser dem som monster. Johaans arbete i Brill är ett tidigt försök på gräsrotsnivå att förverkliga denna ambition för hela riket.",al={"varför den nya pesten","forsakens mål med pesten","vad forskar apothecary johaan om"}},{q="Vilka varelser bär på dessa fjäll?",a="De fås från medlemmar av Vile Fin-stammen i Tirisfal, däribland Vile Fin Minor Oracles, Muckdwellers och Puddlejumpers.",al={"vem släpper vile fin scale","vilka murlocer släpper fjäll"}}},fx={cceccf47={q="Vad är en Vile Fin Scale?",a="En Vile Fin Scale är en tålig vattenlevande fjäll från Vile Fin-murlocstammen, som bor längs stränderna och vattendragen i Tirisfal Glades. Fjällen är naturligt hala och motståndskraftiga mot de nordliga kustvattnen, vilket gör dem till ett ovanligt hållbart biologiskt material.",al={"vad är vile fin-fjäll","lore om vile fin scale","murlocfjäll"}},["3252dae7"]={q="Varifrån kommer Vile Fin-fjäll?",a="Fjällen är biologiska rester som tas direkt från medlemmar av den lokala Vile Fin-murlocstammen, till exempel puddlejumpers, muckdwellers och mindre orakel som stryker längs Tirisfal Glades norra och västra kuster. De växer naturligt och är inte tillverkade.",al={"vem framställde vile fin scale","var får man tag på vile fin-fjäll","vile fin scales ursprung"}}},fp="14,221,19.414.0,20.324.0,45.257.0,36.141.0,60.197.0,44.109.0"}
P.entries["item:voodoo-charm"] = {n="Voodoo Charm",s="Voodoo Charm är en mystisk talisman som används i gravhögarna på Teldrassil för att bryta en ondskefull förtrollning. Oben Rageclaws ande ger den till äventyrare. Den gör det möjligt att slutgiltigt befria hans korrumperade, marionettstyrda kropp, så att hans själ kan finna ro i The Emerald Dream.",h="Voodoo Charm är en mystisk talisman som används i gravhögarna på Teldrassil för att bryta en ondskefull...",kw={"druid of the claw","gnarpine","oben rageclaw","teldrassil","den sovande druiden","voodoo charm"},ang={["class:Druid"]="För unga druider under träning på Teldrassil visar det tragiska i att medlidandedöda en broder Druid of the Claw och befria honom med amuletten, hur sårbart det är att lämna sin kropp bakom sig när man färdas genom The Emerald Dream.",["race:NightElf"]="Amuletten visar hur djupt Gnarlpine-furbolgerna har förfallit och förvandlat heliga gravhålor för kaldorei till platser för grotesk andlig fångenskap."},sec={{t="Att bryta mörka band",b="Djupt inne i Gnarlpine-folkets gravhålor på Teldrassil började furbolgerna använda ondskefull magi för att styra de sovande kropparna hos heliga kaldorei-beskyddare. Druiden Oben Rageclaw fann sin ande skild från sitt kött, och hans fysiska skal blev förtrollat av Gnarlpine-folkets trolldom. När Oben undersöker den förtrollade amuletten inser han att det mörka band som håller hans levande kropp fången inte kan brytas med vanliga böner. I stället blir amuletten ett redskap för slutgiltig befrielse. När hans själlösa kropp har fällts måste amulettens magi riktas mot den fallna kroppen för att helt driva ut furbolgernas inflytande. Då kan hans vandrande ande för alltid fara vidare till The Emerald Dream."}},faq={{q="Vad används Voodoo Charm till?",a="Amuletten används för att bryta Gnarlpine-furbolgernas magiska kontroll över Oben Rageclaw. När Obens själlösa, förtrollade kropp har fällts måste talismanen användas direkt på hans kvarlevor för att bryta den mörka förtrollningen och befria hans själ.",al={"vad gör voodoo charm","användning av voodoo charm","hur använder man voodoo charm"}},{q="Vem ger dig Voodoo Charm?",a="Oben Rageclaws ande ger dig amuletten under uppdraget Druid of the Claw. Efter att ha undersökt talismanen berättar han hur du kan använda den för att befria honom från Gnarlpine-stammens trolldom.",al={"var får jag voodoo charm","vem ger amuletten","oben amulett"}},{q="Varför kallas den Voodoo Charm i nattalvernas länder?",a="Gnarlpine-furbolgerna på Teldrassil har dukat under för korrumpering och bisarr stammagi sedan korrumperingen började sippra in i det stora trädet. Amuletten står för främmande eller förvriden ockult magi som furbolgstammen använder för att snärja och styra kropparna hos druider i vila.",al={"varför voodoo på teldrassil","är det trollvoodoo"}},{q="Vad händer när amuletten används?",a="När amuletten bryter förtrollningen över Obens kropp blir han äntligen fri från Gnarlpine-stammens grepp. Hans fysiska kropp får vila, och hans ande lämnar Teldrassil för att för alltid bo i frid i The Emerald Dream.",al={"vad händer med oben","överlever oben"}}},fx={b324ca48={q="Vad är Voodoo Charm?",a="Voodoo Charm är en magisk talisman knuten till den förvridna magi som håller Teldrassils Gnarlpine-furbolger i sitt grepp. Anden Oben Rageclaw granskar den för att förstå hur furbolgerna fångade hans kropp och inser att bara talismanen kan bryta den vidriga förtrollning som binder hans själlösa kropp för gott.",al={"vad är voodoo charm","voodoo charm i teldrassil","oben och voodoo charm"}},["75919bea"]={q="Varför vill Oben Rageclaw att Voodoo Charm används?",a="Oben Rageclaw behöver talismanen för att bryta Gnarlpine-furbolgernas grepp om honom. När hans själlösa kropp har besegrats i strid skingrar du den mörka förtrollningen genom att använda talismanen över hans fallna kvarlevor. Då befrias hans fångade ande och kan äntligen vila i frid i The Emerald Dream.",al={"varför använda voodoo charm","varför vill oben ha talismanen","syftet med voodoo charm"}}},fp="12,111,24.525.1,40.219.0,31.170.0,51.265.0,37.205.1"}
P.entries["item:wailing-essence"] = {n="Wailing Essence",s="Wailing Essence är en märklig, koncentrerad substans som finns i ektoplasman som strövar omkring djupt inne i Wailing Caverns. Den misstänks driva de bisarra mutationer som sprider sig bland The Barrens växter och djur, och har väckt opportunistiska alkemisters intresse. De vill gärna buteljera dess kraftfulla egenskaper.",h="Wailing Essence är en märklig, koncentrerad substans som finns i ektoplasman som strövar omkring djupt inne i...",kw={"ektoplasma","mebok mizzyrix","ratchet","smartdrycker","wailing caverns","wailing essence"},ang={["class:Druid"]="Essensens existens pekar direkt på det fördärvande inflytandet djupt inne i Wailing Caverns och understryker hur brådskande det är att rena bort Drömmens besmittelse."},sec={{t="En flyktig blandning",b="De underjordiska grottorna under centrala The Barrens har fyllts av onaturlig energi som förvrider bestar och ger upphov till geléartad ektoplasma. Dessa slemmiga varelser koncentrerar en trögflytande substans som kallas Wailing Essence. Lokala druider betraktar vattnet med växande oro, men goblinentreprenörer ser bara en möjlighet att tjäna pengar. I hamnstaden Ratchet tror en excentrisk alkemist vid namn Mebok Mizzyrix att essensen är den saknade aktiva ingrediensen i en serie lukrativa ”smartdrycker” som ska förbättra kundernas intellekt. Han bekymrar sig inte alls för den mardrömslika fördärvade kraft den faktiskt kan innehålla."}},faq={{q="Var kommer Wailing Essence ifrån?",a="Den samlas in från de ektoplasmaslemmar som finns i Wailing Caverns, däribland devouring ectoplasms, evolving ectoplasms och nightmare ectoplasms.",al={"wailing essence byte","var hittar man wailing essence","vad släpper wailing essence"}},{q="Vem vill ha den här essensen?",a="Mebok Mizzyrix, en goblinexperimenterare i Ratchet, vill ha essensen för att brygga en ny variant av sina ”smartdrycker” som ska stärka intellektet.",al={"vem behöver wailing essence","vem köper wailing essence","lämna in wailing essence"}},{q="Vad misstänks essensen göra med The Barrens?",a="Mebok misstänker att essensen ligger bakom det snabbt muterande djurlivet och den onaturliga växtlighet som sprider sig över The Barrens.",al={"vad gör wailing essence","är wailing essence farlig","wailing essence bakgrundshistoria"}},{q="Är det verkligen säkert att dricka Wailing Essence?",a="Med tanke på att den utvinns ur fördärvade, mardrömssmittade ektoplasmaslemmar djupt inne i en förbannad grotta är det i bästa fall vårdslöst att dricka den i en kommersiell dryck, men typiskt för gobliners entreprenörsanda.",al={"kan man dricka wailing essence","är smartdryck säker"}}},fx={["387b8d38"]={q="Vad är Wailing Essence?",a="Wailing Essence är ett märkligt, kraftfullt ämne som finns djupt inne i Wailing Caverns. Det samlas i grottans kringströvande ektoplasmer och slemvarelser. Lokala iakttagare misstänker att ämnet är den onaturliga katalysatorn bakom de märkliga mutationer som förändrar växter och djurliv i trakterna kring The Barrens.",al={"vad är wailing essence","information om wailing essence","om wailing essence"}}},fp="15,312,21.630.0,37.149.0,23.139.0,54.156.0,42.206.0"}
P.entries["item:warsong-axe-shipment"] = {n="Warsong Axe Shipment",s="Warsong Axe Shipment är en tung låda med nyss smidda yxor som väntar på kajen i Booty Bay i Stranglethorn Vale. Warsong Outriders har beställt den för att hålla igång sina avverkningsarbeten i Ashenvale, och den är en avgörande länk i Hordens försörjningskedja över havet.",h="Warsong Axe Shipment är en tung låda med nyss smidda yxor som väntar på kajen i Booty Bay i Stranglethorn...",kw={"ashenvale","yxor","booty bay","locke okarr","splintertree post","warsong axe shipment","warsongs förnödenheter","wharfmaster lozgil"},ang={["faction:Horde"]="Att hämta den här lådan är avgörande för att hålla Warsong Lumber Camp beväpnat och produktivt trots ständiga påtryckningar från fientliga styrkor i Ashenvale.",["race:Orc"]="För Warsong-klanen betyder vassa yxor mer timmer till Orgrimmars och Durotars växande grundvalar."},sec={{t="En lång färd över haven",b="För att hålla avverkningen vid Warsong Lumber Camp igång krävs ett jämnt flöde av hållbara verktyg som inte alltid kan smidas vid fronten. För att förse skogshuggarna skickas beställningar över det stora havet till den neutrala goblinhamnen Booty Bay. Lådan står nära Wharfmaster Lozgil och innehåller vässade yxor som ska skickas tillbaka till Splintertree Post. Den visar vilka logistiska hinder Horden möter när den ska hålla sina avlägsna gränsläger beväpnade och i drift."}},faq={{q="Var finns Warsong Axe Shipment?",a="Lådan står direkt på kajen i goblinhamnen Booty Bay, vid den södra spetsen av Stranglethorn Vale.",al={"yxleveransens plats","var finns yxleveransen","yxlåda i booty bay"}},{q="Varför är en leverans till Ashenvale ända nere i Booty Bay?",a="Blackwater Raiders och Steamwheedle Cartel sköter handelssjöfarten över det stora havet. Booty Bay är ett viktigt handelsnav som knyter samman avlägsna länder och fungerar därför som omlastningsplats för större leveranser av utrustning och verktyg som Horden beställt.",al={"varför booty bay","varför är den i stranglethorn","warsong-yxor i booty bay"}},{q="Vem behöver yxorna?",a="Locke Okarr, en ryttare stationerad vid Splintertree Post i Ashenvale, behöver dem för att fylla på de krympande lagren vid Warsong Lumber Camp.",al={"vem behöver yxorna","vem är leveransen till","locke okarrs yxor"}},{q="Vem har hand om leveransen i Booty Bay?",a="Wharfmaster Lozgil övervakar sjöfrakten längs Booty Bays livliga kajer, där leveransen väntar på transport till Kalimdor.",al={"vem har leveransen","wharfmaster lozgil","hamnmästare i booty bay"}}},fx={["445f7bbf"]={q="Vad är Warsong Axe Shipment?",a="Det är en låda med tunga skogsavverkningsyxor på väg till Warsong-klanens timmerverksamhet i Ashenvale. Orciska skogsarbetare sliter ständigt ut sina verktyg när de avverkar Kalimdors uråldriga skogar. Regelbundna leveranser av nyss smidda timmeryxor är därför avgörande för att hålla sågverken och arbetslagen fullt utrustade.",al={"vad är warsong axe shipment","warsong axe shipments innebörd","yxlåda i ashenvale"}}},fp="20,166,29.447.0,42.84.0,62.173.0,21.133.0,39.108.0"}
P.entries["item:warsong-oil"] = {n="Warsong Oil",s="Warsong Oil är ett viktigt industrismörjmedel för maskinerna vid Warsong Lumber Camp i Ashenvale. Lokala satyrer överföll en livsviktig leverans på vägen och förde oljan till sina fördärvade skogshelgedomar för avskyvärda riter.",h="Warsong Oil är ett viktigt industrismörjmedel för maskinerna vid Warsong Lumber Camp i Ashenvale.",kw={"ashenvale","locke okarr","night run","satyrnaar","splintertree post","warsong oil","warsong-förråd","xavian"},ang={["faction:Horde"]="Hordens alla fästen i Durotar och The Barrens är beroende av virke från Ashenvale. När demonvördande satyrer stjäl maskinoljan hotas bygget av deras unga städer.",["profession:Engineering"]="Ingenjörer vet mycket väl att de ömtåliga lederna i goblinkonstruerade shreddersmaskiner och motorsågar slits ut på några timmar vid timmeravverkning utan en jämn tillförsel av smörjolja."},sec={{t="Stulet bränsle till maskinerna",b="Warsong-klanens avverkning i Ashenvale är starkt beroende av tunga maskiner, shredders konstruerade av gobliner och väldiga sågverk. För att hålla den industriella utrustningen igång krävs en jämn tillförsel av specialolja. Utan den riskerar klanens timmerskörd att plötsligt stanna av, vilket hejdar flödet av virke som så väl behövs för att bygga Orgrimmar och befästa hordens bosättningar i Durotar och The Barrens."},{t="Satyrernas riter",b="I stället för att nå Splintertree Post och avverkningslägren överföll satyrerna som hemsöker skogen nyligen en leverans Warsong Oil. De demoniska tjänarna kastade inte bort den raffinerade vätskan, utan bar behållarna till sina fördärvade enklaver, däribland Night Run, Satyrnaar och Xavian, för att använda det lättantändliga smörjmedlet i sina mörka, avskyvärda riter."}},faq={{q="Vad används Warsong Oil till?",a="Den är ett industrismörjmedel som ska hålla de tunga shreddersmaskinerna, sågarna och timmermaskinerna vid Warsong Lumber Camp igång.",al={"syftet med warsong oil","varför behövs oljan","vad används den till"}},{q="Varför har satyrerna oljan?",a="En försörjningskonvoj på väg till Splintertree Post överfölls längs vägarna i Ashenvale. Satyrerna tog oljan och använde den till avskyvärda mörka riter i sina ruinerade bosättningar.",al={"vem stal oljan","varför har satyrerna oljan","vart tog oljan vägen"}},{q="Var hittar man Warsong Oil?",a="Behållare med oljan finns utspridda på platser i Ashenvale som kontrolleras av satyrer, framför allt i Night Run, Satyrnaar och Xavian.",al={"warsong oil plats","var hittar man warsong oil","oljans platser"}},{q="Vem behöver få tillbaka oljan?",a="Locke Okarr vid Splintertree Post behöver oljan, tillsammans med sågblad, rep och yxor, för att fylla på förråden till den hårt pressade Warsong-avverkningen.",al={"vem vill ha oljan","uppdragsgivare för warsong oil"}}},fx={["7f00f21d"]={q="Vad är Warsong Oil?",a="Warsong Oil är ett viktigt industriellt smörjmedel och bränsle som tillhandahålls till Hordens skogsavverkningsmaskiner i Ashenvale. Det håller tunga maskiner och sågblad igång vid Warsong-lägret och är oumbärligt för att klanens timmerverksamhet ska klara slitaget från den hårda vildmarken.",al={"vad är warsong oil","vad är oljan","information om warsong oil"}}},fp="11,146,21.310.0,20.258.0,29.104.0,31.145.0,31.112.0,28.131.0"}
P.entries["item:warsong-outrider-update"] = {n="Warsong Outrider Update",s="Längs Ashenvales östra gräns förbereder en Warsong Outrider en rapport åt Horden. Där registrerar ryttaren underrättelser från fronten som kurirer ska föra vidare åt Horden. Det hjälper till att säkra övergången mot Azshara och stärka orkernas fotfäste mot Night Elfs motstånd.",h="Längs Ashenvales östra gräns förbereder en Warsong Outrider en rapport åt Horden.",kw={"ashenvale","azshara","the barrens","kadrak","splintertree post","warsong outrider","warsong outrider update"},ang={["faction:Horde"]="Som medlem av Horden är du beroende av rapporter från fronten för att skydda försörjningsvägarna mellan The Barrens och Ashenvale. Längs vägarna fraktas timmer som behövs för att bygga ut Orgrimmar.",["race:Orc"]="Som ork förlitar du dig på vaksamma spejare och snabba kurirer för att försvara Warsong-äran och territoriet mot Night Elf-väktarna, som bestrider din klans anspråk på skogsbruk."},sec={{t="Underrättelser från gränsen",b="Bortom Splintertree Post går den östra vägen genom Ashenvales oroliga gränsland mot Azsharas uråldriga ruiner. Beridna orciska förtrupper patrullerar gränsen och noterar taktiska observationer, patrullernas rörelser och resursbedömningar. De skickar sina fältrapporter till Kadrak i det norra vakttornet, som bevakar gränsen mot The Barrens. Rapporterna ger Hordens befälhavare en tydlig bild av fiendens truppsamlingar och territoriella hot under skogens tak."}},faq={{q="Vad är syftet med den här rapporten?",a="Rapporten redogör för Night Elfs aktiviteter och förhållandena längs den östra vägen i Ashenvale mot Azshara. Kadrak använder underrättelserna för att samordna Hordens truppförflyttningar och stärka försvaret längs The Barrens norra gräns.",al={"syftet med warsong outrider update","varför outrider update","vad är den här rapporten"}},{q="Vem bär och överlämnar rapporten?",a="En Warsong Outrider som patrullerar landsvägen mellan Splintertree Post och gränsen mot Azshara bär rapporten. Ryttaren överlämnar den till Kadrak och får nya strategiska order.",al={"vem skriver outrider update","varifrån kommer outrider update"}},{q="Vart ska rapporten lämnas?",a="För rapporten direkt till Kadrak i det norra vakttornet, som bevakar gränsen mot The Barrens och Ashenvales södra infart.",al={"vart ska jag ta outrider update","vem vill ha outrider update"}},{q="Varför är Warsong så engagerade i Ashenvale?",a="Warsong-klanen kartlägger Ashenvales uråldriga skogar för att hitta timmer och byggmaterial som behövs i Orgrimmar. Deras resursinsamling leder till konflikt med de försvarande Night Elfs och Silverwing Sentinels.",al={"varför är orcher i ashenvale","warsongs intresse för ashenvale"}}},fx={["0cc42a69"]={q="Vad är Warsong Outrider Update?",a="Det är en fältrapport sammanställd av en Warsong Outrider som patrullerar vägarna i östra Ashenvale mot gränsen till Azshara. Den dokumenterar lokal spaning, truppförflyttningar och observationer som är avgörande för att bevara Hordens fotfäste i den omstridda skogen.",al={"vad är warsong outrider update","föremålet warsong outrider update","vad är spejarrapporten"}},["2fb6b9e4"]={q="Varifrån kommer Warsong Outrider Update, och vem skrev den?",a="Den skrivs och överlämnas av en Warsong Outrider som är stationerad längs skogsvägen mellan Splintertree Post och gränsen till Azshara. Spejaren skriver dessa fältrapporter som svar på nya order från norra The Barrens.",al={"vem skrev warsong outrider update","varifrån kommer warsong outrider update","vem överlämnade spejarrapporten"}},aa3bba6b={q="Varför vill Kadrak ha Warsong Outrider Update?",a="Kadrak samordnar Hordens närvaro vid gränsen från vakttornet i norr vid gränsen till The Barrens. Han behöver spejarens observationer från frontlinjen tillsammans med rapporter från andra spanare för att bedöma fiendens styrka och strategiskt planera Warsong-klanens nästa steg längre in i Ashenvale.",al={"varför behöver kadrak outrider update","varför behövs warsong outrider update","varför samla in outrider update"}}},fp="23,299,21.471.0,35.230.0,39.187.0,34.139.0,45.209.0"}
P.entries["item:warsong-runner-update"] = {n="Warsong Runner Update",s="Vid Zoram'gar Outpost för Warsong Runner Update rapporter från västra Ashenvale till Kadrak.",h="Vid Zoram'gar Outpost för Warsong Runner Update rapporter från västra Ashenvale till Kadrak.",kw={"ashenvale","kadrak","the barrens","warsong-rapporterna","warsong-klanen","warsong runner update","the zoram strand","zoram'gar outpost"},ang={["faction:Horde"]="Rapporten visar hur svårt det är att upprätthålla avlägsna utposter i fientligt Night Elf-territorium. Kurirer håller kommunikationen öppen mellan Ashenvale och The Barrens.",["race:Orc"]="Som orc vet du att Warsong-spejare och kurirer riskerar livet i täta skogar för att föra taktiska rapporter till Kadrak och främja klanens territoriella anspråk."},sec={{t="Ögon på västfronten",b="Warsong Runner vid Zoram'gar Outpost bevakar kusten och närliggande hot i västra Ashenvale. Rapporten återger observationer som spejare vid utposten har samlat in och rapporterar om lokal aktivitet. Den färdas till Kadraks vakttorn vid gränsen mot The Barrens och hjälper hordens ledare att stärka sin ställning och planera sina rörelser in i alvernas förfäders skogar."}},faq={{q="Vad är Warsong Runner Update?",a="Warsong Runner Update är en skriftlig militär rapport från Warsong Runner vid Zoram'gar Outpost i västra Ashenvale. Den förmedlar observationer från fronten till hordens ledare vid gränsen mot The Barrens.",al={"runner-rapport","vad är warsong runner update","warsong report zoram"}},{q="Var kommer rapporten ifrån?",a="Rapporten kommer från Warsong Runner vid Zoram'gar Outpost, på Ashenvales avlägsna västkust nära The Zoram Strand.",al={"runnerns plats","var finns warsong runner","vem ger runner update"}},{q="Vem tar emot rapporten?",a="Kadrak, Warsong-befälhavaren i vakttornet längs den norra gränsen mot The Barrens, tar emot rapporten.",al={"vem ska jag lämna detta till","kadraks rapport","leverera runner update"}},{q="Varför behöver Kadrak rapporten?",a="Kadrak samordnar Warsong-klanens militära rörelser in i Ashenvale. Rapporter från utposter som Zoram'gar berättar för honom om fiendens motstånd, sjövägar och kontrollen över det lokala området.",al={"varför runner update","warsong-rapportens syfte"}}},fp="21,93,25.360.0,34.193.0,35.120.0,25.103.0,35.198.0"}
P.entries["item:warsong-saw-blades"] = {n="Warsong Saw Blades",s="Warsong Saw Blades är specialiserade industriella skärverktyg som beställts för att försörja Hordens kalavverkning i Ashenvale. De levereras genom goblinernas logistiska nätverk och är avgörande för att hålla Warsong Lumber Camps timmermaskiner igång.",h="Warsong Saw Blades är specialiserade industriella skärverktyg som beställts för att försörja Hordens...",kw={"avverkning i ashenvale","locke okarr","pixel","splintertree post","warsong lumber camp","warsong saw blades"},ang={["faction:Horde"]="Hordens hela expansion in i centrala Kalimdor är beroende av timmer från Ashenvale, vilket gör bevarandet och underhållet av Warsong-klanens sågverksutrustning till en kritisk strategisk prioritet.",["race:NightElf"]="Varje låda med goblinsmidda sågblad står för den fortsatta skändningen av Ashenvales urgamla trädkronor och slakten av heliga skogsandar."},sec={{t="Industriellt skogsbruk",b="Warsong-klanens avverkning i Ashenvale är starkt beroende av tung maskinutrustning som goblinerna tillhandahåller och underhåller med sin ingenjörskonst. Vanliga yxor räcker inte för att täcka Hordens enorma behov av timmer från Kalimdor, så ångmaskiner och cirkelsågar krävs för att ständigt tugga sig igenom råvirke. Ashenvales urgamla lövträd sliter snabbt ut och knäcker vanliga sågblad, så regelbundna leveranser av ersättningsblad är avgörande för att hålla sågverken igång vid Warsong Lumber Camp."},{t="Säkra leveransen",b="Att skaffa mekaniska delar djupt inne i omstritt territorium är en ständig logistisk huvudvärk. Medan andra avverkningsförnödenheter ofta beslagtas av fientliga furbolger eller satyrer, sköts leveranserna av sågblad via goblinkontakter som Pixel vid Splintertree Post. Genom att samla in dessa blad tillsammans med rep, olja och yxor kan timmermästaren Locke Okarr hålla lägret igång trots ständiga sabotageförsök från de inhemska försvararna."}},faq={{q="Vad används Warsong Saw Blades till?",a="De är reservdelar till cirkelsågar, avsedda för de tunga mekaniska timmerkvarnarna och sågverken vid Warsong Lumber Camp i sydöstra Ashenvale.",al={"sågbladens syfte","användning av sågblad","vad används de till"}},{q="Vem förser Horden med sågbladen?",a="Bladen hanteras av goblinköpmän och logistiker. Pixel, en goblin som är stationerad vid Splintertree Post, övervakar ankomsten av denna mekaniska leverans till Warsong Outriders.",al={"vem tillverkade sågbladen","var kommer sågbladen ifrån","leverantör av sågblad"}},{q="Varför behöver Horden så många sågblad?",a="Ashenvales täta, urgamla träd sliter snabbt på skäreggarna, och Horden behöver enorma mängder timmer för att bygga bosättningar över Durotars och The Barrens torra slätter. Den ständiga avverkningen sliter ut maskiner snabbare än de lokala smederna hinner smida om dem.",al={"varför så många sågblad","warsong-klanens avverkningsbehov","varför behövs sågar"}},{q="Vem samlar in avverkningsförnödenheterna?",a="Locke Okarr, en orch som övervakar leveranser från Splintertree Post, organiserar insamlingen av sågbladen tillsammans med olja, rep och yxor för att leverera dem till timmerlägret.",al={"vem vill ha sågbladen","vem hämtar sågbladen","locke okarr uppdrag"}}},fx={["12f75673"]={q="Vad är Warsong Saw Blades?",a="Dessa kraftiga metallblad är viktiga maskinkomponenter som tillverkats för Warsong Outriders industriella timmermaskiner. Orcerna förlitar sig i hög grad på mekaniserad skogsavverkning för att fälla Ashenvales uråldriga, täta timmer, men de tjocka träden sliter snabbt på skärtänderna. Utan en stadig tillgång på vassa, hållbara sågblad stannar Warsongs timmerverksamhet.",al={"vad är warsong saw blades","föremålet warsong saw blades","vad är sågbladen"}}},fp="18,187,19.405.0,21.375.0,41.126.0,43.140.0,43.262.0,39.162.0"}
P.entries["item:warsong-scout-update"] = {n="Warsong Scout Update",s="Vid Splintertree Post rapporterar en Warsong Scout vad Horden behöver veta om Ashenvale.",h="Vid Splintertree Post rapporterar en Warsong Scout vad Horden behöver veta om Ashenvale.",kw={"ashenvale","the barrens","kadrak","rapport","spanare","splintertree","uppdatering","warsong"},ang={["faction:Horde"]="Warsong-bud håller Hordens främsta läger i Ashenvale i kontakt med försörjningsbaserna i The Barrens medan Horden tränger längre in i skogen.",["race:Orc"]="Som orc vet du att Warsong-klanen får ta den tyngsta bördan av avverkningskampanjen i Ashenvale. Snabba scouter hjälper till att hålla klanens utposter i skogen."},sec={{t="Ögon i den uråldriga skogen",b="Warsong Scouts bevakar skogarna medan Horden söker timmer och försörjningsvägar genom Ashenvale. Från Splintertree Post, ett befäst läger, håller de uppsikt över Night Elf-vakter och rörelser i området. Deras iakttagelser når Kadrak vid gränsen mellan The Barrens och Ashenvale, bland de vanliga orderna. Han använder dem för att bedöma truppernas beredskap och samordna förnödenheter och resor genom de omstridda skogarna."}},faq={{q="Vad är Warsong Scout Update?",a="Warsong Scout Update samlar en Warsong Scouts iakttagelser från Splintertree Post i östra Ashenvale åt befälhavarna vid gränsen.",al={"spaningsuppdatering","spaningsrapport","warsong-spanarens rapport"}},{q="Vem behöver den här uppdateringen?",a="Kadrak behöver rapporten. Hordens officer bevakar gränsen mellan norra The Barrens och Ashenvale från ett vakttorn och använder rapporten för att planera militära manövrer.",al={"vem vill ha detta","rapport till kadrak","vem får uppdateringen"}},{q="Var befinner sig Warsong Scout?",a="Scouten är stationerad i Splintertree Post, Hordens fäste längs huvudvägen genom östra Ashenvale.",al={"var är spanaren","spanarens plats","hitta warsong scout"}},{q="Varför är de här rapporterna så viktiga för Horden?",a="Night Elves försvarar Ashenvale med stor kraft. Scouternas rapporter varnar Hordens ledare för bakhåll och trupprörelser och hjälper till att hålla försörjningsvägar och avverkningsläger säkra.",al={"varför bry sig","warsong-logistik","underrättelser från ashenvale"}}},fx={ed4a3567={q="Varifrån kommer Warsong Scout Update, och vem skrev den?",a="Den här skriftliga rapporten sammanställs av en Warsong Scout som är stationerad i Ashenvale och har sin bas i Splintertree Post i norr. Spejaren har fått i uppdrag att bevaka fiendens rörelser och kartlägga den omstridda skogen, och antecknar viktig information från fältet som lämnas över i utbyte mot nya order från gränsen till The Barrens.",al={"vem skrev warsong scout update","warsong scout update källa","vem skrev scout update"}}},fp="20,91,26.396.0,33.139.0,25.163.0,35.116.0,51.157.0"}
P.entries["item:water-of-the-seers"] = {n="Water of the Seers",s="Water of the Seers är en helig dryck som ges till unga taurer som genomgår sina stammars prövningar i Bloodhoof Village. När de dricker det heliga vattnet nära stammens eld öppnas sinnet för andevärlden, och en eterisk Plains Vision kallas fram för att vägleda pilgrimen på den andliga resan.",h="Water of the Seers är en helig dryck som ges till unga taurer som genomgår sina stammars prövningar i...",kw={"bloodhoof village","plains vision","rite of vision","seer wiserunner","stameld","water of the seers"},ang={["class:Shaman"]="Upplevelsen av dryckens effekter ger en tidig inblick i hur man kommunicerar med andevärlden och visar hur rituella ämnen kan tunna ut slöjan mellan den fysiska världen och förfädernas värld.",["race:Tauren"]="Water of the Seers är en grundläggande helig brygd i utbildningen av unga shu'halo. Den förenar uråldriga shamanistiska seder med stammens övergång till vuxenlivet."},sec={{t="Ett kärl för anden",b="Water of the Seers bereds av stammens mystiker och är en nödvändig del av den uråldriga Rite of Vision. För att tränga igenom slöjan mellan den fysiska verkligheten och förfädernas vägledning måste den som söker dricka det heliga vattnet framför stammens centrala eld i Bloodhoof Village. När drycken har svalts ger den kraftfulla brygden andlig synförmåga. En spöklik vägvisare som kallas Plains Vision tar då gestalt ur glöden och leder vägen mot Seer Wiserunner."}},faq={{q="Vad händer efter att man druckit Water of the Seers?",a="När du dricker det heliga vattnet vid byns stambål öppnas dina andliga sinnen. Inom kort stiger en förfädersande i form av en spöklik varg, Plains Vision, fram ur lågorna och vägleder dina steg genom Mulgore.",al={"vad gör water of the seers","dricka water of the seers","plains vision vatten"}},{q="Var ska man dricka vattnet?",a="Drycken måste intas precis framför den stora stameelden i Bloodhoof Village, strax norr om de lokala shamanäldsterna.",al={"var dricker man water of the seers","water of the seers plats","stameeldens plats"}},{q="Vem leder visionen dig till?",a="Den spektrala Plains Vision leder pilgrimen nordväst, in i kullarna i Mulgore, till grottan där Seer Wiserunner väntar på att tyda din resa.",al={"vart går vargen","plains visions mål","vem är siaren"}}},fx={["6b2d8d4a"]={q="Vad är Water of the Seers?",a="Water of the Seers är en helig dryck som taurenmystiker bereder åt noviser som ska genomgå de traditionella övergångsriterna. När du dricker det välsignade vattnet öppnas dina andliga sinnen, så att du kan uppfatta omen och vägleda andar som vanliga ögon inte kan se.",al={"vad är water of the seers","water of the seers bakgrund","vad är water of the seers för slags föremål"}},["6ddc8851"]={q="Varifrån kommer Water of the Seers, och vem beredde det?",a="Vattnet bereds rituellt och skänks av Zarlman Two-Moons i Bloodhoof Village. Han brygger det av brunnsstenar och Ambercorn som samlats in över hela Mulgore och fyller det med andlig kraft åt unga tauren som genomgår Earthmothers riter.",al={"vem beredde water of the seers","water of the seers ursprung","varifrån kommer water of the seers"}},bc18f3dc={q="Varför vill någon ha Water of the Seers?",a="Du behöver Water of the Seers för att fullborda synens rit, en viktig andlig prövning för tauren. Om du dricker drycken vid stammens eld frammanas Plains Vision, en andlig vägvisare som ska leda dig genom Mulgore mot din utstakade väg och dina äldsterådgivare.",al={"varför dricka water of the seers","syftet med water of the seers","varför behöver jag water of the seers"}}},fp="18,188,23.278.0,51.154.0,35.114.0,33.134.0"}
P.entries["item:water-pitcher"] = {n="Water Pitcher",s="Ett enkelt kärl för att bära färskt källvatten från den lokala brunnen på Red Cloud Mesa. Greatmother Hawkwind ber unga tauren bära det tillbaka till Camp Narache för att lära dem ödmjukhet, tjänstvillighet och respekt för stammens äldste.",h="Ett enkelt kärl för att bära färskt källvatten från den lokala brunnen på Red Cloud Mesa.",kw={"en ödmjuk syssla","camp narache","chief hawkwind","greatmother hawkwind","brunnen i mulgore","red cloud mesa","water pitcher"},ang={["race:Tauren"]="För unga tauren som blir vuxna på Red Cloud Mesa är det en tidig läxa att bära kannan: att hedra de äldre och hjälpa samhället är styrkans sanna grund."},sec={{t="En lektion i ödmjukhet",b="Trots sin enkla utformning är vattenkannan ett viktigt läromedel för ungdomarna i Camp Narache. Den står bredvid brunnen på slätterna sydost om lägret och symboliserar det dagliga arbete som krävs för att försörja samhället. När en nybörjare får fylla kärlet och bära det tunga kärlet till Chief Hawkwind sätter Greatmother Hawkwind deras karaktär på prov. Sysslan visar att ingen uppgift är för ringa för en stammens beskyddare och påminner unga krigare om att ta hand om de vardagliga behoven hos sina fränder är lika viktigt som att svinga ett vapen under jakten."}},faq={{q="Vad används vattenkannan till?",a="Den används för att bära färskt brunnsvatten tillbaka till Camp Narache. Att bära den över slätterna är en traditionell syssla som prövar om en ung äventyrare är villig att utföra vardagligt arbete för stammens bästa.",al={"kannans syfte","varför bära vattenkannan","ödmjuk syssla med kannan"}},{q="Var hittar du vattenkannan?",a="Kannan står precis bredvid brunnen sydost om Camp Narache på Red Cloud Mesa, nära platsen där Greatmother Hawkwind sköter sina sysslor.",al={"kannans plats","var finns vattenkannan","hitta kannan i mulgore"}},{q="Vem ber dig hämta vattenkannan?",a="Greatmother Hawkwind ber unga resenärer att hämta den. Hennes åldrande ben gör vandringen svår, så hon ger uppgiften till ivriga ungdomar för att pröva deras livskraft och ödmjukhet.",al={"vem ger kannauppdraget","greatmother och kannan"}},{q="Vem får vattenkannan när den har fyllts?",a="Den bärs direkt till Chief Hawkwind i Camp Narache, som ser handlingen som ett bevis på att bäraren har det hjärta och den hängivenhet som krävs för att tjäna stammen.",al={"vem får kannan","lämna vattenkannan","ta kannan till"}}},fx={d76860be={q="Vad är Water Pitcher?",a="Water Pitcher är ett enkelt lerkärl som förvaras vid sötvattenbrunnen på slätterna sydost om Camp Narache. Fyllt med färskt brunnsvatten ger det välbehövlig svalka åt de unga jägarna, krigarna och de äldre som bor i lägret på Red Cloud Mesa.",al={"vad är water pitcher","information om water pitcher","water pitcher i mulgore"}},a1f72ee9={q="Varför behöver Chief Hawkwind Water Pitcher?",a="Att hämta färskt vatten från slättens brunn är ett nödvändigt dagsarbete för att Camp Narache ska överleva. Hans mor, Greatmother Hawkwind, ber unga äventyrare att bära upp kruset till hövdingen för att hjälpa stammen och visa att de är villiga att utföra även de enklaste sysslorna för sitt folk.",al={"varför vill man ha water pitcher","varför ta med water pitcher","chief hawkwind och water pitcher"}}},fp="13,217,20.334.0,35.178.0,36.135.0,40.169.0,49.154.0"}
P.entries["item:webwood-egg"] = {n="Webwood Egg",s="Ett Webwood Egg är ett okläckt exemplar som hämtats från ruvande bon i Shadowthread Cave i Shadowglen. Naturforskare som studerar fördärvet på Teldrassil söker efter livsdugliga ägg för att undersöka nykläckta spindeldjur under säkra laboratorieförhållanden.",h="Ett Webwood Egg är ett okläckt exemplar som hämtats från ruvande bon i Shadowthread Cave i Shadowglen.",kw={"aldrassil","gilshalan","shadowglen","shadowthread cave","spindelägg","teldrassil","webwood egg"},ang={["class:Druid"]="Kunskap om hur Webwood-spindlarna fortplantar sig och beter sig medan de är besmittade ger druider viktiga ledtrådar till hur Teldrassils rubbade naturliga balans kan återställas.",["race:NightElf"]="För unga kaldorei som försvarar Teldrassils heliga grenar hjälper insamlingen av dessa ägg lärda att undersöka den onaturliga smitta som sprider sig bland världsträdets inhemska djurliv."},sec={{t="Ett instängt exemplar",b="Att tämja eller kuva en fullvuxen, giftig Webwood-spindel är farligt och långt bortom vad en ensam forskare klarar av. I stället för att brottas med vuxna rovdjur förlitar sig lärda som Gilshalan Windwalker på okläckta ägg som samlats in direkt från kullar gömda i Shadowthread Caves mörkaste vrår. Med ett okläckt ägg kan naturforskarna transportera varelsen säkert och hålla de framkläckta spindelungarna instängda, så att de får levande studieobjekt utan att utsättas för fullvuxna bestars dödliga huggtänder."},{t="Ämnade för Darnassus",b="Den onaturliga aggressiviteten och det fördärv som plågar Teldrassils inhemska djurliv har oroat lärda i hela trädkronan. När äggen väl säkrats i Aldrassil ska de och insamlat gift transporteras ner längs grenarna till huvudstaden Darnassus. Forskarna hoppas att uppfödning och undersökning av spindlarna i kontrollerade miljöer ska ge värdefulla insikter om den mörka åkomma som sprider sig genom världsträdets grenar."}},faq={{q="Var hittar man Webwood Eggs?",a="Webwood Eggs finns i kullar djupt inne i Shadowthread Caves fuktiga gångar, i nordvästra Shadowglen.",al={"webwood egg plats","var finns webwood egg","hitta webwood egg"}},{q="Vem vill ha Webwood Egg?",a="Forskaren Gilshalan Windwalker i Aldrassil ber om ägget för att fortsätta sina vetenskapliga studier av de aggressiva spindeldjur som plågar Shadowglen.",al={"vem behöver webwood egg","lämna in ägg","gilshalans ägg"}},{q="Varför samla in ett ägg i stället för att fånga en spindel?",a="En fullvuxen Webwood-spindel är alldeles för farlig och stor för att lätt kunna fångas och hållas instängd. Ett okläckt ägg ger ett levande exemplar som kan transporteras säkert och placeras i en säker inhägnad innan det kläcks.",al={"varför ett ägg","varför inte fånga en levande spindel"}},{q="Vad händer med ägget när det har samlats in?",a="Gilshalan ser till att ägget och det utvunna spindelgiftet levereras till Darnassus, där lärda kan forska ingående om varelserna på avstånd från vildmarkens omedelbara faror.",al={"vart ska ägget","äggets destination"}}},fx={["0a629fbc"]={q="Vad är ett Webwood Egg?",a="Ett Webwood Egg är ett okläckt spindelägg som lagts av de jättelika Webwood-spindlarna som häckar i Shadowglen. Det innehåller levande spindelungar innan de kläcks, så att forskare kan studera de aggressiva spindeldjuren utan att utsätta sig för omedelbar fara.",al={"vad är webwood egg","webwood egg bakgrund"}},fd568742={q="Varifrån kommer Webwood Egg?",a="Äggen läggs naturligt av de jättelika Webwood-spindlar som härjar i Shadowthread Cave i nordvästra Shadowglen. I grottans mörka, spindelvävsdränkta skrymslen håller spindlarna sina kullar där ungarna utvecklas innan de kläcks.",al={"webwood egg ursprung","varifrån kommer webwood eggs","vem lade webwood egg"}}},fp="11,151,20.355.0,22.353.0,29.104.0,26.118.0,49.178.0,46.163.0"}
P.entries["item:webwood-ichor"] = {n="Webwood Ichor",s="Webwood Ichor är en vätska som utvinns från Webwood-spindlar som stryker omkring i Teldrassil. Dirania Silvershine behöver den, tillsammans med hyacintsvampar och månblomsliljor, för att brygga ett motgift åt den förgiftade Iverron.",h="Webwood Ichor är en vätska som utvinns från Webwood-spindlar som stryker omkring i Teldrassil.",kw={"motgift","dirania silvershine","iverron","shadowglen","shadowthread cave","teldrassil","webwood ichor","webwood-spindel"},ang={["race:NightElf"]="För unga nattalver som försvarar Aldrassil lär insamlingen av Webwood Ichor ut naturens hårda balans: att Teldrassils dödligaste gifter ofta rymmer sina egna botemedel."},sec={{t="Ett giftigt botemedel",b="Webwood-spindlarna som hemsöker Shadowglen bär på ett gift som är så farligt att Iverron blir svårt sjuk. Dirania Silvershine ber om vätska från spindlarna, tillsammans med hyacintsvampar och månblomsliljor, för att tillreda ett motgift."}},faq={{q="Vad används Webwood Ichor till?",a="Dirania Silvershine i Shadowglen behöver Webwood Ichor, hyacintsvampar och månblomsliljor för att tillreda ett motgift åt nattalven Iverron, som har blivit förgiftad.",al={"användning av webwood ichor","vad gör webwood ichor","varför samla vätska"}},{q="Var kommer Webwood Ichor ifrån?",a="Den utvinns ur kropparna efter Webwood-spindlar i nordvästra Shadowglen, särskilt de som håller till runt och inne i Shadowthread Cave.",al={"var hittar man webwood ichor","hur får man webwood ichor","webwood ichor byte"}},{q="Varför använda spindelvätska för att bota ett spindelbett?",a="Dirania ber om Webwood Ichor som en av ingredienserna till Iverrons motgift. Hon förklarar inte hur vätskan verkar i blandningen.",al={"botemedel mot spindelgift","varför gift i motgift"}}},fx={dbd415b9={q="Vad är Webwood Ichor?",a="Webwood Ichor är en vätska som samlas in från Webwood-spindlarna i Shadowglen. Dirania Silvershine behöver den som en av ingredienserna i ett motgift som ska hjälpa Iverron.",al={"webwood ichor","vad är webwood ichor","spindelsekret"}},["789dead2"]={q="Varifrån kommer Webwood Ichor, och vem framställde det?",a="Den tillverkas eller framställs inte, utan utvinns direkt från Webwood-spindlarna som härjar i nordvästra Shadowglen kring Shadowthread Cave. Spindlarna producerar vätskan naturligt som en del av sin biologi.",al={"webwood ichor källa","varifrån kommer webwood ichor","vem producerade webwood ichor"}},["15a9db63"]={q="Varför vill någon ha Webwood Ichor?",a="Dirania Silvershine behöver Webwood Ichor för att blanda ett akut motgift åt Iverron, som har blivit svårt sjuk av spindelgift. Tillsammans med lokala Hyacinth Mushrooms och Moonpetal Lilies är sekretet avgörande för att motverka giftet som drabbat honom.",al={"varför samla in webwood ichor","varför behövs webwood ichor","vem behöver webwood ichor"}}},fp="13,178,12.183.0,31.155.0,35.122.0,43.129.0"}
P.entries["item:webwood-spider-silk"] = {n="Webwood Spider Silk",s="Webwood Spider Silk är en fin, klibbig tråd som utvinns från Webwood Lurkers som stryker omkring i Teldrassils skogar. Spindelsilke kan användas till mycket hantverk, men just dessa stycken eftertraktas av skumma gestalter i Världsträdets grenar.",h="Webwood Spider Silk är en fin, klibbig tråd som utvinns från Webwood Lurkers som stryker omkring i...",kw={"dolanaar","spindelsilke","teldrassil","webwood lurker","webwood spider silk","zenn foulhoof","zenns ärenden"},ang={["profession:Tailoring"]="Spinnare söker ofta efter spindeltrådar, men just dessa stycken ingår i mörka satyruppgörelser snarare än vanligt vävstolshantverk.",["race:NightElf"]="Unga nattalver som lämnar Shadowglen får rådet att vara uppmärksamma på varelserna de jagar, särskilt när de tvingas till det av en ensam satyr som lurar alldeles intill deras hemtrakter."},sec={{t="Ett tvivelaktigt reagens",b="Webwood Spider Silk spinns av de väldiga Webwood Lurkers som håller till kring Dolanaar. Silket är lätt, anmärkningsvärt starkt och farligt att samla in. Satyren Zenn Foulhoof, som lurar längs skogsvägen, anlitar unga äventyrare för att samla in stycken av silket samt nightsaber-huggtänder och strigid-uggelfjädrar. Han påstår att de bara är sällsynta reagenser som behövs i hans skogsverksamhet. Han förlitar sig på att nykomlingar är godtrogna nog att samla in de vilda beståndsdelarna utan att ifrågasätta hans korrumperade natur eller hans verkliga motiv."}},faq={{q="Var hittar man Webwood Spider Silk?",a="Webwood Spider Silk utvinns från Webwood Lurkers och närbesläktade spindeldjur som lever i Teldrassils vildmark, särskilt kring bosättningen Dolanaar.",al={"webwood silkets plats","vem släpper webwood spider silk","var får man tag på webwood spider silk"}},{q="Vem vill ha det här silket?",a="Satyren Zenn Foulhoof, som döljer sina förehavanden strax norr om stigen mellan Shadowglen och Dolanaar, ber om stycken av silket samt uggelfjädrar och rovdjursbetar.",al={"vem behöver webwood silk","uppdragsgivare för webwood silk","zenn foulhoof silk"}},{q="Varför vill Zenn Foulhoof ha Webwood Spider Silk?",a="Zenn påstår att han behöver silket som reagens i sin skogsverksamhet, men håller detaljerna för sig själv.",al={"zenn foulhoofs motiv","varför vill zenn ha silke"}},{q="Kan spelare använda Webwood Spider Silk till skrädderi?",a="Nej. Trots att det är äkta spindelsilke används just den här tråden som uppdragsreagens, inte som vanligt skrädderityg.",al={"är webwood silk ett skrädderimaterial","hantverk med webwood silk"}}},fx={["9ba9fe8b"]={q="Vad är Webwood Spider Silk?",a="Webwood Spider Silk är rå, spunnen tråd som samlas in från de jättelika spindeldjur som hemsöker Teldrassils skogar. Denna naturliga silke är fin men tålig och uppskattas av olika hantverkare bland trädkronorna, men för att samla in den måste du möta de giftiga Webwood-spindlarna i deras skuggiga bon.",al={"vad är webwood spider silk","webwood-silke","spindelsilke från teldrassil"}},["9736af76"]={q="Varifrån kommer Webwood Spider Silk?",a="Silket produceras naturligt av Webwood-spindlar, till exempel Webwood Lurkers som lurar i de trassliga snåren kring Dolanaar. Dessa aggressiva spindeldjur spinner tjocka nät bland Teldrassils väldiga rötter och håligheter, och skapar tåliga trådar som äventyrare måste samla in direkt från själva bestarna.",al={"webwood-silkets ursprung","vem producerar webwood-silke","varifrån kommer webwood-silke"}}},fp="19,211,17.371.0,39.119.0,20.176.0,48.99.1,50.114.0"}
P.entries["item:webwood-venom-sac"] = {n="Webwood Venom Sac",s="En Webwood Venom Sac är ett organ som utvinns från de övervuxna spindeldjuren i Shadowglen på Teldrassil. Naturforskare söker efter sådana prover för att ta reda på hur det nya världsträdets onaturliga tillväxt har förändrat det lokala djurlivet.",h="En Webwood Venom Sac är ett organ som utvinns från de övervuxna spindeldjuren i Shadowglen på Teldrassil.",kw={"aldrassil","gilshalan windwalker","shadowglen","shadowthread cave","teldrassil","gift","webwood-spindel","webwood venom sac"},ang={["class:Druid"]="För druider som är i samklang med naturens balans är den fördärvade styrkan i dessa giftsäckar ett alarmerande, konkret bevis på att allt inte står rätt till uppe bland Teldrassils grenar.",["race:NightElf"]="Unga nattalvsäventyrare i Shadowglen får i uppdrag att samla in dessa prover för att hjälpa lärda som försöker förstå den märkliga nya ekologin i sitt hem bland trädtopparna."},sec={{t="Ett tecken på Teldrassils tillväxt",b="Webwood-spindlarna som lever runt och inne i Shadowthread Cave är släkt med en mycket mindre spindelart som finns på andra platser. Deras plötsliga storleksökning och rovdjurslika aggressivitet har väckt oro bland nattalvernas forskare. Naturforskare som Gilshalan Windwalker studerar giftet i dessa säckar för att analysera dess styrka och sammansättning. De hoppas förstå hur Teldrassils snabba, obenade tillväxt förvrider varelserna som lever i dess grenar."}},faq={{q="Var hittar man Webwood Venom Sacs?",a="De samlas från webwood-spindlar som härjar i Shadowglens norra delar, särskilt i och runt Shadowthread Cave.",al={"var faller de","webwood venom sac plats","spindelgift plats"}},{q="Vem vill ha giftsäckarna?",a="Gilshalan Windwalker, en nattalvaforskare stationerad vid Aldrassil i Shadowglen, samlar in dem för att studera spindlarnas biologi innan han så småningom återvänder till Darnassus.",al={"vem behöver giftsäckar","gilshalan windwalker uppdrag"}},{q="Varför är webwood-spindlarna så stora?",a="Forskarna tror att det nya världsträdets framväxt och snabba tillväxt, Teldrassil, har haft en djupgående och förvridande effekt på det lokala djurlivet. Vanliga spindelarter har därmed blivit enorma, aggressiva rovdjur.",al={"varför är spindlar stora","webwood-spindel storlek"}},{q="Används giftet för att göra ett motgift?",a="Gilshalan samlar in säckarna enbart för jämförande studier. Spindelgift från den här regionen är dock en känd fara, och botemedel som Iverrons motgift behövs separat för att rädda dem som blivit bitna i skogen.",al={"är det här till ett botemedel","motgift ingrediens"}}},fx={bab81581={q="Vad är en Webwood Venom Sac?",a="En Webwood Venom Sac är en intakt körtel som skördats från Webwood-spindlarna som häckar i och kring Shadowthread Cave. Dessa onaturliga spindeldjur producerar kraftigt gift som forskare gärna vill analysera, särskilt med tanke på hur drastiskt spindlarna har muterat jämfört med sina mindre släktingar.",al={"vad är webwood venom sac","föremålet webwood venom sac","giftblåsa"}},["64d32b3b"]={q="Varifrån kommer en Webwood Venom Sac?",a="Säckarna tas direkt från kropparna på Webwood-spindlarna som härjar i norra Shadowglen. De är organ som spindeldjuren producerar naturligt, och deras oroande storlek och giftighet tros påverkas av Teldrassils närvaro.",al={"varifrån kommer webwood venom sacs","webwood venom sacs ursprung","vem producerade webwood venom sac"}}},fp="17,211,32.416.0,35.108.0,27.151.0,37.149.0,39.180.0"}
P.entries["item:well-stone"] = {n="Well Stone",s="Well Stone är små mineralstenar som samlas in från stränderna och omgivningarna kring Mulgore vattenbrunnar. De är rika på subtila jordenergier och utgör en viktig ingrediens när Water of the Seers bryggs under taurenfolkets traditionella övergångsriter.",h="Well Stone är små mineralstenar som samlas in från stränderna och omgivningarna kring Mulgore vattenbrunnar.",kw={"ambercorn","bloodhoof village","mulgore","visionsriten","water of the seers","well stone","zarlman two-moons"},ang={["class:Shaman"]="Schamaner förstår Well Stone som naturliga förankringar för jordens och vattnets magi, som drar samman slumrande andar i en förvandlande ceremoniell blandning.",["race:Tauren"]="Att samla Well Stone är ett viktigt steg för att visa samhörighet med landet. Det lär varje ung tauren hur jordens fysiska beståndsdelar bidrar till andlig upplysning."},sec={{t="Kärl för jordenergier",b="Well Stone ligger naturligt i den mjuka jorden vid Mulgore brunnar och tar upp slätternas och vattnens andliga resonans. Schamaner och siare som Zarlman Two-Moons ser dessa stenar som mer än vanliga flodstenar: de är kärl för mäktig magi. När de blandas med Ambercorn som plockats under slätternas väldiga träd mildrar stenarnas mineraler brygden som behövs för att väcka visionära transliknande tillstånd hos unga tauren under den heliga visionsriten."}},faq={{q="Vad används Well Stone till?",a="Well Stone blandas med Ambercorn för att brygga Water of the Seers. När drycken förtärs framför stammens eld skänker den en vägledande vision till de invigda som vill bevisa sin andliga mognad.",al={"well stone användning","vad används well stone till","varför samla well stone"}},{q="Var hittar man Well Stone?",a="De ligger på marken runt de gemensamma vattenbrunnarna som finns utspridda över Mulgore, där slätternas livgivande fukt möter jorden.",al={"var hittar man well stone","well stone platser","well stone mulgore"}},{q="Vem ber om stenarna?",a="Zarlman Two-Moons, en respekterad mystiker som bor i Bloodhoof Village, ber de invigda samla in dem som en del av visionsriten.",al={"vem behöver well stone","zarlman well stone","visionsritens stenar"}}},fx={["0148a630"]={q="Vad är en Well Stone?",a="En Well Stone är en naturligt förekommande sten som genomsyrats av magiska element och hämtas ur jorden kring de heliga vattenbrunnarna i Mulgore. Taurenmystiker värdesätter stenarna för rituell alkemi, eftersom deras koppling till landets rena vatten gör dem till kraftfulla katalysatorer.",al={"vad är well stones","well stone i mulgore","well stone bakgrund"}},a4e2d25c={q="Var kommer Well Stones ifrån?",a="Well Stones tillverkas inte av dödliga händer, utan hämtas direkt ur jorden och sedimentet kring Mulgore:s vattenbrunnar. Under generationer har de formats och berörts av de heliga källor som förser slätterna med vatten, och mineralerna absorberar naturligt landets omgivande andliga och elementära energi.",al={"var kommer well stones ifrån","vem har tillverkat well stones","well stones ursprung"}},["461b83d8"]={q="Varför vill Zarlman Two-Moons ha Well Stones?",a="Zarlman Two-Moons behöver Well Stones för att bereda Water of the Seers åt unga tauren som ska genomgå Rite of Vision. När stenarna krossas och får dra tillsammans med Ambercorn skapar deras magiska beståndsdelar en kraftfull helig brygd som väcker din andliga syn och låter dig se förfäders vägvisare som lyser upp din väg.",al={"varför samla well stones","varför vill zarlman ha well stones","well stones rite of vision"}}},fp="10,150,26.452.0,30.197.0,28.144.0,26.130.0"}
P.entries["item:wendigo-mane"] = {n="Wendigo Mane",s="Wendigo Manes är de tjocka, raggiga pälsar som tas från de vilda wendigos som strövar bland Dun Moroghs frusna klippor. De är eftertraktade för sitt goda skydd mot den bitande bergskylan. De grova skinnen är tåliga nog att klä golven i stugor eller i dvärgarnas järnhus till krigsmaskiner.",h="Wendigo Manes är de tjocka, raggiga pälsar som tas från de vilda wendigos som strövar bland Dun Moroghs...",kw={"dun morogh","päls","the grizzled den","kharanos","man","skinn","stonegear","trollplow","wendigo"},ang={["profession:Engineering"]="Att köra dvärgmaskiner i Dun Morogh innebär att tampas med iskalla metallhytter. Isolerande beklädnader av wendigopäls är därför en praktisk komfortförbättring.",["race:Dwarf"]="Att jaga wendigos i The Grizzled Den är ett beprövat prov för unga dvärgar som vill visa sin tuffhet för veteranerna i Kharanos."},sec={{t="Värme åt järnverket",b="Bergen i Dun Morogh är hårda och obevekliga, så lokalborna tar vara på de rovdjur som jagar över snödrivorna. Den grova pälsen från en wendigo ger ett tätt skydd mot iskalla vinddrag. Pilot Stonegear, som håller till utanför Kharanos, skickar äventyrare till närbelägna The Grizzled Den för att samla in de tunga manarna. Den excentriske piloten tänker inte sy vinterrockar eller mantlar av dem, utan väva en mjuk, isolerande golvmatta till däcket i sin kära dvärgiska belägringsmaskin, Trollplow."}},faq={{q="Vilka varelser ger Wendigo Mane?",a="Manarna kan samlas in från alla wendigos som lever i Dun Moroghs snölandskap. Det gäller vanliga Young Wendigos, vuxna Wendigos och framstående alfadjur som Vagash, Edan the Howler och Old Icebeard.",al={"var får man wendigo manes","vem släpper wendigo mane","källor till wendigo mane"}},{q="Varför vill Pilot Stonegear ha manarna?",a="Pilot Stonegear vill använda manarna till att tillverka en isolerande matta för däcket inuti hans belägringsmaskin, Trollplow. Det blir isande kallt när man kör en väldig järnmaskin genom frusen terräng, och den tjocka pälsen hjälper till att hålla pilotens plats varm och bekväm.",al={"varför stonegear vill ha manar","pilot stonegears matta","vad används manar till"}},{q="Var är det bäst att hitta wendigos för deras manar?",a="Pilot Stonegear rekommenderar främst The Grizzled Den, ett grottsystem som skurits ut i bergen direkt väster om Kharanos. Grottan och sluttningarna runt den myllrar av wendigos.",al={"the grizzled den plats","var jagar man wendigos","wendigogrotta dun morogh"}},{q="Är wendigos farliga att jaga?",a="Ja. Wendigos är vilda, revirhävdande rovdjur med brutal fysisk styrka och tjockt skinn. Dvärgarnas tränare ser det som ett tidigt mandomsprov att våga sig in i deras hålor och visa prov på bergsbestigarens mod och stridsförmåga.",al={"är wendigos svåra att döda","slåss mot wendigos"}}},fx={["9c5452b4"]={q="Vad är en Wendigo Mane?",a="En Wendigo Mane är en tjock, raggig tofs av grov päls från de vildsinta wendigos som strövar omkring bland Dun Moroghs snöiga klippor. Pälsen isolerar de grymma bestarna mot de bitande snöstormarna i bergen och är slitstark, varm och mycket eftertraktad för grovt hantverk.",al={"vad är wendigo mane","föremålet wendigo mane","wendigo-päls"}},e05af805={q="Varifrån kommer en Wendigo Mane?",a="Dessa manar tas direkt från de vilda wendigos som strövar omkring i Dun Morogh, särskilt nära hålor som Grizzled Den väster om Kharanos. De är naturliga djurhudar som jägare tar från bergens varelser, om de vågar möta deras klor och huggtänder.",al={"varifrån kommer wendigo manes","vem släpper wendigo mane","wendigo mane ursprung"}}},fp="12,133,24.300.0,36.170.0,42.199.0,57.151.0,31.198.0"}
P.entries["item:whitestone-oak-lumber"] = {n="Whitestone Oak Lumber",s="Whitestone Oak Lumber är ett tåligt hantverkstimmer från de underjordiska skeppsvarven under Moonbrook. Det värdesätts för sin styrka och används som ett viktigt skaftmaterial till heliga vapen smidda av Alliansens mästersmeder.",h="Whitestone Oak Lumber är ett tåligt hantverkstimmer från de underjordiska skeppsvarven under Moonbrook.",kw={"the deadmines","goblin woodcarver","jordan stilwell","paladinhammare","test of righteousness","whitestone oak lumber"},ang={["class:Paladin"]="Att skaffa detta timmer från Defias underjordiska skeppsdockor är ett grundläggande krav i Jordan Stilwells Test of Righteousness. Det ger en helig hammare, tillverkad för Ljuset försvarare.",["profession:Blacksmithing"]="I Stilwells vapenskisser kombineras tät Whitestone Oak med förädlad malm och ädelstensarbete för att balansera vikt, hållbarhet och metafysisk resonans."},sec={{t="Ett heligt skaft",b="Utanför Ironforge kräver smeden Jordan Stilwell Whitestone Oak Lumber för att tillverka ett vapen värdigt en sann förkämpe för Ljuset. Tillsammans med en renad Kor-ädelsten och förädlade metaller ger timret det välbalanserade, orubbliga skaft som behövs för att stå emot de heliga energier som kanaliseras under Test of Righteousness."},{t="Timmer från de undre skeppsdockorna",b="Djupt inne i Deadmines labyrintgångar i Westfall formas Whitestone Oak av Goblin Woodcarvers som bygger Defias Brotherhoods hemliga krigsflotta. Dess täta, motståndskraftiga ådring gör det idealiskt för att tåla strukturell belastning och kraftigt slitage. Det väcker intresse hos erfarna rustningsmakare som behöver mer än vanlig ask eller tall till ceremoniella och militära arbeten."}},faq={{q="Var hittar man Whitestone Oak Lumber?",a="Det tas till vara från Goblin Woodcarvers som arbetar djupt inne i Deadmines under Moonbrook i Westfall, där Defias Brotherhood bygger sin dolda jätteskepp.",al={"var man hittar whitestone oak","whitestone oak plats","vem som släpper whitestone oak lumber"}},{q="Vem använder det här timret?",a="Jordan Stilwell, en skicklig smed som arbetar nära Ironforges portar i Dun Morogh, behöver timret för att tillverka ett särskilt vapen åt blivande paladiner.",al={"vem som behöver whitestone oak","lämna in whitestone oak"}},{q="Vad används träet till?",a="Jordan Stilwell använder det tåliga timret som skaft till en mästersmidd, tvåhänt helig hammare, smidd som belöning för att slutföra Test of Righteousness.",al={"vad whitestone oak används till","vad jordan stilwell smider"}},{q="Varför passar goblintimmer till ett heligt vapen?",a="Defias Brotherhood skaffar täta timmersorter av hög kvalitet som klarar att bära upp krigsskepp. Jordan Stilwell inser att sådant konstruktionsvirke ger den fysiska tålighet som krävs för att hantera intensiv gudomlig kraft.",al={"varför goblinträ","varför timmer från deadmines"}}},fx={["3fba151d"]={q="Vad är Whitestone Oak Lumber?",a="Whitestone Oak Lumber är ett fint, specialiserat virke som skickliga hantverkare gärna vill ha. Det uppskattas för sin styrka och kvalitet och utgör det oumbärliga skaftet eller greppet när ett mästerverk till vapen smids åt det heliga ljuset.",al={"vad är whitestone oak lumber","whitestone oak lumber","vad är whitestone lumber"}},["9364a134"]={q="Varifrån kommer Whitestone Oak Lumber, och vem har tillverkat det?",a="Virket avverkas och bearbetas långt inne i Deadmines i Westfall. Det formas av de gobliniska träsnidare som arbetar åt Defias Brotherhood och som sågar och bearbetar timret mitt i deras olagliga byggprojekt under jord.",al={"varifrån kommer whitestone oak","källa till whitestone oak lumber","vem har tillverkat whitestone oak lumber"}},e7d39b03={q="Varför vill Jordan Stilwell ha Whitestone Oak Lumber?",a="Vapensmeden Jordan Stilwell behöver just det här träslaget för att smida ett storslaget vapen åt en helig paladin. Tillsammans med förädlad malm, en renad Kor-ädelsten och hans fars hammare blir den tåliga eken grunden till det han anser vara sitt främsta verk.",al={"varför vill man ha whitestone oak lumber","varför behöver jordan whitestone oak","vad används whitestone oak lumber till"}}},fp="21,150,13.284.1,25.279.1,37.158.1,21.134.0,30.148.0,48.145.0"}
P.entries["item:wildmane-cleansing-totem"] = {n="Wildmane Cleansing Totem",s="Wildmane Cleansing Totem är ett helgat ritualföremål som skapats för att rena den norra vattenkällan i Mulgore. Det anförtros åt unga försvarare av landet och är det sista medlet för att driva bort den giftiga förorening som goblinernas intrång lämnat efter sig.",h="Wildmane Cleansing Totem är ett helgat ritualföremål som skapats för att rena den norra vattenkällan i...",kw={"bloodhoof village","goblinernas gifter","mulgore","mull thunderhorn","tauren","wildmane cleansing totem","wildmane water well"},ang={["class:Shaman"]="Att leda andlig rening genom utsnidade totemer är grundläggande för att hela de sårade vattenandarna som fördärvats av hänsynslös industri.",["race:Tauren"]="Att återställa Wildmane-källan är en högtidlig plikt mot Jordmodern. Det driver bort främmande industriella gifter och bevarar ditt förfädersland."},sec={{t="Reningen av de heliga källorna",b="När goblinernas verksamhet började förgifta landet och smutsa ner Mulgore knappa vattentillgångar vände sig tauren till heliga ritualer för att häva fördärvet. Efter att ha renat både Winterhoof och Thunderhorn vattenkällor tillverkar Mull Thunderhorn denna sista totem för att driva bort den återstående föroreningen vid Wildmane Water Well norr om Thunder Bluff. Totemen är fylld av naturandar och renar det stinkande vattnet så att rent liv åter kan ge näring åt slätterna."}},faq={{q="Vad används Wildmane Cleansing Totem till?",a="Totemen används i en reningsritual hos tauren för att neutralisera gifterna och det förorenade avrinningvatten som smutsar ner Wildmane Water Well norr om Thunder Bluff, och återställa landets renhet.",al={"vad gör totemen","användning av wildmane totem","varför rena källan"}},{q="Vem skapar Wildmane Cleansing Totem?",a="Mull Thunderhorn ger dig totemen efter att du hjälpt honom att samla de nödvändiga beståndsdelarna och rena de andra förgiftade källorna i Mulgore.",al={"vem gav mig totemen","mull thunderhorn totem","var får jag tag på reningstotemen"}},{q="Varför är vattenkällorna i Mulgore förgiftade?",a="Gobliner som tränger sig in i området har fört in giftiga ämnen och skadligt industriavfall i det lokala grundvattnet. Det hotar taurenstammarna och slätternas naturliga balans.",al={"vem förgiftade källorna","varför är källan giftig","goblinernas gifter i mulgore"}},{q="Var ska totemen användas?",a="Den måste tas till Wildmane Water Well, som ligger på The Rolling Plains norr om Thunder Bluffs mäktiga klippor.",al={"wildmane-källans plats","var ligger wildmane water well","vart ska jag ta totemen"}}},fx={["6c54f1c7"]={q="Vad är Wildmane Cleansing Totem?",a="Det är ett heligt ritualföremål som shamanen Mull Thunderhorn har berett i Bloodhoof Village. Totemet har fått andarnas välsignelse efter att du renat Winterhoof- och Thunderhorn-brunnarna, och bär på kraften som behövs för reningsritualen vid den sista förorenade vattenbrunnen norr om Thunder Bluff.",al={"vad är wildmane cleansing totem","wildmane totem","wildmane-reningstotem"}}},fp="24,176,26.406.0,52.139.0,41.121.0,44.151.0,38.65.0"}
P.entries["item:wiley-s-note"] = {n="Wiley's Note",s="Wiley's Note är ett hemligt brev skrivet av Lakeshires skurk Wiley the Black, som betalning för en skuld till Gryan Stoutmantle. Innehållet avslöjar oroväckande allianser som Defias Brotherhood har ingått och drar in Stormwinds underrättelsetjänst i utredningen.",h="Wiley's Note är ett hemligt brev skrivet av Lakeshires skurk Wiley the Black, som betalning för en skuld till...",kw={"defias brotherhood","gryan stoutmantle","mathias shaw","sentinel hill","si:7","stenhuggare","wiley the black","wiley's note"},ang={["class:Rogue"]="Brevet passerar genom händerna på två ökända personer i branschen: Wiley the Black, en skurk på gatunivå, och Master Mathias Shaw, ledare för det hemlighetsfulla SI:7.",["faction:Alliance"]="Brevet markerar den avgörande vändpunkten då lokalt gränslandsbanditdåd i Westfall identifieras som en organiserad konspiration som hotar stabiliteten i själva Stormwind."},sec={{t="En farlig förteckning",b="Det här klottriga meddelandet skrevs i Redridge av den skumraskaktige skurken Wiley the Black och överlämnas för att återgälda en gammal gentjänst till Gryan Stoutmantle. I det avslöjar Wiley vad han vet om Defias Brotherhoods hemliga ambitioner. Hans uppgifter visar att brödraskapet inte arbetar ensamt: de har slutit allianser med gnoller, kobolder och goblinagenter i regionen för att utöka sin verksamhet i hela kungariket."},{t="Kopplingen till stenhuggarna",b="Utöver att nämna legoknektspakter råkar Wiley avslöja en viktig koppling mellan Defias-syndikatet och Stonemasons Guild, som återuppbyggde Stormwind efter det andra kriget. Stoutmantle inser de explosiva politiska följderna av uppgiften och skickar brevet direkt till Master Mathias Shaw, spionchef för SI:7, vilket drar in Stormwinds underrättelseapparat i utredningen."}},faq={{q="Vem skrev Wiley's Note?",a="Det skrevs av Wiley the Black, en person med tvivelaktig moral som håller till i Lakeshire i Redridge. Han överlämnade det för att återgälda en gentjänst han stod i skuld till Gryan Stoutmantle i People's Militia för.",al={"författare till wileys note","vem är wiley","wileys black brev"}},{q="Vilka uppgifter innehåller brevet?",a="Brevet varnar för att Defias Brotherhood smider storslagna planer och har slutit allianser med gnoller, kobolder och gobliner. Stoutmantle söker ytterligare råd om dess känsligare innehåll.",al={"innehållet i wileys note","vad står det i brevet","information om defias-brevet"}},{q="Vart ska brevet levereras?",a="Först förs det till Gryan Stoutmantle vid Sentinel Hill i Westfall. Efter att ha läst det beordrar Stoutmantle att det ska levereras till Master Mathias Shaw vid SI:7:s högkvarter i Stormwind City.",al={"vem får wileys note","lämna in wileys note","var ska jag ta brevet"}},{q="Varför skickar Gryan Stoutmantle brevet till SI:7?",a="Gryan misstänker att brevet pekar på en djupare konspiration än enkelt banditdåd. Han skickar det till Mathias Shaw, chef för Stormwinds underrättelsetjänst, för att utreda saken.",al={"varför visa mathias shaw","varför ge shaw brevet","si7 wileys note"}}},fp="12,218,18.283.0,25.292.1,23.141.0,39.183.0,41.169.0,49.160.0"}
P.entries["item:william-s-shipment"] = {n="William's Shipment",s="I Goldshire packar William Pestle ljus av Elwynns kobolder åt sin bror Morgan i Stormwind.",h="I Goldshire packar William Pestle ljus av Elwynns kobolder åt sin bror Morgan i Stormwind.",kw={"ljus","goldshire","koboldljus","morgan pestle","pestle's apothecary","stormwind","trade district","william pestle","william's shipment"},ang={["faction:Alliance"]="Som medlem i Alliansen hjälper du till att skydda gruvorna i Elwynn från kobolder och förse huvudstadens butiker med råvaror till alkemin.",["race:Human"]="Som människa kan du se hur handeln i Goldshire knyter samman landsbygdens byar med huvudstaden Stormwind."},sec={{t="En familjehandel",b="William Pestle håller handeln mellan Goldshire och huvudstaden i gång. Han samlar material i Elwynn Forest, medan hans bror Morgan driver Pestle's Apothecary i Stormwinds Trade District. William kan inte lämna sina plikter för att resa norrut, så han är beroende av kurirer som bär paketet med vax och ljus in till staden."},{t="Koboldvax",b="Koboldljus från gruvorna i Elwynn fyller försändelsen. William samlar de stora ljusen för vaxets skull och packar dem åt Morgan på Pestle's Apothecary. Vaxet blir en del av lagret som används i huvudstadens alkemihandel."}},faq={{q="Vad innehåller William's Shipment?",a="Försändelsen innehåller ljus från kobolder i gruvorna i Elwynn Forest. William samlar in dem från förbipasserande äventyrare och packar dem som råvaror till familjens alkemibutik.",al={"försändelsens innehåll","vad finns i lådan","vad skickar william"}},{q="Vem skickar William paketet till?",a="William skickar paketet till sin bror Morgan Pestle, som driver Pestle's Apothecary i Trade District i Stormwind City.",al={"vem får försändelsen","vem är leveransen till","försändelsens destination"}},{q="Varför behöver en apotekare så många ljus?",a="William säger att han och hans bror behöver de stora ljusen för deras vax. Han säger inte vilka preparat det ska användas till.",al={"varför ljus till alkemi","vad gör pestle med ljusen","användning av ljus"}},{q="Varför levererar inte William paketet själv?",a="William är upptagen med att sköta sina affärer och samla varor i Goldshire, och har inte tid för resan landvägen till Stormwind. Han anlitar resande som är på väg till huvudstaden för att bära paketet.",al={"varför kan william inte åka","varför behöver william en kurir"}}},fx={bf7eefd8={q="Vad är William's Shipment?",a="William's Shipment är ett säkert inslaget knippe stora vaxljus som William Pestle har gjort i Goldshire. Ljusen togs från kobolder i gruvorna i Elwynn Forest och packades för leverans till Morgan Pestle i Stormwind.",al={"vad är williams shipment","williams shipment-paket","williams leverans"}},["2b07f2a7"]={q="Varifrån kommer William's Shipment, och vem har gjort den?",a="Försändelsen kommer direkt från William Pestle, en alkemist som bor på Lion's Pride Inn i Goldshire. William packade själv lådorna med stora vaxljus som tagits från kobolderna som härjar i de närliggande gruvorna Fargodeep och Jasperlode.",al={"vem har gjort williams shipment","varifrån kom williams shipment","williams shipment ursprung"}}},fp="18,118,16.286.0,10.217.0,34.192.0,39.121.0,44.117.0,48.185.0"}
P.entries["item:wine-ticket"] = {n="Wine Ticket",s="I Stormwind delar Renato Gallina ut Wine Tickets för att locka kunder till familjens butik. Visa upp en för Suzetta Gallina och få en flaska Pinot Noir utan kostnad.",h="I Stormwind delar Renato Gallina ut Wine Tickets för att locka kunder till familjens butik.",kw={"gallina winery","pinot noir","renato gallina","stormwinds kanaler","suzetta gallina","trade district","wine ticket"},ang={["profession:Cooking"]="En flaska Pinot Noir från den här biljetten passar bra till mustiga kötträtter och ostar från hela Eastern Kingdoms."},sec={{t="Familjens årgångsvin gör reklam",b="Renato Gallina gör reklam för Gallina Winery med tryckta biljetter nära Trade District i Stormwind. Vineriet är en liten specialbutik längs kanalerna i närheten. Varje biljett utlovar ett smakprov av Pinot Noir utan kostnad och lockar nyfikna förbipasserande och nyanlända äventyrare till familjens verksamhet, i hopp om att de blir trogna kunder."}},faq={{q="Vad gör jag med Wine Ticket?",a="Ta Wine Ticket till Suzetta Gallina på Gallina Winery längs kanalerna i Trade District i Stormwind. Hon löser in den mot en flaska Pinot Noir utan kostnad.",al={"använda wine ticket","hur använder jag wine ticket","var lämnar jag wine ticket"}},{q="Vem delar ut de här biljetterna?",a="Renato Gallina delar ut biljetterna nära Trade District för att locka potentiella kunder till familjens vinbutik.",al={"vem delar ut wine ticket","var får jag wine ticket"}},{q="Vilket vin får jag med biljetten?",a="Biljetten kan lösas in mot en flaska Pinot Noir, ett av de finaste vinerna som familjen Gallina säljer i kungariket.",al={"wine ticket-belöning","vilket vin får jag"}}},fx={eb06e870={q="Vad är Wine Ticket?",a="Wine Ticket är en reklamkupong och ett annonsblad som delas ut på Stormwinds gator. Den fungerar som en inbjudan till Gallina Winery och ger alla som har den rätt till ett gratis smakprov av Gallina-familjens finaste årgångsviner.",al={"vad är wine ticket","föremålet wine ticket","reklambiljett till vinbutik"}},["38c548d0"]={q="Varför vill Suzetta Gallina ha Wine Ticket?",a="Suzetta Gallina samlar in kupongen för att bekräfta att du har fått vingårdens gatureklam av hennes bror, Renato Gallina. När du byter in kupongen uppfyller de sitt reklamerbjudande och välkomnar nya kunder till sin butik vid kanalen med en gratis flaska Pinot Noir.",al={"varför vill suzetta ha biljetten","varför lämna in wine ticket","varför vill någon ha wine ticket"}}},fp="11,157,28.333.0,34.170.0,28.106.0,41.111.0"}
P.entries["item:winterhoof-cleansing-totem"] = {n="Winterhoof Cleansing Totem",s="Winterhoof Cleansing Totem är ett helgat ritualföremål som Mull Thunderhorn har tillverkat i Bloodhoof Village. Det är ristat för att upphäva den giftiga härja som Venture Companys inkräktare spridit och leder Jordmoderns kraft för att rena den förorenade Winterhoof Water Well.",h="Winterhoof Cleansing Totem är ett helgat ritualföremål som Mull Thunderhorn har tillverkat i Bloodhoof...",kw={"bloodhoof village","rening","mulgore","mull thunderhorn","totem","venture company","vattenkälla","winterhoof"},ang={["class:Shaman"]="Att använda en reningstotem återspeglar grundläggande shamanistiska principer och brukar jordens och vattnets elementära harmoni för att driva bort konstgjord fördärvelse.",["race:Tauren"]="Skändningen av sötvattenkällor slår mot själva kärnan i taurenfolkets band till Jordmodern och gör totemens ritual till ett oumbärligt försvar av hemlandet."},sec={{t="Reningen av källan",b="När Venture Companys gobliningenjörer trängde in på Mulgore-slätterna förorenade deras industriella verksamhet snabbt landets dyrbara grundvatten. Som svar förberedde Mull Thunderhorn Winterhoof Cleansing Totem och laddade det snidade träet med skyddande magi som skulle skölja bort de främmande gifterna. När totemen förs förbi fientliga goblinvakter till kanten av Winterhoof Water Well sprider den föroreningen genom en fokuserad ritual och återställer rent dricksvatten åt slätternas kringströvande hjordar och ursprungsstammar."}},faq={{q="Vad används Winterhoof Cleansing Totem till?",a="Den förs till Winterhoof Water Well sydost om Bloodhoof Village för att utföra en reningsritual och skura bort den industriella förorening som Venture Companys gobliner har släppt ut i grundvattenmagasinet.",al={"reningstotemens syfte","användning av winterhoof totem","vad gör totemen"}},{q="Vem tillverkade totemen?",a="Mull Thunderhorn, en respekterad tauren från Bloodhoof Village, ristade och förberedde totemen särskilt för att upphäva skadan på Winterhoof Water Well.",al={"vem skapade winterhoof totem","skaparen av reningstotemen","mull totem"}},{q="Varför förorenades Winterhoof Water Well?",a="Venture Company slog läger runt källan och fördärvade den naturliga vattenplatsen med avrinning, avfall och kemiskt slam från sina avverknings- och gruvmaskiner.",al={"vem förgiftade winterhoof well","orsak till brunnens förorening","varför är brunnen smutsig"}},{q="Vad händer när reningsritualen är klar?",a="Det grumliga, förorenade vattnet blir rent och hälsosamt igen, så att slätternas lokala djurliv och de vandrande taurenhjordarna tryggt kan dricka ur brunnen.",al={"efter att totemen använts","resultat av brunnens rening","blir brunnen återställd"}}},fx={["25396a0d"]={q="Vad är Winterhoof Cleansing Totem?",a="Det är ett heligt ritualtotem som Mull Thunderhorn har snidat i Mulgore. Totemet är genomsyrat av naturandar och särskilt utformat för att rena den förgiftade Winterhoof Water Well och rensa bort industriföroreningarna från Venture Company.",al={"winterhoof cleansing totem","vad är winterhoof totem","om winterhoof cleansing totem"}},b2bc5f58={q="Varför behöver Mull Thunderhorn att Winterhoof Cleansing Totem används?",a="Tauren är beroende av Mulgore:s vattenbrunnar för sin egen och slätternas vilda djurs överlevnad. Eftersom gobliner från Venture Company har förorenat Winterhoof Water Well behöver Mull Thunderhorn en äventyrare som bär totemet in i fientligt område och renar vattnet innan föroreningen förstör landet för gott.",al={"varför använda winterhoof cleansing totem","varför rena winterhoof-brunnen","winterhoof-totemets syfte"}}},fp="26,132,20.464.0,48.142.0,23.133.0,43.172.0,51.128.0"}
P.entries["item:witchwing-talon"] = {n="Witchwing Talon",s="I nordvästra The Barrens markerar Witchwing Talons döda harpyierövare. Hordens spejare vid The Crossroads söker efter dem som bevis medan de säkrar viktiga karavanleder.",h="I nordvästra The Barrens markerar Witchwing Talons döda harpyierövare.",kw={"the barrens","karavaner","the crossroads","darsok swiftdagger","harpy","klo","witchwing"},ang={["class:Rogue"]="Darsok Swiftdagger värdesätter tysta, precisa angrepp. För honom vittnar dessa vassa klor om en skicklig mördares arbete mot luftburna rovdjur.",["faction:Horde"]="Karavaner förbinder Hordens utspridda utposter i Kalimdor, så när harpyiernas boplatser rensas blir gränslandet säkrare."},sec={{t="Troféer från nästena",b="Witchwing-harpyier anfaller Hordens försörjningskaravaner från sina boplatser nordväst om The Crossroads. Spejaren Darsok Swiftdagger samordnar angrepp mot flockens hierarki. Darsok kräver fysiska bevis på varje död asätare, och klorna utgör sådana bevis. När spejarna kan visa att rövare har fallit kan de försvaga flockens led innan de slår till högre upp i dess befälskedja."}},faq={{q="Vem vill ha Witchwing Talons och varför?",a="Darsok Swiftdagger, en orkspejare vid The Crossroads, samlar in dem. Han planerar ett fälttåg mot Witchwing-kullen och kräver åtta klor som bevis på att dess främsta rövare har dödats.",al={"vem behöver klor","uppdragsgivare för witchwing talon","darsok swiftdagger klor"}},{q="Vilka harpior bär på dessa klor?",a="Witchwing Talons kommer från harpyier i nordvästra The Barrens, däribland vanliga harpyier och Witchwing Roguefeathers som häckar längs klipporna och torra höjderna.",al={"vad släpper witchwing talons","vilka harpior har klor"}},{q="Varför är Witchwing-harpiorna måltavlor?",a="Witchwing-flocken har blivit allt djärvare och angriper Hordens försörjningslinjer och handelskaravaner i hela The Barrens. Darsok vill minska dess lägre leden innan han slår till mot dess löjtnanter och matriark.",al={"varför döda witchwing-harpior","syftet med harpyplundrare"}}},fx={["5a3e0f86"]={q="Vad är en Witchwing Talon?",a="En Witchwing Talon är en vass klo som tas direkt från de bevingade fötterna på Witchwing-harpiorna som hemsöker Barrens nordvästra utkanter. För hordens spejare vid Crossroads är de avhuggna klorna obestridliga, fysiska bevis på döda rövare.",al={"witchwing talon","vad är witchwing-talons","witchwing-klo"}},["98111910"]={q="Varifrån kommer Witchwing Talons?",a="Dessa klor växer naturligt på Witchwing-harpiorna som håller till i kanjonerna i nordvästra Barrens. Jägare som skickats ut för att minska flocken tar dem från kropparna av vanliga Witchwing-harpior och Roguefeathers.",al={"witchwing talon ursprung","varifrån kommer witchwing talons","vem släpper witchwing talons"}}},fp="15,168,24.365.0,35.193.0,33.159.0,45.199.0"}
P.entries["item:wolf-heart-sample"] = {n="Wolf Heart Sample",s="Wolf Heart Sample är på väg till The Crossroads med sjuk vargvävnad från Lordaeron till Kalimdor. Royal Apothecary Society vill ta reda på hur nordliga gifter påverkar The Barrens inhemska djur.",h="Wolf Heart Sample är på väg till The Crossroads med sjuk vargvävnad från Lordaeron till Kalimdor.",kw={"apothecary helbrim","apothecary renferrel","the barrens","the crossroads","lordaeron","royal apothecary society","gifter","wolf heart sample"},ang={["faction:Horde"]="Som medlem av Horde hjälper du till att föra forskningsreagenser över havet och knyta ihop Undercity med Hordes utposter i The Barrens.",["race:Undead"]="Som odöd för du Royal Apothecary Societys forskning till Kalimdor, där sällskapet testar nordliga brygder på okänt djurliv."},sec={{t="En giftig export",b="Wolf Heart Sample började med pestsmittade vargar bland Lordaerons ruiner. Apothecary Renferrel samlade in hjärtana, som packades för resan över Great Sea. Forsakens Royal Apothecary Society vill få större kunskap om gift, pestsmittor och biologiska reagenser. En kurir för paketet till The Crossroads i The Barrens och knyter ihop Undercitys experiment i de sargade Eastern Kingdoms med Kalimdors utpost vid gränslandet."},{t="Helbrims forskning",b="Vid The Crossroads tar Apothecary Helbrim emot Wolf Heart Sample. Helbrim undersöker hur gifter från Lordaerons härjade marker påverkar Kalimdors inhemska djurliv. Giftigheten som bevarats i varghjärtana kan avslöja egenskaper som förbättrar Forsakens gifter och elixir långt hemifrån."}},faq={{q="Vad är Wolf Heart Sample?",a="Wolf Heart Sample består av vävnad från pestdrabbade vargar i Lordaeron. Den kvarvarande giftigheten från de nordliga farsoterna ger Royal Apothecary Society material för att studera frätande gifter.",al={"wolf heart sample","vad är provet","vad finns i paketet"}},{q="Vem skickade provet till The Barrens?",a="Apothecary Zinge skickade provet från Undercity, med varghjärtan som Apothecary Renferrel hade skickat till henne från Silverpine Forest.",al={"vem skickade varghjärtat","vem gav mig det här","var kommer wolf heart sample ifrån"}},{q="Varför vill Apothecary Helbrim ha det?",a="Helbrim undersöker hur gifter från Lordaeron påverkar Kalimdors inhemska djur. Han planerar att studera provets giftiga egenskaper för att utveckla Forsakens alkemiska blandningar och gifter.",al={"varför vill helbrim ha det","helbrims forskning","vad varghjärtat ska användas till"}},{q="Vart ska provet levereras?",a="Ta provet till Apothecary Helbrim vid The Crossroads, en viktig Horde-bosättning mitt i The Barrens.",al={"vart ska varghjärtat lämnas","var finns helbrim","leveransplats"}}},fp="17,205,14.444.0,18.298.0,30.196.0,36.124.0,36.185.0,43.111.0"}
P.entries["item:wolf-heart-samples"] = {n="Wolf Heart Samples",s="Wolf Heart Samples är märkliga organiska prover från fördärvade vargar i Silverpine Forest. Trots sin dödliga giftighet slår hjärtana i de levande djuren utan att döda dem, vilket väcker Royal Apothecary Societys intensiva vetenskapliga intresse.",h="Wolf Heart Samples är märkliga organiska prover från fördärvade vargar i Silverpine Forest.",kw={"apothecary renferrel","apothecary zinge","royal apothecary society","silverpine forest","gift","undercity","wolf heart samples"},ang={["race:Undead"]="Royal Apothecary Societys outtröttliga jakt på dödliga reagenser bidrar till att Forsaken överlever och försvarar sig mot både levande och odöda fiender."},sec={{t="En giftig paradox",b="När Apothecary Renferrel undersökte kadaver i Silverpine Forest upptäckte han att vissa varghjärtan innehöll en dödlig förening. Märkligt nog borde giftmängden i vävnaden lätt vara dödlig för vargarna själva. Renferrel insåg värdet av en fysiologi som frodas trots att den är mättad av dödligt gift och lade undan vävnadsprover för att skickas direkt till Undercity. För Forsaken är studier av naturligt motståndskraftiga eller giftiga organismer ett avgörande steg mot att bemästra biologisk krigföring och framställa nya reagenser."},{t="Leverans till Undercity",b="Proverna anförtros åt kurirer på väg djupt ned under Ruins of Lordaeron och levereras till Apothecary Zinge vid Royal Apothecary Societys högkvarter i Apothecarium. Zinge och hennes kollegor värdesätter nya gifter högre än nästan allt annat. Genom att dissekera och experimentera med de förgiftade vävnaderna försöker sällskapet isolera de kraftfulla föreningarna och förstå hur bestarna överlevde dem, i hopp om att tillämpa principerna i sina egna alkemiska projekt."}},faq={{q="Varför är de här varghjärtana viktiga för Forsaken?",a="Proverna innehåller ett starkt, oförklarligt gift som normalt skulle ha dödat värdvargarna. Royal Apothecary Society fascineras både av själva det kraftfulla giftet och av den biologiska mekanism som låter djuren överleva det.",al={"varför är varghjärtan viktiga","vad gör hjärtana speciella","varför vill apotekare ha varghjärtan"}},{q="Vem begär proverna?",a="Apothecary Renferrel samlade in proverna efter att ha studerat vargar i Silverpine Forest. Han bad en kurir att leverera dem direkt till sin kollega Apothecary Zinge vid sällskapets högkvarter i Undercity.",al={"vem vill ha varghjärtana","vem skickade proverna","vem tar emot proverna"}},{q="Vad ska Apothecary Zinge göra med dem?",a="Apothecary Zinge utför alkemiska experiment och dissektioner av proverna. Royal Apothecary Society katalogiserar och beväpnar sig ständigt med nya gifter för att utveckla nya farsoter och brygder åt Queen Sylvanas.",al={"vad gör zinge med hjärtana","zinges experiment","apothecary zinges forskning"}},{q="Varifrån kom vargarna?",a="Vargarna jagades i Silverpine Forests fördärvade vildmark, ett område som är hårt drabbat av mörk magi, förruttnelse och en märklig förvridning som förändrar den lokala faunan.",al={"varifrån kommer vargarna","silverpine-vargar","var vargarna finns"}}},fx={["61543e32"]={q="Vad är Wolf Heart Samples?",a="Det här är vävnadsprover från fördärvade vargar, som har tagits till vara och konserverats. Till skillnad från vanliga djurrester har dessa hjärtan en ovanligt stark inre giftighet, så svår att den egentligen borde ha dödat bestarna medan de ännu levde.",al={"vad är wolf heart samples","föremålet wolf heart samples","wolf heart samples"}},["33618b83"]={q="Varifrån kommer Wolf Heart Samples?",a="De har beretts och delats upp av Apothecary Renferrel från de besmittade varghjärtan du samlade in åt hans forskning. Renferrel kände igen deras ovanliga egenskaper och lade undan just de här bitarna för att skickas direkt till hans kollegor i Undercity.",al={"varifrån kom wolf heart samples","vem har gjort wolf heart samples","wolf heart samples källa"}},["6a0e6447"]={q="Varför vill någon ha Wolf Heart Samples?",a="Apothecary Zinge och Royal Apothecary Society vill undersöka nya sorters gift. Det onaturliga giftet som genomströmmar proverna ger nya insikter om kraftfulla giftämnen, som apotekarna gärna vill isolera, testa och anpassa till sina egna dödliga blandningar.",al={"varför vill man ha wolf heart samples","vem vill ha wolf heart samples","varför vill zinge ha wolf heart samples"}}},fp="18,168,15.383.0,24.357.0,54.186.0,27.205.0,40.167.0,31.132.0"}
P.entries["item:wood-pulp"] = {n="Wood Pulp",s="Vid Bael Modan hjälper Wood Pulp dvärgarna att förbereda sina sprängladdningar. Dvärgstyrkorna som är stationerade i södra Barrens bär det som en absorberande grund för att stabilisera flytande sprängämnen.",h="Vid Bael Modan hjälper Wood Pulp dvärgarna att förbereda sina sprängladdningar.",kw={"bael modan","bael'dun","barrens","gann stonespire","nitroglycerin","ganns hämnd","sodium nitrate","wood pulp"},ang={["profession:Engineering"]="Ingenjörer vet att Wood Pulp kan absorbera nitroglycerin och ett nitratbaserat oxidationsmedel, vilket stabiliserar den flyktiga vätskan i hållbar dynamit.",["race:Tauren"]="Som tauren från Stonespire-stammen ser du inkräktarnas ammunition vändas mot Bael Modan, som rättvisa för förstörelsen av ditt förfädershem."},sec={{t="Ett flyktigt recept",b="Vid Bael Modan använder Ironforge-dvärgar jordförflyttningsmaskiner och kemiska sprängämnen för att bryta sig in på taurenfolkets urgamla jaktmarker. Flytande nitroglycerin är instabilt på egen hand, så dvärgarnas ingenjörer låter det sugas upp av porös Wood Pulp med Sodium Nitrate för att skapa stabila laddningar för utgrävning och strid. Gevärsskyttar, soldater och officerare bär buntar för sabotage och fältammunition."},{t="Vänt mot fästet",b="Efter att Prospector Khazgorm föll återfick Gann Stonespire dvärgarnas sprängscheman. Den fördrivna taurenkrigaren använder deras metoder mot inkräktarna som tränger in på hans stams marker. Från garnisonen i Bael'dun hämtar Gann Wood Pulp, nitroglycerin och nitrater för att tillverka en laddning som ska förstöra dvärgarnas flygmaskin vid Bael Modan."}},faq={{q="Vad används trämassa till vid Bael Modan?",a="Vid Bael Modan använder dvärgarnas ingenjörer Wood Pulp som absorberande grund för ammunition. De låter instabilt flytande nitroglycerin sugas upp av den, vilket gör sprängladdningarna säkrare för sabotörer att bära och hantera.",al={"varför har dvärgar trämassa","trämassans syfte","vad används trämassa till"}},{q="Vem bär trämassa i Barrens?",a="Dvärgstyrkor stationerade vid Bael Modan i södra Barrens bär Wood Pulp. Bland dem finns Bael'dun-soldater, gevärsskyttar, officerare och deras befälhavande lord, Cyrik Blackforge.",al={"var hittar man trämassa","vem släpper trämassa","trämassans plats"}},{q="Varför behöver Gann Stonespire trämassan?",a="Gann Stonespire använder Wood Pulp för att vända dvärgarnas destruktiva metoder mot dem. Enligt deras sprängscheman blandar han det med återvunnet nitroglycerin och Sodium Nitrate för att tillverka en laddning som ska förstöra dvärgarnas flygmaskin vid Bael Modan.",al={"vem vill ha trämassa","gann stonespire trämassa","varför samla trämassa"}},{q="Exploderar trämassa av sig själv?",a="Nej. Rå Wood Pulp består av sönderdelade träfibrer. Det blir farligt först när det kombineras med flyktiga kemikalier som nitroglycerin och ett oxidationsmedel som Sodium Nitrate.",al={"är trämassa explosiv","kan trämassa explodera"}}},fx={["1f614fe2"]={q="Vad är Wood Pulp?",a="Wood Pulp är bearbetade växtfibrer som dvärgarna i Bael Modan har vid sin utgrävningsplats. Ämnet är ofarligt i sig, men fungerar som en porös, absorberande stabilisator när det blandas med flyktiga vätskor som nitroglycerin. På så vis blir farliga kemikalier till hanterbara, fasta sprängämnen.",al={"vad är wood pulp","föremålet wood pulp","beskrivning av wood pulp"}},["1f0d889e"]={q="Var kommer Wood Pulp ifrån, och vem tillverkade det?",a="Den här massan tillverkas och lagerhålls av Ironforge-dvärgarna vid utgrävningen i Bael'dun. Soldater, gevärsskyttar och officerare stationerade vid Bael Modan bär knippen av den genom fästningen för att förse sprängningsarbetet och artilleriet med material.",al={"var kommer wood pulp ifrån","vem tillverkade wood pulp","wood pulp ursprung"}}},fp="9,195,17.376.0,23.357.1,41.196.0,37.176.0,45.264.0,33.167.0"}
P.entries["item:wooden-key"] = {n="Wooden Key",s="Wooden Key är en enkelt utskuren nyckel som bärs av de vansinniga uråldringar som strövar omkring i norra Ashenvale, nära gränsen till Felwood. Den låser upp en dold kista med en kvarleva från Dartol's Rod, en uråldrig relik från nattalverna.",h="Wooden Key är en enkelt utskuren nyckel som bärs av de vansinniga uråldringar som strövar omkring i norra...",kw={"ashenvale","crazed ancient","dartol's rod","felwood","iron shaft","shael'dryn","withered ancient","wooden key"},ang={["class:Druid"]="De förvridna uråldringarna som håller den här nyckeln visar hur den demoniska farsoten förgiftar Cenarionlundarna mellan Ashenvale och Felwood.",["race:NightElf"]="Det är sorgligt för varje stjärnornas barn att se Kalimdors älskade uråldringar drivas till vansinne och hålla förlorade reliker längs vägen till Felwood."},sec={{t="En nyckel i galna händer",b="Wooden Key bärs av Crazed Ancients och Withered Ancients som vandrar längs de skuggiga stigarna norr om Raynewood Retreat. Shael'dryn kände en gång de lokala trädandar, men beskriver nu hur deras natur har förvridits av fördärv. En av dem bär nyckeln till en kista med en del av Dartol's Rod."},{t="Att låsa upp staven",b="Dryaden Shael'dryn ber äventyrare att hämta den här nyckeln och öppna en gömd, sliten kista i en liten glänta väster om vägen till Felwood. Därinne ligger Iron Shaft, en av de viktiga delar som behövs för att återskapa Dartol's Rod och bekämpa det spridande fördärvet som förgiftar de heliga skogarna."}},faq={{q="Vad låser Wooden Key upp?",a="Wooden Key öppnar en sliten kista som står undangömd i en liten glänta väster om huvudvägen norrut mot Felwood. I kistan ligger Iron Shaft, en del som behövs för att återskapa Dartol's Rod.",al={"vad öppnar wooden key","wooden key kista","var använder man wooden key"}},{q="Vem bär Wooden Key?",a="Nyckeln bärs av Crazed Ancients och Withered Ancients som vandrar i skogarna norr om Raynewood Retreat, nära gränsen till Felwood.",al={"vem släpper wooden key","var hittar man wooden key","wooden key byte"}},{q="Varför har uråldringarna den här nyckeln?",a="Shael'dryn säger att en av de fördärvade trädandar nära Felwood bär nyckeln. Hon förklarar inte hur trädanden fick tag på den.",al={"varför har trädandar nyckeln","uråldrig nyckel bakgrund"}},{q="Vem skickar dig för att hämta Wooden Key?",a="Shael'dryn, en dryad som vårdar Moonwell of Purity i Ashenvale, ber äventyrare att hämta nyckeln som en del av försöket att återskapa Dartol's Rod.",al={"uppdragsgivare för wooden key","vem vill ha wooden key"}}},fx={ebbbe3a2={q="Vad är Wooden Key?",a="Wooden Key är en enkel, utsnidad nyckel som bärs av de korrumperade treants som strövar omkring i norra Ashenvale nära Felwood. Den utformades för att låsa in en gömd kista med en relik efter den avlidne Night Elf Dartol.",al={"information om wooden key","vad är wooden key","om wooden key"}},a6fc69e1={q="Varför vill Shael'dryn ha Wooden Key?",a="Shael'dryn behöver nyckeln så att du kan låsa upp den slitna kistan som gömts i en glänta nära gränsen till Felwood. Därinne finns en Iron Shaft, en viktig del som behövs för att sätta ihop Dartol's Rod igen och rena landet.",al={"varför behövs wooden key","varför hämta wooden key","varför vill man ha wooden key"}}},fp="10,161,18.255.0,17.257.1,32.168.0,27.122.0,34.137.0,41.150.0"}
P.entries["item:worn-parchment"] = {n="Worn Parchment",s="Worn Parchments är fragment av rituella skrifter som bärs av kultister i läger runt Tower of Althalaxx i norra Darkshore. Spejare har samlat in de trasiga bitarna, som ger de första konkreta ledtrådarna om den illvilliga sekt som samlas i ruinerna.",h="Worn Parchments är fragment av rituella skrifter som bärs av kultister i läger runt Tower of Althalaxx i...",kw={"althalaxx","balthule shadowstrike","dark strand","darkshore","fanatiker","worn parchment"},ang={["class:Warlock"]="Skrifterna som bärs av Dark Strand avslöjar en organiserad sammanslutning som verkar i hemlighet på nattalvernas marker och brukar demonisk magi och skuggmagi utom synhåll för både Alliance och Horde.",["race:NightElf"]="Mörka magiker och demonisk fördärvskraft nära forntida ruiner som Althalaxx utgör en grov skändning av Darkshores heliga vildmark."},sec={{t="Fragment av en ondskefull plan",b="Längs Darkshores dimhöljda kust i norr har mörka magiker och deras fanatiska anhängare tagit över den raserade Tower of Althalaxx. Fotsoldaterna som patrullerar området utanför, kända som Dark Strand Fanatics, bär på bitar av slitet pergament bland sina personliga tillhörigheter. En ensam bit ser inte ut att vara mer än fragmentariska klotter och esoteriska symboler, men när flera fragment fogas samman avslöjas en tidigare okänd organisation: Cult of the Dark Strand."},{t="Avslöja kulten",b="Balthule Shadowstrike, en spejare som bevakar tornet från en närbelägen utsiktsplats, använder de insamlade pergamenten för att bedöma hotet åt Delgren the Purifier och vaktposterna i Auberdine. När texterna fogas samman bekräftas det att häxmästarna i tornet inte är ensamma utstötta, utan en organiserad kult vars planer förblir okända."}},faq={{q="Vem bär på de slitna pergamenten?",a="Pergamenten bärs av Dark Strand Fanatics, kultens fotsoldater som slagit läger utanför, runt Tower of Althalaxxs omkrets i norra Darkshore.",al={"vem släpper worn parchment","var får man tag på worn parchment","källa till worn parchment"}},{q="Vad står det på pergamenten?",a="Var för sig är de kryptiska fragment av rituella anteckningar och order. När de samlas in och dechiffreras av Balthule Shadowstrike avslöjar de Cult of the Dark Strands namn och existens.",al={"vad står det på worn parchment","texten på worn parchment","pergamentets betydelse"}},{q="Varför samlar Balthule Shadowstrike in dem?",a="Delgren the Purifier gav Balthule i uppdrag att hålla uppsikt över Tower of Althalaxx. Han behöver skrifterna för att ta reda på varför häxmästare har samlats i ruinerna och bedöma faran för Darkshore innan han rapporterar tillbaka.",al={"vem vill ha worn parchment","balthules uppdrag","varför samla in pergament"}},{q="Vad är Cult of the Dark Strand?",a="Det är en hemlighetsfull sammanslutning av kultister och häxmästare som verkar från Althalaxxs ruiner. Inte ens erfarna spejare som Balthule Shadowstrike hade stött på orden tidigare, innan de fann skrifterna.",al={"kulten dark strand","vilka är dark strand","cult of dark strand"}}},fx={["83151644"]={q="Vad är Worn Parchment?",a="De här slitna pergamenten är skrivna fragment och skriftrullar som bärs av Dark Strand-kultisterna, som slagit läger kring Tower of Althalaxx i norra Darkshore. När de sätts ihop avslöjar innehållet de skuggaktiga förehavandena och närvaron av en häxmästarsekt som kallas Cult of the Dark Strand.",al={"vad är worn parchment","worn parchment bakgrund","information om worn parchment"}},["4385c03d"]={q="Var kommer Worn Parchment ifrån, och vem tillverkade det?",a="Pergamenten kommer från Dark Strand Fanatics och häxmästare som har samlats kring ruinerna av Tower of Althalaxx. Kultisterna bär de här skrivna fragmenten som en del av sin kommunikation och sina mystiska riter, men den exakta upphovspersonen till varje skriftrulle är okänd.",al={"var kommer worn parchment ifrån","vem tillverkade worn parchment","vem skrev worn parchment"}}},fp="14,114,28.404.0,18.313.1,34.152.0,34.183.0,45.201.0,36.221.0"}
P.entries["item:worn-stone-token"] = {n="Worn Stone Token",s="Worn Stone Tokens är små magiska talismaner som bärs av personal och magiker med anknytning till Dalaran i Alterac Mountains. Även om deras omgivande magi till stor del har falnat, skapades de för att hjälpa Kirin Tor att binda och befalla elementartjänare.",h="Worn Stone Tokens är små magiska talismaner som bärs av personal och magiker med anknytning till Dalaran i...",kw={"alterac mountains","dalaran","elementarväsen","keeper bel'varil","magus voidglare","stenpolletter","tarren mill","worn stone token"},ang={["class:Mage"]="Magiker känner igen dessa polletter som de praktiska fokusföremål Kirin Tor använder för att hålla frammanade elementarväsen stabila och lydiga ute i fält.",["faction:Horde"]="Att säkra dessa polletter hjälper De övergivna i Tarren Mill att studera de fientliga styrkorna från Kirin Tor i Alteracs magiska försvar och metoder."},sec={{t="Polletter för elementarmästerskap",b="Magikerna i Dalaran har länge haft en imponerande makt över elementarväsen och använt särskilda talismaner för att kuva dessa utomvärldsliga varelser. Worn Stone Tokens är uttömda eller förbrukade versioner av dessa redskap. De bärs inte bara av teurger och besvärjare, utan även av arbetare och vakter från Dalaran som är stationerade kring ruinerna och interneringslägren i Alterac. Det visar hur djupt elementarbindning är invävd i Dalarans dagliga verksamhet."},{t="De övergivnas nyfikenhet",b="Från sin utpost i Tarren Mill håller De övergivna noga uppsikt över de närbelägna trollkarlarna. Magus Voidglare ville få tag på exemplar av dessa polletter för att tyda Dalarans metoder för att förslava elementarväsen. Keeper Bel'varil ger agenter i uppdrag att först samla in slitna, kraftlösa polletter, så att Magus kan analysera de grundläggande förtrollningsteknikerna på ett säkert sätt innan experiment med kraftfullare, instabila kanaler inleds."}},faq={{q="Vad användes polletterna till?",a="Trollkarlarna i Dalaran använder dessa magiska stenpolletter för att befalla och binda elementarväsen som tillkallats från andra riken, så att de tjänar som arbetare, vakter och försvarare.",al={"worn stone token användning","vad är stenpolletter","varför bär dalaran polletter"}},{q="Varför beskrivs polletterna som slitna?",a="Deras aktiva förtrollningar har falnat med tiden och efter flitig användning. Keeper Bel'varil anser att dessa kraftlösa exemplar är säkrare för Magus Voidglare att börja forska på Dalarans bindningsriter med.",al={"varför slitna","är polletterna magiska","kraftlösa polletter"}},{q="Vilka bär på polletterna?",a="De hittas på olika personer från Dalaran som arbetar i södra Alterac Mountains, från högt uppsatta besvärjare och teurger till vanliga arbetare, sköldvakter och Warden Belamoore vid interneringslägret.",al={"vem släpper worn stone tokens","var hittar man polletter","dalaran pollettbyte"}},{q="Varför vill De övergivna ha dem?",a="Magus Voidglare vill studera Dalarans magiska tekniker för att kontrollera elementarväsen och avslöja hemligheterna bakom deras konster att tillkalla och kuva dem.",al={"varför vill belvaril ha polletter","magus voidglare polletter"}}},fx={["4cdbd814"]={q="Vad är en Worn Stone Token?",a="En Worn Stone Token är en bleknad magisk artefakt som tillverkats av magikerna i Dalaran. Dessa förtrollade stenar fungerar som magiska redskap för att binda, befalla och kontrollera elementartjänare som åkallats från andra dimensioner. Med tiden eller efter omfattande hantering har deras inneboende magi mattats av och blivit overksam, men de bevarar fortfarande de strukturella hemligheterna bakom Dalarans elementarkonst.",al={"vad är worn stone token","worn stone token","stone tokens"}},["2e06b1f4"]={q="Var kommer Worn Stone Tokens ifrån, och vem tillverkade dem?",a="Brickorna tillverkas av trollkarlar och konstnärer i Dalaran, en magokrati känd för sin skicklighet inom extradimensionell magi. Du hittar dem hos Dalarans styrkor som är stationerade runtom i Alterac Mountains, däribland åkallare, teurger, sköldvakter, arbetare och Warden Belamoore vid de närliggande interneringslägren.",al={"vem tillverkade worn stone token","stone tokens ursprung","var kommer stone tokens ifrån"}}},fp="16,188,27.379.0,18.329.0,32.156.0,37.186.0,25.188.0,32.122.0"}
P.entries["item:woven-wand"] = {n="Woven Wand",s="Woven Wand är en unik förtrollad relik som för länge sedan skapades av tre lärlingar i Dalaran som en ed om broderskap. Efter Lordaerons fall och bittra svek mellan dess skapare gömdes staven i Fenris Keep, innan den åter dök upp i de Fördömdas händer.",h="Woven Wand är en unik förtrollad relik som för länge sedan skapades av tre lärlingar i Dalaran som en ed om...",kw={"alaric","bethor iceshard","dalaran","fenris keep","gunther arcanus","magic quarter","thule ravenclaw","woven wand"},ang={["class:Mage"]="Woven Wand belyser Dalarans lärlingars gamla traditioner. De experimenterade ofta med att förena personliga kanaler för att fokusera sin samlade arkana potential.",["race:Undead"]="Artefakten påminner bitterljuvt om dödliga liv som gått förlorade till Scourge och förenar minnena av två överlevande Fördömda i kampen mot deras fallna forna kamrats vansinne."},sec={{t="Den dolda nischen",b="Även om Thule kom att avsky stavens sentimentalitet efter att ha vänt sig till mörkret, kunde han aldrig förmå sig att förstöra den eller överlämna den till sina forna kamrater. I stället tog han artefakten med sig till Silverpine Forest och gömde den djupt inne i en nisch i Fenris Keep. Många år senare, när Thules tillhåll hade intagits och hans tjänare Alaric visade hordens agenter till gömstället, återfanns reliken oskadd. Nekromantikern hade aldrig åkallat dess slumrande förtrollningar, och till slut överlämnades staven till Bethor Iceshard i Magic Quarter i Undercity."},{t="Ett band som brast",b="På den tiden då Dalaran fortfarande utbildade nordens unga magiker flätade tre blivande trollkarlar, Bethor Iceshard, Gunther Arcanus och Thule Ravenclaw, samman sina lärlingsstavar till en enda talisman. Denna Woven Wand fungerade både som en kanal för deras samlade magiska kraft och som en symbol för deras varaktiga vänskap. Deras gemenskap krossades för alltid när Scourge svepte genom Lordaeron. Thule Ravenclaw valde att svära trohet till Lich King och vände sig till den mörka nekromantin. Samtidigt tog Plague of Undeath både Bethor och Gunther, och deras band till Dalaran klipptes till sist helt av."}},faq={{q="Vem skapade Woven Wand?",a="Staven skapades gemensamt av tre lärlingar i Dalaran: Bethor Iceshard, Gunther Arcanus och Thule Ravenclaw. De slog samman sina tre separata lärlingsstavar till en gemensam artefakt som symbol för deras vänskap.",al={"vem skapade woven wand","woven wands skapare","stavens skapare"}},{q="Varför gömdes staven i Fenris Keep?",a="Efter att Thule förrådde sina kollegor för att tjäna Lich King började han avsky artefakten och bandet den symboliserade. Men han kunde inte göra sig av med den eller förstöra den, så han gömde den i en hemlig nisch i sitt tillhåll i Fenris Keep.",al={"varför gömde thule staven","var hittades woven wand","varför fenris keep"}},{q="Varför trodde Bethor Iceshard att staven var förlorad?",a="Bethor antog att staven var förlorad för alltid när deras vänskap föll samman och pesten härjade landet. Han påpekade också att Thule aldrig vågade åkalla dess magiska krafter. Om Thule hade använt den skulle Bethor ha känt kraftens flöde genom deras kvarvarande magiska band.",al={"vad säger bethor om staven","bethors reaktion på staven"}},{q="Hur återfanns staven?",a="Äventyrare från Horden anföll Fenris Keep för att besegra Thule Ravenclaw. Med vägledning från Ravenclaws forna tjänare Alarics avhuggna, fortfarande talande huvud hittade de den dolda nischen med staven och förde ut den ur ruinerna.",al={"vem hittade staven","hur får man woven wand"}}},fx={de7c3f0d={q="Vad är Woven Wand?",a="Woven Wand är en förtrollad relik som vävts samman av lärlingstavlorna från tre magiker i Dalaran: Thule Ravenclaw, Bethor Iceshard och Gunther Arcanus. Den skapades som en symbol för deras tidiga vänskap och förenar deras magiska hantverk i ett enda redskap. Bandet brast när Thule svor sin trohet till Scourge och hans följeslagare föll offer för pesten.",al={"vad är woven wand","woven wand bakgrund","woven wand"}},a3970439={q="Varför vill Bethor Iceshard ha Woven Wand?",a="Bethor Iceshard trodde att staven var förlorad för alltid när deras gemenskap upplöstes och Thule Ravenclaw gick över till Lich King. Utöver sitt känslomässiga värde från deras tid som dödliga studenter i Dalaran rymmer staven vilande magisk kraft som Thule aldrig använde. Bethor fruktar att den ska hamna i Scourges händer och vill därför säkra den.",al={"varför vill bethor ha woven wand","varför ska bethor få staven","vem vill ha woven wand"}}},fp="10,185,17.501.1,15.439.1,27.162.1,39.206.0,48.212.0,27.152.1"}
P.entries["item:xavian-water-sample"] = {n="Xavian Water Sample",s="En flaska med rent, magiskt laddat vatten från foten av det högsta vattenfallet i Xavians forntida alvruiner. Magiker från Horde i Orgrimmar söker efter det för att utforska de latenta arkana krafter som bevarats i Ashenvales äldsta heliga platser.",h="En flaska med rent, magiskt laddat vatten från foten av det högsta vattenfallet i Xavians forntida alvruiner.",kw={"ashenvale","deino","orgrimmar","satyr","splintertree","vattenprov","xavian"},ang={["class:Mage"]="Att hämta provet är ett viktigt fältprov för magiker från Horde. Det prövar deras förmåga att tygla naturliga källor till arkana krafter och ta sig fram i fientlig, demonbesmittad terräng.",["faction:Horde"]="När Horde stärker sin närvaro i Ashenvale kring Splintertree Post ger utvinningen av Xavians forntida arkana resurser Orgrimmars lärda värdefull kunskap."},sec={{t="Den forntida stadens vatten",b="Xavian är en mytomspunnen forntida alvstad, och berättelser om dess gamla kunskap är välkända bland lärda. Även i ruiner sägs dess vatten rymma väldiga magiska krafter. Deino, en lärare i arkana konster i Orgrimmar, ger blivande magiker i uppdrag att färdas djupt in i Ashenvale och hämta ett färskt prov direkt från pölen nedanför Xavians högsta vattenfall. För att få tag på det måste de trotsa farlig mark, eftersom ruinerna nu vaktas hårt av korrumperade satyrer som är fientliga mot alla magiker som lägger sig i."}},faq={{q="Var samlas vattenprovet in?",a="Det samlas in genom att fylla Deino's Flask vid pölen nedanför det högsta vattenfallet i ruinerna av Xavian. Platsen ligger i nordöstra Ashenvale, norrut förbi sjöarna bortom Splintertree Post och Satyrnaar.",al={"var hittar jag xavians vatten","var ligger xavians vattenfall","hur får jag tag på xavians vattenprov"}},{q="Varför vill Deino ha det här vattnet?",a="Deino är en lärare i arkana konster som håller till i Valley of Spirits i Orgrimmar. Hon studerar kraftfulla och ovanliga källor till magi för att undervisa unga utövare från Horde och söker den uråldriga magiska essens som bevarats i Xavians orörda vatten.",al={"vem vill ha xavians vatten","varför samla vatten från xavian","deinos syfte"}},{q="Vilka hot vaktar Xavians vatten?",a="De forntida alvruinerna bebos av satyrer, demoniska varelser som hatar inkräktare och försvarar sitt revir våldsamt mot nyfikna magiker. Vattendragen i närheten är också hem åt aggressiva bestar, som flodkrokolisker.",al={"vilka fiender finns i xavian","vem bor i xavian","faror i xavian"}},{q="Vad händer när provet återlämnas till Orgrimmar?",a="Deino börjar genast studera provets arkana egenskaper och använder den insamlade magin för att föra sin forskning framåt och hjälpa till med utbildningen av magiker från Horde.",al={"lämna in xavians vatten","vad används vattnet till"}}},fx={ff7d6737={q="Vad är Xavian Water Sample?",a="Det är en flaska fylld med vatten som hämtats direkt vid foten av det högsta vattenfallet i den förstörda staden Xavian. Vattnet i den här uråldriga Night Elf-bosättningen sägs ha väldiga magiska krafter och väcker Horde-lärdas intensiva nyfikenhet.",al={"vad är xavian water sample","xavian water sample","flaska med vatten från xavian"}},["27a4db96"]={q="Var kommer Xavian Water Sample ifrån, och vem tillverkade det?",a="Vattnet hämtas från det naturliga vattenfallet i hjärtat av Xavian, en uråldrig alvstad djupt inne i östra Ashenvale. Ingen dödlig hantverkare skapade det. I stället rinner det rena vattnet genom ruiner genomsyrade av uråldrig Night Elf-magi och den kvardröjande korruptionen från satyrerna som nu gör anspråk på området.",al={"var kommer vatten från xavian ifrån","vem tillverkade xavian water sample","vatten från xavian källa"}}},fp="19,166,26.432.0,36.181.0,31.235.0,40.178.0,54.183.0"}
P.entries["item:young-crocolisk-skin"] = {n="Young Crocolisk Skin",s="Young Crocolisk Skin är ett smidigt reptilskinn från unga krokolisker i Wetlands. Lokala garvare som James Halloran i Menethil Harbor värdesätter skinnen, som bereds och skeppas till hamnar runt Azeroth.",h="Young Crocolisk Skin är ett smidigt reptilskinn från unga krokolisker i Wetlands.",kw={"krokolisk","james halloran","läder","menethil harbor","skinn","garvning","wetlands"},ang={["class:Hunter"]="Att smyga längs Wetlands leriga stränder på jakt efter krokoliskskinn är rutin för spårare som förser den livliga läderhandeln i Menethil Harbor."},sec={{t="Garvning och handel i träskmarkerna",b="Menethil Harbor är ett livligt handelscentrum längs Khaz Modans västkust och skeppar varor från träskmarkerna till avlägsna hamnar. Bland stadens mest lönsamma exportvaror finns de beredda skinnen som garvas av hamnens lokale garvare, James Halloran. Fullvuxna krokolisker ger tjocka, hårda fjäll, medan deras ungar har mjukare och betydligt mer lättarbetat skinn. Eftersom skinnen från de unga djuren är ömtåliga och efterfrågade förlitar sig Halloran på lokala jägare och resenärer på genomresa, som får leta i de sumpiga markerna strax utanför staden och hålla hans garvställ fyllda."}},faq={{q="Varför vill James Halloran särskilt ha skinn från unga krokolisker?",a="Unga krokolisker ger betydligt mjukare skinn än fullvuxna djur. Vuxna bestar har tjocka, styva fjäll, medan ungdjurens skinn är mycket lättare att bearbeta och bereda till smidiga produkter som är efterfrågade längs sjöfartslederna.",al={"varför skinn från unga krokolisker","hallorans skinn","varför mjuka skinn"}},{q="Var finns unga krokolisker?",a="Young Wetlands Crocolisks lever i vattendragen, kärren och träskmarkerna strax utanför Menethil Harbor i västra Wetlands.",al={"var finns unga krokolisker","var hittar man unga krokodiler","krokolisker i wetlands"}},{q="Vem mer jagar krokoliskerna åt hamnen?",a="En lokal jägare vid namn Einar brukar komma med krokoliskhudar till James Hallorans läderverksamhet, men efterfrågan överstiger ofta vad en enda spårare kan leverera.",al={"vem jagar krokolisker","jägaren einar","jägare och garvare i menethil"}},{q="Vart skeppas de beredda skinnen?",a="Hallorans färdiga varor lastas på handelsfartyg som lämnar Menethil Harbor och går till större hamnar och marknader i Eastern Kingdoms och bortom.",al={"handel med krokoliskläder","skinnexport från menethil","vart skickas skinnen"}}},fx={["2363e64c"]={q="Vad är Young Crocolisk Skin?",a="Det är det råa, smidiga skinnet från unga crocolisks som strövar omkring i Wetlands träskmarker. Eftersom de unga bestarna ännu inte har utvecklat de tjocka, styva fjällen hos fullvuxna individer är deras skinn mycket smidigare och eftertraktat av lokala läderarbetare.",al={"vad är young crocolisk skin","föremålet young croc skin","vad betyder crocolisk skin"}},a9554702={q="Var kommer Young Crocolisk Skin ifrån?",a="Skinnen kommer direkt från de unga crocolisks som lever i de blöta träskmarkerna kring Menethil Harbor. De är inte tillverkade varor, utan naturliga hudar som flås från jagade bestar innan de garvas till fint läder.",al={"young crocolisk skin källa","var får man tag på young crocolisk skin","vem tillverkade young crocolisk skin"}}},fp="20,169,32.472.0,70.175.0,36.120.0,47.148.0,36.153.0"}
P.entries["item:yowler-s-paw"] = {n="Yowler's Paw",s="Yowler's Paw är den makabra trofén som tagits från Yowler, den våldsamma flockledaren bland gnollerna som hotar kullarna ovanför Lakeshire. När den överlämnas till stadens hantverkare Verner Osgood blir den ett obestridligt bevis på att besten som ledde de lokala gnollflockarna har fällts.",h="Yowler's Paw är den makabra trofén som tagits från Yowler, den våldsamma flockledaren bland gnollerna som...",kw={"gnollarnas flockledare","tjut i kullarna","lakeshire","gnoll i redridge","redridge mountains","verner osgood","yowler","yowler's paw"},ang={["class:Hunter"]="Att spåra upp alfahanen bland gnollerna i Redridge och ta hans tass sätter färdigheter i vildmarksspårning och besthantering på prov mot ett farligt rovdjur.",["faction:Alliance"]="Att besegra Yowler och återta hans tass bidrar till att stabilisera Redridge Mountains, när Stormwinds militär är alltför hårt ansatt för att skydda sin egen östra gräns."},sec={{t="Flockledarens trofé",b="Gnollerna i Redridge har länge terroriserat höjderna kring Lake Everstill, och deras blodisande tjut ekar ner mot samhället Lakeshire. Ingen av dem är mer fruktad än Yowler, den hänsynslösa alfahanen som driver deras expansion. Eftersom gnollöron och -tassar brukar användas som bevis för utförda dusörer i människornas områden ber Verner Osgood modiga äventyrare att hämta Yowler's Paw. Att hugga av den markerar inte bara slutet för ett ovanligt listigt rovdjur, utan är också ett medvetet försök att slå sönder befälsordningen bland hans oorganiserade anhängare."},{t="En stad lämnad åt sig själv",b="Att återbörda Yowler's Paw visar hur desperat situationen i Lakeshire är. Stormwind-armén är helt upptagen med hotet från Blackrock-orcherna som befäst sig kring Stonewatch Keep, så stadens myndigheter och invånare måste anlita kringresande legoknektar för att försvara sig. Utan regelbundna kungliga garnisoner är bevis som Yowler's Paw det enda sättet för nybyggare som Verner Osgood att se till att de lokala vägarna förblir någorlunda säkra för handel och resor."}},faq={{q="Vem ber om Yowler's Paw?",a="Verner Osgood, en framstående handelsman och invånare i Lakeshire, ber om tassen. Han vill ha bevis på att alfagnollen som terroriserar kullarna har oskadliggjorts för gott.",al={"vem vill ha yowler's paw","verner osgood tassuppdrag","lämna in yowler's paw"}},{q="Vem är Yowler?",a="Yowler är den fruktade ledaren för gnollflockarna i Redridge. Till skillnad från vanliga blandrashundar bland gnollerna har han den råstyrka och list som krävs för att samla flera flockar, vilket gör honom till ett akut hot mot invånarna i närheten.",al={"vem är yowler","yowlers bakgrund","gnollernas ledare i redridge"}},{q="Varför förlitar sig Lakeshire på dusörer i stället för soldater från Stormwind?",a="Stormwind-armén är överbelastad med striderna mot Blackrock-orcherna, som har befäst Stonewatch Keep i östra Redridge. Eftersom inga förstärkningar finns att avvara måste invånare som Verner Osgood förlita sig på fristående äventyrare för att jaga hot som Yowler.",al={"varför finns inga vakter från stormwind","var är stormwind-armén","varför anlitar verner legoknektar"}},{q="Vad händer när Yowler dödas?",a="När Yowler dödas bryts ledarskapet som håller de aggressiva gnollerna samman. Hans flock skingras i vildmarken, vilket ger Lakeshires invånare ett tillfälligt andrum.",al={"vad händer efter att yowler dör","gnollerna efter yowler","slutet på tjuten i kullarna"}}},fx={["5e9f7255"]={q="Vad är Yowler's Paw?",a="Yowler's Paw är den avhuggna tassen från gnollflockens ledare i Redridge, tagen som fysiskt bevis på hans död. Verner Osgood i Lakeshire ber äventyrare att jaga rätt på den vilda alfahanen och hämta tassen för att bekräfta att besten äntligen har dödats.",al={"vad är yowlers paw","föremålet yowler paw","yowlers paw"}},c7fb7fcc={q="Var kommer Yowler's Paw ifrån?",a="Det är ingen tillverkad sak, utan Yowler själv avhuggna lem. Yowler leder de aggressiva gnollerna som strövar omkring på kullarna ovanför Lakeshire. Han är mycket vildare och slugare än de vanliga byrackor som hotar Redridge Mountains.",al={"var får man tag på yowlers paw","vem tillverkade yowlers paw","yowler paw ursprung"}},["034bdc4c"]={q="Varför vill Verner Osgood ha Yowler's Paw?",a="Verner Osgood kräver tassen som obestridligt bevis på att den hotfulla gnollledaren är död. Stormwinds armé är hårt ansatt i striderna mot Blackrock-orcherna, så Lakeshire är beroende av kringresande äventyrare för att hålla de lokala rovdjuren nere. Verner kräver bevis innan han belönar dig.",al={"varför vill man ha yowlers paw","varför vill verner ha yowlers paw","yowler paw belöning"}}},fp="12,155,25.445.0,22.398.0,26.181.0,14.148.0,66.225.0,35.170.0"}
P.entries["item:zalazane-s-head"] = {n="Zalazane's Head",s="Master Gadrin väntar på bevis för att Zalazane har fallit. Darkspear vill bli av med häxdoktorn som drev bort dem från Echo Isles.",h="Master Gadrin väntar på bevis för att Zalazane har fallit.",kw={"darkspear","echo isles","gadrin","förhäxat troll","sen'jin village","voodootroll","zalazane","zalazane's head"},ang={["faction:Horde"]="Som medlem av Horde hjälper du till att säkra Durotars sydkust genom att döda Zalazane och hindra hans mörka magi från att undergräva Thralls nygrundade territorier.",["race:Troll"]="Som Darkspeartroll är det en personlig handling av hämnd och rättvisa att ta Zalazanes huvud från förrädaren som drev ditt folk i landsflykt och förslavade dina bröder."},sec={{t="Bevis på förrädarens fall",b="Master Gadrin ber om bevis för att Zalazane är död. Häxdoktorn förrådde Darkspear och tog kontroll över deras öhem med besvärjelser som förslavar sinnet. Hans magi drev Vol'jins folk till Durotars stränder. Från Echo Isles skickar Zalazane fortfarande förhäxade slavar över vattnet för att ta fler offer. Sen'jin Village behöver bevis för att hans välde har upphört. När Zalazanes avhuggna huvud återlämnas bekräftas hans nederlag, och den fördrivna stammen får en viss ro och hopp om att en dag återta sina stulna öar."}},faq={{q="Vem ber om Zalazane's Head?",a="Master Gadrin, häxdoktorn i Sen'jin Village på Durotars sydkust, ber om Zalazane's Head som bevis för att Zalazane har dödats.",al={"vem vill ha zalazanes huvud","zalazanes uppdragsgivare","gadrin zalazane"}},{q="Varför blev Zalazane måltavla?",a="Zalazane var en gång en respekterad trollkarl bland Darkspear. Hans maktbegär fick honom att förslava sina fränder med sinneskontrollerande magi, driva stammen från Echo Isles och plundra fastlandet efter fler Darkspear att binda som slavar.",al={"varför döda zalazane","vad gjorde zalazane","zalazanes historia"}},{q="Var finns Zalazane?",a="Zalazane håller till på den största av Echo Isles, utanför Durotars sydöstra kust. Förhäxade voodootroll som är bundna att tjäna honom omger honom.",al={"var finns zalazane","zalazanes plats","zalazane på echo isles"}},{q="Återtar man Echo Isles genom att ta med huvudet?",a="När Zalazane dödas upphör det omedelbara hotet från hans räder, och Sen'jin Village får en viss lättnad. Men Echo Isles är fortfarande farliga och fulla av kvarvarande voodooslavar. Darkspear har fortfarande huvuddelen av sitt fäste på fastlandet.",al={"återtar trollen echo isles","är echo isles återtagna","är echo isles säkra"}}},fx={a9dad833={q="Vad är Zalazane's Head?",a="Det är det avhuggna huvudet från häxdoktorn Zalazane, taget efter att han besegrats på Echo Isles. Det är mer än en hemsk trofé. Det tjänar som obestridligt bevis på att den förrädiske trollkarlen som svek Darkspear-stammen och drev bort dem från deras öhem äntligen har dödats.",al={"vad är zalazane head","vad är zalazanes head","föremålet zalazane head"}},c704c705={q="Var kommer Zalazane's Head ifrån?",a="Det kommer direkt från den förrädiske häxdoktorn Zalazane själv. Du tar det efter att ha besegrat honom vid hans läger på den största av Echo Isles. Det tillverkades inte, utan togs med våld för att sätta stopp för hans förslavning av andra Darkspear-troll.",al={"vem tillverkade zalazane head","var får man tag på zalazanes head","zalazanes head ursprung"}}},fp="15,136,26.524.0,29.143.0,26.232.0,24.143.0,46.223.0"}
P.entries["item:zamah-s-note"] = {n="Zamah's Note",s="Zamah's Note är ett skriftligt meddelande som Zamah skickat från Thunder Bluff över Great Sea till Apothecary Lydon i Tarren Mill. Det innehåller en brådskande begäran om en alkemisk brygd som kan hantera Venture Company i Stonetalon Mountains utan att ta till direkt blodsutgjutelse.",h="Zamah's Note är ett skriftligt meddelande som Zamah skickat från Thunder Bluff över Great Sea till Apothecary...",kw={"hillsbrad foothills","lydon","stonetalon mountains","tarren mill","thunder bluff","undercity","venture company","zamah"},ang={["faction:Horde"]="Brevets leverans visar hur logistiskt samarbete och gemensamma resurser knyter samman Hordens avlägsna huvudstäder i Kalimdor och Eastern Kingdoms.",["race:Undead"]="Meddelandet visar hur externa allierade i allt högre grad förlitar sig på Royal Apothecary Societys specialiserade kemikunskaper för att lösa komplexa kriser."},sec={{t="En vädjan över Great Sea",b="Venture Companys verksamhet har slagit djupa rötter i Stonetalon Mountains. Goblinerna skövlar skogarna och river upp den heliga marken. Zamah söker en specialiserad lösning för att driva bort dem utan att utlösa en fullständig massaker och vänder sig därför till Forsaken Royal Apothecary Societys expertis. I brevet beskriver hon det akuta läget i Stonetalon för sin kollega Apothecary Lydon, som befinner sig långt borta i Tarren Mill, i Hillsbrad Foothills i Lordaeron."},{t="Alkemistkontakter",b="Det förseglade meddelandet måste färdas långt över kontinenterna. Resenärer från Kalimdor tar zeppelinare till Undercity och fortsätter söderut genom Silverpine Forest till Hillsbrad. När Lydon tar emot Zamahs meddelande väcker hennes särskilda krav genast hans intresse. Han är stolt över att ha fått en hälsning från andra sidan havet och förbereder sig på att ta fram en alkemisk lösning på goblinernas problem."}},faq={{q="Vad är Zamah's Note?",a="Det är ett förseglat brev skrivet av Zamah i Thunder Bluff och adresserat till Apothecary Lydon i Tarren Mill. Hon ber om en alkemisk formel för att få bort Venture Company från Stonetalon.",al={"vad är det här för föremål","zamahs brev","brev till lydon"}},{q="Varför behöver Zamah hjälp från Tarren Mill?",a="Zamah söker en ovanlig, blodlös lösning för att fördriva goblinerna som härjar i Stonetalon. Hon kontaktar Apothecary Lydon eftersom Forsaken-alkemisterna har specialiserade kemiska brygder för sådana diskreta störningar.",al={"varför skicka till hillsbrad","varför kontakta lydon","varför tarren mill"}},{q="Vart ska brevet levereras?",a="Det ska föras till Apothecary Lydon, som bor i den Forsaken-kontrollerade staden Tarren Mill i Hillsbrad Foothills i Lordaeron.",al={"vem får brevet","lämna in zamahs brev","vart ska jag ta brevet"}},{q="Vilka är Venture Company som nämns i brevet?",a="Venture Company är ett hänsynslöst gruv- och skogsbolag som drivs av gobliner. Det är ökänt för att kalhugga skogar, exploatera naturresurser och förorena marker över hela Kalimdor, däribland Stonetalon Mountains heliga toppar.",al={"venture company i stonetalon","vilka är venture company","venture company"}}},fx={c24d4d7f={q="Var kommer Zamah's Note ifrån, och vem skrev den?",a="Brevet skrevs av Zamah, en Forsaken som bor i Thunder Bluff. Hon oroar sig över Venture Companys fortsatta exploatering och förstörelse i Stonetalon Mountains och skrev brevet för att nå en betrodd kollega i Lordaeron på andra sidan havet.",al={"vem skrev zamahs note","varifrån kommer zamahs note","vem tillverkade zamahs note"}},["6846e14b"]={q="Varför vill Apothecary Lydon ha Zamah's Note?",a="Apothecary Lydon behöver brevet eftersom det beskriver Zamahs specifika önskemål om en alkemisk lösning mot Venture Company. Zamah vill ha en extrem, blodlös metod för att driva bort The Defilers från Stonetalon, och brevet anger hennes exakta krav så att Lydon kan förbereda rätt brygd.",al={"varför vill lydon ha brevet","varför vill man ha zamahs note","syftet med zamahs note"}}},fp="12,191,27.383.0,22.323.0,21.167.0,42.180.0,41.93.0,49.208.0"}
P.entries["item:zargh-s-meats"] = {n="Zargh's Meats",s="Vid The Crossroads tillagar Zargh färskt kött åt Gryshka i Orgrimmar. Paketet ger unga Horde-resenärer en anledning att lära sig vindryttarleden.",h="Vid The Crossroads tillagar Zargh färskt kött åt Gryshka i Orgrimmar.",kw={"the crossroads","devrak","gryshka","kött","orgrimmar","valley of strength","vindryttare","zargh"},ang={["profession:Cooking"]="Gryshka uppskattar de här färska köttbitarna. De visar orcernas förkärlek för sällsynt kött, lätt tillagat och hämtat direkt från The Barrens vilda bestar.",["race:Orc"]="Som orc får du genom att bära Zarghs köttbitar till Gryshka lära känna Valley of Strength, hjärtat i din huvudstad, och behovet av att resa med wyvern genom luften."},sec={{t="En kurirs last",b="Zargh, en orcisk slaktare och jägare vid The Crossroads i The Barrens, tillagar färska köttbitar åt Gryshka, värdshusvärden i Orgrimmars Valley of Strength. Hetta över savannerna kan snabbt förstöra färskt viltkött, så paketet skickas med kurirer till rastplatsen vid The Crossroads. Vindryttarmästaren Devrak ordnar en wyvernflygning till Orgrimmars Skytower och besparar resenärerna den långa färden landvägen genom Durotar."},{t="Vägen till hjärtat",b="Zarghs leverans förmedlar en personlig känsla tillsammans med provianten. När Gryshka tar emot köttet känner hon igen Zarghs förmåga att vinna en dams gunst med förstklassigt viltkött. Hon ser fram emot att tillaga köttbitarna åt värdshusets stamgäster och besökare. För nyanlända orciska och trolliska resenärer är leveransen en introduktion till långväga flygresor mellan Hordens bosättningar på Kalimdor."}},faq={{q="Vem tillredde Zargh's Meats?",a="Zargh, en orcisk slaktare och jägare vid The Crossroads i The Barrens, tillagar och packar köttet.",al={"vem gjorde zarghs meats","vem är zargh","varifrån kommer köttet"}},{q="Vem ska få köttet?",a="Gryshka, värdshusvärden i Orgrimmars Valley of Strength, tar emot köttbitarna.",al={"vem får köttet","vem är gryshka","var ska jag lämna zarghs meats"}},{q="Varför måste köttet fraktas med vindryttare?",a="Färskt kött förstörs snabbt i hettan i The Barrens och Durotar. Zargh skickar kurirer till Devrak vid rastplatsen i The Crossroads, där en wyvern kan bära paketet till Orgrimmar innan det förstörs.",al={"varför flyga med köttet","devrak vindryttare kött"}},{q="Varför kan bara vissa raser leverera det här paketet?",a="Orciska och trolliska resenärer bär Zarghs paket till Orgrimmar. Taurenäventyrare bär djurhudar till Thunder Bluff, medan Forsaken-kurirer tar med sig förnödenheter tillbaka till The Sepulcher.",al={"varför kan taurener inte få det här uppdraget","odöda zarghs meats","vem kan leverera zarghs meats"}}},fx={a104b0f9={q="Vad är Zargh's Meats?",a="Zargh's Meats är ett paket med utvalda råa köttstycken som buntas ihop vid The Crossroads. Till skillnad från vanliga slaktarrester skickas dessa fina styckningsdetaljer som en gåva till Gryshka, värdshusvärden i Orgrimmars Valley of Strength.",al={"vad är zargh's meats","zargh's meats föremål","zargh's köttpaket"}}},fp="13,149,17.408.0,18.387.0,27.95.0,34.76.0,41.188.0,48.175.0"}
P.entries["item:zhevra-hooves"] = {n="Zhevra Hooves",s="Över The Barrens betar zhevras på den öppna savannen. Deras hovar visar att en jägare kan möta ett snabbt och kraftfullt byte.",h="Över The Barrens betar zhevras på den öppna savannen.",kw={"the barrens","the crossroads","darkthorn","hovar","jakt","runner","sergra","zhevra"},ang={["class:Hunter"]="Som jägare lär du dig av att spåra zhevras över savannen hur du hanterar snabba hjorddjur som kan vända sig om och slå med kraftiga sparkar.",["faction:Horde"]="Som ny rekryt i Horde som anländer till The Barrens kan du visa att du duger till att försvara The Crossroads genom att samla hovar åt Sergra Darkthorn."},sec={{t="Jaktens troféer",b="Zhevras betar över The Barrens, men deras kompakta, muskulösa ben kan slå hårt. Sergra Darkthorn, orkschamanen som ansvarar för The Crossroads, skickar blivande spejare från Horde för att samla hovar från zhevralöpare. Jakten vässar en nybörjarjägares instinkter och uthållighet. En skrämd löpare kan sparka omkull även en stadig tauren. Hela hovar visar att en jägare kan hantera snabbt byte som sparkar innan hen ger sig på Kalimdors dödligaste rovdjur."}},faq={{q="Vem vill ha Zhevra Hooves?",a="Sergra Darkthorn, en orkschaman vid The Crossroads i The Barrens, ber jägare att hämta fyra Zhevra Hooves för att visa att de är redo för svårare villebråd.",al={"vem behöver hovar","vem tar emot zhevrahovar","sergra hovar"}},{q="Var kommer Zhevra Hooves ifrån?",a="Zhevra Hooves får man från zhevralöpare som betar på den öppna savannen norr och söder om The Crossroads.",al={"var hittar man hovar","zhevra runner plats","hitta zhevra"}},{q="Varför är zhevras farliga att jaga?",a="Zhevras kan slå med stor kraft med bakbenen. En zhevra i full galopp kan sparka omkull en vuxen tauren, men zhevras är mindre aggressiva än raptorer eller prowlers.",al={"är zhevras starka","zhevras sparkstyrka","zhevra fara"}},{q="Varför låter Sergra jägare spåra zhevras i stället för vildare bestar?",a="Sergra ser zhevras som ett steg upp från plainstriders. De ger nykomlingar stadig men trygg övning innan de möter verkligt dödliga varelser.",al={"varför jaga zhevra","syftet med segras träning"}}},fx={["51f26e7e"]={q="Vad är Zhevra Hooves?",a="Zhevra Hooves är de robusta, kraftiga hovar som tas från de randiga vildhästarna som galopperar över The Barrens savanner. De rymmer en enorm kraft – en enda spark räcker för att få en fullvuxen tauren på fall – och är ett konkret bevis på en jägares växande skicklighet och uthållighet under den obarmhärtiga solen.",al={"vad är zhevra hooves","zhevra hooves","om zhevra hooves"}}},fp="13,114,20.440.0,24.152.0,33.106.0,33.179.0,69.136.0"}
P.entries["npc:abercrombie"] = {n="Abercrombie",s="Abercrombie verkar vara en svag, excentrisk eremit som bor i en förfallen koja i västra Duskwood nära Raven Hill Cemetery. Han påstår sig vara en ofarlig enstöring som plågas av skogens fasor och får gärna medkännande resenärer att samla ovanliga ingredienser och förnödenheter åt honom.",h="Abercrombie verkar vara en svag, excentrisk eremit som bor i en förfallen koja i västra Duskwood nära Raven...",kw={"abercrombie","styggelse","darkshire","duskwood","eliza","ghoulish effigy","raven hill","eremiten"},ang={["class:Paladin"]="Abercrombie står för den ondskefulla förvridning av nekromanti som frodas bakom fasaden av en vanlig, ofarlig stadsbo i behov av välgörenhet.",["class:Warlock"]="När Abercrombie offrar sitt eget hjärta för att återuppliva ett lik visar det hur långt dödliga är beredda att gå, även till självförstörelsens gräns, för att bruka mörk magi.",["faction:Alliance"]="Alliansens hjältar hjälper aningslöst den eländige eremiten och förser honom därmed med materialet som behövs för att iscensätta ett angrepp på Darkshire."},sec={{t="Eremiten från Raven Hill",b="Undangömd bland de ruttnande skuggorna nära Raven Hill Cemetery framstår Abercrombie som en ynklig gestalt. Han utger sig för att vara en gammal man som bara försöker överleva Duskwoods fasor och ber resenärer springa enkla ärenden till Darkshire för att hämta förnödenheter, örter och tråd. För den som inte känner till traktens historia verkar han bara vara ännu en olycklig själ som lämnats kvar när provinsen förföll."},{t="Balsamerarens vansinne",b="Innan sorgen förtärde hans sinne var Abercrombie en respekterad och vänlig alkemist i Raven Hill. När hans älskade hustru Eliza dog krossade sorgen hans förstånd. Han vände sig till förbjudna nekromantiska konster, skar ut sitt eget hjärta och lade det i Elizas döda bröst för att återuppliva henne. Ritualen skapade bara ett monster: Eliza återvände, förbannad med en omättlig hunger efter levande kött, och den vansinnige alkemisten tvingades hålla henne begravd på kyrkogården."},{t="En monstruös lögn",b="I mörka folksägner är Abercrombie känd som bara ”The Embalmer”. Han hyser ett djupt, sjukligt agg mot samhället Darkshire och dess ledare. De till synes oskyldiga uppgifter han ger hjälpsamma äventyrare, som att hämta ghoulrevben, specialtråd och frätande brygder, är i själva verket de sista delarna som behövs för att sätta ihop Stitches, en kolossal styggelse av hopsydda kroppsdelar, skapad för att slakta Night Watch och härja staden."}},faq={{q="Vem är Abercrombie?",a="Abercrombie är en eremit som bor nära Raven Hill Cemetery i Duskwood. Han var en skicklig alkemist, men förlorade förståndet efter sin hustrus död och är i hemlighet den nekromantiska gestalten som kallas The Embalmer.",al={"vem är eremiten","abercrombies historia","vem är abercrombie"}},{q="Varför vill Abercrombie ha förnödenheter från Darkshire?",a="Abercrombie påstår att han behöver hushållsförnödenheter och tråd för att överleva i vildmarken, men i själva verket lurar han äventyrare att samla ihop delarna som behövs för att sätta ihop den monstruösa styggelsen Stitches.",al={"varför behöver abercrombie tråd","abercrombies förnödenheter","vad bygger abercrombie"}},{q="Vem var Eliza?",a="Eliza var Abercrombies hustru. Efter hennes död försökte Abercrombie återuppliva henne med mörk magi genom att flytta sitt eget hjärta till hennes lik. Hon återvände som ett glupskt odött monster som han tvingades hålla begravt på Raven Hill Cemetery.",al={"eliza och abercrombie","abercrombies hustru","balsamerarens brud"}},{q="Vad händer när du lämnar brevet till borgmästaren?",a="Lord Ello kan inte läsa brevet eftersom det är skrivet på ett uråldrigt språk, så han ber Sirra Von'Indi översätta det. Översättningen avslöjar att Abercrombie har gjort något outsägligt. När Ello läser den börjar den monstruösa Stitches släpa sig längs vägen från Raven Hill mot Darkshire.",al={"brevet till borgmästaren","vad står det i brevet","abercrombies brev"}},{q="Varför hatar Abercrombie Darkshire?",a="Abercrombie förklarar aldrig varför. Sorgen och den mörka magin efter hans hustrus död drev honom till vansinne. Han kallar hånfullt borgmästare Ello Ebonlocke för en gammal vän, samtidigt som han skickar sin monstruösa skapelse längs vägen för att förgöra Darkshire.",al={"varför angriper abercrombie darkshire","balsamerarens motiv","abercrombies hämnd"}},{q="Är Abercrombie allierad med Scourge?",a="Nej. Abercrombie är en ensam eremit utan band till Lich Kings arméer.",al={"är abercrombie med i scourge","vem arbetar abercrombie för"}}},fx={["5abf44f4"]={q="Varför bor Abercrombie nära Raven Hill Cemetery?",a="Abercrombie håller till i en enslig stuga strax nordost om Raven Hill Cemetery i västra Duskwood, långt från Darkshire. Han utger sig för att vara en harmlös, excentrisk eremit och ber förbipasserande resenärer att hämta förnödenheter åt honom från staden.",al={"varför är abercrombie här","varför raven hill abercrombie","orsak till abercrombies plats"}},a3c5130f={q="Varför är Abercrombie fruktad i hela Duskwood?",a="Även om han utger sig för att vara en harmlös eremit är Abercrombie i hemlighet den fruktade gestalt som kallas Embalmer. Lokala sägner och barnberättelser skildrar hur han sjönk allt djupare in i galen nekromantik och skar ut sitt eget hjärta för att återuppliva sin döda hustru som en ghoul som hungrar efter kött. Bara hans namn för tankarna till skräcken från förbjudna, hopsydda monster som släppts lösa bland de levande.",al={"varför är abercrombie fruktad","embalmer abercrombies rykte","embalmer i duskwood"}}},fp="11,251,25.395.0,22.379.2,21.366.1,19.181.2,50.193.1,14.225.1,52.291.2,36.238.1,39.72.0"}
P.entries["npc:aelthalyste"] = {n="Aelthalyste",s="I Undercitys War Quarter tränar Aelthalyste Forsaken-präster i skuggans kraft. Hon vägleder deras andliga disciplin och skickar trollakolyter till deras egna äldste i Orgrimmar.",h="I Undercitys War Quarter tränar Aelthalyste Forsaken-präster i skuggans kraft.",kw={"aelthalyste","banshee","devouring plague","präst","skugga","undercity","ur'kyo","war quarter"},ang={["class:Priest"]="Som Forsaken-präst finner du i Aelthalyste en lärare i din lära, mörka besvärjelser och skuggornas vägar.",["faction:Horde"]="Som medlem av Horden kan du se hur Aelthalystes respekt för Ur'kyos läror hjälper till att överbrygga koalitionens kulturella skillnader.",["race:Troll"]="Som troll hänvisas du av Aelthalyste till Ur'kyo i Orgrimmar för att lära dig Darkspear-riter.",["race:Undead"]="Som odöd delar du Forsakens vändning från de forna livens heliga ljus mot skuggans praktiska kraft."},sec={{t="Den glömda skuggans röst",b="Aelthalyste tränar Forsaken-präster i skuggans kraft. Medan många präster i Azeroth vördar det heliga ljuset har hennes elever vänt sig bort från det. Hon steg fram som en kroppslös banshee och delar Sylvanas Windrunners följares spektrala vånda och obevekliga beslutsamhet. Från sin kammare i Undercitys War Quarter kallar hon blivande präster från avlägsna utposter för att bemästra sina mörkare konster. Hon lär dem att använda lidande som ett vapen."},{t="Band till horden",b="Aelthalyste respekterar de andliga traditionerna hos andra utövare i Horden. Hon skickar trolliska initiander bort från sina skuggläror och hänvisar dem över havet till Ur'kyo i Orgrimmar, där de kan lära sig Darkspear-andlighet. Hennes respekt låter Hordens magiker utvecklas inom sina egna traditioner och stärker banden mellan Kalimdor och Lordaeron."}},faq={{q="Vem är Aelthalyste?",a="Aelthalyste är en banshee och en ledande lärare inom Forsaken-prästerskapet. I Undercitys War Quarter tränar hon Forsaken-utövare i skuggmagi.",al={"aelthalystes bakgrund","vem är bansheeprästen","aelthalyste-spelperson"}},{q="Var hittar jag Aelthalyste?",a="Aelthalyste finns i War Quarter under ruinerna av Capital City, i Undercity. Andra Forsaken-instruktörer finns i närheten.",al={"aelthalystes plats","var finns aelthalyste","hitta aelthalyste"}},{q="Vad tror präster bland de Förinta på?",a="Många Forsaken-präster tror att det heliga ljuset övergav dem när de blev odöda. De har vänt sig från ljuset de vördade i livet mot skuggorna och anammat mörker, viljestyrka och personlig disciplin.",al={"de glömda skuggorna","de förintas prästtro","de glömda skuggornas kult"}},{q="Varför skickar Aelthalyste trollpräster till Orgrimmar?",a="Aelthalyste skickar trollpräster till Orgrimmar eftersom trollens band till andar och skuggor skiljer sig från Forsakens lära. Hon respekterar den skillnaden och skickar trollakolyter till Ur'kyo, Darkspear-prästtränaren i Valley of Spirits, för att träna.",al={"ur'kyo aelthalyste","varför skickar hon bort trollen","aelthalystes trolluppdrag"}},{q="Vad lär Aelthalyste ut?",a="Aelthalyste ger Forsaken-figurer grundläggande prästundervisning och vägleder avancerade akolyter i odödas riter. Hennes undervisning omfattar besvärjelser som Touch of Weakness och Dark Sacrifice.",al={"aelthalystes prästträning","vilka besvärjelser ger aelthalyste","aelthalystes förmågor"}},{q="Är Aelthalyste lojal mot Sylvanas?",a="Ja. Aelthalyste är en banshee i Undercity som tjänar Sylvanas Windrunner. Hon arbetar för att stärka Forsaken genom att bemästra mörk magi.",al={"aelthalystes fraktion","är hon lojal mot undercity","bansheens lojalitet"}}},fx={["71b5fa08"]={q="Varför är Aelthalyste i Undercity?",a="Aelthalyste bor i Undercitys War Quarter för att undervisa och vägleda utövare av skuggmagi. Som översteprästinna inom de Forsakens prästerskap leder hon utbildningen av Forsaken-präster och kallar lovande lärjungar från fjärran så att de kan bemästra sin tros mörkare riter.",al={"varför är aelthalyste här","aelthalystes syfte i undercity","varför är aelthalyste i war quarter"}},["84a14853"]={q="Vad vill Aelthalyste?",a="Aelthalyste vill stärka och utveckla disciplinen inom de Forsakens prästerskap. Hon fokuserar på att främja skuggmagi bland de Forsaken och kallar tillbaka invigda präster till Undercity för att förfina deras mörkare krafter, samtidigt som hon ser till att allierade utövare, som trollpräster, får rätt utbildning av sina egna äldste.",al={"aelthalystes mål","vad är aelthalystes mål","aelthalystes motiv"}},["61183540"]={q="Vilka är Aelthalystes allierade?",a="Aelthalyste tjänar de Forsaken som en framstående ledare inom deras prästerskap. Hon har nära undervisningsband till prästtränare i hela Hordens länder och hyser ömsesidig respekt för Darkspears äldste som Ur'kyo. Därmed ser hon till att trollstudenter leds tillbaka till sina egna andliga mästare i Orgrimmar.",al={"aelthalystes kontakter","vem samarbetar aelthalyste med","aelthalystes allierade"}}},fp="11,188,29.452.0,19.359.0,19.162.0,29.136.0,33.195.0,53.247.0,28.182.0,33.146.0"}
P.entries["npc:agathelos-the-raging"] = {n="Agathelos the Raging",s="Agathelos the Raging är en kolossal pansarvildsvinshane som hålls instängd i de törnbeklädda tunnlarna i Razorfen Kraul. För quilboar, vars gud och anfader är det väldiga vildsvinet Agamaggan, har ett odjur av hans storlek stor andlig betydelse, och han blir ännu mer fruktansvärd när han rasar. Hans enorma tyngd och styrka gör honom till ett av de farligaste odjuren som lurar under södra The Barrens.",h="Agathelos the Raging är en kolossal pansarvildsvinshane som hålls instängd i de törnbeklädda tunnlarna i...",kw={"agamaggan","agathelos","vildsvin","death's head","quilboar","rasande","razorfen kraul"},ang={["class:Druid"]="Druider håller Agamaggan högt aktad som en av de stora Ancients som föll under De äldstas krig. Att se en av hans kolossala släktingar instängd och rasande i Kraul är en dyster syn.",["class:Hunter"]="En jägare kan uppskatta Agathelos enorma rovdjurskropp, men hans ändlösa raseri gör honom till ett odjur som bör dödas snarare än tämjas.",["race:Tauren"]="De jordnära tauren känner väl till legenderna om Agamaggan och inser att quilboars fördärvande av hans besläktade odjur är ännu ett tecken på förruttnelsen som angriper The Barrens."},sec={{t="Den stora galtens avatarer",b="Quilboars gud och anfader är Agamaggan, ett titaniskt vildsvin. Ett odjur av Agathelos storlek, ungefär dubbelt så högt som en Barrens-åsködla, har därför stor andlig betydelse bland Razorfen-stammarna."},{t="Hållen i kedjor",b="Quilboar låter inte Agathelos ströva fritt i Kraul. Han hålls i en kort återvändstunnel bakom ett fält som bevakas av flera quilboar-vakter. Om inkräktare tar sig förbi barriären möter de ett rasande odjur som blir ännu större och mer skräckinjagande när det rasar."}},faq={{q="Varför är Agathelos så enorm?",a="Agathelos är ett naturligt kolossalt pansarvildsvin, ungefär dubbelt så stort som en vanlig åsködla, och han blir ännu större när han rasar. För quilboar, vars gud och anfader Agamaggan var ett titaniskt vildsvin, har ett odjur av hans storlek stor andlig betydelse.",al={"varför är agathelos stor","agathelos storlek","jättevildsvin i barrens"}},{q="Varför håller quilboar honom inlåst bakom en barriär?",a="Quilboar håller Agathelos instängd i en kort tunnel bakom ett fält som bevakas av flera av deras vakter, så att det monstruösa, rasande vildsvinet inte kan ströva fritt i Kraul.",al={"agathelos barriär","varför är agathelos inburad","agathelos kraftfält"}},{q="Vad har han för koppling till Agamaggan?",a="Agamaggan är det väldiga vildsvinet, en Ancient och quilboar-folkets anfader. På grund av detta släktskap har ett jättelikt vildsvin som Agathelos stor andlig betydelse för quilboar.",al={"agathelos agamaggan","är agathelos en gud","agamaggan son"}},{q="Vilken stam skapade Agathelos?",a="Agathelos är ett odjur, inte en skapelse. Han hålls av Death's Head-quilboar i Razorfen Kraul, som stänger in honom i en bevakad tunnel djupt inne bland törnena.",al={"vem skapade agathelos","vem matar agathelos","agathelos stam"}},{q="Kan jägare tämja Agathelos?",a="Nej. Agathelos är ett elitmonster med tung rustning, alldeles för farligt för att en jägare ska kunna tämja honom.",al={"tämja agathelos","kan jag tämja agathelos","jägare agathelos"}}},fx={a8df9e57={q="Vem är Agathelos the Raging?",a="Agathelos the Raging är en kolossal pansarvildsvin som hålls djupt inne i Razorfen Kraul. För quilboar, vars gud och anfader Agamaggan var ett titanskt vildsvin, har han stor andlig betydelse. Han är ungefär dubbelt så stor som en vanlig åsködla och blir ännu mer monstruös i strid.",al={"vem är agathelos","agathelos identitet","vad är agathelos the raging"}},["28c36899"]={q="På vems sida står Agathelos the Raging?",a="Agathelos är ett odjur, ingen intrigmakare. Han hålls av quilboar i Razorfen Kraul, instängd i en bevakad tunnel, och angriper alla som tar sig in i hans inhägnad.",al={"agathelos fraktion","vem tjänar agathelos","på vems sida står agathelos"}},["38ca6f4f"]={q="Vad vill Agathelos the Raging?",a="Agathelos har inga stora ambitioner eller listiga planer. Han är uppslukad av ursinnig vrede och vill bara krossa, stånga och trampa ner allt som tar sig in i hans inhägnad.",al={"vad vill agathelos","agathelos motiv","agathelos mål"}},be737a36={q="Varför är Agathelos the Raging fruktad?",a="Agathelos är fruktad för sin enorma, skräckinjagande kroppshydda och sitt okontrollerbara raseri. Han är bepansrad och naturligt väldig, och hans storlek och vildsinthet ökar ännu mer när han blir ursinnig. Då kan han krossa hela rövargrupper under sina hovar.",al={"varför är agathelos fruktad","hur farlig är agathelos","agathelos rykte"}}},fp="20,322,25.219.0,14.268.0,25.267.0,53.165.0,36.158.0,29.134.0,27.102.0"}
P.entries["npc:aggem-thorncurse"] = {n="Aggem Thorncurse",s="Aggem Thorncurse är en levande quilboar-schaman i Razorfen Kraul med titeln Death's Head Prophet. När han hotas kallar han en galtande till sin hjälp.",h="Aggem Thorncurse är en levande quilboar-schaman i Razorfen Kraul med titeln Death's Head Prophet.",kw={"aggem","kraul","quilboar","razorfen","thorncurse"},ang={["class:Priest"]="Hans profettitel speglar quilboarernas andliga traditioner.",["class:Shaman"]="Aggem kallar på en galtande för att hjälpa sig, ett tydligt uttryck för quilboarernas schamanism.",["faction:Horde"]="Eftersom quilboarerna ständigt hotar The Barrens bidrar det till att säkra Durotar och Mulgore att göra sig av med ihärdiga försvarare som Aggem Thorncurse."},sec={{t="Death's Head Prophet",b="Aggem vaktar en del av Razorfen Kraul som ockuperas av Death's Head-stammen. Hans schamanistiska krafter omfattar att kalla på en galtande, vilket speglar quilboarernas vördnad för Agamaggan."}},faq={{q="Vem är Aggem Thorncurse?",a="Aggem är en quilboar-schaman och Death's Head Prophet i Razorfen Kraul.",al={"aggem thorncurse","vem är aggem","aggem razorfen kraul"}},{q="Var kan Aggem Thorncurse hittas?",a="Han finns inne i Razorfen Kraul i södra The Barrens.",al={"aggem plats","var finns aggem","var hittar man aggem thorncurse"}},{q="Vilken ande åkallar Aggem?",a="Aggem kallar på en galtande som strider vid hans sida.",al={"aggem ande","aggems galtande"}},{q="Hur strider Aggem?",a="Aggem använder schamanistisk magi och kallar på en galtande som strider vid hans sida.",al={"aggems förmågor","hur strider aggem"}},{q="Tillhör Aggem Thorncurse en viss quilboar-stam?",a="Han tillhör Death's Head-stammen.",al={"aggems stam","vilken stam tillhör aggem","razorfen quilboar"}}},fx={["0a149290"]={q="Varför är Aggem Thorncurse här?",a="Aggem står bland Death's Head-quilboar i Razorfen Kraul och försvarar sin stams territorium.",al={"varför är aggem thorncurse i razorfen kraul","varför är aggem thorncurse här"}},["32004356"]={q="Vem är Aggem Thorncurse knuten till?",a="Han tillhör Death's Head-stammen och följer quilboarernas schamanistiska traditioner.",al={"aggem thorncurses kontakter","vem är aggem thorncurse allierad med"}}},fp="16,124,24.174.0,24.70.0,36.61.0,33.48.0,31.70.0,62.40.0"}
P.entries["npc:ahanu"] = {n="Ahanu",s="Ahanu är en taurenhandlare som arbetar i Hewa's Armory på Thunder Bluffs nedre höjd. Han tillverkar och säljer läderrustning till resenärer och unga krigare som ger sig av genom Mulgore och de vidsträckta slätterna. Han hjälper också nyanlända kurirer att hitta rätt bland höjderna när de levererar meddelanden från närliggande bosättningar.",h="Ahanu är en taurenhandlare som arbetar i Hewa's Armory på Thunder Bluffs nedre höjd.",kw={"ahanu","hewa's armory","jahan hawkwing","läderrustning","mulgore","thunder bluff"},ang={["race:Tauren"]="För unga taurenkrigare som anländer från The Crossroads på sin första vindryttarfärd erbjuder Ahanu både ett välbekant välkomnande och nödvändiga hudar inför resan."},sec={{t="Handlare i Hewa's Armory",b="Bland läderhantverkarnas stånd och vapenförråden på Thunder Bluffs nedre höjd förser Ahanu dem som lever på Kalimdors gräsmarker med viktig utrustning. Han arbetar med hudar som skickas av hans vän Jahan Hawkwing vid The Crossroads och företräder de vanliga hantverkarna som förser taurenhuvudstaden med slitstark utrustning av garvade och beredda hudar. För resenärer som just anlänt med vindryttare från The Crossroads är Ahanu ofta den första de möter i den storslagna staden. Han tar emot leveranser och visar budbärare vägen till de lokala flygrostplatserna."}},faq={{q="Vem är Ahanu?",a="Ahanu är en taurenhandlare som bor på Thunder Bluffs nedre höjd, inne i Hewa's Armory. Han säljer läderrustning och hjälper kurirer som anländer till huvudstaden från The Crossroads.",al={"ahanu npc","ahanu historia","vem är ahanu"}},{q="Vad säljer Ahanu?",a="Han säljer olika enkla delar av beredd och garvad läderrustning, bland annat jackor, bälten, stövlar och armbågsskydd för jägare, skurkar och unga äventyrare.",al={"ahanu varor","ahanu sortiment","ahanu handlare"}},{q="Var i Thunder Bluff hittar jag honom?",a="Ahanu finns inne i Hewa's Armory på Thunder Bluffs nedre höjd, nära andra rustningsmakare, läderarbetare och vapensmeder.",al={"ahanu plats","var finns ahanu","ahanu karta"}},{q="Vilka uppdrag handlar om Ahanu?",a="Unga taurenäventyrare får i uppdrag att leverera varor till honom med vindryttare i ”Ride to Thunder Bluff”. Därefter hänvisar han dem tillbaka till Tal, stadens vindryttarmästare.",al={"ahanu uppdrag","ride to thunder bluff ahanu"}}},fx={f9ab69c3={q="På vems sida står Ahanu?",a="Ahanu är en lojal medlem av Horden och en stolt medborgare i Thunder Bluff. Han verkar öppet under överhövding Cairne Bloodhoofs baner och utrustar taurenjägare, druider och besökande Horde-resenärer som passerar genom staden.",al={"ahanus fraktion","tillhör ahanu horden","vem tjänar ahanu"}},b68e223b={q="Varför är Ahanu här?",a="Ahanu sköter sin butik i Hewa's Armory på den nedre höjden i Thunder Bluff. Han är stadens rustningsmakare och tillhandahåller tålig, garvad läderutrustning åt jägare och resenärer som utforskar Mulgore och den större kontinenten.",al={"varför är ahanu i thunder bluff","ahanus syfte i thunder bluff","vad förde ahanu hit"}},c2a07e44={q="Vad vill Ahanu?",a="Ahanu är nöjd med sitt arbete som läderhandlare och önskar sig inte mycket mer än en rättvis affär och gott sällskap. Han fokuserar på att förse resenärer med hållbara rustningar och uppskattar sällskapet från andra stadsbor.",al={"vad behöver ahanu","ahanus mål","ahanus motivation"}},b04a3d48={q="Vem är Ahanu knuten till?",a="Ahanu räknar Jahan Hawkwing, en annan taurenhandlare vid The Crossroads i The Barrens, som en vän. Jahan skickar färska buntar med hudar till honom, som Ahanu förädlar till lädervaror i Thunder Bluff.",al={"ahanus vänner","vem känner ahanu","ahanus följeslagare"}}},fp="5,239,25.376.0,13.146.0,21.139.0,38.119.0,26.155.0"}
P.entries["npc:aku-mai"] = {n="Aku'mai",s="Aku'mai är en väldig hydra med tre huvuden som lever i de sjunkna ruinerna av Blackfathom Deeps vid The Zoram Strand. Som tjänare åt en Old God steg den upp ur vattnet när gudens korrumperande inflytande besudlade templets heliga Moon Well. Twilight's Hammer-kulten har samlats i djupen och offrar oskyldiga till den i utbyte mot kraft.",h="Aku'mai är en väldig hydra med tre huvuden som lever i de sjunkna ruinerna av Blackfathom Deeps vid The Zoram...",kw={"aku'mai","blackfathom","djupen","hydra","kelris","old god","zoram"},ang={["class:Druid"]="Aku'mais onaturliga korruption förvrider Ashenvales kustvatten och måste renas bort för att återställa den naturliga balansen.",["class:Priest"]="Aku'mais och Twilight's Hammers vidriga närvaro står för de Old Gods korruption, i strid med den Heliga Ljusets och Elunes läror.",["race:NightElf"]="Aku'mai har vanhelgat den innersta helgedomen i ett ruinerat tempel som en gång helgats åt mångudinnan Elune och gjort den heliga platsen till ett näste för korruption."},sec={{t="Zoram Strands plågoande",b="Blackfathom Deeps var en gång ett storslaget tempel tillägnat Elune, tills en Old Gods korrumperande inflytande sipprade upp ur jorden och besudlade dess heliga Moon Well. Aku'mai, en gigantisk hydra och tjänare åt guden, steg upp ur vattnet. Aku'mai är ingen vanlig varelse i tidvattnet, utan en levande plåga över The Zoram Strand som tagit sin boning i nattalvernas fallna tempels översvämmade ruiner och förgiftar vattnet med sin illvilja."},{t="Tjänare åt det uråldriga mörkret",b="Aku'mais vidriga närvaro lockade till slut Twilight's Hammer djupt in i de underjordiska grottorna. Kultisterna, ledda av Twilight Lord Kelris och i förbund med nagas, håller till i det dränkta templet och offrar oskyldiga till Aku'mai för att få kraft."}},faq={{q="Vad är Aku'mai?",a="Aku'mai är en uråldrig hydra med tre huvuden, genomsyrad av mörk kraft. Den tjänar en Old God och steg upp ur Blackfathom Deeps förgiftade vatten. Nu håller den till i templets översvämmade salar.",al={"vem är aku'mai","aku'mais historia","vad är aku'mai för slags monster"}},{q="Var lever Aku'mai?",a="Aku'mai håller till i de djupast belägna, översvämmade grottorna i Blackfathom Deeps, ett ruinerat tempelkomplex tillägnat Elune vid kusten av The Zoram Strand i nordvästra Ashenvale.",al={"aku'mais plats","var finns aku'mai","var hittar jag aku'mai"}},{q="Varför matar Twilight's Hammer Aku'mai?",a="Twilight's Hammer vördar Aku'mai som en tjänare åt de Old Gods de dyrkar. Kultisterna, ledda av Twilight Lord Kelris, offrar oskyldiga till besten i utbyte mot mörk kraft.",al={"varför matar kultister aku'mai","kelris och aku'mai","twilight's hammer och aku'mai"}},{q="Vilka krafter har Aku'mai?",a="Utöver sin enorma storlek och sina många gapande huvuden bär Aku'mai på de Old Gods mörka gunst. I strid rasar den ursinnigt och omger dem som kommer nära med giftmoln.",al={"aku'mais krafter","är aku'mai magisk","void-hydra"}},{q="Är Aku'mai en Old God?",a="Nej. Aku'mai är ingen Old God, utan en uråldrig hydra som tjänar en sådan. Dess onda närvaro räcker för att samla Twilight's Hammer till dyrkan omkring den.",al={"är aku'mai en old god","är aku'mai en gud"}},{q="Varför beger sig äventyrare ner i djupen för att dräpa den?",a="Om Aku'mais vildsinthet och kultens hängivenhet inte stoppas hotar de att släppa lös en katastrofal ondska över Ashenvale och Kalimdor. Både Alliansens och Hordens myndigheter vill sätta stopp för Twilight's Hammer och dräpa skräckvarelsen som lurar i templets hjärta.",al={"varför döda aku'mai","ondska i blackfathom: aku'mai","hotet från aku'mai"}}},fx={["055a774d"]={q="På vems sida står Aku'mai?",a="Aku'mai tjänar en Old God och är inte lojal mot några dödliga raser. Kulten Twilight's Hammer dyrkar odjuret och offrar oskyldiga till det i utbyte mot mörka krafter.",al={"akumais fraktion","vem tjänar akumai","akumais lojalitet"}},["7b9e18bb"]={q="Vad vill Aku'mai?",a="Aku'mai är ett vildsint odjur, ingen intrigmakare. Det tjänar en Old God och lurar i Blackfathom Deeps förgiftade vatten. Kultisterna i Twilight's Hammer offrar oskyldiga till det i hopp om att återupprätta den tid då de gamla gudarna härskade över världen.",al={"akumais mål","vad vill akumai ha","akumais syfte"}},["6cae52d5"]={q="Varför är Aku'mai här i Blackfathom Deeps?",a="Aku'mai steg upp ur vattnen i det sjunkna templet när en Old Gods fördärv sipprade upp ur marken och besmittade dess heliga Moon Well. De dränkta salarna i Blackfathom Deeps ger nu kulten Twilight's Hammer en mörk, vattenfylld tillflyktsort där den kan skydda och dyrka odjuret i hemlighet.",al={"varför är akumai i blackfathom","hur kom akumai hit","akumai zhang strand"}},ba41fb22={q="Vem är Aku'mai knuten till?",a="Aku'mai tjänar en forntida gud. I Blackfathom Deeps dyrkar Twilight's Hammer, under Twilight Lord Kelris, besten och offrar oskyldiga åt den för att få makt.",al={"aku'mais kopplingar","vem styr aku'mai","aku'mai och kelris"}},["989c4b42"]={q="Varför är Aku'mai så fruktad?",a="Aku'mai är en gigantisk hydra med tre huvuden och tjänare åt en forntida gud, uppstigen ur The Zoram Strands förgiftade vatten. Berättelser om dess grymhet och den mörka dyrkan som den lockar fram hos Twilight's Hammer gör den till en av de mest fruktade fasor som lurar längs Ashenvales kust.",al={"varför aku'mai är fruktad","aku'mais rykte","är aku'mai farlig"}}},fp="7,276,27.329.0,34.215.1,16.160.0,24.136.0,45.156.0,33.164.0,22.124.0,53.241.0"}
P.entries["npc:alamar-grimm"] = {n="Alamar Grimm",s="Alamar Grimm är en tränare för gnomiska häxmästare som är stationerad i Coldridge Valley vid Anvilmar. Bitter över den tragiska förlusten av Gnomeregan misstror han främlingar och fokuserar på att lära unga häxmästare att tygla mörka krafter och kalla fram sina första demoniska undersåtar.",h="Alamar Grimm är en tränare för gnomiska häxmästare som är stationerad i Coldridge Valley vid Anvilmar.",kw={"alamar","anvilmar","coldridge","gnomeregan","grimm","imp","tränare","häxmästare"},ang={["class:Warlock"]="För gnomiska häxmästare som börjar sin bana i Coldridge Valley ger Grimm dig dina första besvärjelser och låter dig bevisa ditt värde för att förtjäna din första imp.",["race:Gnome"]="Grimm förkroppsligar den stillsamma bitterheten hos landsflyktingar som känner sig övergivna av sina allierade medan Gnomeregan fortfarande är i troggers händer."},sec={{t="En bitter landsflykting",b="Medan de flesta gnomer i Coldridge Valley ägnar sin energi åt återhämtning och uppfinningar, bär Alamar Grimm på en djup bitterhet över Gnomeregans fall. Han ser cyniskt på vanliga äventyrare och till och med Ironforges dvärdar, och muttrar att deras allierade bryr sig mer om diplomati med människor än om att återta den fallna teknostaden. Från Anvilmar söker han likasinnade som förstår att hänsynslös makt kan vara vad hans folk verkligen behöver."},{t="Mästare i mörka konster",b="För unga gnomer som beträder den onda magins väg fungerar Grimm som en första vägvisare. När han får se ett Tainted Memorandum tar han ovanligt varmt emot dem och börjar undervisa rekryterna i grundläggande besvärjelser. Men innan han ger en novis den farliga kunskap som krävs för att binda en demonisk imp kräver han bevis på deras magiska och fysiska uthållighet. Han skickar dem för att hämta de märkliga fjäderamuletter som bärs av lokala Frostmane-trollnoviser."}},faq={{q="Vem är Alamar Grimm?",a="Alamar Grimm är en tränare för gnomiska häxmästare i Anvilmar i Coldridge Valley. Han tränar nybörjare bland gnomiska häxmästare i deras grundläggande onda förmågor och lär dem att kalla fram sin första imp.",al={"alamar grimm","vem är alamar","gnomisk häxmästartränare anvilmar"}},{q="Varför är Alamar Grimm arg på dvärgarna?",a="Alamar tycker att dvärgarna i Ironforge inte verkligen prioriterar att återta Gnomeregan, trots att de gett de fördrivna gnomerna skydd. Han ogillar att dvärgarnas intressen verkar väga tyngre för deras allians med människor än för att befria hans folks hemland.",al={"varför hatar alamar dvärgar","alamars syn på dvärgar","varför arg"}},{q="Vad ber Alamar Grimm nya häxmästare att göra?",a="För att bevisa att de har uthålligheten och den magiska förmågan som krävs för att kontrollera en demon instruerar Grimm noviser bland häxmästarna att jaga lokala Frostmane-trollnoviser och samla in deras fjäderamuletter. När de har hämtats använder han dem för att pröva rekryten innan han lär ut ritualen för att kalla fram en imp.",al={"alamar grimm imp-uppdrag","uppdrag med fjäderamuletter","frostmane-amulett häxmästare"}}},fx={["04c944ae"]={q="På vems sida står Alamar Grimm?",a="Alamar Grimm står helhjärtat på det förvisade gnomfolket sida, men känner en stark bitterhet mot deras nuvarande allierade. Dvärgarna ger de fördrivna gnomerna skydd i Dun Morogh, men Alamar hyser agg mot Ironforges ledare och anser att de prioriterar banden till avlägsna människor framför att återta Gnomeregan. Han verkar inom Alliansen enbart för att bygga upp gnomernas styrka på sina egna villkor.",al={"alamar grimms fraktion","alamar grimms lojalitet","vem alamar grimm kämpar för"}},["949ab41a"]={q="Vad vill Alamar Grimm?",a="Alamar vill inget mindre än att återta Gnomeregan och stärka sitt folk med mörk magi. Han avfärdar vanliga äventyrare som ineffektiva misslyckanden som lät staden falla och vill i stället fostra disciplinerade och kapabla häxmästare med den magiska och fysiska styrka som krävs för att återta deras hemland.",al={"alamar grimms mål","vad alamar vill","alamar grimms motiv"}},["1846448c"]={q="Varför är Alamar Grimm i Coldridge Valley?",a="Efter Gnomeregans tragiska fall sökte Alamar skydd tillsammans med sina överlevande landsmän i Coldridge Valleys trygghet. Nära Anvilmar fungerar han som mentor och tränare åt nyanlända gnomer som känner sig dragna till felmagi. Han prövar deras förmåga och rustar dem med de mörka besvärjelser som behövs för den hårda väg som väntar.",al={"varför alamar grimm är här","varför alamar är i anvilmar","alamar grimms syfte här"}}},fp="12,196,14.402.0,23.366.0,20.142.0,41.228.0,46.194.0"}
P.entries["npc:alanndarian-nightsong"] = {n="Alanndarian Nightsong",s="Alanndarian Nightsong är en Night Elf i Auberdine i Darkshore som ägnar sig åt att vårda regionens hårt ansatta djurliv. Hon samarbetar med resenärer för att råda bot på plågorna som drabbar det lokala djurlivet, särskilt regionens hjortar, som har insjuknat av gift i Darkshores vatten.",h="Alanndarian Nightsong är en Night Elf i Auberdine i Darkshore som ägnar sig åt att vårda regionens hårt...",kw={"alanndarian","auberdine","bota","darkshore","kaldorei","nightsong","strider","djurliv"},ang={["class:Druid"]="Druider kommer att känna samhörighet med Alanndarians försök att hitta vattenburna föroreningar och bota förgiftade varelser runt om i Darkshore.",["class:Hunter"]="Jägare som är lyhörda för djurens beteenden hjälper Alanndarian nära, med sina spårningsfärdigheter för att hitta vilda striders och nödställda villebråd.",["faction:Alliance"]="Alanndarian är en viktig kontakt för alliansresenärer som anländer till Auberdine och hjälper nykomlingar att förstå det känsliga läget för norra Kalimdors vildmark.",["race:NightElf"]="Hennes vördnad för skogen och hängivenhet åt att rena förvildat djurliv speglar kaldoreiernas grundläggande bevarandeideal."},sec={{t="En vårdare i Auberdine",b="I kustbosättningen Auberdine vakar Alanndarian Nightsong över Darkshores känsliga ekologiska balans. När mystiska föroreningar tränger ner i jorden och vattnet börjar det forntida skogens varelser insjukna och visa onaturlig aggressivitet. Alanndarian agerar som väktare och naturkännare och söker praktiska botemedel för att lindra deras lidande och återställa deras naturliga livskraft."},{t="Att läka de drabbade och sjuka",b="Mycket av Alanndarians uppmärksamhet går till att hitta grundorsakerna till åkommorna som sprids bland det lokala djurlivet. Genom att noggrant samla in botaniska ingredienser och undersöka regionens främsta vattenkällor tillverkar hon salvor och läkande brygder. Hon ber kringvandrande äventyrare att applicera botemedlen direkt på sjuka skogsdjur och försöker hejda den spridande korruptionen innan den tar över Darkshores djurliv för gott."}},faq={{q="Vem är Alanndarian Nightsong?",a="Alanndarian Nightsong är en Night Elf-naturkännare som finns i hamnstaden Auberdine i Darkshore. Hon ägnar sig åt att ta hand om det lokala djurlivet och hitta örtmediciner mot de onaturliga sjukdomar som plågar kusten.",al={"alanndarian","vem är alanndarian nightsong","alanndarian nightsongs bakgrund"}},{q="Var hittar man Alanndarian Nightsong?",a="Hon bor i Auberdine, det främsta Night Elf-fästet längs Darkshores dimhöljda kust.",al={"alanndarians plats","var finns alanndarian","hitta alanndarian nightsong"}},{q="Vilka uppgifter ber hon äventyrare utföra?",a="Alanndarian ber äventyrare spåra källorna till sjukdomarna som förgiftar Darkshores varelser, samla in viktiga läkande ingredienser från vildmarken och ge botemedel direkt till sjuka djur som de krassliga hjortarna.",al={"alanndarians uppdrag","uppdrag med sjuka djur i auberdine","vad vill alanndarian"}},{q="Är hon släkt med andra Nightsongs?",a="Andra Night Elves bär namnet Nightsong, men inget bekräftar att hon är släkt med någon av dem. Hennes dagliga fokus ligger fortfarande på att värna om Darkshores vildmark.",al={"nightsong-släkten","släktskap med master nightsong","falara nightsong"}},{q="Varför är varelserna i Darkshore sjuka?",a="Något förorenar Cliffspring Falls, Darkshores främsta källa till dricksvatten, och det förgiftade vattnet har gjort hjortar sjuka i hela regionen. Alanndarian misstänker att även en större förorening ligger bakom.",al={"varför är darkshores djur sjuka","förvildade striders i darkshore","plåga i darkshore"}},{q="Kan hon träna tallstriderdjur?",a="Även om ryktet säger att hon har stor kunskap om striders tränar hon inte aktivt jägarnas tama husdjur ute i fält. I stället håller hon fokus på de vilda bestånden.",al={"tallstrider-tränare","träna strider i auberdine","träna min strider"}}},fx={["04324614"]={q="På vems sida står Alanndarian Nightsong?",a="Hon står helhjärtat på nattalverna i Darnassus och den bredare Alliansens sida. Från sin post i Auberdine arbetar hon direkt med att skydda Darkshores djurliv och hjälper resenärer som är lojala mot Kaldoreis sak.",al={"alanndarian nightsongs fraktion","alanndarian nightsong, alliansen eller horden"}},d3838107={q="Vad vill Alanndarian Nightsong?",a="Alanndarian är fast besluten att förstå och häva de märkliga åkommor som drabbar traktens djur. Hon söker hjälp med att hitta sjukdomarnas källa och samla de ingredienser som behövs för att tillverka botemedel som läker Darkshores fördärvade varelser.",al={"alanndarian nightsongs mål","vad alanndarian försöker göra"}},["209c0886"]={q="Varför är Alanndarian Nightsong i Darkshore?",a="Hon har sitt hem i hamnstaden Auberdine för att vaka över Darkshores vildmark. Härifrån håller hon noga uppsikt över den krypande fördärvning som oroar traktens djurliv och samordnar arbetet med att återställa landets balans.",al={"varför alanndarian är i auberdine","alanndarians skäl i darkshore"}}},fp="21,181,24.265.0,29.290.0,29.155.0,41.99.0,47.144.0,35.149.0,40.172.0,31.149.0"}
P.entries["npc:althea-ebonlocke"] = {n="Althea Ebonlocke",s="Commander Althea Ebonlocke leder Night Watch, stadsvakten som kämpar för att skydda Darkshire från Duskwoods fasor. Som släkting till borgmästaren Ello Ebonlocke ansvarar hon för försvaret av en isolerad region som Stormwinds reguljära militär har övergett. Hon organiserar patruller, ger äventyrare i uppdrag att rensa bort lokala fasor och samordnar stadens kamp för överlevnad mot ständiga monsterhot.",h="Commander Althea Ebonlocke leder Night Watch, stadsvakten som kämpar för att skydda Darkshire från Duskwoods...",kw={"althea","befälhavare","darkshire","duskwood","ebonlocke","milis","mor'ladim","night watch","stitches"},ang={["class:Paladin"]="Paladiner som färdas längs Duskwoods dystra vägar kan hjälpa Althea att ge rastlösa själar ro och lätta på en del av den andliga skräck som tynger hennes milisstyrka.",["class:Warrior"]="Krigare finner en sträng och praktisk befälhavare i Althea. Hon respekterar kampdisciplin och värdesätter frontkämpar som är villiga att hålla stånd mot övermäktiga odds.",["faction:Alliance"]="Althea förkroppsligar Alliansens bortglömda gränsmarkers bistra beslutsamhet och håller riket samman där kronans arméer har dragit sig tillbaka."},sec={{t="Befälhavare för vakten",b="Medan hennes släkting, borgmästare Ello Ebonlocke, sköter stadens civila styre i rådhuset, leder Commander Althea Darkshires tunna försvarslinje. När Stormwind inte skickade kungliga trupper för att skydda Duskwood från krypande fasor bildade invånarna Night Watch. Under Altheas stadiga och obevekliga befäl patrullerar dessa frivilliga de dimhöljda vägarna och hindrar skelettodöda, våldsamma vargar och spindlar från att tränga in i stadens utkanter."},{t="En stad på ruinens brant",b="Althea är pragmatisk och förstår sin milisstyrkas begränsningar. Hennes styrkor är underlägsna och hon förlorar ständigt rekryter, så hon tar gärna hjälp av förbipasserande legosoldater och resenärer för att minska hoten vid Darkshires tröskel. Hon leder kampanjer mot gastar och skelett på skogens fridfulla men sorgliga gravplatser och håller samtidigt utkik efter mörkare rykten som rör sig djupt inne i skogen."},{t="Skogens tragedier",b="Utöver skogens vanliga skadedjur samordnar Althea utredningen av och kampen mot Duskwoods värsta plågor. Hon hjälper till att nysta upp Stalvan Mistmantles mörka öde och söker svar på varför Mor'Ladim, den fallne riddaren Morgan Ladimore, vandrar rastlöst omkring. När Abercrombie släpper lös monstret Stitches längs huvudvägen är det Altheas Night Watch som rycker ut längs vägen för att stå emot det."}},faq={{q="Vem är Althea Ebonlocke?",a="Commander Althea Ebonlocke leder Night Watch, Darkshires stadsmilis i Duskwood. Hon ansvarar för att organisera försvaret av regionen mot de odöda och bestar som lurar i skuggorna.",al={"vem är althea","befälhavare ebonlocke","vem leder night watch"}},{q="Vad är Night Watch?",a="Night Watch är en frivillig milis som Darkshires invånare har bildat. Eftersom Stormwind nästan inte har gett Duskwood något militärt stöd har lokalbefolkningen slutit sig samman under Altheas ledning för att patrullera vägarna och bekämpa skogens fasor.",al={"vad är night watch","vilka är night watch","darkshires milis"}},{q="Hur är Althea släkt med borgmästare Ello Ebonlocke?",a="Althea är släkt med Lord Ello Ebonlocke, Darkshires borgmästare. Medan borgmästaren styr stadens angelägenheter från rådhuset leder Althea milisen ute i fält.",al={"släkt med ello ebonlocke","är althea ellos dotter","altheas familj"}},{q="Varför hjälper inte Stormwind Althea att försvara Darkshire?",a="När kung Varian Wrynn är försvunnen och Stormwinds resurser är ansträngda har adelsrådet i stort sett försummat rikets avlägsna områden. Darkshire får nästan inga soldater eller någon undsättning, så Althea måste förlita sig på lokala frivilliga och fristående äventyrare.",al={"varför finns inga stormwind-vakter","stormwinds stöd till duskwood","var är soldaterna"}},{q="Vilka uppdrag erbjuder Commander Althea?",a="Althea erbjuder Night Watchs centrala uppdragskedja och skickar ut äventyrare för att jaga vargar, skelettmonster och gastar runt om i Duskwood. Hon hjälper också till att utreda Legend of Stalvan och hantera den kringvandrande fasan Mor'Ladim.",al={"altheas uppdrag","night watchs uppdragskedja"}},{q="Vad gör Althea när Stitches anfaller Darkshire?",a="När det stygnade monstret som Abercrombie skapat släpar sig längs vägen mot Darkshire rycker grupper av hennes vakter i Night Watch ut längs vägen för att stå emot det. Utan hjälp från äventyrare kan monstret dock slå sig rakt igenom dem.",al={"althea och stitches","vem slåss mot stitches","darkshire under attack"}}},fx={["4a666294"]={q="På vems sida står Commander Althea Ebonlocke?",a="Commander Althea står helhjärtat på Darkshires folks och Alliansens sida. Stormwind har i stort sett övergett Duskwood åt sitt skuggiga öde, men Althea vägrar att överge sitt hem. Hon leder Night Watch, en desperat lokal milis som svurit att hålla stånd mot vildsinta bestar, rastlösa döda och krypande fasor som hotar att utplåna staden.",al={"althea ebonlockes fraktion","vem althea kämpar för","är althea med i alliansen"}},["37e849b9"]={q="Vad vill Commander Althea Ebonlocke?",a="Hennes främsta mål är att Darkshire ska överleva. Utan regelbundna förstärkningar från armén arbetar Althea outtröttligt för att hålla den framryckande vildmarken stången. Hon leder Night Watch mot skelettdemoner, rabiessmittade vargar och spindlar, och söker aktivt modiga äventyrare som kan undanröja dödliga hot i skogens skuggor innan de slaktar hennes hårt prövade stad.",al={"vad althea vill","althea ebonlockes mål","altheas uppdrag i duskwood"}},["288c0322"]={q="Varför är Commander Althea Ebonlocke i Darkshire?",a="Duskwood är hennes hem och hennes plikt. Hon är släkt med borgmästaren Lord Ello Ebonlocke och stannar på stadstorget för att leda Night Watch från stadens hjärta. I stället för att fly till tryggheten i Stormwind stannar Althea vid fronten, samordnar patruller och samlar alla dugliga resenärer till försvaret av gränserna.",al={"varför althea är i darkshire","varför commander althea är här","var althea ebonlocke befinner sig"}}},fp="16,220,22.387.0,19.341.0,21.380.1,24.168.0,24.214.0,46.126.0,53.263.0,40.179.0,52.215.1"}
P.entries["npc:altsoba-ragetotem"] = {n="Altsoba Ragetotem",s="Altsoba Ragetotem är en tauren-vapensmed stationerad vid Bloodvenom Post i Felwood. Från denna avlägsna Horde-utpost förser han ständigt förbipasserande mästare med pålitliga klubbor, stavar och yxor inför mötet med skogens fördärvade fasor.",h="Altsoba Ragetotem är en tauren-vapensmed stationerad vid Bloodvenom Post i Felwood.",kw={"altsoba","bloodvenom post","felwood","ragetotem","tauren","handlare","vapensmed"},ang={["faction:Horde"]="Altsoba tillhandahåller viktiga krigsförnödenheter åt Hordens agenter som håller stånd i en av Kalimdors mest korrumperade regioner.",["race:Tauren"]="Som medlem av Ragetotem-stammen för Altsoba med sig taurenernas traditionella ståndaktighet till ett land som plågas svårt av demoniskt fördärv."},sec={{t="Rustningssmed vid Bloodvenom Post",b="Bloodvenom Post är en förrädisk utpost i hjärtat av Felwood, omgiven av demonisk korruption och förgiftat djurliv. Att upprätthålla en försörjningslinje här ute är en bister nödvändighet, och Altsoba Ragetotem drar sitt strå till stacken genom att utrusta Hordens spejare och resenärer. Oavsett om någon behöver en stadig halvmåneyxa eller en tung krigshammare ser Altsoba till att krigare på väg in i de korrumperade skogarna inte går obeväpnade ut i striden."}},faq={{q="Vem är Altsoba Ragetotem?",a="Altsoba Ragetotem är en tauren-handlare stationerad vid Bloodvenom Post, Hordens läger i Felwood. Han tillhandahåller grundläggande tunga vapen åt resenärer och försvarare som trotsar den fördärvade dalen.",al={"vem är altsoba","altsoba ragetotem","tauren vid bloodvenom post"}},{q="Vad säljer Altsoba?",a="Han säljer en mängd vanliga närstridsvapen, däribland stridsstavar, morgonstjärnor, krigshammare och yxor, och erbjuder pålitligt stål åt äventyrare som beger sig djupt in i Felwood.",al={"altsobas varor","altsobas handelsvaror","vilka vapen säljer altsoba"}},{q="Var hittar jag Altsoba Ragetotem?",a="Du hittar honom vilande vid Bloodvenom Post, uppe på klipporna med utsikt över Felwoods vidriga vatten och förgiftade gläntor.",al={"altsobas plats","var finns altsoba","bloodvenom posts handelsplats"}}},fp="17,229,26.419.0,25.188.0,23.177.0,35.131.0"}
P.entries["npc:alyissia"] = {n="Alyissia",s="Alyissia är en kaldorei-krigartränare som håller till i Aldrassils ihåliga grenar i Shadowglen. Hon lär nyvaknade Night Elf-krigare grunderna i närstrid och hjälper dem att tygla sin råstyrka och disciplin för att försvara sin unga världsträd.",h="Alyissia är en kaldorei-krigartränare som håller till i Aldrassils ihåliga grenar i Shadowglen.",kw={"aldrassil","alyissia","night elf","shadowglen","teldrassil","krigartränare"},ang={["class:Warrior"]="För unga Night Elf-krigare är Alyissia den allra första mentorn. Hon lär dem tidigt stridsställningar och kampdisciplin innan de ger sig längre in i Teldrassils vildmark.",["race:NightElf"]="Alyissia står för kaldoreis disciplin i frontlinjen och rustar försvarare att skydda Aldrassils rötter från korruption."},sec={{t="Krigarmentor i Shadowglen",b="I Aldrassils skyddade fristad undervisar Alyissia unga Night Elf som dras till svärd och sköld snarare än naturmagi eller prästskap. Kaldoreis militär är traditionellt känd för sina Sentinels och smygande bågskyttar, men det farliga läget i dagens Kalimdor kräver beslutsamma frontlinjekämpar. Alyissia lär ut grundläggande tekniker och ser till att nyrekryter kan rikta sin stridsvrede, bemästra sina ställningar och stå emot den aggressiva faunan och de korrumperade grells som tränger in i Shadowglen."}},faq={{q="Vem är Alyissia?",a="Alyissia är en Night Elf-krigartränare i Aldrassil, Shadowglens centrala fristad. Hon ger nybörjarkrigare som påbörjar sin färd i Teldrassil inledande vägledning, träning och enkla kampövningar.",al={"vem är alyissia","alyissia npc","vad gör alyissia"}},{q="Var hittar jag Alyissia?",a="Hon håller till på markplanet i Aldrassils stora ihåliga stam, mitt i Shadowglen i Teldrassil.",al={"alyissias plats","var finns alyissia","hitta alyissia"}},{q="Vilka uppdrag erbjuder Alyissia?",a="Alyissia tar emot Simple Sigil som nya Night Elf-krigare bär med sig. Sigillet presenterar henne som deras krigartränare i Aldrassil.",al={"alyissias uppdrag","uppdrag från alyissia"}}},fx={ce80cb6f={q="På vems sida står Alyissia?",a="Alyissia står helhjärtat på nattalverna i Darnassus och den bredare Alliansens sida. Från sin post i Aldrassil, mitt i Shadowglen, tjänar hon sitt folk genom att lära lovande unga nattalvskrigare grunderna i strid och plikt och hjälpa till att skydda Teldrassil mot hoten omkring ön.",al={"alyissias fraktion","vem alyissia tjänar","alyissia och alliansen"}},["6cc138aa"]={q="Varför är Alyissia här?",a="Alyissia är stationerad i Aldrassil för att vägleda nyvaknade och blivande nattalvskrigare som tar sina första steg i Shadowglen. Hon ser till att de som tar till vapen har den disciplin, stridsteknik och beslutsamhet som krävs för att försvara sin avskilda skogliga fristad.",al={"varför alyissia är i aldrassil","alyissias syfte i shadowglen","vad alyissia gör här"}},["8fbe341c"]={q="Vad vill Alyissia?",a="Alyissia söker dugliga rekryter som kan lära sig stridskonsten och visa sitt mod. Hon vill att nya krigare ska finslipa sin disciplin och sina stridsfärdigheter så att de kan skydda sitt skogshem och hjälpa sina fränder över hela Teldrassil.",al={"alyissias mål","vad alyissia behöver","alyissias motiv"}}},fp="8,143,28.455.0,16.179.0,26.112.0,32.127.0"}
P.entries["npc:amber-kearnen"] = {n="Amber Kearnen",s="I Westfall håller Amber Kearnen uppsikt över Defias Brotherhood åt SI:7. Från en dold utsiktspunkt bevakar hon deras olagliga verksamhet åt Master Mathias Shaw.",h="I Westfall håller Amber Kearnen uppsikt över Defias Brotherhood åt SI:7.",kw={"amber","defias","kearnen","klaven mortwake","klaven's tower","mathias shaw","skurk","si:7","westfall"},ang={["class:Rogue"]="Som Alliance-skurk kan du lita på Agent Kearnen som din fältkontakt när du planerar att infiltrera Klaven's Tower.",["faction:Alliance"]="Som medlem av Alliance kan du se Kearnen som Stormwinds hemliga agent i Westfall, där hon bekämpar Defias Brotherhood utan att oroa befolkningen."},sec={{t="Ögon på tornet",b="Amber Kearnen spanar åt SI:7 i Westfall, långt från Stormwind Keeps salar. Hon bevakar ett övergivet torn som Defias Brotherhood har tagit över. Master Mathias Shaw leder hennes arbete direkt. Kearnen informerar hemliga agenter som skickats för att stoppa Defias hot och samla underrättelser i det omstridda landskapet."},{t="Ett dödligt uppdrag",b="Amber Kearnen håller uppsikt över Klaven Mortwake, en Defias som tagit skydd i tornet sydost om Sentinel Hill. Efter veckor av bevakning informerar hon infiltrerande skurkar om de märkliga, omänskliga vakterna som följde med en leverans från Duskwood. Hon skickar dem för att stjäla tornets nyckel, ta sig in i tornet och ta reda på vad som finns i kistan från Duskwood, däribland Klavens dagbok. Hennes tålamod och noggranna anteckningar hjälper kronans hemliga operationer mot Defias."}},faq={{q="Vem är Amber Kearnen?",a="Amber Kearnen arbetar för SI:7, Stormwinds elitstyrka för underrättelser. Som fältagent och spejare spårar hon Defias verksamhet i Westfall.",al={"amber kearnen","vem är kearnen","agent kearnen"}},{q="Var hittar man Amber Kearnen?",a="Amber Kearnen håller uppsikt i Westfalls vildmark, nära det övergivna Alliance-vakttornet som Defias Brotherhood ockuperar.",al={"amber kearnens plats","var är kearnen","var är amber kearnen"}},{q="Vilken koppling har hon till Mathias Shaw?",a="Amber Kearnen rapporterar direkt till Master Mathias Shaw, SI:7:s ledare. Shaw skickar andra agenter till henne i Westfall för att höra vad hon vet om Defias verksamhet där.",al={"kearnen mathias shaw","vem arbetar kearnen åt"}},{q="Vilken roll har hon i Klaven's Tower?",a="Amber Kearnen bevakar tornet som Klaven Mortwake håller. Hon informerar Alliance-skurkar som SI:7 skickat om hur de kan smyga in, undvika Defias-vakterna och hämta Klavens dagbok.",al={"klavens torn","amber kearnen klavens torn","vad gör hon vid tornet"}}},fx={b2881d9a={q="På vems sida står Amber Kearnen?",a="Amber Kearnen är en lojal agent i Alliansen och tjänstgör i Stormwinds främsta underrättelseorganisation, SI:7. Hon rapporterar direkt till SI:7:s ledning och arbetar i hemlighet ute i fält för att skydda kungariket mot inhemsk omstörtning och fientliga fraktioner.",al={"amber kearnens fraktion","vem amber kearnen arbetar för","är amber kearnen med i alliansen"}},e7eadf92={q="Vad vill Amber Kearnen?",a="Hennes främsta uppdrag är att hålla Defias Brotherhood under uppsikt och sätta stopp för deras verksamhet i Westfall. Hon samlar underrättelser om Klaven Mortwake och hjälper fältagenter som ska infiltrera hans torn och hämta viktiga dokument från Defias Brotherhood.",al={"amber kearnens mål","vad amber kearnen försöker göra","amber kearnens uppdrag"}},e7dcbc70={q="Varför är Amber Kearnen stationerad i Westfall?",a="SI:7 skickade henne till Westfall för att ständigt spana på ett övergivet vakttorn tillhörande Alliansen som Defias Brotherhood har tagit över. Hon håller sig dold i närheten, bevakar fiendens rörelser och ger hemligt stöd åt agenter som skickats för att ta sig in i fästet.",al={"varför amber kearnen är här","varför amber kearnen är i westfall","varför agent kearnen är i westfall"}}},fp="13,139,17.291.0,19.446.1,21.138.0,33.126.0,39.171.0,42.170.0"}
P.entries["npc:anastasia-hartwell"] = {n="Anastasia Hartwell",s="Anastasia Hartwell är en framstående magilärare bland de Fördömda och bor i Undercitys Magic Quarter. Hon vägleder nybörjare och blivande magiker i de arkaniska konsterna och övervakar viktig magisk forskning och fältuppdrag i Lordaeron och bortom.",h="Anastasia Hartwell är en framstående magilärare bland de Fördömda och bor i Undercitys Magic Quarter.",kw={"anastasia","balnir","deino","de fördömda","hartwell","lordaeron","magiker","magic quarter","tabetha","lärare","undercity"},ang={["class:Mage"]="Anastasia Hartwell är en oumbärlig mentor för hordens magiker som passerar genom Undercity. Hon lär ut högre besvärjelsegrader och ger viktiga klassuppdrag.",["faction:Horde"]="Genom samarbeten med lärare som Deino i Orgrimmar förenar Anastasia Lordaerons arkaniska arv med hordens bredare magiska strävanden.",["race:Undead"]="Hon står för att Dalarans och Lordaerons ansedda arkaniska traditioner lever vidare bland de Fördömda, bevarade trots odödens tragedi."},sec={{t="Arkanisk behärskning bland ruinerna",b="I de mörka, ekande salarna i Undercitys Magic Quarter undervisar Anastasia Hartwell Fördömda och hordens magiker i att kanalisera arkaniska energier. Trots att kungadömet Lordaeron föll i ruiner har tidigare mänskliga utövare som Anastasia bevarat sina lärda traditioner i odöden. Hon hävdar att magi kräver strikt disciplin och varnar varje resenär hon möter för att vårdslösa besvärjelser snabbt förgör den som är otränad."},{t="Fältforskning och reliker",b="Utöver grundläggande besvärjelseundervisning leder Anastasia lovande elever till viktiga fältundersökningar. Hon skickar magiker till Balnir Farmstead i östra Tirisfal Glades för att samla snapdragons som visar hur långt pesten har spridit sig, och till Algernon's alchemist shop i Apothecarium för att fånga de osynliga varelserna av ren magi bakom en märklig störning. Genom hennes uppgifter lär sig utövarna att magisk behärskning innebär att möta farorna direkt, även i den egna staden."},{t="Magiutövarnas allierade",b="Anastasias kontakter sträcker sig långt bortom Tirisfals gränser. När hordens magiker blir skickligare samarbetar hon med andra lärare i avlägsna länder, som Deino i Orgrimmar, och hänvisar avancerade elever till ensliga mästare som Tabetha i träskmarkerna i Dustwallow Marsh. Hennes vägledning ser till att Fördömda magiker förblir en del av hordens bredare magiska strävanden."}},faq={{q="Vem är Anastasia Hartwell?",a="Anastasia Hartwell är en magilärare bland de Fördömda i Undercitys Magic Quarter. Hon lär blivande magiker besvärjelser och ger särskilda uppdrag för att hämta arkaniska artefakter och reagenser i Lordaeron.",al={"anastasia hartwell","vem är anastasia","hartwell undercity"}},{q="Var hittar jag Anastasia Hartwell?",a="Hon finns i Undercitys Magic Quarter, bland andra arkaniska utövare och lärare under stadens välvda underjordiska tak.",al={"anastasia hartwells plats","var finns anastasia hartwell","plats för magilärare i undercity"}},{q="Vad säger Anastasia till dem som inte är magiker?",a="Hon ger försiktiga råd till besökare som inte är magiker och varnar dem för att vara vaksamma på magi under sina resor genom världen. Hon påpekar att den lätt bränner den som är otränad.",al={"anastasias skvaller","anastasias dialog","hartwells råd"}},{q="Vilka uppdrag erbjuder Anastasia Hartwell?",a="Anastasia erbjuder olika träningsuppdrag för magiker, bland annat att samla snapdragons vid Balnir Farmstead, undersöka en magisk störning i en alkemistbutik i Apothecarium och ta kontakt med avlägsna lärare som Deino i Orgrimmar och Tabetha i Dustwallow Marsh.",al={"anastasias uppdrag","hartwells uppgifter","magikeruppdrag i undercity"}},{q="Är Anastasia Hartwell släkt med andra Hartwell i Tirisfal?",a="Hon har samma efternamn som Andrew Hartwell och Geoffrey Hartwell, men deras släktskap är obekräftat.",al={"hartwellfamiljen","andrew hartwell","geoffrey hartwell"}},{q="Varför skickar Anastasia magiker till Balnir Farmstead?",a="Hon ber magiker samla Balnir Snapdragons så att hon kan mäta pestens spridning i Tirisfal Glades och skicka blommorna till apotekarna.",al={"balnir farmstead-uppdrag","varför balnir farmstead","hartwell balnir"}}},fx={["686de903"]={q="På vems sida står Anastasia Hartwell?",a="Anastasia Hartwell står helhjärtat på de Fördömdas och Hordens sida. Djupt inne i Undercitys Magic Quarter tjänar hon Lady Sylvanas Windrunner genom att förbereda nyuppväckta magiker på att använda de arkana krafterna till försvar för sitt spirande kungarike.",al={"anastasia hartwells fraktion","vem anastasia hartwell tjänar","anastasia hartwells lojalitet"}},bc0bb7e5={q="Varför är Anastasia Hartwell här?",a="Hon bor i Undercitys Magic Quarter och tränar blivande utövare bland de Fördömda och Horden i arkan magi. Hon vägleder nybörjare och varnar dem som saknar erfarenhet för magins faror, samtidigt som hon skickar dugliga magiker på viktiga uppdrag över Lordaeron och bortom dess gränser.",al={"varför anastasia hartwell är i undercity","vad anastasia hartwell gör här","anastasia hartwells roll"}},["18e123e6"]={q="Vad vill Anastasia Hartwell?",a="Hon vill se till att utövare av arkan magi är disciplinerade, dugliga och försiktiga. Hon påminner ofta utomstående om att vild kraft bränner den som inte behärskar den. Genom krävande uppgifter och magiska undersökningar arbetar hon för att stärka de Fördömdas arkanmagi.",al={"anastasia hartwells mål","vad anastasia hartwells motiv är"}}},fp="18,218,27.341.0,25.418.0,19.358.0,26.169.0,36.155.0,37.102.0,42.291.0,61.116.0,54.141.0"}
P.entries["npc:andron-gant"] = {n="Andron Gant",s="Andron Gant är en tillbakadragen, ofta berusad Forsaken som håller till i Apothecariums dunkla djup i Undercity. Han utför ibland forskningsuppdrag och hämtar reliker åt lokala lärda.",h="Andron Gant är en tillbakadragen, ofta berusad Forsaken som håller till i Apothecariums dunkla djup i...",kw={"andron gant","apothecarium","astor hadren","deathstalkers","jediga","tablet of markri","varimathras"},ang={["class:Rogue"]="Forsaken-skälmar som klättrar i Deathstalkers led får lära sig att Undercitys egna salar kräver lika stor vaksamhet som dess gränser.",["race:Undead"]="Gant är en välbekant syn i Apothecarium, en berusad Forsaken som sällan lämnar staden och förmedlar märkliga ärenden åt dess magiker."},sec={{t="En sluddrande enstöring",b="Andron Gant ligger och drar sig bland Apothecariums giftiga ångor och lämnar sällan Undercitys skyddande stenmurar. För den som ser honom på håll verkar han knappt vara mer än en berusad lärd. Ibland anlitar han äventyrslystna kurirer för att hämta svårfunna reliker, som Tablet of Markri, från avlägsna kuster åt lokala magiker."},{t="Avslöjad av Deathstalkers",b="Gants förrädiska affärer undgick inte Undercitys underrättelsenätverk. När Syndicate skickade en kurir vid namn Astor Hadren för att hämta en förteckning över komprometterade uppgifter, gensköt blivande agenter inom Deathstalkers kuriren. En agent utgav sig för att vara Hadren och lurade den berusade Gant att lämna ifrån sig den belastande förteckningen utan minsta misstanke. Därmed fick Lord Varimathras obestridliga bevis för Gants förräderi mot Forsaken."}},faq={{q="Var hittar jag Andron Gant?",a="Andron Gant finns i Undercity, där han håller till på Apothecarium-distriktets lägre nivåer.",al={"andron gant plats","var finns andron gant","gant plats i undercity"}},{q="Varför är Andron Gant intresserad av Azshara-tavlor?",a="Gant fungerar som mellanhand åt vissa magiker i Undercity och ordnar betalningar till asätare och kontakter som Jediga för att hämta forntida reliker från ruinerna i Azshara.",al={"andron gant azshara","tablet of markri andron gant","varför vill gant ha tavlor"}},{q="Varför utreder Deathstalkers Andron Gant?",a="Deathstalkers undersöker hans affärer med kontakter utanför staden och söker underrättelser om hans forskningsuppdrag.",al={"utredning av gant","andron gants kontakter","åt vem arbetar andron gant"}},{q="Vem leder utredningen av Andron Gant?",a="Deathstalkers utreder Gant på uppdrag av Lord Varimathras och söker underrättelser om hans kontakter och forskning.",al={"vem utreder andron gant","deathstalkers andron gant","varimathras andron gant"}}},fx={["1e42df39"]={q="Vem är Andron Gant?",a="Andron Gant är en Förfallen invånare som ofta besöker Apothecarium i Undercity. Till synes är han inte mycket mer än en vanemässig drinkare som sällan lämnar huvudstaden och förmedlar märkliga lärda uppdrag, som att skaffa forntida tavlor åt lokala magiker.",al={"vem är andron gant","andron gant bakgrund","vem är gant"}},["24992602"]={q="Vems sida står Andron Gant på?",a="Även om han lever bland de Förfallna i Undercity arbetar Gant i hemlighet som informatör åt Syndicate. Han samlar underrättelser i huvudstaden och överlämnar känsliga liggare till Syndicates kurirer, vilket gör honom till en hemlig förrädare mot den Mörka damens rike.",al={"är andron gant lojal","vem tjänar andron gant","andron gants lojalitet"}},e54869d5={q="Vad vill Andron Gant?",a="Offentligt ägnar Gant tiden åt att dricka och förmedla märkliga föremål, till exempel genom att betala äventyrare för att hämta reliker som Tablet of Markri från Azshara åt magikerna i Undercity. I hemlighet går hans främsta arbete ut på att sammanställa känsliga liggare och underrättelser för att sälja dem till Syndicate.",al={"vad vill andron","andron gants motiv","andron gants mål"}},["1151765b"]={q="Varför är Andron Gant i Undercity?",a="Gant håller sig undan i Apothecarium under förevändningen att han är en harmlös, berusad lärd och förmedlare. Undercity ger honom en perfekt täckmantel för att i tysthet samla underrättelser och upprätthålla en hemlig kommunikationskanal till konspiratörer utanför staden.",al={"varför är andron gant här","varför är andron i undercity","andron gant och apothecarium"}}},fp="11,185,18.293.0,29.427.1,29.96.0,49.151.0,49.121.1,47.119.1"}
P.entries["npc:anduin-wrynn"] = {n="Anduin Wrynn",s="Anduin Llane Wrynn är den tioårige krönte kungen av Stormwind och regerar medan hans försvunne far, kung Varian Wrynn, är borta. På grund av sin unga ålder sköts rikets verkliga styre av Highlord Bolvar Fordragon och det kungliga hovet.",h="Anduin Llane Wrynn är den tioårige krönte kungen av Stormwind och regerar medan hans försvunne far, kung...",kw={"anduin","bolvar","pojkkung","prestor","prins","stormwind","tronsal","wrynn"},ang={["faction:Alliance"]="För Alliansens invånare och soldater är kung Anduin en oskyldig symbol för rikets motståndskraft, även om många oroar sig för att hans ungdom gör tronen sårbar för hovintriger i skuggorna.",["race:Human"]="För Stormwinds folk står pojkkungen för Wrynn-dynastins överlevnad och tar sin försvunne far Varians plats."},sec={{t="En pojke på tronen",b="Prins Anduin föddes under den fredliga perioden efter det andra kriget och fick sitt namn efter både sin farfar, kung Llane, och den legendariske riddaren Sir Anduin Lothar. Efter att hans far mystiskt försvunnit på väg till ett diplomatiskt toppmöte i Theramore kröntes barnet hastigt för att bevara stabiliteten i riket. Den tioårige monarken är intelligent och empatisk för sin ålder, men har föga att säga till om i statsärenden. Styret över riket är därför delat mellan Highlord Bolvar Fordragon och hovrådgivaren Lady Katrana Prestor."},{t="En bricka vid hovet",b="Inom Stormwind Keeps förgyllda murar omges unge Anduin av växande politiska spänningar. Highlord Bolvar ansvarar för rikets militära försvar och försöker bevara dess sammanhållning, medan adelskvinnan Katrana Prestor ständigt viskar råd i hovets öra och aktivt motarbetar truppförflyttningar till avlägsna mänskliga bosättningar. Anduin anar hur osäker situationen vid hovet är och saknar sin far djupt, men tills vidare är han en galjonsfigur omgiven av intrigerande adelsmän och vaksamma beskyddare."}},faq={{q="Varför styr ett barn Stormwind?",a="Kung Varian Wrynn försvann under mystiska omständigheter när han seglade mot ett diplomatiskt toppmöte i Theramore. För att undvika en tronföljdskris och bevara ordningen i riket kröntes den tioårige prins Anduin formellt till kung, medan Highlord Bolvar Fordragon utsågs till regent och fick styra i hans ställe.",al={"varför är anduin kung","var är varian","vem är pojkkungen"}},{q="Vem styr egentligen riket just nu?",a="Highlord Bolvar Fordragon är regent över Stormwind. Han för befäl över rikets arméer och har den högsta verkställande makten tills Anduin blir myndig. Adelskvinnan Lady Katrana Prestor är dock en högt uppsatt rådgivare med stort inflytande över det kungliga hovet och adelsrådet.",al={"vem styr stormwind","vem har makten","stormwinds regent"}},{q="Efter vem fick Anduin sitt namn?",a="Han är uppkallad efter två hjältar ur Stormwinds historia: sin farfar, den fallne kung Llane Wrynn, och Sir Anduin Lothar, Azeroths lejon, som ledde Alliansen under det första och andra kriget.",al={"anduins namns ursprung","vem anduin är uppkallad efter","varför heter han anduin"}},{q="Var i staden finns Anduin?",a="Kung Anduin finns i tronsalen i Stormwind Keep, där han sitter på den kungliga tronen med Highlord Bolvar Fordragon och Lady Katrana Prestor tätt intill sig.",al={"var är anduin","anduins plats","anduin wrynns plats"}}},fp="12,261,19.571.0,19.525.0,32.303.1,40.300.0,26.196.0,36.160.0"}
P.entries["npc:apothecary-helbrim"] = {n="Apothecary Helbrim",s="Vid The Crossroads studerar Apothecary Helbrim The Barrens för Royal Apothecary Society. Han har skickats till Kalimdor och samlar in okända ingredienser åt Forsaken.",h="Vid The Crossroads studerar Apothecary Helbrim The Barrens för Royal Apothecary Society.",kw={"apotekare","barrens","crossroads","fungal spores","helbrim","royal apothecary society","zamah"},ang={["faction:Horde"]="Helbrim arbetar nära orciska vakter och tauren-vandrare, men hans driv att samla sporer och gifter gör till och med hans allierade illa till mods.",["race:Undead"]="Som en av Forsaken ser du hur ditt folk bidrar till Horde i Kalimdor: Helbrim gör vildmarken till material för Societys forskning."},sec={{t="Apothecary i dammet",b="Apothecary Helbrim arbetar under den obarmhärtiga solen vid The Crossroads, långt från Royal Apothecary Societys kvarter i Undercitys fuktiga underjord. Han har skickats över Great Sea till Kalimdor och söker efter användbara växter, svampar och andra naturprover i The Barrens. Han är beroende av att resenärer tar med prover åt honom, däribland lokala svampsporer, och samarbetar med Apothecary Zamah i Thunder Bluff. Genom Helbrim når Forsakens alkemister bortom Lordaerons förstörda gränser."}},faq={{q="Vem är Apothecary Helbrim?",a="Helbrim är en alkemist bland Forsaken och agent för Royal Apothecary Society. Han är stationerad vid The Crossroads för att samla in och studera naturliga ingredienser från hela The Barrens.",al={"vem är helbrim","helbrims historia","apotekare i crossroads"}},{q="Varför är en Forsaken-apotekare stationerad i The Barrens?",a="Royal Apothecary Society söker nya föreningar, gifter och ingredienser för sin forskning. Helbrim skickades till centrala Kalimdor för att studera lokala prover, däribland svampsporer som skiljer sig från dem i Lordaerons pesthärjade länder.",al={"varför är han i crossroads","vad gör helbrim här","varför forsaken i barrens"}},{q="Vad gör han med svampsporerna som spelare ger honom?",a="Helbrim studerar svampsporerna för att undersöka deras giftighet, medicinska värde och andra egenskaper. Han förpackar prover som kurirer ska föra till Apothecary Zamah i Thunder Bluff för fortsatta experiment.",al={"helbrim svampsporer","vad används sporer till","uppdrag med svampsporer"}},{q="Vem arbetar Helbrim med?",a="Helbrim lyder under Royal Apothecary Society i Undercity. I Kalimdor samarbetar han med Apothecary Zamah vid The Pools of Vision i Thunder Bluff och gör ibland affärer via goblinmellanhänder som Wharfmaster Dizzywig i Ratchet.",al={"helbrims allierade","vem lyder helbrim under"}}},fx={d7b2fd88={q="Vems sida står Apothecary Helbrim på?",a="Helbrim är en av de Förfallna och lyder direkt under Royal Apothecary Society i Undercity. Som en del av Lady Sylvanas Windrunners folk står han med Horde, även om sällskapet ofta driver sina egna hemliga alkemiska planer, också i allierade områden som The Barrens.",al={"helbrims fraktion","vem tjänar helbrim","tillhör helbrim horde"}}},fp="18,158,22.484.0,26.170.0,54.236.0,57.196.0,27.248.0"}
P.entries["npc:apothecary-johaan"] = {n="Apothecary Johaan",s="Apothecary Johaan är alkemist och forskare vid Royal Apothecary Society, stationerad i Brill. På uppdrag av sin orden och Lady Sylvanas utför han dödliga experiment på den lokala floran och faunan för att utveckla Forsakens nya farsot.",h="Apothecary Johaan är alkemist och forskare vid Royal Apothecary Society, stationerad i Brill.",kw={"apotekare","brill","johaan","farsot","royal apothecary society","silverpine","tirisfal"},ang={["faction:Horde"]="Orcher och tauren kanske ryggar tillbaka för alkemiska farsoter, men Joaahns dödliga brygder tryggar strategiskt Hordens fäste i Eastern Kingdoms.",["race:Undead"]="Joaahns forskning är central för Forsakens sak. Han utvecklar vapnen som behövs för att skapa ett permanent hemland, fritt från Scourge och levande hot."},sec={{t="En tjänare åt sällskapet",b="Apothecary Johaan verkar öppet i Forsakens bosättning Brill i Tirisfal Glades och företräder den nybildade Royal Apothecary Societys vetenskapliga ambitioner. Liksom sina kollegor runtom i Lordaeron arbetar Johaan på direkta order med att skapa biologiska och alkemiska vapen som kan trygga Forsakens osäkra framtid mot både de levande och Scourge."},{t="Brygden av den nya farsoten",b="Johaan samordnar de första fälttesterna av det som sällskapet kallar ”New Plague”. Med råmaterial från Tirisfals fördärvade djurliv och angripna odlingar, som Darkhound Blood, murlocfjäll, spindelgift och stulna gårdspumpor, testar han giftblandningar och bedömer deras styrka på levande försöksobjekt innan han skickar resultaten söderut till Silverpine Forest."}},faq={{q="Vem är Apothecary Johaan?",a="Apothecary Johaan är en alkemisk forskare stationerad i Brill. Han tillhör Royal Apothecary Society och skickar unga Forsaken-mästare för att samla motbjudande ingredienser runtom i Tirisfal Glades.",al={"apothecary johaan","vem är johaan","johaan brill"}},{q="Var hittar jag Apothecary Johaan?",a="Du hittar honom utomhus, nära galgen och alkemisk utrustning i staden Brill, strax norr om Undercity i Tirisfal Glades.",al={"johaans plats","var finns johaan","hitta johaan"}},{q="Vad arbetar Johaan med?",a="Johaan tar fram och förfinar tidiga varianter av The New Plague och testar biologiska ämnen och giftiga extrakt från Tirisfals angripna fält och bestar.",al={"johaans experiment","vad gör johaan","johaans farsot"}},{q="Vad gör han med farsotsproverna?",a="När testblandningarna har tillretts och deras dödlighet bedömts packar Johaan proverna och skickar kurirer med dem till allierade apotekare stationerade i Silverpine Forest.",al={"leverans till silverpine","vart skickas farsotsprover"}},{q="Vilken organisation tillhör Johaan?",a="Han är aktiv medlem i Royal Apothecary Society, det alkemiska gille som tjänar Lady Sylvanas Windrunner och Forsaken i Undercity.",al={"johaans fraktion","vem arbetar johaan för"}},{q="Varför intresserar han sig för de lokala gårdarna?",a="Mänskliga gårdar som Solliden Farmstead och de närliggande pumpafälten odlar pumpor som ger råmaterial till hans experimentella gifter.",al={"fields of grief johaan","varför skickas jag till gårdar"}}},fx={c51cf856={q="Vems sida står Apothecary Johaan på?",a="Johaan tjänar Lady Sylvanas Windrunner och de Förfallna som medlem i Royal Apothecary Society. Från Brill arbetar han för Undercity med att utveckla kemiska vapen och farsoter som ska säkra deras domän mot både Scourge och de levande.",al={"johaans fraktion","vem tjänar johaan","apothecary johaans lojalitet"}},["90913b50"]={q="Varför är Apothecary Johaan i Tirisfal Glades?",a="Johaan är stationerad i Brill för att bedriva fältforskning och samla lokala ingredienser i Tirisfal Glades. Närheten till fördärvad växtlighet, djurliv och omstridda mänskliga bosättningar låter honom samla testreagenser och experimentera direkt på försöksobjekt, långt från Undercitys huvudkammare.",al={"varför är johaan här","varför är apothecary johaan i brill","johaans syfte i tirisfal"}}},fp="17,188,24.322.0,22.341.1,25.163.0,35.153.0,26.146.0,40.134.0,40.140.0,40.141.0"}
P.entries["npc:apothecary-renferrel"] = {n="Apothecary Renferrel",s="Apothecary Renferrel är en framstående medlem av Royal Apothecary Society och är stationerad vid The Sepulcher i Silverpine Forest. Han har i uppdrag att driva Forsakens alkemiska arbete framåt och samordnar omfattande fältstudier av regionens fördärvade djurliv och odöda hot. Resande genom Silverpine hjälper honom ofta att samla flyktiga reagenser och undersöka farliga rester från Scourge.",h="Apothecary Renferrel är en framstående medlem av Royal Apothecary Society och är stationerad vid The...",kw={"apotekare","recept på död","renferrel","rot hide","royal apothecary society","the sepulcher","silverpine","thule ravenclaw"},ang={["faction:Horde"]="Orcher och taurer kan rygga tillbaka inför hans motbjudande biologiska experiment, men Renferrels underrättelsearbete mot Scourge hjälper till att skydda Hordens områden från angrepp norrifrån.",["race:Undead"]="Renferrel förkroppsligar Forsakens pragmatiska och skoningslösa överlevnadsinstinkt. Han gör Lordaerons inhemska växter och djur till vapen för att skapa en trygg framtid åt de frigjorda odöda."},sec={{t="Alkemisten vid The Sepulcher",b="Renferrel verkar från The Sepulcher och är en av Royal Apothecary Societys främsta fältforskare i Silverpine Forest. Undercity rymmer sällskapets storslagna laboratorier och högsta ledning, medan Renferrel sköter det praktiska och leriga arbetet med att säkra biologiska prover från trakten, förädla kraftfulla brygder och analysera den dystra ekologin vid Lordaerons västra gräns."},{t="Undersökningar av Rot Hide och Scourge",b="Renferrel ägnar mycket av sin energi åt Rot Hide-gnollerna och de kringströvande odöda som hemsöker trakten. Genom blod- och vävnadsprover försöker han förstå pestens kvardröjande påverkan och de nekromantiska krafter som binder de lokala monstren. Hans undersökningar leder till en direkt konfrontation med Thule Ravenclaw, en mäktig Scourge-nekromant som verkar nära ruinerna på Fenris Isle."}},faq={{q="Vem är Apothecary Renferrel?",a="Apothecary Renferrel är en alkemist i Royal Apothecary Society, baserad vid The Sepulcher, Forsakens främsta utpost i Silverpine Forest. Han studerar lokala bestar, pestvarianter och fiendestyrkor för att brygga blandningar och säkra regionen åt drottning Sylvanas.",al={"renferrel","vem är renferrel","apothecary renferrels bakgrund"}},{q="Vad forskar Renferrel om i Silverpine?",a="Han fokuserar på att utveckla nya pestsmittor och giftblandningar, allmänt kända som ”Recipe for Death”. Han ber äventyrare samla in hjärtan från grizzlybjörnar, Rot Hide-gnollernas ichor och andra biologiska beståndsdelar för att testa och förfina dödliga blandningar.",al={"renferrels forskning","renferrels experiment","recept på död"}},{q="Vilken koppling har han till Rot Hide-gnollerna?",a="Renferrel studerar Rot Hide-gnollernas fördärvade ichor. Hans inledande tester upptäcker häxmästar- och nekromantisk magi, så han skickar ett prov till Bethor Iceshard i Undercity för vidare undersökning.",al={"rot hide ichor","rot hides ursprung","gnoller i silverpine"}},{q="Varför siktar Renferrel in sig på Thule Ravenclaw?",a="Renferrel undersöker magin bakom Rot Hide-gnollerna och söker Bethor Iceshards hjälp med att identifiera dess källa. Undersökningen leder mot hoten på Fenris Isle.",al={"thule ravenclaws uppdrag","vem är thule ravenclaw","nekromantiker i fenris keep"}},{q="Vart skickar Renferrel äventyrare efter Silverpine?",a="När hans inledande forskning är klar och de lokala hoten har hanterats skickar Renferrel erfarna resande sydost till Hillsbrad Foothills. Där knyts gränsarbetet från The Sepulcher samman med Forsakens större verksamhet i Lordaeron.",al={"efter the sepulcher","leverans till hillsbrad","resa till hillsbrad"}},{q="Vad är Royal Apothecary Society?",a="Royal Apothecary Society är Forsakens vetenskapliga och alkemiska gren, grundad under Lady Sylvanas Windrunner. Sällskapet har sitt högkvarter i Undercity, och dess forskare arbetar outtröttligt med att utveckla nya gifter, motverka naturligt förruttnande och skapa en pest som kan utrota Scourge.",al={"royal apothecary society","ras","forsakens apotekare"}}},fx={["703d1213"]={q="Vems sida står Apothecary Renferrel på?",a="Apothecary Renferrel tjänar de Förfallna och Lady Sylvanas Windrunner som svuren medlem i Royal Apothecary Society. Under Hordes övergripande banér ligger hans lojalitet hos Undercitys alkemister. Han ägnar sina krafter åt att stärka de Förfallnas överlevnad och herravälde mot gemensamma fiender som Scourge och de levande.",al={"renferrels fraktion","vem tjänar renferrel","tillhör apothecary renferrel horde"}},dbc0ae2b={q="Varför är Apothecary Renferrel här i Silverpine Forest?",a="Renferrel är stationerad vid Sepulcher och utför viktig alkemisk fältforskning åt Royal Apothecary Society. Silverpine Forest ger honom tillgång till vildsinta bestar, farlig aktivitet från Scourge och lokala hot som de besmittade Rot Hide-gnollerna, alla viktiga för att samla kraftfulla ingredienser och brygga nya gifter.",al={"varför är renferrel i sepulcher","varför är renferrel där","varför är apothecary renferrel här"}}},fp="20,229,25.349.0,34.323.1,28.250.0,43.241.0,46.189.0,42.177.1,55.228.0,37.264.0"}
P.entries["npc:apothecary-zinge"] = {n="Apothecary Zinge",s="Under Ruins of Lordaeron arbetar Apothecary Zinge för Forsaken. Hon studerar biologiska prover och ordnar forskningsleveranser genom Horde-länderna.",h="Under Ruins of Lordaeron arbetar Apothecary Zinge för Forsaken.",kw={"apothecarium","apothecary zinge","the crossroads","helbrim","royal apothecary society","prover","undercity","zinge"},ang={["faction:Horde"]="Som Horde är du beroende av öppna försörjningsvägar och pålitliga kurirer som korsar havet mellan Kalimdor och Eastern Kingdoms för att hålla dina frontlinjer försörjda.",["race:Undead"]="Som Forsaken kan du se forskare som Zinge i spetsen för ditt folks vetenskapliga självständighet. De arbetar outtröttligt med lösningar som ska säkra Forsakens överlevnad och överhöghet."},sec={{t="I tjänst hos sällskapet",b="Apothecary Zinge arbetar i Apothecarium under Undercity. Under Master Apothecary Faranell söker hon efter kemiska och biologiska ämnen som kan främja Forsakens mål. Hennes arbete förbinder henne med fältforskare och spejare långt bortom Tirisfal Glades, bland annat vid avlägsna utposter i Kalimdor."},{t="Experiment mellan kontinenter",b="Apothecary Zinge är beroende av kurirer och äventyrare som transporterar testmaterial över havet. Hon skriver regelbundet till Apothecary Helbrim vid The Crossroads i The Barrens. Hon skickar giftiga varghjärtan från Silverpine Forest till honom, så att han kan studera hur Lordaerons gifter påverkar Kalimdors bestar."}},faq={{q="Var hittar man Apothecary Zinge?",a="Apothecary Zinge arbetar i Apothecarium, det alkemiska kvarteret på Undercitys sydöstra avsats.",al={"zinge plats","var finns apothecary zinge","apothecary zinge plats"}},{q="Vilken organisation tillhör hon?",a="Apothecary Zinge tillhör Royal Apothecary Society, ett sällskap av Forsaken-alkemister som skapar brygder, farsoter och motgifter i Lady Sylvanas Windrunners tjänst.",al={"zinges fraktion","vem arbetar zinge för"}},{q="Varför behöver hon prover från The Barrens?",a="Proverna skickas från Silverpine Forest till Apothecary Helbrim vid The Crossroads. Zinge låter äventyrare bära giftiga varghjärtan till sin kollega, som studerar hur Lordaerons gifter påverkar Kalimdors bestar.",al={"varför prover från the barrens","helbrims prov","zinges leverans till the barrens"}}},fx={["55fc7dbb"]={q="Vem är Apothecary Zinge?",a="Apothecary Zinge är en alkemist bland de Förfallna och aktiv medlem i Royal Apothecary Society, som har sin bas i Undercity. Hon är hängiven sin orden och dess forskning och brygder, samordnar fältforskning, skickar giftprover till kollegor i avlägsna länder som The Barrens och håller nära kontakt med vänner som Fenstad Argyle.",al={"vem är zinge","apothecary zinge bakgrund","vem är apothecary zinge"}},b56b8970={q="Vems sida står Apothecary Zinge på?",a="Zinge tjänar de Förfallna och Royal Apothecary Society, och sluter direkt upp bakom Lady Sylvanas Windrunner och därmed Horde. Hon är fullt lojal mot Undercitys forskningsarbete och hjälper Horde-äventyrare som är villiga att bistå hennes experiment.",al={"zinges fraktion","vem tjänar zinge","apothecary zinges lojalitet"}},d8143764={q="Varför är Apothecary Zinge inblandad i The Barrens?",a="Zinge är själv stationerad i Apothecarium i Undercity, men låter kurirer föra giftiga varghjärtprover från Silverpine Forest till hennes kollega Apothecary Helbrim vid The Crossroads. Han undersöker hur Lordaerons gifter påverkar bestarna i Kalimdor.",al={"varför är zinge intresserad av the barrens","zinges koppling till the barrens","varför skicka prover till the barrens"}}},fp="16,157,25.315.0,29.296.0,36.109.0,37.177.0,43.203.0"}
P.entries["npc:aramis-hammerhand"] = {n="Aramis Hammerhand",s="Aramis Hammerhand är en odöd helig krigare i Deathknells vanhelgade kapell. Som paladintränare för Forsaken undervisar han nyligen uppväckta döda som vill återknyta banden till det heliga ljuset. Att följa denna väg i odödheten kräver enorm disciplin, eftersom den strålande energin vållar deras förruttnade kroppar plågsam smärta.",h="Aramis Hammerhand är en odöd helig krigare i Deathknells vanhelgade kapell.",kw={"aramis","kapell","deathknell","forsaken","hammerhand","ljus","paladin","tirisfal","tränare"},ang={["class:Paladin"]="För Forsakens paladiner är Aramis den första mentor de möter. Han vägleder dem genom den plåga och andliga disciplin som krävs för att bruka det heliga ljuset i en odöd kropp.",["race:Undead"]="Aramis visar att uppståndelsen till odödhet inte kräver att man överger Lordaerons stolta arv av helig krigföring, även om den innebär ett enormt personligt lidande."},sec={{t="Ett ljus i Deathknell",b="Inom Deathknells dystra kapellmurar är Aramis Hammerhand en ovanlig företeelse bland de nyligen uppväckta Forsaken. I livet hörsammade många av Lordaerons invånare Silver Hand och dog när Scourge svepte fram över norr. Aramis överlevde rikets fall, men uppväcktes som odöd. Ändå valde han att hålla fast vid sitt tidigare livs krigiska och andliga läror. Nu vägleder han andra som vägrar överge sin hängivenhet."},{t="Det heliga ljusets plåga",b="För en odöd är det en prövning av enastående viljestyrka att kanalisera det heliga ljuset. Kraften bränner nekrotiskt kött och väcker sedan länge döda nerver till outhärdlig smärta. Aramis lär sina invigda att denna tro kräver att de uthärdar ständig plåga. Genom uppgifter som 'A Difficult Path' och 'Rediscovering the Light' kräver han att unga paladiner möter de fysiska och andliga kostnaderna för att bruka en kraft som i grunden strider mot deras nuvarande natur."}},faq={{q="Vem är Aramis Hammerhand?",a="Aramis Hammerhand är en paladintränare för Forsaken i kapellet i Deathknell i Tirisfal Glades. Han hjälper nyligen uppväckta odöda som vill följa den heliga stridens väg.",al={"aramis bakgrund","vem är hammerhand","paladintränare i deathknell"}},{q="Kan Forsaken verkligen bruka det heliga ljuset?",a="Ja, genom ren viljestyrka och övertygelse kan Forsaken åkalla det heliga ljuset. Det orsakar dock enorm fysisk smärta, eftersom den strålande energin bränner och skrapar deras ruttnande kött medan den läker eller stärker dem.",al={"kan odöda vara paladiner","hur använder odöda ljuset","forsakens ljus"}},{q="Var hittar jag Aramis Hammerhand?",a="Han står i kapellet i Deathknell, Forsakens startbosättning i Tirisfal Glades.",al={"var finns aramis","hammerhands plats","paladintränare deathknell"}},{q="Vilka uppdrag erbjuder Aramis Hammerhand?",a="Aramis erbjuder flera klasspecifika uppdrag för nyligen uppväckta paladiner, däribland 'A Difficult Path', 'Rediscovering the Light', 'A Light in the Darkness', 'Coming to Terms' och 'Continue Your Training'.",al={"aramis uppdrag","paladinuppdrag i deathknell"}},{q="Varför arbetar en paladintränare för Forsaken?",a="Före pesten var Lordaeron Silver Hands riddarordens vagga. Många av de nyligen befriade Forsaken minns sina eder och vägrar överge sitt heliga kall, trots att de är odöda.",al={"varför finns det paladiner bland forsaken","forsaken och silver hand"}},{q="Läker ljuset odöda på vanligt sätt?",a="Ljuset kan läka deras kroppar och ge dem krigisk styrka, men processen är outhärdlig. Det återaktiverar deras sinnesnerver och tvingar dem att känna sina egna kroppars förruttnelse.",al={"skadar ljuset odöda","lore om ljusets läkning av odöda"}}},fx={["63e97215"]={q="Vems sida står Aramis Hammerhand på?",a="Aramis Hammerhand står stadigt på de Förfallnas sida. Han följer paladinernas disciplin och lär nyväckta odöda att hantera det Heliga ljuset, men hans lojalitet tillhör Queen Sylvanas Windrunner och det kungarike hon bygger i Ruins of Lordaeron.",al={"aramis hammerhands lojalitet","vem tjänar aramis","aramis hammerhands fraktion"}},c81bf44f={q="Varför är Aramis Hammerhand här i Deathknell?",a="Du hittar Aramis i det förfallna kapellet i Deathknell, där han tar emot nyväckta Förfallna. Han väntar på dem som just befriats ur Scourges grepp och som bar heliga eder i livet. Han vägleder dem genom plågan och disciplinen som krävs för att åter tända deras heliga kraft i det odöda livet.",al={"varför är aramis i deathknell","aramis hammerhands plats i deathknell","vad förde aramis hit"}}},fp="17,200,22.384.0,27.320.0,25.133.0,47.173.0,35.112.0,41.185.0,50.190.0,55.165.0"}
P.entries["npc:arcanist-doan"] = {n="Arcanist Doan",s="Arcanist Doan är en mästerlig mänsklig magiker som bor i Athenaeum i Scarlet Monasterys biblioteksflygel. Han tjänar Scarlet Crusade som en av dess dödligaste arkanister och vaktar viktiga arkiv.",h="Arcanist Doan är en mästerlig mänsklig magiker som bor i Athenaeum i Scarlet Monasterys biblioteksflygel.",kw={"arkanist","athenaeum","detonation","doan","bibliotek","scarlet key","scarlet monastery"},ang={["class:Mage"]="Doans mästerskap i arkan försvarsmagi gör hans skyddande bubbla till ett levande exempel på magiskt värn.",["class:Paladin"]="Paladiner finner i Doan en ovanlig arkanist som Scarlet Crusade litar på, en orden som annars sätter Ljusets kraft över alla andra.",["faction:Alliance"]="För Alliansens styrkor visar Doan hur långt Scarlet Crusades fanatism sträcker sig: till och med en mästare på arkan magi binds till dess våldsamma paranoia.",["faction:Horde"]="De Fördömda och deras allierade i Horden ser Doan som en farlig befälhavare för Scarlet Crusade, vars bibliotek gömmer viktig information och nycklar som krävs för att tränga in i korstågets innersta helgedomar."},sec={{t="Athenaeums väktare",b="Medan Scarlet Crusades fanatiska led förlitar sig starkt på stridsraseri och helig glöd, var Doan övertygad om att rå arkansk kraft var nödvändig för att driva bort Scourge från Lordaeron. Djupt inne i klostrets bibliotek anförtroddes han rollen som både lärdomsväktare och operativ portvakt. Han skyddade The Scarlet Key, som säkrar korstågets helgedomar i de norra kungadömena."}},faq={{q="Varför finns en magiker i Scarlet Crusade?",a="Även om korståget domineras av fanatiska paladiner och präster anser Doan bestämt att mästerlig arkan magi är ett oumbärligt vapen för att rena Lordaeron från Scourge.",al={"varför är doan magiker","magiker i korståget","doans magi"}},{q="Vilken koppling har Arcanist Doan till Ashbringer?",a="Ingen är känd. Doan är känd som väktare av Scarlet Monasterys bibliotek och beskyddare av The Scarlet Key, inte som en del av Ashbringers historia.",al={"doan ashbringer","skapade doan ashbringer","ashbringer-kristall"}},{q="Vad vaktar Doan i biblioteket?",a="Doan vakar över klostrets samling av böcker och historiska dokument i Athenaeum. Bakom honom finns en låst kista med The Scarlet Key, en viktig nyckel som öppnar de låsta portarna till klostrets vapenförråd och katedralflygel.",al={"vad släpper doan","scarlet key","varför döda doan"}},{q="Vilken magi använder Doan i strid?",a="Doan är berömd för att kasta en Arcane Bubble som gör honom osårbar medan han kanaliserar en massiv Detonation som fyller hela rummet. Han stör också magiker med områdesbaserad tystnadsmagi och förvandlar hot till får.",al={"doans besvärjelser","doans förmågor","arcanist doans bubbla"}},{q="Var stred Doan under det tredje kriget?",a="Hans bedrifter under det tredje kriget finns inte nedtecknade. I dag är han känd som väktare av Scarlet Monasterys bibliotek, där han skyddar Athenaeum och The Scarlet Key.",al={"doans krigshistoria","var var doan"}},{q="Har Doan några personliga hemligheter?",a="Doan tjänar som arkanist hos Scarlet Crusade. Hans privata kärleksförhållanden är inte dokumenterade i Classic-källorna.",al={"doans historia"}}},fx={["979d2c44"]={q="Vem är Arcanist Doan?",a="Arcanist Doan är en mänsklig magiker och en av de mäktigaste utövarna av arkansk magi inom Scarlet Crusade. Han håller till djupt inne i Athenaeum i Scarlet Monasterys bibliotek, där han vaktar ordens arkiv och The Scarlet Key. Han använder förödande arkan magi för att försvara ordens heliga tillflyktsort.",al={"vem är doan","arcanist doans bakgrund","doan och scarlet monastery"}},["46f867c9"]={q="Vad vill Arcanist Doan?",a="Doan drivs av övertygelsen att arkan magi är det enda verkliga sättet att fullständigt rena Lordaeron från Scourge. Medan hans bröder och systrar i Scarlet Crusade nästan helt förlitar sig på det Heliga ljusets fanatism anser Doan att rå arkan kraft och studier krävs för att hejda och utrota de odödas farsot en gång för alla.",al={"doans mål","vad vill doan","arcanist doans motiv"}},["88b26aa6"]={q="Varför är Arcanist Doan fruktad?",a="Doan fruktas som en av Lordaerons mest formidabla magiker. I strid omsluter han sig med en nästan ogenomtränglig Arcane Bubble medan han laddar förödande Detonation-besvärjelser, som kan förinta hela grupper av inkräktare på ett ögonblick.",al={"varför fruktas doan","hur mäktig är doan","doans rykte"}}},fp="13,220,23.418.0,37.188.0,53.153.0,36.244.0,35.219.0,42.163.0,38.122.0"}
P.entries["npc:archaeologist-flagongut"] = {n="Archaeologist Flagongut",s="Archaeologist Flagongut är en lärd dvärg som företräder Explorers' League och håller till på Deepwater Tavern i Menethil Harbor. Han var på väg till utgrävningen vid Whelgar Excavation Site, men blir en viktig kontakt för fältrapporter som färdas över havet från Darkshore.",h="Archaeologist Flagongut är en lärd dvärg som företräder Explorers' League och håller till på Deepwater Tavern...",kw={"arkeolog","deepwater tavern","explorers' league","flagongut","menethil harbor","remtravel","whelgar"},ang={["faction:Alliance"]="Flagongut fungerar som en logistisk länk mellan nattalvernas länder i Darkshore och Alliansens östra fästen i Khaz Modan.",["race:Dwarf"]="Flagongut visar hur långt Explorers' Leagues ambitioner sträcker sig: till och med ett värdshus vid havet kan bli en utpost där man pusslar ihop titanernas hemligheter."},sec={{t="En lärd i hamnen",b="Archaeologist Flagongut sitter med en mugg i handen på Deepwater Tavern i Menethil Harbor. Liksom många medlemmar i Ironforges Explorers' League reste han västerut genom Khaz Modan för att hjälpa till med upptäckter nära Whelgar Excavation Site i Wetlands. Trots att han befinner sig långt från bibliotekets höga salar håller han kontakten med fältforskare och hjälper till att hantera förlorade reliker och rapporter som förs över Great Sea från avlägsna expeditioner."},{t="Band till fältet",b="Dvärgars nyfikenhet begränsas sällan till en enda kontinent. När Chief Archaeologist Greywhisker i Darnassus skickar vidare det mystiska fossil som den tankspridde Prospector Remtravel grävde fram i Darkshore, blir Flagongut häpen. En gång tog han med sig ett liknande fossil till Explorers' Leagues årliga konferens i Ironforge, övertygad om att det bar på en kraft som på något sätt kunde frigöras."}},faq={{q="Vem är Archaeologist Flagongut?",a="Flagongut är en dvärgforskare från Explorers' League. Han håller till på Deepwater Tavern i Menethil Harbor, där han granskar fältarbetet vid utgrävningar och kommunicerar med utgrävningsplatser.",al={"vem är flagongut","flagongut npc","archaeologist flagongut bakgrund"}},{q="Varför är Flagongut på Deepwater Tavern?",a="Han kom ursprungligen till Menethil Harbor för att ta sig till Whelgar Excavation Site i Wetlands. Medan han är i hamnen använder han värdshuset som bas för att hantera post, inkommande föremål och korrespondens från fjärran länder.",al={"varför är flagongut i menethil","flagonguts plats","vad gör flagongut här"}},{q="Vilken koppling har Flagongut till Darkshore?",a="Prospector Remtravels mystiska fossil från Darkshore skickas vidare till Flagongut av Chief Archaeologist Greywhisker i Darnassus, eftersom det liknar ett fossil som Flagongut en gång tog med sig till en konferens för Explorers' League. Flagongut tror att sådana fossil bär på en kraft som kan frigöras.",al={"flagonguts koppling till darkshore","varför darkshore-uppdrag i wetlands"}},{q="Vilken organisation tillhör han?",a="Han tillhör Explorers' League, King Magni Bronzebeards kungliga samfund som ägnar sig åt att avslöja dvärgfolkets forntida ursprung, reliker och historia i hela Azeroth.",al={"flagonguts fraktion","flagongut explorers' league"}}},fx={c473457f={q="Vems sida står Archaeologist Flagongut på?",a="Archaeologist Flagongut är på Ironforges och Alliances sida. Som agent för dvärgarnas Explorers' League är han lojal mot sitt folk och deras lärda uppdrag att gräva fram och katalogisera forntida reliker över hela den kända världen.",al={"flagonguts fraktion","vem arbetar flagongut åt","flagonguts lojalitet"}},af05d80a={q="Vad vill Archaeologist Flagongut?",a="Flagongut vill avslöja fossilets hemligheter. På vägen till Whelgar's Excavation Site svalde raptorer Stone of Relu, reliken han tror är nyckeln, och han behöver hjälp att återfå den samt sitt ursprungliga fossil, som nu finns hos Prospector Whelgar. Då kan han studera dem tillsammans med Remtravels fossil från Darkshore.",al={"flagonguts mål","vad behöver flagongut","varför prata med flagongut"}}},fp="23,228,17.421.0,17.367.0,31.184.0,41.198.0,40.252.0,36.169.0"}
P.entries["npc:archaeologist-hollee"] = {n="Archaeologist Hollee",s="Archaeologist Hollee är en dvärgisk forskare stationerad i kustbosättningen Auberdine. På uppdrag av dvärgiska utgrävningsintressen håller hon reda på arkeologiska fynd och undersökningar i Darkshores uråldriga, dimhöljda vildmark. Hon samordnar ofta arbetet med prospektörer som söker igenom området efter reliker och geologiska avvikelser.",h="Archaeologist Hollee är en dvärgisk forskare stationerad i kustbosättningen Auberdine.",kw={"archaeologist hollee","auberdine","darkshore","explorers' league","ironforge","prospector remtravel","den tankspridde prospektören","problem i darkshore"},ang={["faction:Alliance"]="Hollee står för samarbetet mellan Eastern Kingdoms och nattalverna och använder Auberdine som bas för att studera Kalimdors avlägsna förflutna.",["race:Dwarf"]="Att se en landsman så långt över havet, i Darkshores dimmiga skogar, påminner om Ironforges gränslösa törst efter att upptäcka forntida historia."},sec={{t="En dvärgisk lärd i kaldoreiernas land",b="Även om Darkshore främst vaktas och befolkas av nattalver, visar närvaron av dvärgiska lärda som Archaeologist Hollee på Ironforges växande nyfikenhet på Kalimdor. Explorers' League skickar representanter långt över haven för att upptäcka spår av forntida historia, och Darkshores ruiner erbjuder lockande mark för studier. Hollee har sin tillfälliga bas i Auberdine och fungerar som regional kontakt för kringvandrande kartläggare och expeditionsgrupper."},{t="Hålla koll på Remtravel",b="En stor del av Hollees dagliga arbete går ut på att hålla reda på sina medarbetare ute i fält, särskilt den tankspridde Prospector Remtravel. Remtravel har fått i uppdrag att utföra omfattande kartläggningar längs den vilda kusten, men vandrar ofta långt bort utan att rapportera tillbaka i tid. Hollee ber ofta resenärer som passerar Auberdine att leta reda på honom, återhämta saknade kartläggningsdata och se till att fältarbetet inte går förlorat till det lokala djurlivet eller hot som rycker närmare."}},faq={{q="Vem är Archaeologist Hollee?",a="Archaeologist Hollee är en dvärg stationerad i Auberdine i Darkshore. Hon bedriver och övervakar regionalt fältarbete på uppdrag av dvärgiska arkeologiska expeditioner på den västra kontinenten.",al={"vem är hollee","hollee darkshore","dvärg i auberdine"}},{q="Var hittar man Hollee?",a="Hon finns i kusthamnstaden Auberdine, på Darkshores västkust.",al={"hollees plats","var finns archaeologist hollee"}},{q="Varför forskar dvärgar i Darkshore?",a="Efter det tredje kriget och den allt starkare alliansen mellan Ironforge och nattalverna har dvärgiska forskare rest till Kalimdor för att studera forntida reliker, geologiska formationer och sedan länge begravd historia som kan kasta ljus över deras eget ursprung.",al={"varför är dvärgar i darkshore","ironforge i kalimdor"}},{q="Vilka problem behöver hon hjälp med?",a="Hollee oroar sig främst för Prospector Remtravel, en tankspridd kartläggare som gav sig av till Darkshores södra delar och inte återvände med sina fynd.",al={"hollees uppdrag","uppdraget med den tankspridde prospektören"}},{q="Vad har Hollee och Prospector Remtravel för relation?",a="De är kollegor som arbetar med samma utgrävningar och kartläggningar i Darkshore. Remtravel utför det praktiska fältarbetet bland ruinerna, medan Hollee samordnar rapporter och har kontakt med resenärer från Auberdine.",al={"vem är remtravel","remtravel och hollee"}},{q="Tillhör Hollee Explorers' League?",a="Hon representerar dvärgiska arkeologiska expeditioner och prospekteringsresor som är allierade med Ironforge. De organiseras vanligtvis under Explorers' League, som verkar från Eastern Kingdoms.",al={"explorers' league hollee","hollees fraktion"}}},fp="20,230,35.339.0,25.347.1,28.149.0,26.85.0,49.221.0,37.145.0,65.200.0,44.203.0"}
P.entries["npc:archbishop-benedictus"] = {n="Archbishop Benedictus",s="I Stormwind City leder Archbishop Benedictus Church of the Holy Light från Cathedral of Light. Han vägleder de troende och alliansen genom osäkra tider.",h="I Stormwind City leder Archbishop Benedictus Church of the Holy Light från Cathedral of Light.",kw={"alonsus faol","ärkebiskop","benedictus","cathedral of light","church of the holy light","eye of paleth","präst","stormwind"},ang={["class:Priest"]="Som präst ser du upp till Archbishop Benedictus, som leder utbildningen, läran och löftena för alla präster i alliansen som överhuvud för Church of the Holy Light.",["faction:Alliance"]="Som medlem av alliansen kan du vända dig till Archbishop Benedictus för moralisk vägledning och andlig tröst åt flyktingar. Han vägleder också högt uppsatta paladiner och befälhavare."},sec={{t="Den heliga Ljusets herde",b="Archbishop Benedictus tog över ledningen för Church of the Holy Light efter att hans mentor, Archbishop Alonsus Faol, hade dött. Han hade sett första och andra kriget ödelägga kungarikena och bidrog till att övervaka bygget av Cathedral of Light i Stormwind City. Han svor att upprätthålla trons dygder. Efter att Lordaeron föll och Scourge växte sig starkt under tredje kriget sökte de mänskliga kungarikena hans andliga vägledning. Från katedralen ger han råd åt det kungliga hovet, utbildar nyinvigda präster och leder heliga korståg mot de odöda och demoniska krafter som hotar Azeroth."},{t="Ett hoppets fyrbåk",b="I hela alliansen betraktar människor Archbishop Benedictus som en mild, vis och välvillig patriark. Han inger allmänheten hopp och samlar hjältar mot mörka hot, däribland Amnennar the Coldbringer i Kalimdor. Han hjälper också till att rena förbannade reliker som trogna äventyrare för med sig."}},faq={{q="Vem är Archbishop Benedictus?",a="Archbishop Benedictus leder Church of the Holy Light och är den högsta religiösa auktoriteten i Grand Alliance. Från Cathedral of Light i Stormwind City vägleder han de troende och ger råd åt kungarikets ledare.",al={"benedictus","ärkebiskop stormwind","ledare för church of the holy light"}},{q="Vilken relation har han till Alonsus Faol?",a="Archbishop Benedictus var Archbishop Alonsus Faols främsta lärjunge. Faol grundade Knights of the Silver Hand. Efter Faols död tog Benedictus över ledningen för Church of the Holy Light och fortsatte sin mentors arbete.",al={"faols lärjunge","alonsus faol benedictus"}},{q="Vilka uppgifter ansvarar Benedictus för åt äventyrare?",a="Archbishop Benedictus leder alliansens hjältar mot Scourge, bland annat på expeditioner till Razorfen Downs för att dräpa lich Amnennar the Coldbringer. Han använder också helig kraft för att rena korrumperade artefakter som Cursed Eye of Paleth.",al={"benedictus uppdrag","vad gör archbishop benedictus"}},{q="Vilken inställning har han till de odöda?",a="Archbishop Benedictus kräver att Forsaken ska få en snabb och permanent död. Hans följeslagare Commander Karl Philips säger att ärkebiskopen bara ber om att deras hjärtan förs tillbaka och bränns i Cathedral of Light.",al={"benedictus forsaken","benedictus syn på scourge"}}},fx={["40ad9930"]={q="Vems sida står Archbishop Benedictus på?",a="Archbishop Benedictus står stadigt med Grand Alliance och Church of the Holy Light. Han bor i Cathedral of Light i Stormwind och tjänar som andlig fader åt både människor och dvärgar. Han vägleder rikets präster och ger råd när King Varian Wrynn är frånvarande.",al={"archbishop benedictus fraktion","tillhör benedictus alliance","vem tjänar benedictus"}},ae63c6cb={q="Vad vill Archbishop Benedictus?",a="Benedictus vill bevara och sprida den Heliga Ljusets dygder i en splittrad värld. Efter att pesten ödelade Lordaeron strävar han efter att skydda de troende, utbilda en ny generation präster och utrota mörk korruption varhelst den hotar Alliansen.",al={"benedictus mål","vad försöker benedictus göra","benedictus motiv"}},["5f68afea"]={q="Varför är Archbishop Benedictus berömd?",a="Benedictus är känd som den Heliga Ljusets kyrkas högsta ledare. Han studerade direkt under den vördade ärkebiskopen Alonsus Faol och hjälpte till att övervaka bygget av Stormwinds magnifika Cathedral of Light. I hela Eastern Kingdoms vördas han som en strålande källa till from visdom och orubbligt ledarskap.",al={"varför är benedictus välkänd","är benedictus berömd","benedictus rykte"}}},fp="21,169,26.598.0,16.287.0,29.226.0,41.211.0,51.240.0,33.221.0"}
P.entries["npc:archmage-ansirem-runeweaver"] = {n="Archmage Ansirem Runeweaver",s="Archmage Ansirem Runeweaver är en äldre mänsklig magiker och en av de styrande medlemmarna i Dalarans råd av sex. Han överlevde Scourges förstörelse av Dalaran under det tredje kriget och övervakar Kirin Tors verksamhet från Violet Citadel medan Dalaran återuppbyggs. Trots att han ägnar sig åt att återuppbygga sin stad har han också diskreta intressen utomlands, däribland en viljestark dotter som rymde till Booty Bay för att bli pirat.",h="Archmage Ansirem Runeweaver är en äldre mänsklig magiker och en av de styrande medlemmarna i Dalarans råd av...",kw={"ansirem","booty bay","catelyn","council of six","dalaran","violet citadel","kirin tor","revilgaz","runeweaver"},ang={["class:Mage"]="Ansirem är en vördad medlem av Council of Six och en bestående auktoritet inom disciplinerade magiska studier.",["faction:Alliance"]="Som ledare för Kirin Tor med bas i Lordaeron står Ansirem fortsatt på Alliansens sida medan mänskliga magiker kämpar för att återta sina länder från kvarlevor av Scourge."},sec={{t="En pelare i Kirin Tor",b="Ansirem Runeweaver är en erfaren magiker som hjälpt till att försvara Dalaran i årtionden. Han sitter i Council of Six, Kirin Tors styrande magokrati. Han överlevde förödelsen när Arthas Menethil och Scourge marscherade mot staden och Archimonde tillkallades. Efter Dalarans fall har Ansirem hjälpt till med arbetet att återuppbygga den magiska staden, vars skyddande sköld togs ner i ett tidigt skede. Nu arbetar han från Violet Citadel."},{t="Intressen i fjärran länder",b="Trots sina lärda plikter och sitt stränga magikermanér har Ansirem personliga band långt bortom Alterac Mountains. Hans viljestarka dotter Catelyn rymde till Booty Bay för att bli pirat och tog med sig en forntida troll-dolk som han hade hittat under sin forskning i Stranglethorn. Han har också haft att göra med Baron Revilgaz där. Han har dessutom ägnat sig åt magiska studier av trollfornföremål och upprätthåller diplomatiska förbindelser mellan avlägsna riken."}},faq={{q="Vem är Archmage Ansirem Runeweaver?",a="Han är en framstående mänsklig magiker och en av de sex styrande ärkemagikerna i Kirin Tors Council of Six. I årtionden har han försvarat Dalaran och övervakar nu verksamheten kring den återuppbyggda staden och dess magiska försvar.",al={"vem är ansirem","ansirem runeweavers historia","vem är ärkemagikern"}},{q="Vad hände med hans dotter?",a="Hans viljestarka dotter Catelyn rymde till Booty Bay för att bli pirat. Där är hon känd som Catelyn the Blade. Ansirem hade gett henne en forntida troll-dolk som han hittat under sin forskning i Stranglethorn, och hon tog med sig den.",al={"ansirems dotter","catelyn the blade","catelyn runeweaver"}},{q="Vilken roll har han i Dalaran?",a="Ansirem är en viktig representant för Kirin Tor i Violet Citadel. Han samordnar forskning, magiskt försvar och kommunikation med allierade medan staden återuppbyggs efter förstörelsen under det tredje kriget.",al={"varför är ansirem i alterac","ansirem dalaran","vad gör han här"}},{q="Kämpade Ansirem i det tredje kriget?",a="Ja. Ansirem har hjälpt till att försvara Dalaran i årtionden och överlevde Scourges belägring av staden, då Arthas vaktade Kel'Thuzads åkallan av Archimonde. Han överlevde stadens förstörelse och hjälper nu till att återuppbygga den.",al={"ansirem scourge","kämpade ansirem mot arthas"}}},fp="27,420,25.428.0,19.452.0,35.233.0,30.233.0,28.213.0,35.217.0"}
P.entries["npc:archmage-malin"] = {n="Archmage Malin",s="Utanför Wizard's Sanctum i Stormwind City leder Archmage Malin det magiska arbetet. Han var tidigare elev till Archmage Trelane och samordnar fältagenter som söker efter magiska artefakter och sällsynta reagenter i Eastern Kingdoms.",h="Utanför Wizard's Sanctum i Stormwind City leder Archmage Malin det magiska arbetet.",kw={"arathi highlands","archmage malin","kryten","mage quarter","malin","skuerto","stormwind","trelane","wizard's sanctum"},ang={["class:Mage"]="Som Alliance-magiker på besök i Wizard's Sanctum ser du hur Malin knyter samman formella studier i Stormwind med farorna som följer av att återfinna förlorade reliker ute i vildmarken.",["faction:Alliance"]="Som Alliance-resenär vet du att Malins agenter i Arathi söker efter mäktiga artefakter innan de hamnar i händerna på Syndicate, Boulderfist-ogrerna eller Horde."},sec={{t="Väktare vid Wizard's Sanctum",b="Archmage Malin är den främsta kontaktpersonen för Stormwinds magiker och håller till nedanför Wizard's Sanctum i Mage Quarter. Han lärde sig magi under Archmage Trelane och arbetar nu för att skydda sin tidigare mästares spridda arv. Medan akolyterna studerar inne i tornet håller Malin uppsikt över sådant i riket som kräver magisk tillsyn."},{t="Blickar mot höglandet",b="Archmage Malin riktar mycket av sin uppmärksamhet norrut, mot de farliga ruinerna i Arathi Highlands. Han skickade sina betrodda medarbetare, Skuerto och Apprentice Kryten, för att återfinna Archmage Trelanes förlorade ägodelar och säkra känsliga besvärjelsekomponenter. Från huvudstaden samordnar Malin deras arbete och förlitar sig på dugliga Alliance-resenärer som kan föra instruktioner, förnödenheter och underrättelser till hans agenter i fientligt territorium."}},faq={{q="Vem är Archmage Malin?",a="Archmage Malin är en högt uppsatt mänsklig magiker i Stormwind City. Utanför Wizard's Sanctum i Mage Quarter övervakar han forskning, skickar ut lärlingar på uppdrag och hjälper till att upprätthålla ordningen bland huvudstadens magiker.",al={"archmage malin bakgrund","vem är malin","malin stormwind"}},{q="Vilken koppling har Malin till Archmage Trelane?",a="Archmage Trelane var Archmage Malins mästare och mentor. Malin är fortfarande djupt lojal mot Trelane och samordnar försöken att hitta och återta sin tidigare mästares tillhörigheter och magiska reliker i Arathi Highlands.",al={"malin trelane","vem var malins mästare","archmage trelanes koppling"}},{q="Varför skickar Malin äventyrare till Arathi Highlands?",a="Archmage Malin skickar resenärer för att nå sina agenter, Skuerto och Apprentice Kryten, i Arathi Highlands. Resan är farlig och det är svårt att kommunicera, så han behöver att de tar med sig önskemål, magiska förnödenheter och instruktioner för att återta Trelanes artefakter.",al={"malins uppdragsförfrågan","varför arathi","skuerto uppdrag"}},{q="Var hittar man Archmage Malin?",a="Archmage Malin står utanför ingången till Wizard's Sanctum vid tornets fot, i Stormwind Citys Mage Quarter. Därifrån har han utsikt över ramperna som leder upp till sanctumets portalrum.",al={"var finns malin","archmage malin plats","malin karta"}}},fx={deac5a59={q="Vilken sida står Archmage Malin på?",a="Archmage Malin är lojal mot Alliansen och tjänstgör i Stormwind City. Han har en framträdande plats utanför Wizard's Sanctum i Mage Quarter, arbetar nära andra mänskliga magiker och förlitar sig på betrodda agenter och äventyrare från Alliansen för att utföra sina uppdrag i Eastern Kingdoms.",al={"tillhör malin alliansen","malins fraktion","vem tjänar malin"}},["77b45b55"]={q="Varför är Archmage Malin här i Stormwind?",a="Archmage Malin står utanför Wizard's Sanctum för att samordna magiska insatser och övervaka verksamhet utanför huvudstaden. Han stannar i Stormwind men skickar agenter som Skuerto och Apprentice Kryten till avlägsna, farliga trakter som Arathi Highlands. Han ber dugliga resenärer som passerar staden att hjälpa dem.",al={"varför är malin i stormwind","malins syfte vid wizard's sanctum","varför står malin utanför sanctum"}}},fp="14,230,31.318.0,21.374.0,22.228.0,47.193.0,56.265.0,34.198.0"}
P.entries["npc:archmage-xylem"] = {n="Archmage Xylem",s="Archmage Xylem är en excentrisk och tillbakadragen mänsklig magiker som bor i ett ensligt torn på klipporna i norra Azshara. Han är känd för sitt häftiga humör och sina farliga experiment, och har dragit sig undan världen för att ägna sig åt esoterisk forskning inom magins område. För att nå honom krävs magisk teleportering, och han tar bara emot äventyrare som kan hjälpa honom med hans säregna studier eller personliga vendettor.",h="Archmage Xylem är en excentrisk och tillbakadragen mänsklig magiker som bor i ett ensligt torn på klipporna i...",kw={"magi","ärk magiker","azshara","morphaz","sanath lim-yo","torn","xylem"},ang={["class:Mage"]="För magiutövare står Xylem för både fulländat mästerskap och den oroande följden av total isolering i jakten på magisk kraft.",["faction:Horde"]="Trots att han är människa är den tillbakadragne magikern förvånansvärt villig att förhandla med hordens förkämpar som kan hjälpa honom med hans studier.",["race:Human"]="Till skillnad från de formella magikerna i Dalaran eller Stormwind har Xylem helt vänt människosamhället ryggen för att leva ostörd i Azsharas vildmark."},sec={{t="En enstöring ovanför kusten",b="Högt uppe på de taggiga klipporna i norra Azshara har Archmage Xylem sitt hem i en avskild tornspira med utsikt över den förstörda kust där alverna en gång bodde. I stället för att anlägga en väg eller stig isolerade magikern sin fristad helt och hållet. Han förlitar sig på sin tjänare Sanath Lim-yo, som magiskt transporterar godkända besökare uppför klippväggen. Över hela Kalimdor betraktas han som djupt excentrisk och farlig att ha att göra med. Till och med andra lärda är mycket försiktiga med honom och påpekar att han inte liknar nästan någon annan mänsklig magiker."},{t="Ett agg mot Morphaz",b="Xylems avskildhet är inte helt fridfull; han hyser ett starkt agg mot den gröna drakflykten, i synnerhet mot en drake vid namn Morphaz. En gång slukade besten en av Xylems olyckliga lärlingar hel, tillsammans med en magisk skärva med enorm kraft. I stället för att sörja lärlingen är den hämndlystne ärkemagikern fortfarande besatt av att jaga rätt på Morphaz och ta den dyrbara artefakten ur drakens mage."}},faq={{q="Hur tar du dig till Archmage Xylems torn?",a="Archmage Xylems torn står på en otillgänglig klippa i norra Azshara, utan någon gångväg upp. För att nå honom måste du hitta hans tjänare Sanath Lim-yo, som står nära klippornas fot och kan teleportera resenärer magiskt upp till tornområdet.",al={"ta sig till xylem","nå xylems torn","teleportera till xylem","xylems plats"}},{q="Vem är Archmage Xylem?",a="Han är en excentrisk mänsklig ärkemagiker som bor i ett ensligt torn på en klipptopp i norra Azshara, där han utför farliga magiska experiment långt från civilisationen.",al={"vem är xylem","archmage xylems historia","xylems bakgrund"}},{q="Varför vill Xylem att draken Morphaz ska dö?",a="Den gröna draken Morphaz angrep Xylems anhängare och slukade en av hans lärlingar hel. Lärlingen bar på en skärva med väldig magisk kraft, och Xylem vill att draken ska dö så att reliken kan återtas ur dess mage.",al={"xylem morphaz","varför döda morphaz","morphaz skärva"}},{q="Varför säger folk att Xylem är farlig?",a="Lokala kontakter som Jediga varnar resenärer för att Xylem är oberäknelig, avskärmad från omvärlden och märklig på ett sätt som skiljer sig tydligt från andra människor.",al={"är xylem farlig","är xylem galen","xylems personlighet"}},{q="Tillhör Xylem Alliansen eller Kirin Tor?",a="Xylem verkar som en fullständigt självständig eremit. Han tjänar inte aktivt Alliansens militär och gör gärna affärer med alla äventyrare som är villiga att göra hans ärenden, oavsett fraktion.",al={"xylems fraktion","tillhör xylem alliansen","xylem kirin tor"}}},fp="14,410,25.521.0,24.442.1,40.269.0,22.158.0,44.235.0,37.125.0,51.191.0"}
P.entries["npc:argent-guard-manados"] = {n="Argent Guard Manados",s="Argent Guard Manados är en Night Elf-vaktpost i Darnassus, utsänd på uppdrag av Argent Dawn. Han vilar vid Craftsmen's Terrace, håller uppsikt över den växande korruptionen i Kalimdor och vägleder äventyrare mot de onda krafter som lurar i Blackfathom Deeps.",h="Argent Guard Manados är en Night Elf-vaktpost i Darnassus, utsänd på uppdrag av Argent Dawn.",kw={"argent dawn","argent guard manados","blackfathom deeps","craftsmen's terrace","darnassus","manados","twilight falls"},ang={["faction:Alliance"]="För Alliansens förkämpar som besöker Darnassus är Manados en viktig länk mellan korstågen i det avlägsna Lordaeron och kultisternas växande hot i norra Kalimdor.",["race:NightElf"]="Manados visar att inte alla Night Elves begränsar sin plikt till Cenarion Circle eller Sentinels. Vissa viger sina liv åt neutrala organisationer som Argent Dawn, öppna för alla fraktioner, för att bevara Azeroth."},sec={{t="En väktare för gryningen",b="Medan större delen av Argent Dawn riktar sin vaksamhet mot Lordaerons härjade marker och Scourge, vakar Argent Guard Manados för deras räkning i Night Elf-folkets huvudstad Darnassus. Bland hantverkare och handelsfolk på Craftsmen's Terrace håller Manados utkik efter nya hot mot balansen i norra Kalimdor. När rykten når honom om att kulten Twilight's Hammer har fått ett fäste under Ashenvales vågor, värvar Manados dugliga hjältar för att slå till mot Blackfathom Deeps och återta artefakter från deras mörka dyrkan."}},faq={{q="Vem är Argent Guard Manados?",a="Manados är en Night Elf-agent från Argent Dawn som är stationerad i Darnassus. I stället för att bekämpa Scourge i Eastern Kingdoms stannar han i Kalimdor för att hålla utkik efter mörka sekter och utomvärldslig korruption.",al={"vem är manados","argent guard manados roll","manados darnassus"}},{q="Var hittar jag Argent Guard Manados?",a="Han står vid Craftsmen's Terrace i Darnassus, där han vakar över staden och samordnar arbetet med lokala äventyrare.",al={"manados plats","var finns argent guard manados","manados craftsmen's terrace"}},{q="Vilka uppdrag ger Argent Guard Manados?",a="Han erbjuder uppdraget 'Twilight Falls', där äventyrare ska ta sig in i Blackfathom Deeps i Ashenvale och hämta Twilight Pendants från kultisterna som gömmer sig där inne.",al={"manados uppdrag","uppdragsgivare för twilight falls","argent dawn-uppdrag i blackfathom deeps"}},{q="Varför är Argent Dawn intresserade av Blackfathom Deeps?",a="Argent Dawn bekämpar onda krafter som hotar Azeroth. Att kulten Twilight's Hammer plötsligt dykt upp och dyrkar uråldriga, korrumperade väsen i Ashenvales översvämmade ruiner är en fara de inte kan ignorera.",al={"varför argent dawn i blackfathom deeps","argent dawn och twilight-kulten"}}},fx={df5dd966={q="Vilken sida står Argent Guard Manados på?",a="Argent Guard Manados tjänar Argent Dawn, en oberoende orden som är hängiven åt att utrota ondska och skydda Azeroth från mörk korruption. Han är en nattalv stationerad i Darnassus huvudstad, men hans främsta lojalitet gäller gryningens globala korståg snarare än Alliansens vanliga befälskedja.",al={"manados fraktion","vem tjänar manados","tillhör manados alliansen"}},f4cc0234={q="Vad vill Argent Guard Manados?",a="Manados vill stoppa de mörka ritualer som får fäste längs Ashenvales kust. Han värvar dugliga äventyrare för att ta sig in i Blackfathom Deeps och slå till mot skymningshammarns kultister som har vanhelgat nattalvernas forntida helgedom.",al={"vad letar manados efter","manados mål","varför skicka någon till blackfathom"}}},fp="20,175,22.472.0,28.193.0,38.136.0,43.143.0,55.215.0"}
P.entries["npc:argos-nightwhisper"] = {n="Argos Nightwhisper",s="I Stormwinds Park visar Argos Nightwhisper Alliansens resenärer vägen mot Darkshore. Hans bror Gershala studerar den korruption som sprider sig där.",h="I Stormwinds Park visar Argos Nightwhisper Alliansens resenärer vägen mot Darkshore.",kw={"argos","auberdine","korruption utomlands","darnassus","kaldorei","nightwhisper","parken","stormwind"},ang={["faction:Alliance"]="Som Alliansens hjälte kan du se Argos som en länk mellan Eastern Kingdoms och Kalimdor. Han uppmuntrar unga hjältar att korsa havet och hjälpa nattalverna.",["race:NightElf"]="Som kaldorei långt från Kalimdor kan Argos kännas som ett välbekant ansikte. Han visar resenärer vägen till sin bror i Darkshore och till hoten mot deras hemland."},sec={{t="En kaldorei i människornas huvudstad",b="Argos Nightwhisper bor bland de nattalver som samlas i Stormwinds Park. Områdets stilla dungar påminner om kaldoreiernas förfäders skogsland. Liksom andra av sitt folk som tjänstgör i människoriket knyter Argos samman de nya allierade på andra sidan Stora havet. Rapporterna från andra sidan havet oroar honom. Han uppmanar dugliga Alliansens hjältar att resa till Auberdine i Darkshore, där hans bror Gershala behöver hjälp med den korruption som sprider sig."}},faq={{q="Vem är Argos Nightwhisper?",a="Argos Nightwhisper är en nattalv som bor i Stormwind City. Han företräder Darnassus i Alliansens östra huvudstad, hjälper resenärer och visar dem vägen till färden till Kalimdor.",al={"argos nightwhisper","vem är argos","argos stormwind"}},{q="Var hittar man Argos Nightwhisper?",a="Du hittar Argos i Parken, det grönskande området i Stormwind City där besökande nattalver samlas.",al={"argos plats","var är argos","hitta argos nightwhisper"}},{q="Vad ber Argos äventyrare att göra?",a="Argos ber erfarna äventyrare att resa till Auberdine i Darkshore, där hans bror Gershala behöver hjälp med att studera korruptionen som sprider sig genom landet.",al={"korruption utomlands uppdrag","argos uppdrag","varför resa till darnassus"}},{q="Är Argos släkt med andra Nightwhispers?",a="Ja. Argos är bror till Gershala Nightwhisper, en nattalvslärd i Auberdine i Darkshore. Därför skickar Argos resenärer dit.",al={"nightwhisper-familjen","argos släktingar"}}},fx={["50b5b885"]={q="Vilken sida står Argos Nightwhisper på?",a="Argos Nightwhisper står stadigt på Alliansens och sitt kaldoreiska folks sida. Som nattalv bland sändebud och resenärer i Stormwinds Park är han lojal mot Darnassus och hjälper resenärer och hjältar som arbetar för Alliansens försvar och välmående.",al={"argos nightwhispers fraktion","tillhör argos alliansen","vem tjänar argos"}},e48f5556={q="Varför är Argos Nightwhisper i Stormwind?",a="Argos håller till i Park, den grönskande fristad som reserverats för nattalver i Stormwind City. Liksom många av sina fränder i människornas huvudstad tjänar han som sändebud och kontakt mellan Darnassus och Eastern Kingdoms. Han söker dugliga förkämpar som kan hjälpa till med kaldoreiska angelägenheter utomlands.",al={"varför är argos i stormwind","varför är argos nightwhisper här","vad gör argos i stormwind"}}},fp="18,144,31.434.0,26.165.0,38.98.0,38.152.0,40.139.0"}
P.entries["npc:arugal"] = {n="Arugal",s="Ärkemagikern Arugal är en före detta magiker från Dalaran som släppte lös de vilda worgen över Lordaeron. Överväldigad av vansinne och sorg härskar han nu från Shadowfang Keeps höjder. Där behandlar han de vilda bestarna som sina älskade barn och hotar hela Silverpine Forest.",h="Ärkemagikern Arugal är en före detta magiker från Dalaran som släppte lös de vilda worgen över Lordaeron.",kw={"arugal","kirin tor","pyrewood","shadowfang","silverlaine","silverpine","ur","worgen"},ang={["class:Mage"]="Arugal visar hur katastrofal vårdslös besvärjelsekonst kan vara och hur Kirin Tors djupa forskning kan förvandlas till en okontrollerbar mardröm.",["faction:Horde"]="Arugals worgen härjar längs vägen söder om The Sepulcher, och Lady Sylvanas har beordrat att han ska avrättas för att säkra Silverpine Forest åt Forsaken.",["race:Undead"]="Arugals bestar har dödat flera Deathstalkers och apotekare. Att sätta stopp för hans vansinne är en livsviktig uppgift för Royal Apothecary Society."},sec={{t="En desperat kallelse",b="Före Lordaerons fall tillhörde Arugal Kirin Tor, även om vissa jämlikar, som Dalar Dawnweaver, avfärdade honom som en charlatan vars svaga magi till stor del byggde på förtrollade prydnader. När Scourge svepte fram över norr under det tredje kriget sökte Arugal ett vapen mäktigt nog att hejda framryckningen. Med hjälp av den avlidne Dalaranmagikern Urs esoteriska forskning genomborrade Arugal slöjan mellan världarna och kallade worgen till den dödliga världen. De glupska bestarna slet igenom de odödas legioner, precis som avsett, men deras vilda ursinne gick inte att tygla, och deras grymma hunger vändes snart mot oskyldiga dödliga."},{t="Faller i vansinne",b="De frammanade fasorna slaktade inte bara Scourge, utan vände sig snart också mot magikerna själva. Bestarna belägrade sedan Baron Silverlaines urgamla säte, och borgen föll snabbt för klor och huggtänder. Dess herre och hans följe dödades i massakern. I stället för att fly från sin monstruösa skapelse bröts Arugals sinne sönder av skulden, och han tog bestarna till sig som sina egna barn. Han döpte om fästningen till Shadowfang Keep och befäste sin ställning innanför dess murar, omgiven av vålnaderna från offren och trogna flockar av hunddjur."},{t="Silverpine Forests gissel",b="Från sin höga utkikspunkt i Shadowfang Keep utsträcker Arugal sitt förvridna välde över landsbygden. Hans mörka trolldom sveper in Pyrewood Village, där invånarna lever under en nattlig förbannelse, och förpestar Deep Elem Mine med glupska Moonrage-bestar. Forsaken ser honom nu som ett outhärdligt hot. Sylvanas Windrunners Deathstalkers och apotekare smider aktivt planer på att avrätta den vansinnige ärkemagikern för att säkra gränserna till sitt spirande rike."}},faq={{q="Vem är Arugal?",a="Arugal är en före detta mänsklig ärkemagiker från Kirin Tor. Under det tredje kriget kallade han fram de monstruösa worgen för att bekämpa Scourge. Överväldigad av sina handlingar drog han sig tillbaka till Shadowfang Keep, där han nu leder worgenflockar som deras självutnämnde fader.",al={"vem är arugal","arugals bakgrund","lore om bossen i shadowfang"}},{q="Varför kallade Arugal fram worgen?",a="Under det tredje kriget hotade Scourge att översvämma norra Lordaeron. I desperation sökte Arugal ett vapen för att hejda de odöda och använde sig av Dalaranmagikern Urs forskning om andra världar. Han trodde att de vilda bestarna kunde förgöra Scourge, men förlorade kontrollen över dem så snart de hade kallats fram.",al={"varför worgen","varför kalla fram bestar","arugals motiv med worgen"}},{q="Var bor Arugal just nu?",a="Arugal har sitt näste på toppen av Shadowfang Keep, en uråldrig fästning med utsikt över Pyrewood Village i södra Silverpine Forest. Han vaktas av sitt monstruösa vargdjur Fenrus, tillsammans med svärmar av trogna worgen och rastlösa andar.",al={"var är arugal","arugals plats","hitta arugal"}},{q="Vad hände med Baron Silverlaine?",a="Baron Silverlaine var den adlige herre som ursprungligen härskade över fästningen och byn Pyrewood. När Arugals worgen belägrade borgen slaktades Silverlaine och hans hov brutalt. Deras hämndlystna, plågade vålnader hemsöker nu borgens blodfläckade salar.",al={"baron silverlaines öde","vem ägde shadowfang","borgens historia"}},{q="Varför vill Forsaken döda Arugal?",a="Arugals flockar terroriserar Silverpine Forest, angriper Forsakens spejare, överfaller patruller och smittar till och med trogna tjänare inom Royal Apothecary Society. Sylvanas Windrunner ser den vansinnige ärkemagikern som ett direkt hot mot säkerheten och utvidgningen av Undercitys gränser.",al={"forsaken mot arugal","uppdraget att döda arugal","varför döda arugal"}},{q="Vad är förbannelsen över Pyrewood Village?",a="Arugal lade fördärvliga förtrollningar över trakten och utsatte invånarna i Pyrewood Village för worgenförbannelsen. I dagsljus ser byborna ut som vanliga människor, men när natten faller förvandlas de till vildsinta bestar, bundna att försvara Arugals territorium.",al={"förbannelsen över pyrewood","varför är byborna i pyrewood vargar","pyrewood arugal"}}},fx={c709d248={q="Vilken sida står Archmage Arugal på?",a="Arugal tjänar varken Alliansen eller Horden. Han var en gång medlem av Dalarans Kirin Tor, men bröt alla band efter att ha fallit i vansinne. Nu leder han sin egen vilda flock i Shadowfang Keep. Han ser worgen som sina verkliga barn och stöter våldsamt bort både Kirin Tors sändebud och de Fördömda.",al={"arugals fraktion","vem tjänar arugal","är arugal med horden eller alliansen"}},["5a0ecd53"]={q="Vad vill Archmage Arugal?",a="Efter att ha släppt worgen lösa i världen förtärs Arugal av skuld och vansinne. Nu vill han skydda, styra och utöka sin flock. Med förtrollad magi binder han bestarna till sin vilja och sprider worgenförbannelsen genom Silverpine Forest för att bygga sin mörka familj och slakta alla som vågar tränga in på hans område.",al={"arugals mål","vad försöker arugal göra","arugals motiv"}},["127eccbf"]={q="Varför är Archmage Arugal i Shadowfang Keep?",a="När de tillkallade worgen bröt sig loss anföll de fästningen som tillhörde Baron Silverlaine ovanför Pyrewood Village. Arugal drevs till vansinne av katastrofen han hade orsakat, tog de vildsinta bestarna till sig som sina barn, övertog den förstörda borgen och döpte om den till Shadowfang för att härska över sin flock i avskildhet.",al={"varför är arugal här","varför tog arugal sig till shadowfang","hur fick arugal shadowfang keep"}},["760497b6"]={q="Varför är Archmage Arugal fruktad?",a="Arugal är ökänd i hela Lordaeron för att ha utnyttjat Urs förbjudna forskning och släppt de vilda worgen lösa i världen. Förbannelsen han framkallade dödade inte bara de vandöda. Den smittade närliggande trakter, förvandlade fridfulla bybor till blodtörstiga bestar och gjorde en hel region till en mardröm under hans oberäkneliga magiska kontroll.",al={"varför är arugal berömd","arugals rykte","varför är arugal farlig"}}},fp="6,208,19.543.0,17.462.0,25.422.1,14.242.0,33.282.0,35.225.0,35.220.0,37.264.0,38.218.0"}
P.entries["npc:ashlan-stonesmirk"] = {n="Ashlan Stonesmirk",s="Ashlan Stonesmirk är en dvärgisk sprängämnesexpert som tjänstgör vid regementet som bevakar Dun Modr och Thandol Span i norra Wetlands. Därifrån håller han vaksam uppsikt över regionala faror som hotar Ironforges rike.",h="Ashlan Stonesmirk är en dvärgisk sprängämnesexpert som tjänstgör vid regementet som bevakar Dun Modr och...",kw={"ett mörkt hot tornar upp sig","ashlan","dun modr","ironforge","loch modan","stonesmirk"},ang={["faction:Alliance"]="När du hjälper Ashlan säkrar du den strategiska korridoren som förbinder Loch Modan med Wetlands och Alliansens nordliga territorier.",["race:Dwarf"]="Stonesmirk står för de skickliga specialisterna som stöder Ironforges soldater längs Khaz Modans gränser."},sec={{t="Expert vid gränsen",b="Ashlan Stonesmirk är stationerad i Dun Modr i norra Wetlands och tjänstgör vid regementet som bevakar Thandol Span. Hans kunskaper om sprängämnen gör honom till en användbar kontakt när misstänkta material hotar dvärgarnas försvar."},{t="Ett mörkt hot tornar upp sig",b="När chefsingenjör Hinderweir hittar ett misstänkt pulver nära Stonewrought Dam skickar han det till Ashlan för undersökning. Ashlan identifierar pulvret som Seaforium och ger råd om hur det ska oskadliggöras."}},faq={{q="Var hittar jag Ashlan Stonesmirk?",a="Under den här perioden är Ashlan Stonesmirk stationerad i Dun Modr i norra Wetlands, nära Thandol Span.",al={"ashlans plats","var finns ashlan stonesmirk","ashlan stonesmirk plats"}},{q="Vilken roll har Ashlan Stonesmirk?",a="Han är en dvärgisk sprängämnesexpert som tjänstgör vid regementet som bevakar Dun Modr och Thandol Span. Hinderweir vänder sig till honom för att identifiera ett misstänkt pulver som hittats nära Stonewrought Dam.",al={"vem är ashlan stonesmirk","ashlans uppgift","vad gör ashlan"}},{q="Vilka uppdrag erbjuder Ashlan?",a="Han hjälper äventyrare under ”A Dark Threat Looms” genom att undersöka misstänkt pulver som chefsingenjör Hinderweir skickat.",al={"ashlans uppdrag","uppdrag från ashlan stonesmirk"}}},fx={["0cdc60de"]={q="Vem är Ashlan Stonesmirk?",a="Ashlan Stonesmirk är en dvärgisk sprängämnesexpert stationerad med regementet i Dun Modr i norra Wetlands.",al={"vem är ashlan","ashlan stonesmirks bakgrund","vem är ashlan stonesmirk"}},c5f8e74c={q="Vilken sida står Ashlan Stonesmirk på?",a="Han tjänar Ironforge och Alliansen och hjälper till att försvara norra Wetlands och upptäcka hot mot dvärgarnas byggnadsverk.",al={"ashlan stonesmirks fraktion","tillhör ashlan alliansen","vem tjänar ashlan stonesmirk"}},["82d01692"]={q="Varför är Ashlan Stonesmirk här?",a="Ashlan är stationerad i Dun Modr, där hans kunskaper om sprängämnen hjälper dvärgarnas regemente och resenärer som undersöker hotet mot Stonewrought Dam.",al={"varför är ashlan i loch modan","ashlan stonesmirks lägers syfte","varför är ashlan nära mogrosh"}}},fp="17,171,23.210.0,19.192.1,35.91.0,33.193.0,30.114.0"}
P.entries["npc:asterion"] = {n="Asterion",s="Asterion är en uråldrig Highborne-ande bunden till ruinerna av Bashal'Aran i Darkshore. För tiotusen år sedan var han den betrodde ställföreträdaren åt guvernören Athrikus Narassin, men fängslades av okänd anledning i ett magiskt månsten sigill som höll honom fången genom livet och in i efterlivet. Än i dag är hans vålnad fjättrad vid den förstörda helgedomen, omgiven av demoniska bestar och drömmande om frihet.",h="Asterion är en uråldrig Highborne-ande bunden till ruinerna av Bashal'Aran i Darkshore.",kw={"ameth'aran","asterion","athrikus","bashal'aran","darkshore","highborne","månsten","narassin","satyr"},ang={["class:Mage"]="I livet var Asterion hyllad för sin behärskning av mystisk magi och sin skicklighet i närstrid, vilket gör honom till ett fascinerande exempel på tidig kaldoreisk magi.",["faction:Alliance"]="Asterion är en av de sällsynta Highborne-andar som är villiga att lita på och hjälpa äventyrare från Alliansen. Han ber dem om hjälp att bryta sitt tiotusen år gamla fängelse.",["race:NightElf"]="Asterion är en tragisk kvarleva från tiden före Klyvningen och visar den grymma interna maktkamp som förtärde Highborne redan innan Azshara bjöd in den brinnande legionen till deras land."},sec={{t="En tjänare av forntida prakt",b="Innan den stora Klyvningen krossade det uråldriga Kalimdor var Bashal'Aran och Ameth'Aran systerstäder, välsignade av drottning Azshara själv. Azshara utsåg Athrikus Narassin till att styra de två bosättningarna, och Asterion var hans högra hand. Asterion var respekterad både för sin skicklighet i närstrid och sin behärskning av mystisk magi. Han levde bland folket i Bashal'Aran och reste ofta mellan systerstäderna för att sköta invånarnas behov."},{t="Månstenens fängelse",b="Av skäl som gått förlorade med tiden föll Asterion i onåd hos sin herre. Athrikus skapade ett mäktigt månsten sigill och smidde en magisk bur utan möjlighet till flykt för att hålla Asterion fången i Bashal'Aran. Fångenskapen sträckte sig över århundraden av plågsam instängdhet. Än värre var att Asterion, när han till slut dog, upptäckte att döden inte gav honom någon frihet. Hans ande förblev bunden till den förstörda helgedomen, som lämnats åt sitt öde när världen sprack upp och demoner översvämmade den forntida bosättningen."},{t="Hämnd från graven",b="Vidriga satyrer och grells strövar omkring bland ruinerna av Bashal'Aran och livnär sig på rester av mystisk kraft, men de undviker helgedomen där Asterions vålnad dröjer sig kvar. Om en äventyrare från Alliansen hämtar månstenens sigill från satyrerna och krossar det i Ameth'Aran, bryts Asterions vålnadskedjor äntligen. Men friheten ger honom ingen frid. När han känner att Athrikus Narassin fortfarande lever vänder den uråldrige magikern tankarna från tiotusen års förtvivlan mot hämnd."}},faq={{q="Vem är Asterion?",a="Asterion är en uråldrig Highborne-vålnad som återfinns bland ruinerna av Bashal'Aran i Darkshore. Före Klyvningen var han en skicklig magiker och ställföreträdare åt guvernören Athrikus Narassin.",al={"asterions historia","vem är vålnaden i bashal'aran","vålnad alv darkshore"}},{q="Varför är Asterion fängslad?",a="Athrikus Narassin band Asterion med ett magiskt månsten sigill. Den exakta orsaken till deras konflikt är fortfarande okänd, men magin var så mäktig att inte ens Asterions död bröt förtrollningen. Hans vålnad hölls fången i årtusenden.",al={"varför är asterion fången","asterions fängelse","varför fångade athrikus asterion"}},{q="Varför anfaller inte satyrerna i Bashal'Aran honom?",a="Satyrerna och grells i ruinerna festar på de kvarvarande mystiska energierna i Bashal'Aran, men håller sig på avstånd från helgedomen där Asterion är bunden. De hade månstenens sigill som höll honom fången och lät hans ande vara.",al={"anfaller satyrer asterion","varför låter demoner asterion vara"}},{q="Var bodde Asterion när han levde?",a="Asterion hade sitt hem bland folket i Bashal'Aran och reste ofta söderut till systerstaden Ameth'Aran för att sköta stadens angelägenheter under drottning Azsharas guvernörs styre.",al={"asterions hem","var kom asterion ifrån"}},{q="Vad händer när du befriar honom?",a="Asterion hoppas att månstenens sigill ska bryta den fångenskap som fortsatte efter hans död. Vad som händer när han försöker beskrivs i spoileravsnittet.",al={"vad händer med asterion","går asterion vidare","asterions hämnd"}},{q="Är Asterion fientlig mot nutida nattalver?",a="Nej. Trots att Asterion är en uråldrig Highborne från drottning Azsharas hov är han fredlig mot resenärer från Alliansen och ber dem om hjälp att bryta hans uråldriga magiska bojor.",al={"är asterion vänligt inställd","asterion alliansen"}}},fx={["0f52734c"]={q="Vad vill Asterion?",a="Asterion vill befrias från det uråldriga magiska fängelse som har hållit hans ande fången i tiotusen år. Athrikus Narassin band honom till Bashal'Aran med ett månstenens sigill och lät Asterion lida även efter den fysiska döden. Han behöver desperat att du hämtar sigillet från satyrerna och krossar det i Ameth'Aran. Då får hans långa plåga ett slut och hans tankar kan vändas mot hämnd på hans forna herre.",al={"asterions mål","vad behöver asterion","asterions motiv"}},["98a0ebe3"]={q="Vem är Asterion knuten till?",a="I forntiden tjänade Asterion direkt under Athrikus Narassin, högborneherren som drottning Azshara utsett att styra Ameth'Aran och Bashal'Aran. Som andreman tog Asterion hand om båda bosättningarnas behov. Trots sin lojala tjänst band Athrikus Asterion med sin mörka konst i ett månstenens fängelse av arkan magi, av skäl som gått förlorade i historien. Deras uråldriga band blev ett arv av svek.",al={"asterions herre","vem fängslade asterion","athrikus narassin och asterion"}}},fp="8,175,29.355.0,20.384.0,24.410.1,16.187.0,27.195.0,47.230.0,32.158.0,32.150.1,42.171.0"}
P.entries["npc:athridas-bearmantle"] = {n="Athridas Bearmantle",s="Athridas Bearmantle är en nattalvdruid som bor i Dolanaar bland Teldrassils grenar. Han har fått i uppdrag att skydda bosättningen och skickar unga äventyrare för att undersöka den tilltagande fördärvelsen bland traktens djur och närliggande Gnarlpine-furbolger.",h="Athridas Bearmantle är en nattalvdruid som bor i Dolanaar bland Teldrassils grenar.",kw={"athridas","bearmantle","dolanaar","furbolg","gnarlpine","kaldorei","night elf","teldrassil"},ang={["class:Druid"]="Athridas uppdrag mot de fördärvade Gnarlpine och hans oro för forntida reliker berör direkt naturens balans, som druiderna har svurit att återställa.",["race:NightElf"]="För unga Kaldorei som lämnar Shadowglen visar Athridas Teldrassils hårda verklighet: deras nya hem hotas redan inifrån."},sec={{t="Dolanaars väktare",b="Athridas Bearmantle är stationerad i Dolanaar och utgör en första försvarslinje för nattalverna som lämnar Shadowglen. När grenarna på det nyväxta världsträdet Teldrassil visar onaturliga tecken på förruttnelse och oro samordnar Athridas outtröttligt den lokala spaningen och skyddar den fridfulla orten från hoten runt omkring."},{t="Furbolgernas plåga",b="Athridas oro gäller främst den närliggande Gnarlpine-stammen av furbolger. Gnarlpine var en gång fredliga grannar, men har fallit offer för en utbredd galenskap och fördärvelse som förgiftar deras schamaner och hövdingar och driver dem till våldsam ursinnighet mot Kaldorei. Athridas samlar villiga kämpar för att hejda hotet och blottlägga den djupare smitta som slår rot i vildmarken."}},faq={{q="Vem är Athridas Bearmantle?",a="Athridas Bearmantle är en nattalv som är stationerad i Dolanaar på ön Teldrassil. Han samordnar det lokala försvaret och värvar äventyrare för att bekämpa de mörka krafter som smyger fram bland världsträdets grenar.",al={"vem är athridas","athridas bearmantle bakgrund","athridas dolanaar"}},{q="Var hittar jag Athridas Bearmantle?",a="Athridas finns i Dolanaar, den första större orten som nattalväventyrare når efter att ha lämnat Shadowglen på Teldrassil.",al={"athridas plats","var finns athridas","hitta athridas bearmantle"}},{q="Vilka hot fokuserar Athridas på?",a="Athridas fokuserar främst på de aggressiva Gnarlpine-furbolgerna, som har fallit offer för ett fördärvande inflytande. Han skickar resenärer för att hejda deras angrepp, undersöka deras galenskap och återfinna viktiga reliker.",al={"athridas uppdrag","vad vill athridas","athridas uppgifter"}},{q="Varför angriper Gnarlpine-furbolgerna Dolanaar?",a="Gnarlpine-stammen har fallit offer för ett mörkt, onaturligt fördärv som sipprar genom Teldrassil. Det har gjort deras schamaner och krigare galna av fientlighet mot nattalverna.",al={"varför är gnarlpine galna","gnarlpine-fördärvelse","furbolgernas fientlighet mot teldrassil"}},{q="Vilken roll har Athridas i att säkra Teldrassil?",a="Athridas fungerar som en tidig väktare och samordnare. Han ser till att den tilltagande fördärvelsen bland Teldrassils djur och furbolger bekämpas innan den kan översvämma bosättningen Dolanaar.",al={"athridas roll","athridas betydelse"}}},fx={["04c7b610"]={q="Vilken sida står Athridas Bearmantle på?",a="Athridas står stadigt på nattalverna i Darnassus och Alliansens sida. Han är stationerad i Dolanaar och ägnar sina krafter åt att skydda sitt folk och hålla ordning i Teldrassil mot den korruption som tränger sig på.",al={"athridas fraktion","vem tjänar athridas","athridas bearmantles lojalitet"}},aae97259={q="Vad vill Athridas Bearmantle?",a="Athridas vill rena Teldrassils djurliv från den plötsliga pest som förgiftar det och stilla den rasande frenesi som drabbat de lokala Gnarlpine-furbolgerna. Han värvar dugliga resenärer för att undersöka korruptionen, återfinna heliga reliker och oskadliggöra farliga, laglösa furbolger som hotar Dolanaar.",al={"athridas mål","vad försöker athridas göra","athridas bearmantles drivkraft"}},["7a39a622"]={q="Varför är Athridas Bearmantle här i Dolanaar?",a="Dolanaar är den första större bosättningen som resenärer når bortom Shadowglen, vilket gör platsen till utgångspunkt för hanteringen av lokala kriser. Athridas är stationerad här för att samordna försvaret, hålla uppsikt över de oroliga skogarna och leda äventyrare mot de växande hoten i skogsmarken.",al={"varför är athridas i dolanaar","athridas postering","varför är athridas här"}}},fp="19,205,20.268.0,22.344.0,27.184.0,37.115.0,36.197.0,50.171.0,52.148.0"}
P.entries["npc:auntie-bernice-stonefield"] = {n="\"Auntie\" Bernice Stonefield",s="På familjegården Stonefield i södra centrala Elwynn Forest håller ”Auntie” Bernice Stonefield uppsikt över grannskapet. Hon blev änka när hennes man stupade i rikets militära fälttåg och är känd i hela dalen för sina fläskkarrépajer. Hon håller till utanför bondgården tillsammans med Ma Stonefield och är fortfarande djupt misstänksam mot den rivaliserande familjen Maclure.",h="På familjegården Stonefield i södra centrala Elwynn Forest håller ”Auntie” Bernice Stonefield uppsikt över...",kw={"auntie","bernice","elwynn","goldtooth","maclure","halsband","pork belly pie","stonefield"},ang={["profession:Cooking"]="Bernices fläskkarrépaj är berömd i hela Elwynn Forest som en klassiker inom mustig matlagning från människornas gränstrakter.",["race:Human"]="Som människa visar Bernice Stormwinds landsbygdsfolkets uthållighet. Hon fortsätter med vardagen och värnar om familjens stolthet efter att hennes man stupat i rikets krig."},sec={{t="Ett liv i motgång",b="Bernice bär krigets börda, liksom många vanliga människor i kungariket Stormwind. Hennes man stupade i militära fälttåg, och nu bor hon med sina släktingar på familjegården. Hon hjälper Ma Stonefield att sköta gårdens dagliga sysslor och ser till att hushållet får mat och fungerar. Hennes fläskkarrépajer har gjort henne berömd bland dalens invånare."},{t="Fejden och det försvunna halsbandet",b="För Bernice går den gamla bitterheten mellan familjerna Stonefield och Maclure djupt. När hennes älskade familjehalsband försvann misstänkte hon att unge Billy Maclure hade tagit det. Att få tillbaka det visar sig vara mer komplicerat än att reda ut ett grannskämt. Billy bedyrar att han inte stal halsbandet, men erkänner nästan att han tappade det nära Fargodeep Mine. Där såg han den guldtandade kobolden Goldtooth rycka åt sig det och bära det till sitt näste."}},faq={{q="Vem är Auntie Bernice Stonefield?",a="”Auntie” Bernice Stonefield är en äldre medlem av familjen Stonefield som bor på The Stonefield Farm i södra Elwynn Forest. Hon blev änka i rikets krig, sköter gården tillsammans med Ma Stonefield och är känd för sina fläskkarrépajer.",al={"vem är auntie bernice","bernice stonefields bakgrund","stonefields auntie"}},{q="Vad hände med Auntie Bernices make?",a="Bernices man stupade under ett militärt fälttåg för kungariket Stormwind och lämnade henne som änka.",al={"auntie bernices make","vem var bernice gift med","stonefield änka"}},{q="Vad är Auntie Bernice känd för?",a="Bernice är känd i hela trakten för sina fläskkarrépajer, som även busiga grannar gärna byter till sig en bit av.",al={"bernice stonefields paj","fläskkarrépaj i elwynn"}},{q="Varför är Auntie Bernice arg på Billy Maclure?",a="Bernice misstänker att Billy Maclure tog hennes älskade familjehalsband, vilket fördjupar den långvariga fejden mellan familjerna Stonefield och Maclure.",al={"fejden med billy maclure","bernice halsbandstjuv","varför hatar bernice billy"}},{q="Stal Billy Maclure verkligen halsbandet?",a="Billy bedyrar att han inte stal Bernices halsband, men erkänner nästan att han tappade det nära Fargodeep Mine. Han säger att den guldtandade kobolden Goldtooth plockade upp det och bar det till sitt näste.",al={"stal billy halsbandet","vem har stonefields halsband","goldtooths halsband"}},{q="Var hittar man Auntie Bernice?",a="Du hittar Bernice utanför den stora bondgården på The Stonefield Farm, söder om vägen mellan Goldshire och Westfall, bredvid Ma Stonefield.",al={"auntie bernices plats","var finns bernice stonefield"}}},fx={["0a2ddc6d"]={q="Vems sida står \"Auntie\" Bernice Stonefield på?",a="\"Auntie\" Bernice är en lojal undersåte till kungariket Stormwind och en stolt medlem av familjen Stonefield. Hon står fast vid sin släkt i den långvariga, bittra fejden med grannarna Maclure och har föga tålamod med någon som bär det namnet.",al={"\"auntie\" bernices fraktion","vem stöder bernice","bernice stonefield alliance"}},["0e5ea09d"]={q="Vad vill \"Auntie\" Bernice Stonefield?",a="Framför allt vill \"Auntie\" Bernice få tillbaka sitt älskade familjehalsband, som försvann och fick henne att misstänka unge Billy Maclure. För att lösa mysteriet och återfå arvegodset är hon beredd att baka en av sina berömda pajer med fläsksida för att locka fram sanningen ur honom.",al={"vad behöver \"auntie\" bernice","\"auntie\" bernices mål","bernice stonefields motiv för uppdrag"}},f6bb7867={q="Varför är \"Auntie\" Bernice Stonefield här?",a="The Stonefield Farm är \"Auntie\" Bernices hem. Efter att ha förlorat sin make i ett av Stormwinds militära fälttåg bor hon kvar på familjegården i Elwynn Forest tillsammans med Ma Stonefield och resten av släkten, där hon sköter hushållet och gården.",al={"varför är bernice på gården","varför är bernice stonefield här","vad förde \"auntie\" bernice hit"}},["21972eac"]={q="Vilka band har \"Auntie\" Bernice Stonefield?",a="Hon är en äldre matriark i klanen Stonefield och bor sida vid sida med Ma Stonefield på deras gård i Elwynn. Hennes familj är indragen i en bitter, pågående rivalitet med hushållet Maclure i närheten, vilket färgar nästan alla hennes möten med deras släkt.",al={"\"auntie\" bernices familj","bernice stonefields släktingar","vilka är \"auntie\" bernices släktingar"}}},fp="27,319,18.302.0,33.438.1,33.237.0,42.109.0,34.129.0,47.141.0,46.196.1,32.139.0"}
P.entries["npc:austil-de-mon"] = {n="Austil de Mon",s="Austil de Mon är en krigarinstruktör bland de Fördömda, stationerad i Brill i Tirisfal Glades. Han håller till på Gallows' End Tavern och tränar nyuppväckta krigare som vill vässa sin stridsförmåga i den Mörka damens tjänst.",h="Austil de Mon är en krigarinstruktör bland de Fördömda, stationerad i Brill i Tirisfal Glades.",kw={"austil de mon","brill","krigare bland de fördömda","gallows' end tavern","tirisfal glades","krigarinstruktör"},ang={["class:Warrior"]="För krigare bland de Fördömda som lämnar Deathknell är Austil de Mon en av de främsta mentorerna, med vägledning och formell förmågeträning i Tirisfal Glades.",["race:Undead"]="Austil härdar nyuppväckta odöda till formidabla frontkämpar som är redo att försvara Lordaeron mot Scourge och Scarlet Crusade."},sec={{t="En veteran på Gallows' End",b="Austil de Mon finns inne på Gallows' End Tavern i Brill och är en av de första instruktörerna för krigare bland de Fördömda som ger sig av från Deathknell. Medan de levande en gång fyllde värdshuset för att dricka och vila använder Austil nu den dystra tillflyktsorten för att lära nybefriade odöda att kanalisera rå stridsdisciplin och skoningslösa stridstekniker mot rikets fiender i trakten."}},faq={{q="Vem är Austil de Mon?",a="Austil de Mon är en odöd krigarinstruktör på Brills marker i Tirisfal Glades, där han tränar stridande bland de Fördömda.",al={"austil de mon","austil","vem är austil"}},{q="Var hittar jag Austil de Mon?",a="Du hittar honom på Gallows' End Tavern i Brill, Tirisfal Glades, strax norr om Undercity.",al={"austil de mon plats","var är austil","austil de mon karta"}},{q="Vilken roll har han i Brill?",a="Han lär nybörjarkrigare stridstekniker, ställningar och stridsförmågor för att stärka de Fördömdas militär mot lokala hot.",al={"vad gör austil","austil tränare","austils roll"}}},fx={["00da3c5d"]={q="Vems sida står Austil de Mon på?",a="Austil de Mon är lojal mot Forsaken och den Mörka Damen, drottning Sylvanas Windrunner. Som del av det framväxande odöda kungariket som formats ur Lordaerons ruiner tjänar han tillsammans med sina bröder och systrar i Horde. Han bidrar med sin stridserfarenhet för att vässa styrkan hos nyanlända Forsaken-krigare som försvarar Tirisfal Glades mot Scourge och Scarlet Crusade.",al={"austil de mons fraktion","austil de mons lojalitet","vem tjänar austil"}},d899e308={q="Vad vill Austil de Mon?",a="Austil de Mon vill stärka Forsakens militära led mot Lordaerons många fiender. Genom att träna nyuppväckta krigare på Gallows' End Tavern ser han till att de som griper till vapen under den Mörka Damen har den disciplin och teknik som krävs för att överleva mot både den skoningslösa Scourge och Scarlet Crusades fanatiska zeloter.",al={"austil de mons mål","vad vill austil","austil de mons syfte"}},aed6134f={q="Varför är Austil de Mon i Brill?",a="Austil är stationerad på Gallows' End Tavern i Brill för att ta emot och öva krigare som kommer från Deathknell. Brill fungerar som den främsta utposten och försörjningscentralen i norra Tirisfal Glades. Därför behövs krigstränare som Austil för att göra nyuppstigna odöda till dugliga frontsoldater innan de marscherar längre in i omstritt territorium.",al={"varför är austil i brill","varför är austil de mon här","varför är austil de mon på den här platsen"}}},fp="13,137,25.315.0,21.91.0,31.105.0,32.142.0"}
P.entries["npc:ayanna-everstride"] = {n="Ayanna Everstride",s="Ayanna Everstride är en kaldorei-jägarinstruktör stationerad i Aldrassil i Shadowglen på Teldrassil. Hon lär upp unga Night Elf-spårare i grunderna i prickskytte, spårning och överlevnad i vildmarken. Unga jägare som tar sina första steg under Världsträdets grenar söker hennes vägledning för att förfina sin skogsvana.",h="Ayanna Everstride är en kaldorei-jägarinstruktör stationerad i Aldrassil i Shadowglen på Teldrassil.",kw={"aldrassil","ayanna","everstride","jägarinstruktör","night elf","shadowglen","teldrassil"},ang={["class:Hunter"]="För unga Night Elf-jägare som inleder sin resa i Shadowglen är Ayanna Everstride den första mentorn som lär dem hantera vapen, spåra och överleva i den otämjda vildmarken.",["race:NightElf"]="Ayanna är stationerad i Aldrassils heliga håligheter och hjälper till att skydda det unga Världsträdet genom att förbereda rekryter på att försvara den omgivande skogen mot korruption som tränger sig på."},sec={{t="En mentor i Shadowglen",b="Inne i Aldrassil, mitt i Shadowglen, står Ayanna Everstride redo att undervisa nyväckta kaldorei i vildmarkens seder. För Night Elf är en jägare inte bara en fällläggare eller prickskytt, utan en oumbärlig väktare av de heliga skogarna. Ayanna vägleder dem i tidiga stridstekniker och hjälper nybörjare att bemästra avståndsstrid och överleva i Teldrassils farliga skogar."}},faq={{q="Vem är Ayanna Everstride?",a="Ayanna Everstride är en Night Elf-jägarinstruktör i Aldrassil, som ligger i startområdet Shadowglen på Teldrassil. Hon lär nybörjarjägare grundläggande stridsfärdigheter och tekniker för att överleva utomhus.",al={"ayanna everstride","vem är ayanna","jägarinstruktör i aldrassil"}},{q="Var hittar jag Ayanna Everstride?",a="Hon finns inne i Aldrassil, den väldiga bosättningen i ett ihåligt träd i Shadowglen, mitt i Teldrassil.",al={"ayannas plats","var finns ayanna","hitta ayanna everstride"}},{q="Vilka uppdrag involverar Ayanna Everstride?",a="Nya Night Elf-jägare hänvisas till Ayanna genom tidiga träningsuppdrag, till exempel när de får en Etched Sigil av sina första instruktörer. Därefter ger hon en introduktion för blivande skogsspäjare.",al={"ayannas uppdrag","etched sigil-uppdrag","uppdragsgivare ayanna"}}},fx={["881ffa5e"]={q="Vems sida står Ayanna Everstride på?",a="Ayanna står stadigt på nattalvernas och Alliances sida i Darnassus. Från sin post i Shadowglen, inne i Aldrassil, vägleder hon nyvakna nattalver i gemenskap med vildmarken. Hon är lojal mot sin släkt och försvaret av Teldrassil.",al={"ayanna everstrides fraktion","vem tjänar ayanna everstride","ayanna everstride alliance"}},e6b7d676={q="Vad vill Ayanna Everstride?",a="Ayanna har vigt sig åt att vägleda unga jägare. Hon vill se till att nattalver lär sig spåra, skjuta och överleva i harmoni med naturen innan de beger sig längre ut i världen.",al={"ayanna everstrides mål","vad vill ayanna","ayanna everstrides syfte"}},bbb0d24a={q="Varför är Ayanna Everstride här i Shadowglen?",a="Ayanna bor i Aldrassil och arbetar som jägartränare. När unga nattalver vaknar i den skyddade lunden Shadowglen förbereder hon dem som väljer jägarens väg med viktiga färdigheter, vapen och undervisning.",al={"varför är ayanna i aldrassil","varför är ayanna everstride här","ayanna everstrides roll i shadowglen"}}},fp="17,174,22.329.0,25.150.0,35.128.0,38.186.0"}
P.entries["npc:ayessa-dawnsinger"] = {n="Ayessa Dawnsinger",s="Ayessa Dawnsinger är en Skyborne-ledare i Valanaar på Zephras Isle. Hon leder Windshapers och vägleder de Skyborne som står på Hordens sida genom prövningar och politik.",h="Ayessa Dawnsinger är en Skyborne-ledare i Valanaar på Zephras Isle.",kw={"ayessa","dawnsinger","horden","skyborne","valanaar","windshapers","zephras"},ang={["faction:Horde"]="För Horden är Ayessa Dawnsinger deras främsta allians med Skyborne och en hörnsten för deras närvaro och diplomatiska band på Zephras Isle.",["race:Skyborne"]="Som Windshapers ledare förkroppsligar Ayessa Skybornes vision om att stå enade med Horden för att säkra sin framtid."},sec={{t="Windshapers ledare",b="Ayessa Dawnsinger står i bosättningen Valanaar på Zephras Isle och är Windshapers främsta vägledare, den Skyborne-fraktion som står på Hordens sida. Därifrån leder hon viktiga insatser över hela ön och hanterar yttre hot, inre slitningar och sitt folks överlevnad medan de navigerar bland allianser i Kalimdor och bortom."},{t="Kampen om Zephras",b="Ayessa spelar en avgörande roll i att lösa konflikter på ön. Hon skickar ut betrodda mästare för att hantera förrymda konstrukter, fientliga gestalter som Lorthuna och Skybornes större öde. Hennes auktoritet leder Windshapers genom spända politiska och fysiska konfrontationer och ser till att deras röst och styrka fortsätter att respekteras inom Horden."}},faq={{q="Vem är Ayessa Dawnsinger?",a="Ayessa Dawnsinger är en framstående Skyborne som leder Windshapers, den Skyborne-fraktion som står på Hordens sida på Zephras Isle.",al={"ayessa berättelse","vem är ayessa","ayessa dawnsinger bakgrund"}},{q="Var finns Ayessa Dawnsinger?",a="Hon finns i bosättningen Valanaar på Zephras Isle.",al={"var finns ayessa","ayessas plats","ayessa dawnsinger karta"}},{q="Vad är Windshapers?",a="Windshapers är den Skyborne-fraktion som står på Hordens sida och leds av Ayessa Dawnsinger från sin bas i Valanaar.",al={"windshapers fraktion","vilka är windshapers"}},{q="Vilken roll har Ayessa i lokala uppdrag?",a="Ayessa ger flera viktiga uppdrag som rör öns försvar, däribland att undersöka förrymda konstrukter, konfrontera Lorthuna och forma Zephras framtid.",al={"ayessas uppdrag","ayessas uppdragskedja"}}},fx={["53a49c44"]={q="Vems sida står Ayessa Dawnsinger på?",a="Ayessa Dawnsinger står stadigt på Hordes sida. Som ledare för The Windshapers vägleder hon den Horde-allierade fraktionen Skyborne från Valanaar på Zephras Isle. Hon leder deras arbete och samlar Hordes förkämpar kring sin sak.",al={"ayessa dawnsingers fraktion","är ayessa med horde eller alliance","ayessas lojalitet"}},e31c8ea2={q="Vilka band har Ayessa Dawnsinger?",a="Ayessa Dawnsinger har nära band till The Windshapers, fraktionen av Skyborne som är allierad med Horde och som hon leder. Från Valanaar samordnar hon deras verksamhet och organiserar motståndet mot deras lokala fiender på Zephras Isle.",al={"ayessa dawnsingers fraktionsband","ayessas kontakter","vem arbetar ayessa med"}}},fp="17,179,25.385.0,24.356.1,25.138.0,37.61.0,25.121.0,38.174.0"}
P.entries["npc:azar-stronghammer"] = {n="Azar Stronghammer",s="Azar Stronghammer är en paladin av dvärgfolk stationerad vid Thunderbrew Distillery i Kharanos. Efter att ha slutfört sin egen utbildning i de heliga konsterna vägleder han nyvaknade dvärghjältar inom Det heliga ljuset och hänvisar lovande rekryter till vidare undervisning i Ironforge.",h="Azar Stronghammer är en paladin av dvärgfolk stationerad vid Thunderbrew Distillery i Kharanos.",kw={"azar","destilleri","dun morogh","kharanos","paladin","stronghammer","thunderbrew","tome of divinity","tränare"},ang={["class:Paladin"]="För dvärgpaladiner som påbörjar sin resa i Dun Morogh är Azar en viktig tidig mentor som så småningom leder dig till Ironforge, där du kan förtjäna den heliga Tome of Divinity.",["race:Dwarf"]="Azar visar hur dvärgarna har tagit till sig Det heliga ljuset och hur hängivenhet åt helig rättfärdighet passar utmärkt ihop med en varm härd och en mugg Thunderbrew."},sec={{t="En vägvisare i kylan",b="Paladiner förknippas oftare med mänsklighetens stora katedraler, men dvärgarna i Khaz Modan har helhjärtat tagit till sig Det heliga ljusets dygder. Azar Stronghammer är stationerad vid Thunderbrew Distillery i Kharanos och håller uppsikt över nyinvigda dvärgpaladiner som försöker finna fotfästet bland Dun Moroghs frusna sluttningar. Han har fulländat sina egna militära och andliga löften och är en tillgänglig mentor. När en nybörjare visar tillräcklig hängivenhet och andlig mognad skickar Azar dem längs bergsstigen till Ironforge för att studera under erfarna kämpar som Tiza Battleforge."}},faq={{q="Vem är Azar Stronghammer?",a="Azar Stronghammer är en paladintränare av dvärgfolk, stationerad vid Thunderbrew Distillery i Kharanos. Han ansvarar för unga dvärgkrigares första träning i Det heliga ljuset innan han skickar dem vidare till huvudstaden.",al={"vem är azar","azar stronghammers roll","paladintränare i kharanos"}},{q="Var hittar man Azar Stronghammer?",a="Han finns inne i Thunderbrew Distillery i byn Kharanos, inbäddad bland Dun Moroghs centrala snöiga kullar.",al={"azar stronghammers plats","var finns azar","hitta azar stronghammer"}},{q="Vilken träning ger han unga paladiner?",a="Azar lär nybörjare paladinernas grundläggande stridskonst och besvärjelser. När en lärling är redo att genomgå prövningarna i Tome of Divinity för att lära sig uppståndelsens heliga riter hänvisar han dem till Tiza Battleforge i Ironforge.",al={"vad gör azar","azar uppdrag","paladinuppdrag azar"}},{q="Varför är en paladintränare stationerad på ett destilleri?",a="Dvärgkulturen väver samman samhällsliv, kamratskap och stark dryck. Thunderbrew Distillery är hjärtat i Kharanos sociala liv och försvar, vilket gör det till en naturlig samlingsplats för lokala försvarare och mentorer.",al={"varför är paladinen på destilleri","paladin på bar","destilleritränare"}}},fx={["38fe723c"]={q="Vems sida står Azar Stronghammer på?",a="Azar Stronghammer står stadigt på kungariket Ironforges och Alliances sida. Som en erfaren dvärgpaladin är han lojal mot sitt folk, King Magni Bronzebeard och Ljusets heliga lärosatser.",al={"azar stronghammers fraktion","azar stronghammers lojalitet","för vem strider azar"}},["56baf4f4"]={q="Vad vill Azar Stronghammer?",a="Efter att ha genomgått en omfattande egen utbildning i Ljuset vill Azar vägleda nästa generation dvärgpaladiner. Han håller uppsikt över lovande lärlingar i Dun Morogh och ser till att de är redo innan han skickar dem vidare till mästartränare som Tiza Battleforge i Ironforge.",al={"azar stronghammers mål","vad försöker azar göra","azar stronghammers syfte"}},["132f6bb2"]={q="Vilka band har Azar Stronghammer?",a="Azar har starka band till sina medpaladiner bland dvärgarna. Han samordnar särskilt med Tiza Battleforge i Hall of Mysteries i Ironforge för att utveckla utbildningen av lovande invigda.",al={"azar stronghammers kontakter","azar stronghammers allierade","vem känner azar"}}},fp="17,194,19.463.0,25.197.0,37.114.0,48.214.0,51.220.0"}
P.entries["npc:azuregos"] = {n="Azuregos",s="Azuregos är en excentrisk blå drake som håller till längs Azsharas kust för att skydda forntida reliker från Highborne. På uppdrag av Spell-Weaver Malygos att vakta en väldig magisk kraft föredrar han stilla studier framför våld, men han slår gärna undan varje äventyrare som är dum nog att störa hans vakthållning.",h="Azuregos är en excentrisk blå drake som håller till längs Azsharas kust för att skydda forntida reliker från...",kw={"azshara","azuregos","bay of storms","blå drake","eldarath","malygos","scepter shard","shifting sands"},ang={["class:Mage"]="Som agent för den blå drakflykten förkroppsligar Azuregos behärskningen och regleringen av de mystiska krafterna. Han betraktar dödliga magiker som vårdslösa barn som leker med krafter bortom deras förstånd.",["race:NightElf"]="Azuregos vandrar bland de sönderslagna resterna av Eldarath och håller noggrann uppsikt över just den Highborne-trolldom som nästan slet Kalimdor i stycken under Sunderingen."},sec={{t="Eldaraths väktare",b="Azuregos drogs till Azsharas magiska stränder och valde de forntida ruinerna av Eldarath som sin fristad. Otaliga reliker överlevde den stora Sunderingen längs dessa sönderslagna kuster, och Azuregos ser det som sin heliga plikt som Malygos tjänare att hålla sådana mäktiga artefakter borta från oförsiktiga dödliga. I stället för att lura i en mörk grotta strövar han fritt bland klipporna och stränderna och kallar stolt sig själv för härskaren över all magi i trakten. Han har en sarkastisk humor, men försvarar Azsharas skatter ursinnigt mot den ändlösa strömmen av äventyrare som söker ära eller byte."},{t="En motvillig väktare",b="Efter War of the Shifting Sands fick Azuregos i uppdrag att vakta Blue Scepter Shard, en del av en nyckel som behövs för att bryta barriären vid Scarab Wall. Den listiga draken avskydde de ständiga huvudvärken, skattjägarna och blivande hjältarna som artefakten lockade till sig. Till slut gjorde han sig av med reliken på det mest oceremoniella sätt man kan tänka sig: han matade den till en förstärkt småfisk vid namn Maws. Den som hoppades lägga beslag på skärvan skulle därmed behöva muddra djupen i stället för att störa honom."}},faq={{q="Vem är Azuregos?",a="Azuregos är en mäktig blå drake som drakastern Malygos skickade för att patrullera ruinerna i Azshara. Många drakar är dystra eller vredgade, men Azuregos är särpräglat excentrisk och kvick. Ändå krossar han skoningslöst dödliga som avbryter hans magiska studier eller åtrår Eldaraths skatter.",al={"azuregos berättelse","vem är den blå draken i azshara","azuregos bakgrund"}},{q="Varför är Azuregos i Azshara?",a="Han kom för att studera och säkra de kraftfulla mystiska artefakter som den forntida civilisationen Highborne lämnade efter sig efter den stora Sunderingen. Han vaktar ruinerna i Eldarath mot hänsynslösa plundrare som söker farlig magi.",al={"varför är azuregos här","vad gör azuregos i azshara","azuregos syfte"}},{q="Vad har han med Scarab Wall att göra?",a="Azuregos fick i uppdrag att vakta Blue Scepter Shard, en del av nyckeln som kan öppna Scarab Wall igen. Du måste tala med draken för att få veta vad som hände med den.",al={"azuregos scepter shard","azuregos shifting sands","shifting sands shard"}},{q="Varför visar sig hans ande i Azshara?",a="Azuregos ande visar sig i Azshara nära den levande draken och talar med resenärer. Det förklaras aldrig hur anden och draken kan finnas sida vid sida.",al={"azuregos ande","azuregos spöke","varför är azuregos ett spöke"}}},fp="8,310,24.599.0,21.501.1,16.296.0,27.217.0,42.165.1,38.160.0"}
P.entries["npc:bailiff-conacher"] = {n="Bailiff Conacher",s="Bailiff Conacher tjänstgör i Lakeshire Town Hall som högste ordningsman under Magistrate Solomon. Han ansvarar för att upprätthålla den civila ordningen och verkställa lokala förordningar, och tar hjälp av självständiga hjältar för att upprätthålla Stormwinds lagar i det hårt ansatta Redridge Mountains.",h="Bailiff Conacher tjänstgör i Lakeshire Town Hall som högste ordningsman under Magistrate Solomon.",kw={"bailiff","conacher","lakeshire","morganth","redridge","shadowhide","solomon","stadshus"},ang={["faction:Alliance"]="Bailiff Conacher står för Stormwinds rättssystems bräckliga räckvidd i en gränsstad som i stort sett lämnats åt sig själv."},sec={{t="Rättvisa i Lakeshire",b="I Lakeshire Town Hall arbetar Bailiff Conacher nära Magistrate Solomon för att upprätthålla laglig myndighet i Redridge Mountains. Staden är belägrad från alla håll av Blackrock-orcher och lokala gnoller, så Conacher kan inte förlita sig på vanliga civila rutiner eller kungliga garnisoner. I stället utfärdar han rättsliga förordningar som ger förbiresande resenärer befogenhet att skipa dödsstraffets rättvisa på rikets vägnar."},{t="Att tillämpa Solomon's Law",b="När den mörke magikern Morganth tog Tower of Ilgalar i besittning och tvingade de lokala Shadowhide-gnollerna att lyda honom, ansåg Lakeshires domstol att bestarna var medskyldiga till högförräderi. Eftersom det är belagt med dödsstraff att hjälpa en förrymd brottsling från kungariket Stormwind, åberopar Conacher Solomon's Law. Han skickar äventyrare till höjderna för att leta upp Shadowhide-gnoller och kräver deras hängen som juridiskt bevis på att kronans lag har verkställts."}},faq={{q="Vem är Bailiff Conacher?",a="Bailiff Conacher är en tjänsteman vid Lakeshires domstol som hjälper Magistrate Solomon att upprätthålla den civila myndigheten och Stormwinds lagar i Redridge Mountains.",al={"bailiff conachers roll","vem är conacher","conachers bakgrund"}},{q="Var hittar man Bailiff Conacher?",a="Han finns inne i Lakeshire Town Hall, på brons norra sida i Redridge Mountains.",al={"bailiff conachers plats","var finns conacher","conacher i redridge"}},{q="Vad är Solomon's Law?",a="Det är Magistrate Solomons rättsliga tillämpning av Stormwinds lagar. Enligt förordningen är det belagt med dödsstraff att hjälpa kända brottslingar som den fredlöse trollkarlen Morganth, vilket lagligen gör hans allierade Shadowhide-gnoller dömda till avrättning.",al={"vad är solomons law","solomons lag och gnoller","shadowhide och lagen"}},{q="Varför ber Conacher om Shadowhide-hängen?",a="Hängena fungerar som verifierbart bevis på att en Shadowhide-gnoll har dödats i verkställandet av Lakeshires lagliga straff för dem som hjälper Morganth.",al={"varför samla hängen","shadowhide-hängenas syfte"}}},fx={["6ce891cc"]={q="Vems sida står Bailiff Conacher på?",a="Bailiff Conacher tjänar Alliance och lyder direkt under Magistrate Solomon i staden Lakeshire. Som tjänsteman vid Redridges domstol har han till uppgift att upprätthålla Stormwinds lagar och skydda lokalbefolkningen mot hot som tränger sig på.",al={"conachers lojalitet","vem tjänar conacher","är conacher med alliance"}},["5d999432"]={q="Vad vill Bailiff Conacher?",a="Conacher vill upprätthålla Lakeshires lagar och skydda Redridge. Eftersom den avfällige magikern Morganth värvar de lokala Shadowhide-gnollerna rekryterar fogden dugliga äventyrare som kan skipa rättvisa bland gnollerna och hejda den mörke magikerns inflytande.",al={"conachers mål","vad behöver bailiff conacher"}},["8124ae86"]={q="Varför är Bailiff Conacher här i Lakeshire?",a="Conacher är stationerad i Lakeshire Town Hall som stadens fogde. Tillsammans med Magistrate Solomon hjälper han till att skipa lokal rättvisa och organisera stadens försvar, medan Stormwind inte kan avvara förstärkningar till regionen.",al={"varför är conacher i redridge","conacher i lakeshire town hall"}},df8ac9aa={q="Vilka band har Bailiff Conacher?",a="Conacher arbetar direkt under Magistrate Solomon som en del av Lakeshires domstol. Han samarbetar nära med stadens tjänstemän och lokala vakter för att hålla ordning i bosättningen när inkräktare hotar utifrån.",al={"conachers allierade","vem arbetar conacher med"}}},fp="16,183,20.353.0,22.417.0,24.143.0,36.116.0,22.210.0,46.121.0"}
P.entries["npc:bailor-stonehand"] = {n="Bailor Stonehand",s="Bailor Stonehand är en skicklig dvärgisk smed som bor i Thelsamar i Loch Modan. Han är känd för sitt kunnande inom metallurgi och var en gång mentor åt den mänsklige vapensmeden Jordan Stilwell. Han tillverkar en särskild legering som är avgörande för mästerliga vapen. Just nu har arbetet i smedjan drabbats av bakslag efter att lokala Mo'grosh-oger överfallit och stulit hans malmleveranser.",h="Bailor Stonehand är en skicklig dvärgisk smed som bor i Thelsamar i Loch Modan.",kw={"bailor stonehand","jordan stilwell","loch modan","mo'grosh","smed","thelsamar","verigan's fist"},ang={["class:Paladin"]="Paladiner som vill smida det legendariska vapnet Verigan's Fist följer i Bailors fotspår. Han lärde Jordan Stilwell den särskilda legeringsformeln för att smida den heliga hammaren.",["profession:Blacksmithing"]="Bailor är en mästare på metallarbete, och hans särskilda legeringar är välkända i hela Khaz Modan. Han förkroppsligar dvärgarnas traditionella strävan att fullända sällsynta och motståndskraftiga metaller."},sec={{t="Smedjans mästare",b="Bailor Stonehand verkar i dvärgbosättningen Thelsamar och för vidare det gedigna hantverket hos Loch Modans smeder. Han är känd för sin skarpa blick för råmineraler och sin förmåga att smälta särskilda legeringar. Bailors kunskap sträcker sig bortom Khaz Modan. Han var mentor åt den välkände mänsklige smeden Jordan Stilwell och lärde honom metallurgins grunder. Han delade också med sig av formler som senare visade sig viktiga när heliga paladinvapen som Verigan's Fist skulle smidas."},{t="Ogernas överfall",b="Trots sitt stillsamma mästerskap går Bailors handel inte fri från de växande hoten i Loch Modan. Leveranser av högklassig malm till hans smedja har fallit offer för Mo'grosh-ogerna, som håller till i kullarna i nordöst. Utan råmaterial kan Bailor inte tillverka sina sällsynta legeringar. Han måste därför förlita sig på förbipasserande resenärer och allierade för att återta de stulna förnödenheterna från ogregerillans läger."}},faq={{q="Vem är Bailor Stonehand?",a="Bailor Stonehand är en erfaren dvärgisk smed i Thelsamar i Loch Modan. Han är känd för att smälta sällsynta metallegeringar och för att tidigare ha lärt Jordan Stilwell vapensmedens hantverk.",al={"bailor stonehand","vem är bailor","smeden i thelsamar"}},{q="Vad har Bailor med Jordan Stilwell att göra?",a="Bailor var en gång lärare åt Jordan Stilwell, en mänsklig smed med verkstad nära Ironforge. Stilwell tillskrev Bailor äran för att ha lärt honom konsten att bearbeta förädlad malm, särskilt en särskild legering som används för att smida den heliga stridshammaren Verigan's Fist.",al={"bailor och jordan","jordans lärare stilwell","smeden bakom verigan's fist"}},{q="Vad hände med Bailors malm?",a="Bailors råmalmsleverans rövades bort av Mo'grosh-ogerna, som håller till i högarna i nordöstra Loch Modan. Nu saknar han material för sin specialiserade metallurgi.",al={"bailors malmleverans","vem stal bailors malm","ogreleverans"}},{q="Var hittar man Bailor Stonehand?",a="Bailor finns nära Thelsamars centrum, den främsta dvärgstaden längs Loch Modans huvudväg.",al={"bailors plats","var finns bailor stonehand","bailor i thelsamar"}}},fx={["0eb0f83a"]={q="Vems sida står Bailor Stonehand på?",a="Bailor Stonehand står stadigt på Ironforges och Alliances sida. Han bor bland sina släktingar i Thelsamar och använder sitt hantverk för att stödja den lokala dvärgbosättningen. Han hjälper också resande Alliance-äventyrare, särskilt paladiner som behöver hans metallurgiska kunskaper, att försvara riket mot fientliga hot.",al={"bailor stonehands fraktion","är bailor med alliance","bailors sida"}},a41b979c={q="Vad vill Bailor Stonehand?",a="Bailor vill arbeta ostört som smed, men främst vill han få tillbaka sina värdefulla råmaterial. Mo'grosh-ogrer har plundrat och stulit hans senaste malmleverans. Därför söker han skickliga resenärer som vågar sig in i ogreternas område för att hämta hans förlorade förnödenheter.",al={"vad vill bailor","bailor stonehands mål","bailors drivkraft"}},["346dae44"]={q="Varför är Bailor Stonehand i Thelsamar?",a="Bailor bor i Thelsamar, där han driver sin smedja och förser bosättningen med fint dvärkt hantverk i metall. Staden ligger nära gruvorna och den oländiga terrängen i Loch Modan, vilket gör den till en idealisk utpost för en erfaren smed, även om lokala ogreplundringar ibland ställer till det för hans leveranser.",al={"varför är bailor här","varför är bailor i loch modan","varför är bailor i thelsamar"}}},fp="16,212,19.252.0,11.237.0,24.153.0,47.164.0,30.150.0,36.101.0"}
P.entries["npc:baine-bloodhoof"] = {n="Baine Bloodhoof",s="Baine Bloodhoof är son till Cairne Bloodhoof, högöverhövdingen, och tillförordnad beskyddare av Bloodhoof Village i Mulgore. Medan hans far styr stammarna från Thunder Bluffs höga toppar övervakar Baine det lokala försvaret, undersöker den tilltagande industriella exploateringen och skyddar byn mot vilda rovdjur. Han är en viktig länk mellan de unga taurenkrigarna och klanens nedärvda visdom.",h="Baine Bloodhoof är son till Cairne Bloodhoof, högöverhövdingen, och tillförordnad beskyddare av Bloodhoof...",kw={"baine","bloodhoof","bloodhoof village","cairne","centaur","khiragg","mulgore","palemane","rexxar","thunder bluff"},ang={["class:Shaman"]="Baine vördar andarna framför allt annat och skickar resande för att tysta dvärgarnas maskiner och hejda de vårdslösa gruvarbetarna innan deras grävande sårar jordens andar ännu mer.",["faction:Horde"]="Baine förkroppsligar det lugna förståndet och den stillsamma kampstyrkan som håller tauren stadiga inom Thralls Horde. Han vägleder dem som färdas genom centrala Mulgore.",["race:Tauren"]="Baine står för både högöverhövding Cairnes hedervärda släktlinje och det levande hoppet hos de unga stammarna som samlats över Mulgorets slätter."},sec={{t="Högöverhövdingens son",b="Baine föddes som son till Cairne och tillbringade sin ungdom på resor med sitt nomadfolk, innan de slog sig ned på Mulgorets bördiga gräsmarker. Under hans tidiga liv hotade centaurklanerna ständigt. Kort efter det tredje kriget tillfångatog ett centaurkrigsband under Khiragg den unge Baine och försatte Cairne i en sorgedvala som nästan krossade de nygrundade bosättningarna. Först tack vare mästaren Rexxars mod kunde Baine befrias ur fångenskapen. Räddningen återgav Cairne hans kraft, så att tauren kunde stå tillsammans med Thralls Horde mot de invaderande Kul Tirans och säkra sitt fäste på kontinenten."},{t="Bloodhoof Villages beskyddare",b="I stället för att stanna i huvudstadens relativa bekvämlighet väljer Baine att bo bland sitt folk i Bloodhoof Village. I takt med att Cairne åldras tar Baine på sig ett allt större ansvar för ledarskapet och företräder nästa generation taurenledare. Han leder krigare och tillresta allierade i kampen mot de oregerliga Palemane-gnollerna som plågar gränstrakterna, och håller noga uppsikt över misstänkta utomstående krafter som hotar Mulgorets naturliga balans."},{t="Moder Jordas försvarare",b="Utöver gränsstrider möter Baine moderna inkräktare som inte bryr sig om den andliga balansen. I öster gräver goblinernas Venture Company djupt i det heliga landskapet, medan dvärgiska prospektörer från Bael Modan gräver i förfädernas jord vid Bael'dun Digsite. Baine förespråkar ett bestämt men sansat svar: att försöka varna gruvarbetarna och förstöra deras förödande utrustning i stället för att kasta sig in i meningslöst blodspillan. Han varnar för att dvärgarnas våldsamma grävande skadar jordens andar, men gruvarbetarna vägrar lyssna."}},faq={{q="Vem är Baine Bloodhoof?",a="Baine är Cairne Bloodhoofs ende son. Cairne är högöverhövding över taurenstammarna. Baine ansvarar för försvaret och stammens angelägenheter i Bloodhoof Village, där han leder de lokala krigarna och skyddar Mulgore medan hans far styr från Thunder Bluff.",al={"baine berättelse","vem är baine","cairnes son"}},{q="Var finns Baine just nu?",a="Baine står i Bloodhoof Village, mitt i Mulgore strax söder om Thunder Bluff. Du hittar honom nära byns centrum, där han fördelar uppgifter till nyanlända äventyrare.",al={"baines plats","var finns baine","baine bloodhoof plats"}},{q="Hur räddades Baine från centaurerna?",a="Efter det tredje kriget tillfångatog centaurledaren Khiragg Baine och försatte Cairne i förlamande sorg. Bestmästaren Rexxar sökte upp Bovan Windtotems utstötta, spårade centaurerna till deras läger, dödade fångvaktarna och återförde Baine tryggt till sin far.",al={"baine kidnappad","rexxar räddar baine","baine tillfångatagen"}},{q="Vilka problem hanterar Baine i Bloodhoof Village?",a="Baine samordnar insatser mot de aggressiva Palemane-gnollerna som trakasserar de lokala hjordarna och håller noga uppsikt över utländska inkräktare, som goblinernas Venture Company och Alliansens dvärgiska utgrävare som stör jorden.",al={"baine uppdrag","vad gör baine","problem i bloodhoof village"}},{q="Vad tycker Baine om dvärgarnas utgrävning vid Bael'dun?",a="Baine anser att gruvarbetarnas våldsamma grävande vid Bael'dun skadar jordens andar och vanhelgar landet. Han skickar resande för att ta deras verktyg och slå sönder dem, i hopp om att skrämma bort dem och lära dem att det inte leder till kunskap att gröpa ur landet.",al={"baine och dvärgarna","gruvdrift vid bael'dun","dvärgarnas utgrävning i mulgore"}},{q="Kommer Baine att efterträda Cairne som högöverhövding?",a="Som Cairnes son får Baine en allt större roll i att leda tauren medan hans far åldras, och många ser honom som den självklara arvtagaren till de förenade stammarna.",al={"blir baine ledare","framtida högöverhövding","cairnes arvtagare"}}},fx={["59aa4b20"]={q="Vilken sida står Baine Bloodhoof på?",a="Baine är helt hängiven taurenfolket och Horde. Som son till High Chieftain Cairne Bloodhoof är han trogen sin stam i Mulgore och den större allians som formats med Thralls orcher och Darkspear Trolls.",al={"baine bloodhoofs fraktion","är baine med i horde","baines lojalitet"}},["9cbf1856"]={q="Vad vill Baine Bloodhoof?",a="Baine vill trygga Mulgore och skydda det fredliga hemland som hans far säkrade åt folket. Just nu vill han slå tillbaka de aggressiva Palemane-gnollerna, undersöka Venture Companys verksamhet i öster och driva bort dvärggrävarna som skadar den heliga jorden vid Bael'dun Digsite.",al={"baine bloodhoofs mål","baines mål","vad vill baine"}},["1590aad3"]={q="Vilka band har Baine Bloodhoof?",a="Baine är son till High Chieftain Cairne Bloodhoof. Utöver familjen känner han en djup och bestående tacksamhetsskuld till Rexxar, Hordens mästare, som räddade honom ur fångenskap när kentaurplundrare hotade hans liv.",al={"baines familj","vilka är baines släktingar","baines förbindelser"}}},fp="15,171,25.470.0,29.373.0,26.453.0,23.199.0,35.150.0,39.242.0,53.198.0,55.252.0,44.149.0"}
P.entries["npc:balir-frosthammer"] = {n="Balir Frosthammer",s="Balir Frosthammer är en dvärgisk försvarare stationerad i Coldridge Valley i Dun Morogh. De plötsliga och aggressiva angreppen från Rockjaw-trogger i dvärgarnas länder oroar honom, och han rekryterar oerfarna äventyrare för att hejda vågen innan dalen blir översvämmad.",h="Balir Frosthammer är en dvärgisk försvarare stationerad i Coldridge Valley i Dun Morogh.",kw={"ett nytt hot","balir frosthammer","coldridge valley","dun morogh","rockjaw-trogger","tannok frosthammer"},ang={["faction:Alliance"]="Balirs insatser håller Coldridge Valley säkert som en viktig samlingsplats för alliansrekryter som börjar sin träning i Khaz Modan.",["race:Dwarf"]="För unga dvärgar står Balir Frosthammer i främsta ledet för att försvara deras hemland och ger dem deras allra första möjligheter att skydda Dun Morogh mot hot underifrån."},sec={{t="Försvaret av Coldridge Valley",b="Balir Frosthammer håller utkik efter annalkande faror från sin post i den snötäckta enklaven Coldridge Valley. Dalen har länge varit en trygg tillflykt och övningsplats för unga dvärgar och gnomer, men nya störningar under jord har drivit upp våldsamma Rockjaw-trogger till ytan. Balir är en av de första som slår larm och samlar nyanlända rekryter för att decimera troggerna innan de tränger längre in i Dun Morogh."},{t="Frosthammarnas släkt",b="Med det stolta efternamnet Frosthammer kan Balir vara släkt med Tannok Frosthammer från Kharanos. Deras familj står fast i sin plikt mot Ironforge och ser till att de kalla bergspassen förblir säkra för resenärer, gruvarbetare och bergsklättrare, även när hoten i området blir fler."}},faq={{q="Vem är Balir Frosthammer?",a="Balir Frosthammer är en dvärg stationerad i Coldridge Valley i Dun Morogh. Han ger nyanlända äventyrare i uppdrag att decimera de fientliga Rockjaw-troggerna som hotar dalens försvar.",al={"balir frosthammer vem är han","vem är balir"}},{q="Varför oroar Balir sig för troggerna?",a="Rockjaw-troggerna har nyligen tagit sig upp till ytan i stort antal, stört freden i Coldridge Valley och angripit dvärgarnas bosättningar. Balir inser att de blir ett allt större hot som måste hejdas tidigt.",al={"varför trogger","troggproblem coldridge"}},{q="Är Balir släkt med Tannok Frosthammer?",a="Kanske. Balir har samma namn, Frosthammer, som Tannok Frosthammer från Kharanos, vilket antyder att de är släkt, men det är inte bekräftat.",al={"tannok släkting","frosthammersläkten"}}},fx={c02dfef8={q="Vilken sida står Balir Frosthammer på?",a="Balir står fast på Ironforges och Alliances sida. Han är stationerad i Coldridge Valley, där han vakar över dvärgarnas hemland och arbetar tillsammans med andra bergsmän och rekryter för att hålla Dun Morogh tryggt mot nya faror.",al={"balir frosthammers fraktion","vem tjänar balir","är balir med i alliance"}},["14c400d2"]={q="Vad vill Balir Frosthammer?",a="Balir vill driva tillbaka Rockjaw-troggerna som börjat invadera dalen. Deras plötsliga uppdykande och aggressivitet oroar honom djupt, så han värvar stridsdugliga äventyrare för att rensa bort inkräktarna innan de tar över Coldridge.",al={"balir frosthammers drivkraft","vad behöver balir","varför behöver balir hjälp"}}},fp="17,99,24.334.0,23.263.0,25.156.0,40.168.0,39.142.0"}
P.entries["npc:balthule-shadowstrike"] = {n="Balthule Shadowstrike",s="Balthule Shadowstrike är en nattalvsscout i norra Darkshore, nära Tower of Althalaxx. Som framskjuten agent åt Delgren the Purifier håller han uppsikt över de olycksbådande kultisterna och mörkerutövarna i de forna alviska ruinerna. Äventyrare som färdas längs nordkusten hänvisas ofta till honom för att hjälpa till att avslöja och störa de mörka ritualer som pågår i tornet.",h="Balthule Shadowstrike är en nattalvsscout i norra Darkshore, nära Tower of Althalaxx.",kw={"althalaxx","balthule","kultister","darkshore","delgren","mathystra","purifier","scout","shadowstrike"},ang={["class:Rogue"]="Balthule verkar djupt inne på fientligt territorium, mitt framför näsan på farliga besvärjare, och visar prov på en sann alvisk scouts tålamod och vaksamhet.",["faction:Alliance"]="Balthule är en viktig kontakt i främsta ledet för Alliansens medlemmar som skickas norrut från Auberdine för att rensa bort de mörka kultister som verkar kring Tower of Althalaxx.",["race:NightElf"]="För nattalverna är de vidriga kultisternas skändning av de forna ruinerna i Kalimdor en skymf. Balthule vill hämnas den innan fördärvet sprider sig längre in i deras områden."},sec={{t="En scout i skuggorna",b="Balthule Shadowstrike håller ensam och farlig vakt i vildmarken strax väster om Tower of Althalaxx. Norra Darkshore är fullt av rastlösa andar och skuggade ruiner, men verksamheten kring tornet utgör ett särskilt akut hot. Balthule lyder under Delgren the Purifier och följer de mörka besvärjarnas rörelser. De har tagit sig in bland de forna lämningarna efter Highborne."},{t="Avslöja kulten",b="Trollkarlarna och kultisterna som tagit Tower of Althalaxx i besittning ägnar sig åt mörk, förbjuden magi och skördar artefakter och själar från ruinerna runtomkring. Balthule förlitar sig på resande hjältar från Alliansen som tar sig in på tornområdet, slår ut kultens ledare och hämtar skriftrullar och talismaner som avslöjar den verkliga omfattningen av deras kallelseritualer."}},faq={{q="Vem är Balthule Shadowstrike?",a="Balthule Shadowstrike är en nattalvsscout stationerad i norra Darkshore. Han fungerar som framskjuten scout och agent och samarbetar med Delgren the Purifier för att övervaka ondskefull kultverksamhet i området.",al={"vem är balthule","balthules roll","balthule shadowstrike npc"}},{q="Var finns Balthule Shadowstrike?",a="Han är stationerad i norra Darkshore, strax väster om det olycksbådande Tower of Althalaxx nära kusten.",al={"var finns balthule","balthules plats","hitta balthule shadowstrike"}},{q="Vad är hans uppdrag vid Tower of Althalaxx?",a="Han skickades för att spionera på de mörka besvärjarna och kultisterna som slagit sig ned i Tower of Althalaxx. Han hjälper till att samla underrättelser och samordna angrepp för att störa deras fördärvade ritualer.",al={"varför är balthule här","vad vill balthule","althalaxx uppdragsfigur"}},{q="Vem är Delgren the Purifier?",a="Delgren the Purifier är en mänsklig paladin stationerad vid Maestra's Post i Ashenvale. Han samordnar kampanjen mot de mörka krafter som hemsöker norra Darkshore. Balthule fungerar som hans ögon och öron i fält.",al={"vem är delgren","balthules överordnade","delgrens koppling"}},{q="Vilka slags fiender håller till i Tower of Althalaxx?",a="Tornet och dess omgivningar har tagits över av mörka kultister, trollkarlar och framkallade demoniska eller skuggfyllda tjänare, som vill utnyttja den forna Highborne-kraften i ondskefulla syften.",al={"vilka finns i tornet","althalaxxs fiender","kultister i tower of althalaxx"}},{q="Varför intresserar sig Alliansen för dessa ruiner?",a="Tower of Althalaxx är en forntida alvisk byggnad. Förekomsten av vidrig trolldom och demonisk aktivitet så nära alvernas områden utgör ett direkt hot mot Darkshores säkerhet och nattalverna i Darnassus.",al={"varför bry sig om tornet","alliansens närvaro i darkshore"}}},fx={d382c05d={q="Vilken sida står Balthule Shadowstrike på?",a="Balthule tjänar Alliance och sina nattälvskamrater. Han arbetar direkt som spejare och agent åt Delgren the Purifier och håller uppsikt över hot som växer fram i norra Darkshore.",al={"balthules fraktion","vem tjänar balthule","är balthule med i alliance"}},["67352a1e"]={q="Vad vill Balthule Shadowstrike?",a="Balthule vill avslöja de mörka ritualerna i Tower of Althalaxx. Genom att spionera på kultisterna som håller ruinen hoppas han samla tillräckligt med information för att Delgren the Purifier ska kunna rena den korruption som slår rot längs kusten.",al={"vad vill balthule","balthules mål","vad försöker balthule göra"}},d4776665={q="Varför är Balthule Shadowstrike här?",a="Sentinel Elissa Starbreeze från Auberdine skickade Balthule för att hålla vakt utanför Tower of Althalaxx. Han ligger gömd i närheten och ska observera de fientliga invånarna samt värva skickliga resenärer för att störa deras mörka planer.",al={"varför är balthule i darkshore","varför är balthule här","vad förde balthule hit"}}},fp="21,207,22.310.0,19.294.1,29.113.0,39.103.0,46.160.0,28.190.0,51.182.0,46.160.0"}
P.entries["npc:barithras-moonshade"] = {n="Barithras Moonshade",s="Barithras Moonshade är en Night Elf som bor i Auberdine i Darkshore. I kustbosättningen söker han hjälp av äventyrare som vill utforska den skuggiga vildmarken och samla sällsynta underjordiska växter.",h="Barithras Moonshade är en Night Elf som bor i Auberdine i Darkshore.",kw={"auberdine","barithras","grottsvampar","darkshore","death cap","moonshade","onu"},ang={["profession:Herbalism"]="Den som är mån om växtlivet uppskattar Barithras intresse för Darkshores ovanliga grottsvampar.",["race:NightElf"]="Barithras hjälper sina fränder i Auberdine att skydda Darkshore genom att hålla uppsikt över floran och bevara banden till forntida skogsväktare som Onu."},sec={{t="Bosatt i Auberdine",b="Barithras Moonshade håller vakt i byn Auberdine och bidrar till Night Elfs arbete med att utforska och hantera Darkshores oroliga marker. Han skickar resande till närliggande underjordiska grottor för att samla särskilda svampar, som Death Cap, för studier och bruk."},{t="Band till de forntida",b="Utöver de lokala växterna hjälper Barithras äventyrare söderut för att ta kontakt med Onu, en av de vördnadsvärda forntida som försöker läka Darkshores förgiftade jord och lugna dess rastlösa naturandar."}},faq={{q="Vem är Barithras Moonshade?",a="Barithras Moonshade är en Night Elf som bor i Auberdine vid Darkshores dimmiga kust. Han ger äventyrare i uppdrag att undersöka den lokala floran och kontakta traktens väktare.",al={"vem är barithras","barithras moonshade","vem är den här nattalven"}},{q="Var hittar jag Barithras Moonshade?",a="Han finns i hamnbosättningen Auberdine vid Darkshores kust.",al={"barithras plats","var finns barithras","barithras moonshade plats"}},{q="Vilka uppgifter ger Barithras?",a="Barithras skickar resande till närliggande grottor för att samla svampar, som den farliga Death Cap, och hänvisar senare äventyrare söderut för att träffa den forntida Onu.",al={"barithras uppdrag","vilka uppdrag ger barithras","grottsvampuppdrag"}},{q="Är Barithras släkt med de andra Moonshade?",a="Inga släktingar till Barithras finns dokumenterade, så eventuella band till andra Night Elfs med namnet Moonshade är okända.",al={"moonshadefamiljen","andra moonshade","är barithras släkt med sentinel moonshade"}}},fx={["1a832bfc"]={q="Vilken sida står Barithras Moonshade på?",a="Barithras Moonshade står fast på nattälvorna i Auberdines och Alliances sida. Han är stationerad i Darkshore, där han värnar om bosättningens väl och hjälper resenärer som skyddar den omgivande vildmarken.",al={"barithras moonshades fraktion","vem tjänar barithras","är barithras med i alliance"}},e41cf5ef={q="Vad vill Barithras Moonshade?",a="Barithras söker hjälp med lokala angelägenheter i Darkshore. Han skickar skickliga äventyrare för att samla resurser som grottsvampar och visar dem vidare till forna allierade som Onu i lundarna söderut.",al={"barithras moonshades mål","vad behöver barithras","barithras moonshades uppdrag"}}},fp="19,178,21.202.0,20.150.0,27.131.0,37.88.0,31.126.0,45.99.0"}
P.entries["npc:barkeep-daniels"] = {n="Barkeep Daniels",s="Barkeep Daniels sköter disken på Lakeshire Inn och serverar trötta stadsvakter, lokala fiskare och resande besökare. När Blackrock-klanen härjar i Redridge Mountains och skär av försörjningsvägarna har det blivit en kamp i motvind att hålla värdshuset välförsett.",h="Barkeep Daniels sköter disken på Lakeshire Inn och serverar trötta stadsvakter, lokala fiskare och resande...",kw={"barkeep daniels","bartender","daniels","dry times","lakeshire inn","värdshusvärd i redridge"},ang={["faction:Alliance"]="Att hålla moralen uppe i Lakeshire är avgörande för Alliansen, eftersom bosättningen fungerar som kungarikets illa tilltygade buffert mot Blackrock Stronghold i norr."},sec={{t="Hålla humöret uppe i Lakeshire",b="Bakom disken på Lakeshire Inn står Barkeep Daniels, häller upp drycker och hälsar alla som kommer in från bron välkomna. Lakeshire har i månader varit under ständig press från gnoller och Blackrock-orcher, och stadens försvarare förlitar sig på värdshuset för att koppla av efter dystra patruller. Tyvärr för Daniels har avskurna vägar och oupphörliga angrepp stört handeln i hela regionen. Han börjar få farligt ont om sprit just när staden behöver gott humör som mest, och tar gärna emot hjälp från varje äventyrare som passerar och kan hämta leveranser från tryggare bosättningar."}},faq={{q="Vem är Barkeep Daniels?",a="Barkeep Daniels är en mänsklig värdshusvärd som arbetar bakom disken på Lakeshire Inn. Han tar emot dryckesbeställningar från lokalbefolkningen, resande äventyrare och den hårt prövade stadsvakten.",al={"daniels redridge","värdshusvärd lakeshire","vem är daniels"}},{q="Varför börjar dryckerna ta slut?",a="Pågående räder från Blackrock-orcherna och närliggande gnollstammar har strypt tillförseln av försörjningskaravaner och handelsvägar in i Redridge Mountains. När leveranserna uteblir och pressade försvarare dricker ur de befintliga förråden kämpar Daniels med att fylla hyllorna igen.",al={"varför slut på sprit","lore om uppdraget dry times","varför ingen alkohol"}},{q="Vad behöver han hjälp med?",a="Genom uppdraget 'Dry Times' söker Daniels resande som är villiga att ge sig ut och hämta nya spritleveranser utanför Redridge, så att värdshusets gäster blir nöjda.",al={"uppdrag med barkeep daniels","vad vill han ha","daniels ärende"}}},fx={["2f43c9bf"]={q="Vilken sida står Barkeep Daniels på?",a="Barkeep Daniels är en trogen medborgare i Alliance och en självklar del av Lakeshire. Han betjänar ortsbor, besökare och stadens försvarare bakom disken på Lakeshire Inn. Han står stadigt med Stormwinds kungarike inför det växande Blackrock-hotet.",al={"barkeep daniels fraktion","är barkeep daniels med i alliance","daniels lojalitet i redridge"}}},fp="15,216,33.415.0,23.115.0,32.218.0,28.108.0"}
P.entries["npc:baron-aquanis"] = {n="Baron Aquanis",s="Baron Aquanis är en mäktig vattenelementar i de översvämmade Moonshrine Ruins i Blackfathom Deeps, där Twilight's Hammer har slagit läger. Han stiger upp ur djupet när någon stör ruinernas Fathom Stone. Earthen Rings schamaner har länge trott att han är en förvriden elementarkraft, och de misstänker att kulten ligger bakom det.",h="Baron Aquanis är en mäktig vattenelementar i de översvämmade Moonshrine Ruins i Blackfathom Deeps, där...",kw={"aquanis","baron aquanis","blackfathom deeps","earthen ring","fathom core","fathom stone","je'neu sancrea","moonshrine ruins","twilight's hammer","vattenelementar"},ang={["class:Shaman"]="För Earthen Rings schamaner är Baron Aquanis ett tragiskt exempel på hur elementar krafter förvrids. Hans besudlade kvarlevor kan ge avgörande insikter om hur förvridna andar renas.",["faction:Horde"]="Je'neu Sancrea samarbetar med Horde vid Ashenvales kust, och Fathom Core som hans Hordehjälpare hämtar ska visa vad Twilight's Hammer gör med elementen där."},sec={{t="Fathom Stones väktare",b="Under de översvämmade salarna i Moonshrine Ruins ligger Fathom Stone, mitt framför näsan på Twilight's Hammers kultister som nu håller till i ruinerna. Inuti finns en Fathom Core, en anordning som, om den avläses rätt, berättar historien om all elementar aktivitet i området. Je'neu Sancrea från Earthen Ring skickar Hordeäventyrare för att hämta kärnan, och när stenen störs stiger Baron Aquanis upp ur djupet."},{t="Djupens förvridning",b="Earthen Ring har länge betraktat Baron Aquanis som en förvriden elementarkraft. När han besegras lämnar han efter sig en Strange Water Globe: en oförstörbar klotformad behållare med stinkande, skvalpande vatten som tycks ha gett honom energi. Je'neu Sancrea tror att klotet kan visa vad som förvridit baronen och hur. Han skulle inte bli förvånad om det visade sig vara Twilight's Hammer."}},faq={{q="Var hittar jag Baron Aquanis?",a="Baron Aquanis håller till i de översvämmade Moonshrine Ruins, djupt inne i Blackfathom Deeps. Han strövar inte omkring i salarna: han stiger upp ur vattnet när ruinernas Fathom Stone under vattnet störs, vilket Hordeäventyrare gör när de hämtar dess Fathom Core åt Je'neu Sancrea.",al={"aquanis plats","var finns baron aquanis","hur framkallar man baron aquanis"}},{q="Vad är Strange Water Globe?",a="Strange Water Globe är vad Baron Aquanis lämnar efter sig när han besegras: ett klot som ingen fysisk kraft kan krossa, med stinkande vatten som skvalpar därinne. Det tycks ha gett elementaren energi. Je'neu Sancrea från Earthen Ring vill undersöka det och tror att det kan visa vad som förvridit baronen och hur det gick till.",al={"strange water globe","aquanis klot","vad används vattenklotet till"}},{q="Varför intresserar sig Earthen Ring för Baron Aquanis?",a="Earthen Ring vakar över elementens balans. Je'neu Sancrea och hans kamrater har länge trott att Baron Aquanis är en förvriden elementarkraft, och nu när Twilight's Hammer finns i Moonshrine Ruins fruktar de att kulten tvingar elementen att motarbeta Horde. Baronens kvarlevor och ruinernas Fathom Core kan visa vad kulten håller på med.",al={"varför bryr sig earthen ring","je'neu sancrea aquanis"}},{q="Vad är Fathom Core?",a="Fathom Core är en elementarartefakt som finns i den sjunkna Fathom Stone. När en kunnig schaman läser av den på rätt sätt avslöjar den en utförlig historik över elementar aktivitet i området och blottlägger vilka mörka ritualer Twilight's Hammer utför i ruinerna.",al={"fathom core bakgrund","vad gör fathom core"}},{q="Är Baron Aquanis allierad med Twilight's Hammer?",a="Inte frivilligt, så vitt någon kan avgöra. Earthen Ring betraktar honom som en förvriden elementar, inte som en villig tjänare, och Twilight's Hammers kultister som håller Moonshrine Ruins är de självklara misstänkta. Je'neu Sancrea säger att han inte skulle bli förvånad om de låg bakom det, men han vill ha bevis innan han säger det säkert.",al={"är aquanis med i twilight's hammer","aquanis kult"}},{q="Har Alliance något med Baron Aquanis att göra?",a="Inte direkt. Fathom Stone, och därmed Baron Aquanis, är Je'neu Sancreas angelägenhet: han är en schaman i Earthen Ring som samarbetar med Horde vid Ashenvales kust, och det är Hordeäventyrare han skickar för att hämta Fathom Core. Allianceutforskare i Blackfathom Deeps har andra uppdrag där.",al={"kan alliance strida mot aquanis","alliance-uppdrag om aquanis"}}},fp="13,237,28.401.0,24.376.1,31.235.0,32.274.0,52.356.0,24.267.0,51.289.0,51.277.0"}
P.entries["npc:baron-revilgaz"] = {n="Baron Revilgaz",s="Baron Revilgaz är den listige goblinledaren för Booty Bay och Blackwater Raiders, och styr piratnästet på uppdrag av Steamwheedle Cartel. Från sin högt belägna balkong på Salty Sailor Tavern balanserar han skör handelsneutralitet med hänsynslös opportunism. Han anlitar kringresande legosoldater för att säkra sina investeringar, underminera rivaler som Bloodsail Buccaneers och hämta uråldriga reliker från djungeln.",h="Baron Revilgaz är den listige goblinledaren för Booty Bay och Blackwater Raiders, och styr piratnästet på...",kw={"blackwater raiders","bloodsail buccaneers","booty bay","lake nazferiti","revilgaz","salty sailor tavern","seahorn","steamwheedle cartel","stone of the tides"},ang={["class:Rogue"]="Revilgaz respekterar tjuvar, spioner och opportunister. Han anlitar ofta skurkar för stölder med mycket på spel, sabotage mot rivaliserande handelskarteller och hemliga hämtningar av sällsynta djungelartefakter.",["faction:Alliance"]="Booty Bay ligger på ruinerna av den mänskliga enklaven Blackwater Cove från tiden före det första kriget, som tillhörde Stormwind. När kunskap om forntiden kan ge vinst samarbetar Revilgaz regelbundet med lärda och bibliotekarier i Stormwind.",["profession:Engineering"]="Revilgaz håller sig engagerad i goblinernas tekniska rivaliteter och använder ohederliga metoder för att säkra avancerade ritningar och bränsleregulatorer från Venture Company."},sec={{t="Booty Bays mästare",b="Från sin utsiktsplats ovanpå Salty Sailor Tavern bevakar Baron Revilgaz de livliga hamnarna i Blackwater Cove genom ett specialtillverkat förtrollat kikarsikte. Med sin betrodde rådgivare, taurenen Fleet Master Seahorn, vid sin sida utövar Revilgaz fast kontroll över stadens ficktjuvar, köpmän och kapare. Hamnen var ursprungligen en mänsklig bosättning som troll övermannade före det första kriget. Gobliner tog sedan över och befäste den, och med tiden blev den ett kommersiellt nav med piratprägel för Blackwater Raiders. Revilgaz ser till att hamnen officiellt förblir öppen för både alliansens och hordens resenärer och upprätthåller strikt neutralitet inom hamnområdet så att handeln kan fortsätta utan avbrott."},{t="Ett nät av ambitioner",b="Revilgaz inflytande sträcker sig långt bortom hamnen. När affärerna stagnerade efter de senaste krigen på andra håll i Azeroth tog han vara på upptäckten av tastyfish och grundade Stranglethorn Fishing Extravaganza för att locka folk tillbaka till sina stränder. I Stranglethorn Vale håller han noga uppsikt över konkurrenter och möjliga hot: han beställer sabotage mot Venture Company vid Lake Nazferiti, övervakar noga Nesingwarys jaktexpedition och mänskliga militärläger i norr och upprätthåller handelskontakter inom kapplöpningen med Monte Gazlowe och Pozzik vid Mirage Raceway."},{t="Stone of the Tides",b="Bakom Revilgaz handelsfasad döljer sig en besatthet av uråldrig kraft och rikedom. Efter att ha undersökt rykten om en hemsökt ö utanför kusten skickar Revilgaz ut äventyrare för att hitta den legendariska Stone of the Tides. För att hitta den måste de rådfråga uråldriga böcker i Stormwind Library, studera elementära rester tillsammans med Archmage Ansirem Runeweaver och återta en uråldrig trolldolk från Bloodsail Buccaneers. Dolken ska krossa kustaltaret som skyddar stenen. På så sätt bryter Revilgaz en dödlig elementförbannelse och säkrar den ovärderliga reliken åt sina egna valv."}},faq={{q="Vem är Baron Revilgaz?",a="Baron Revilgaz är härskaren över Booty Bay och ledaren för Blackwater Raiders. Han styr piratnästet på uppdrag av det neutrala Steamwheedle Cartel, med en blandning av hänsynslös girighet och diplomatisk pragmatism.",al={"vem är revilgaz","revilgaz bakgrund","booty bays boss","booty bays ledare"}},{q="Var hittar man Baron Revilgaz?",a="Han står på den översta balkongen på Salty Sailor Tavern i Booty Bay och blickar ut över viken tillsammans med sin betrodde rådgivare, Fleet Master Seahorn.",al={"var finns revilgaz","revilgaz plats","hur hittar man revilgaz"}},{q="Vilken relation har Revilgaz till Bloodsail Buccaneers?",a="De är bittra fiender. Bloodsail Buccaneers följer inte Steamwheedle Cartels regler och plundrar aktivt Booty Bays handelsfartyg. Bloodsails ledare planerar regelbundet mord på Revilgaz och Seahorn.",al={"revilgaz bloodsail","bloodsail mot revilgaz","varför hatar de bloodsail"}},{q="Vad har Revilgaz för intressen vid Mirage Raceway?",a="Revilgaz sponsrar goblinernas racinglag, lett av Pozzik, i tävlingarna mot gnomerna i The Shimmering Flats. Han använder äventyrare för att stjäla Venture Companys egna ritningar till bränsleregulatorer vid Lake Nazferiti och leverera dem till kapplöpningsbanan.",al={"revilgaz kapplöpning","revilgaz shimmering flats","revilgaz pozzik"}},{q="Vad är Stranglethorn Fishing Extravaganza?",a="När handeln minskade på grund av regionala krig på andra håll i Azeroth stöttade Revilgaz en fiskare vid namn Riggle Bassbait efter att ha smakat den lokala ”tastyfish”. Revilgaz gjorde fångsten till en veckovis fisketävling längs Stranglethorns kust för att få fart på Booty Bays ekonomi.",al={"fiskeloppets bakgrund","vem startade fisketävlingen","tastyfish revilgaz"}},{q="Vad är Stone of the Tides?",a="Det är en uråldrig, förbannad magisk sten som gömts vid The Vile Reef. Revilgaz finner berättelsen om den i Stormwinds arkiv och anlitar forskaren från Dalaran, Archmage Ansirem Runeweaver, för att hjälpa äventyrarna att montera ned dess elementära skydd och göra anspråk på reliken.",al={"stone of the tides uppdrag","stenen vid vile reef","tidernas altare"}}},fp="14,425,19.682.0,17.589.0,22.572.1,22.222.0,34.143.0,62.231.0,47.242.0,47.274.0,31.245.1"}
P.entries["npc:baron-silverlaine"] = {n="Baron Silverlaine",s="Baron Silverlaine var den rättmätige mänsklige länsherren över fästningen som en gång kallades Silverlaine Keep, högt ovanför Pyrewood Village. När ärkemagikern Arugal släppte lös de vilda worgen i trakten blev baronen skoningslöst slaktad. Nu dröjer hans plågade ande kvar i den förstörda matsalen, bunden i odödlighet till hålan som blev hans grav.",h="Baron Silverlaine var den rättmätige mänsklige länsherren över fästningen som en gång kallades Silverlaine...",kw={"arugal","baron","spöke","stora salen","fästning","pyrewood","shadowfang","silverlaine","worgen"},ang={["class:Mage"]="Silverlaines öde är en bister varning för magisk vårdslöshet. När konsten att frammana missbrukas, som ärkemagikern Arugal gjorde, går oskyldiga liv till spillo och outplånliga ärr lämnas kvar.",["race:Human"]="Silverlaine är ett bittert vittnesmål om hur mänsklig adel förlorade sin makt vid Gilneas gräns. Hans fästning översvämmades av en Dalaran-utbildad trollkarls magiska övermod.",["race:Undead"]="För Forsaken som tränger fram genom Silverpine är Silverlaines vålnad bara ännu en kvarleva från den gamla aristokratin som måste röjas undan för att bryta Arugals grepp om fästningen."},sec={{t="Silverlaine Keeps fall",b="Innan varg bestarnas skugga lade sig över Silverpines södra kullar styrde Baron Silverlaine över ett stolt adelsgods. Hans fästning skyddade och övervakade de omgivande länderna. Freden krossades när ärkemagikern Arugal, som sökte ett vapen mot den framryckande Scourge, släppte lös frammanade worgen i trakten. De vildsinta monstren gick inte att kontrollera. De stormade fästningen, övermannade vakterna och slaktade baronen."},{t="En plågad vålnad",b="Döden gav ingen befrielse åt Baron Silverlaine. Bunden till fästningens uråldriga stora sal vandrar hans rastlösa vålnad nu bland de omkullvälta matborden där han en gång höll festmåltider. Den förbannade länsherren går till angrepp mot inkräktare som kommer in i hans förfallna hem."}},faq={{q="Vem var Baron Silverlaine?",a="Han var den adlige mänsklige härskaren över fästningen som ursprungligen hette Silverlaine Keep, belägen ovanför Pyrewood Village. Han dödades när worgen intog fästningen.",al={"baron silverlaine historia","vem är silverlaine","vem styrde shadowfang"}},{q="Varför hemsöker han Shadowfang Keep?",a="Silverlaine slaktades i sitt eget hem under worgenanfallet som ärkemagikern Arugal släppte lös. Hans vålnad förblev förbunden med matsalen i hans förstörda fästning efter döden och kan inte gå vidare.",al={"varför är silverlaine ett spöke","är silverlaine död","silverlaines ande"}},{q="Varför angriper Silverlaine inkräktare?",a="Hans förbannade ande dröjer kvar i hans forna hem, där han angriper inkräktare i stora salen.",al={"varför angriper silverlaine","silverlaines vålnad","silverlaine inkräktare"}},{q="Var i fästningen kan man hitta honom?",a="Baron Silverlaine hemsöker stora salen, som var fästningens praktfulla matsal innan den förstördes när hans gods föll.",al={"var finns silverlaine","baron silverlaines plats","silverlaines matsal"}},{q="Vad kallades Shadowfang Keep före worgenanfallet?",a="Den kallades ursprungligen Silverlaine Keep, efter baronens adelsfamilj som härskade där innan Arugal tog kontrollen.",al={"shadowfangs ursprungliga namn","silverlaine keeps historia","shadowfangs gamla namn"}},{q="Överlevde någon i Silverlaines familj?",a="Inga uppgifter säger det. De gamla rapporterna berättar bara att worgen belägrade baronens fästning och att hans hämndlystna vålnad fortfarande hemsöker den. Inget finns dokumenterat om resten av hans hushåll.",al={"silverlaines familj","överlevde silverlaines familj","silverlaines arvingar"}}},fx={["1b1b3783"]={q="Vilken sida står Baron Silverlaine på?",a="Baron Silverlaine slåss för ingen annan än sig själv och minnena av sin förstörda egendom. Han mördades när Archmage Arugal släppte lös de vilda worgen på slottet, och döden har förvridit hans spöklika sinne. Bunden av en bitter förbannelse angriper han urskillningslöst alla levande inkräktare som kommer in i hans matsal.",al={"baron silverlaines fraktion","vem slåss silverlaine för","står baron silverlaine på arugals sida"}},["5d3ddd3d"]={q="Vad vill Baron Silverlaine?",a="Baron Silverlaine är fångad som en hämndlysten vålnad och vill bara driva bort eller slakta alla som vågar invadera hans hem. Hans våldsamma död plågar honom, och hans ande rasar obevekligt mot dem som stör hans fästnings urgamla salar.",al={"vad vill silverlaine","baron silverlaines mål","varför anfaller silverlaine"}},["02c6a3ca"]={q="Vilka band har Baron Silverlaine?",a="Baron Silverlaines tragiska öde är knutet till Archmage Arugal. När Arugal kallade på worgen från en annan dimension för att bekämpa Scourge blev bestarna glupska och belägrade Silverlaines fäste. Arugal tog borgen och gjorde den till Shadowfang Keep, och baronens hämndlystna spöke hemsöker den än i dag.",al={"silverlaines band","vem har silverlaine band till","baron silverlaine och arugal"}}},fp="17,189,28.379.0,19.208.0,26.120.0,35.168.0,40.103.0,34.116.0,57.140.0,43.176.0"}
P.entries["npc:baros-alexston"] = {n="Baros Alexston",s="I Stormwinds stadshus håller Baros Alexston uppsikt över huvudstaden han hjälpte till att återuppbygga. Han var en gång nära vän med Edwin VanCleef i Stonemasons Guild, men förblev kronan trogen när gillet splittrades.",h="I Stormwinds stadshus håller Baros Alexston uppsikt över huvudstaden han hjälpte till att återuppbygga.",kw={"alexston","arkitekt","baros","cathedral square","stadshus","defias","gård","stonemasons","oskickat brev","vancleef"},ang={["class:Rogue"]="Som skurk i Stormwind har du genom Baros en koppling till Master Mathias Shaw och SI:7, som i tysthet står i skuld till arkitekten trots hans tidigare band till VanCleef.",["faction:Alliance"]="Som medlem i Alliansen kan du se den smärtsamma kompromiss som splittrade Stonemasons Guild i Baros. Hantverkarna hade ägnat sina liv åt att återuppbygga huvudstaden.",["race:Human"]="Som människa från Westfall kanske du känner igen Baros efternamn från den förstörda Alexston Farmstead, som nu översvämmas av tjuvar och gnoller."},sec={{t="Från gården till schavotten",b="Baros växte upp på Alexston Farmstead i Westfalls böljande gräsmarker. Tjuvar intog och brände familjens gård när han var ung. Innan de flydde gömde hans far hastigt familjens kära arvegods runt om på ägorna. Baros reste senare till huvudstaden och gick med i Stonemasons Guild. I flera år arbetade han sida vid sida med gildmästaren Edwin VanCleef medan de byggde upp Stormwind på nytt ur askan efter det första kriget."},{t="En bitter skilsmässa",b="När återuppbyggnaden av Stormwind var klar vägrade House of Nobles att betala det överenskomna beloppet. Våldsamma protester följde, Stonemasons Guild upplöstes och dödliga upplopp fyllde gatorna. Edwin VanCleef ledde de obetalda hantverkarna i exil, där de bildade Defias Brotherhood. Adelsmännen erbjöd Baros posten som stadsarkitekt om han tog avstånd från upproret. Baros motsatte sig gillets övergång till våldsamt röveri och tackade ja, vilket skapade en bitter spricka mellan honom och hans forna kamrater."},{t="Spöket i Deadmines",b="Baros övervakar huvudstadens underhåll från sitt skrivbord i stadshuset, och Mathias Shaw från SI:7 står diskret i skuld till honom. Efter att VanCleef föll i djupet av Deadmines låg ett oskickat brev adresserat till Baros kvar på ledaren för Defias kropp. Brevet påminner om bandet som bröts av politik, förräderi och blodsutgjutelse kring Stormwinds grundvalar."}},faq={{q="Var hittar jag Baros Alexston?",a="Du hittar Baros Alexston inne i Stormwinds stadshus, på norra sidan av Cathedral Square i Stormwind City.",al={"baros alexstons plats","var finns baros alexston","baros stormwind"}},{q="Vilken roll har Baros Alexston i Stormwind?",a="Baros ansvarar för byggandet, underhållet och den arkitektoniska planeringen i Stormwind City som stadens chefsarkitekt.",al={"baros arbete","baros titel","vad gör baros"}},{q="Hur känner Baros Edwin VanCleef?",a="Baros och Edwin VanCleef var nära kollegor i Stonemasons Guild och arbetade sida vid sida för att återuppbygga Stormwind efter det första kriget. När House of Nobles vägrade att betala arbetarna ledde VanCleef ett uppror, medan Baros stannade kvar och blev stadsarkitekt.",al={"baros och vancleef","kände baros edwin","baros stonemasons"}},{q="Varför gick Baros inte med i Defias Brotherhood?",a="Baros motsatte sig gillets övergång till våldsamt uppror. Adelsmännen erbjöd honom posten som stadsarkitekt på villkor att han vägrade följa VanCleef, och Baros tackade ja.",al={"varför stannade baros","baros och defias splittring","varför svek baros stonemasons"}},{q="Vad är det oskickade brevet som hittades på Edwin VanCleef?",a="Efter att Edwin VanCleef dog i Deadmines hittades ett oskickat brev adresserat till Baros Alexston på hans kropp. Det vittnar om kvarstående bitterhet och olöst historia mellan de forna hantverkarna.",al={"uppdraget oskickat brev","vancleefs oskickade brev","brev till baros"}},{q="Vilken koppling har Baros Alexston till Westfall?",a="Baros växte upp på Alexston Farmstead i Westfall, och efter att tjuvar brände gården flydde familjen. Han rekryterar äventyrare för att återta sina barndomssaker, däribland sin första kompass.",al={"alexston farmstead","baros westfall","baros barndom"}}},fx={["47ce41c7"]={q="Varför är Baros Alexston i Stormwind City Hall?",a="Baros Alexston arbetar från City Hall i Cathedral Square som Stormwinds chefsarkitekt. När Stonemasons Guild gjorde uppror på grund av obetalda löner vägrade Baros att delta i Edwin VanCleefs våldsamma resning. Som tack för sin lojalitet och brytning med gillets idéer erbjöd kronan honom den officiella posten som stadsarkitekt. Där övervakar han kungarikets offentliga arbeten och byggprojekt.",al={"varför är baros alexston här","varför är baros alexston i city hall","vad gör baros i stormwind"}},["8a4dbaf4"]={q="Vad vill Baros Alexston?",a="Baros vill tjäna Stormwind hederligt och samtidigt konfrontera sitt förflutnas spöken. På det personliga planet vill han återfå förlorade arvegods från familjen, som sin första kompass, som gömdes undan innan tjuvar brände ner hans barndomsgård i Westfall. Politiskt oroar han sig djupt för att avslöja förräderi i staden och få slut på Defias Brotherhoods våldsamma kampanj.",al={"baros alexstons drivkrafter","vad vill baros","baros mål"}}},fp="14,189,34.402.0,24.486.1,27.341.1,32.112.0,43.104.0,35.263.1,45.150.1,50.198.1,48.185.0"}
P.entries["npc:bartleby"] = {n="Bartleby",s="Bartleby dricker och söker bråk på Pig and Whistle Tavern i Stormwinds Old Town. Hans envisa grepp om ölmuggen blir ett prov för blivande krigare som måste möta honom i ett krogslagsmål.",h="Bartleby dricker och söker bråk på Pig and Whistle Tavern i Stormwinds Old Town.",kw={"bartleby","slagsmål","burlguard","berusad","mugg","old town","pig and whistle","krog","krigare"},ang={["class:Warrior"]="Som ung krigare i Stormwind minns du din duell med Bartleby. Att ta muggen från den envisa suputen blir ett minnesvärt prov i närstrid.",["race:Human"]="Som människa ser du den råa arbetarklassidan av Stormwinds Old Town, där lokala tvister avgörs över vältade barstolar snarare än genom kungliga påbud."},sec={{t="En självklar del av Pig and Whistle",b="Bartleby tillbringar sina dagar på Pig and Whistle Tavern i Stormwinds Old Town. Krogen lockar ett råare klientel än ölstugorna på Cathedral Square. Han klamrar sig fast vid sin favoritmugg, dricker billigt öl, ältar oförrätter och söker bråk med alla som stör honom."},{t="En krigares övergångsprov",b="Stormwinds krigarlärare ser Bartleby som ett praktiskt prov. Harry Burlguard skickar nybörjarkrigare för att hitta honom och ta hans mugg. De måste utbyta knytnävsslag med den berusade slagskämpen och visa att de har mod nog att möta en oregerlig motståndare på nära håll."}},faq={{q="Vem är Bartleby?",a="Bartleby är en oregerlig gäst på Pig and Whistle Tavern i Stormwinds Old Town. Han blir redlöst berusad och vägrar lämna ifrån sig muggen utan ett slagsmål.",al={"bartlebys historia","vem är bartleby","bartleby stormwind"}},{q="Var hittar jag Bartleby?",a="Du hittar Bartleby när han dricker på bottenvåningen av Pig and Whistle Tavern i Stormwinds Old Town.",al={"bartlebys plats","var finns bartleby","bartleby pig and whistle"}},{q="Varför måste krigare slåss mot honom?",a="Harry Burlguard, en krigarlärare i Old Town, skickar unga rekryter till Bartleby för att pröva deras stridsförmåga. Att ta muggen med våld visar att de kan hantera ett plötsligt slagsmål och en tuff motståndare.",al={"varför besegra bartleby","krigaruppdrag bartleby","bartlebys syfte"}},{q="Vad händer när du utmanar honom?",a="När Bartleby utmanas på muggen dricker han en dryck som stärker hans uthållighet och blir fientlig. Han slåss obeväpnad på krogen tills han besegras och ger upp.",al={"slåss mot bartleby","uppdrag att besegra bartleby","slagsmål med bartleby"}},{q="Tillhör Bartleby någon fraktion eller organisation?",a="Bartleby är civil i Stormwind och en notorisk suput. Han har inga kända band till Defias Brotherhood eller stadsvakten.",al={"är bartleby defias","bartlebys fraktion","bartleby alliance"}},{q="Varför lämnar han inte bara ifrån sig muggen?",a="Bartleby är stridslysten, kraftigt berusad och envis. Han ser önskemål om drycken eller muggen som förolämpningar och föredrar att göra upp med knytnävarna framför att skiljas från spriten.",al={"bartlebys mugg","bartlebys ölsejdel","varför slåss om muggen"}}},fx={["59ff692a"]={q="Varför är Bartleby här i Old Town?",a="Bartleby tillbringar dagarna med att supa på Pig and Whistle Tavern. Han har inga stora ambitioner eller plikter i Old Town, utan hänger vid baren, smuttar på sitt öl och vaktar sin dyrbara mugg mot alla som vågar störa honom.",al={"varför är bartleby på pig and whistle","varför är bartleby där","varför är bartleby i stormwind"}}},fp="8,194,32.256.0,27.267.0,16.166.0,26.105.0,34.193.0,35.159.0,52.126.0,36.184.0"}
P.entries["npc:bashana-runetotem"] = {n="Bashana Runetotem",s="Bashana Runetotem är ört läkare och druidisk forskare bosatt på Elder Rise i Thunder Bluff. Som dotter till Archdruid Hamuul Runetotem hjälper hon Cenarion Circle genom att övervaka jordbruksundersökningar och vägleda Hordens äventyrare mot korrumperande krafter.",h="Bashana Runetotem är ört läkare och druidisk forskare bosatt på Elder Rise i Thunder Bluff.",kw={"bashana","blackfathom deeps","cenarion circle","elder rise","hamuul","morrowgrain","runetotem","thunder bluff"},ang={["class:Druid"]="För tauren-druider som lär sig sitt hantverk under hennes far Hamuul visar Bashana vilket aktivt fältarbete som krävs för att förstå Kalimdors föränderliga ekologi.",["faction:Horde"]="Bashana fungerar som en viktig länk mellan Cenarion Circles representanter i Thunder Bluff och Hordens hjältar som vill slå till mot kultisthot."},sec={{t="En dotter av Cirkeln",b="På de vindpinade höjderna på Elder Rise för Bashana Runetotem vidare sin far, Archdruid Hamuul Runetotems, druidiska arv. Medan hennes far vägleder de växande tauren-druiderna och ger Cairne Bloodhoof råd, fokuserar Bashana på praktisk forskning om botaniska avvikelser och regionala hot. Hon förser resenärer med redskap som ständigt gröna påsar för att odla mystisk flora, särskilt det gåtfulla morrowgrain, samtidigt som hon samordnar Hordens insatser för att rena den otäcka korruption som sprids från platser som Blackfathom Deeps."}},faq={{q="Vem är Bashana Runetotem?",a="Bashana är en tauren-druid och forskare som bor på Elder Rise i Thunder Bluff. Hon är dotter till Archdruid Hamuul Runetotem och arbetar för Cenarion Circle med att studera märklig flora och organisera insatser mot naturhot i Kalimdor.",al={"vem är bashana","bashanas bakgrund","vem är bashana runetotem"}},{q="Vilken forskning bedriver hon om morrowgrain?",a="Bashana anlitar Hordens äventyrare för att odla och samla in morrowgrain med hjälp av fröpåsar och jord. Cenarion Circle studerar denna kraftfulla, mystiska ört för att förstå dess ovanliga egenskaper och koppling till större botaniska gåtor som uppdagas i Kalimdor.",al={"forskning om morrowgrain","vad gör bashana med morrowgrain","varför morrowgrain"}},{q="Vilken koppling har hon till Blackfathom Deeps?",a="Bashana tar emot rapporten och bevisen från äventyrare som Argent Guard Thaelrid skickat för att konfrontera kultisterna i Blackfathom Deeps. Hon belönar deras hjälp med att bekämpa korruptionen som hotar Ashenvale.",al={"bashana blackfathom deeps","uppdraget blackfathom villainy","varför bfd"}},{q="Var hittar man henne?",a="Hon finns på Elder Rise i Thunder Bluff, mesan som är tillägnad stadens schamaner, druider och andliga äldste, nära druidernas paviljonger.",al={"var finns bashana runetotem","bashanas plats","hur hittar man bashana"}}},fx={["10189cb7"]={q="Vilka band har Bashana Runetotem?",a="Bashana är dotter till ärkedruiden Hamuul Runetotem, den vördnadsvärde ledaren för taurernas druider i Thunder Bluff. Under hans ledning bedriver hon viktig forskning på uppdrag av Cenarion Circle och hjälper till att vägleda nya mästare som vill stödja druidernas arbete.",al={"bashana runetotems familj","vem är bashana släkt med","bashana hamuuls dotter"}},["2d6e22c9"]={q="Vilken sida står Bashana Runetotem på?",a="Bashana är hängiven både Horde och Cenarion Circle. Som tauren-druid i Thunder Bluff arbetar hon för sitt folk och den bredare Horden, samtidigt som hon följer Cenarion-druidernas naturvärnande principer. De studerar mysterierna och korruptionen som plågar Kalimdor.",al={"bashana runetetems fraktion","vem tjänar bashana","bashana, horde eller cenarion circle"}}},fp="17,164,24.437.0,25.238.0,48.219.0,44.194.0,23.151.0"}
P.entries["npc:bath-rah-the-windwatcher"] = {n="Bath'rah the Windwatcher",s="Bath'rah the Windwatcher är en ensam djungeltrollschaman och vapensmed som bor bland ruinerna nära Chillwind Point. Långt från sitt tropiska hemland studerar han de stormiga elementen i de norra bergen och söker mäktiga kämpar som kan hjälpa honom att smida väldiga vapen av vind.",h="Bath'rah the Windwatcher är en ensam djungeltrollschaman och vapensmed som bor bland ruinerna nära Chillwind...",kw={"alterac","bath'rah","chillwind","cyclonian","elementar","schaman","whirlwind","windwatcher"},ang={["class:Shaman"]="Som elementens jämlike känner Bath'rah en djup andlig samhörighet med schamaner som söker en närmare gemenskap med jordens, vattnets och luftens andar.",["class:Warrior"]="Bath'rah är berömd bland veteraner för att vägleda dem genom prövningarna som krävs för att smida ikoniska Whirlwind-vapen med hjälp av elementaren Cyclonians essens."},sec={{t="Eremit bland bergstopparna",b="Medan de flesta djungeltroll håller sig till söderns varma skogar och kuster har Bath'rah valt ett ensamt liv som bergeremit bland de kalla ruinerna i Alterac Mountains. Som erfaren schaman och hantverkare ägnar han dagarna åt att lyssna på de tjutande vindarna och samtala med naturandar. Hans besatthet är inte bara filosofisk. Han vill binda våldsamma elementstormars raseri i påtagliga vapen åt dem som har styrkan att svinga dem."},{t="Cyclonians mästare",b="Bath'rahs största ambition kretsar kring Cyclonian, en monstruös vindelementar som håller till bland de omgivande bergstopparna. Eftersom han inte kan besegra en sådan varelse ensam anlitar Windwatcher erfarna krigare och schamaner för att samla ovanliga elementarkärnor och kalla fram besten. Genom att döda Cyclonian och ta dess elementarhjärta tämjer Bath'rah råa stormar till legendariska vapen som är berömda i hela Azeroth."}},faq={{q="Vem är Bath'rah the Windwatcher?",a="Bath'rah är en excentrisk djungeltrollschaman och vapensmed som lever i avskildhet bland ruinerna i Alterac Mountains nära Chillwind Point. Han hjälper erfarna äventyrare att kanalisera elementarkrafter till mäktiga vapen.",al={"bath'rahs identitet","vem är bath'rah","windwatchers historia"}},{q="Varför bor ett djungeltroll i Alterac?",a="Bath'rah lever som eremit nära Chillwind Point, där han studerar elementarkrafter och hjälper dugliga äventyrare att smida vapen. Det är inte fastslaget varför han lämnade sitt tidigare hemland.",al={"varför är bath'rah i alterac","troll i alterac mountains"}},{q="Vad är Cyclonian?",a="Cyclonian är en väldig, våldsam vindelementar som hemsöker ruinerna kring Bath'rahs fristad. Bath'rah behöver varelsens kärna för att smida vapen genomsyrade av elementarvind.",al={"vem är cyclonian","vad kallar bath'rah fram"}},{q="Varför söker krigare upp honom?",a="Krigare reser från världens alla hörn till Bath'rah eftersom han vet hur man smider de ikoniska Whirlwind-vapnen. När de besegrar Cyclonian under hans ledning får de vapen genomsyrade av tjutande vindar.",al={"bath'rahs krigaruppdrag","killen med whirlwind-yxan"}},{q="Hjälper Bath'rah bara Hordens medlemmar?",a="Bath'rah lever avskild från de stora fraktionskonflikterna som ensam eremit. Han fokuserar främst på elementarhantverk och hjälper dugliga krigare och schamaner som respekterar andarna och bidrar till hans arbete med elementen.",al={"är bath'rah fientlig","bath'rah och alliansen"}}},fx={["4f68ea16"]={q="Vad vill Bath'rah the Windwatcher?",a="Bath'rah söker en värdig mästare som kan möta och besegra Cyclonian, ett rasande elementväsen som håller till nära hans läger. Han åtrår varelsens hjärta och hoppas kunna tämja dess råa urkraft för att smida ett enastående vapen med enorm kraft.",al={"bath'rah vill","vad vill bathrah","bathrahs mål"}}},fp="24,300,19.475.0,19.409.1,32.221.0,40.185.0,18.178.0,29.192.0,45.218.0"}
P.entries["npc:bazil-thredd"] = {n="Bazil Thredd",s="Bazil Thredd är Edwin VanCleefs löjtnant och mest betrodda medhjälpare. Han har suttit fängslad i Stormwind Stockade sedan stenhuggarnas upplopp. Nu har fångarna gjort uppror, och Thredd leder de upproriska Defias-fångarna från det östra cellblocket.",h="Bazil Thredd är Edwin VanCleefs löjtnant och mest betrodda medhjälpare.",kw={"bazil thredd","defias","defias brotherhood","edwin vancleef","hamhock","maelik","stockade","stenhuggarna","stormwind stockade","thredd","warden thelwater"},ang={["faction:Alliance"]="Ett Defias-uppror alldeles under Stormwinds gator hotar huvudstaden direkt, och Warden Thelwater vill få ledaren undanröjd innan upproret sprider sig.",["race:Human"]="Thredd är en levande påminnelse om stenhuggarnas upplopp, som ställde Defias Brotherhood mot kungariket."},sec={{t="VanCleefs löjtnant",b="När adeln i Stormwind vägrade betala Stonemasons Guild för att återuppbygga staden avvisade Edwin VanCleef regeringens eftergifter och utlöste ett öppet uppror. Bazil Thredd stod vid VanCleefs sida som hans främste löjtnant och mest betrodda medhjälpare. Under de våldsamma sammandrabbningarna som följde tillfångatogs Thredd av stadsvakten. Medan VanCleef och de överlevande murarna flydde till Westfall för att bilda Defias Brotherhood kastades Thredd ner i Stormwind Stockades djup."},{t="Upproret i Stockade",b="I åratal förblev Thredd tyst och verkade bortglömd bakom järngaller. Isoleringen bröts av ett massivt fängelseupplopp som övermannade vakterna, öppnade cellerna och förvandlade Stockade till en beväpnad fästning alldeles under Mage Quarter. Thredd tog befälet över de fängslade Defias-banditerna, upprorsmakarna och deras allierade stråtrövare och upprättade sin ledningspost i den östra flygeln, bevakad av en ogre vid namn Hamhock. Warden Thelwater kräver Thredds huvud för att krossa upprorets ledning och återställa ordningen innan kaoset sprider sig ut på stadens gator."},{t="Den gåtfulle besökaren",b="Warden Thelwater trodde länge att Brotherhood hade övergett Thredd och låtit honom ruttna. Men några månader före upproret började en gåtfull man, som visade upp papper i namnet Maelik, besöka Thredd en eller två gånger i veckan. Trots Thelwaters misstankar visade sig besökarens handlingar vara helt äkta. Thelwater tvivlar på att mannen kommer tillbaka när Thredd är död, men beskrivningen är värd att föra vidare: den som har så goda papper har mäktiga kontakter, och besöken tyder på att krafter utanför fängelset hade nått Defias-löjtnanten inne i staden."}},faq={{q="Vem är Bazil Thredd?",a="Bazil Thredd var Edwin VanCleefs högra hand under stenhuggarnas uppror i Stormwind. Efter att ha tillfångatagits under upploppen fängslades han i Stockade, där han nu leder de myteriska fångarna.",al={"bazil thredds bakgrund","vem är thredd","stockades boss thredd"}},{q="Var hittar man Bazil Thredd?",a="Han finns djupt inne i Stormwind Stockade, fängelsekomplexet under Canal District nära Mage Quarter. Gå från korsningen i huvudkorridoren ner i det östra cellblocket och förbi ogren Hamhock. Thredd leder från mittcellen i den bortre salen.",al={"var finns bazil thredd","thredds plats","hitta bazil thredd"}},{q="Varför gör fångarna uppror i Stockade?",a="Fångarna har övermannat vakterna, öppnat cellerna och tagit över fängelsets korridorer. Bazil Thredd, den viktigaste Defias-fången i Stockade, har tagit befälet över de upproriska banditerna och straffångarna. Warden Thelwater kämpar för att hindra upproret från att sprida sig ut på Stormwinds gator.",al={"varför gör de uppror","orsaken till upploppet i stockade","varför gjorde fångarna uppror"}},{q="Varför vill Warden Thelwater se Thredd död?",a="Warden Thelwater tror att upproret inte kan slås ner så länge Thredd lever och leder det. Fängelsevakterna är övermannade och fångarna håller hela komplexet. Därför beordrar vaktchefen att Thredd ska avrättas för att slå sönder upprorets ledning.",al={"varför döda thredd","thelwaters belöning för thredd","varför vill de ha bazil thredds huvud"}},{q="Vem besökte Thredd före upploppet?",a="En tystlåten man som uppgav namnet Maelik besökte Thredd varje vecka under månaderna före upproret. Thelwater misstänkte honom, men besökaren hade giltiga handlingar. Det tyder starkt på att Defias-sympatisörer eller korrupta tjänstemän i Stormwind ordnade kontakten.",al={"thredds besökare","vem är maelik","den gåtfulle besökarens identitet"}},{q="Vilken roll hade Thredd i Stonemasons Guild?",a="Thredd var Edwin VanCleefs främste löjtnant under återuppbyggnaden av Stormwind och de efterföljande arbetskonflikterna. Han hjälpte till att organisera gillets motstånd när adelsrådet vägrade betala dem för arbetet.",al={"var thredd stenhuggare","thredd och stenhuggarna","stenhuggaren thredd"}}},fp="12,187,21.517.0,21.469.0,19.473.1,20.181.0,32.249.0,28.274.0,43.202.0,40.241.1,48.211.0"}
P.entries["npc:bazzalan"] = {n="Bazzalan",s="Bazzalan leder kulten Searing Blade från lavagrottorna under Orgrimmar. Tillsammans med Jergosh the Invoker styr han dess verksamhet i Ragefire Chasm.",h="Bazzalan leder kulten Searing Blade från lavagrottorna under Orgrimmar.",kw={"bazzalan","kultist","jergosh","orgrimmar","ragefire chasm","rfc","satyr","searing blade"},ang={["class:Rogue"]="Bazzalan använder smygande, våldsamma hugg och giftiga klingor, vilket gör honom särskilt intressant för skurkar.",["faction:Horde"]="Bazzalan och hans kult utgör en fara under Thralls fäste, och Horden vill få dem undanröjda.",["race:Orc"]="Orcherna kämpade hårt för att undkomma demonisk manipulation. Att en satyr leder kultister i deras egna grundvalar är en skymf mot dem."},sec={{t="En orm under staden",b="Under Orgrimmar har Bazzalan anslutit sig till kulten Searing Blade i Ragefire Chasm. Medan Thrall arbetar för att grunda orchernas nya hem i Durotar leder satyren och skurken kultens styrkor ute på fältet från slingrande lavagrottor. Han är snabb och dödlig med sina dubbla klingor."},{t="Kultens ledarskap och svek",b="Från en vulkanisk avsats ovanför den centrala kammaren håller Bazzalan uppsikt över kultens vakter. Jergosh the Invoker utför demoniska ritualer nedanför. Liksom alla satyrer är Bazzalans yttersta lojalitet hos demoniska herrar. Han använder gift, snabba angrepp och smygande mot Hordens spejare som vågar sig nära kultens uppmarschområde."}},faq={{q="Vem är Bazzalan?",a="Bazzalan är en satyr och skurk som delar ledarskapet för kulten Searing Blade i Ragefire Chasm under Orgrimmar.",al={"bazzalans bakgrund","vem är bazzalan","satyrboss rfc"}},{q="Var hittar man Bazzalan i Ragefire Chasm?",a="Bazzalan håller sig dold på de övre avsatserna i Ragefire Chasm, ovanför Jergosh the Invoker. Mörka ramper uthuggna i grottväggarna leder upp till honom.",al={"bazzalans plats","var finns bazzalan","hitta bazzalan"}},{q="Vad gör en satyr under Orgrimmar?",a="Bazzalan arbetar med Searing Blade, en demonisk kult som försöker underminera Horden inifrån. Satyrer är bundna till demoniska makter och tjänar ofta som anstiftare och lönnmördare åt skuggornas råd.",al={"varför finns det en satyr i orgrimmar","varför är bazzalan i rfc"}},{q="Vilka förmågor använder Bazzalan i strid?",a="Bazzalan anfaller snabbt med närstridsvapen och använder Sinister Strike. Ibland drabbar han sina motståndare med ett milt försvagande gift.",al={"bazzalans förmågor","bazzalans attacker","hur slåss bazzalan"}},{q="Vilken relation har han till Jergosh the Invoker?",a="Bazzalan och Jergosh delar ledarskapet för Searing Blade i Ragefire Chasm. Jergosh sköter åkallanden och frammanar mörka krafter, medan Bazzalan leder kultens strids- och smygverksamhet.",al={"jergosh och bazzalan","är bazzalan släkt med jergosh"}},{q="Varför vill Horden att Bazzalan ska dö?",a="Bazzalans närvaro djupt under huvudstaden utgör ett direkt demoniskt hot. Hordens ledare skickar äventyrare in i Ragefire Chasm för att röja honom ur vägen innan Searing Blades planer hotar staden.",al={"bazzalans belöning","slå tillbaka invasionen bazzalan"}}},fx={["9fcb4f3a"]={q="På vems sida står Bazzalan?",a="Bazzalan tjänar de demoniska herrarna bakom Shadow Council. Tillsammans med Jergosh the Invoker leder han Searing Blade-kultisterna som håller till under Orgrimmar och arbetar i hemlighet mot Horden och stadens säkerhet.",al={"vem tjänar bazzalan","bazzalans fraktion","bazzalans lojalitet"}}},fp="8,151,26.264.0,26.319.0,16.114.0,46.133.0,40.198.0,43.134.0,48.197.0,38.192.0"}
P.entries["npc:beldin-steelgrill"] = {n="Beldin Steelgrill",s="Beldin Steelgrill är en välkänd dvärgisk ingenjör och mästertekniker som driver Steelgrill's Depot i Dun Morogh. Han anses allmänt vara en av de främsta mekanikerna för belägringsmaskiner i Khaz Modan och ansvarar för underhållet av Ironforges militärs tunga pansar och bandgående krigsmaskiner. För att hålla de väldiga konstruktionerna igång krävs en aldrig sinande tillgång på specialverktyg av hög kvalitet.",h="Beldin Steelgrill är en välkänd dvärgisk ingenjör och mästertekniker som driver Steelgrill's Depot i Dun...",kw={"beldin steelgrill","dun morogh","ironforge","kharanos","mekaniker","belägringsmaskin","ångstridsvagn","steelgrill"},ang={["profession:Engineering"]="För ingenjörer är Beldin en symbol för dvärgarnas främsta fordonsteknik och ger en plats på första parkett till Alliansens mäktigaste mekaniserade krigsmaskiner.",["race:Dwarf"]="Beldins gård visar Ironforges industriella styrka och bevisar att dvärgarnas hantverk sträcker sig långt bortom handhållna hammare och yxor, ända till förödande belägringsartilleri."},sec={{t="Mästare på bandbestar",b="Steelgrill's Depot ligger en bit längs vägen från Kharanos och fungerar som den främsta testplatsen och servicestationen för dvärgiska ångstridsvagnar och belägringsmaskiner. Beldin Steelgrill är dess chefstekniker och är vida berömd för sin enastående expertis i att reparera och trimma bepansrade krigsvagnar. Att tämja tung metall och mullrande ångpannor är ett obarmhärtigt arbete, och Beldin förbrukar verktyg i rask takt. Hans ständiga behov av tunga skiftnycklar, avbitare och precisionsinstrument pressar ofta de lokala järnarbetarna till det yttersta för att hålla hans arbetsbänk försedd."}},faq={{q="Vem är Beldin Steelgrill?",a="Beldin Steelgrill är en mästermekaniker bland dvärgarna och ägare till Steelgrill's Depot i Dun Morogh. I hela Khaz Modan är han känd som den främste teknikern för dvärgiska belägringsmaskiner och krigsvagnar.",al={"beldin steelgrill","vem är beldin","stridsvagnsmekaniker dun morogh"}},{q="Vad händer på Steelgrill's Depot?",a="Depån ligger strax nordost om Kharanos och fungerar som en livlig underhålls- och testplats för Alliansens ångstridsvagnar och tunga mekaniska utrustning.",al={"steelgrills depå","vad är steelgrill depot","depåns syfte"}},{q="Varför förbrukar Beldin så många verktyg?",a="Underhåll av tunga pansarplåtar, komplicerade kugghjul och ångpannor med högt tryck kräver hårt arbete och specialutrustning. Beldin arbetar så hårdhänt att verktygen slits ut i häpnadsväckande takt, och han lägger därför krävande beställningar hos smeder i närheten.",al={"varför behöver han verktyg","steelgrills verktyg","verktyg åt steelgrill"}}},fx={c08b01c8={q="På vems sida står Beldin Steelgrill?",a="Beldin är lojal mot Bronzebeard-klanen i Ironforge och står stadigt på Alliansens sida. Han håller till en kort bit från Kharanos och ser till att den dvärgiska militären och de lokala försvarsstyrkorna har tung mekaniserad rustning och belägringsmaskiner.",al={"beldin steelgrills fraktion","vem tjänar beldin","är beldin steelgrill med i alliansen"}},["940fd3ae"]={q="Varför är Beldin Steelgrill berömd?",a="Beldin är känd i hela Dun Morogh som den främste experten på belägringsmaskiner. Hans kunnande om krigsmaskiner och tung mekanik har gett honom ett oöverträffat rykte bland dvärgiska ingenjörer, men också gjort honom ökänd för sina höga krav på de lokala verktygsmakarna.",al={"beldin steelgrills rykte","varför är beldin känd","främsta experten på belägringsmaskiner"}}},fp="17,234,27.289.0,25.181.0,35.138.0,41.172.0"}
P.entries["npc:bethor-iceshard"] = {n="Bethor Iceshard",s="Bethor Iceshard är en mäktig magiker bland de Fördömda och har sin bas i Magic Quarter i Undercity. Han vakar över de arkanistiska och skuggmagiska utövarna i Temple of the Damned och har betydande makt i Sylvanas rike. Bakom hans kyliga sätt döljer sig ett förflutet sammanflätat med gamla vänner som skiljdes åt av Scourge.",h="Bethor Iceshard är en mäktig magiker bland de Fördömda och har sin bas i Magic Quarter i Undercity.",kw={"bethor iceshard","de fördömda","gunther arcanus","magic quarter","den förlorade lichmästaren","temple of the damned","thule ravenclaw","undercity"},ang={["class:Mage"]="För magiker bland de Fördömda står Bethor för uthållighetens höjdpunkt och visar att arkana konster kan frodas även i odödlighetens kalla grepp.",["faction:Horde"]="Bethor samordnar viktiga offensiva magi- och antinekromantiska operationer som skyddar Hordens fäste i Lordaeron.",["race:Undead"]="Bethors personliga tragedi speglar många av de Fördömdas: Scourge slet dem från älskade vänner och hem, och nu möter de forna allierade som bittra fiender."},sec={{t="Härskare över Magic Quarter",b="Bethor Iceshard står i Temple of the Damned och övervakar utövarna av arkana konster och skuggmagi i Undercity. Han är respekterad och fruktad för sitt intellekt och sin iskalla beslutsamhet, och hans politiska och magiska inflytande räcker för att ge direkta order till provinsiella magistrater i hela Lordaeron. Han skickar ut agenter bland de Fördömda för att säkra värdefulla magiska skrifter, undersöka arkanistiska avvikelser och krossa rivaliserande makter som hotar Undercitys herravälde."},{t="Gamla vänner och bittra återseenden",b="Bethor har inte glömt sina tidigare följeslagare. Han spårar mäktiga odöda magiker genom Tirisfal och Silverpine och skickar ut agenter för att ta reda på om avfälliga magiker tjänar Lich King eller kan vinnas över till de Fördömdas sak. När Bethor upptäcker att Gunther Arcanus väcker de döda vid Brightwater Lake arbetar han tålmodigt för att föra sin gamle vän in i Lady Sylvanas skara. Thule Ravenclaw, vars frivilliga förräderi ödelade deras forna brödraskap, får däremot ingen nåd."},{t="Lärlingsband",b="Innan det tredje kriget ödelade Lordaeron var Bethor en dödlig lärling som studerade magi tillsammans med sina två nära vänner, Gunther Arcanus och Thule Ravenclaw. Som ett tecken på deras vänskap flätade de tre eleverna samman sina övningsstavar. Scourge krossade deras band fullständigt. När död och mörk magi svepte över kungariket överlämnade Thule Ravenclaw sin själ till Lich King av egen vilja, Gunther dog och återuppstod på en avskild ö i Brightwater Lake, och Bethor dukade under men lyckades senare bryta sig fri som en av de Fördömda."}},faq={{q="Vem är Bethor Iceshard?",a="Bethor Iceshard är en högt uppsatt magiker bland de Fördömda som styr över Temple of the Damned i Undercitys Magic Quarter. Han samordnar magisk forskning, underrättelsearbete om avfällingar och hemliga arkanistiska operationer åt Dark Lady.",al={"bethor iceshard","vem är bethor","bethors historia"}},{q="Var hittar man Bethor Iceshard?",a="Bethor bor i Temple of the Damned, den centrala byggnaden i Undercitys Magic Quarter.",al={"var finns bethor","bethors plats","hitta bethor iceshard"}},{q="Vad har Bethor Iceshard för historia med Gunther Arcanus?",a="Bethor och Gunther var nära vänner när de var magilärlingar i Lordaeron. Efter att ha dött under Scourges invasion lyckades båda till slut bryta sig fria från Lich Kings kontroll, och Bethor organiserade Gunthers värvning till de Fördömda.",al={"gunther och bethor","gunther arcanus vänskap","hur känner bethor gunther"}},{q="Vem var Thule Ravenclaw för Bethor?",a="Thule Ravenclaw var den tredje medlemmen i Bethors och Gunthers lärlingskrets. Till skillnad från de andra två svor Thule frivilligt sin själ till Lich King under Scourges invasion och blev en hatad nekromantiker på Fenris Isle.",al={"thule ravenclaws koppling","thule och bethor","bethor ravenclaw"}},{q="Vad är historien bakom Bethors stav?",a="När de var unga flätade Bethor, Gunther och Thule samman sina övningsstavar som en symbol för deras eviga vänskap. Den flätade minnessaken knyter fortfarande de tre splittrade magikerna till deras dödliga förflutna och väcker sorg.",al={"woven wand","stav till bethor","bethors lärlingsstav"}},{q="Vilken roll har Bethor i de Fördömdas samhälle?",a="Bethor är en av Undercitys främsta auktoriteter inom arkana konster. Han vägleder nyuppståndna magiker och häxmästare, leder den militära underrättelseverksamheten om avfälliga nekromantiker och har makt över regionala civila ämbetsmän bland de Fördömda, som Magistrate Sevren.",al={"bethors roll","vad gör bethor","bethors makt"}}},fx={["31504eb7"]={q="På vems sida står Bethor Iceshard?",a="Bethor är helt hängiven Lady Sylvanas Windrunner och de Förfallna. Från sitt heliga rum i Undercitys Magic Quarter har han stor makt inom de Förfallnas hierarki. Han leder arkana utövare och samlar resurser mot Scourge och andra hot mot sitt folk.",al={"bethor iceshards fraktion","bethor iceshards lojalitet","vem tjänar bethor"}},["14082dd0"]={q="Vad vill Bethor Iceshard?",a="Bethor vill stärka de Förfallnas arkana krafter och skydda deras unga kungadöme. Han försöker värva begåvade utövare som sin tidigare vän Gunther Arcanus till de Förfallnas sak, samtidigt som han skoningslöst bekämpar Scourge och håller förrädare som Thule Ravenclaw ansvariga för att ha sålt sina själar till Lich King.",al={"bethor iceshards mål","vad vill bethor","bethor iceshards motiv"}},["50a70545"]={q="Varför är Bethor Iceshard i Undercity?",a="Bethor styr över Temple of the Damned i Undercitys Magic Quarter och leder de Förfallnas magiker och häxmästare. Han stannar här för att sköta arkana angelägenheter, vägleda lovande magiker och samordna strategiska insatser i hela Lordaeron från huvudstadens hjärta.",al={"varför är bethor i undercity","bethor iceshards plats i berättelsen","varför är bethor här"}}},fp="15,179,27.409.0,36.460.1,23.486.1,23.232.0,35.90.0,46.235.1,34.226.1,39.228.0,47.240.0"}
P.entries["npc:billy-maclure"] = {n="Billy Maclure",s="På The Maclure Vineyards skapar Billy Maclures spratt problem mellan två grannjordbruk. Den unge människopojken smiter från sysslorna och eldar på fejden mellan sin familj och Stonefields, men färska bakverk kan få honom att samarbeta.",h="På The Maclure Vineyards skapar Billy Maclures spratt problem mellan två grannjordbruk.",kw={"bernice stonefield","billy maclure","fargodeep mine","goldtooth","borttappat halsband","the maclure vineyards","pork belly pie","stonefield"},ang={["faction:Alliance"]="Som äventyrare i Alliansen, nyanländ från Northshire, får du genom att hjälpa till med Billys spratt möta farorna i Fargodeep Mine.",["profession:Cooking"]="Som kock kan du se hur Auntie Bernices Pork Belly Pie hjälper till att lösa lokala tvister och locka fram bekännelser från fåordiga bondpojkar.",["race:Human"]="Som människa visar Billys bekymmer de vardagliga grälen på landsbygden i Elwynn. Fejder mellan gårdar och barndomens hyss fortsätter mitt i Stormwinds politiska oro."},sec={{t="En pojke på vingårdarna",b="Billy Maclure tillbringar dagarna utanför ladan på The Maclure Vineyards, nära bonden Gerard Tiller. Han växer upp bland vinrankorna i södra Elwynn Forest och smiter ofta från sysslorna för att ströva omkring på ängarna. Maclures och Stonefields har länge varit fientligt inställda till varandra. Billy ser deras fejd som en chans till spratt och småstölder."},{t="Det stulna halsbandet",b="Billy Maclure stal Auntie Bernice Stonefields värdefulla arvegodshalsband. När han sprang nära Fargodeep Mine tappade han det. Goldtooth, en enorm och våldsam kobold, snappade åt sig halsbandet och försvann in i gruvans gångar. Billy är rädd för kobolderna och de närboende äldstes vrede, så han tvekar att erkänna. Auntie Bernices varma Pork Belly Pie kan locka fram sanningen ur honom."}},faq={{q="Vem är Billy Maclure?",a="Billy Maclure är en ung människopojke på The Maclure Vineyards i Elwynn Forest. Han smiter från arbetet på gården, hittar på spratt och retar upp grannarna Stonefields.",al={"vem är billy","billy maclures historia","maclure-pojke"}},{q="Var hittar man Billy Maclure?",a="Billy väntar utanför huvudladan på The Maclure Vineyards, i södra Elwynn Forest öster om The Stonefield Farm.",al={"billy maclures plats","var är billy","hitta billy maclure"}},{q="Vad gjorde Billy mot Auntie Bernice?",a="Billy stal Auntie Bernice Stonefields arvegodshalsband under fejden mellan deras familjer.",al={"bernice halsband","vad stal billy","stulet halsband elwynn"}},{q="Vad hände med halsbandet som Billy stal?",a="Billy tappade halsbandet nära Fargodeep Mine. Goldtooth plockade upp det och bar in det i gruvan.",al={"var är halsbandet","borttappat halsband elwynn","vem har bernices halsband"}},{q="Hur får du Billy att erkänna vad som hände med halsbandet?",a="Ge Billy en nybakad Pork Belly Pie från Auntie Bernice. Hans aptit kan locka honom att erkänna.",al={"paj till billy","hur mutar man billy","muta billy maclure"}},{q="Vem är Goldtooth?",a="Goldtooth är en ovanligt stor och våldsam koboldledare i Fargodeep Mine. Han tog Auntie Bernices halsband nära gruvans ingång och förvarar det i gångarna.",al={"vem är goldtooth","goldtooths historia","fargodeep-kobold"}}},fx={["324ac528"]={q="På vems sida står Billy Maclure?",a="Billy är en lojal medlem av familjen Maclure i Elwynn Forest och står fast vid kungariket Stormwind och Alliansen. Hans familj ligger i bitter och långvarig fejd med grannarna Stonefield, men Billy är fortfarande bara en ung pojke som hamnar mellan familjens agg och sin egen aptit.",al={"billy maclures fraktion","vilken sida står billy på","vem stödjer billy"}},c9c2f9db={q="Vad vill Billy Maclure?",a="Billy vill helst hålla sig borta från trubbel och få äta sig mätt. Framför allt längtar han efter tant Bernice Stonefields berömda fläskpajer, trots den häftiga rivaliteten mellan deras familjer. Han kan till och med tänka sig att erkänna sina busstreck om någon kommer med en nybakad, smakrik paj.",al={"vad vill billy","vad längtar billy maclure efter","billy maclures favoritmat"}},f69aaa51={q="Varför är Billy Maclure här?",a="Billy bor på Maclure Vineyards, familjens hem och levebröd i Elwynn Forest. Han tillbringar dagarna med att hänga utanför ladan nära Gerard Tiller, uträtta ärenden och leka i trakten när han inte smyger över mot grannarnas gård, Stonefield Farm.",al={"varför är billy maclure här","varför är billy på maclure vineyards","vad gör billy här"}},["275e906f"]={q="Vilka band har Billy Maclure?",a="Billy tillhör familjen Maclure, som driver jordbruk, och bor på vingården tillsammans med släktingar och arbetare som Gerard Tiller. Hans busstreck har också knutit honom nära den rivaliserande familjen Stonefield, särskilt tant Bernice Stonefield, vars värdefulla halsband han stal och vars bakverk han älskar i hemlighet.",al={"billy maclures familj","vem är billy maclure släkt med","billy maclures kontakter"}}},fp="13,221,22.344.0,19.383.1,21.152.0,33.106.0,36.97.0,42.97.1,62.101.1,17.166.1"}
P.entries["npc:bingles-blastenheimer"] = {n="Bingles Blastenheimer",s="Bingles Blastenheimer är en excentrisk gnomisk flygare som blivit strandsatt vid Loch Modans sydöstra strand, vid The Loch. Efter att ha kraschlandat med sin experimentella flygfarkost är han omgiven av lokala troggar och bestar och gör allt för att rädda sina dyrbara verktyg och delar.",h="Bingles Blastenheimer är en excentrisk gnomisk flygare som blivit strandsatt vid Loch Modans sydöstra strand...",kw={"bingles","blastenheimer","gnom","gyrokopter","loch modan","pilot"},ang={["profession:Engineering"]="Alla uppfinnare känner igen bedrövelsen i att förlora oersättliga specialnycklar och manicker till tjuvaktiga troggar efter att en ambitiös flygtur gått snett.",["race:Gnome"]="Bingles står för den typiska gnomiska drivkraften att utveckla flygtekniken, där mekaniska fel och explosioner helt enkelt ses som små motgångar på vägen mot framsteg."},sec={{t="En hård landning",b="Liksom många ambitiösa gnomiska ingenjörer gav sig Bingles Blastenheimer upp i luften med en specialbyggd flygfarkost, bara för att upptäcka att det är mycket svårare att komma ner säkert än att lyfta. När hans gyrokopter fick fel och kraschade vid The Lochs sydöstra strand överlevde Bingles oskadd, men farkosten slogs sönder i spridda delar. Han är strandsatt långt från Ironforge och håller sig nära vraket, på sin vakt mot hungriga krokolisker och fientliga troggar. Han ber förbipasserande resenärer att återfinna verktygen och sprängämnena Blastencapper som troggar från en närliggande ö stal från honom."}},faq={{q="Vem är Bingles Blastenheimer?",a="Bingles Blastenheimer är en gnomisk pilot och uppfinnare som råkade ut för en katastrofal krasch med sin flygfarkost på Loch Modans sydöstra strand vid The Loch.",al={"vem är bingles","bingles blastenheimer bakgrund","vem är gnomen vid sjön"}},{q="Vad hände med hans flygfarkost?",a="Bingles kraschade med sin gyrokopter i The Loch. Troggar från en närliggande ö gick sedan till angrepp och stal hans verktyg och hans särskilda sprängämnen Blastencapper.",al={"varför kraschade bingles","bingles gyrokopter","vad hände med bingles flygplan"}},{q="Varför har Bingles inte återvänt till staden?",a="Bingles är strandsatt utan sin gyrokopter, och troggar från en närliggande ö har stulit hans verktyg och sprängämnena Blastencapper. Han vill ha tillbaka dem för kampen om att återta Gnomeregan och väntar vid vraket på att någon ska återfinna dem.",al={"varför är bingles strandsatt","varför stanna vid sjön"}},{q="Vart tar Bingles vägen när hans farkost är lagad?",a="I den här eran stannar Bingles vid kraschplatsen på The Lochs sydöstra strand och väntar på att äventyrare ska återfinna hans försvunna förnödenheter.",al={"vart tar bingles vägen","bingles tillhåll"}}},fx={["1e141199"]={q="På vems sida står Bingles Blastenheimer?",a="Bingles är en lojal gnom som står fast vid Gnomeregan och Alliansen. Han förlitar sig på vänligt sinnade alliansresenärer för att få tillbaka sin förlorade utrustning och överleva i Loch Modans vildmark.",al={"bingles blastenheimers fraktion","är bingles med i alliansen","vem arbetar bingles för"}},["89c66e03"]={q="Varför är Bingles Blastenheimer här?",a="Bingles flög över Loch Modan i sin älskade gyroplan när katastrofen slog till. Flygmaskinen störtade vid sjöns strand och lämnade honom strandsatt och ensam bland de farliga bestarna och fientliga troggarna i vildmarken.",al={"varför är bingles i loch modan","hur hamnade bingles här","bingles blastenheimers krasch"}}},fp="21,191,15.438.0,29.134.0,36.136.0,36.233.0,51.124.1"}
P.entries["npc:bink"] = {n="Bink",s="Bink är en magetränare av gnomernas folk som bor i Hall of Mysteries i Ironforges Mystic Ward. Kvicktänkt och entusiastisk vägleder hon blivande magiker genom den arkaniska konstens alla finesser och förmedlar kontakter med framstående trollkarlar i Alliansen.",h="Bink är en magetränare av gnomernas folk som bor i Hall of Mysteries i Ironforges Mystic Ward.",kw={"andromath","bink","gnom","hall of mysteries","ironforge","magetränare","mystic ward","tabetha"},ang={["class:Mage"]="För magiker i Alliansen som besöker eller bor i Ironforge är Bink en viktig tränare och uppdragskontakt. Hon skickar elever till mäktiga mentorer runtom i Azeroth för att studera.",["race:Gnome"]="Bink står för den fortsatta jakten på arkanisk mästerlighet bland de landsförvisade gnomer som söker skydd i sina dvärgallierades stora salar."},sec={{t="En fyrbåk i Hall of Mysteries",b="I Ironforges Mystic Ward står Bink bland de samlade lärda, prästerna och arkanisterna i Hall of Mysteries. Liksom många av de gnomer som drevs bort från Gnomeregan har hon anpassat sig till livet i dvärgarnas bergfäste. Där delar hon med sig av sitt skarpa intellekt och sin kunskap om arkanisk konst till dem som lär sig magikerns väg. Hon har goda kontakter med trollkarlar i Eastern Kingdoms och Kalimdor och hänvisar ofta lovande lärlingar till framstående mentorer som High Sorcerer Andromath i Stormwind eller Tabetha i Dustwallow Marsh."}},faq={{q="Vem är Bink?",a="Bink är en gnomisk magetränare i Alliansen, stationerad i Hall of Mysteries i Ironforges Mystic Ward. Hon lär ut arkanisk magi och är mentor och kontakt för magiker under utbildning.",al={"binks bakgrund","vem är bink","bink ironforge"}},{q="Var hittar jag Bink?",a="Du hittar henne i Hall of Mysteries, som ligger i den västra flygeln av Ironforges Mystic Ward.",al={"binks plats","var finns bink","hitta bink"}},{q="Vilka uppdrag berör Bink?",a="Magiker under utbildning hänvisas till henne genom uppdrag som Speak with Bink. Sedan visar hon magiker vägen till vidare studier och skickar dem till auktoriteter som High Sorcerer Andromath i Stormwinds Wizard's Sanctum eller eremitmagikern Tabetha i Dustwallow Marsh.",al={"binks uppdrag","uppdraget speak with bink"}},{q="Vad säger Bink till dem som inte är magiker?",a="Om någon som inte utövar arkanisk magi kommer fram till henne ger hon glatt ett praktiskt råd: ”Bli vän med en magiker! Vi har ett och annat trick i rockärmen, minsann...”",al={"binks rykten","binks dialog"}}},fx={cf09b30e={q="På vems sida står Bink?",a="Bink står stadigt på Alliansens sida och stödjer Gnomeregan Exiles, som har funnit skydd i Ironforge. Från Hall of Mysteries arbetar hon tillsammans med andra lärda och trollkarlar. Hon använder sina magiska förmågor för att hjälpa sina allierade och undervisa lovande nya magiker som strider under Alliansens fana.",al={"binks fraktion","vem tjänar bink","bink, alliansen eller horden"}},d0de8b26={q="Varför är Bink i Hall of Mysteries?",a="Bink bor i Ironforges Hall of Mysteries och arbetar som magitränare för gnomer. Efter Gnomeregans fall fann de fördrivna gnomerna en fristad hos Bronzebeard-dvärgarna. Bink använder sina arkaniska kunskaper för att träna blivande magiker och skicka ut elever på uppdrag som är viktiga för den arkana gemenskapen.",al={"varför är bink här","vad gör bink i ironforge","varför är bink i ironforge"}}},fp="4,152,33.505.0,12.130.0,22.91.0,25.210.0,32.126.0"}
P.entries["npc:bishop-delavey"] = {n="Bishop DeLavey",s="I Stormwind Keep lyssnar Bishop DeLavey till hovets lågmälda bekymmer. Han företräder Church of the Holy Light i Petitioner's Chamber, där tro och stat möts.",h="I Stormwind Keep lyssnar Bishop DeLavey till hovets lågmälda bekymmer.",kw={"bishop delavey","delavey","elling trias","det heliga ljuset","jorgen","försvunnen diplomat","petitioner's chamber","stormwind keep"},ang={["class:Priest"]="Som präst visar DeLavey hur djupt Church of the Holy Light är involverad i Stormwinds politik, där tro möter statskonst och hemliga affärer.",["faction:Alliance"]="Som medlem av Alliansen kan du se hur DeLaveys diskreta utredning skyddar den bräckliga freden mellan Stormwind och Lady Jaina Proudmoores utpost Theramore."},sec={{t="En biskop vid hovet",b="Bishop DeLavey ger råd åt Stormwinds hov från borgen. Medan Archbishop Benedictus sköter Cathedral of Light bor DeLavey bland adeln och petitionärerna. Han ger hovet andlig vägledning samtidigt som han navigerar rikets politik. Hans plats där gör att han får höra viskade rykten och känsliga klagomål innan de når Highlord Bolvar Fordragon eller den unge kungen Anduin."},{t="En känslig utredning",b="En försvunnen diplomat har dragit in Bishop DeLavey i en hemlig utredning. Diplomaten skickades för att träffa Lady Jaina Proudmoore i Theramore men kom aldrig fram. För att förhindra panik håller hovet försvinnandet hemligt. DeLavey misstänker Defias Brotherhood och går utanför de vanliga vaktkanalerna. Han använder privata kontakter och diskreta äventyrare, däribland fiskaren Jorgen, för att nå dolda uppgiftslämnare som Elling Trias."}},faq={{q="Var hittar man Bishop DeLavey?",a="Bishop DeLavey finns i Petitioner's Chamber inne i Stormwind Keep, strax intill huvudingången där undersåtar samlas för att vädja till det kungliga hovet.",al={"delaveys plats","var finns bishop delavey","delavey i borgen"}},{q="Vilken roll har han i Stormwind Keep?",a="Bishop DeLavey företräder Church of the Holy Light vid Stormwinds kungliga hov. Han sköter kyrkans angelägenheter, ger adeln råd och tar i tysthet itu med känsliga frågor för rikets räkning.",al={"delaveys arbete","vem är bishop delavey","vad gör delavey"}},{q="Varför utreder han den försvunna diplomaten?",a="Diplomaten försvann på väg till ett möte med Lady Jaina Proudmoore i Theramore. Bishop DeLavey misstänker inblandning från Defias och utreder saken genom betrodda kanaler för att hindra krisen från att oroa allmänheten.",al={"delavey försvunnen diplomat","varför bryr sig delavey om diplomaten"}},{q="Hur har DeLavey kontakt med Elling Trias?",a="Bishop DeLavey skickar meddelanden via mellanhänder, däribland fiskaren Jorgen, till Elling Trias, en ostmästare som i hemlighet samlar underrättelser åt SI:7.",al={"delavey och trias","delaveys si:7-kontakt"}}},fx={["9f3cf19d"]={q="Vem är Bishop DeLavey?",a="Bishop DeLavey är en äldre mänsklig präst i Church of the Holy Light och är stationerad i Stormwind Keep. Som kyrkans officiella sändebud vid det kungliga hovet sköter han kyrkliga och administrativa ärenden bland adeln och regentskapet.",al={"vem är delavey","bishop delaveys identitet","vem är bishop delavey"}},["8f5e30a8"]={q="På vems sida står Bishop DeLavey?",a="DeLavey är helt lojal mot Church of the Holy Light och Stormwinds stora allians. Han arbetar direkt för rikets bästa och försöker skydda kronan och diskret reda ut hot mot kungariket innan panik sprider sig på gatorna.",al={"delaveys fraktion","är bishop delavey med i alliansen","vem tjänar bishop delavey"}},["663bbb38"]={q="Vad vill Bishop DeLavey?",a="DeLavey vill ta reda på sanningen bakom försvinnandet av en viktig diplomat från Stormwind som skickats till Theramore. Eftersom nyheten om försvinnandet kan destabilisera hovet vill han utreda saken diskret genom pålitliga mellanhänder och underrättelser via bakkanaler.",al={"vad försöker delavey göra","bishop delaveys mål","vad vill delavey"}},["44aea1e7"]={q="Varför är Bishop DeLavey i Stormwind Keep?",a="DeLavey bor i Petitioner's Chamber och företräder Church of the Holy Light inför Highlord Bolvar Fordragon och det kungliga hovet. Därifrån ger han kronan råd i kyrkliga frågor och håller sig nära kungarikets politiska intriger.",al={"varför är delavey i fästningen","varför är bishop delavey här","delavey petitioner's chamber"}}},fp="14,183,17.380.0,18.424.1,34.156.0,35.187.0,45.212.0,41.174.1"}
P.entries["npc:blanchy"] = {n="Blanchy",s="Gamla Blanchy är det lojala och hårt arbetande stoet som tillhör Theodore och Verna Furlbrow. Just nu vilar hon bredvid deras vagn nära The Jansen Stead i Westfall. Hon är känd för sitt milda temperament och sin goda aptit, och förblir en stadig följeslagare till sina ägare mitt i oron som gripit landsbygden.",h="Gamla Blanchy är det lojala och hårt arbetande stoet som tillhör Theodore och Verna Furlbrow.",kw={"blanchy","furlbrow","the jansen stead","havre","gamla blanchy","verna furlbrow","westfall"},ang={["faction:Alliance"]="För alliansresenärer som färdas söderut från Elwynn Forest till Westfall är hjälpen med att mata gamla Blanchy ofta en av de första stillsamma välgärningar de gör för de kämpande lokala flyktingarna."},sec={{t="En trogen gårdshäst",b="Långt innan Blanchy drog Furlbrows vagn genom Westfalls damm arbetade hon på deras gård i Stormwinds kornbod, där hon blev känd som ett ovanligt ljuvligt och väluppfostrat sto. År av hårt arbete har slitit ner henne till ”gamla Blanchy”, och den mödosamma flykten från oroliga gårdar har gjort henne utmattad. Trots att hon tydligt är trött har hon fortfarande god aptit, och resande som kommer med näringsrika nävar havre från fälten runt omkring får Blanchys egen älskade filt och foderpåse av Verna."}},faq={{q="Vem äger Blanchy?",a="Blanchy tillhör Theodore och Verna Furlbrow, gårdsägare som färdas genom Westfall. Hon är deras trogna draghäst och älskade familjekamrat.",al={"blanchys ägare","vem tillhör blanchy","furlbrows häst"}},{q="Var kommer Blanchy ursprungligen ifrån?",a="Det finns inga uppgifter om var Blanchy föddes. Så vitt någon i Westfall vet har hon länge varit Furlbrows häst och arbetat på deras gård tills familjen tvingades ge sig ut på vägarna.",al={"blanchys ursprung","var kommer blanchy ifrån","unga blanchy"}},{q="Varför behöver Verna Furlbrow havre till Blanchy?",a="År av arbete och den långa färden längs Westfalls farliga vägar har gjort gamla Blanchy helt utmattad. Verna ber äventyrare på genomresa att leta reda på återstående säckar med havre från närliggande gårdar för att återställa den trogna hästens krafter.",al={"blanchy havre","varför mata blanchy","furlbrows trötta häst"}},{q="Var hittar man Blanchy?",a="Gamla Blanchy står bunden bredvid Furlbrows vagn längs huvudvägen nära The Jansen Stead i norra Westfall.",al={"blanchys plats","var finns gamla blanchy","blanchy karta"}}},fp="7,303,19.579.0,17.160.0,39.178.0,46.237.0,27.116.0"}
P.entries["npc:blind-hunter"] = {n="Blind Hunter",s="Blind Hunter är en svårfunnen albino-fladdermus som håller till djupt inne i Razorfen Kraul. Till skillnad från de vanliga fladdermössen som häckar nära grottmynningarna strövar denna sällsynta varelse omkring i quilboarernas utpost, där solen aldrig når in.",h="Blind Hunter är en svårfunnen albino-fladdermus som håller till djupt inne i Razorfen Kraul.",kw={"albino-fladdermus","blind hunter","kraulfladdermus","kraulbest","sällsynt fladdermus","razorfen kraul"},ang={["class:Hunter"]="För bestmästare som färdas genom The Barrens är Blind Hunter ett eftertraktat byte, antingen som ett sällsynt albinodjur att tämja eller som källa till välgjorda underjordiska bågar."},sec={{t="Djupen i Kraul",b="Razorfen Kraul genomkorsas av vindlande törnsnår och mörka underjordiska grottor. Vanliga fladdermöss i Kraul håller till närmare ytan, där ett svagt ljus sipprar in från omvärlden. Blind Hunter har däremot anpassat sig helt till de mest avlägsna och mörka skrymslena i snåret. Dess bleka albinopäls och mjölkiga blick är troligen resultatet av generationer helt avskilda från naturligt solljus."},{t="Ett sällsynt byte",b="Som namnet antyder tror forskare och spejare att varelsen har förlorat det mesta eller hela sin vanliga syn. I stället förlitar den sig på skarp hörsel och ekolokalisering för att spåra byten i dunklet. Den visar sig sällan och jagar bara då och då genom det täta snåret. Därför är ett möte med detta spökdjur en sällsynt upplevelse för grottutforskare."}},faq={{q="Vad är Blind Hunter?",a="Blind Hunter är en sällsynt albino-fladdermus som lever i de djupaste, becksvarta gångarna i Razorfen Kraul. Den är anmärkningsvärt blek och svårfunnen jämfört med de vanliga grottfladdermössen närmare ingången.",al={"vem är blind hunter","vad är blind hunter","blind hunter fladdermus"}},{q="Var visar sig Blind Hunter?",a="Den håller till på de skuggiga stigarna i Razorfen Krauls inre och häckar långt bortom gränsen där dagsljuset utifrån helt försvinner.",al={"blind hunter plats","var hittar man blind hunter","blind hunter dyker upp"}},{q="Är Blind Hunter verkligen blind?",a="Naturkunniga och äventyrare misstänker att den verkligen är blind på grund av sina mjölkiga ögon och sin livsmiljö djupt inne i grottan. Men dess jaktförmåga är knivskarp: i mörkret förlitar den sig på skarp hörsel och ekolokalisering.",al={"är den blind","kan blind hunter se"}},{q="Kan jägare tämja Blind Hunter?",a="Ja, bestmästare som kan hantera bevingade rovdjur kan tämja Blind Hunter. Den blir en särpräglad, blek följeslagare för den som har tålamod att spåra upp den.",al={"kan jag tämja blind hunter","blind hunter tämjbar","blind hunter husdjur"}},{q="Varför är Blind Hunter vit?",a="Det är ett albinoexemplar vars färg troligen utvecklades efter ett liv i ständig mörker, långt från solens strålar. Andra fladdermöss vågar sig närmare grottmynningen.",al={"varför är den albino","varför är blind hunter vit","albino-fladdermus"}},{q="Hur skiljer den sig från vanliga fladdermöss i Kraul?",a="Vanliga fladdermöss i Kraul har typisk mörk färg och lever närmare ingången, där ljuset fortfarande når in. Blind Hunter är däremot blek, skygg och anpassad enbart till djupa underjordiska gångar.",al={"skillnad på kraulfladdermöss","kraulfladdermus jämfört med blind hunter"}}},fx={["7be10a10"]={q="På vems sida står Blind Hunter?",a="Blind Hunter är ett vilddjur som inte står på Razorfen-kvilboarnas eller någon yttre makts sida. Den är ett topprovdjur i Razorfen Krauls becksvarta grottor, där den överlever enbart på djurinstinkt och ser alla inkräktare som möjliga byten.",al={"blind hunters fraktion","står blind hunter med quilboar","blind hunters sida"}},["5a3f492c"]={q="Vad vill Blind Hunter?",a="Som en otämjd varelse under jord hyser Blind Hunter inga politiska ambitioner eller illvilja. Den jagar helt enkelt för att få mat och försvarar sitt avskilda jaktområde i Krauls djupaste, ljuslösa grottor mot alla som råkar snubbla in i dess lya.",al={"blind hunters motiv","blind hunters mål","vad vill blind hunter"}},["66c6306f"]={q="Varför är Blind Hunter här?",a="Till skillnad från de vanliga Kraul-fladdermössen, som fladdrar nära ingången där solljuset sipprar in, bor Blind Hunter i Razorfen Krauls djupaste, becksvarta delar. Den har levt i evigt mörker och trivs i hålorna långt där nere, där den aldrig har sett ljuset.",al={"varför är blind hunter i razorfen","varför finns blind hunter där","varför är blind hunter här"}}},fp="12,175,19.308.0,13.312.0,25.180.0,35.123.0,35.171.0,34.142.0,30.153.0,43.171.0"}
P.entries["npc:blind-mary"] = {n="Blind Mary",s="Blind Mary är en plågad banshee som hemsöker en övergiven, förfallen bondgård strax sydost om Darkshire i Duskwood. En gång var hon en fåfäng och vacker dödlig kvinna. Hennes våldsamma död och förvandling drev henne till att stympa sig själv i sorg över vad hon hade blivit.",h="Blind Mary är en plågad banshee som hemsöker en övergiven, förfallen bondgård strax sydost om Darkshire i...",kw={"banshee","blind mary","darkshire","duskwood","spökhår","hemsökt plats","spegel","vålnad"},ang={["class:Priest"]="Mary är ett tragiskt exempel på en själ som slitits loss från sina band av fruktansvärda trauman och som genom sorg och fåfänga fastnat halvvägs mellan liv och fördömelse.",["faction:Alliance"]="Blind Marys tragiska öde påminner Darkshires försvarare om hur djupt Duskwoods förbannelse har ödelagt vanligt folks liv.",["profession:Tailoring"]="Vävnadshantverkare söker ibland upp spöklika varelser som Mary för att få tag på spökhårstråd, ett ömtåligt, övernaturligt material vävt av eteriska rester."},sec={{t="En tragisk fåfänga",b="Innan skuggorna föll över Duskwood var Mary känd som en slående vacker dödlig kvinna som var mycket stolt över sitt utseende. Hon sågs sällan utan sin älskade spegel. När de odöda svepte över trakten dödades Mary tillsammans med många av sina grannar. Till skillnad från dem som fick vila i jorden dröjde hennes ande kvar som en eterisk banshee, dömd att vandra i de dödligas värld i en fasansfull, genomskinlig gestalt."},{t="Förblindad av förtvivlan",b="När Mary vaknade till odödlighet överväldigades hon av sorg, fasa och vrede över sin monstruösa spegelbild. Hon stod inte ut med åsynen av sitt spöklika ansikte och rev därför ut sina egna ögon med bara händerna, så att hon aldrig skulle se sig själv igen. I sin vånda kastade hon bort sin älskade spegel och driver nu genom sitt övergivna hem som en blind, gråtande vålnad, klamrande sig fast vid svaga minnen av det dödliga liv hon förlorade."}},faq={{q="Vem är Blind Mary?",a="Blind Mary är en banshee som hemsöker en förfallen gård i utkanten av Darkshire i sydost. I livet var hon en vacker kvinna från trakten, men hon slaktades när Duskwood sjönk ner i mörker och återuppstod som en odöd ande.",al={"vem är blind mary","blind marys bakgrund","blind marys historia","blind mary i duskwood"}},{q="Varför kallas hon Blind Mary?",a="Uppslukad av sorg och förtvivlan över sin fasansfulla bansheeform rev Mary ut sina egna ögon med bara händerna, så att hon aldrig mer skulle behöva se sin egen spegelbild.",al={"varför är hon blind","hur förlorade blind mary sina ögon","blind marys ögon"}},{q="Var håller Blind Mary till?",a="Hon dröjer sig kvar i en förfallen bondgård som kallas Blind Mary's Haunt, strax sydost om staden Darkshire i östra Duskwood.",al={"blind marys plats","var finns blind mary","blind marys tillhåll"}},{q="Är Blind Mary fientlig mot levande resenärer?",a="Till skillnad från de aggressiva gastarna och skeletten som strövar omkring i skogarna runtomkring angriper Blind Mary inte resenärer direkt. Hon är fångad i sin sorg och den som närmar sig hennes ruin kan tala med henne.",al={"är blind mary fientlig","angriper blind mary","kan man tala med blind mary"}},{q="Vad hände med Mary's spegel?",a="Efter att i fasa över sitt spöklika tillstånd ha slitit ut sina ögon kastade Mary bort sin dyrbara spegel. Den ligger nu förlorad någonstans i Duskwoods hemsökta trakter.",al={"marys spegel","blind marys spegel","vad hände med hennes spegel"}},{q="Varför söker äventyrare upp Blind Mary?",a="Resenärer och lokala hantverkare besöker Mary i samband med uppdrag kring Darkshire. De kan fråga efter hennes gamla spegel till Viktori Prism'Antras stjärnskådningsapparat eller ta med Madame Evas spökkam för att samla spökhår till en särskild tråd.",al={"blind marys uppdrag","varför besöka blind mary","blind marys uppdragskedja"}}},fx={d3776a58={q="På vems sida står Blind Mary?",a="Blind Mary tillhör ingen armé eller fraktion. Hon är en banshee som uppstod ur Duskwoods tragedi, men hon marscherar inte med Scourge eller för krig mot de levande. Fångad i sin ensamhet och plåga är hon neutral mot kringvandrande äventyrare. Hon bemöter alla som vill lyssna på hennes sorg eller återlämna minnessaker från hennes tidigare liv.",al={"är blind mary med alliance eller horde","blind marys fraktion","på vems sida står mary"}},["45d21972"]={q="Vad vill Blind Mary?",a="Mary längtar efter skönheten hon förlorade och står inte ut med att bli sedd. En gång bar hon alltid med sig en spegel och talar fortfarande om den med dem som frågar. Men när någon ger henne en kam påminns hon bara om vad hon har blivit, och hon skickar bort den.",al={"vad vill mary","vad söker blind mary","blind marys önskningar"}},["5b1d02ea"]={q="Varför är Blind Mary här?",a="Blind Mary hemsöker en övergiven bondgård strax sydost om Darkshire eftersom det var där hon mötte sitt tragiska slut. Hon dödades av de kringströvande odöda som översvämmar Duskwood och återuppstod som en gråtande banshee, bunden av sorg och vansinne till ruinerna av sitt forna hem.",al={"varför är blind mary i duskwood","varför hemsöker blind mary bondgården","blind marys plats och historia"}}},fp="10,242,15.388.0,18.344.0,18.181.0,29.116.0,28.120.0,42.207.0,38.155.0,39.241.0"}
P.entries["npc:bloodmage-drazial"] = {n="Bloodmage Drazial",s="Bloodmage Drazial är en blodalv som utövar magi från de mystiska konsterna och blodmagi i norra Blasted Lands. Tillsammans med sin syster Lynnore studerar han de inhemska bestarna i de röda ödemarkerna för att brygga kraftfulla alkemiska brygder åt resande äventyrare.",h="Bloodmage Drazial är en blodalv som utövar magi från de mystiska konsterna och blodmagi i norra Blasted Lands.",kw={"blasted boar","blasted lands","blodmagiker","brygder","drazial","lynnore","scorpok","snickerfang"},ang={["class:Mage"]="Drazial visar på blodalvernas kontroversiella avsteg: han använder öppet blodmagi och biologiska reagenser för att framställa magiska förstärkningar, i stället för att enbart förlita sig på Kirin Tors traditionella trollkonst."},sec={{t="Alkemiska studier i de röda ödemarkerna",b="Bloodmage Drazial håller till nära det norra passet där Swamp of Sorrows övergår i Blasted Lands, och ägnar sig åt en ovanlig sorts magi. Medan många högalver skyr de förbjudna konsterna eller sörjer över Quel'Thalas använder Drazial och hans syster Lynnore blodmagi för att utvinna kraft ur den hårda miljön. Ödemarkens fördärvade djurliv – scorpoks, snickerfangs och blasted boars – uppvisar en märklig, onaturlig livskraft, som Drazial och Lynnore tror kommer från energin som frigjordes när The Dark Portal öppnades. Genom att skörda särskilda organ och vävnader från dessa varelser brygger Drazial flyktiga brygder som ger enorma utbrott av fysisk styrka, smidighet och uthållighet."},{t="En oberoende leverantör",b="Till skillnad från många fraktionsagenter som är stationerade i Blasted Lands verkar Drazial med praktisk distans. Han har ingen officiell lojalitet till vare sig Alliansen eller Horden, utan väljer att sälja sin alkemi till alla som är tillräckligt härdade för att trotsa ödemarken och samla de råvaror han behöver. Så länge resenärer kommer med organ från de lokala rovdjuren är Drazial nöjd med att hålla sina kittlar bubblande."}},faq={{q="Vem är Bloodmage Drazial?",a="Bloodmage Drazial är en blodalvsmagiker som är stationerad nära den norra ingången till Blasted Lands. Tillsammans med sin syster Lynnore studerar han det lokala djurlivet och brygger kraftfulla alkemiska reagenser med delar från områdets fördärvade bestar.",al={"vem är drazial","drazials historia","bloodmage drazial npc"}},{q="Varför samlar Drazial på djurdelar?",a="Varelserna i Blasted Lands har anpassat sig för att överleva i fördärvad terräng laddad med magi. Drazial använder kraftfulla inre organ från vildsvin, hyenor, skorpioner och basilisker för att brygga särskilda elixir som stärker en krigares fysiska förmåga.",al={"varför vill drazial ha vildsvinslungor","drazials uppdragsföremål","drazials djurorgan"}},{q="Arbetar Drazial för Alliansen eller Horden?",a="Drazial är neutral gentemot båda fraktionerna. Han och Lynnore bryr sig inte om kriget mellan Stormwind och Horden, utan gör gärna affärer med alla äventyrare som vill bidra till deras magiska och alkemiska forskning.",al={"drazials fraktion","är drazial horde eller alliance","kan alliance prata med drazial"}},{q="Vem är den andra blodalven som håller till med honom?",a="Alven bredvid honom är hans syster, Bloodmage Lynnore. Syskonen utövar blodmagi tillsammans och brygger olika brygder från de många bestarna som strövar omkring i Blasted Lands.",al={"drazials följeslagare","vem är med drazial","lynnore"}}},fp="17,267,36.687.0,23.431.0,25.255.0,39.255.0,48.220.0,43.177.0"}
P.entries["npc:bloodmage-lynnore"] = {n="Bloodmage Lynnore",s="Bloodmage Lynnore är en blodsmidd utövare av förbjuden blodmagi. Hon har slagit läger med sin bror Drazial nära den norra ingången till Blasted Lands. Hon hjälper äventyrare genom att blanda kraftfulla alkemiska brygder av de lokala bestarnas organ.",h="Bloodmage Lynnore är en blodsmidd utövare av förbjuden blodmagi.",kw={"blasted lands","blodmagi","bloodmage lynnore","cerebral cortex compound","gizzard gum","lynnore"},ang={["class:Mage"]="För magiker som fascineras av okonventionell magi är Lynnore en svårfunnen och kontroversiell gren av arkan filosofi, som manipulerar livsessens i stället för vanliga leyenergier.",["faction:Horde"]="För resenärer från Horde är Lynnore en värdefull kontakt i Blasted Lands. Hon byter till sig unika alkemiska brygder av alla, oavsett fraktion, som kommer med råvarorna."},sec={{t="Blodmagiens mästare",b="Bloodmage Lynnore har slagit läger med sin bror Drazial nära den norra ingången till Blasted Lands och är en av de ytterst få alver i Eastern Kingdoms som utövar blodmagi. Det hårda och fördärvande landskapet i Blasted Lands bekymrar henne inte. Hon studerar de dolda arkana och livgivande energier som strömmar genom traktens bestar. Resenärer som ger henne hjärnor och kräsmagar från den lokala faunan upptäcker att hon kan destillera dessa makabra ingredienser till specialiserade elixir som ger stora förbättringar av intellekt och ande."}},faq={{q="Vem är Bloodmage Lynnore?",a="Bloodmage Lynnore är en blodmagiker av blodalverna som slagit läger nära den norra ingången till Blasted Lands. Hon ger uppdrag och är specialist på alkemi. I utbyte mot bestdelar erbjuder hon kraftfulla brygder som förbättrar egenskaper.",al={"vem är lynnore","bloodmage lynnore berättelse","lynnore blasted lands"}},{q="Var finns Bloodmage Lynnore?",a="Hon har slagit läger med sin bror, Bloodmage Drazial, nära den norra ingången till Blasted Lands, där passet från Swamp of Sorrows mynnar ut i ödemarken.",al={"lynnore plats","var finns lynnore","hitta bloodmage lynnore"}},{q="Vilka brygder tillverkar hon?",a="Lynnore använder delar från det lokala djurlivet, som basiliskhjärnor, gamkrås och snickerfang-käkar, för att brygga sällsynta tonika som Cerebral Cortex Compound och Gizzard Gum. De ger långvariga förbättringar av intellekt och ande.",al={"lynnores förstärkningar","förbrukningsvaror i blasted lands","cerebral cortex compound"}}},fp="17,249,21.549.0,25.228.0,37.168.0,31.252.0"}
P.entries["npc:bloodmage-thalnos"] = {n="Bloodmage Thalnos",s="Bloodmage Thalnos är en skelettmagiker som hemsöker kyrkogårdsflygeln i Scarlet Monastery. Det finns inga uppgifter om vem han var i livet, men han föll offer för odödhetens pest och dröjer sig nu kvar djupt inne på korstågets heliga mark, hungrig efter hämnd.",h="Bloodmage Thalnos är en skelettmagiker som hemsöker kyrkogårdsflygeln i Scarlet Monastery.",kw={"blodmagiker","kyrkogård","scarlet monastery","skelett","thalnos"},ang={["class:Mage"]="Thalnos visar hur pesten kan förvrida en begåvad magiker till något hämndlystet som fortfarande behärskar eld och skugga.",["class:Priest"]="Bland gravarna är Thalnos ett oroande tecken på att korstågets nit inte har hållit mörkret borta från dess egen heliga mark.",["faction:Horde"]="De Fördömda ser i Thalnos det de undkom: en odöd magiker utan någon annan vilja kvar än hämnd, på lur i hjärtat av Scarlet Crusades eget kloster."},sec={{t="En magiker återuppstånden i döden",b="Inga uppgifter berättar vem Thalnos var i livet. Oavsett hans bakgrund föll han offer för odödhetens pest. I stället för att renas eller förintas för gott återuppstod han som ett förtvinat skelett, fortfarande klamrande sig fast vid sin flammande magi och arkana mästerskap, och ropande efter hämnd och fler själar."},{t="Kyrkogårdens mästare",b="Thalnos är instängd i den innersta delen av klostrets gårdsgravar och befaller gengångare och släpande odöda hantlangare mot alla som stör hans domän. Hans fortsatta närvaro är en bitter motsägelse för korståget: ett odött monster som dröjer sig kvar precis under deras heliga salar och förkroppsligar den fasa de svor att utrota för evigt."}},faq={{q="Vem är Bloodmage Thalnos?",a="Thalnos är en skelettmagiker som hemsöker klostrets kyrkogård. Det finns inga uppgifter om vem han var i livet; han föll offer för odödhetens pest och återuppstod som en odöd magiker som fortfarande hungrar efter hämnd.",al={"vem är thalnos","thalnos historia","information om bloodmage thalnos"}},{q="Varför tillåts ett odött skelett vara i Scarlet Monastery?",a="Korståget avrättar fanatiskt alla odöda de ser, vilket gör Thalnos överlevnad till ett mysterium. Undangömd längst bort på kyrkogården bland återuppståndna kryptor och andar stryker han omkring i sin egen fördärvade domän i stället för att röra sig fritt bland de levande korsfararna.",al={"varför är thalnos i klostret","varför behåller scarlet crusade thalnos","scarlet crusades odöda magiker"}},{q="Vilka krafter använder Thalnos?",a="Trots att han behållit titeln Bloodmage och återuppstått som ett skelett behärskar Thalnos flammande besvärjelser och skuggmagi, och han frammanar hämndlystna andar och vandrande döda för att övermanna inkräktare på kyrkogården.",al={"thalnos besvärjelser","bloodmage thalnos magi","vad gör thalnos"}},{q="Var Thalnos en blodalv?",a="Hans ursprungliga släktskap som dödlig är osäkert. Titeln Bloodmage i sig bevisar inte att han var en blodalv.",al={"är thalnos högälv","thalnos ras","vilken ras var thalnos"}},{q="Vem vill se Thalnos död?",a="Thalnos är fientlig mot inkräktare på klostrets kyrkogård. Ingen särskild order om att döda honom är fastställd för den här epoken.",al={"thalnos uppdrag","vem vill döda thalnos","ljusets mörka sida thalnos"}}},fx={ee50c387={q="På vems sida står Bloodmage Thalnos?",a="Thalnos tjänar ingen. Efter att ha dukat under för de odödas pest blev han en varelse som helt drivs av hämnd och ohelig kraft. Nu är han ett odött skelett som våldsamt vaktar sitt eget område på klostrets begravningsplats. Han befaller vålnader och zombifierade varelser att slakta alla levande inkräktare som korsar hans väg.",al={"thalnos fraktion","vem tjänar thalnos","tillhör thalnos scarlet crusade"}},fb23ba27={q="Vad vill Bloodmage Thalnos?",a="Thalnos har blivit vansinnig av att vara odöd och önskar sig inte mycket mer än ohelig hämnd. Den hämndlystne skelettmagikern är bunden till klostrets begravningsplats och befaller rastlösa vålnader och återupplivade lik att utplåna alla som vågar sig in i hans förbannade område.",al={"vad vill thalnos","thalnos mål","thalnos motiv"}},["39b55bcf"]={q="Varför fruktas Bloodmage Thalnos?",a="Thalnos är en mäktig odöd magiker som härskar över klostrets begravningsplats. Han slungar eld och skugga mot inkräktare och ropar efter hämnd och fler själar. Att en sådan varelse lurar bland Scarlet Crusades egna döda gör honom ännu mer kuslig.",al={"varför fruktas thalnos","vad gjorde thalnos berömd","bloodmage thalnos rykte"}}},fp="17,258,21.282.0,23.362.0,25.203.0,59.256.0,31.200.0,24.111.0,23.130.0"}
P.entries["npc:bluff-runner-windstrider"] = {n="Bluff Runner Windstrider",s="Bluff Runner Windstrider är en kringvandrande taurenbudbärare som rör sig över Thunder Bluffs platåberg. Han bär brådskande meddelanden genom staden och visar hordenäventyrarna vägen mot avlägsna gränstrakter som Ashenvale, Feralas och Plaguelands.",h="Bluff Runner Windstrider är en kringvandrande taurenbudbärare som rör sig över Thunder Bluffs platåberg.",kw={"ashenvale","bluff runner","camp mojache","budbärare","mulgore","thunder bluff","windstrider"},ang={["faction:Horde"]="Windstrider är en viktig länk mellan Mulgore fridfulla slätter och de blodiga fronterna där horden kämpar för resurser och överlevnad.",["race:Tauren"]="Traditionella löpare som Windstrider håller de utspridda stammarna och de centrala äldste förbundna utan moderna maskiner eller främmande postnätverk."},sec={{t="En budbärare på platåbergen",b="Thunder Bluffs höga platåer kräver snabba fötter för att hålla ledare och besökare informerade, och Bluff Runner Windstrider fyller den viktiga rollen. Han springer ständigt över repbroar och gångvägar i taurenhuvudstaden och fungerar som både härold och budlöpare. När viktiga utposter i Kalimdor eller Eastern Kingdoms behöver förstärkning hejdar Windstrider förbipasserande hjältar så att de kan föra bud och hörsamma kallelsen till vapen."},{t="Kallelser till gränslandet",b="Windstriders meddelanden når långt bortom Mulgore lugna gränser. Han skickar äventyrare norrut till Ashenvale för att delta i Senani Thunderhearts stora jakt vid Splintertree Post, visar erfarna spejare söderut mot Camp Mojache i Feralas djup och förmedlar allvarliga varningar om det pågående odöda hotet i Western Plaguelands. Genom honom förblir Mulgore stamfolkets hjärta knutet till hordens vidare konflikter."}},faq={{q="Vem är Bluff Runner Windstrider?",a="Bluff Runner Windstrider är en taurenbudbärare som vandrar omkring i Thunder Bluff. Han ansvarar för att sprida nyheter och samla dugliga resenärer från horden för att hjälpa till i brådskande fälttåg runt Azeroth.",al={"windstrider npc","bluff runner","vem är windstrider"}},{q="Var hittar jag Bluff Runner Windstrider?",a="Windstrider håller inte till på en enda plats. Han springer ständigt längs Thunder Bluffs broar och terrasser, ofta i en slinga mellan den centrala platån och de närliggande höjderna.",al={"windstriders plats","var finns bluff runner","hitta windstrider"}},{q="Vilka uppdrag erbjuder Windstrider?",a="Han erbjuder vägvisaruppdrag som leder växande äventyrare till avlägsna omstridda områden, däribland jakten i Ashenvale, grundandet av Camp Mojache i Feralas och kallelser till vapen i Plaguelands.",al={"windstriders uppdrag","vad ger han","bluff runners uppgifter"}},{q="Varför kallas han ”Bluff Runner”?",a="Tauren förlitar sig på smidiga löpare med stor uthållighet för att förmedla bud över Thunder Bluffs oländiga platåberg, klippor och hängande broar, där ridna färder kan vara besvärliga eller långsamma.",al={"vad är en bluff runner","bluff runner titel"}}},fx={e05bd34a={q="På vems sida står Bluff Runner Windstrider?",a="Bluff Runner Windstrider tjänar taurenstammarna och Horde från högt uppe på Thunder Bluff. Som officiell kurir och budbärare agerar han på de äldstes och hövdingarnas uppdrag för att leverera viktiga nyheter, samla krigare och hålla kontakten med avlägsna utposter i Kalimdor och bortom det.",al={"windstriders fraktion","bluff runner windstriders lojalitet","vem tjänar windstrider"}},b3137841={q="Varför är Bluff Runner Windstrider här?",a="Windstrider färdas över Thunder Bluffs höjder för att sprida brådskande budskap bland resenärer och försvarare. En stad som breder ut sig över stora platåer behöver snabba kurirer till fots som förmedlar besked mellan ledare och äventyrare. På så sätt når budskapen dem som är redo att svara på avlägsna bosättningars rop på hjälp.",al={"varför är windstrider i thunder bluff","windstriders syfte i thunder bluff","vad gör windstrider här"}},["7698149f"]={q="Vad vill Bluff Runner Windstrider?",a="Windstrider söker dugliga äventyrare som är villiga att bege sig långt bortom Mulgore. Genom att leverera kallelser, nyheter och uppmaningar till strid hoppas han leda framväxande hjältar till gränstrakter där Horde behöver hjälp. Han visar dem vägen till viktiga jaktmarker och hårt ansatta utposter runtom i Azeroth.",al={"vad behöver windstrider","bluff runner windstriders motiv","varför har windstrider uppdrag"}}},fp="24,195,24.385.0,21.397.0,32.161.0,42.138.0,35.188.0,34.168.0"}
P.entries["npc:bolvar-fordragon"] = {n="Bolvar Fordragon",s="Stormwinds krona och arméer vilar i Bolvar Fordragons händer medan kung Varian är försvunnen. Som regent och högste befälhavare över Stormwinds väpnade styrkor står han vid den unge kungen Anduins sida i Stormwind Keep och försöker hålla riket samman. Problemen på hemmaplan växer, medan Lady Katrana Prestors råd ofta fördröjer hans militära beslut.",h="Stormwinds krona och arméer vilar i Bolvar Fordragons händer medan kung Varian är försvunnen.",kw={"anduin wrynn","bolvar","fordragon","highlord","katrana prestor","regent","stormwind keep"},ang={["class:Paladin"]="Som paladin förkroppsligar Bolvar Alliansens krigsideal: hängivenhet till Ljuset och orubblig pliktkänsla gentemot sitt folk, även när de politiska intrigerna hopar sig.",["faction:Alliance"]="Som Stormwinds högste befälhavare leder Bolvar människornas militär och väger lokala uppror mot Alliansens större åtaganden."},sec={{t="Rikets regent",b="Kung Varian försvann på väg till ett fredstoppmöte på Theramore Isle och lämnade Stormwind i politisk oreda. Den tioårige prins Anduin kröntes för att säkra kontinuiteten, medan Highlord Bolvar Fordragon tog på sig uppgiften att styra som regent. Bolvar är en vördad paladin som är hängiven kronan, och nu står han inför ett pressat rike. Stormwinds soldater är utspridda över Westfall, Redridge och Duskwood. Lady Katrana Prestors avfärdande råd gör bördan tyngre och hindrar honom gång på gång från att skicka kungliga trupper till gränsbyarna."},{t="Ett nät av svek",b="Stadens magistrater och gränsmarskalkar ber om förstärkningar mot Defias Brotherhood och Blackrock-orcherna, men Lady Prestor påverkar i tysthet kungliga dekret och förringar varje rapport om fara. Bolvar respekterar adelns råd och tvekar att agera utan obestridliga bevis. Utan att förstå det lämnar han kronan oförmögen att agera. När övertygande bevis dyker upp, som varningar från utredare i Theramore eller nyheter om försvunna fältbefäl, lägger regenten hovets sedvänjor åt sidan och vänder sig till oberoende äventyrare."}},faq={{q="Varför styr Bolvar i stället för kung Varian?",a="Kung Varian Wrynn försvann under misstänkta omständigheter när han seglade till ett diplomatiskt toppmöte på Theramore Isle. Hans tioårige son Anduin kröntes för att bevara den politiska ordningen, medan Highlord Bolvar Fordragon blev regent och styrde riket och förde befäl över dess arméer tills Varian hittas.",al={"var är kungen","varför bestämmer bolvar","vem är regenten"}},{q="Varför skickar Bolvar inte soldater för att hjälpa Redridge eller Westfall?",a="Stormwinds stående arméer är hårt ansträngda med att bevaka rikets kärnområden och gränser. Lady Katrana Prestor, Bolvars främsta rådgivare, ifrågasätter gång på gång rapporter från platser som Lakeshire, kallar dem överdrifter och avråder från att skicka kungliga styrkor. Utan militära bevis ger Bolvar i stället oberoende äventyrare i uppdrag att ingripa.",al={"varför finns ingen stormwind-armé","varför skickar bolvar ingen hjälp","trupper till lakeshire"}},{q="Vilken relation har Bolvar till Lady Katrana Prestor?",a="Lady Katrana Prestor är den främsta rådgivaren vid Stormwinds tron. Bolvar respekterar hennes politiska omdöme och kunskap om adelns angelägenheter, men hon uppmanar honom ständigt till återhållsamhet och råder honom att avfärda rapporter om drakar, orcher och Defias-komplotter.",al={"bolvar och prestor","vem är lady prestor för bolvar"}},{q="Vilken koppling har Bolvar till den unge prins Anduin?",a="Bolvar är inte släkt med Anduin, men han är den unge kungens hängivna beskyddare, förmyndare och mentor. Han står vid Anduins tron i Stormwind Keep, skyddar honom från hovets intriger och håller ätten Wrynn trygg tills Varian återvänder.",al={"anduin och bolvar","är bolvar anduins far"}}},fx={["634d3c0f"]={q="Vem är Highlord Bolvar Fordragon?",a="Highlord Bolvar Fordragon är en vördad paladin och Stormwinds regent. Som rikets högste befälhavare styr han på den unge kung Anduin Wrynns vägnar efter kung Varian Wrynns mystiska försvinnande. Han är känd för sin ädla själ och heder, och bär den enorma bördan att upprätthålla ordningen och försvara riket under en av Stormwinds mest sårbara tider.",al={"vem är bolvar","bolvars identitet","vem är highlord bolvar"}},["946cb7aa"]={q="På vems sida står Bolvar Fordragon?",a="Bolvar är fullständigt hängiven kungariket Stormwind och Alliance. Hans främsta lojalitet tillhör huset Wrynn. Han skyddar prins Anduin med all kraft och arbetar för att värna rikets territorier trots allvarlig politisk oro och uttunnade garnisoner.",al={"bolvars lojalitet","vilken fraktion tillhör bolvar","bolvars fraktion"}},["309206e7"]={q="Vad vill Bolvar Fordragon?",a="Framför allt vill Bolvar bevara stabiliteten i Stormwind, ta reda på vad som hänt den försvunne kung Varian och skydda den unge Anduin Wrynn från dem som vill utnyttja hans ungdom. Han försöker bemöta hoten från Defias Brotherhood och Blackrock-orcherna och samtidigt balansera försvaret av avlägsna områden som Redridge och Westfall mot kungliga rådets önskemål.",al={"bolvars mål","vad försöker bolvar göra","bolvars motiv"}},e6552818={q="Varför är Bolvar Fordragon berömd?",a="Bolvar är känd som en paladin med enastående beslutsamhet, mod och orubblig moralisk övertygelse. Som Highlord, regent och högste befälhavare över Stormwinds styrkor har hans ledarskap och ståndaktiga heder gjort honom till en av de mest respekterade militära strategerna och paladinerna i hela Alliance.",al={"varför är bolvar berömd","bolvars rykte","är bolvar berömd"}}},fp="16,333,19.514.0,15.531.1,44.297.0,60.355.0,56.256.0,51.248.0"}
P.entries["npc:braelyn-firehand"] = {n="Braelyn Firehand",s="Braelyn Firehand är en alvisk utövare av arkana konster som lever stillsamt bland Horden vid Sun Rock Retreat i Stonetalon Mountains. Hon säger sig vilja undanröja mystiska hinder i höglandet och värvar resenärer för att angripa nattalvernas väktare vid Stonetalon Peak.",h="Braelyn Firehand är en alvisk utövare av arkana konster som lever stillsamt bland Horden vid Sun Rock Retreat...",kw={"braelyn","cenarius","firehand","highborne","ordanus","stonetalon","sun rock retreat"},ang={["class:Druid"]="Hennes avsiktliga slakt av Cenarius söner och plundring av The Talon Den är ett avskyvärt brott mot naturens balans.",["class:Mage"]="Braelyn talar gärna om ley-energier och mystiska blockeringar och tilltalar utövare som förstår hur arkana krafter flödar genom landet.",["faction:Horde"]="Braelyn anlitar gärna vandrare från Horden för att angripa nattalverna och använder de pågående territoriella konflikterna i Kalimdor som täckmantel för en djupare, mörkare agenda."},sec={{t="En oväntad gäst",b="Bland taurenhyddorna och de rustika orktälten vid Sun Rock Retreat sticker Braelyn Firehand ut. En blodalv som bor öppet i en avlägsen bosättning i Horden är en ovanlig syn. Tillflyktsortens shamaner och hövdingar tolererar hennes närvaro och verkar ovetande om hennes verkliga lojaliteter. Braelyn utger sig för att vara en observatör som fascineras av den regionala magins flöde, och hon anlitar gärna förbipasserande legosoldater från Horden för farliga uppdrag bland klipporna."},{t="Ett agg mot lunden",b="Braelyn riktar sina allierade mot nattalvernas druider och Cenarius heliga avkomma, som håller till högt uppe vid Stonetalon Peak. Hon hävdar att druiderna stryper de omgivande ley-linjerna och hämmar det arkanas flöde genom bergen. Hennes verkliga motiv är dock djupt personliga: hon bär på bittra minnen av Keeper Ordanus och minns hans uråldriga högfärd, då han ansåg sig stå över till och med Highborne. Hon betalar villigt resenärer från Horden för att jaga rätt på Ordanus och återvända med hans huvud."},{t="Band till Jaedenar",b="Braelyns bitterhet är mer än ett kvardröjande hat; hennes mål ligger helt i linje med den del av Shadow Council som verkar från Jaedenar i Felwood. Genom att uppmuntra Hordens kämpar att systematiskt slakta nattalverna och väktarna som håller de heliga bergen fria röjer hon väg för mörkare makter, samtidigt som hon döljer sin ondskefulla tillhörighet bakom skenet av vanliga gränsstrider."}},faq={{q="Vem är Braelyn Firehand?",a="Braelyn Firehand är en alvmagiker som bor vid Sun Rock Retreat i Stonetalon Mountains. Omgiven av Horden driver hon sin egen arkana agenda mot nattalverna som vaktar Stonetalon Peak.",al={"vem är braelyn","braelyn firehands historia","alv vid sun rock retreat"}},{q="Varför bor en alv vid Sun Rock Retreat?",a="Sun Rock Retreat är en livlig, avlägsen utpost. Braelyn utnyttjar lägrets tolerans och den jämna strömmen av krigare från Horden för att låta andra utföra sina personliga angrepp mot nattalverna, utan att väcka bosättningens ledare misstankar direkt.",al={"varför är hon med horden","varför är braelyn vid sun rock","blodalv i stonetalon"}},{q="Vad vill hon ha gjort vid Stonetalon Peak?",a="Hon ber äventyrare angripa druiderna och Cenarius barn vid Stonetalon Peak och hävdar att de hämmar magins flöde. Hennes senare jakt på Keeper Ordanus leder till Raynewood Retreat i Ashenvale.",al={"braelyns uppdragsmål","varför döda ordanus","braelyn firehands uppgifter"}},{q="Vad har hon för historia med Keeper Ordanus?",a="Braelyn hävdar att hon kände Keeper Ordanus personligen i en avlägsen forntid. Hon hyser ett bittert agg mot honom och påstår att han var oerhört högfärdig och ansåg sig överlägsen till och med de forntida Highborne.",al={"braelyn och ordanus","hur känner hon ordanus","ordanus bakgrund"}},{q="Vad säger Braelyn Firehand att hon forskar om?",a="Braelyn hävdar att druiderna och Cenarius barn vid Stonetalon Peak begränsar magins flöde. Hon vill få bort dem så att hon kan dra nytta av den kraften.",al={"braelyns verkliga fraktion","braelyn och shadow council","vem arbetar hon för"}},{q="Är Braelyn magiker eller häxmästare?",a="Hon utövar arkana konster och strider med Fireballs.",al={"braelyns klass","är braelyn en häxmästare","braelyn firehands besvärjelser"}}},fx={deec6fbf={q="Vilka band har Braelyn Firehand?",a="Braelyn tjänar en mästare i Jaedenar och har band till Shadow Council. Hon värvar Horde-resenärer till angrepp mot nattalverna och Cenarius barn.",al={"braelyn firehands band","vilka band har braelyn","braelyn firehands allierade"}}},fp="16,139,17.325.0,26.380.1,16.270.1,24.202.0,42.208.0,43.203.0,40.184.0,51.148.2,31.57.2"}
P.entries["npc:braenna-flintcrag"] = {n="Braenna Flintcrag",s="Braenna Flintcrag är en dvärgprästtränare som tjänstgör i Hall of Mysteries i Ironforges Mystic Ward. Hon undervisar hängivna följare av det heliga ljuset och vägleder dvärgakoliter när de utvecklar sin andliga disciplin och läkekonst. Hon meddelar också besökande nattalvpräster när de kallas hem till Temple of the Moon i Darnassus.",h="Braenna Flintcrag är en dvärgprästtränare som tjänstgör i Hall of Mysteries i Ironforges Mystic Ward.",kw={"braenna flintcrag","hall of mysteries","det heliga ljuset","ironforge","mystic ward","prästtränare","returning home"},ang={["class:Priest"]="För dvärgpräster och Alliansens präster är Braenna en pålitlig mentor i Ironforge som lär ut viktiga besvärjelser och hur man bemästrar Ljuset.",["race:Dwarf"]="Braenna förkroppsligar dvärgarnas djupt rotade andliga hängivenhet i Ironforge och förenar stridsvilja med trogen tjänst åt det heliga ljuset."},sec={{t="En vägledare i Hall of Mysteries",b="I Hall of Mysteries stilla nischer i Ironforges Mystic Ward tjänar Braenna Flintcrag Alliansen som en hängiven prästtränare. Ironforge är känt för sina dånande smedjor och krigare, men hängivna dvärgar som Braenna vårdar Khaz Modans andliga välbefinnande. Hon vägleder noviser som hör det heliga ljusets kallelse och lär dem återställande läkekonst och skyddande besvärjelser, två discipliner som krävs för att överleva i en allt farligare värld."}},faq={{q="Vem är Braenna Flintcrag?",a="Braenna Flintcrag är en dvärgprästtränare i Hall of Mysteries i Ironforges Mystic Ward. Hon lär präster nya heliga böner, besvärjelser och andliga discipliner.",al={"braenna flintcrag","vem är braenna","prästtränaren braenna"}},{q="Var hittar jag Braenna Flintcrag?",a="Du hittar henne i Hall of Mysteries, en stor helgedom för de magiska och gudomliga konsterna i Ironforges Mystic Ward.",al={"var finns braenna","braenna flintcrags plats","hitta braenna flintcrag"}},{q="Vilka tjänster erbjuder hon resenärer?",a="Hon erbjuder utbildning och befordran i rang för Alliansens präster. Hon berättar också för besökande nattalvpräster när de kallas hem till Temple of the Moon i Darnassus, som i uppdraget Returning Home.",al={"braennas tjänster","vad gör braenna","kan braenna träna mig"}},{q="Är hon släkt med någon annan i Khaz Modan?",a="Hon delar efternamnet Flintcrag med Thulman Flintcrag, vilket tyder på att hon tillhör en framstående dvärgasläkt i Khaz Modan.",al={"flintcrag-släkten","thulman flintcrags släkting","braenna flintcrags släktingar"}}},fx={d5abdbfc={q="På vems sida står Braenna Flintcrag?",a="Braenna är hängiven Alliance och dvärgarnas kungarike Ironforge. Från Hall of Mysteries arbetar hon tillsammans med andra lärda, mystiker och heliga utövare. Hon tjänar sitt folk och hela Alliance genom den Heliga Ljusets lära och andliga disciplin.",al={"braenna flintcrags fraktion","vem tjänar braenna","braenna flintcrag och alliance"}},["787cf3cf"]={q="Vad vill Braenna Flintcrag?",a="Braenna ägnar sig åt att vägleda och förbereda trogna lärjungar i den Heliga Ljusets mysterier. Hon lägger sin tid på att utbilda blivande dvärgpräster i Ironforge och ser till att de får den andliga styrka och de heliga färdigheter som behövs för att hjälpa sitt samhälle och skydda Alliance.",al={"vad vill braenna","braenna flintcrags mål","braenna flintcrags syfte"}},["19ad6f1b"]={q="Varför är Braenna Flintcrag här?",a="Braenna bor i Hall of Mysteries i Ironforges Mystic Ward, som är huvudstadens heliga fristad för gudomliga studier och magisk praktik. Bland sina medmentorer finns hon till hands för att hjälpa och undervisa präster som färdas genom eller tjänar bergsstaden.",al={"varför är braenna här","varför är braenna i ironforge","varför finns braenna flintcrag där"}}},fp="17,240,32.337.0,25.126.0,35.78.0,44.175.0,44.135.0"}
P.entries["npc:brainwashed-noble"] = {n="Brainwashed Noble",s="Djupt inne i grottorna utanför The Deadmines hålls Brainwashed Noble fången under Defias kontroll. Magisk manipulation har berövat honom hans vilja, och han tjänar brödraskapet tillsammans med odöda tjänare i stället för att vandra i Stormwinds ståtliga salar.",h="Djupt inne i grottorna utanför The Deadmines hålls Brainwashed Noble fången under Defias kontroll.",kw={"brainwashed noble","the deadmines","defias brotherhood","adelsmännens hus","moonbrook","stormwind","westfall"},ang={["class:Mage"]="Som magiker använder Brainwashed Noble magiska stavar och arkanmagi som Polymorph, vilket tyder på att han fick formell magisk utbildning i huvudstaden innan hans sinne krossades.",["race:Human"]="Som människa visar det djupa agg som Defias Brotherhood hyser mot Stormwinds styrande elit att en jämlike i riket kan reduceras till en viljelös vaktpost under Westfall."},sec={{t="En bricka i brödraskapets spel",b="Brainwashed Noble vandrar genom gångarna som leder in i The Deadmines, bland banditer och ruttnande lik. Rester av förnäm klädsel tyder på att han tillhörde Stormwinds House of Nobles, kanske som sittande medlem eller ättling. Edwin VanCleef tog honom till fånga, och Defias valde förtrollningar framför lösen och böjde hans sinne till en besvärjande vakt för deras tillflyktsort. Brödraskapets hat mot de stormän som vägrade betala efter att staden återuppbyggts sträcker sig ända in i grottorna under Westfall."}},faq={{q="Vem är Brainwashed Noble?",a="Brainwashed Noble är en aristokratisk människa som tros komma från Stormwinds House of Nobles. Defias Brotherhood tillfångatog honom och kuvade honom med magi djupt inne i The Deadmines grottor.",al={"vem är brainwashed noble","vad är brainwashed noble","adelsman i the deadmines"}},{q="Varför befinner sig en Stormwind-adelsman i The Deadmines grottor?",a="Defias Brotherhood hyser ett bittert agg mot Stormwinds aristokrati över skulder som lämnades obetalda efter att staden återuppbyggts. En tillfångatagen adelsman ger dem magisk arbetskraft och möjlighet till personlig hämnd.",al={"varför är han i the deadmines","varför är adelsmannen i grottor"}},{q="Var hittar man Brainwashed Noble?",a="Brainwashed Noble finns i grottgångarna i Moonbrook som leder mot ingången till The Deadmines, bland gångar där skelettartade odöda håller till.",al={"brainwashed nobles plats","var dyker han upp"}},{q="Hur blev han hjärntvättad?",a="Det är okänt vem som utförde magin. Avfälliga besvärjare och förtrollare bland Defias i Westfall kan böja en fånges sinne med trolldom.",al={"vem hjärntvättade honom","hur kontrolleras han"}}},fx={["7d2ae820"]={q="Vems sida står Brainwashed Noble på?",a="Han tjänar Defias Brotherhood, men inte av egen vilja. Han har berövats sin vilja och hålls fången av aristokratin. Nu vaktar han nätverket av tunnlar som leder mot Edwin VanCleefs fäste och använder sina magiska konster mot alla som tränger in på laglös mark.",al={"brainwashed noble sida","vem slåss brainwashed noble för","är brainwashed noble med i defias"}},["0b33d704"]={q="Vem är Brainwashed Noble knuten till?",a="Hans förflutna knyter honom till Stormwinds adelshus, den styrande aristokratin som för närvarande regerar under Highlord Bolvar Fordragon. I sitt nuvarande, krossade tillstånd är han dock helt bunden till Edwin VanCleef och de Defias-sammansvurna som håller honom i sitt grepp djupt inne i Moonbrook-gruvorna.",al={"brainwashed nobles band","vem kontrollerar brainwashed noble","brainwashed nobles fraktion"}}},fp="17,224,25.460.1,29.181.0,52.204.1,41.143.1,23.151.0"}
P.entries["npc:brandur-ironhammer"] = {n="Brandur Ironhammer",s="Brandur Ironhammer är en paladintränare av dvärgsläkt i Hall of Mysteries i Ironforge. Han vägleder blivande förkämpar för det heliga ljuset genom deras första riter, prövar deras hängivenhet och skickar dem ut över alliansen.",h="Brandur Ironhammer är en paladintränare av dvärgsläkt i Hall of Mysteries i Ironforge.",kw={"brandur","hall of mysteries","ironforge","ironhammer","mystic ward","paladin","tiza battleforge","tome of divinity","tränare"},ang={["class:Paladin"]="För dvärgiska paladiner och alliansens paladiner är Brandur en viktig mentor i Ironforge. Han erbjuder nödvändig stridsträning, heliga sigill och direktiv som leder till avancerade heliga prövningar.",["race:Dwarf"]="Brandur förkroppsligar Khaz Modans tradition av dvärgpaladiner, som förenar kampens stål med vördnad för det heliga ljuset i hjärtat av Ironforge."},sec={{t="En vägledare i Mystic Ward",b="I Hall of Mysteries stilla alkover tjänar Brandur Ironhammer alliansen genom att lära nybörjarpaladiner det heliga ljusets vägar. Tillsammans med sin kollega Tiza Battleforge håller Brandur ett vakande öga på unga dvärgförkämpar och vägleder dem genom prövningarna i Tome of Divinity. Han är djupt hängiven sina heliga plikter, men har erkänt sina personliga brister efter Tizas uppriktiga råd. Han arbetar målmedvetet för att tygla sin avund och bevara den inre renhet som krävs av en ljusets krigare."},{t="En länk till Silver Hand",b="Brandur är en viktig förbindelselänk mellan Ironforge och den bredare alliansens brödraskap. När mänskliga invigda hittar till dvärgarnas berg skickar han dem söderut till Duthorian Rall i Cathedral of Light. När paladinerna blir mer erfarna i fält samordnar Brandur deras utplacering till slagfält som Chillwind Camp i Western Plaguelands. Till sist skickar han veteraner bland korsfararna till Lord Grayson Shadowbreaker för att genomgå den krävande prövningen för krigshästen."}},faq={{q="Var finns Brandur Ironhammer?",a="Brandur finns i Hall of Mysteries, som ligger i Mystic Ward på norra sidan av Ironforge.",al={"brandur ironhammer plats","hitta brandur ironhammer","var finns brandur"}},{q="Vilken roll har Brandur Ironhammer för paladiner?",a="Han är tränare för paladinklassen och lär ut nya besvärjelser och förmågor, vägleder invigda genom klassuppdrag som Tome of Divinity och hänvisar erfarna paladiner till avancerade prövningar i alliansen.",al={"brandur paladintränare","vad gör brandur","brandurs syfte"}},{q="Vem är Brandurs kollega i Hall of Mysteries?",a="Brandur arbetar tillsammans med Tiza Battleforge, en annan paladintränare av dvärgsläkt i Hall of Mysteries. Tiza är en uppriktig mentor för honom och har påpekat att hans svartsjuka är hans svaghet, ett fel Brandur har svurit att övervinna.",al={"brandurs partner","vem arbetar med brandur","tiza battleforge relation"}},{q="Varför skickar Brandur paladiner till Stormwind City?",a="Mänskliga paladiner som tränar i Ironforge hänvisas ofta av Brandur till Duthorian Rall eller Lord Grayson Shadowbreaker i Cathedral of Light i Stormwind. På så vis genomgår de de formella riter som föreskrivs av deras eget kungarike.",al={"brandur stormwind uppdrag","varför gå till duthorian rall","brandur mänskliga paladiner"}},{q="Har Brandur kopplingar till kampen mot Scourge?",a="Ja. Brandur vidarebefordrar brådskande kallelser från Commander Ashlam Valorfist och skickar beprövade paladiner med renhet och tapperhet för att bistå alliansens korståg vid Chillwind Camp, vid gränsen till Western Plaguelands.",al={"brandur plaguelands","chillwind camp brandur","ashlam valorfist brandur"}}},fx={ce9b1d9f={q="Vem är Brandur Ironhammer?",a="Brandur Ironhammer är en dvärgisk paladintränare som tjänstgör i Hall of Mysteries i Ironforges Mystic Ward. Han är hängiven det Heliga ljuset och handleder blivande paladiner i strid, tro och dygd. Han vägleder både dvärgiska noviser och mänskliga allierade till de prövningar och mästare som kan vässa deras heliga kall.",al={"brandur ironhammer","vem är brandur","brandurs bakgrund"}},d07784b0={q="Vems sida står Brandur Ironhammer på?",a="Brandur är trogen kungariket Ironforge och Grand Alliance. Han tjänar det Heliga ljusets paladiner, samarbetar nära med försvarare i Stormwind och förmedlar uppmaningar om stöd till Alliansens befälhavare vid aktiva fronter mot Scourge.",al={"brandur ironhammers fraktion","vem tjänar brandur","brandur och alliansen"}},cf78f4b8={q="Vad vill Brandur Ironhammer?",a="Brandur vill fostra en duglig och rättskaffens ny generation paladiner som kan skydda Alliansen och bekämpa mörkret som hotar Azeroth. Personligen strävar han efter att övervinna sina egna brister. Han har lovat sin kollega Tiza Battleforge att arbeta på att övervinna sin kvardröjande svartsjuka.",al={"brandurs mål","vad vill brandur","brandurs syfte"}},["65b7f94c"]={q="Varför är Brandur Ironhammer i Ironforge?",a="Han tjänstgör i Hall of Mysteries som en ledstjärna och instruktör för heliga krigare i dvärgarnas huvudstad. Här lär han ut stridskonst och andliga läror, prövar noviser och samordnar sig med lärare runtom i Alliansen för att se till att Ljusets riddare är redo för strid.",al={"varför är brandur här","brandur i hall of mysteries","varför är brandur i ironforge"}}},fp="18,108,26.330.0,26.354.0,36.98.0,52.156.0,47.168.0,49.177.0,63.204.0"}
P.entries["npc:brann-bronzebeard"] = {n="Brann Bronzebeard",s="Brann Bronzebeard är den yngste brodern till King Magni och Muradin, som tros vara död. Han är känd över hela Azeroth som en enastående upptäcktsresande och arkeolog, och som en av grundarna av Explorers' League. Hans omättliga nyfikenhet på titanruiner och forntida historia har drivit honom djupt in i Silithus dödliga ödemarker. Hans följeslagare i södra Silithus väntar på nyheter om hans senaste expedition.",h="Brann Bronzebeard är den yngste brodern till King Magni och Muradin, som tros vara död.",kw={"ahn'qiraj","brann","bronzebeard","explorers league","frankal","glibb","natalia mar'alith","rutgar","the scarab wall","silithus"},ang={["faction:Alliance"]="Branns expeditioner bidrar direkt till Alliansens kunskap och arkiv, men hans vana att försvinna spårlöst driver ofta Ironforges ledning till vansinne.",["race:Dwarf"]="Som King Magnis yngste bror personifierar Brann dvärgarnas passion för att gräva i rötterna till sitt titaniska arv."},sec={{t="En kunglig vandrare",b="Medan hans äldste bror Magni styr Ironforge från tronen och Muradin tjänstgjorde vid fronten, gav sig Brann ut i vildmarken. Han var en veteran från det andra kriget. Men i fredstid riktade han sin kraftfulla fysik mot att utforska det bortglömda förflutna. Som ledare för Explorers' League kartlade Brann väldiga områden av Eastern Kingdoms, från Elwynn Forest till Zul'Gurubs otämjda djungler, innan han vände blicken över Stora havet mot det forntida Kalimdors mysterier."},{t="Problem i Silithus",b="Brann drogs söderut av rapporter från Cenarion Circle om den gamle guden C'Thun och den slumrande qiraji-svärmen. Tillsammans med upptäcktsresandena Rutgar Glyphshaper och Frankal Stonebridge slog han upp Bronzebeard Encampment i södra Silithus. En tragedi inträffade när prästinnan Natalia Mar'alith, vansinnig av de viskande fasorna i den skiftande sanden, angrep lägret. När Brann vägrade hennes krav på att leda dem tillbaka in i Hive'Regal blev hon rasande och gick till anfall. Brann, hans besättning och hans tama apa Glibb lyckades nätt och jämnt slå tillbaka henne."},{t="Bortom The Scarab Wall",b="I stället för att dra sig tillbaka efter den skräckinjagande attacken blev den oförvägne arkeologen besatt av att ta sig in i det förseglade riket bakom The Scarab Wall. Brann upptäckte en dold underjordisk tunnel som helt kringgick den forntida barriären och begav sig ensam in. Han lämnade Glibb i expeditionens vård och gav strikta skriftliga order om att apan skulle få gott om mat, vatten och kärleksfulla kramar. Hans följeslagare är fortfarande strandsatta i södra Silithus och väntar desperat på besked inifrån silithidernas kupor."}},faq={{q="Vem är Brann Bronzebeard?",a="Han är den yngste brodern till King Magni Bronzebeard av Ironforge och en av grundarna av dvärgarnas Explorers' League, där han är en drivande kraft. Brann sitter inte i rådskammare. Han är en legendarisk arkeolog och kartograf som färdas genom Azeroths farligaste gränstrakter för att hitta titanartefakter och förlorade civilisationer.",al={"vem är brann","branns historia","brann bronzebeards bakgrund"}},{q="Var är Brann Bronzebeard just nu?",a="Hans spår leder till Silithus, där Rutgar Glyphshaper och Frankal Stonebridge håller till vid Bronzebeard Encampment. De kan ha information om hans senaste expedition.",al={"branns plats","var hittar man brann","var är brann i silithus"}},{q="Vad hände med lägret i Silithus?",a="Rutgar Glyphshaper och Frankal Stonebridge har oroande nyheter om expeditionen. Prata med dem för att få veta vad som hände i lägret.",al={"vad hände vid bronzebeard encampment","vem angrep branns läger","natalias attack mot brann"}},{q="Vem är Glibb?",a="Glibb är Brann Bronzebeards följeslagare, en apa som stannar hos upptäcktsresandena vid Bronzebeard Encampment i Silithus.",al={"glibb apan","branns apa","branns husdjur"}},{q="Deltog Brann i det andra kriget?",a="Ja. Brann är veteran från det andra kriget, men i fredstid riktade han sin styrka mot att utforska det bortglömda förflutna.",al={"brann andra kriget","var brann med i alliansens armé","brann och muradin kriget"}},{q="Varför är Brann intresserad av Silithus?",a="Brann drogs till öknen av viskningar från Cenarion Circle om den gamle guden C'Thun, titanernas historia och det instängda qiraji-riket. Det fick honom att söka en väg förbi den förseglade The Scarab Wall så att han kunde undersöka ruinerna på plats.",al={"varför for brann till silithus","branns syfte i silithus","brann c'thun"}}},fp="17,421,16.500.0,19.540.1,22.520.1,25.329.0,37.169.0,38.138.0,13.109.0,34.123.0,36.225.0"}
P.entries["npc:branstock-khalder"] = {n="Branstock Khalder",s="Branstock Khalder är prästtränaren vid Anvilmar i Coldridge Valley. Vänlig och jordnära lär han nyblivna dvärgpräster om det Heliga ljuset, samtidigt som han håller ett vakande öga på det växande hotet från troggs utanför.",h="Branstock Khalder är prästtränaren vid Anvilmar i Coldridge Valley.",kw={"anvilmar","branstock","coldridge","dun morogh","khalder","ljus","präst","tränare"},ang={["class:Priest"]="För dvärgpräster är Branstock Khalder den första andliga vägledaren de möter. Han hjälper dig att tyda din första heliga runa och introducerar dig till det Heliga ljusets försvars- och läkekonster.",["race:Dwarf"]="Branstock visar den praktiska, jordnära hängivenhet som är typisk för Ironforges dvärgar. Han förenar vördnad inför ljuset med stark motståndskraft mot kylan och de lokala troggangreppen."},sec={{t="En vägledande hand i Coldridge",b="I Anvilmars livliga sal är Branstock Khalder en tålmodig mentor för blivande präster som ger sig ut på sin andliga resa. Han är en lättsam dvärg med djup hängivenhet till ljuset och hjälper nya akolyter att bemästra sina första böner och heliga runor. Hans främsta uppgift är andlig undervisning, men Branstock är väl medveten om dalens växande faror, framför allt den aggressiva trogginvasionen som hotar de lokala bergsfolken. När en novis visar tillräcklig behärskning av ljuset skickar han dem genom Coldridge Pass för att söka vidare vägledning hos sin överordnade, Maxan Anvol, i Kharanos."}},faq={{q="Vem är Branstock Khalder?",a="Branstock Khalder är en dvärgisk prästtränare i Anvilmar, utposten där äventyret börjar i Coldridge Valley. Han lär blivande präster om det Heliga ljusets vägar och ger andliga råd till försvarare som möter dalens svårigheter.",al={"branstocks historia","vem är branstock","prästtränare i anvilmar"}},{q="Vart skickar Branstock sina elever härnäst?",a="När de unga prästerna har finslipat sina första förmågor och hjälpt till med problemen i Coldridge Valley skickar Branstock dem genom Coldridge Pass till Kharanos, där de får söka upp hans överordnade, Father Maxan Anvol.",al={"vart går jag efter branstock","branstocks nästa uppdrag","prästernas väg från anvilmar"}},{q="Vad oroar Branstock sig för i Coldridge Valley?",a="Utöver sina andliga plikter oroar sig Branstock djupt för den senaste trogginvasionen som sprider sig genom Coldridge Valley. Han inser att ljusets kraft behövs snabbt för att läka sår och stärka dalens försvar.",al={"problem i anvilmar","vad branstock oroar sig för","trogg hot i coldridge"}},{q="Vad säger han till dem som inte är präster?",a="Även om du följer en annan väg ger Branstock ett enkelt råd: vänd aldrig ljuset ryggen. Han påminner förbipasserande om att tron en dag kan vara det enda som räddar deras liv.",al={"branstocks citat","branstocks skvallertext"}}},fx={ac45145a={q="Vems sida står Branstock Khalder på?",a="Branstock står stadigt på Ironforges och Alliansens sida. Som präst av det Heliga ljuset ägnar han sig åt att vägleda unga dvärgpräster och skydda Coldridge Valley mot yttre hot.",al={"branstock khalders fraktion","vem tjänar branstock khalder","branstock khalders lojalitet"}},["48c1936a"]={q="Vad vill Branstock Khalder?",a="Branstock vill undervisa unga akolyter i det Heliga ljusets vägar och se till att de har styrkan att överleva utanför Anvilmar. Han vill också att det lokala hotet från troggerna hejdas innan de helt övermannar Coldridge Valley.",al={"branstock khalders mål","vad vill branstock","branstock khalders syfte"}},["0b38c258"]={q="Varför är Branstock Khalder i Coldridge Valley?",a="Branstock är stationerad i Anvilmar för att välkomna nyvaknade präster och lära dem grundläggande böner och heliga läror. Från denna stillsamma utpost förbereder han unga noviser innan han skickar dem vidare till Kharanos.",al={"varför är branstock khalder här","branstocks syfte i anvilmar","varför är branstock i anvilmar"}},["15965ad4"]={q="Vem är Branstock Khalder knuten till?",a="Branstock tjänar under prästen Maxan Anvol, sin överordnade som är stationerad längre ner på berget i Kharanos. Han samarbetar också nära med lokala försvarare som Sten Stoutarm för att hitta lovande kandidater bland de nya rekryterna.",al={"branstock khalders kontakter","vem rapporterar branstock till","branstock khalders överordnade"}}},fp="17,140,27.331.0,25.149.0,44.124.0,54.120.0,32.93.0"}
P.entries["npc:brave-moonhorn"] = {n="Brave Moonhorn",s="Brave Moonhorn är en tauren-spejare stationerad högst upp på The Great Lift vid The Barrens södra gräns. Från denna klippa håller han utkik över ingången till Thousand Needles och varnar resenärer för farorna i området.",h="Brave Moonhorn är en tauren-spejare stationerad högst upp på The Great Lift vid The Barrens södra gräns.",kw={"brave moonhorn","centaur","cliffwatcher longhorn","freewind post","the great lift","grimtotem","thousand needles"},ang={["faction:Horde"]="Moonhorn tjänar som en tidig vaktpost för Horde och visar nyanlända i ravinen mot säkerheten och Freewind Posts befästa höjder.",["race:Tauren"]="Moonhorns djupa misstro mot Grimtotem speglar den pyrande konflikten och misstron mellan traditionella stammar som är lojala mot Cairne Bloodhoof och den hemlighetsfulla Grimtotem-klanen."},sec={{t="Väktare vid hissen",b="Brave Moonhorn står vakt högt ovanför Thousand Needles branta stup, där de norra slätterna möter ravinlandet. Hans främsta uppgift är att hålla utkik efter hot som rör sig på ravinens botten nedanför, särskilt fientliga centaurklaner. Den som vill ta sig ner i ravinerna stöter ofta på honom först och får viktiga varningar innan de går ut på The Great Lifts väldiga plattformar."},{t="Oroande skuggor",b="Utöver det ständiga hotet från kringströvande centaur hyser Moonhorn djupa farhågor om sina medtauerner från Grimtotem-stammen. Han uppmanar resande allierade i Horde att hålla sig på avstånd från dem och påpekar att deras beteende kring Thousand Needles blir alltmer oberäkneligt och misstänkt. För att säkra områdets försvar skickar han kurirer till Freewind Post med varningar till Cliffwatcher Longhorn."}},faq={{q="Vem är Brave Moonhorn?",a="Brave Moonhorn är en taurenkrigare och spejare med uppgift att bevaka vägen till The Great Lift, som förbinder The Barrens med Thousand Needles. Han håller koll på fiendens aktivitet och varnar förbipasserande resenärer för faror i närheten.",al={"brave moonhorns roll","vem är moonhorn","tauren-vakt vid hissen"}},{q="Varför varnar Moonhorn för Grimtotem?",a="Moonhorn har märkt att Grimtotem-klanen beter sig märkligt och oförutsägbart i den omgivande ravinen. Trots att de formellt tillhör taurenfolket gör deras aggressiva slutenhet dem opålitliga för vakterna som upprätthåller ordningen längs leden.",al={"varning för grimtotem","varför undvika grimtotem","moonhorn och grimtotem"}},{q="Vilket meddelande vill han få fram till Freewind Post?",a="Han bär med sig brådskande varningar om den ökande centauraktiviteten i Thousand Needles och ber pålitliga Horde-budbärare att vidarebefordra informationen till Cliffwatcher Longhorn vid Freewind Post.",al={"meddelande till freewind post","vad är moonhorns meddelande","lore om meddelande till freewind post"}},{q="Var finns Brave Moonhorn?",a="Han står nära platåns kant högst upp på The Great Lift, precis vid gränsen mellan The Barrens och Thousand Needles.",al={"var finns moonhorn","brave moonhorns plats","vakt vid the great lift"}}},fx={["9347caaf"]={q="Vems sida står Brave Moonhorn på?",a="Brave Moonhorn tjänar Thunder Bluff och Horden. Han är stationerad högst upp på The Great Lift mellan The Barrens och Thousand Needles. Där håller han uppsikt över gränsen och visar resande Horde-äventyrare säkert ner i ravinen.",al={"är brave moonhorn med i horden","brave moonhorns fraktion","vem tjänar moonhorn"}},ff589928={q="Varför är Brave Moonhorn stationerad vid The Great Lift?",a="Moonhorn är placerad vid stupet i Thousand Needles för att vakta nedfarten och hålla uppsikt över faror i närheten. Härifrån bevakar han centaurernas aggression och Grimtotem-klanens oroliga rörelser, så att resenärer som tar sig ner i ravinen får ordentliga varningar.",al={"varför är moonhorn här","vad gör moonhorn vid hissen","varför är brave moonhorn vid the great lift"}},["4ac94a87"]={q="Vem är Brave Moonhorn knuten till?",a="Moonhorn lyder under taurenledarna i Thunder Bluff och samarbetar nära med Cliffwatcher Longhorn vid Freewind Post. När faror uppstår längs ravinens leder är det befälhavaren Longhorn som han förlitar sig på för att ta emot sina spaningsrapporter.",al={"moonhorns allierade","vem rapporterar moonhorn till","brave moonhorns kontakter"}}},fp="14,230,20.436.0,14.403.0,22.214.0,45.239.0,53.188.0,32.139.0"}
P.entries["npc:brewmaster-drohn"] = {n="Brewmaster Drohn",s="Ovanför Ratchets hamnar sköter Brewmaster Drohn sitt bryggeri. Orchen bor strax uppför backen från hamnen och gör starka drycker med metoder som är knutna till den kringvandrande pandaren Chen Stormstout. Resenärer som hittar övergivna tunnor runtom i Kalimdor skickas till Dohns veranda.",h="Ovanför Ratchets hamnar sköter Brewmaster Drohn sitt bryggeri.",kw={"the barrens","bryggmästare","chen stormstout","drohn","ratchet","trogg ale"},ang={["faction:Alliance"]="Som alliansäventyrare bör du veta att Steamwheedle skyddar Drohn i Ratchet. Anfall honom, så vänder sig de lokala goblinmyndigheterna mot dig.",["profession:Cooking"]="Om du ägnar dig åt matlagning ligger Dohns skicklighet i att blanda sällsynta växter och djur till fina drycker i öknen.",["race:Orc"]="Som ork kan du se Dohns bryggande som ett sätt att förvandla freden i Durotar och The Barrens till ett hantverk, till skillnad från fästningarna som många krigare byggde efter att ha följt Thrall till Kalimdor."},sec={{t="En mästare i Ratchet",b="Brewmaster Drohn brygger hemma på höjden ovanför Ratchets goblinhamn. I stället för att ägna sig åt strid har orchen valt bryggandet som sitt hantverk. Han lever i lugn och ro i den neutrala fristad som Gazlowes Steamwheedle Cartel grundade. Många orcher föredrar grovt öl eller enkel sprit, men Drohn arbetar med sällsynta ingredienser, noggrant balanserade smaker och metoder som sällan används bland hans folk."},{t="Pandarenbanden",b="Brewmaster Drohn lärde sig brygga av en mentor som hade studerat för Chen Stormstout, den kringvandrande pandaren som stred vid Rexxars och Hordens sida när Durotar grundades. Chen lärde också Drohn att göra Trogg Ale. När resenärer hittar Chens övergivna tunnor ute i vildmarken är Drohn den enda lokala experten som kan identifiera ingredienserna och återskapa vandrarens starka brygder."}},faq={{q="Vem är Brewmaster Drohn?",a="Brewmaster Drohn brygger i Ratchet i The Barrens. Orchen är känd för sina exotiska öl och banden till den kringvandrande pandaren Chen Stormstouts bryggtraditioner.",al={"drohns bakgrund","vem är drohn","bryggmästare i ratchet"}},{q="Hur känner Drohn Chen Stormstout?",a="Drohn lärde sig av en mentor som Chen Stormstout hade lärt att brygga Stormstout. Chen lärde senare Drohn att göra Trogg Ale.",al={"band till chen","hur känner han chen","drohn och chen"}},{q="Vad ska jag göra om jag hittar Chens tomma tunna?",a="Ta Chens Empty Keg till Brewmaster Drohn i Ratchet. Han känner igen Chens hantverk och skickar dig för att hitta de sällsynta lokala ingredienser som behövs för att återskapa brygden.",al={"chens tomma tunna","hittade tom tunna","tunnuppdrag"}},{q="Tillhör Brewmaster Drohn Horden?",a="Ja. Drohn är en ork i Horden, men han bor och brygger i Ratchet, en neutral goblinhamn. Om du anfaller honom försämras en alliansäventyrares anseende hos Ratchet och Steamwheedle Cartel.",al={"tillhör drohn horden","är drohn neutral","drohns fraktion"}},{q="Vilka drycker gör Drohn?",a="Drohn gör starka brygder, däribland Trogg Ale och Chen Stormstouts namngivande Stormstout. De kräver betar, körtlar och andra delar från bestar runtom i The Barrens.",al={"drohns recept","drohns brygder"}},{q="Var ligger Drohn exakt?",a="Hitta Drohn utanför sitt hus på höjden med utsikt över Ratchet, strax nordväst om huvudhamnen i The Barrens.",al={"drohns plats","var är drohn","hitta brewmaster drohn"}}},fx={["2bb5b883"]={q="Vad vill Brewmaster Drohn?",a="Drohn ägnar sig åt att bemästra sitt hantverk och förfina exotiska, kraftfulla recept. När resenärer hittar tomma tunnor som den kringvandrande pandaren Chen Stormstout lämnat efter sig, söker Drohn efter sällsynta ingredienser i The Barrens, som savannlejonsbetar, plainstrider-njurar och ett Thunder Lizard Horn. Han vill återskapa de legendariska brygderna och hedra bryggartraditionerna han fått lära sig.",al={"vad vill drohn","drohns mål","varför hjälpa drohn"}},e385fb6c={q="Varför är Brewmaster Drohn i Ratchet?",a="Drohn driver sitt destilleri i utkanten av Ratchet och drar full nytta av den livliga goblinhamnen. Stadens neutralitet och livliga handel lockar resenärer, exotiska varor och nyfikna gäster från hela Azeroth ända fram till hans dörr. Där får han både en ivrig marknad för sitt öl och tillgång till The Barrens vildmark, där han hittar ingredienser till brygderna.",al={"varför är drohn här","varför är drohn i ratchet","varför är drohn där"}}},fp="16,264,32.403.0,23.386.0,24.161.0,36.128.0,44.162.0,43.191.0,36.171.0,31.110.0"}
P.entries["npc:brewmeister-bilger"] = {n="Brewmeister Bilger",s="Brewmeister Bilger är en berusad dvärgbryggare som bor i källaren under värdshuset i Southshore i Hillsbrad Foothills. Han fördriver timmarna med att smaka på starka spritsorter och vänta på leveranser från avlägsna länder.",h="Brewmeister Bilger är en berusad dvärgbryggare som bor i källaren under värdshuset i Southshore i Hillsbrad...",kw={"bilger","brewmeister bilger","hillsbrad foothills","värdshuskällare","mackreel","southshore"},ang={["faction:Alliance"]="Bilger hör hemma i källaren under värdshuset i Southshore och är en av dvärgarna som bor bland människorna i denna hårt prövade alliansstad.",["race:Dwarf"]="Bilger visar att dvärgarnas kärlek till starka drycker frodas även i en hamnstad bland människor, långt från Ironforge."},sec={{t="Livet i källaren",b="Bilger tillbringar dagarna med att vandra runt i den svala källaren under värdshuset i Southshore, hicka och leta efter de starkaste brygderna Azeroth kan erbjuda."},{t="Smak för starka importvaror",b="Trots sin ständiga berusning är Bilger fortfarande en kräsen spritkännare. Han har smak för kraftig dvärgisk månskenssprit och starka likörer från södern, och tar gärna emot specialbrygder som månskensspriten Foggy MacKreel skickar till honom från Thandol Span."}},faq={{q="Var hittar jag Brewmeister Bilger?",a="Brewmeister Bilger finns en trappa ner i källaren under värdshuset i Southshore, alliansens hamnstad i Hillsbrad Foothills.",al={"bilgers plats","var finns bilger","dvärg i southshores källare"}},{q="Vilka uppdrag berör Brewmeister Bilger?",a="Bilger tar emot sällsynt sprit som levereras från Wetlands, däribland starka spritsorter som MacKreel's Moonshine, som skeppas norrut till Southshore.",al={"bilgeruppdrag","mackreel's moonshine-uppdrag"}}},fx={["0436bf77"]={q="Vem är Brewmeister Bilger?",a="Brewmeister Bilger är en dvärgisk bryggare som tillbringar dagarna med att dricka i källaren på Southshores värdshus. Han hickar sig igenom starka drycker medan han väntar på hembränt som hans vänner, däribland Foggy MacKreel, är skyldiga honom.",al={"vem är bilger","brewmeister bilgers identitet","vem är brewmeister bilger"}},["29798063"]={q="Vems sida står Brewmeister Bilger på?",a="Bilger står på Alliansens och Southshores sida. Han är en dvärg från Ironforge och bor i lugn och ro bland lokalbefolkningen, även om han föredrar källarens tunnor framför kommunala plikter.",al={"bilgers fraktion","är bilger med i alliansen","vems sida står bilger på"}},["5541902b"]={q="Varför är Brewmeister Bilger här?",a="Bilger har gjort källaren på Southshores värdshus till sitt hem. Han tillbringar dagarna bland faten, med sina starka drycker och hembräntet som vänner som Foggy MacKreel är skyldiga honom.",al={"varför är bilger i southshore","vad gör bilger här","varför är brewmeister bilger här"}}},fp="18,149,18.128.0,26.232.0,36.115.0,39.142.0"}
P.entries["npc:brine"] = {n="Brine",s="På Blackthorn Ridge vägleder Brine schamanlärlingar mot vattnets andar. Den här orkschamanen lär dem att tala med tidvattnet och förtjäna sin Water Totem.",h="På Blackthorn Ridge vägleder Brine schamanlärlingar mot vattnets andar.",kw={"the barrens","blackthorn ridge","brine","call of water","schaman","tarren mill","water totem"},ang={["class:Shaman"]="Brine vägleder dig genom prövningar av uthållighet och ande innan du kan tala med vatten och göra anspråk på din Water Totem.",["faction:Horde"]="Brine är veteran från krigen i Hillsbrad och tjänar Horden genom att föra elementens andliga arv vidare till nya generationer."},sec={{t="Eremit på åsen",b="Brine bor på en kulle i norra Blackthorn Ridge, långt från handelsplatserna i The Barrens. Torra savanner omger henne, men hon har vigt sitt liv åt att förstå vatten. Schamaner i Horden söker hennes visdom efter att ha bemästrat jord och eld. Hon lär att vatten kräver tålamod och perspektiv, egenskaper som få förstår lika djupt som hon."},{t="Minnen från Eastern Kingdoms",b="I sin ungdom marscherade Brine med sina orkkamrater genom Hillsbrad Foothills och stred mot mänskliga bosättningar. Under fälttåget kom hon till Tarren Mill och fann en enkel brunn som fick sitt vatten från en frisk källa. Brunnen stannade kvar i hennes minne som ett tecken på liv mitt i förödelsen. Den stärkte en lärdom hon fått som barn: även i den djupaste sorgen kan man finna en liten strimma hopp."},{t="Vattnets kallelse",b="Brine prövar blivande schamaner genom pilgrimsfärder där de ska samla rena vattendroppar från olika källor. Hennes prövningar lär dem att vatten kan vara milt men ändå obevekligt. I hennes ritualer samtalar schamaner med elementandar och binder vattnets helande kraft till sina totemiska fokusföremål."}},faq={{q="Vem är Brine?",a="Brine är en erfaren orkschaman som bor ensam på en kulle i norra Blackthorn Ridge, i södra The Barrens. Hon vägleder lärlingar som söker gemenskap med vattenandar.",al={"brines bakgrund","vem är brine","ork på blackthorn ridge"}},{q="Varför bor en vattenschaman i en öken?",a="The Barrens är torrt, men Brines ensamhet låter henne samtala djupt med elementen, långt från bosättningarnas larm.",al={"varför i the barrens","varför bor brine i öknen"}},{q="Vad har Brine för koppling till Tarren Mill?",a="För många år sedan stred Brine sida vid sida med Hordens krigare i Hillsbrad Foothills och tog sig till Tarren Mill. Där fann hon en liten brunn med rent källvatten, ett bestående tecken på liv och hopp mitt i krigets ruiner.",al={"brunnen i tarren mill","brine hillsbrad","brines historia"}},{q="Vilken roll har Brine i schamanernas träning?",a="Brine vägleder lärlingar genom Call of Water-prövningarnas olika steg. Hon skickar dem att samla rent vatten från olika källor och lär dem ödmjukhet och uthållighet innan de får den insikt som krävs för deras Water Totem.",al={"brines schamanuppdrag","hur får man water totem","call of water brine"}},{q="Var finns Brine?",a="Brine bor högst uppe på en brant klippa i norra Blackthorn Ridge, i södra The Barrens, strax norr om Razorfen Kraul.",al={"brines plats","var finns brine","hitta brine i the barrens"}},{q="Vilken filosofi vägleder hennes undervisning?",a="Brine lär att hopp och förnyelse går att finna även i smärta och sorg. Vatten står för liv och uthållighet genom svåra prövningar.",al={"brines filosofi","vattnets lärdomar"}}},fx={["452ad9e3"]={q="Vems sida står Brine på?",a="Brine är lojal mot Horden och delar med sig av sin djupa andliga visdom till blivande Horde-schamaner som vill bemästra elementen. Hon bor avskilt bland kullarna i södra The Barrens i stället för i en livlig fästning, men är en viktig mentor för de schamantraditioner som Thralls nya rike vårdar.",al={"brines fraktion","är brine med i horden","vem tjänar brine"}},a90c6b58={q="Vad vill Brine?",a="Brine vill vägleda blivande schamaner till förståelse för vattnets dubbla natur: dess stilla, livgivande klarhet och dess ursinniga, obevekliga kraft. I stället för att bara skänka dem kraft kräver hon att resenärer ger sig ut på krävande pilgrimsfärder till rent vatten i Kalimdor och Eastern Kingdoms. Där ska de lära sig uthållighet och gemenskap med elementandar.",al={"brines mål","vad gör brine","varför hjälpa schamaner"}}},fp="5,162,19.350.0,32.405.0,17.266.1,13.174.0,41.120.0,42.205.0,45.222.0,31.114.0,37.135.0"}
P.entries["npc:brock-stoneseeker"] = {n="Brock Stoneseeker",s="Brock Stoneseeker är en dvärgisk gruvinstruktör i bosättningen Thelsamar i Loch Modan. Som ägare av Brock's School of Mining and Surveying lär han nybörjare att utvinna värdefulla malmer och mineraler ur marken.",h="Brock Stoneseeker är en dvärgisk gruvinstruktör i bosättningen Thelsamar i Loch Modan.",kw={"brock stoneseeker","loch modan","gruvtränare","gruvskola","thelsamar"},ang={["profession:Mining"]="Gruvarbetare som färdas genom Loch Modan söker upp Brock Stoneseeker i Thelsamar för att påbörja eller utveckla sin träning i att gräva fram och smälta regionala malmer.",["race:Dwarf"]="För dvärgarna i Khaz Modan är sten och metall grundläggande, vilket gör lärare som Brock till en viktig länk i att bevara Ironforges djupt rotade hantverkstraditioner."},sec={{t="Mästare i gruvdrift och prospektering",b="Brock Stoneseeker driver Brock's School of Mining and Surveying från Thelsamar. I Loch Modans mineralrika kullar är erfarenhet av hacka och blick för geologiska ådror oumbärliga. Brock lär blivande gruvarbetare grunderna i att hitta malmfyndigheter, utvinna råmetaller och kartlägga underjordiska fyndigheter, så att Alliansens hantverkare kan förse Ironforges legendariska smedjor med bränsle."}},faq={{q="Vem är Brock Stoneseeker?",a="Brock Stoneseeker är en gruvtränare av dvärgfolk som håller till i Thelsamar i Loch Modan. Han driver Brock's School of Mining and Surveying och lär hantverkare att utvinna malm och kartlägga råa mineralfyndigheter.",al={"brock stoneseeker","vem är brock","brock thelsamar"}},{q="Var hittar man Brock Stoneseeker?",a="Brock bor i Thelsamar, den största dvärgstaden i Loch Modan, där han driver sin gruvverksamhet nära de lokala hantverkarna.",al={"var finns brock","brock stoneseeker plats","brock karta"}},{q="Vilket yrke lär Brock ut?",a="Han är gruvtränare och lär resande grunderna i att samla grov sten, koppar och annan tidig malm som finns utspridd över landsbygden i Khaz Modan.",al={"vad lär brock ut","brocks tränartyp","gruvtränare thelsamar"}},{q="Vad är Brock's School of Mining and Surveying?",a="Det är Brocks träningsverksamhet i Thelsamar, där blivande prospektörer får lära sig att utvinna mineraler säkert och läsa underjordiska ådror i bergen.",al={"brocks skola","gruvskola thelsamar"}}},fx={["38215f8d"]={q="På vems sida står Brock Stoneseeker?",a="Brock Stoneseeker står fast på Ironforge-dvärgarnas och Grand Alliances sida. Från den fridfulla bosättningen Thelsamar i Loch Modan tjänar han bergsfolket och resenärerna i Khaz Modan genom att utbilda skickliga gruvarbetare som kan leta malm i det karga dvärglandet.",al={"brock stoneseekers fraktion","tillhör brock stoneseeker alliance","vem tjänar brock stoneseeker"}},["53fa3834"]={q="Varför är Brock Stoneseeker här?",a="Brock bor i Thelsamar och driver Brock's School of Mining and Surveying. Klipporna och bergen runt Loch Modan är rika på råsten och mineralådror, vilket gör platsen idealisk för att utbilda blivande gruvarbetare och skicka ut dem bland de omgivande bergen.",al={"varför är brock stoneseeker i thelsamar","varför är brock här","vad förde brock till loch modan"}},["7d1f98e6"]={q="Vad vill Brock Stoneseeker?",a="Brock vill lära nykomlingar dvärgarnas grundläggande gruvkonst och hedra skolans mest hängivna elever. Han vill se till att prospektörer ger sig ut i Khaz Modans karga vildmarker välutrustade för att hitta rik malm och kartlägga landet.",al={"vad vill brock stoneseeker","brock stoneseekers mål","vad vill brock"}}},fp="17,162,30.348.0,25.165.0,37.133.0,33.149.0,47.179.0"}
P.entries["npc:bromos-grummner"] = {n="Bromos Grummner",s="Bromos Grummner är en paladintränare för dvärgar, stationerad i Anvilmar i Coldridge Valley. Han vägleder unga dvärgkrigare i heligt ljus och predikar orubblig tro på det Heliga Ljuset och det starka bandet mellan dvärgar och människor i Knights of the Silver Hand.",h="Bromos Grummner är en paladintränare för dvärgar, stationerad i Anvilmar i Coldridge Valley.",kw={"anvilmar","bromos","coldridge","dun morogh","grummner","paladin","silver hand","tränare"},ang={["class:Paladin"]="För dvärgpaladiner är Bromos deras allra första andliga mentor och introducerar dem till Silver Hands heliga plikter.",["race:Dwarf"]="Bromos förkroppsligar den bestående traditionen bland dvärgar som vigt sig åt Ljuset och strider sida vid sida med sina mänskliga allierade."},sec={{t="Ett ljus i Coldridge",b="I Anvilmars stadiga stenhall välkomnar Bromos Grummner dvärgnoviser som söker sig till det Heliga Ljusets disciplin. Med självsäkerhet och beslutsamhet lär han unga paladiner stridsriter och heliga böner. Utöver stridens grunder betonar Bromos sammanhållning och påminner sina elever om att Knights of the Silver Hand förenar Ironforge och Alliansens mänskliga kungariken i ett rättfärdigt syfte."}},faq={{q="Vem är Bromos Grummner?",a="Bromos Grummner är paladintränaren i Anvilmar, som ligger i Coldridge Valley i Dun Morogh. Han ger nya dvärgpaladiner grundläggande träning, besvärjelser och andlig vägledning.",al={"vem är bromos","bromos grummners bakgrund","paladintränare i anvilmar"}},{q="Vilken orden representerar Bromos?",a="Bromos representerar Knights of the Silver Hand. Han betonar aktivt vikten av bandet mellan människor och dvärgar, som smitts under den heliga ordens fana.",al={"bromos och silver hand","är bromos med i silver hand"}},{q="Vad lär han nya rekryter?",a="Han lär noviser paladinklassens grundläggande stridskonster och gudomliga besvärjelser. Han ger dem tidiga prövningar för att visa sin hängivenhet till Ljuset och sin beredskap att skydda Dun Morogh.",al={"bromos uppdrag","vad gör bromos grummner"}}},fx={["73c3e4de"]={q="På vems sida står Bromos Grummner?",a="Bromos står fast på Ironforges och Grand Alliances sida. Som hängiven medlem av Knights of the Silver Hand värdesätter han det starka bandet mellan dvärgar och människor högt. Han tror att deras gemensamma tro på Holy Light är avgörande för att hålla deras riken samman.",al={"bromos grummners fraktion","bromos och alliance","vem slåss bromos för"}},["830a5136"]={q="Varför är Bromos Grummner här i Coldridge Valley?",a="Bromos är stationerad i Anvilmar för att undervisa nya dvärgpaladiner som hörsammat Holy Lights kallelse. Med kylan som kryper närmare och lokala troggar som hotar ser han till att varje blivande försvarare lär sig att använda sin stridsförmåga och rättfärdiga välsignelser i folkets tjänst.",al={"varför är bromos i anvilmar","bromos grummners syfte","vad gör bromos här"}},["33b2371f"]={q="Vad vill Bromos Grummner?",a="Bromos vill fostra en disciplinerad och orubblig generation dvärgpaladiner. Han vill lära sina elever att bemästra Lights heliga krafter och att hängivet värna den heliga alliansen mellan dvärgar och människor inom Silver Hand.",al={"vad vill bromos","bromos mål","bromos motiv"}}},fp="15,215,21.238.0,23.157.0,33.137.0,32.179.0"}
P.entries["npc:brother-joshua"] = {n="Brother Joshua",s="I Stormwind vägleder Brother Joshua dem som kommer till Cathedral of Light för att lära sig den Heliga Ljusets vägar. Han tränar novispräster i att hela sår och stärka sina allierade.",h="I Stormwind vägleder Brother Joshua dem som kommer till Cathedral of Light för att lära sig den Heliga...",kw={"brother joshua","cathedral of light","heliga ljuset","mänsklig präst","prästtränare","stormwind"},ang={["class:Priest"]="Som präst kan du studera det Heliga Ljuset med Brother Joshua i Stormwind och lära dig nya böner och discipliner allt eftersom du utvecklas.",["faction:Alliance"]="Som medlem i Alliansen hittar du Joshua i Cathedral of Light, i hjärtat av ditt kungarike."},sec={{t="En mentor i katedralen",b="Brother Joshua väntar nära huvudaltaret i Stormwinds Cathedral of Light, redo att undervisa nya trosutövare. Som präst i den Heliga Ljusets kyrka lär han dem läkekonst, skyddande besvärjelser och den koncentration som krävs för att ha kontakt med Ljuset. Unga mänskliga präster som inleder sin tjänst för Alliansen finner en av sina första vägledare i honom."}},faq={{q="Vem är Brother Joshua?",a="Brother Joshua är en mänsklig präst och tränare i den Heliga Ljusets kyrka. Han lär blivande präster deras besvärjelser, ritualer och heliga plikter i Stormwinds Cathedral of Light.",al={"vem är brother joshua","brother joshuas roll","joshua präst"}},{q="Var hittar jag Brother Joshua?",a="Brother Joshua står nära högaltaret längst bak i Cathedral of Light, på Cathedral Square i Stormwind City.",al={"brother joshuas plats","var finns brother joshua","var finns joshua"}},{q="Vilka tjänster erbjuder han?",a="Brother Joshua lär präster nya grader av gudomliga och läkande besvärjelser och kan återställa deras andliga talanger.",al={"vad gör joshua","brother joshua träning","kan joshua träna mig"}}},fx={cce3d5dc={q="På vems sida står Brother Joshua?",a="Brother Joshua tjänar Church of the Holy Light och står fast på Grand Alliances sida. Han är hängiven Lights läror och utför sitt prästerliga uppdrag under valven i Stormwinds Cathedral of Light. Där ger han andlig vägledning och stöd åt sina medborgare och Alliance-resenärer.",al={"brother joshuas lojalitet","brother joshuas fraktion","vem tjänar brother joshua"}},["2e9120b0"]={q="Vad vill Brother Joshua?",a="Brother Joshua vill sprida Holy Lights läror och vägleda lovande akolyter i deras heliga kall. Han ägnar dagarna åt att utbilda nya präster, fördjupa deras gemenskap med Light och se till att Stormwinds trogna står stadigt i oroliga tider.",al={"brother joshuas mål","vad försöker brother joshua göra","brother joshuas syfte"}},["2e708272"]={q="Varför är Brother Joshua här?",a="Brother Joshua är stationerad i Stormwinds Cathedral of Light och utför sina uppgifter nära altaret som prästernas ordinerade lärare. Från denna plats med andlig auktoritet vägleder han dem som kallats till prästämbetet och hjälper besökare som söker Lights visdom.",al={"varför är brother joshua i stormwind","varför är brother joshua i katedralen","varför är brother joshua här"}},["5cfd3f6a"]={q="Vilka har Brother Joshua band till?",a="Brother Joshua tillhör prästerskapet i Church of the Holy Light och arbetar tillsammans med prästerna och paladinerna i Cathedral of Light. Genom sina kyrkliga plikter håller han också kontakt med andra organisationer, som Cenarion Circle, när ömsesidig hjälp behövs.",al={"brother joshuas kontakter","brother joshua och kyrkan","vem lyder brother joshua under"}}},fp="14,177,25.338.0,22.182.0,32.122.0,28.117.0"}
P.entries["npc:brother-kristoff"] = {n="Brother Kristoff",s="På Cathedral Square i Stormwind predikar Brother Kristoff under Uthers staty. Han är en mänsklig präst i Church of the Holy Light och står utomhus nära den stora statyn av Uther the Lightbringer. Han söker praktiska böcker till predikningar om andlig styrka.",h="På Cathedral Square i Stormwind predikar Brother Kristoff under Uthers staty.",kw={"brother kristoff","cathedral of light","cathedral square","ståndaktighet","kristoff","stresses of iron","uther-statyn"},ang={["class:Priest"]="Som präst kan du uppskatta Brother Kristoffs jordnära syn på liturgin. Han hämtar lärdomar från praktiska hantverk för att lära ut de djupare mysterierna kring inre ståndaktighet.",["profession:Blacksmithing"]="Som smed kanske du tycker att det är roande att en Light-präst vänder sig till böcker om järnpåfrestning och metallurgi för att lära prästerskapet om motståndskraft."},sec={{t="Predikanten vid statyn",b="Brother Kristoff tjänar Church of the Holy Light på Cathedral Square, under statyn av Uther the Lightbringer. Han verkar bland invånarna och pilgrimerna som passerar torget, i stället för att stanna inne i Cathedral of Light. Till predikningar som Fortitude of the Spirit hämtar han jämförelser från vardagen. I The Stresses of Iron hittar han ett sätt att förklara hur den dödliga själen uthärdar påfrestningar. Han jämför Holy Lights gåva av inre beslutsamhet med den härdade styrkan hos bearbetad metall."}},faq={{q="Vem är Brother Kristoff?",a="Brother Kristoff är en mänsklig präst och lärd inom Church of the Holy Light. Han arbetar utomhus på Cathedral Square i Stormwind, nära den stora statyn av Uther the Lightbringer.",al={"brother kristoff bakgrund","vem är kristoff","kristoff stormwind"}},{q="Vad gör Brother Kristoff på Cathedral Square?",a="Brother Kristoff förbereder predikningar om Light och tron. Han arbetar på en predikan om Fortitude of the Spirit och söker hänvisningar i böcker om metallurgi för att förklara andlig motståndskraft.",al={"kristoffs uppgift","kristoffs roll","varför står brother kristoff utomhus"}},{q="Varför behöver Brother Kristoff en bok om järn?",a="Brother Kristoff söker The Stresses of Iron till sin predikan om ståndaktighet. Han använder järn under påfrestning som en jordnära jämförelse för hur hängivenhet till Holy Light stärker den dödliga anden mot motgångar.",al={"the stresses of iron","bok om att tala om ståndaktighet","varför vill kristoff ha metallurgi"}}},fx={["610da828"]={q="På vems sida står Brother Kristoff?",a="Brother Kristoff tjänar Church of the Holy Light och Alliance. Som broder i prästerskapet är han hängiven Holy Light och Stormwinds invånares andliga vägledning. Han står trofast under skuggan av Cathedral of Light.",al={"brother kristoffs fraktion","vem tjänar brother kristoff","brother kristoff och alliance"}},["8237c000"]={q="Vilka har Brother Kristoff band till?",a="Brother Kristoff tillhör prästerskapet i Church of the Holy Light och har sin bas i Cathedral of Light i Stormwind. Tillsammans med sina präst- och paladinkollegor i Cathedral Square tar han hand om rikets invånares och försvarares andliga behov.",al={"brother kristoffs kontakter","brother kristoff och kyrkan","vilka band har brother kristoff"}}},fp="16,144,24.495.0,24.179.0,50.180.0,49.186.0"}
P.entries["npc:brother-neals"] = {n="Brother Neals",s="I Northshire Abbey håller Brother Neals uppsikt över mat- och dryckesförråden. Han övervakar leveranserna och provsmakar vin från den lokala vingården.",h="I Northshire Abbey håller Brother Neals uppsikt över mat- och dryckesförråden.",kw={"brother neals","elwynn forest","grape manifest","northshire abbey","northshire valley","vingård","vin"},ang={["profession:Cooking"]="Som den som sköter klostrets förråd och spritdrycker har Brother Neals en roll med anknytning till kokkonsten."},sec={{t="Källarmästare",b="Brother Neals ser till att Northshire Abbey har mat och dryck från sina rum i det övre klocktornet. Han följer druvförteckningarna från Northshire Vineyards och smakar på vinet för att kontrollera dess kvalitet. Han håller också uppsikt över leveranserna som anländer från fälten runt dalen."}},faq={{q="Vem är Brother Neals?",a="Brother Neals hör till Northshire Abbey och sköter dess förråd av mat, dryck och vin åt prästerskapet och rekryterna i dalen.",al={"brother neals","neals","vem är neals"}},{q="Var finns Brother Neals?",a="Brother Neals håller till i det översta rummet i Northshire Abbey. Gå uppför stentrapporna inne i stora salen för att nå den stillsamma kammaren nära tornets topp.",al={"var är brother neals","brother neals plats","hitta neals"}},{q="Vilken roll har han i vingården?",a="Brother Neals håller koll på druvskördarna och vinsändningarna från den närbelägna Northshire Vineyard. Han ägnar tid åt att provsmaka årgången och föra räkenskaperna.",al={"uppdraget grape manifest","neals vin","vad gör neals"}}},fx={["340be3c1"]={q="På vems sida står Brother Neals?",a="Brother Neals är en trogen medlem av Brotherhood of Northshire och tjänar Northshire Abbey och Stormwinds Grand Alliance. Han utför sina kyrkliga plikter i lugn och ro innanför klostrets murar.",al={"brother neals fraktion","vem tjänar brother neals","brother neals och alliance"}},["0d7c1646"]={q="Vad vill Brother Neals?",a="Brother Neals måste hålla ordentlig räkenskap över Northshires förråd, särskilt vinlagret från den lokala vingården. Han behöver få leveranser och handlingar, som Grape Manifest, direkt till sina rum så att han kan sköta förråden och njuta av ett rikligt smakprov på klostrets årgångsvin.",al={"brother neals grape manifest","vad behöver brother neals"}},bb6478cd={q="Varför är Brother Neals här?",a="Som broder i klostret bor Neals i Northshire Abbeys stilla övre torn och ser efter samfundets mat- och dryckesförråd. Hans tjänst håller honom nära källarens reserver och de räkenskapshandlingar som behövs för att försörja prästerskapet och de nya rekryterna.",al={"varför är brother neals i tornet","varför är brother neals i northshire"}}},fp="13,140,20.243.0,21.117.0,33.161.0,40.137.0"}
P.entries["npc:brother-sarno"] = {n="Brother Sarno",s="I Cathedral of Light i Stormwind City välkomnar Brother Sarno besökare och gudstjänstbesökare. Den mänsklige prästen visar också Alliance-resenärer till Ironforge, där Tinkmaster Overspark behöver hjälp med att återta Gnomeregan.",h="I Cathedral of Light i Stormwind City välkomnar Brother Sarno besökare och gudstjänstbesökare.",kw={"brother sarno","cathedral of light","church of the holy light","stormwind","techbot","tinkmaster overspark"},ang={["class:Priest"]="Som präst kan du se Brother Sarno välkomna besökare i Stormwind och visa den gästfrihet och milda nåd som hör till Holy Light.",["race:Gnome"]="Trots att Brother Sarno tjänar i ett mänskligt gudshus visar han resenärer som vill hjälpa Gnomeregan att återhämta sig vägen mot Ironforge."},sec={{t="En välkomnande röst i katedralen",b="Inne i Cathedral of Light i Stormwind hälsar Brother Sarno pilgrimer och resenärer välkomna vid ingången. Han är broder i Church of the Holy Light och välkomnar dem som söker bön, tröst eller vägledning. Hans vänliga sätt får besökarna att känna sig trygga mitt i katedralens vardag."},{t="Band till Ironforge",b="Brother Sarno hjälper även Alliance utanför katedralen. När han fick höra att Tinkmaster Overspark i Ironforge behövde hjälp med sin förrymda uppfinning Techbot i Gnomeregan, visade Sarno dugliga resenärer vägen mot Dun Morogh. Hans hjälp stöder de gnomer som tvingats lämna sitt hem."}},faq={{q="Var hittar jag Brother Sarno?",a="Brother Sarno står strax innanför huvudingången till Cathedral of Light i Cathedral Square, Stormwind City, till vänster om dörrarna.",al={"sarno plats","var finns brother sarno","katedralens välkomnare"}},{q="Vad gör Brother Sarno?",a="Brother Sarno välkomnar besökare och gudstjänstbesökare i Cathedral of Light. Han visar också resenärer till Tinkmaster Overspark i Ironforge för att hjälpa till med problemen i Gnomeregan.",al={"brother sarnos roll","vad gör sarno"}},{q="Varför skickar en präst från Stormwind folk till Gnomeregan?",a="Prästerskapet fick höra att Tinkmaster Overspark behövde hjälp med att återta förrymd teknologi som Techbot. Brother Sarno visade dugliga kämpar vägen mot Ironforge för att hjälpa till.",al={"sarno gnomeregan uppdrag","varför bryr sig sarno om gnomer"}},{q="Tillhör han någon särskild orden?",a="Brother Sarno är en ordinerad medlem av Church of the Holy Light. Han tjänar under katedralens prelater och Archbishop Benedictus i Stormwind.",al={"sarnos fraktion","brother sarnos orden"}}},fx={["61335d44"]={q="Vem är Brother Sarno?",a="Brother Sarno är en mänsklig präst i Church of the Holy Light, stationerad i den ståtliga Cathedral of Light i Stormwind City. Han står strax innanför huvudentrén på vänster sida och hälsar besökare och pilgrimer välkomna till helgedomen.",al={"vem är brother sarno","brother sarnos identitet","vem är sarno"}},["52c947c9"]={q="På vems sida står Brother Sarno?",a="Brother Sarno är en hängiven tjänare åt Church of the Holy Light och en trogen medlem av Grand Alliance. Han hjälper Stormwinds invånare och upprätthåller nära och samarbetsinriktade band med Alliances allierade, däribland gnomerna och dvärgarna i Khaz Modan.",al={"brother sarnos fraktion","brother sarnos lojalitet","vem tjänar brother sarno"}},["3cc89cc1"]={q="Vad vill Brother Sarno?",a="Utöver att välkomna gudstjänstbesökare till Cathedral of Light håller Brother Sarno utkik efter dugliga Alliance-äventyrare. Han hänvisar hjälpsamma resenärer till Ironforge för att hjälpa Tinkmaster Overspark med en besvärlig mekanisk skapelse vid namn Techbot, djupt inne i den fallna staden Gnomeregan.",al={"vad vill brother sarno","brother sarnos mål","brother sarnos motiv"}},["222a0285"]={q="Varför är Brother Sarno i katedralen?",a="Brother Sarno står nära huvudentrén till Cathedral of Light för att välkomna gudstjänstbesökare, pilgrimer och trötta resenärer som söker tröst. Där håller han också öronen öppna efter problem långt borta och förmedlar kontakt mellan besökande hjältar och allierade i nöd.",al={"varför är brother sarno här","varför är sarno i katedralen"}}},fp="13,200,34.272.0,17.285.0,31.139.0,27.173.0,54.175.0,37.153.0"}
P.entries["npc:brother-wilhelm"] = {n="Brother Wilhelm",s="Bakom smedjan i Goldshire tränar Brother Wilhelm unga paladiner i det Heliga ljuset. Han vägleder dem när de lämnar Northshire Abbey och tar sina första steg in i Elwynn Forest.",h="Bakom smedjan i Goldshire tränar Brother Wilhelm unga paladiner i det Heliga ljuset.",kw={"brother wilhelm","brotherhood of northshire","elwynn forest","goldshire","heliga ljuset","paladintränare","tome of divinity"},ang={["class:Paladin"]="Som paladin finner du din första mentor i Brother Wilhelm efter att ha lämnat Northshire Valley. Han vägleder din utveckling och öppnar vägen till att bemästra Tome of Divinity.",["race:Human"]="Som människa ser du i Brother Wilhelm den Heliga ljusets kyrkas tro, som försvarar Elwynns hjärtland."},sec={{t="En vägledare i Goldshire",b="Brother Wilhelm tränar nya paladiner bakom smedjan i Goldshire. Northshire Valley är en fristad för dem som börjar sin bana i ljuset, men många söker hans vägledning när de ger sig ut i den större skogen. Han lär dem deras heliga plikter när de lämnar klostret och tar sig an arbetet med att skydda riket."},{t="Tome of Divinitys väg",b="Brother Wilhelm vägleder blivande paladiner mot Tome of Divinity. Dess ritual lär de invigda hur tungt det är att offra sig och hur mäktig gudomlig återlösning kan vara. Genom ritualen prövar de sin hängivenhet och lär sig att använda ljuset för att återuppväcka fallna kamrater och skipa rättvisa i hela Stormwindriket."}},faq={{q="Var hittar jag Brother Wilhelm?",a="Brother Wilhelm finns i Goldshire i Elwynn Forest, precis bakom byns smedja. Där tränar och vägleder han blivande paladiner.",al={"wilhelms plats","var finns brother wilhelm","hitta brother wilhelm"}},{q="Vilka tjänster erbjuder Brother Wilhelm?",a="Brother Wilhelm tränar unga paladiner i nya besvärjelser, stridsvälsignelser och heliga tekniker medan de färdas genom Elwynn Forest.",al={"vad gör wilhelm","paladintränare i goldshire","brother wilhelm tränare"}},{q="Tillhör Brother Wilhelm Brotherhood of Northshire?",a="Brother Wilhelms titel och nära band till Northshire Abbey tyder på att han har kopplingar till Brotherhood of Northshire. Från Goldshire tjänar han den Heliga ljusets kyrka och Stormwindriket.",al={"tillhör wilhelm brotherhood of northshire","wilhelms fraktion","vem tjänar brother wilhelm"}},{q="Vilken roll har han i uppdraget Tome of Divinity?",a="Brother Wilhelm vägleder mänskliga paladiner som har blivit starkare mot Tome of Divinity och dess prövningar, som leder till den heliga uppståndelsevälsignelsen.",al={"tome of divinity wilhelm","uppdrag om uppståndelse wilhelm","paladinuppdrag i goldshire"}}},fx={["0af03050"]={q="Vem är Brother Wilhelm?",a="Brother Wilhelm är en mänsklig paladinmentor stationerad i Goldshire. Han är hängiven Holy Light och rikets försvar och vägleder och tränar nya paladiner som beger sig bortom Northshire Valley till Elwynn Forests vidsträckta områden.",al={"vem är brother wilhelm","brother wilhelms identitet","vem är wilhelm"}},cccf7116={q="På vems sida står Brother Wilhelm?",a="Brother Wilhelm står stadigt på Alliansens och kungariket Stormwinds sida. Han tjänar Ljusets heliga ordnar och ägnar sig åt att stärka rikets paladiner mot interna stridigheter och regionala hot.",al={"vem tjänar brother wilhelm","brother wilhelms fraktion","brother wilhelm och alliansen"}},["3fb91c50"]={q="Varför är Brother Wilhelm i Goldshire?",a="Brother Wilhelm är stationerad bakom smedjan i Goldshire och undervisar unga paladiner som nyligen lämnat Northshire Abbey. Han stannar kvar i Elwynn Forest för att övervaka deras fortsatta utveckling och andliga beredskap när de går ut i aktiv tjänst.",al={"varför är brother wilhelm här","brother wilhelm i goldshire","varför är wilhelm i elwynn"}}},fp="15,156,20.304.0,20.318.0,33.134.0,43.127.0,57.189.0,47.163.0"}
P.entries["npc:bruegal-ironknuckle"] = {n="Bruegal Ironknuckle",s="Bruegal Ironknuckle är en ökänd dvärgisk fånge i Stormwind Stockade. Till skillnad från småbrottslingarna och det upproriska slöddret i cellerna är han en fruktad slagskämpe vars närvaro djupt inne i korridorerna innebär omedelbar fara för alla som försöker återställa ordningen.",h="Bruegal Ironknuckle är en ökänd dvärgisk fånge i Stormwind Stockade.",kw={"slagskämpe","bruegal ironknuckle","dvärg","fånge","ironknuckle","sällsynt","stockade","stormwind"},ang={["class:Warrior"]="Ironknuckle slåss med rå beslutsamhet och tunga nävar. Han visar stridskämpar hur tygellös råstyrka ser ut när disciplin och ära saknas.",["faction:Alliance"]="Stormwinds stadsvakt förlitar sig på modiga hjältar från Alliance för att kuva laglösa som Ironknuckle, som hotar att förvandla huvudstadens hjärta till ett permanent fäste för anarki.",["race:Dwarf"]="Dvärgbesökare kan finna det omskakande att se en bastant frände bland Stormwinds ficktjuvar och skurkar. Det visar att landsförvisning och laglöshet drabbar även Ironforges söner."},sec={{t="En farlig fånge",b="När Stormwind Stockade gjorde öppet uppror tog många av stadens mest våldsamma banditer kontroll över de underjordiska cellblocken. En av dem är Bruegal Ironknuckle, en särskilt farlig dvärgfånge som är känd för sin brutala styrka i slagsmål. I stället för att hålla sig i en enda cell strövar han omkring i de upprorshärjade korridorerna, redo att slå ner alla som försöker kväsa upproret."},{t="En oregerlig fredlös",b="Mycket av upproret i anläggningen orkestreras av Defias Brotherhood och deras ledare, men fångar som Bruegal visar att fängelset hyser allehanda skurkar och fredlösa från de östra rikena. Vilka brott som gav honom ett straff djupt under Stormwind är okänt, men hans okuvliga motståndskraft gör honom svår att hitta och till en av de farligaste ensamfångarna i fängelsets korridorer."}},faq={{q="Vem är Bruegal Ironknuckle?",a="Bruegal Ironknuckle är en elitfånge av dvärgras som sitter fängslad i Stormwind Stockade. Han är känd som en svårfunnen och hårdför fånge som strövar omkring i fängelsets korridorer under det pågående upproret.",al={"vem är bruegal","ironknuckles historia","dvärgfånge i stockade"}},{q="Tillhör Bruegal Ironknuckle Defias Brotherhood?",a="Bruegal är en dvärgfånge i The Stockade. Hans exakta tillhörighet finns inte angiven i den tillgängliga källan.",al={"är bruegal med i defias","defias dvärg stockade"}},{q="Varför sitter han fängslad i The Stockade?",a="De exakta anklagelserna som ledde till att han hamnade i The Stockade finns inte angivna i officiella offentliga arresteringsorder, men hans våldsamma humör och rykte som slagskämpe tyder på allvarliga brott mot Stormwinds lagar.",al={"varför är bruegal inlåst","bruegals brott"}},{q="Var kan han hittas i The Stockade?",a="Bruegal sitter inte stilla i någon bestämd cell. Han är en svårfunnen fånge som ibland strövar genom fängelsets inre passager och korsningar och överraskar dem som rensar ut upprorsmakarna.",al={"bruegals spawn","var finns bruegal","sällsynt spawn i stockade"}},{q="Finns han alltid i fängelset?",a="Nej. Bruegal syns sällan bland de upproriska fångarna. Han hålls ofta inlåst eller gömmer sig utom synhåll och visar sig bara då och då under oroligheterna.",al={"kan bruegal utebli","varför hittar jag inte bruegal"}},{q="Vad gör honom särskild bland fångarna?",a="Utöver sin fruktansvärda stridsförmåga sägs Bruegal bära på värdefullt smuggelgods och utrustning som han gömt undan fängelsevakterna. Det gör honom till ett eftertraktat byte för äventyrare som vågar möta honom.",al={"varför letar folk efter bruegal","bruegals betydelse"}}},fp="19,171,19.359.0,13.379.0,27.153.0,54.87.0,37.179.0,42.133.0,35.102.0,43.190.0"}
P.entries["npc:cain-firesong"] = {n="Cain Firesong",s="Cain Firesong är en magitränare bland de Förfallna i Brill i Tirisfal Glades. Han hjälper nybörjare inom magins konst att växa i kraft och vägleder dem innan han hänvisar dem vidare till djupare studier i Undercity. Du hittar honom på trappavsatsen en våning upp i Gallows' End Tavern.",h="Cain Firesong är en magitränare bland de Förfallna i Brill i Tirisfal Glades.",kw={"anastasia hartwell","magi","brill","cain firesong","gallows' end tavern","magitränare","tirisfal glades"},ang={["class:Mage"]="För unga magiker bland de Förfallna som ger sig av från Deathknell är Cain Firesong din främsta mentor i Tirisfal Glades innan du kallas till Undercity.",["race:Undead"]="Cain visar att även i döden är de tidigare mänskliga magikernas traditionella magi ett kraftfullt vapen för de Förfallna."},sec={{t="En magiutövare i Brill",b="Medan många magiker bland de Förfallna fördjupar sig i skuggmagi eller nekromanti behärskar Cain Firesong de traditionella magiska disciplinerna. Han är stationerad i Brill och fungerar som en tidig mentor för magiker bland de Förfallna som ger sig av från Deathknell. De lokala dödsvakterna visar besökare till trappavsatsen en våning upp i Gallows' End Tavern och skämtar om att han kom för sent för att få ett rum."},{t="Vägledning för nya talanger",b="När nybörjarmagikerna under hans ledning kommer vidare från sina grundläggande studier i Tirisfal Glades ser Cain till att de inte stagnerar. Han skickar sina mest lovande elever till mästersorceressan Anastasia Hartwell, som bor i Magic Quarter i Undercity."}},faq={{q="Vem är Cain Firesong?",a="Cain Firesong är en magitränare bland de Förfallna, stationerad i Brill i Tirisfal Glades. Han lär ut magiska besvärjelser till nybörjare bland hordens magiker och hänvisar avancerade elever vidare till Undercity.",al={"vem är cain firesong","cain firesongs historia","cain firesong brill"}},{q="Var håller Cain Firesong till i Brill?",a="Cain står på trappavsatsen en våning upp i Gallows' End Tavern i Brill. De lokala dödsvakterna skämtar om att han checkade in för sent för att få ett rum.",al={"var finns cain firesong","cain firesongs plats","cains rum på värdshuset"}},{q="Vart skickar Cain magiker efter deras grundutbildning?",a="När en magiker har kommit tillräckligt långt under hans ledning skickar Cain dem ner till Magic Quarter i Undercity för att fortsätta sin utbildning hos Anastasia Hartwell.",al={"cain firesong uppdrag","vem skickar cain magiker till","tala med anastasia"}}},fx={["265be98f"]={q="På vems sida står Cain Firesong?",a="Cain Firesong står stadigt på de Förkastades och Hordens sida. Han är stationerad i Brill och tjänar den Mörka Damen genom att lära nyuppväckta odöda magins konst, så att de Förkastades besvärjare får den magiska styrka de behöver för att försvara Tirisfal Glades och stärka Undercity.",al={"cain firesongs fraktion","cain firesongs lojalitet","vem tjänar cain firesong"}},["5ce3d117"]={q="Vad vill Cain Firesong?",a="Cain vill finslipa de unga Förkastade magikernas arkandisciplin innan han skickar dem vidare till mästartränare i Undercity.",al={"cain firesongs mål","vad gör cain firesong","cain firesongs syfte"}},f96c1f09={q="Varför är Cain Firesong här?",a="Cain är stationerad i Brill för att undervisa unga magiker som kommer från Deathknell. Du hittar honom på trappavsatsen en våning upp i Gallows' End Tavern.",al={"varför är cain firesong i brill","varför är cain firesong där","varför är cain firesong här"}}},fp="13,189,23.388.0,18.199.0,21.169.0,39.154.0,56.135.0"}
P.entries["npc:cairne-bloodhoof"] = {n="Cairne Bloodhoof",s="Cairne Bloodhoof är de förenade taurenstammarnas vördnadsvärde överhövding och Thunder Bluffs härskare. Som en väldig krigare med stor visdom knöt han taurenfolkets öde till Thralls hord efter att orcherna hjälpt hans folk att undkomma utrotning från kentaurernas sida.",h="Cairne Bloodhoof är de förenade taurenstammarnas vördnadsvärde överhövding och Thunder Bluffs härskare.",kw={"baine","bloodhoof","cairne","kentaur","överhövding","mulgore","thrall","thunder bluff"},ang={["faction:Horde"]="Tillsammans med Thrall är Cairne en av det moderna Kalimdorhordens grundare och en stöttepelare för ära, visdom och militär styrka.",["race:Tauren"]="Cairne är ditt folks räddare. Han har enat de splittrade stammarna, slagit tillbaka kentaurerna och lett bygget av Thunder Bluff."},sec={{t="Ett folk i Mulgore",b="I generationer levde tauren som kringvandrande nomader över The Barrens, ständigt jagade och drivna mot utrotning av vilda kentaurplundrare. När Thrall och hans orcher anlände till Kalimdors stränder såg Cairne en ovanlig ädelhet hos dem. Thrall erbjöd militärt skydd och eskorterade Cairnes desperata karavan över slätterna till Mulgore i utbyte mot vägledning till oraklet vid Stonetalon Peak. Cairne slog sig ned på Thunder Bluffs väldiga platåberg och grundade till sist ett permanent, enat hem för alla taurenstammar."},{t="Löfte till horden",b="Cairne kände sig skyldig Thrall en tjänst och följde orcherna till Stonetalon Peak, där han stred sida vid sida med horden och Jaina Proudmoores människor mot den brinnande legionen under det tredje kriget. Senare, när amiral Daelin Proudmoore invaderade Durotar, tog Cairne åter själv till vapen och stred vid Rexxars sida efter att hans tillfångatagne son Baine hade återförts i säkerhet. I dag är Cairne en av hordens mest respekterade äldste och Thralls närmaste förtrogna, och erbjuder lugna råd när andra vill starta krig utan eftertanke."}},faq={{q="Vem är Cairne Bloodhoof?",a="Cairne Bloodhoof är de förenade taurenstammarnas överhövding, hövding för Bloodhoof-stammen och ledare för Thunder Bluff. Han är en uråldrig krigare vars ledarskap och styrka förde tauren ur nomadisk landsflykt till ett tryggt hemland.",al={"vem är cairne","taurenledare","överhövding"}},{q="Varför är tauren allierade med orcherna?",a="Under det tredje kriget jagade plundrande kentaurstammar tauren mot utrotning. Thrall och hans nyligen anlända orcher slog tillbaka plundrarna och eskorterade Cairnes stora karavan till Mulgore. Av tacksamhet svor Cairne att hans folk skulle ge Thralls hord sin lojalitet och styrka.",al={"varför går tauren med i horden","cairne och thralls vänskap","allians mellan tauren och orcher"}},{q="Var bor Cairne?",a="Han styr från Thunder Bluff, huvudstaden som byggts på Mulgores höga platåberg, tillsammans med ledarna för de återförenade taurenstammarna.",al={"var finns cairne","cairnes plats","hitta cairne bloodhoof"}},{q="Vad är Baine Bloodhoof för Cairne?",a="Baine är Cairnes älskade son och arvinge. När kentaurplundrare förde bort Baine sörjde Cairne djupt och vägrade strida tills Rexxar och hans följeslagare spårade upp Baine och förde honom tryggt hem.",al={"cairnes son","är baine cairnes son","baine bloodhoofs relation"}}},fx={d2aba303={q="Vad vill Cairne Bloodhoof?",a="Cairne önskar sitt folk en varaktig fred och välgång. I åratal stod de nomadiska taurerna nära utrotning på grund av kringströvande kentaurstammar. Efter att ha enat stammarna på Mulgore högplatåer är hans fokus att säkra deras förfäders hem, värna deras fredliga andliga traditioner och stå troget vid sina bundsförvanters sida i Horden mot alla som hotar Kalimdor.",al={"cairnes mål","vad vill cairne","cairnes ambitioner"}},["665f60ad"]={q="Varför är Cairne Bloodhoof i Thunder Bluff?",a="Som hövding över de enade taurstammarna styr Cairne sitt folk från huvudstaden Thunder Bluff. Han grundade bosättningen på Mulgore höga platåer för att skydda taurerna mot kringströvande kentaurer. Här stannar han för att styra stammarna, ge råd åt schamaner och samordna försvaret med sina bundsförvanter i Horden.",al={"varför är cairne i thunder bluff","varför är cairne här","varför är cairne bloodhoof där"}},a87d4b70={q="Varför är Cairne Bloodhoof berömd?",a="Cairne vördas som en oöverträffad krigare och den visionäre ledare som enade de splittrade taurstammarna. Han är känd över hela Kalimdor för sin enorma styrka och beprövade visdom, och spelade en avgörande roll i segern över den brinnande legionen på Mount Hyjal och i grundandet av den moderna Horden tillsammans med Thrall.",al={"cairne bloodhoofs rykte","är cairne bloodhoof berömd","varför är cairne respekterad"}}},fp="16,227,19.547.0,19.495.0,24.217.0,40.278.0,25.136.0,33.200.0"}
P.entries["npc:calor"] = {n="Calor",s="Calor är en hängiven invånare i Darkshire som hjälper familjen Carevin att försvara Duskwood. På uppdrag av Jonathan Carevin samordnar han aktivt jakten på de våldsamma worgen som stryker omkring i de dystra skogarna. Äventyrare som vill driva tillbaka de glupska bestarna som hemsöker skogen får ofta sina uppdrag av honom.",h="Calor är en hängiven invånare i Darkshire som hjälper familjen Carevin att försvara Duskwood.",kw={"calor","carevin","darkshire","duskwood","jonathan carevin","night watch","the rotting orchard","worgen"},ang={["class:Hunter"]="Jägare hittar stadig sysselsättning hos Calor, där de spårar upp och gallrar bland vilda, övernaturliga bestar som trotsar skogens naturliga ordning.",["faction:Alliance"]="Calor är en viktig kontakt för alliansens hjältar som är villiga att trotsa de dystra skogarna för att försvara Darkshires isolerade invånare."},sec={{t="En lojalist i skuggorna",b="I den hårt prövade bosättningen Darkshire arbetar Calor nära Jonathan Carevin, en av stadens framstående försvarare. Mitt i Duskwoods ändlösa mörker och smygande fasor ägnar sig Calor åt att stödja familjen Carevins uppdrag: att utrota de övernaturliga fasor som tränger in mot stadens utkanter innan de återstående stadsborna slaktas."},{t="Worgenhotet",b="Calors främsta uppgift är att bekämpa de förvildade worgen som stryker omkring i skogen, särskilt kring pestdrabbade platser som The Rotting Orchard. Dessa våldsamma vargmän är mycket mer aggressiva och farliga än vanliga bestar och slaktar både resande och patruller. Calor värvar dugliga kämpar för att minska deras antal och undersöka deras ursprung, i ett desperat försök att hejda den blodtörstiga flodvågen."}},faq={{q="Vem är Calor?",a="Calor är en människa som lever i Darkshire och står på familjen Carevins sida. Han hjälper till att försvara staden genom att skicka ut äventyrare för att jaga farliga hot i Duskwood.",al={"calor darkshire","vem är calor","calor duskwood"}},{q="Var hittar du Calor?",a="Calor finns i Darkshire, den främsta alliansstaden i Duskwoods skuggiga skogar.",al={"var finns calor","calors plats","calors koordinater"}},{q="Vilken relation har Calor till Jonathan Carevin?",a="Calor är en trogen anhängare till familjen Carevin. Han följer Jonathan Carevins direktiv och hjälper honom att föra krig mot de dödliga monster som plågar skogen.",al={"calor och carevin","vem arbetar calor för","familjen carevin och calor"}},{q="Vilka fiender får Calor dig att bekämpa?",a="Calor ger äventyrare i uppdrag att jaga de blodtörstiga worgenflockar som hemsöker skogen och riktar särskilt deras anfall mot dem nära platser som The Rotting Orchard.",al={"calors uppdrag","vad vill calor","worgenuppdrag calor"}},{q="Varför är worgenhotet så brådskande i Duskwood?",a="Worgen är våldsamma, glupska rovdjur som anfaller allt de får syn på. Utan regelbundna utrensningar som samordnas av personer som Calor och Night Watch skulle bestarna snabbt övermanna Darkshires svagt bemannade försvarslinjer.",al={"varför döda worgen i duskwood","worgenhotet i duskwood"}},{q="Tillhör Calor Night Watch?",a="Nej. Calor blev desillusionerad av det han uppfattade som Night Watchs likgiltighet och anslöt sig i stället till Jonathan Carevin. Nu agerar han som direkt ombud och anhängare i familjen Carevins korståg mot worgen.",al={"calor night watch","är calor med i night watch"}}},fx={e997a1f9={q="Vad vill Calor?",a="Calor är fast besluten att utrota varulvarna som hemsöker Duskwood. På direkt order av Jonathan Carevin värvar han dugliga äventyrare till att jaga de vilda bestarna som lurar på platser som The Rotting Orchard och hejda spridningen av deras skuggiga korruption innan den överväldigar Darkshire.",al={"calors mål","vad gör calor","vad vill calor"}},f0ff266f={q="Varför är Calor i Darkshire?",a="Calor stannar i Darkshire för att hjälpa familjen Carevin i deras korståg mot skogens bestar. Från denna hårt ansatta stad samordnar han spaning och jakt på de vilda varulvsflockar som stryker omkring i de närliggande dungarna och övergivna fruktodlingarna.",al={"varför är calor här","varför är calor i darkshire","varför är calor i duskwood"}}},fp="5,157,25.243.0,17.318.0,13.139.0,25.68.0,51.119.0,39.86.0,47.193.0,37.161.0"}
P.entries["npc:calvin-montague"] = {n="Calvin Montague",s="Calvin Montague är en opportunistisk Forsaken-skurk som dröjer sig kvar nära utgångsporten till Deathknell i Tirisfal Glades. Han utnyttjar nyvaknade odöda när de lämnar gravgården och försöker lura förbipasserande att uträtta ärenden åt honom.",h="Calvin Montague är en opportunistisk Forsaken-skurk som dröjer sig kvar nära utgångsporten till Deathknell i...",kw={"en skurks affär","calvin montague","bedragare","deathknell","forsaken-skurk","montague","tirisfal glades"},ang={["class:Rogue"]="Forsaken-skurkar genomskådar snabbt Calvin Montagues uppenbara försök till manipulation och känner igen en ficktjuvskollega som försöker lura de ovana med en billig bluff.",["race:Undead"]="För de nyuppståndna som lämnar Deathknell blir Calvin en tidig lärdom om att inte alla Sylvanas undersåtar är intresserade av ömsesidig solidaritet."},sec={{t="En bedragare vid porten",b="Strax utanför portarna från Deathknell förkroppsligar Calvin Montague den hänsynslösa pragmatism som är vanlig bland Lordaerons rastlösa döda. I stället för att sköta sin egen korrespondens eller betala skäliga budpriser försöker han med smicker övertala kringvandrande äventyrare att leverera brev under falska förespeglingar. Medan flera andra framstående odöda med efternamnet Montague sköter bankintressen i Undercity ägnar sig Calvin åt en betydligt mindre hedervärd syssla och föredrar små bedrägerier och svek."},{t="En skurks plan",b="Calvin föreslår att du tar med ett förseglat meddelande åt honom, men den som är skarpsinnig eller har erfarenhet av undre världen genomskådar snabbt hans bluff. Även bland de nyuppståndna som försöker finna en mening i Tirisfals dystra ruiner påminner Calvin nykomlingarna om att tillit är en bristvara i den Mörka damens tjänst."}},faq={{q="Vem är Calvin Montague?",a="Calvin Montague är en Forsaken-skurk som står nära utgångsporten till Deathknell i Tirisfal Glades. Han försöker utnyttja nyuppståndna odöda genom att lura dem att uträtta ett obetalt ärende åt honom.",al={"calvin montague","vem är calvin montague","calvin deathknell"}},{q="Vad vill Calvin att äventyrarna ska göra?",a="Calvin försöker övertala förbipasserande resenärer att leverera ett brev åt honom under falska förespeglingar. Han hoppas få gratis budservice genom smidig manipulation.",al={"calvin montague uppdrag","calvins brev","vad vill calvin"}},{q="Är Calvin Montague släkt med bankirerna i Undercity?",a="Han delar efternamn med flera framstående bankirer i Undercity, däribland Ophelia, Mortimer, William och Randolph Montague. Något släktskap har inte bekräftats.",al={"montague-familjen","montague-bankirer i undercity","är calvin släkt med bankirerna"}},{q="Var hittar man Calvin Montague?",a="Han håller till längs vägen strax utanför träporten som markerar Deathknells norra utgång och hejdar äventyrare på väg ut i det vidsträckta Tirisfal Glades.",al={"calvins plats","var finns calvin montague","hitta calvin montague"}}},fx={["9e392640"]={q="På vems sida står Calvin Montague?",a="Calvin är en självständig Förkastad skurk som främst ser till sitt eget bästa. Han bor i de Förkastades områden och umgås med deras resenärer, men hans intriger och skumma affärer visar att han tjänar sin egen plånbok, inte någon ädel sak eller statlig verksamhet.",al={"calvin montagues fraktion","vem tjänar calvin montague","är calvin montague en av de förkastade"}},["0598d792"]={q="Varför håller Calvin Montague till utanför Deathknell?",a="Calvin håller till precis längs vägen ut från Deathknell för att utnyttja nyvaknade odöda. Nyuppväckta Förkastade som beger sig ut i Tirisfal Glades är lätta byten för en hänsynslös skurk som vill lura någon att utföra hans budärenden gratis.",al={"varför är calvin montague här","var håller calvin montague till vid deathknell","varför är calvin vid utgången från deathknell"}}},fp="15,134,21.422.0,16.310.1,23.167.0,40.157.0,52.152.0,35.149.0"}
P.entries["npc:canaga-earthcaller"] = {n="Canaga Earthcaller",s="I Valley of Trials vägleder Canaga Earthcaller nya shamaner i Horden mot landets andar och deras första totem.",h="I Valley of Trials vägleder Canaga Earthcaller nya shamaner i Horden mot landets andar och deras första totem.",kw={"call of earth","canaga","darkspear","durotar","earth sapta","earthcaller","schaman","valley of trials"},ang={["class:Shaman"]="Som shaman möter du Canaga som din första andliga mentor i Durotar. Han förbereder Earth Sapta så att du kan tala med elementen och göra anspråk på ditt Earth Totem.",["race:Orc"]="Som orch hittar du Canaga i arbete sida vid sida med orchernas instruktörer i dalen. Han hjälper unga orcher att knyta sina andar till den hårda jorden i deras nya hemland.",["race:Troll"]="Som troll hittar du Canaga bland de framstående Darkspear-gestalterna i Valley of Trials. Han vägleder unga trollshamaner när de inleder sin väg med andarna."},sec={{t="Landets röst",b="Canaga Earthcaller vägleder Darkspear-troll och orcher som påbörjar shamanens väg bland Valley of Trials röda klippor. Han lär nykomlingarna att stilla sina sinnen och lyssna till Kalimdors dån. De förbereder jord-sapta så att de kan tala med andarna."},{t="Det första totemet",b="Canaga ber varje novis att samla heliga ingredienser och resa till den lokala Spirit Rock i Durotar. Där dricker de jord-sapta och får se elementandarterna med egna ögon. Med hans vägledning får de sitt Earth Totem."}},faq={{q="Vem är Canaga Earthcaller?",a="Canaga Earthcaller är en Darkspear-trollshaman i Valley of Trials. Han handleder unga shamaner som tar sina första steg i Horden.",al={"canagas historia","vem är canaga","canaga earthcaller npc"}},{q="Vad lär Canaga unga schamaner?",a="Canaga vägleder Hordens shamaner genom uppdragskedjan Call of Earth i Durotar. Han brygger Earth Sapta, som låter nykomlingarna uppfatta och tala med den lokala jordelementaranden när de söker sitt första totem.",al={"schamanuppdrag durotar","call of earth durotar","canagas uppdrag"}},{q="Vad är Earth Sapta som Canaga tillreder?",a="Earth Sapta är en andlig dryck som Canaga brygger av lokala ingredienser. Shamaner dricker den för att öppna sina sinnen för landets dolda andar och tala med elementmanifestationer.",al={"vad är earth sapta","saptas historia"}},{q="Varför tränar en troll schamaner på en orcisk prövningsplats?",a="Efter det tredje kriget knöt sig Darkspear-stammen nära till Thralls Horde och slog sig ned tillsammans med orcherna i Durotar. Trollshamaner och krigare tränar nu sida vid sida med unga orcher i Valley of Trials.",al={"varför troll i valley of trials","darkspear i valley of trials"}},{q="Var hittar man Canaga Earthcaller?",a="Canaga sitter på klippplatåer med utsikt över de östra stigarna i Valley of Trials, strax söder om det främsta träningsområdet.",al={"canagas plats","var finns canaga"}}},fx={["9fbe2a10"]={q="På vems sida står Canaga Earthcaller?",a="Canaga tjänar Horden och vägleder unga schamaner bland både Darkspear-trollen och orcherna. Han är stationerad i Valley of Trials och hjälper unga invigda att inleda sin gemenskap med Durotars elementandar på krigshövding Thralls nygrundade rikes vägnar.",al={"canaga earthcallers fraktion","tillhör canaga horden","vem tjänar canaga"}},["911868d9"]={q="Vad vill Canaga Earthcaller?",a="Canaga vill se till att blivande schamaner stämmer sig rätt med jordens andar. Han prövar hoppfulla invigda genom att be dem samla heliga reagenser, dricka Earth Sapta och ta direkt kontakt med traktens elementväsen.",al={"vad vill canaga","canaga earthcallers mål","canagas syfte"}},f7883336={q="Vilka har Canaga Earthcaller band till?",a="Canaga tillhör Darkspear-stammen och samarbetar direkt med orkernas schamanlärare i Valley of Trials. Tillsammans vägleder de unga troll och orcher genom Call of Earth.",al={"canaga earthcallers band","vem samarbetar canaga med","canagas bundsförvanter"}}},fp="18,123,17.269.0,15.219.0,26.135.0,37.210.0,40.181.0,60.200.0,38.116.0"}
P.entries["npc:captain-danuvin"] = {n="Captain Danuvin",s="Vid Sentinel Hill hjälper Captain Danuvin till att hålla Westfalls gränsland samman. Han samarbetar med People's Militia och leder frivilliga och rekryter i patrullering längs vägarna och för att driva tillbaka gnoller och laglösa. Hans order skyddar försörjningslederna och jordbruken från fiender.",h="Vid Sentinel Hill hjälper Captain Danuvin till att hålla Westfalls gränsland samman.",kw={"captain danuvin","danuvin","gryan stoutmantle","patrullera westfall","peoples militia","riverpaw","sentinel hill","westfall"},ang={["class:Warrior"]="Som krigare kan du använda din kampdisciplin och styrka mot gnollflockar och hjälpa till att röja landsvägen.",["faction:Alliance"]="Captain Danuvin är en av få militärer som upprätthåller ordningen i Westfall trots kronans försummelse. Rekryter från Alliansen kan hjälpa till att försvara riket.",["race:Human"]="Som människa kan du hjälpa Captain Danuvin att försvara ditt hemland och skydda Stormwinds kornbod från plundrare och bestar."},sec={{t="Försvaret av kullen",b="Captain Danuvin samordnar patrullerna från det befästa tornet på Sentinel Hill. Stormwinds reguljära garnison har dragit sig tillbaka, vilket har försvagat Westfalls försvar rejält. Han förlitar sig på resande, lantarbetare och frivilliga kämpar för att upprätthålla viss ordning över slätterna."},{t="Patrullering vid gränsen",b="Captain Danuvin fokuserar på vägarna och de öppna markerna runt Sentinel Hill. Riverpaw Gnolls plundrar nära de centrala utposterna, så han skickar ut patruller för att minska deras antal och säkra området. Hans order hjälper till att hålla plundrare och lycksökare borta från lägret."}},faq={{q="Var hittar jag Captain Danuvin?",a="Captain Danuvin finns vid Sentinel Hill, Alliansens utpost i centrala Westfall. Han brukar vara nära det befästa tornet som blickar ut över vägen.",al={"danuvins plats","var finns captain danuvin","danuvin westfall"}},{q="Vilken fraktion representerar Captain Danuvin?",a="Captain Danuvin tjänar Alliansen och stöder Westfalls lokala försvarare. Han arbetar nära Gryan Stoutmantle och People's Militia.",al={"danuvins fraktion","vem tjänar danuvin"}},{q="Vilka uppgifter ger han äventyrare?",a="Captain Danuvin skickar rekryter att patrullera slätterna och driva tillbaka Riverpaw Gnolls som rycker fram mot Sentinel Hill.",al={"danuvins uppdrag","vad vill captain danuvin","uppdraget patrullera westfall"}},{q="Varför förlitar sig Danuvin på frivilliga i stället för Stormwinds armé?",a="Stormwind har lämnat Westfall utan garnisonstrupper. Captain Danuvin och ledarna på Sentinel Hill förlitar sig på legosoldater och milisrekryter.",al={"varför ingen stormwindarmé","varför milis","stormwinds garnison i westfall"}},{q="Har Danuvin förbindelser utanför Westfall?",a="Captain Danuvins band finns i Westfall, hans hemland. Han har svurit att stå vid de medborgare som stannade kvar, så han fokuserar på slätterna och vägarna runt Sentinel Hill.",al={"danuvin redridge","danuvins förbindelser"}},{q="Vilken roll har han jämfört med Gryan Stoutmantle?",a="Gryan Stoutmantle leder People's Militia och ansvarar för Westfalls övergripande försvar. Captain Danuvin sköter fälttaktik, vägpatruller och gnollhotet nära basen.",al={"stoutmantle eller danuvin","har danuvin befälet"}}},fp="15,238,16.246.0,23.254.0,33.149.0,44.142.0,42.112.0,67.143.0,50.163.0,47.171.0"}
P.entries["npc:captain-grayson"] = {n="Captain Grayson",s="Vid Westfall Lighthouse vakar Captain Grayson över fyren som svek honom. Hans skepp krossades mot den mörka kusten, och nu sköter han ljuset så att andra sjömän slipper möta samma öde.",h="Vid Westfall Lighthouse vakar Captain Grayson över fyren som svek honom.",kw={"captain grayson","piratspöke","grayson","fyr","old murk-eye","westfall","westfall lighthouse"},ang={["class:Paladin"]="Som paladin kan du hedra din heliga plikt att försvara de hjälplösa och driva tillbaka de mordiska murlocer­na genom att hjälpa Grayson, trots att han är en odöd ande.",["class:Priest"]="Som präst kan du ge Graysons rastlösa själ tröst. Skuld och sorg håller hans ande kvar efter att han såg en oskyldig familj dö.",["faction:Alliance"]="Med Defias Brotherhood som stryper Westfall och Stormwind som försummar sina gränser måste resenärer från Alliansen svara på Graysons vädjan och hålla fyrens låga brinnande."},sec={{t="Ett liv som slutade bland klipporna",b="Captain Grayson seglade en gång som kapten på södra Eastern Kingdoms hav. En natt slocknade fyren när hans skepp närmade sig Westfalls klippiga grund. Skeppet slog mot klipporna, och Grayson dog med det. Han vaknade som ett jordbundet spöke, fången vid kusten."},{t="Tragedi vid fyren",b="Efter sin död begav sig Captain Grayson till Westfall Lighthouse i hopp om att få veta vad som väntade bortom livet. Där såg han Old Murk-Eye, en ökänd murloc, jaga bort fyrvaktaren och hans familj. De modiga fyrvaktarna återvände för att tända fyren på nytt, men Old Murk-Eye samlade de kringliggande murlocerna och ledde en andra, brutal massaker. Grayson kunde bara se på när familjen slaktades."},{t="En spöklik vakt",b="Fyrvaktarna är döda och Westfall förfaller av vanvård. Captain Grayson bär fyrljusets högtidliga börda på sina spektrala axlar. Han ber resenärer som passerar att samla bränsle till den stora elden. Han söker också hämnd för familjen som slaktades: jaga rätt på Old Murk-Eye och driv tillbaka kustens murlocer."}},faq={{q="Vem är Captain Grayson?",a="Captain Grayson är ett mänskligt piratspöke vid Westfall Lighthouse. Hans skepp krossades mot kusten när fyren slocknade, och nu sköter han ljuset för att skydda sjömän som passerar.",al={"graysons identitet","vem är piratspöket","fyrspöke"}},{q="Hur dog Captain Grayson?",a="Captain Grayson dog när hans piratskepp slog mot de förrädiska klipporna längs Westfalls kust. Fyren var släckt den natten, så han och hans besättning fick ingen varning innan skeppet slets i stycken.",al={"graysons död","hur blev grayson ett spöke","vad dödade captain grayson"}},{q="Vad hände med den riktiga fyrvaktaren?",a="Kustens murlocer angrep fyrvaktaren och hans familj. Den modiga familjen undkom det första anfallet och återvände för att tända fyren på nytt, men Old Murk-Eye samlade en andra räd och slaktade dem inför Graysons ögon.",al={"var är fyrvaktaren","vad hände med fyrvaktarna","fyrvaktarens familj"}},{q="Vem är Old Murk-Eye?",a="Old Murk-Eye är en slug och grym murloc-hövding vid Westfalls kust. Han ledde anfallet som dödade fyrvaktarens familj och hotar alla som försöker hålla fyren tänd.",al={"murk-eyes historia","old murk-eye","murlocledare i westfall"}},{q="Varför vill Grayson att fyren ska hållas tänd?",a="Grayson drunknade när kusten låg i beckmörker och ser det som sin högtidliga plikt i livet efter detta att hålla fyren tänd. Han vill bespara andra sjömän samma öde på grundet.",al={"graysons motiv","varför tända fyren"}},{q="Är Captain Grayson fientlig mot äventyrare?",a="Nej. Trots att Grayson var pirat när han levde hyser han inget agg mot de levande. Han har bevittnat alltför många massakrer och söker frid och hjälp med att hålla fyren tänd.",al={"är grayson vänligt sinnad","är grayson fientlig"}}},fx={["8f770f95"]={q="På vems sida står Captain Grayson?",a="Captain Grayson tjänar inget dödligt kungarike. Han var en gång en levande piratkapten och är fortfarande neutral till levande resenärer, men söker hjälp från dem som är villiga att säkra kusten. I döden är hans verkliga lojalitet inte med Stormwind eller någon flotta, utan med Westfall Lighthouse och sjömännens trygga färd.",al={"captain graysons fraktion","är grayson med alliansen eller horden","vem tjänar grayson"}},["2ee261a8"]={q="Varför är Captain Grayson vid fyren?",a="Grayson drogs till fyren efter att hans skepp krossats mot Westfalls kust eftersom fyren var släckt. Bunden till den dödliga världen som ande tog han sig hit och såg hjälplöst på medan Old Murk-Eye och hans murlocer slaktade fyrvaktarens familj. När fyrvaktarna var döda bestämde sig Grayson för att stanna och själv skydda fyren.",al={"varför är captain grayson här","varför kom grayson till westfall lighthouse","vad förde grayson till fyren"}}},fp="15,183,29.290.0,21.372.0,15.310.0,23.171.0,28.203.0,44.217.0,20.193.0,46.176.0,42.160.0"}
P.entries["npc:captain-greenskin"] = {n="Captain Greenskin",s="Captain Greenskin är en elitgoblinpirat som övervakar bygget och besättningen på Edwin VanCleefs massiva järnklädda jagare. Djupt inne i Deadmines underjordiska vik befaller han piratstyrkorna som Defias Brotherhood har värvat. Hans mål är att göra krigsfartyget seglingsklart så att det kan sätta kurs mot Stormwind.",h="Captain Greenskin är en elitgoblinpirat som övervakar bygget och besättningen på Edwin VanCleefs massiva...",kw={"captain greenskin","the deadmines","goblinpirat","greenskin","jagare","smite","vancleef"},ang={["class:Rogue"]="Greenskin står högst i Defias pirathierarki och är hårt bevakad av kapare och råskinn på krigsfartygets däck.",["faction:Alliance"]="För Alliansens styrkor utgör Captain Greenskin det marina hotet från Defias-upproret. Om hans jagare bryter igenom kustförsvaret är Westfalls och Stormwinds oförsvarade stränder direkt hotade."},sec={{t="Jagarkaptenen",b="Captain Greenskin patrullerar huvuddäcket på den väldiga jagaren som byggs i Deadmines vik och utgör Defias-sammansvärjningens marina ryggrad. Greenskin är en rutinerad goblinsjöman som togs in i Edwin VanCleefs innersta krets för att förvandla en underjordisk grotta till ett torrdocka för ett krigsvapen."},{t="Ett piratmanskap",b="Greenskin leder inte en vanlig besättning av stenhuggare eller banditer. Under hans direkta uppsikt tjänstgör rutinerade skurkar, däribland hans fruktade taurenska styrman Mr. Smite och murlockocken Cookie. Tillsammans håller de skeppets landgångar och övre däck och står mellan inkräktare och VanCleefs privata hytt ovanpå bryggan."}},faq={{q="Vem är Captain Greenskin?",a="Captain Greenskin är en goblinpiratkapten som Edwin VanCleef har värvat för att övervaka färdigställandet och driften av Defias Brotherhoods hemliga krigsjagare i Deadmines.",al={"greenskins historia","vem är greenskin","captain greenskin"}},{q="Var kom Greenskin ifrån innan han anslöt sig till Defias?",a="Det finns inga uppgifter om var Greenskin seglade innan han började arbeta för VanCleef. Han är endast känd som goblinpiratkaptenen som befaller Defias jagare och dess besättning i Deadmines.",al={"greenskins ursprung","var kommer greenskin ifrån","greenskin booty bay"}},{q="Vilka tjänstgör under Captain Greenskin?",a="Bland dem han befaller finns hans styrman, taurenen Mr. Smite, samt Cookie, murlockocken, och en grupp Defias-pirater som patrullerar det järnklädda fartygets däck.",al={"greenskins besättning","styrman","greenskins undersåtar"}},{q="Vad är Greenskins uppdrag i Deadmines?",a="Han har fått i uppdrag att göra det massiva järnklädda krigsfartyget sjödugligt och klart att segla ut ur den underjordiska grottan och ut på Stora havet för att slå till mot kungariket Stormwind.",al={"vad gör greenskin","varför är greenskin här"}},{q="Var hittar man Captain Greenskin?",a="Han patrullerar huvuddäcket på den stora jagaren som ligger för ankar i Deadmines innersta grotta och vaktar vägen till Edwin VanCleef.",al={"greenskins plats","var finns captain greenskin"}},{q="Tillhör Captain Greenskin Defias Brotherhood, eller är han legosoldat?",a="Han är en piratkapten som arbetar direkt för Edwin VanCleef och befaller de marina styrkorna som deltar i Defias Brotherhoods plan.",al={"är greenskin defias","greenskins fraktion"}}},fx={["9c1c4117"]={q="Varför är Captain Greenskin här?",a="Captain Greenskin anlitades av Edwin VanCleef för att övervaka bygget av och leda Defias Brotherhoods väldiga slagskepp. Han stannar ombord på fartyget, djupt inne i The Deadmines vik, och leder sin piratbesättning för att se till att krigsskeppet blir färdigt och beväpnat.",al={"varför är greenskin i the deadmines","varför är captain greenskin här","greenskins syfte i the deadmines"}},["6bcae29e"]={q="Vad vill Captain Greenskin?",a="Som inhyrd kapten av goblinras söker Greenskin vinst och spänningen i att föra befäl till sjöss. Han tänker färdigställa det kolossala pansarkrigsskeppet i The Deadmines vik och föra det ut på Stora havet för att tjäna Edwin VanCleefs planer mot Stormwind.",al={"greenskins mål","vad vill captain greenskin","greenskins motiv"}},["433e5911"]={q="Varför är Captain Greenskin fruktad?",a="Captain Greenskin för befäl över piratbesättningen på Edwin VanCleefs slagskepp, med brutala rövare som hans taurenstyrman Mr. Smite vid sin sida. Med en klyvande klinga och förgiftade harpuner patrullerar han däcket och står mellan inkräktare och VanCleef själv.",al={"varför är greenskin fruktad","captain greenskins rykte","är greenskin berömd"}}},fp="17,220,24.234.0,15.276.0,25.169.0,56.135.0,35.128.0,45.153.0,37.149.0,67.154.0"}
P.entries["npc:captain-rugelfuss"] = {n="Captain Rugelfuss",s="Captain Rugelfuss är en sträng dvärgisk officer vid den södra porten i Valley of Kings. Han har fått i uppdrag att säkra gränsen till Loch Modan och organiserar försvaret mot ett plötsligt och aggressivt trogguppror.",h="Captain Rugelfuss är en sträng dvärgisk officer vid den södra porten i Valley of Kings.",kw={"captain rugelfuss","ironforges vakt","loch modan","bergsjägare","rugelfuss","troggarnas hot","valley of kings"},ang={["class:Warrior"]="Krigare kan känna igen sig i Rugelfuss rättframma taktiska stil och hans tydliga uppdrag: att röja frontlinjen med svärd och sköld.",["faction:Alliance"]="Rugelfuss påminner alliansens resenärer om att det är avgörande för alliansens överlevnad att försvara hemlandet mot vilda angrepp, även när de stora arméerna strider på andra håll.",["race:Dwarf"]="För dvärgar står Captain Rugelfuss för Ironforges militära ståndaktighet. Han vaktar urgamla bergspass mot urgamla fiender från underjorden."},sec={{t="Försvar vid den södra porten",b="Captain Rugelfuss håller till nära Valley of Kings monumentala, uthuggna valv och övervakar den södra ingången till Loch Modan. När alliansstyrkorna är hårt ansatta över hela världen förlitar sig Ironforge på veteraner som honom för att hålla hemtrakterna säkra. Rugelfuss struntar i militär pompa och formaliteter och föredrar att helt fokusera på det dystra läget vid gränsen."},{t="Troggarnas intrång",b="Den främsta kris som kräver Rugelfuss uppmärksamhet är det växande hotet från troggarna. De har grävts fram ur uråldriga grottor och strömmar in i högländerna. De vilda bestarna har övermannat dvärgiska patruller i utkanterna och byggt befästa fästen i närheten. I kungens länders namn rekryterar kaptenen dugliga resenärer som kan decimera deras led och driva bort varelserna från vägen."},{t="Spaning vid fronten",b="Rugelfuss uppgifter handlar om mer än råstyrka. Hans bergsjägare spanar ständigt på trogglägren."}},faq={{q="Vem är Captain Rugelfuss?",a="Captain Rugelfuss är en dvärgisk militärbefälhavare från Ironforge, stationerad vid den södra ingången i Valley of Kings i Loch Modan. Han ansvarar för det regionala försvaret och gränssäkerheten.",al={"captain rugelfuss bakgrund","vem är rugelfuss","rugelfuss loch modan"}},{q="Var hittar man Captain Rugelfuss?",a="Han är stationerad nära South Gate i Valley of Kings och bevakar det södra passet från Loch Modan mot Dun Morogh.",al={"var finns rugelfuss","captain rugelfuss plats"}},{q="Varför oroar sig Captain Rugelfuss för troggar?",a="Ett nyligt trogguppror utgör en allvarlig fara för dvärgiska bosättningar och försörjningslinjer. Troggarna har trängt ända fram till den södra ingången och angripit Ironforges patruller. Om de inte hejdas hotar de att ta över kungens territorium.",al={"varför bekämpa troggar","troggarnas hot mot loch modan"}},{q="Varför struntar Rugelfuss i militära formaliteter?",a="Rugelfuss ser onödiga honnörer och ceremonier som farliga distraktioner när kungens länder är under belägring. Han kräver omedelbara, praktiska insatser i stället för protokoll.",al={"rugelfuss personlighet","lugn ras"}}},fx={["506fbcb9"]={q="På vems sida står Captain Rugelfuss?",a="Captain Rugelfuss står stadigt på Ironforges och den stora alliansens sida. Som officer som försvarar Loch Modans södra tillfartsvägar har han svurit att skydda dvärgarnas länder och försvara King Magni Bronzebeards auktoritet mot yttre hot.",al={"captain rugelfuss fraktion","vem tjänar rugelfuss","är rugelfuss med i alliansen"}},["8c27dafb"]={q="Vad vill Captain Rugelfuss?",a="Rugelfuss vill slå ner troggupproret som hotar Valley of Kings och kungens länder. Han förlitar sig på förbipasserande resenärer för att decimera de invaderande troggerna och driva tillbaka dem från vägarna i Loch Modan.",al={"vad behöver rugelfuss","rugelfuss mål","vad försöker rugelfuss göra"}},["0fa68497"]={q="Varför är Captain Rugelfuss stationerad i Valley of Kings?",a="Rugelfuss är posterad vid Loch Modans södra gräns för att bevaka passet mot Dun Morogh. Troggar svärmar i de omgivande dalarna, så en organiserad dvärgisk militär närvaro är nödvändig för att hålla vägen och samordna försvaret av kungens länder.",al={"varför är captain rugelfuss här","varför är rugelfuss vid södra porten","rugelfuss postering"}}},fp="17,134,25.270.0,19.263.0,24.96.1,25.159.0,37.137.0,48.184.0,50.144.0"}
P.entries["npc:captain-shatterskull"] = {n="Captain Shatterskull",s="Vid Mor'shan Base Camp leder Captain Shatterskull Hordens försvar av den norra gränsen. Som en erfaren orcisk befälhavare samordnar han insatserna för att slå tillbaka Night Elf-styrkor som utmanar gränsen nära Warsong Gulch.",h="Vid Mor'shan Base Camp leder Captain Shatterskull Hordens försvar av den norra gränsen.",kw={"the barrens","captain shatterskull","kadrak","mor'shan base camp","orcisk kapten","shatterskull","silverwing","warsong"},ang={["faction:Horde"]="För Hordens krigare som anländer från södra The Barrens försvarar Captain Shatterskull den norra gränsen mot Night Elf-infall från Ashenvale.",["race:Orc"]="Som orc speglar Captain Shatterskulls försvar av Hordens dyrköpta marker ett krigiskt sinnelag hos ett folk som andra ser som inkräktare."},sec={{t="Väktare vid den norra gränsen",b="Vid Mor'shan Base Camp försvarar Captain Shatterskull Hordens fäste vid Ashenvales utkant. Han arbetar tillsammans med andra officerare, som Kadrak, mot Night Elf-vakter och Silverwing-styrkor som försöker återta gränstrakterna. Kampen om Ashenvales timmer och uråldriga marker håller gränsen mot The Barrens under ständig press."}},faq={{q="Vem är Captain Shatterskull?",a="Captain Shatterskull är en erfaren orcisk befälhavare vid Mor'shan Base Camp och leder Hordens försvar mot Night Elf-styrkor.",al={"shatterskulls identitet","vem är captain shatterskull","shatterskull npc"}},{q="Var finns Captain Shatterskull?",a="Du hittar Captain Shatterskull vid Mor'shan Base Camp, på Barrens norra gräns, före Ashenvale.",al={"shatterskulls plats","var finns captain shatterskull","shatterskull vid mor'shan camp"}},{q="Vilken roll har han vid Mor'shan Base Camp?",a="Vid Mor'shan Base Camp leder Captain Shatterskull försvaret av Hordens norra gränstrakt och samlar krigare mot Alliansens Silverwing Sentinels.",al={"vad gör shatterskull","shatterskulls uppgift","befälhavare vid mor'shan"}},{q="Vilka arbetar Captain Shatterskull med?",a="Captain Shatterskull arbetar tillsammans med frontlinjeofficerare som Kadrak och samordnar försvar och rekrytering inför gränsstriderna.",al={"shatterskulls allierade","kadrak och shatterskull"}}},fx={["4e979652"]={q="På vems sida står Captain Shatterskull?",a="Captain Shatterskull tjänar horden med brinnande lojalitet. Han är stationerad vid Mor'shan Base Camp, på den spända gränsen mellan The Barrens och Ashenvale, och står som ett bålverk mot nattalverna och alliansen. Han organiserar styrkor för att försvara hordens intressen i området.",al={"captain shatterskulls fraktion","vem tjänar shatterskull","shatterskull horden eller alliansen"}},["3a9b17d5"]={q="Vad vill Captain Shatterskull?",a="Shatterskull strävar efter full kontroll över den omstridda norra gränsen. Han beordrar hordens förkämpar att kuva Silverwing Sentinels, som rycker fram från Ashenvale, och kräver militära uppoffringar och krigsheder för att säkerställa att Mor'shans murar förblir ointagliga för fienden.",al={"captain shatterskulls mål","vad behöver shatterskull","varför vill shatterskull döda silverwing"}},["0393c0a4"]={q="Varför är Captain Shatterskull här?",a="Han är stationerad vid Mor'shan Base Camp för att övervaka hordens försvar vid frontlinjen mot nattalverna. Gränsen till Ashenvale är en aktiv brännpunkt för territoriella skärmytslingar, så Shatterskull fick i uppdrag att samordna förstärkningar och slå tillbaka alliansens intrång.",al={"varför är shatterskull vid morshan","captain shatterskulls postering","varför är captain shatterskull i the barrens"}}},fp="20,206,31.335.0,28.128.0,40.110.0,39.163.0,40.131.0"}
P.entries["npc:captain-stoutfist"] = {n="Captain Stoutfist",s="Captain Stoutfist är den dvärgofficer som ansvarar för det militära försvaret av Menethil Harbor i Wetlands. När Dragonmaw-klanen rycker fram från sina fästen i träskmarkerna samordnar Stoutfist försvarsmanövrer och motanfall för att säkra att den viktiga allianshamnen inte faller.",h="Captain Stoutfist är den dvärgofficer som ansvarar för det militära försvaret av Menethil Harbor i Wetlands.",kw={"captain stoutfist","dragonmaw","dun algaz","dvärg","ironforge","menethil harbor","nek'rosh","wetlands"},ang={["class:Warrior"]="Stoutfist är en rättfram dvärgtaktiker som föredrar djärva militära anfall framför försiktiga befästningar. Han skickar krigare till frontlinjen för att slå ut fiendens artilleri och ledarskap.",["faction:Alliance"]="Captain Stoutfist håller stånd vid en av alliansens viktigaste maritima knutpunkter och håller sjövägarna öppna mellan Khaz Modan, Stormwind och avlägsna utposter.",["race:Dwarf"]="Stoutfist förkroppsligar Ironforges härdade beslutsamhet. Han har fått i uppdrag att skydda viktig infrastruktur i låglandet, långt nedanför bergstopparnas trygghet."},sec={{t="Menethils försvarare",b="Menethil Harbor är den främsta djupvattenhamnen som förbinder Ironforge och Stormwind med Wetlands träskiga lågland och havet bortom. Som stadens befälhavare bär Captain Stoutfist det tunga ansvaret för att skydda hamnen, civilbefolkningen och garnisonen mot hoten runtomkring. Träskmarkerna är ökända för sina faror, men det största hotet mot samhället är en organiserad framstöt från renegatorcher."},{t="Dragonmaw-hotet",b="Dragonmaw-klanen har hållit till i Wetlands sedan andra kriget och har börjat flytta sina operationer direkt mot vägarna och passen. Genom att infiltrera Dun Algaz hotar de att skära av landvägen som förbinder Loch Modan och Ironforge med Menethil Harbor. Eftersom trupperna är få förlitar sig Captain Stoutfist på alliansfrivilliga som rekommenderats av Mountaineer Valstag Ironjaw för att hejda framryckningen."},{t="Slaget mot Nek'rosh",b="I stället för att invänta en belägring leder Captain Stoutfist ett aggressivt fälttåg mot orchernas läger. Han beordrar de allierade styrkorna att ta krigsbaner nära Whelgar's Excavation Site, sabotera Dragonmaw-katapulter som förbereds för ett anfall och döda klanens hänsynslöse lokale hövding, Nek'rosh Skullcrusher. Genom att fälla Nek'rosh vill Stoutfist bryta ryggraden på orchernas offensiv innan Menethil Harbor övermannas."}},faq={{q="Vem är Captain Stoutfist?",a="Captain Stoutfist är dvärgarnas militära befälhavare med uppgift att försvara Menethil Harbor. Han samordnar garnisonens försvar, bedömer hoten i området och rekryterar frivilliga för att driva tillbaka fiender som hotar hamnen.",al={"captain stoutfist","stoutfist menethil","menethils kapten"}},{q="Var finns Captain Stoutfist?",a="Han är stationerad i Menethil Harbor, alliansens främsta knutpunkt på Wetlands västkust.",al={"stoutfists plats","var finns captain stoutfist","hitta stoutfist"}},{q="Varför behöver Captain Stoutfist hjälp utifrån?",a="Den lokala garnisonen är hårt ansatt i hela Wetlands. Dragonmaw-orcherna har tagit bergspassen vid Dun Algaz och närmar sig staden, så Stoutfist har inte tillräckligt med ordinarie trupper för att både genomföra anfall och hålla hamnen säker.",al={"varför behöver stoutfist hjälp","menethils försvarsproblem"}},{q="Vem är Nek'rosh Skullcrusher?",a="Nek'rosh Skullcrusher är den hänsynslöse ledaren för Dragonmaw-orcherna i Wetlands. Captain Stoutfist beordrar att han ska dödas för att slå sönder orchernas samordning och skydda Menethil Harbor från ett fullskaligt anfall.",al={"vem är nekrosh","nek'rosh skullcrusher","dragonmaws boss i wetlands"}},{q="Hur hänger Dun Algaz ihop med Captain Stoutfists uppdrag?",a="Dun Algaz är det viktiga bergspasset som förbinder Loch Modan och Ironforge med Wetlands. När Dragonmaw-orcherna trängde in i passet varnade Mountaineer Valstag Ironjaw för att Menethil var hotat och skickade äventyrare till Stoutfist för att förstärka hamnens försvar.",al={"dun algaz stoutfist","sambandet med algazpasset"}},{q="Vilket hot utgör Dragonmaw-katapulterna?",a="Dragonmaw har samlat belägringsvapen för att slå sönder befästningarna och belägra Menethil Harbor direkt. Stoutfist beordrar hjältar att sabotera katapulterna innan de kan rullas inom skotthåll.",al={"nek'roshs plan med katapulterna","dragonmaw-katapulter"}}},fx={["40162abd"]={q="På vems sida står Captain Stoutfist?",a="Captain Stoutfist tjänar alliansen och dvärgriket Ironforge. Han är stationerad vid Menethil Harbor och leder stadens garnison för att skydda denna viktiga hamnstad och resenärer mellan Wetlands och bergen i Khaz Modan.",al={"captain stoutfists fraktion","är stoutfist med i alliansen","vem tjänar stoutfist"}},["31290b24"]={q="Vad vill Captain Stoutfist?",a="Captain Stoutfist vill en gång för alla undanröja hotet från de framryckande Dragonmaw-orcherna. Han vill ta deras krigsbaner från Dragonmaw-lägret, bränna katapulterna som Nek'rosh byggde för att belägra Menethil Harbor och se deras hövding, Nek'rosh Skullcrusher, dödad så att Menethil Harbor förblir tryggt.",al={"captain stoutfists mål","vad behöver stoutfist","stoutfists mål"}},["6891235c"]={q="Varför är Captain Stoutfist i Menethil Harbor?",a="Captain Stoutfist är stationerad i Menethil Harbor som befälhavare med uppgift att försvara hamnen. De strategiska bergspassen vid Dun Algaz är blockerade av fientliga Dragonmaw-orcher. Därför stannar han här för att samla soldater och legosoldater till hamnens försvar.",al={"varför är stoutfist i wetlands","captain stoutfists roll i menethil","varför är stoutfist här"}},["2b51270f"]={q="Vilka har Captain Stoutfist band till?",a="Captain Stoutfist samordnar sig med andra försvarare från alliansen i Khaz Modan och tar emot förstärkningar som skickas via Valstag Ironjaw. Han leder garnisonen vid Menethil Keep och förlitar sig på resande förkämpar från alliansen för att föra striden direkt till Dragonmaw-klanen.",al={"captain stoutfists allierade","vilka arbetar captain stoutfist med","captain stoutfists kontakter"}}},fp="17,199,20.331.0,20.371.0,20.372.1,25.212.0,35.110.0,45.226.0,29.193.0,58.260.0,44.163.0"}
P.entries["npc:captain-thalo-thas-brightsun"] = {n="Captain Thalo'thas Brightsun",s="Vid Ratchets kajer håller Captain Thalo'thas Brightsun en vänlig min mot alliansresenärer. Kaparen tjänar Steamwheedle Cartel och hyser agg mot styrkorna från Theramore vid Northwatch Hold, eftersom de skjuter mot hans fartyg.",h="Vid Ratchets kajer håller Captain Thalo'thas Brightsun en vänlig min mot alliansresenärer.",kw={"the barrens","brightsun","northwatch hold","ratchet","steamwheedle cartel","thalo'dan privateers","thalo'thas brightsun"},ang={["faction:Alliance"]="Brightsun talar vänligt med dig i hamnen, men Theramores styrkor vid Northwatch Hold har fått honom att i hemlighet konspirera med dina fiender.",["faction:Horde"]="Brightsun ger Horden en anledning att anfalla Northwatch Hold och slå ut alliansens marina artilleri längs centrala Kalimdors kust."},sec={{t="Kapare från Ratchet",b="Captain Thalo'thas Brightsun leder Thalo'dan Privateers från Ratchets kajer under Steamwheedle Cartels fana. Ratchet välkomnar köpmän under alla fanor om de har pengar, men handeln längs The Barrens kust hotas av faror. Northwatch Hold ligger strax söder om hamnen, där dess tunga kanoner hotar neutrala sjöleder. Brightsun är vänlig mot besökande resenärer, men garnisonens angrepp på hans flotta har prövat hans tålamod."},{t="Ett privat krig mot Northwatch",b="Ett öppet anfall mot Northwatch Hold skulle kunna hota Ratchets neutralitet, så Brightsun kan inte skicka sin flotta mot fortet. I stället vänder han sig till dugliga legosoldater från Horden för att göra upp. Deras angrepp ska tysta kanonerna och befria hans tillfångatagna besättning. Genom att använda Hordens hjälptrupper skyddar Brightsun sina handelsintressen utan att provocera fram en direkt alliansmotattack mot kartellen eller själv gå öppet in i konflikten."}},faq={{q="Vem är Captain Thalo'thas Brightsun?",a="Captain Thalo'thas Brightsun för befäl över Thalo'dan Privateers från Ratchet i Steamwheedle Cartels tjänst.",al={"thalothas brightsun","vem är brightsun","kapten i ratchet"}},{q="Varför är han arg på Northwatch Hold?",a="Alliansstyrkorna vid Northwatch Hold har upprepade gånger skjutit med tunga kanoner mot Brightsuns handelsfartyg och fängslat hans sjömän, vilket stör handeln längs kusten.",al={"varför anfalla northwatch","brightsuns konflikt med northwatch","varför hata alliance"}},{q="Varför anlitar han bara Horde för att angripa Northwatch?",a="Brightsun förblir diplomatisk mot alliansresenärer i Ratchet, men kan inte be allianslojalister att anfalla sin egen fästning. Horden har skäl att försvaga Theramores militära utpost.",al={"kan alliance göra hans uppdrag","varför bara horde","brightsuns uppdrag för alliance"}},{q="Tillhör han Alliance eller Horde?",a="Brightsun tillhör ingen av fraktionerna. Hans lojalitet ligger hos Steamwheedle Cartel och hans kapare, men hans nuvarande oförrätter för hans intressen i linje med Hordens.",al={"brightsuns fraktion","är brightsun horde","är brightsun neutral"}}},fx={["30395239"]={q="Varför är Captain Thalo'thas Brightsun i Ratchet?",a="Captain Brightsun använder den neutrala hamnen Ratchet som en trygg tillflyktsort och bas för sin besättning, Thalo'dan Privateers. Under Steamwheedle Cartels beskydd kan han bedriva handel, reparera sina fartyg och rekrytera folk längs The Barrens handelsleder till sjöss.",al={"varför är brightsun här","varför är captain thalothas i ratchet","varför är thalothas i ratchet"}},["8eff1400"]={q="Vilka har Captain Thalo'thas Brightsun band till?",a="Brightsun leder sin egen besättning, känd som Thalo'dan Privateers, och samarbetar nära med Gazlowes Steamwheedle Cartel i Ratchet. Han förhåller sig neutral till besökare från alliansen i staden, men hans hårda sjömansfejd med Northwatch Hold har fått honom att söka hjälp från krigare i horden.",al={"brightsuns band","åt vem arbetar thalothas","thalothas brightsuns allierade"}}},fp="28,220,20.444.0,29.428.0,36.114.0,35.163.0,53.193.0,44.180.0"}
P.entries["npc:captured-mountaineer"] = {n="Captured Mountaineer",s="Captured Mountaineer är en dvärg från Ironforge som hålls fången i källaren på Gallows' End Tavern i Brill. Han är bunden och bevakad av Forsaken och tjänar som ofrivilligt försöksobjekt i Royal Apothecary Societys grymma experiment.",h="Captured Mountaineer är en dvärg från Ironforge som hålls fången i källaren på Gallows' End Tavern i Brill.",kw={"en ny farsot","apothecary johaan","källare i brill","captured mountaineer","dvärgfånge","gallows end tavern","spejare från ironforge"},ang={["race:Dwarf"]="Att se en stolt broder från Ironforge inlåst under en Forsaken-taverna och utsatt för fasansfulla alkemiska försök påminner bittert om Forsakens skoningslösa fientlighet mot de levande.",["race:Undead"]="För Forsaken är levande fångar från Alliansen en viktig resurs för Royal Apothecary Societys mål: att fullända en farsot som kan utplåna både Scourge och levande fiender."},sec={{t="En fånge i källaren",b="Undangömd under golvbrädorna på Gallows' End Tavern i Brill sitter den här bergsbestigaren från Ironforge fången, långt från tryggheten i Khaz Modan. Medan gästerna dricker ovanför får Royal Apothecary Society använda honom som ovetande försöksobjekt för sina brygder. Apothecary Johaan och hans kollegor testar hur dödligt deras nya farsot är på levande alliansdvärgar. De använder fången för att mäta hur väl gifterna ger de levande en snabb och plågsam död."}},faq={{q="Vem är Captured Mountaineer?",a="Han är en spejare från Ironforge som tillhör Alliansen och hamnade i Forsakens händer. Just nu sitter han fängslad i källaren på Gallows' End Tavern i Brill.",al={"vem är den här dvärgen","dvärg i brill-taverna","fången dvärg"}},{q="Varför håller Forsaken honom vid liv i källaren?",a="Royal Apothecary Society använder honom som levande försöksobjekt. I stället för att avrätta honom direkt ger apotekare som Johaan honom experimentblandningar för att studera hur de verkar på levande dvärgar.",al={"varför hålla honom vid liv","varför är han i tavernan","vad gör de med dvärgen"}},{q="Vad händer med honom under försöken?",a="Som en del av arbetet med att ta fram en ny farsot tvingas han svälja blandningar som apotekarna brygger. Den dödliga blandningen visar sig snabbt fungera och tar fångens liv, vilket bevisar hur långt giftet har utvecklats.",al={"dör dvärgen","vad händer i en ny farsot"}},{q="Vilka andra träffar honom här nere?",a="Förutom apotekarna som utför experimenten använder Deathguard tavernans källare som fängelsecell. Där håller de tillfångatagna bergsbestigare tills de kan tas om hand på \"lämpligt\" sätt.",al={"vem pratar med dvärgen","renee lauer"}}},fx={["5cefef25"]={q="På vems sida står Captured Mountaineer?",a="Han tillhör Ironforge och den stora alliansen. Dvärgarnas bergsvandrare patrullerar vanligtvis bergspassen i Khaz Modan och omstridda gränser, vilket gör honom till en svuren fiende till de förfallna och horden.",al={"captured mountaineers fraktion","captured mountaineer alliansen eller horden","på vilken sida står bergsvandraren"}},d7cdb16d={q="Vad vill Captured Mountaineer?",a="Fastkedjad i en fuktig källare hoppas han främst överleva och fly. Tyvärr ser Royal Apothecary Society honom inte som en krigsfånge att lösa ut, utan som råmaterial för att förädla deras dödliga nya farsot.",al={"vad vill captured mountaineer","captured mountaineers mål","captured mountaineers önskningar"}}},fp="20,159,24.334.0,32.110.0,55.164.0,37.139.1,38.149.0"}
P.entries["npc:captured-scarlet-zealot"] = {n="Captured Scarlet Zealot",s="Den Captured Scarlet Zealot är en fången korsfarare som hålls inspärrad i källaren under Gallows' End Tavern i Brill. Forsakens apotekare och bybor håller uppsikt över honom, och han tjänar som levande försöksobjekt för Royal Apothecary Societys nya brygder.",h="Den Captured Scarlet Zealot är en fången korsfarare som hålls inspärrad i källaren under Gallows' End Tavern...",kw={"apothecary johaan","brill","captured scarlet zealot","gallows' end tavern","fånge","scarlet crusade","tirisfal glades"},ang={["class:Priest"]="Scarlet-zealoter gör anspråk på ensamrätt till det heliga Ljuset, men fångens orubbliga tro skyddar honom inte mot den bistra verkligheten i Forsakens fångenskap.",["race:Undead"]="För Forsaken i Brill är den här fanatikern i bojor en symbol för de skoningslösa korsfarare som vill utrota dem. Som apotekarens försökskanin gör han större nytta."},sec={{t="En bitter fånge i Brill",b="Inspärrad under Gallows' End Tavern förkroppsligar denna medlem av Scarlet Crusade sin ordens obevekliga fanatism. Även i bojor, omgiven av de odöda som han ser som en styggelse, visar han ingen ånger och åkallar Ljuset för att skydda honom från de vidriga och oheliga varelserna omkring honom. För Forsaken är det ingen barmhärtighetshandling att fånga en levande fanatiker; det ger värdefullt mänskligt försöksmaterial för att bedöma dödligheten hos experimentella farsoter och gifter som Apothecary Johaan utvecklar."}},faq={{q="Varför hålls en Scarlet Zealot vid liv i Brill?",a="Forsaken håller honom fången i källaren under tavernan som levande försöksobjekt för att testa nya gifter och kemiska ämnen som Royal Apothecary Society utvecklar.",al={"varför är scarlet zealot fångad","varför hålla zealoten vid liv","vem är zealoten i brill-källaren"}},{q="Var hittar jag den här fången?",a="Han sitter fängslad i den fuktiga källaren under Gallows' End Tavern, mitt i Brill i Tirisfal Glades.",al={"var finns captured scarlet zealot","scarlet zealots plats","zealot i brill"}},{q="Hur reagerar han på Forsaken omkring sig?",a="Trots att han hålls fången förblir han fanatiskt trotsig. Han ropar att Ljuset ska skydda honom från hans odöda fångvaktare och svär att Scarlet Crusade ska befria Azeroth från dem.",al={"vad säger zealoten","zealotens dialog","renee lauer och zealot"}}},fx={e526a97b={q="Vem är Captured Scarlet Zealot?",a="Han är en tillfångatagen mänsklig soldat som tillhör fanatiska Scarlet Crusade. Han hålls fängslad i den mörka källaren under Gallows' End Tavern i Brill och är ofrivilligt föremål för de förfallnas förhör, hån och alkemiska försök.",al={"vem är captured scarlet zealot","vem är zealoten i källaren","scarlet-fånge i brill"}},["7dde551c"]={q="På vems sida står Captured Scarlet Zealot?",a="Han är fanatiskt lojal mot Scarlet Crusade, en kompromisslös orden som har svurit att utrota alla odöda. Trots att han är bunden och omringad av förfallna fångvaktare vägrar han att ta avstånd från sin trohet. Han spottar ur sig trots och kallar de förfallna onaturliga styggelser.",al={"captured scarlet zealots fraktion","på vilken sida står zealoten","zealotens lojalitet"}},["69888ecc"]={q="Vad vill Captured Scarlet Zealot?",a="Framför allt vill han förgöra både de förfallna och gisslet fullständigt. Hjälplöst fastkedjad vill han inget hellre än att se korståget bränna Undercity och rensa Lordaeron från de hädiska monster han ser där.",al={"zealotens mål","vad vill fången","captured zealots motiv"}},aafac6db={q="Vilka har Captured Scarlet Zealot band till?",a="Han är bunden till Scarlet Crusade och lyder dess befälhavare, som för krig i Tirisfal Glades. Här på plats står han under noggrann uppsikt av Apothecary Johaan och gästerna på Gallows' End Tavern, som behandlar honom som en fientlig fånge och ett försöksobjekt för alkemiska experiment.",al={"captured zealots kontakter","vem lyder zealoten under","captured zealots band"}}},fp="23,155,25.457.0,44.164.0,30.96.0,45.163.0"}
P.entries["npc:carendin-halgar"] = {n="Carendin Halgar",s="Carendin Halgar är en framstående tränare i demonologi för de Fördömda och håller till i Magic Quarter i Undercity. Han är bitsk och ökänd för sitt korta tålamod, och ansvarar för utbildningen av nybörjare inom de mörka konsterna. Han lär blivande demonologer att kuva mäktiga demoniska väsen från Twisting Nether, bland annat genom ritualer för att binda Voidwalkers och Succubi.",h="Carendin Halgar är en framstående tränare i demonologi för de Fördömda och håller till i Magic Quarter i...",kw={"carendin halgar","väsen från tomrummet","de fördömda","halgar","magic quarter","succubus","bindningen","tränare","undercity","voidwalker","demonolog"},ang={["class:Warlock"]="Carendin Halgar är en viktig mentor i Lordaeron och vägleder demonologer genom de hårda prövningar som krävs för att betvinga och binda både Voidwalkers och Succubi.",["faction:Horde"]="Carendin är den främsta östliga länken för demonologer i Horde och samordnar utbildningen med andra mörka utövare på andra sidan havet i Kalimdor.",["race:Undead"]="Carendin speglar de Fördömdas kompromisslösa anda. Han visar ingen nåd eller tvekan och ser demoner enbart som verktyg att bryta ner och utnyttja."},sec={{t="Mästare i de mörka konsterna",b="I det giftiga dunklet i Undercitys Magic Quarter undervisar Carendin Halgar dem som utforskar Twisting Nether. Han kräver fokus och lydnad och tolererar inte misslyckanden, tvekan eller svaghet. Under hans vakande blick drivs demonologer bortom enkla besvärjelser och mot den farliga konsten att frammana demoner och manipulera själar, vilket befäster de Fördömdas hänsynslösa syn på demonisk träldom."},{t="Att kuva Nether",b="Carendins undervisning kretsar kring att binda allt farligare demoner till besvärjarens vilja. Han skickar sina elever över Lordaeron och längre bort för att hämta uråldriga runor, runstenar och mortals destillerade, rena essens till förrädiska besvärjelsecirklar. Oavsett om de ska befalla ett skuggväsen från tomrummet eller locka en förförisk succubus till underkastelse ser Carendin till att demonologen betvingar demonen innan den slukar sin mästare."}},faq={{q="Var hittar man Carendin Halgar?",a="Carendin Halgar finns i Magic Quarter i Undercity, bland andra som utövar fel- och skuggmagi.",al={"carendin halgar plats","plats för demonologtränare i undercity","var finns halgar"}},{q="Vilken roll har Carendin Halgar för demonologer?",a="Han är mentor och uppdragsgivare för demonologer i Horde och lär dem ritualerna som krävs för att frammana och binda mäktiga demoner permanent, som Voidwalker och Succubus.",al={"vad gör carendin","halgars uppgift","carendins uppdrag"}},{q="Hur är Carendin Halgar som person?",a="Han är ökänd för att vara rakt på sak, krävande och helt utan tålamod. Han förväntar sig snabba resultat av sina elever och avskyr tidsspillan och ursäkter.",al={"halgars temperament","är carendin trevlig","carendin halgars bakgrund"}},{q="Varför behöver Carendin rena hjärtan till besvärjelseritualer?",a="I lektionerna om att frammana en succubus ger Halgars assistent Godrick Farsan noviserna i uppdrag att skaffa de renas obefläckade hjärtan. Deras oskuld och essens används som bete för att locka in och fånga den demoniska varelsen i en bindande cirkel.",al={"syftet med de renas hjärtan","carendin och att frammana succubus","varför rena hjärtan"}},{q="Har Carendin Halgar kontakt med demonologer utanför Undercity?",a="Ja. Han skickar lovande elever till Strahad Farsan i The Barrens för att fortsätta sina studier.",al={"carendins kontakter","halgar orgrimmar","gan'rul bloodeye carendin"}},{q="Vem skickar Carendin avancerade demonologer till?",a="När en novis visar att hen behärskar grundläggande demoner tillräckligt väl skickar Carendin hen vidare för mer esoterisk undervisning, till exempel till den excentriske besvärjaren Strahad Farsan i The Barrens.",al={"sökandet efter strahad","vem skickar carendin dig till","halgars nästa mentor"}}},fx={ba046d55={q="Vad vill Carendin Halgar?",a="Carendin vill forma disciplinerade och skickliga häxmästare som utan tvekan eller svaghet styr demoner. Han kräver att de noggrant följer bindningsritualerna och sätter sina elever på hårda prov för att försäkra sig om att de kontrollerar sina åkallade tjänare i stället för att falla offer för dem.",al={"vad vill carendin","carendins motiv","carendins mål"}},ea246188={q="Varför är Carendin Halgar här?",a="Han är stationerad i Undercitys Magic Quarter för att vägleda nyblivna häxmästare bland de Förfallna. Under ruinerna av Capital City övervakar han de farliga åkallelser som krävs för att binda mäktigare undersåtar från Twisting Nether i sin tjänst.",al={"varför är carendin i undercity","varför är carendin här","varför befinner sig carendin här"}},["743d4acc"]={q="Vilka har Carendin Halgar band till?",a="Carendins assistent är Godrick Farsan. Han skickar också elever till åkallaren Strahad Farsan i The Barrens för vidare undervisning.",al={"carendins allierade","carendins band","vem arbetar carendin med"}},["3b100529"]={q="Vem är Carendin Halgar?",a="Carendin Halgar är en framstående tränare i svartkonst för de förfallna och bor i Magic Quarter i Undercity. Han är känd för sitt stränga och otåliga sätt och lär blivande utövare de mörka konsterna att åkalla och binda demoniska väsen till sin vilja.",al={"vem är carendin halgar","carendin halgar i berättelsen","vem är halgar"}},b7e57faa={q="På vems sida står Carendin Halgar?",a="Carendin är lojal mot de förfallna och horden. Han verkar öppet från Undercity och använder sin mörka kunskap för att stärka den magiska kraften hos Lady Sylvanas anhängare mot deras gemensamma fiender i Lordaeron.",al={"carendin halgars fraktion","vem tjänar carendin","är carendin lojal mot sylvanas"}}},fp="15,213,23.313.0,22.349.1,35.112.0,49.122.0,43.124.0,60.203.0,66.105.0,48.159.0"}
P.entries["npc:caretaker-folsom"] = {n="Caretaker Folsom",s="Vid Stormwinds kanaler nära parken tar Caretaker Folsom hand om resterna av en adlig familj. Han skötte en gång Flintridge-godset. Nu säljer han det som överlevde den blodiga tragedin.",h="Vid Stormwinds kanaler nära parken tar Caretaker Folsom hand om resterna av en adlig familj.",kw={"kanaler","caretaker folsom","flintridge","folsom","mistmantle","park","stalvan","stormwind"},ang={["faction:Alliance"]="Som Alliance-utredare på jakt efter Duskwoods mest ökända mördare kan du vända dig till Folsom, en levande länk till Flintridge-hushållets sista dagar."},sec={{t="Ett hus i ruiner",b="Folsom följde i sin fars fotspår och började arbeta som förvaltare på Flintridge-godset. Det livet tog slut när hushållet massakrerades. Herrgården övergavs, och till slut tog de återstående medlen slut. Folsom fick vaka över det som fanns kvar och skickar nu familjens överlevande arvegods och ägodelar på auktion."},{t="Band till en mörk berättelse",b="De som utreder Stalvan Mistmantles blodiga historia hänvisas ofta till Folsom vid Stormwinds kanalstråk. Sorgen tynger honom, och han talar ogärna. Han förvarar kvarvarande ägodelar och dokument från Flintridge som avslöjar Stalvans oroande fall och hans slutliga försvinnande i Duskwoods skuggor."}},faq={{q="Vem är Caretaker Folsom?",a="Caretaker Folsom tjänstgör i Stormwind City och skötte en gång familjen Flintridges gods. Efter massakern som dödade hela familjen fick han ansvaret för deras återstående egendom.",al={"folsom","vem är folsom","caretaker folsom berättelse"}},{q="Var hittar jag Caretaker Folsom?",a="Du hittar Caretaker Folsom längs kanalernas stenlagda stråk i Stormwind City, nära ingången till parken.",al={"var finns caretaker folsom","folsoms plats","caretaker folsom stormwind"}},{q="Vad hände med familjen Flintridge?",a="Familjen Flintridge massakrerades på sitt gods för många år sedan. Eftersom inga arvingar fanns kvar som kunde göra anspråk på det bommades herrgården igen, och till slut tog medlen slut.",al={"flintridge-mordet","vad hände med flintridge","vem dödade familjen flintridge"}},{q="Varför säljer Folsom familjens arvegods?",a="Familjen Flintridges återstående medel tog till slut slut. Folsom skickar nu det som finns kvar av godsets ägodelar på auktion.",al={"varför auktion","flintridge-auktion","folsoms auktion"}},{q="Vilken roll har han i The Legend of Stalvan?",a="Folsom hjälper dem som försöker lägga pusslet kring Stalvan Mistmantles tragedi genom att dela med sig av kvarvarande personliga tillhörigheter och ledtrådar från Flintridge-herrgården.",al={"stalvan-uppdrag folsom","the legend of stalvan folsom"}}},fx={["2b9b56eb"]={q="Vem är Caretaker Folsom lojal mot?",a="Caretaker Folsom är en lojal undersåte till Stormwind och en hängiven tjänare åt den olycksdrabbade familjen Flintridge. Han hyser inget agg och har inga dolda politiska lojaliteter. Han tillbringar sina dagar vid stadens kanaler och försöker hedra minnet av hushållet och sköta dess sista angelägenheter, precis som han och hans far troget tjänade det.",al={"caretaker folsoms fraktion","vem tjänar folsom","folsoms lojalitet"}},bbc99921={q="Varför är Caretaker Folsom här?",a="Du hittar Caretaker Folsom vid kanalerna i Stormwind eftersom familjen Flintridges tillgångar helt har sinat. Efter familjens våldsamma bortgång tvingades han avveckla dödsboet. Han är kvar i huvudstaden och sköter den dystra uppgiften att inventera och auktionera ut familjens kvarvarande arvegods.",al={"varför är folsom i stormwind","varför är caretaker folsom här","vad förde folsom hit"}},["8f9af06f"]={q="Vilka har Caretaker Folsom band till?",a="Folsom är bunden till det adliga godset Flintridge genom blodsband och tjänst. Hans far var godsförvaltare före honom, och Folsom ägnade sitt liv åt att sköta hushållet tills Stalvan Mistmantle ödelade det och slaktade hela familjen.",al={"folsoms band","vem har folsom band till","folsom och flintridge"}}},fp="16,184,16.277.0,19.321.1,24.182.0,34.112.0,39.152.1,43.129.0,42.139.0"}
P.entries["npc:carolai-anise"] = {n="Carolai Anise",s="Carolai Anise är en excentrisk alkemist bland de Förfallna som bor i byn Brill i Tirisfal Glades. Hon utbildar nybörjare i alkemi, men hennes farliga brygder har fått de lokala vakterna att mumla nervöst.",h="Carolai Anise är en excentrisk alkemist bland de Förfallna som bor i byn Brill i Tirisfal Glades.",kw={"alkemi","apotekare","brill","carolai anise","lärare för de förfallna","tirisfal glades"},ang={["profession:Herbalism"]="Samlare som skördar vilda växter i Tirisfal tar ofta med fredsblomma, silverblad och jordrot till Carolai för att hon ska förädla dem till kraftfulla blandningar.",["race:Undead"]="För nybefriade Förfallna som lär sig att hantera reagenser ger Carolai en grundläggande introduktion till alkemins hantverk i Tirisfal Glades."},sec={{t="Ett oberäkneligt hantverk",b="Carolai Anise håller till i Brill och ägnar sitt odöda liv åt alkemi, ett oberäkneligt hantverk. Många forskare bland de Förfallna arbetar under Royal Apothecary Societys dystra uppdrag, men Carolai ägnar sig åt sina egna märkliga brygder mitt i bosättningen. Hennes oberäkneliga experiment och rykande destillationskolvar är så ökända att Deathguards som håller vakt över Brill öppet muttrar att hon verkar fast besluten att spränga sitt eget hus i luften."}},faq={{q="Vem är Carolai Anise?",a="Carolai Anise är en odöd alkemilärare som bor i bosättningen Brill i Tirisfal Glades. Hon lär blivande Förfallna att brygga drycker, elixir och oljor.",al={"carolai anise","alkemist i brill","vem är carolai"}},{q="Var hittar jag henne?",a="Du hittar henne i Brill, den främsta staden för de Förfallna i centrala Tirisfal Glades. Hon arbetar med sina alkemiförnödenheter i en av stadens byggnader.",al={"var finns carolai anise","carolai anises plats","var finns alkemiläraren i brill"}},{q="Varför klagar Deathguards på henne?",a="De lokala Deathguards varnar för att Carolais instabila alkemiexperiment bara väntar på att orsaka en olycka. De skämtar ofta om, eller oroar sig för, att hon till slut ska spränga hela sitt hus i luften.",al={"deathguards om carolai","spränga huset i luften","carolai anise fara"}}},fx={d66f68b4={q="Vem är Carolai Anise lojal mot?",a="Hon är lojal mot de Förfallna och den Mörka Damen Sylvanas Windrunner. Hon verkar öppet från bosättningen Brill och tjänar de Förfallnas gemenskap i stort genom att undervisa andra odöda och resande ur Horde i grunderna i bryggning och destillering.",al={"carolai anises fraktion","är carolai anise förfallen","vem tjänar carolai anise"}},dbcf2ddc={q="Vad vill Carolai Anise?",a="Carolai är helt uppslukad av sitt alkemiska hantverk och sina flyktiga experiment. Hon lär ut sitt yrke till lärlingar, men verkar fast besluten att fortsätta med vårdslösa, bubblande brygder. Den lokala stadsvakten oroar sig så mycket att hennes experiment ska jämna verkstaden med marken.",al={"carolai anises motiv","vad gör carolai anise","carolai anises mål"}},["917b8b51"]={q="Varför är Carolai Anise i Brill?",a="Hon bor i Brill för att lära nyvakna Förfallna och resande ur Horde från Deathknell alkemi. Tirisfal Glades erbjuder gott om lugn och råvaror för hennes brygder och låter henne driva sitt flyktiga hantverk till farliga ytterligheter.",al={"varför är carolai anise i brill","varför är carolai anise i tirisfal glades","varför är carolai anise här"}}},fp="13,85,16.382.0,21.138.0,21.121.0,42.153.0"}
P.entries["npc:cazul"] = {n="Cazul",s="I The Cleft of Shadow vägleder Cazul unga häxmästare mot större makt över demoner. Han är blind och uråldrig och bevarar gamla orciska häxmästartraditioner.",h="I The Cleft of Shadow vägleder Cazul unga häxmästare mot större makt över demoner.",kw={"blind cazul","cazul","cleft of shadow","demonologi","orgrimmar","voidwalker","häxmästare"},ang={["class:Warlock"]="Som häxmästare i Horde kan du söka Cazuls vägledning i The Cleft of Shadow när du vill binda djupare krafter från Nether.",["race:Orc"]="Som orc ser du i Cazul hur mörk magi lever vidare bland ditt folk. Han utövar den på avstånd från Thralls hedersvakts vaksamma blick."},sec={{t="Ögon i mörkret",b="Cazul väntar i The Cleft of Shadow under Orgrimmar, där blivande häxmästare söker hans råd. Trots sin blindhet känner han strömmarna i Twisting Nether och hör demonernas viskningar. De som vill bemästra sitt hantverk och binda farligare tjänare skickas ofta till honom. Synen är borta, men hans arkanmagi finns kvar."}},faq={{q="Vem är Cazul?",a="Cazul är en åldrad, blind orcisk häxmästare som bor i The Cleft of Shadow under Orgrimmar. Han ger blivande häxmästare råd om mörk trolldom och demonologi.",al={"vem är cazul","cazuls historia","blind npc cazul"}},{q="Varför är Cazul blind?",a="Inga uppgifter berättar varför Cazul är blind.",al={"varför är cazul blind","hur förlorade cazul synen"}},{q="Vilken roll har Cazul för häxmästare?",a="Cazul vägleder häxmästare som vill utveckla sitt hantverk, särskilt dem som lär sig att frammana och binda en succubus.",al={"cazuls uppdrag","vad lär caso?","häxmästaruppdrag cazul"}}},fx={["9bd6f5fc"]={q="Vem är Cazul lojal mot?",a="Cazul står på Horde:s sida och har sitt hem i Orgrimmars skuggiga underjordiska enklav. De som utövar mörk magi verkar under vaksam tillsyn under krigshövdingens stad, men han delar fridfullt sin uråldriga kunskap med Horde-utövare som söker upp honom.",al={"cazuls fraktion","tillhör cazul horde","cazuls lojalitet"}},f5d7dff7={q="Varför är Cazul i Cleft of Shadow?",a="Cleft of Shadow är det avsedda kvarteret där Orgrimmars utövare av mörkare magi bedriver sina studier, avskilda från allmänheten. Cazul stannar där för att undervisa och vägleda häxmästare som behöver uråldrig kunskap och förmåga att bemästra åkallade vidunder.",al={"varför är cazul här","cazul orgrimmar cleft","varför är cazul i cleft of shadow"}}},fp="5,155,16.336.0,13.151.0,19.35.0,39.110.0"}
P.entries["npc:cerellean-whiteclaw"] = {n="Cerellean Whiteclaw",s="Cerellean Whiteclaw är en nattalv som vilar nära hamnen och värdshuset i Auberdine i Darkshore. Han hemsöks av minnet av sin förlorade kärlek från den uråldriga Sundering och kämpar för att ge hennes rastlösa ande ro.",h="Cerellean Whiteclaw är en nattalv som vilar nära hamnen och värdshuset i Auberdine i Darkshore.",kw={"ameth'aran","anaya dawnrunner","auberdine","cerellean whiteclaw","darkshore","för evig kärlek","spöke","sundering"},ang={["class:Druid"]="Liksom många druider gick Cerellean in i den långa slummern tillsammans med Malfurion Stormrage, men The Emerald Dream kunde inte tvätta bort hans jordiska hjärtesorg.",["race:NightElf"]="Cerelleans tragiska historia speglar de djupa, bestående ärr som War of the Ancients och den stora Sundering lämnade efter sig hos kaldorei."},sec={{t="En kärlek som slets itu",b="För tiotusen år sedan, före War of the Ancients, delade Cerellean Whiteclaw sitt liv med Anaya Dawnrunner. När den demoniska invasionen slet det uråldriga Kalimdor i stycken omkom Anaya när hennes stad, Ameth'Aran, förstördes. Förkrossad av sorg följde Cerellean Malfurion Stormrage in i den långa druidiska slummern, men The Emerald Dream gav honom föga lindring från minnet av henne. När han vaknade årtusenden senare vandrade han omkring i Darkshore, omtöcknad av sorg, och upptäckte att Anayas spöke fortfarande var bundet till stenarna där hon föll."},{t="En vädjan om befrielse",b="Cerellean längtar efter att ge Anaya ro, men står inte ut med sorgen över att själv slå ner hennes plågade skugga. Han ber förbipasserande resenärer att bege sig söderut till de hemsökta ruinerna av Ameth'Aran, ge hennes ande ro och hämta hennes hängsmycke. När Anayas skugga befriats besöker hon Cerellean en kort stund vid hamnen i Auberdine, försäkrar honom om sin eviga kärlek och lovar att de en dag ska återförenas i livet efter detta."}},faq={{q="Vem är Cerellean Whiteclaw?",a="Cerellean Whiteclaw är en uråldrig nattalv som bor nära hamnen i Auberdine i Darkshore. Han sörjer sin förlorade kärlek, Anaya Dawnrunner, som omkom under War of the Ancients för tiotusen år sedan.",al={"vem är cerellean","cerellean whiteclaw","alv vid auberdines hamn"}},{q="Vem var Anaya Dawnrunner?",a="Anaya Dawnrunner var Cerelleans älskade och bodde i den uråldriga staden Ameth'Aran. Hon dödades under War of the Ancients när staden lades i ruiner, och hennes plågade ande dröjde sig kvar bland spillrorna i tusentals år.",al={"anaya dawnrunner","cerelleans kärlek","cerelleans älskade"}},{q="Varför ger inte Cerellean Anayas ande ro själv?",a="Cerellean är så djupt fäst vid henne och så förkrossad att han saknar den känslomässiga styrkan att själv konfrontera och förinta hennes spöklika gestalt. Han förlitar sig på medkännande resenärer för att ge henne den slutliga befrielsen.",al={"varför slåss inte cerellean mot anaya","varför behövs en äventyrare"}},{q="Var ligger ruinerna av Ameth'Aran?",a="Ruinerna av Ameth'Aran ligger i södra Darkshore, öster om huvudvägen. Området hemsöks av uråldriga kaldorei-spöken som omkom under den stora Sundering.",al={"var ligger ameth'aran","var anaya befinner sig","var är anaya"}}},fx={["20d93eae"]={q="Vem är Cerellean Whiteclaw lojal mot?",a="Cerellean är en kaldorei-medborgare som står på nattalvernas och Alliances sida. Han står fridfullt i Auberdine, upptagen av sin personliga sorg snarare än politiska eller militära ambitioner. Han söker hjälp från alla resande som är villiga att bistå honom.",al={"cerellean whiteclaws fraktion","vem tjänar cerellean","står cerellean på alliances eller hordes sida"}},f9b8a3f3={q="Vad vill Cerellean Whiteclaw?",a="Cerellean vill ge sin förlorade kärleks ande, Anaya Dawnrunner, evig frid. Han plågas av att se hennes spöke bundet till ruinerna av Ameth'Aran. Han söker någon stark nog att förgöra hennes vålnad och återlämna hennes hänge till honom, så att hon befrias från sin urgamla plåga.",al={"cerelleans mål","vad behöver cerellean","cerellean whiteclaws uppdragsmål"}},["838b08c5"]={q="Varför är Cerellean Whiteclaw i Darkshore?",a="Efter att ha vaknat från årtusenden i The Emerald Dream tillsammans med Malfurion Stormrage vandrade Cerellean omkring på Kalimdor i sorgedimma. Sorgen drog honom tillbaka mot ruinerna av Ameth'Aran, där Anaya dog. Han dröjer nu nära hamnen i Auberdine, oförmögen att gå vidare.",al={"varför är cerellean i auberdine","varför befinner sig cerellean whiteclaw här","varför är cerellean här"}}},fp="19,191,19.500.0,18.388.1,27.187.0,25.235.0,57.143.0,34.152.0"}
P.entries["npc:charlga-razorflank"] = {n="Charlga Razorflank",s="Charlga Razorflank, vida conocida como la Bruja de Kraul, es una geomante feroz y astuta que gobierna Razorfen Kraul. Bajo su mando, los jabaespines de Razorfen expulsaron a los tauren de la parte meridional de The Barrens mediante una expansión despiadada, afirmando luchar en nombre de su dios caído, Agamaggan.",h="Charlga Razorflank, vida conocida como la Bruja de Kraul, es una geomante feroz y astuta que gobierna...",kw={"agamaggan","the barrens","charlga","bruja","geomante","kraul","jabaespín","razorflank"},ang={["class:Shaman"]="Aunque Charlga domina potentes artes geománticas, su distorsión de los elementos representa una corrupción oscura de las tradiciones primigenias sagradas.",["faction:Horde"]="Acabar con Charlga es fundamental para proteger las rutas de caravanas y los campamentos de la parte meridional de The Barrens frente a los implacables grupos de guerra jabaespines.",["race:Tauren"]="La expansión agresiva de Charlga expulsó a tu pueblo de sus territorios ancestrales por toda la parte meridional de The Barrens. Derrotarla es cuestión de supervivencia y recuperación para tu tribu."},sec={{t="La Bruja de Kraul",b="Charlga Razorflank gobierna desde los enmarañados y enormes zarzales de Razorfen Kraul. Su pueblo la venera como una maestra geomante cuya magia experimental no tiene igual entre los jabaespines. Charlga unió a sus parientes divididos y los convirtió en una amenaza letal. Dominó la tierra primigenia y las espinas gigantes que brotan de los restos del semidiós Agamaggan, y transformó el laberíntico Kraul en una fortaleza impenetrable."},{t="Expansión y traición",b="Charlga dirigió incursiones violentas y constantes contra tribus rivales y aldeas de la Horda por toda la parte meridional de The Barrens, hasta expulsar a los tauren de sus tierras ancestrales. Pero su verdadera ambición va más allá: Charlga negoció en secreto con emisarios de la Plaga de no-muertos, y cambió la devoción de su desprevenida tribu por un poder antinatural y alianzas insidiosas."}},faq={{q="¿Quién es Charlga Razorflank?",a="Charlga Razorflank es la jefa y geomante suprema de la tribu de jabaespines de Razorfen. Tiene su guarida en las profundidades de Razorfen Kraul, en la parte meridional de The Barrens.",al={"historia de charlga","quién es la bruja de kraul","jefe de razorfen"}},{q="¿Qué magia usa Charlga?",a="Es una geomante de talento excepcional que manipula la tierra elemental y las enormes zarzas de sangre nacidas del semidiós Agamaggan.",al={"habilidades de charlga","poderes de geomante"}},{q="¿Por qué atacaron los jabaespines a los tauren en The Barrens?",a="Bajo el mando de Charlga, los jabaespines de Razorfen Kraul atacaron a tribus rivales y aldeas de la Horda, y expulsaron a los tauren de la parte meridional de The Barrens.",al={"por qué los jabaespines odian a los tauren","guerra de jabaespines en the barrens"}},{q="¿Qué relación tiene Charlga con Razorfen Downs?",a="Razorfen Downs creció de las mismas enredaderas imponentes que su Kraul y es la capital tradicional de los jabaespines, hogar de la tribu Death's Head y sus sumos sacerdotes. Charlga gobierna Kraul, no Downs.",al={"charlga downs","charlga razorfen downs"}},{q="¿Por qué quiere la Horda que muera?",a="Los tauren y sus aliados de la Horda la consideran una amenaza existencial inmediata por sus incursiones implacables, el robo de sus tierras y sus peligrosos tratos con fuerzas oscuras.",al={"misión de la bruja de kraul","por qué matar a charlga"}}},fx={["29fd1a6b"]={q="Vem är Charlga Razorflank lojal mot?",a="Charlga leder Razorfen-kvilboarna, men hon har äventyrat sitt folk genom att förhandla med Scourge. Hon säger sig kämpa för kvilboarnas ras och för att återuppliva deras galtgud Agamaggan. I hemlighet har hon dock lierat sin stam med de odöda sändebud som Amnennar the Coldbringer skickat och tjänar mörka intressen som hennes anhängare inte känner till.",al={"charlga razorflanks fraktion","vem tjänar charlga","vilken sida står charlga razorflank på"}},["98b63c0f"]={q="Vad vill Charlga Razorflank?",a="Charlga strävar efter total makt över södra The Barrens och fullständig makt åt sin stam. Hon driver sitt folk till blodiga räder mot rivaliserande stammar, byar tillhörande Horde och taurerna. I hemlighet har hon också förhandlat med Scourges agenter och lierat sin ovetande stam med de odöda i något ondskefullt syfte.",al={"charlgas mål","vad vill charlga","charlga razorflanks motiv"}},["581cf8d6"]={q="Varför är Charlga Razorflank här?",a="Razorfen Kraul är Razorfen-kvilboarnas förfäders hem, som vuxit fram ur de kolossala törnsnår där Agamaggan föll under War of the Ancients. Som stammens främsta häxa och hövding har Charlga sitt näste längst in i Kraul, där hon samordnar sina krigsskaror och studerar geomantiska kristaller.",al={"varför är charlga i razorfen kraul","varför befinner sig charlga razorflank här","var är charlga"}},["98250d5e"]={q="Vilka har Charlga Razorflank band till?",a="Charlga har direkta band till Scourge-styrkorna som hemsöker Razorfen Downs. Hon förhandlar med sändebud från Amnennar the Coldbringer, häxmästaren som i hemlighet utövar kontroll över Death's Head-kvilboarna. Därmed lierar hon sin ovetande stam med de odödas led.",al={"charlgas allierade","charlgas band","vem arbetar charlga med"}},f526ba0c={q="Varför är Charlga Razorflank berömd eller fruktad?",a="Charlga fruktas som häxan i Kraul och besitter experimentella geomantiska krafter som ingen av hennes likar kan mäta sig med. Under hennes järnhårda ledning förde Razorfen-kvilboarna vilda fälttåg som drev bort de nomadiska taurerna från hela södra The Barrens. Det gav henne ett dödligt rykte över hela Kalimdor.",al={"varför fruktas charlga","hur mäktig är charlga","charlga razorflanks krafter"}}},fp="18,177,22.366.0,22.325.1,26.122.0,28.131.0,54.131.0,47.209.0,33.174.0"}
P.entries["npc:chef-breanna"] = {n="Chef Breanna",s="Chef Breanna är kock på Lakeshires lokala värdshus i Redridge Mountains. Hon har fått i uppgift att mätta Stormwind-soldaterna som är stationerade där för att skydda den hårt ansatta staden vid sjön. Hon förlitar sig på rejäl, lokal mat för att hålla försvararna på benen.",h="Chef Breanna är kock på Lakeshires lokala värdshus i Redridge Mountains.",kw={"breanna","chef breanna","kock","garnison","gulasch","lakeshire","redridge goulash"},ang={["faction:Alliance"]="Utan Chef Breanna som förser soldaterna vid bron och stadens försvarsområde med mat skulle Lakeshires hårt pressade garnison snart duka under av utmattning inför de skoningslösa anfallen från orcher och gnoller.",["profession:Cooking"]="Breannas påhittiga recept på Redridge Goulash visar hur en kock vid gränsen kan förvandla farliga lokala rovdjur – spindlar, kondorer och goretusks – till en rejäl måltid som håller en militär utpost vid liv."},sec={{t="Mat till Lakeshires försvarare",b="Chef Breanna driver en restaurang i nordvästra Lakeshire tillsammans med sina assistenter Crystal Boughman och Gretchen Vogel. Hon bär det tunga ansvaret för att förse hela den lokala bataljonen med mat. Lakeshire är belägrat av Blackrock-orcher, gnoller och murlocer. Därför är det viktigt att hålla Stormwinds underbemannade garnison stark och vid gott mod. Hennes specialitet, Redridge Goulash, görs på vilt och bestar från de omgivande bergsryggarna. På så sätt blir farliga rovdjur från vildmarken till mat åt stadens utmattade vakter."}},faq={{q="Vem är Chef Breanna?",a="Chef Breanna är kock i Lakeshire och driver stadens kök i den nordvästra delen av bosättningen. Hon har fått i uppgift att laga mat åt Stormwind-soldaterna som försvarar Redridge Mountains.",al={"chef breanna","breanna lakeshire","vem är breanna"}},{q="Vad behöver Chef Breanna hjälp med?",a="Hon behöver lokalt viltkött för att laga Redridge Goulash åt garnisonen. Äventyrare hjälper henne genom att samla Tough Condor Meat, goretusksnynen och Crisp Spider Meat från vildmarken runt Lakeshire.",al={"breannas uppdrag","ingredienser till redridge goulash","vad vill hon ha"}},{q="Vem arbetar med Chef Breanna?",a="På hennes livliga värdshus arbetar Crystal Boughman och Gretchen Vogel. De hjälper henne att sköta restaurangen och ta hand om hungriga stadsbor och soldater.",al={"breannas medhjälpare","crystal boughman","gretchen vogel"}}},fx={["33f751f4"]={q="Vem är Chef Breanna lojal mot?",a="Chef Breanna är lojal mot Alliance och kungariket Stormwind. Hon driver sitt kök i Lakeshire och ansvarar direkt för provianteringen av Stormwinds lokala bataljon, som är stationerad där för att försvara staden och dess omgivande gränser.",al={"chef breannas fraktion","vem tjänar breanna","tillhör chef breanna alliance"}},f2dfd1fc={q="Varför är Chef Breanna här i Lakeshire?",a="Breanna driver stadens restaurang i nordvästra Lakeshire. Hennes främsta uppgift är att hålla de lokala soldaterna från Stormwind mätta och redo för tjänst medan hoten kring Redridge växer. Hon använder färska lokala råvaror för att försörja garnisonen.",al={"varför är breanna i redridge","varför är chef breanna i lakeshire","breannas uppgift i lakeshire"}}},fp="12,188,29.406.0,20.143.0,38.186.0,28.161.0"}
P.entries["npc:chef-grual"] = {n="Chef Grual",s="Chef Grual är kock på Scarlet Raven Tavern i Darkshire. I en avskild stad som kvävs av dimma och monster gör Grual sitt bästa för att mätta Night Watch och trötta resenärer, även om hans val av ingredienser väcker höjda ögonbryn.",h="Chef Grual är kock på Scarlet Raven Tavern i Darkshire.",kw={"chef grual","crab cakes","darkshire","duskwood","grual","jitters","scarlet raven tavern","vargspett"},ang={["faction:Alliance"]="Grual arbetar på Scarlet Raven Tavern i Darkshire och håller Alliances utmattade försvarare mätta trots bristen på regelbundna förnödenhetskaravaner från Stormwind.",["profession:Cooking"]="Grual är en dyster lektion i improvisation i köket och visar att en kock i isolerade trakter använder det lokala vilt som går eller krälar genom träden.",["race:Human"]="Liksom många av Darkshires kvarvarande invånare visar Grual en dyster, envis motståndskraft och anpassar sig till den skuggiga skogens fasor på sitt eget pragmatiska sätt."},sec={{t="Matlagning under belägring",b="Att driva ett matställe i Darkshire är en dyster uppgift. Förbindelserna med Westfall och Stormwind utsätts ständigt för angrepp från stråtrövare, vargar och odöda, så färska förnödenheter är i princip obefintliga. Grual får klara sig med vad vildmarken erbjuder. Från vargkött till köttrester som lokala äventyrare släpar in genom dörren lagar Grual mat med den pragmatism nöden kräver."},{t="Hemliga ingredienser",b="Grual är ökänd för sina specialrätter, framför allt sina berömda Dusky Crab Cakes och kryddade vargspett. Eftersom kustkrabbor inte finns i närheten av Duskwoods dystra inlandsskogar bygger hans Crab Cakes på ett ganska motbjudande substitut: de slemmiga benen från traktens Venom Web Spiders. Oavsett om gästerna inser att de äter spindelkött eller helt enkelt föredrar att inte fråga håller Grual köket igång utan ursäkter."}},faq={{q="Vem är Chef Grual?",a="Chef Grual är en mänsklig kock som arbetar på Scarlet Raven Tavern i Darkshire. Han lagar mat åt stadens försvarare, resenärer och flyktingar som gömmer sig undan farorna i Duskwood.",al={"chef grual","grual darkshire","kock i darkshire"}},{q="Var hittar jag Chef Grual?",a="Han står i bakrummet och köket på Scarlet Raven Tavern i centrala Darkshire, längs huvudvägens södra kant.",al={"gruals plats","var finns chef grual","hitta chef grual"}},{q="Vad innehåller Dusky Crab Cakes egentligen?",a="Trots namnet finns det inga krabbor i Duskwood. Chef Grual ersätter dem med slemmiga spindelben från de monstruösa spindlar som hemsöker skogarna runt omkring och finhackar dem till biffar som liknar skaldjur.",al={"ingredienser i crab cake","spindel-crab cakes","vad innehåller dusky crab cakes"}},{q="Vilka uppdrag erbjuder Chef Grual?",a="Grual ber resenärer att samla färska ingredienser från vildmarken, bland annat vargkött till hans Seasoned Wolf Kabobs och spindelben till hans Dusky Crab Cakes. Han lagar också Dusky Crab Cakes åt Jitters, en svältande man som gömmer sig i Duskwood.",al={"gruals uppdrag","chef gruals recept"}},{q="Varför ger han Jitters mat?",a="Jitters har gömt sig i en spökstad i Duskwood i flera veckor och levt på enbart larver och ogräs. Desperat efter riktig mat skickar han resenärer till Grual för att hämta en omgång Dusky Crab Cakes.",al={"jitters mat","jitters kurrande mage grual"}},{q="Är Grual knuten till Night Watch?",a="Grual är civil kock, inte beväpnad vakt, men hans kök stöder Night Watch och den lokala milisen direkt genom att hålla Darkshire mättat under den ständiga belägringen.",al={"grual night watch","strider grual"}}},fx={ccc14f35={q="På vems sida står Chef Grual?",a="Chef Grual står stadigt på Darkshires och Alliansens sida. Staden är fortfarande isolerad och hemsökt av skuggor, men Grual håller elden brinnande på Scarlet Raven Tavern och lagar mat åt invånarna, trötta resenärer och stadens försvarare.",al={"chef gruals fraktion","vem tjänar chef grual","chef grual och alliansen"}},["3ac222da"]={q="Vad vill Chef Grual?",a="Grual vill hålla Scarlet Raven Tavern välförsedd trots farorna i Duskwood. Handelsvägarna är avskurna och det finns ont om färsk boskap, så han förlitar sig på äventyrliga resenärer som hämtar ovanliga lokala råvaror, som vargkött och slemmiga spindelben, till stadens hungriga gäster.",al={"vad behöver chef grual","chef gruals ingredienser","chef gruals mål"}},["91c4d31a"]={q="Varför är Chef Grual här?",a="Grual är Darkshires kock och arbetar på Scarlet Raven Tavern. Många har flytt undan det tilltagande mörkret i Duskwood, men Grual stannar och sköter köket för att bidra till att den isolerade bosättningen överlever.",al={"varför är chef grual i duskwood","varför stannar grual i darkshire","chef gruals roll"}}},fp="10,160,19.305.0,18.284.1,18.158.0,28.137.0,43.148.1,34.197.1,25.157.0,41.128.0"}
P.entries["npc:chef-jessen"] = {n="Chef Jessen",s="Chef Jessen är Southshores slaktare och kock, och ser till att kuststaden får mat trots de ständiga spänningarna vid gränsen. Han är mest känd för sin berömda sköldpaddsbisque.",h="Chef Jessen är Southshores slaktare och kock, och ser till att kuststaden får mat trots de ständiga...",kw={"chef jessen","matlagning","hillsbrad foothills","jessen","lordamere lake","snapjaw","southshore","sköldpaddsbisque"},ang={["faction:Alliance"]="Jessen håller till i Southshore och hjälper till att försörja soldaterna och äventyrarna från Alliance som försvarar frontlinjen mot hoten i norr.",["profession:Cooking"]="Jessen är en värdefull kontakt för kockar som passerar genom Hillsbrad. Hans recept på sköldpaddsbisque ger en mättande måltid åt tåliga resenärer."},sec={{t="En kock i Southshore",b="Chef Jessen håller till i Southshore i södra Hillsbrad Foothills och förser både lokalbefolkningen och förbipasserande soldater från Alliance med proviant och kött. Han har stor kulinarisk skicklighet. För många år sedan, innan pesten och kriget störde livet i norra Lordaeron, reste han regelbundet norrut förbi Dalaran till Lordamere Lakes stränder. Där jagade han snapjaw-sköldpaddor för att få kött till sin prisbelönta Soothing Turtle Bisque. Han delar gärna med sig av receptet till resenärer som hjälper honom att samla ingredienser."}},faq={{q="Vem är Chef Jessen?",a="Chef Jessen är en mänsklig slaktare och kock i Southshore i Hillsbrad Foothills. Han säljer kött och delar med sig av lokala matrecept till resenärer som stöder Alliance.",al={"jessen","chef jessen southshore","vem är jessen"}},{q="Vilken rätt är Chef Jessen känd för?",a="Hans signaturrätt är Soothing Turtle Bisque. Förr brukade han hämta färskt sköldpaddskött från snapjaw-sköldpaddorna kring Lordamere Lake, strax norrut förbi Dalaran, för att tillaga den mustiga soppan.",al={"recept på sköldpaddsbisque","jessens specialitet","soothing turtle bisque"}},{q="Varför ber Chef Jessen resenärer om hjälp?",a="Det har blivit farligt att samla snapjaw-sköldpaddskött kring Lordamere Lake på grund av oroligheterna i regionen och Forsakens närvaro i närheten. Jessen förlitar sig på dugliga äventyrare som kan samla sköldpaddskött åt honom så att han kan laga sin bisque.",al={"jessens uppdrag","uppdrag om sköldpaddskött"}},{q="Säljer Chef Jessen något ovanligt?",a="Förutom köttet han säljer till Southshores invånare är Jessens specialitet Soothing Turtle Bisque. Han lär ut receptet till kockar som hjälper honom att samla snapjaw-kött.",al={"jessens specialitet","jessen köttförsäljare"}}},fx={["4b3f98b6"]={q="På vems sida står Chef Jessen?",a="Chef Jessen är lojal mot Alliansen. Han bor och arbetar i Southshore, den främsta mänskliga tillflyktsorten och Alliansens fäste längs södra kusten av Hillsbrad Foothills. Han lagar mat åt lokalbor och resenärer som kämpar för att hålla stånd i Lordaeron.",al={"chef jessen alliansen eller horden","är chef jessen med i alliansen","chef jessens fraktion"}},["73d1d0ab"]={q="Varför är Chef Jessen i Southshore?",a="Chef Jessen arbetar som lokal köttförsäljare och kock i Southshore. Förr reste han ända förbi Dalaran och ut till Lordamere Lake för att själv jaga snapjaw, men numera stannar han tryggt i staden och förlitar sig på äventyrliga förbipasserande som kommer med färska råvaror.",al={"varför är chef jessen i southshore","varför är chef jessen här","vad förde chef jessen till hillsbrad"}}},fp="11,127,20.458.0,19.162.0,34.182.0,44.213.0,39.148.0"}
P.entries["npc:chief-archaeologist-greywhisker"] = {n="Chief Archaeologist Greywhisker",s="Chief Archaeologist Greywhisker är ett sändebud för dvärgarnas Explorers' League och är stationerad i Darnassus utanför Temple of the Moon. Han skickades från Ironforge över havet till norra Kalimdor för att avslöja forntida historia och samordnar dvärgarnas fältforskning i hela regionen. Just nu är han upptagen med att samla in fältrapporter och spåra försvunna kollegor i Darkshore.",h="Chief Archaeologist Greywhisker är ett sändebud för dvärgarnas Explorers' League och är stationerad i...",kw={"agamaggan","chefsarkeolog","darkshore","darnassus","explorers' league","greywhisker","ironforge","tarelvir","temple of the moon"},ang={["faction:Alliance"]="Han är en viktig lärd och logistisk länk mellan Ironforges Explorers' League och expeditioner stationerade i norra Kalimdor.",["race:Dwarf"]="Att hitta en av Ironforges främsta lärda utanför Temple of the Moon påminner dig tryggt om ditt folks omättliga längtan efter att avslöja forntida historia, även i Kalimdors avlägsnaste hörn.",["race:NightElf"]="Greywhisker representerar den nyfunna alliansen mellan ditt folk och Eastern Kingdoms. Han samtalar respektfullt med lärda utanför Elunes tempel om kontinentens förflutna."},sec={{t="En dvärglärd i Darnassus",b="Det är ovanligt att hitta en dvärg från Ironforge högt bland Teldrassils grenar, men Chief Archaeologist Greywhisker representerar Explorers' Leagues vittgående ambitioner. Han har bytt Ironforges föreläsningssalar och museivalv mot fältarbete i Kalimdor och står ofta utanför Temple of the Moon i Darnassus, där han samtalar med nattalvernas lärda, som Tarelvir. Greywhiskers föreläsningar i Eastern Kingdoms handlade ofta om forntida legender och uråldriga väsen som vildguden Agamaggan, och han längtar efter att få se vilka forntida hemligheter nattalvernas förfäders land kan rymma."},{t="Blicken mot Darkshore",b="Greywhiskers främsta uppgift i Kalimdor är att övervaka dvärgarnas utgrävningar och hålla koll på expeditioner som genomsöker forntida ruiner längs kusten. Tyvärr innebär fältforskning i outforskade trakter särskilda faror för chefsarkeologen. Han förlitar sig på resande för att få kontakt med prospektörer som är stationerade på andra sidan havet i Darkshore. Han väntar oroligt på nyheter från utgrävningsplatserna och hoppas att kollegorna inte har fallit offer för farorna bland de forntida ruinerna."}},faq={{q="Vem är Chief Archaeologist Greywhisker?",a="Han är en framstående dvärglärd från Ironforge och representant för Explorers' League. Han är stationerad utanför Temple of the Moon i Darnassus, där han samordnar ligans forskning i norra Kalimdor och samarbetar med nattalvernas lärda.",al={"vem är greywhisker","greywhiskers bakgrund","chefsarkeolog"}},{q="Vad gör en dvärg från Ironforge i Darnassus?",a="Explorers' League har skickat forskare över hela Azeroth för att avslöja bortglömd historia och forntida artefakter. Greywhisker skickades över havet för att knyta lärda kontakter i nattalvernas huvudstad och övervaka dvärgexpeditioner som utforskar Kalimdors forntida kuster.",al={"varför är en dvärg i darnassus","dvärg vid temple of the moon"}},{q="Vad har han för koppling till Agamaggan?",a="I Ironforge var Greywhisker välkänd för sina lärda föreläsningar om forntida historia. Ett av ämnena han tog upp var vildguden Agamaggan, det väldiga vildsvinet vars legend inspirerade yngre dvärgprospektörer som Lonebrow att studera forntida berättelser om bestar.",al={"greywhisker agamaggan","agamaggan föreläsningar"}},{q="Vem talar Greywhisker med utanför templet?",a="Greywhisker står i Darnassus och talar med Tarelvir, en nattalvslärd utanför Temple of the Moon. De utbyter tankar och samordnar historisk forskning mellan sina folk.",al={"greywhisker tarelvir","vem är med greywhisker"}},{q="Vilka problem försöker han lösa i Darkshore?",a="Greywhisker har skickat dvärgkollegor till Darkshore för att gräva ut forntida ruiner, men det har visat sig svårt att hålla kontakten med de isolerade expeditionerna. Han söker ofta efter kurirer som kan se till de tankspridda prospektörerna och hämta deras forskningsdagböcker.",al={"greywhisker darkshore","prospektörer i darkshore"}},{q="Vilken fraktion tillhör Greywhisker?",a="Greywhisker tillhör Explorers' League, en arkeologisk organisation i Ironforge som ägnar sig åt att upptäcka dvärgarnas ursprung och forntida historia och som är helt lojal mot Alliance.",al={"greywhiskers fraktion","explorers' league darnassus"}}},fp="31,225,30.479.0,17.347.0,39.253.0,46.224.0,36.195.0,49.177.0,45.220.0,41.187.0"}
P.entries["npc:chief-engineer-hinderweir-vii"] = {n="Chief Engineer Hinderweir VII",s="Chief Engineer Hinderweir VII är en erfaren dvärgisk ingenjör stationerad högst upp på Stonewrought Dam i Loch Modan. Han ansvarar för underhållet och försvaret av detta monumentala ingenjörsverk och övervakar dess känsliga mekanismer samtidigt som han håller utkik efter sabotage. Den som talar med honom upptäcker snart att allvarliga faror hotar den väldiga dammens stabilitet.",h="Chief Engineer Hinderweir VII är en erfaren dvärgisk ingenjör stationerad högst upp på Stonewrought Dam i...",kw={"a dark threat looms","dvärg","ingenjör","hinderweir","loch modan","sabotage","stonewrought dam"},ang={["faction:Alliance"]="Alliansen har inte råd att låta dammen falla; ett katastrofalt dammbrott skulle störa försörjningsvägar och ödelägga de allierades områden norr om Loch Modan.",["profession:Engineering"]="Ingenjörer kan uppskatta den väldiga mekaniska omfattningen av Hinderweirs ansvarsområde, eftersom Stonewrought Dam är en enastående kombination av byggnadskonst och mekanisk styrning.",["race:Dwarf"]="För dvärgar står Hinderweir för det högtidliga ansvaret att bevara Khaz Modans främsta stenhantverksbedrifter från yttre illvilja."},sec={{t="Dammens mästare",b="Stonewrought Dam är en av dvärgarnas främsta bedrifter inom stenhantverk och ingenjörskonst, och håller tillbaka Lochs väldiga vattenmassor. Chief Engineer Hinderweir VII bär det stora ansvaret för att underhålla dammens konstruktion och maskineri. Uppe på dammens krön övervakar han vattenlederna, slussportarna och konstruktionens belastningspunkter och skyddar dem mot väder och lokala faror."},{t="Sabotage och omstörtning",b="Att sköta dammen handlar om mer än rutinunderhåll; mörka krafter prövar ständigt dess försvar. Hinderweir upptäcker tecken på planerat sabotage, iscensatt av fientliga krafter i trakten. Medveten om att ett katastrofalt dammbrott skulle översvämma låglandet och ödelägga Khaz Modans känsliga infrastruktur ber Chief Engineer pålitliga äventyrare från Alliansen att spåra konspirationen, desarmera dolda sprängladdningar och undanröja hotet innan stenverket ger vika."}},faq={{q="Vem är Chief Engineer Hinderweir VII?",a="Chief Engineer Hinderweir VII är dvärgarnas arbetsledare med ansvar för att underhålla och försvara Stonewrought Dam i norra Loch Modan.",al={"hinderweir","chefingenjör","damingenjör"}},{q="Var hittar jag Chief Engineer Hinderweir VII?",a="Han står på gångvägen högst upp på Stonewrought Dam, som sträcker sig längs Loch Modans norra kant nära gränsen till Wetlands.",al={"hinderweirs plats","var finns hinderweir","hitta hinderweir"}},{q="Vad är Stonewrought Dam?",a="Stonewrought Dam är ett väldig dvärgiskt arkitektoniskt underverk som håller tillbaka vattnet i Loch Modan och hindrar sjön från att våldsamt svämma över de lägre våtmarkerna i norr.",al={"vad är dammen","stonewrought dams syfte","varför är dammen viktig"}},{q="Vilka hot oroar Hinderweir?",a="Hinderweir undersöker pågående sabotage mot dammen och hittar bevis på mörka planer och sprängladdningar som placerats ut för att spräcka dess grundvalar.",al={"hot mot dammen","a dark threat looms","vem vill förstöra dammen"}},{q="Varför ingår ”VII” i hans namn?",a="VII är den romerska siffran för sju. Det finns ingen dokumenterad förklaring till varför den ingår i Hinderweirs namn.",al={"hinderweirs namn","varför den sjunde","vad betyder hinderweir vii"}},{q="Vilka uppdrag erbjuder Chief Engineer Hinderweir?",a="Han erbjuder uppdragskedjan ”A Dark Threat Looms”, där äventyrare får i uppgift att undersöka sabotage och skydda Stonewrought Dam från förstörelse.",al={"hinderweirs uppdrag","uppdrag vid dammen","uppdraget a dark threat looms"}}},fx={["35f113ec"]={q="På vems sida står Chief Engineer Hinderweir VII?",a="Chief Engineer Hinderweir VII är en stolt dvärg som är lojal mot Ironforge och Alliansen. Han är stationerad vid Stonewrought Dam i Loch Modan. Hans främsta uppgift är att skydda ett av dvärgrikets största ingenjörsunder från alla yttre faror.",al={"hinderweirs fraktion","är hinderweir med i alliansen","vem tjänar hinderweir"}},["3db73bdf"]={q="Vad vill Chief Engineer Hinderweir VII?",a="Hinderweir vill säkra Stonewrought Dam och dess försvar till varje pris. Han misstänker fulspel och ett förestående sabotage mot den väldiga dammen. Därför söker han pålitliga äventyrare som kan undersöka misstänkt verksamhet i närheten och undanröja alla mörka hot innan en katastrof drabbar Loch Modan.",al={"hinderweirs mål","vad vill chief engineer hinderweir","hinderweirs motiv"}},["53bdb0ce"]={q="Varför är Chief Engineer Hinderweir VII här?",a="Som chefsingenjör med ansvar för Stonewrought Dam är Hinderweir stationerad direkt på den väldiga konstruktionen för att övervaka driften och säkerheten. Han håller vakt på plats för att ta hand om strukturella problem och möta omedelbara faror som hotar sjön.",al={"varför är hinderweir vid dammen","varför är chief engineer hinderweir här","hinderweirs uppgift i loch modan"}}},fp="29,194,17.267.0,23.292.1,37.92.0,47.150.0,29.162.0,41.152.0,32.91.0,49.173.0"}
P.entries["npc:chief-hawkwind"] = {n="Chief Hawkwind",s="Chief Hawkwind är ledare för Camp Narache, prövningsplatsen på Red Cloud Mesa i Mulgore. Han vägleder Shu'halos ungdomar och handleder nya äventyrare när de ger sig ut på sina traditionella övergångsriter. Under hans vakande blick lär sig de unga modiga ödmjukhet, respekt för landet och styrkan som krävs för att skydda sitt folk.",h="Chief Hawkwind är ledare för Camp Narache, prövningsplatsen på Red Cloud Mesa i Mulgore.",kw={"en enkel uppgift","bristleback","camp narache","chief hawkwind","mulgore","red cloud mesa","styrkans rit","jordemoderns riter","taurernas hövding"},ang={["faction:Horde"]="Hawkwinds undervisning ser till att nyupptagna taurer inte bara blir skickliga krigare och besvärjare, utan också trofasta och hedervärda bundsförvanter till den unga Horden.",["race:Tauren"]="Som den första hövdingen som vägleder dig på din resa förmedlar Chief Hawkwind Shu'halos grundläggande värderingar: vördnad för Jordemodern, trohet mot stammen och ödmjukhet i styrka."},sec={{t="Mesa-platåns hövding",b="Mitt i Camp Narache bär Chief Hawkwind det högtidliga ansvaret att förbereda nästa generation taurer för den stora världen. Red Cloud Mesa är en skyddad tillflykt där unga jägare, shamaner, druider och krigare genomgår Jordemoderns uråldriga riter. Hawkwind vakar över dessa seder och ser till att alla ungdomar lär sig plikt och uthållighet innan de lämnar platåns trygghet."},{t="Att vägleda riterna",b="Hawkwinds lärdomar börjar med ödmjukhet, inte krigisk ära. Han skickar invigda på enkla ärenden, som att hämta rent källvatten, för att väcka vördnad för naturen och de äldre. Först när de har visat ett ödmjukt hjärta leds de modiga vidare till prövningar av stridsförmåga, som kulminerar i tester där de måste stå emot de aggressiva Bristleback quilboar som tränger in på förfädernas slätter."},{t="Försvaret av Camp Narache",b="Utöver rollen som mentor måste Chief Hawkwind hantera växande faror alldeles intill lägret. Bristleback-stammen har blivit allt djärvare och pressar hårt mot Red Cloud Mesas gräns. Hawkwind samordnar försvaret av bosättningen och ger de nyss beprövade modiga uppdraget att hejda quilboarernas angrepp så att den heliga träningsplatsen förblir trygg."}},faq={{q="Vem är Chief Hawkwind?",a="Chief Hawkwind är hövding för Camp Narache på Red Cloud Mesa. Han ansvarar för stammens angelägenheter i området och handleder unga taurer när de förbereder sig för sina första steg ut i Mulgore och Kalimdors större värld.",al={"hawkwind","chief hawkwinds bakgrund","vem är hövdingen i camp narache"}},{q="Vad är Jordemoderns riter?",a="Jordemoderns riter är en traditionell följd av heliga prövningar som unga taurer genomgår när de blir vuxna. Med vägledning från äldre som Chief Hawkwind prövar riterna ödmjukhet, styrka, mod och den andliga förbindelsen till landet och förfäderna.",al={"taurernas riter","jordemoderns riter","vad är riterna"}},{q="Varför ber Chief Hawkwind dig hämta vatten först?",a="Hawkwind ger uppdraget 'A Humble Task' för att påminna de unga modiga om att tjänstvillighet och respekt för gemenskapen är lika viktiga som stridsstyrka. Att hämta färskt vatten åt stammens äldre lär de invigda tålamod och ödmjukhet innan de skickas ut i strid.",al={"en enkel uppgift","varför hämta vatten","hawkwinds vattenuppdrag"}},{q="Vilket hot står Camp Narache inför?",a="Camp Narache är ständigt utsatt för fientliga Bristleback quilboar som bor i kullarna runt Red Cloud Mesa. Chief Hawkwind måste organisera försvaret av platån och skicka ut invigda för att decimera quilboarernas styrkor.",al={"hot mot narache","vem anfaller camp narache","quilboar i camp narache"}},{q="Vart skickar Chief Hawkwind äventyrare härnäst?",a="När en ung modig har klarat de inledande riterna på platån skickar Chief Hawkwind dem ner i Mulgore, till Bloodhoof Village, för att söka upp Chief Baine Bloodhoof, Cairnes son, och fortsätta Jordemoderns riter.",al={"vart går jag efter hawkwind","efter camp narache","lämna red cloud mesa"}},{q="Är Chief Hawkwind släkt med Greatmother Hawkwind?",a="Ja, Greatmother Hawkwind är hans mor. Familjen Hawkwind har länge haft djupa rötter och ledarroller bland taurena som bor på Red Cloud Mesa.",al={"greatmother hawkwinds släktband","familjen hawkwind","vem är greatmother hawkwind"}}},fx={c01d188d={q="På vems sida står Chief Hawkwind?",a="Chief Hawkwind står lojalt med sina taurenfränder och Horden. Som stamledare stationerad på Red Cloud Mesa vägleder och stärker han den nyaste generationen taurenförsvarare, så att de är redo att tjäna både sitt folk och hela Horden.",al={"chief hawkwinds fraktion","hawkwind horden eller alliansen","vem tjänar chief hawkwind"}},e0733ded={q="Vad vill Chief Hawkwind?",a="Hawkwind vill skydda Camp Narache och se till att unga tauren sätts på prov ordentligt innan de ger sig ut i Kalimdor. Han leder Earthmothers heliga riter, där din ödmjukhet och styrka prövas mot de framryckande Bristleback quilboar, så att du kan tjäna ditt folk med heder.",al={"vad är chief hawkwinds mål","chief hawkwinds uppgift","vad vill hawkwind"}},d395b627={q="Varför är Chief Hawkwind vid Camp Narache?",a="Chief Hawkwind bor vid Camp Narache för att sköta stammens lokala angelägenheter och vägleda unga äventyrare genom deras första prövningar. Från denna upphöjda platå vakar han över träningsmarkerna och organiserar försvaret mot de aggressiva Bristleback quilboar, som ständigt trakasserar lägret.",al={"varför är chief hawkwind här","varför är hawkwind vid camp narache"}}},fp="14,234,21.301.0,17.362.0,22.300.0,22.170.0,38.228.0,51.239.0,35.181.0,48.237.0,50.150.0"}
P.entries["npc:christoph-jeffcoat"] = {n="Christoph Jeffcoat",s="Christoph Jeffcoat är en Förfallen handelsman stationerad i bosättningen Tarren Mill i Hillsbrad Foothills. Han förser lokala hantverkare och resenärer med viktiga handelsvaror, matlagningskryddor och specialrecept. I en aktiv krigszon som omstrids av Alliansen och Syndikatet håller hans alldagliga varor Hordens krigsinsats i norr igång.",h="Christoph Jeffcoat är en Förfallen handelsman stationerad i bosättningen Tarren Mill i Hillsbrad Foothills.",kw={"christoph jeffcoat","förfallen handelsman","hillsbrad","lenande kryddor","tarren mill","handelsvaror","handelsman"},ang={["faction:Horde"]="För Hordens hjältar som strider i Hillsbrad Foothills tillhandahåller Jeffcoat oumbärliga hantverksmaterial och vanliga verktyg mitt i Tarren Mill.",["profession:Cooking"]="Christoph Jeffcoat är ett viktigt stopp för blivande kockar i Hillsbrad, eftersom han har lenande kryddor och lär ut sitt eget recept på lenande sköldpaddssoppa till kockar som kommer med snapjaw-kött."},sec={{t="En handelsman vid frontlinjen",b="Även om Tarren Mill är de Förfallnas militära fäste i Hillsbrad Foothills kan en garnison inte strida enbart på illvilja. Christoph Jeffcoat sköter den stillsamma, praktiska sidan av ockupationen och säljer reagenser, verktyg, trådar och kryddor till soldater och kringresande hantverkare. Från de lenande kryddor som behövs till lokala maträtter som sköldpaddssoppa till sällsynta ritningar och alkemiska flaskor ser Jeffcoat till att Hordens styrkor som passerar genom södra Lordaeron är fullt utrustade inför striderna mot Southshore och farorna i området."}},faq={{q="Var hittar jag Christoph Jeffcoat?",a="Christoph Jeffcoat finns i Tarren Mill, Hordens främsta fäste för de Förfallna i norra Hillsbrad Foothills.",al={"christoph jeffcoat plats","var är jeffcoat","handelsman i tarren mill"}},{q="Vilka slags varor säljer han?",a="Han är handelsman med förnödenheter och har trådar för skrädderi, smedshammare, flussmedel, flaskor för alkemi och matlagningskryddor som lenande kryddor och starka kryddor, samt ett urval specialrecept.",al={"vad säljer jeffcoat","christoph jeffcoats varor","jeffcoats föremål"}},{q="Varför är han viktig för lokala kockar?",a="Jeffcoat säljer lenande kryddor, en ingrediens i lenande sköldpaddssoppa, och lär själv Hordens kockar att laga soppan när de tar med sköldpaddskött från snapjaw-sköldpaddorna.",al={"handelsman med lenande kryddor hillsbrad","ingredienser till lenande sköldpaddssoppa","jeffcoat matlagning"}}},fx={["36cd3db3"]={q="Vem är Christoph Jeffcoat?",a="Christoph Jeffcoat är en odöd handelsman stationerad vid Tarren Mill i Hillsbrad Foothills. Han tjänar de Förfallna genom att förse resenärer, hantverkare och försvarare som håller Hordens frontlinjer i området med handelsvaror, råmaterial och hantverkskomponenter.",al={"vem är christoph jeffcoat","christoph jeffcoats identitet","vem är jeffcoat"}},["1470d19f"]={q="På vems sida står Christoph Jeffcoat?",a="Christoph Jeffcoat är hängiven de Förfallna och Horden. Han är stationerad i den hårt omstridda utposten Tarren Mill och betjänar Hordens äventyrare och kämpar som strider mot Alliansens styrkor från Southshore i närheten.",al={"christoph jeffcoats fraktion","är christoph jeffcoat med i horden","vem tjänar christoph jeffcoat"}},["7ff6f152"]={q="Varför är Christoph Jeffcoat här i Tarren Mill?",a="Tarren Mill fungerar som den norra förankringen för Hordens verksamhet i Hillsbrad Foothills, och hantverkare och kämpar får ständigt slut på vardagsvaror. Christoph Jeffcoat är stationerad här för att se till att handelsvaror, flaskor, trådar och kryddor alltid finns tillgängliga för dem som försvarar utposten.",al={"varför är christoph i tarren mill","varför är christoph jeffcoat här","varför är jeffcoat i hillsbrad"}}},fp="18,206,29.409.0,36.113.0,33.167.0,36.140.0"}
P.entries["npc:chronormu"] = {n="Chronormu",s="Chronormu, som går under det dödliga namnet Chromie, är en bronsh drake förklädd till en energisk kvinnlig gnom. Hon har fått i uppdrag att skydda tidens flöde på Azeroth och arbetar ofta direkt med dödliga i stället för att betrakta dem på avstånd. I Western Plaguelands ingriper hon diskret i det tragiska eftermälet av det tredje kriget för att rätta till störda tidsvävar.",h="Chronormu, som går under det dödliga namnet Chromie, är en bronsh drake förklädd till en energisk kvinnlig...",kw={"andorhal","bronsdrake","chromie","chronormu","nozdormu","gestalt"},ang={["class:Mage"]="Magiker som studerar den arkaniska disciplinen kronomanti kommer att finna Chronormus avslappnade tidsmanipulation och lokala tidsfickor både fascinerande och häpnadsväckande i sin omfattning.",["race:Gnome"]="Chronormu vandrar bland dödliga som Chromie, en gladlynt gnom vars lilla, anspråkslösa skepnad döljer en bronsdrake."},sec={{t="En drake i liten skepnad",b="Även om hon visar sig för dödliga som en excentrisk och gladlynt gnom vid namn Chromie, är Chronormu medlem av bronsprean som tjänar under den tidlöse Nozdormu. Titanerna har gett bronsdrakarna i uppdrag att vakta historien och rätta till störningar i tidsvägarna. I skepnad av en kvinnlig gnom vandrar hon bland dödliga som en tillgänglig och optimistisk jämlike."},{t="Väktare i Plaguelands",b="Chronormu har slagit sig ner i de förfallna Ruins of Lordaeron och håller särskilt uppsikt över det ödelagda Western Plaguelands. Rikets katastrofala fall och Scourges spridning slet djupa sår i regionens historia och lämnade efter sig tidsanomalier och fångade rester. Från platser som Ruins of Andorhal arbetar hon diskret och tar hjälp av dödliga äventyrare för att laga sammantrasslade tidslinjer och undersöka störningar, utan att avslöja bronspreans fulla, skräckinjagande majestät om det inte behövs."}},faq={{q="Är Chromie verkligen en gnom?",a="Nej. Chromie är bara Chronormus dödliga gestalt, en bronsdrake. Bronsdrakar antar dödliga skepnader för att kunna röra sig bland de yngre raserna utan att väcka onödig skräck eller misstanke.",al={"är chromie en gnom","chromies sanna form","vem är chromie"}},{q="Varför har Chromie två namn?",a="Chronormu är helt enkelt hennes sanna namn som bronsdrake. Chromie är det kortare namn hon använder i sin gnomskepnad bland dödliga.",al={"chronormus namn och kön","varför kallas chromie chronormu","chronormus kön"}},{q="Vad gör Chromie i Western Plaguelands?",a="Förödelsen som Scourge orsakade i Lordaeron ledde till allvarliga störningar i historien och tidsvägarna. Chromie är stationerad i ruinerna för att undersöka tidsanomalier, upphäva historiska störningar och ta hjälp av pålitliga äventyrare för att laga skadade tidsvävar.",al={"vad gör chromie här","varför är chromie i andorhal","chromie i western plaguelands"}},{q="Vilka är bronsprean?",a="Bronsprean leds av drakbehärskaren Nozdormu och välsignades av titanerna med kraften att färdas genom och skydda tidens vägar. De ser till att historien utvecklas som avsett och ingriper när tiden förändras eller korrumperas.",al={"bronsdrakar","vad är bronsprean","nozdormus flygel"}}},fp="9,360,23.370.0,26.516.0,26.180.0,32.124.0,49.274.0,32.245.0"}
P.entries["npc:clarice-foster"] = {n="Clarice Foster",s="Clarice Foster är en Förfallen kvinna som bor djupt under Mulgore-klipporna i The Pools of Vision. Långt från Lordaerons pestdrabbade gläntor tillbringar hon dagarna i begrundan bland tauren-siande och mystiker.",h="Clarice Foster är en Förfallen kvinna som bor djupt under Mulgore-klipporna i The Pools of Vision.",kw={"clarice foster","förfallna","the pools of vision","spirit rise","thunder bluff","until death do us part"},ang={["race:Tauren"]="Clarice Foster har välkomnats till de heliga The Pools of Vision under Spirit Rise och visar att tauren är villiga att hysa Hordens ovanliga nykomlingar.",["race:Undead"]="Clarice Foster står för de Förfallnas band till sina tauren-allierade i Kalimdor, långt från Tirisfals och Silverpines pestfläckade jord."},sec={{t="En Förfallen i The Pools of Vision",b="Medan de flesta Förfallna stannar i Lordaerons nordliga trakter och återuppbygger sitt kungarike under Undercity, har Clarice Foster rest till taurenfolkets hjärta i Kalimdor. Skyddad i The Pools of Visions grottor under Thunder Bluffs platå bor hon tillsammans med Förfallna apotekare och tauren-schamaner som studerar jordens andliga och elementära mysterier."}},faq={{q="Vem är Clarice Foster?",a="Clarice Foster är en Förfallen kvinna som finns i de underjordiska The Pools of Vision under Thunder Bluff. Hon är en av de få odöda sändebuden och besökarna som bor bland Mulgore-tauren.",al={"vem är clarice","clarice foster npc","clarice fosters bakgrund"}},{q="Var hittar jag Clarice Foster?",a="Hon finns i The Pools of Vision, ett grottkomplex under Spirit Rise i Thunder Bluff.",al={"clarice fosters plats","var finns clarice foster","hitta clarice foster"}},{q="Vilka uppdrag erbjuder hon?",a="Hon ger uppdraget 'Until Death Do Us Part'. Bitter över att hennes avlidne make lämnade henne för sitt korståg mot de odöda och dog, skickar hon resande för att lägga hans hängsmycke på hans grav vid The Sepulcher i Silverpine Forest.",al={"clarice fosters uppdrag","until death do us part-uppdraget"}}},fx={["4e89059e"]={q="På vems sida står Clarice Foster?",a="Clarice Foster står på de Förfallnas och hela Hordens sida. Hennes uppgifter håller henne långt från Lordaeron, i The Pools of Vision under Thunder Bluff, men hon är fortfarande lojal mot drottning Sylvanas och de Förfallnas sak.",al={"clarice fosters fraktion","clarice fosters lojalitet","vem tjänar clarice foster"}}},fp="14,179,33.339.0,22.180.0,32.104.0,27.203.0"}
P.entries["npc:clerk-daltry"] = {n="Clerk Daltry",s="Clerk Daltry är stadens arkivarie i Darkshire Town Hall i Duskwood. Omgiven av liggare och registerböcker hjälper han till att undersöka byns förflutna och leta fram historiska handlingar, även om arkiven är ganska eftersatta och inaktuella.",h="Clerk Daltry är stadens arkivarie i Darkshire Town Hall i Duskwood.",kw={"carevin","clerk daltry","darkshire","duskwood","liggare","mistmantle","handlingar","stalvan","stadshus"},ang={["faction:Alliance"]="För Alliance-utredare som avslöjar Duskwoods kusliga mysterier är Clerk Daltry en oumbärlig myndighetskontakt för försvunna handlingar och olösta fall.",["race:Human"]="Daltry bevarar det som återstår av Grand Hamlets historiska arv från tiden innan mörkret sänkte sig över skogsriket."},sec={{t="Stadens arkivarie",b="Medan Darkshire kämpar mot framryckande bestar, odöda fasor och övernaturligt mörker sköter Clerk Daltry stadens vardagliga angelägenheter. Från Darkshire Town Hall arbetar han tillsammans med Lord Ello Ebonlocke och det lokala rådet, och för stadens historiska liggare, fastighetsregister och folkräkningsuppgifter. I en trakt som splittrats av katastrofer är hans handlingar några av de få bevarade banden till tiden innan Grand Hamlet föll i skugga."},{t="Pappersspår",b="Eftersom Darkshire är avskuret från den regelbundna förvaltningen i Stormwind är Daltrys dokumentföring ökänd för sina brister. Gamla handlingar försvinner, liggare släpar efter och viktiga stadsdokument kommer ofta bort eller skadas. Äventyrare som undersöker gamla olösta fall eller sedan länge försvunna invånare vänder sig ofta till honom, men upptäcker att sanningen kräver att de gräver bland förbisedda anteckningar eller beger sig ut i de farliga skogarna för att återfinna förlorade papper."},{t="Legenden om Stalvan",b="Daltry spelar en central roll i att nysta upp Stalvan Mistmantles mörka mysterium. När en olycksbådande familjelegend leder utredare tillbaka till Darkshire söker Daltry i sina arkiv efter handlingar om den före detta skolläraren. Eftersom stadens registeruppgifter om Stalvan är ofullständiga måste Daltry skicka sökare genom staden och till bortglömda gårdar runt om i kungariket för att lägga det tragiska och blodiga händelseförloppet till rätta."}},faq={{q="Var finns Clerk Daltry?",a="Clerk Daltry finns inne i Darkshire Town Hall, som ligger i den centrala byn Darkshire i Duskwood. Han står bland stadens tjänstemän och rådsmedlemmar och sköter de kommunala registren.",al={"clerk daltrys plats","var finns daltry","var finns skrivaren i darkshire"}},{q="Vad arbetar Clerk Daltry med i Darkshire?",a="Han tjänstgör som Darkshires stadsarkivarie och ansvarar för att bevara handlingar, stadsregister och juridiska förteckningar. Han hjälper äventyrare som behöver arkivuppgifter om tidigare invånare, markanspråk eller historiska utredningar.",al={"vad gör daltry","daltrys roll","vem är clerk daltry"}},{q="Varför är hans handlingar ofullständiga?",a="Duskwood har genomlidit år av isolering, magisk förvanskning och våldsamma oroligheter. Stadens fokus har legat på den omedelbara överlevnaden mot Night Watchs fiender, så arbetet med att hålla liggarna uppdaterade har ofta fått stå tillbaka och lämnat arkiven ofullständiga.",al={"varför är daltrys handlingar bristfälliga","inaktuella handlingar i duskwood","daltrys försvunna liggare"}},{q="Vilka uppdragskedjor inleder eller deltar Clerk Daltry i?",a="Daltry är en viktig person i berättelsen ”The Legend of Stalvan” och hjälper spelare att spåra upp Stalvan Mistmantles svårfunna förflutna. Han bistår också med utredningar som ”The Carevin Family” och ”The Shadowy Search Continues”.",al={"daltrys uppdrag","vilka uppdrag ger daltry","clerk daltrys uppdragskedja"}},{q="Vem skickar utredare till Clerk Daltry?",a="Madame Eva skickar dem som följer Stalvan-mysteriet till skrivaren i Town Hall, och även resenärer som följer andra spår, till exempel sökandet efter Velinde Starsong, hänvisas till honom. När hans egna handlingar inte räcker skickar Daltry dem vidare, exempelvis till värdshuset för att fråga om en främling.",al={"vem skickar folk till daltry","daltrys kontakter"}},{q="Kan Horde-spelare tala med Clerk Daltry?",a="Nej. Clerk Daltry är en kommunal tjänare knuten till Alliance. Darkshire och stadshuset bevakas av Night Watch och är fientliga mot alla Horde-äventyrare.",al={"är daltry vänligt sinnad mot horde","kan horde tala med daltry"}}},fx={["063859f4"]={q="Vem är Clerk Daltry?",a="Clerk Daltry är en mänsklig ämbetsman stationerad i Darkshire Town Hall i Duskwood. Han ansvarar för stadens offentliga handlingar, folkräkningsuppgifter och invånarnas släkthistorier. Han fungerar som arkivarie i en isolerad bosättning hemsökt av skuggor och glömda förflutna.",al={"vem är daltry","vem är clerk daltry","clerk daltry i darkshire"}},["7e4b683b"]={q="På vems sida står Clerk Daltry?",a="Daltry står stadigt på Alliansens och Darkshires sida. Som tjänsteman i stadshuset tjänar han den lokala civila myndigheten och hjälper resenärer och utredare som försöker lösa stadens problem eller hitta försvunna personer.",al={"är daltry med i alliansen","daltrys fraktion","clerk daltrys lojalitet"}},["3b37b748"]={q="Vad vill Clerk Daltry?",a="Clerk Daltry vill hålla ordning på handlingarna och hjälpa utredare som granskar Duskwoods mörka mysterier. Han hjälper ofta resenärer att söka i stadens loggböcker, släktregister och gamla dokument efter försvunna invånare som Stalvan Mistmantle, men arkiven är långt ifrån fullständiga.",al={"vad vill daltry","clerk daltrys mål","daltrys motiv"}},["7e737b61"]={q="Varför är Clerk Daltry här?",a="Daltry stannar i Darkshire för att sköta sina kommunala uppgifter i stadshuset. Trots de mörknande skogarna och de ständiga farorna som tränger sig på är staden fortfarande beroende av en tjänsteman som bevarar lagfarter, brev och identiteten hos dem som bor i området.",al={"varför är daltry i darkshire","varför är clerk daltry här","varför är daltry i stadshuset"}}},fp="12,203,18.395.0,15.375.0,21.308.1,30.168.0,40.166.0,31.233.0,58.197.0,40.255.0,42.119.0"}
P.entries["npc:cliffwatcher-longhorn"] = {n="Cliffwatcher Longhorn",s="Cliffwatcher Longhorn är den lugna taurenledaren som är stationerad högt uppe på Freewind Post i Thousand Needles. Han har fått i uppdrag att skydda den isolerade utposten i Horde och samordnar försvaret mot Galak-centaurernas framryckning samtidigt som han håller uppsikt över Grimtotem-stammens misstänkta intriger.",h="Cliffwatcher Longhorn är den lugna taurenledaren som är stationerad högt uppe på Freewind Post i Thousand...",kw={"arnak grimtotem","brave moonhorn","cliffwatcher longhorn","freewind post","galak","grimtotem","nataka longhorn","thousand needles"},ang={["faction:Horde"]="Freewind Post är en viktig länk som säkrar försörjningslinjerna genom södra Kalimdor, och Longhorn ser till att Horde behåller sitt utsatta fotfäste mitt i fientligt centaurterritorium.",["race:Tauren"]="För taurenresenärer står Longhorn för Shu'halos gränslandssjäl. Han vakar över omstridda, heliga platåer samtidigt som han navigerar den bittra, olösta konflikten med Grimtotem-stammen."},sec={{t="Väktare över platåerna",b="Freewind Post ligger högt uppe bland Thousand Needles väldiga klippspiror och behöver skarpa ögon och stadigt ledarskap för att överleva. Cliffwatcher Longhorn ansvarar för bosättningens dagliga säkerhet. Fientliga styrkor samlas på kanjonens botten och längs åsarna intill, och Longhorn samordnar främst spaningsrapporter och militära försvarsinsatser."},{t="Centaurernas fientlighet och Grimtotems intriger",b="Longhorn hanterar hot från flera håll. Nere i kanjonen sonderar de aggressiva Galak-centaurerna ständigt bosättningens försvar, så han skickar äventyrare för att driva tillbaka dem och minska deras antal. Än mer oroande är dock Grimtotem-taurerna. Longhorn misstror deras hemlighetsfulla läger nära utposten djupt och ordnar spaning för att beslagta deras gömda anteckningar. Där avslöjas oroande bevis på förräderi inom gruppen, bland annat Arnak Grimtotems våldsbrott."}},faq={{q="Vem är Cliffwatcher Longhorn?",a="Cliffwatcher Longhorn är taurenledaren som för befälet över Freewind Post, Hordes högt belägna utpost i Thousand Needles. Han organiserar spejare, försvarspatruller och insatser mot lokala hot.",al={"cliffwatcher longhorn information","vem är longhorn","ledare för freewind post"}},{q="Var hittar jag Cliffwatcher Longhorn?",a="Han finns högst upp på Freewind Posts huvudplatå i Thousand Needles. Ta hissen upp från kanjonens botten och gå över träbroarna.",al={"cliffwatcher longhorn plats","var finns longhorn"}},{q="Varför oroar sig Longhorn för centaurerna?",a="Rapporter från spejare som Brave Moonhorn visar att Galak-centaurernas fientlighet har ökat oroväckande snabbt. Longhorn beordrar förebyggande anfall för att kuva klanen och hindra den från att övermanna utpostens försvar.",al={"varför döda centaurer","kuva centaurerna bakgrund","centaurhot i thousand needles"}},{q="Varför intresserar sig Longhorn för Grimtotem-stammen?",a="Grimtotem-klanen lever visserligen bland Horde, men beter sig öppet hemlighetsfullt och illvilligt. Longhorn misstänker fula avsikter och anlitar äventyrare för att stjäla deras gömda anteckningar och ta reda på vad de planerar.",al={"longhorn grimtotem","varför spionera på grimtotem"}},{q="Vem är Arnak Grimtotem, och varför vill Longhorn ha tag på honom?",a="Arnak Grimtotem utförde en våldsam attack mot invånarna vid utposten. Longhorn utfäster en belöning för hans huvud för att se till att Arnak ställs till svars för sitt förräderi.",al={"efterlyst arnak grimtotem","arnak belöning bakgrund"}},{q="Har Cliffwatcher Longhorn någon familj?",a="Ja, hans bror Nataka Longhorn är stationerad långt västerut vid Ghost Walker Post i Desolace. Cliffwatcher är upptagen med sina plikter och får sällan tillfälle att skriva till honom.",al={"longhorns bror","nataka longhorns bror"}}},fx={["8c33620b"]={q="Vems sida står Cliffwatcher Longhorn på?",a="Cliffwatcher Longhorn står stadigt på Hordens sida och stöder taurenstammarna som lyder under Thunder Bluff. Han är stationerad högst uppe på Freewind Post och samordnar försvaret av bosättningen. Han förlitar sig på Hordens kämpar för att skydda ravinens vägar nedanför från fientliga centaurklaner och den omstörtande Grimtotem-stammen.",al={"cliffwatcher longhorn fraktion","longhorn horde allians","vem tjänar longhorn"}},d26a5d43={q="Vad vill Cliffwatcher Longhorn?",a="Longhorn vill upprätthålla säkerhet och ordning i hela Thousand Needles. Han vill hämnas på fientliga Galak-centaurgrupper som trakasserar resande, avslöja vilka hemliga planer de lokala Grimtotem smider och skipa snabb rättvisa åt förrymda hot som Arnak Grimtotem.",al={"vad vill longhorn","longhorns mål","cliffwatcher longhorns motiv"}},e12f4ee3={q="Varför är Cliffwatcher Longhorn här?",a="Longhorn är stationerad på Freewind Post som en av dess främsta tillsynsmän och försvarare. Från denna högt belägna platå bevakar han rapporter från ravinens botten, leder Hordens spejare och organiserar motåtgärder mot de farliga centaurstammarna och de svekfulla Grimtotem som omger utposten.",al={"varför är longhorn på freewind post","varför är cliffwatcher longhorn i thousand needles","longhorns roll på freewind post"}}},fp="21,279,21.405.0,40.498.1,29.201.0,39.158.0,44.213.0,44.218.0,54.162.0,43.174.0"}
P.entries["npc:coleman-farthing"] = {n="Coleman Farthing",s="Coleman Farthing är en bitter överlevare bland de Fördömda, bosatt på Gallows' End Tavern i Brill. I livet arbetade han åt den välbärgade Agamanddynastin vid dess vidsträckta kvarnar i norra Tirisfal. Övertalad att stanna och försvara egendomen mot Scourge dog han tillsammans med sina arbetskamrater. Nu ägnar han sitt odöda liv åt att utkräva hämnd på sina forna herrar.",h="Coleman Farthing är en bitter överlevare bland de Fördömda, bosatt på Gallows' End Tavern i Brill.",kw={"agamands arvegods","agamand mills","brill","coleman farthing","dödsfall i familjen","gallows' end tavern","lordaeron","tirisfal glades"},ang={["class:Warrior"]="Coleman visar blivande krigare direkt till Agamand Family Crypt och uppmanar dem att plundra en fallen aristokratisk familjs stridsarvegods för att beväpna sig inför de kommande krigen.",["race:Undead"]="För de Fördömda står Coleman för den gemensamma bitterhet som många ur vanligt folk känner mot Lordaerons gamla adel, vars arrogans och högmod ofta påskyndade undersåtarnas undergång under pesten."},sec={{t="En bitter tjänare",b="Före det tredje kriget försörjde sig Coleman Farthing som arbetare vid Agamand Mills, Tirisfal Glades största kvarn- och jordbruksrörelse. När Scourge vällde fram över Lordaeron vägrade den aristokratiska familjen Agamand att fly från sina värdefulla marker. I stället uppmanade de sitt hushåll och sina arbetare att ta till vapen tillsammans med dem och lovade att de kunde försvara gårdarna mot den odöda horden. Coleman och hans arbetskamrater stannade och trodde på sina herrar – ett beslut som kostade varenda en av dem livet."},{t="Hämnd från graven",b="Coleman uppväcktes som odöd och bröt sig fri under de Fördömdas fana. Han hyser ett brinnande hat mot Agamands. Han klandrar inte bara Scourge, utan också sina arbetsgivares rena högmod och girighet, som lurade personalen att delta i en omöjlig sista strid. Nu hänger Coleman i Brills värdshus och värvar Hordens kämpar för att tåga till de pesthärjade kvarnarna, fälla de återuppståndna Agamandsläktingarna och plundra arvegodsvapnen i deras familjekrypta, så att inte ens den sista resten av deras ära blir kvar."}},faq={{q="Var hittar man Coleman Farthing?",a="Coleman Farthing tillbringar dagarna på Gallows' End Tavern i Brill, mitt i Tirisfal Glades.",al={"coleman farthing plats","var finns coleman farthing","coleman farthing brill"}},{q="Varför hatar Coleman familjen Agamand så mycket?",a="När Scourge invaderade Lordaeron övertalade Agamandfamiljens överhuvuden sina arbetare, däribland Coleman, att stanna och försvara kvarnarna i stället för att fly i säkerhet. Hela arbetsstyrkan blev slaktad. Coleman ser deras uppmaning som arrogant manipulation som ledde honom rakt i döden.",al={"varför hatar coleman agamands","coleman farthing motiv","gammalt agg mot agamand mills"}},{q="Vad hände med Agamand Mills?",a="Den vidsträckta egendomen blev helt översvämmad av Scourge. De vinddrivna kvarnarna står i ruiner och hemsöks, medan familjen Agamands medlemmar och deras slaktade arbetare vandrar genom de pesthärjade fälten som tanklösa, fientliga odöda under Lich Kings herravälde.",al={"vad hände med agamand mills","agamand mills berättelse","vem äger agamand mills"}},{q="Vilka uppgifter ger Coleman äventyrare?",a="Coleman skickar äventyrare norrut till Agamand Mills för att decimera de kringströvande odöda, dräpa de återuppståndna medlemmarna av Agamandsläkten och hämta deras kvarlevor för vanhelgning samt plundra Agamand Family Crypt på förfädernas vapen.",al={"coleman farthing uppdrag","agamand uppdrag brill"}},{q="Varför vill Coleman ha Agamands arvegodsvapen?",a="Coleman ser Agamands förfäders vapen som symboler för det tomma högmod som ledde hans arbetskamrater i döden. Han skickar skickliga krigare för att plundra relikerna ur familjekryptan, både för att beröva dynastin dess ära och för att använda vapnen mot deras fiender.",al={"agamands arvegods uppdragsberättelse","varför stjäla agamands vapen"}},{q="Är Coleman Farthing släkt med Bishop Farthing?",a="De har samma efternamn och båda kommer från det fallna kungariket Lordaeron, men det finns inga bekräftade uppgifter om släktskap mellan dem.",al={"släktskap med bishop farthing","coleman farthings familj"}}},fx={["54a8df22"]={q="Vem är Coleman Farthing?",a="Coleman Farthing är en Forsaken som bor på Gallows' End Tavern i Brill. I livet var han arbetare hos den rika familjen Agamand vid deras kvarnar i västra Tirisfal Glades. När Scourge drog fram genom Lordaeron övertalade hans herrar honom och de andra arbetarna att stanna och slåss i stället för att fly. Kvarnarna invaderades och alla där slaktades. Nu har han återuppväckts med fri vilja under Dark Lady och är uppfylld av bitter vrede mot familjen som ledde honom till en fasansfull död.",al={"vem är coleman farthing","coleman farthing bakgrund","vem är coleman"}},["3d5d2be6"]={q="Vems sida står Coleman Farthing på?",a="Coleman Farthing står stadigt på Forsakens och Hordens sida. Han lever bland sina odöda fränder i Brill, i säkerhet från den viljelösa Scourge som hemsöker ruinerna från hans forna liv. Han stöder Forsakens kamp för att säkra Tirisfal Glades, men hans fokus är djupt personligt: han skickar förbipasserande äventyrare för att göra upp med herrarna som dömde honom till döden.",al={"coleman farthing fraktion","är coleman med i horden","vem tjänar coleman"}},ac8a2a0f={q="Vad vill Coleman Farthing?",a="Coleman vill ha fullständig hämnd på familjen Agamand. Han vill se kvarlevorna av sina forna herrar, Gregor, Nissa, Thurman och Devlin, fullständigt förstörda så att han kan stampa på dem. Han vill också att deras förfäders krypta plundras på dess värdefulla arvegodsvapen och att den stolta dynastin berövas sin värdighet, sin släktlinje och sin viloplats.",al={"vad vill coleman","coleman farthings mål","coleman mål"}},["3e94941c"]={q="Varför är Coleman Farthing här i Brill?",a="Coleman stannar på Gallows' End Tavern i Brill eftersom värdshuset är den främsta samlingsplatsen för nyuppståndna odöda och Hordens resande på väg norrut. Han är inte stark nog att ensam anfalla de övertagna Agamand Mills, så han väntar bland resenärerna och värvar dugliga krigare och besvärjare som kan marschera nordväst och utkräva hämnd åt honom.",al={"varför är coleman i brill","varför är coleman på gallows end","coleman farthing brill"}}},fp="16,296,16.456.0,24.432.0,36.97.0,49.279.0,35.224.0,44.227.0,51.265.0,47.153.0"}
P.entries["npc:collin-mauren"] = {n="Collin Mauren",s="I Mage Quarter i Stormwind studerar Collin Mauren praktisk magi och skapar användbara besvärjelser av naturliga reagenser. Han skapar också arkana skriftrullar åt sin vän Gaxim Rustfizzle, en gnomisk ingenjör och upptäcktsresande.",h="I Mage Quarter i Stormwind studerar Collin Mauren praktisk magi och skapar användbara besvärjelser av...",kw={"basilisk","collin mauren","dust devils","gaxim rustfizzle","mage quarter","stonetalon","stormwind","westfall"},ang={["class:Mage"]="Som magiker kan du se Collins experimentella syn på besvärjelser: han använder reagenser som elementärt skräp och basiliskfjäll för att väva samman nyttomagi.",["faction:Alliance"]="Som medlem av alliansen kan du se hur Collin förser äventyrare med nyttomagi för kommunikation och handel över hela fraktionen, från Westfall till Kalimdor.",["race:Human"]="Som människa delar du stad med Collin. Hans stillsamma studier i Stormwinds Mage Quarter speglar människomagikernas lärda strävanden."},sec={{t="Den arkanas lärdom",b="I Mage Quarter i Stormwind studerar Collin Mauren magins praktiska användning. Han skapar arkana formler för att lösa specifika problem och använder naturliga anomalier och råmaterial som samlats in över Azeroth. Deras egenskaper hjälper honom att skapa funktionella skriftrullar och reagenser åt vänner och resenärer."},{t="Hjälper Gaxim Rustfizzle",b="Collin Mauren hjälper sin vän Gaxim Rustfizzle att fjärrutlösa NG-5-sprängladdningar. Gaxim, en gnomisk uppfinnare, behövde ett sätt att utlösa dem på avstånd, så Collin utformade en meddelandebesvärjelse till en skriftrulle. För att överföra besvärjelsen till skriftrullen använder Collin skräp från Westfalls oberäkneliga Dust Devils. Han väntar på att få höra hur det går med Gaxims plan."},{t="Exotiska studier i Stonetalon",b="Collin Maurens studier sträcker sig från Stormwind över Stora havet till Kalimdors Stonetalon Mountains. Han söker efter fjällen från områdets basilisker, vars tåliga hudar intresserar honom som material för att skapa nya besvärjelser. Resenärer på väg till Kalimdor får ofta hans förfrågningar om dessa sällsynta hudar. Fjällen ligger till grund för hans studier av hur urvarelsers anatomi kan stabilisera komplexa förtrollningar."}},faq={{q="Var hittar man Collin Mauren?",a="Collin Mauren finns i Mage Quarter i Stormwind City, bland tornen och butikerna som huvudstadens arkanister använder.",al={"collin maurens plats","var finns collin mauren","collin mauren stormwind"}},{q="Vilken sorts magi specialiserar sig Collin på?",a="Collin specialiserar sig på praktiska förtrollningar och nyttoformler. Han experimenterar med naturliga komponenter som elementärt skräp och bestfjäll för att skapa skriftrullar, däribland en meddelandebesvärjelse för Gaxims fjärrutlösta sprängladdningar, samt andra unika besvärjelser.",al={"collin maurens forskning","vad gör collin mauren","collin maurens magi"}},{q="Vem är Gaxim Rustfizzle och hur känner Collin honom?",a="Gaxim Rustfizzle är en äventyrlig gnomisk uppfinnare och Collins vän. När Gaxim behövde fjärrutlösa sina sprängladdningar skapade Collin en skriftrulle med en meddelandebesvärjelse åt honom.",al={"gaxim rustfizzles vän","collin och gaxim","vem är gaxim rustfizzle"}},{q="Varför behöver Collin elementärt skräp från Westfall?",a="Collin behöver skräp från en av Westfalls Dust Devils för att överföra en meddelandebesvärjelse till en skriftrulle. Gaxim Rustfizzle behöver besvärjelsen för att fjärrutlösa sina NG-5-sprängladdningar.",al={"questen devils in westfall","varför dust devils","questen westfall dust devils"}},{q="Varför är Collin intresserad av Stonetalon Mountains?",a="Collin studerar basiliskfjäll från Stonetalon Mountains i Kalimdor för deras magiska egenskaper. Han använder deras tåliga, naturligt motståndskraftiga hudar som grund för att skapa nya besvärjelser.",al={"basilisker i stonetalon","hämtning åt mauren","stonetalonfjäll collin"}},{q="Tillhör Collin Kirin Tor?",a="Collin bor i Mage Quarter och utövar traditioner som är vanliga bland alliansens magiker. Han arbetar främst som oberoende forskare och reagentmakare, snarare än som aktiv representant för Dalaran.",al={"tillhör collin kirin tor","collin mauren dalaran","collin i mage quarter"}}},fx={f243f9d9={q="Vem är Collin Mauren?",a="Collin Mauren är en mänsklig magiker som bor i Mage Quarter i Stormwind City. Han är en lärd forskare och skapar besvärjelser, och experimenterar med arkaniska formler och förtrollat pergament. Med sällsynta komponenter från avlägsna länder tillverkar han magiska skriftrullar åt sina gelikar och resande äventyrare.",al={"vem är collin","collin maurens bakgrund","vem är mauren"}},b186ecef={q="Varför är Collin Mauren i Stormwind?",a="Collin bor i Stormwinds Mage Quarter, omgiven av stadens bibliotek, akademier och andra utövare av arkana konster. I denna livliga tillflyktsort kan han utföra sina experiment i lugn och ro och få tag på exotiska reagenser som äventyrare för med sig till huvudstaden.",al={"varför är collin här","varför är collin mauren i stormwind","vad gör collin i stormwind"}},["8e195ded"]={q="Vad vill Collin Mauren?",a="Collin söker ovanliga mystiska reagenser för att fullända sitt besvärjelsehantverk. Han skaffar elementrester från Westfalls stördjäklar för att skapa särskilda meddelanderullar åt sin vän Gaxim Rustfizzle, eller basiliskfjäll från Stonetalon Mountains. Han drivs av arkanisk nyfikenhet och nyfikna resenärers önskemål.",al={"collin maurens motiv","vad vill collin","vad letar collin efter"}}},fp="13,203,21.269.0,23.321.0,28.375.0,33.126.0,45.257.0,59.178.0,52.180.0,53.181.0,37.204.0"}
P.entries["npc:colonel-kurzen"] = {n="Colonel Kurzen",s="Colonel Conrad Kurzen var en gång en dekorerad och ädel officer i Stormwind-armén, utsänd för att leda en expedition till norra Stranglethorn Vale. Efter att plötsligt ha blivit galen och tyrannisk förvandlade han sin styrka till en laglös djungelmilis som utgår från en beväpnad anläggning. I dag söker hans tidigare underordnade vid närliggande Rebel Camp aktivt hans död för att få slut på hans skräckvälde.",h="Colonel Conrad Kurzen var en gång en dekorerad och ädel officer i Stormwind-armén, utsänd för att leda en...",kw={"colonel kurzen","conrad kurzen","doren","kurzen","kurzen's compound","rebel camp","stockpile","stranglethorn vale"},ang={["class:Warrior"]="Kurzen är ett varnande exempel på hur disciplinerad militär styrka kan kuvas och förvridas helt när viljan och hedern berövas den.",["faction:Alliance"]="Kurzen står för en allvarlig militär skandal och en tragisk förlust av Stormwind-soldater. Därför godkänner Alliansens befäl och lokala lojalister att han röjs ur vägen.",["race:Human"]="För Stormwinds människor var Kurzen en gång en jämlike och en respekterad ledare. Hans brutala fall i tyranni påminner dem mörkt om djungelns faror."},sec={{t="Ett fall från nåd",b="Före sitt fall ansågs Colonel Conrad Kurzen i Stormwind vara en ovanligt skicklig och ädel officer. Kungarikets ledning litade på honom och gav honom befälet över en expeditionsstyrka som skickades söderut, in i Stranglethorn Vales täta djungler. Men djupt inne i de fuktiga vildmarkerna började Kurzen uppvisa oberäkneligt beteende och extrem storhetsvansinne. Han förklarade att han ensam härskade över den omgivande vildmarken och övergav sin trohet till Stormwind."},{t="Upproret",b="Kurdens plötsliga förvandling splittrade leden. Många soldater föll för blind lojalitet eller förvriden fanatism, men andra bestördes av hans galenskap och brutalitet. Dit hörde hans handling att kasta Emerine Junis i anläggningens fängelse enbart för att hon avvisade hans närmanden. Under ledning av Lieutenant Doren bröt sig en grupp samvetsömma soldater loss och grundade Rebel Camp längs den norra vägen. Dessa avhoppade lojalister för nu ett desperat krig mot Kurzen för att stoppa hans framfart."},{t="Ogren bakom kulisserna",b="Kurdens galenskap berodde varken på djungelfeber eller naturlig utmattning. Översten föll offer för mörk magi som utövades av Mai'Zoth, en slug ogremagiker ur Mosh'ogg-klanen. Genom att ta Kurzens sinne i besittning förvandlade Mai'Zoth en disciplinerad avdelning Stormwind-soldater till våldsamma marionetter. Han styrde Kurzen till att ta kontroll över regionen, utan att ogres själva behövde inleda ett öppet krig."}},faq={{q="Varför vände sig Colonel Kurzen mot Stormwind?",a="Någon gång under sin expedition till Stranglethorn Vale började Kurzen uppvisa oberäkneligt beteende och storhetsvansinne och övergav sin trohet till Stormwind. Vad som drev den en gång ädle översten till galenskap är ett mysterium som hans tidigare soldater vid Rebel Camp fortfarande försöker lösa.",al={"varför är kurzen ond","vad hände med kurzen","kurzens bakgrund"}},{q="Var finns Colonel Kurzen?",a="Han leder sin milis från en plats djupt inne i Kurzen's Compound, bland kullarna i norra Stranglethorn Vale. Han håller till i den befästa byggnaden Stockpile längst bak i lägret.",al={"var hittar man kurzen","kurzens plats","colonel kurzens compound"}},{q="Vilka är rebellerna vid Rebel Camp?",a="Rebellerna är tidigare soldater under Kurzens befäl som vägrade följa honom i hans galenskap. Under ledning av Lieutenant Doren är de fortfarande lojala mot Stormwind och utgår från Rebel Camp nära den norra gränsen. De försöker göra slut på Kurzens laglösa armé.",al={"rebel camps bakgrund","vem är lieutenant doren","varför rebel camp"}},{q="Vem är Emerine Junis?",a="Emerine Junis var knuten till expeditionen och avvisade Kurzens ovälkomna närmanden. När översten blev allt grymmare och mer verklighetsfrånvänd låste han in henne i anläggningens fängelseburar.",al={"emerine junis","kurzens fånge"}},{q="Agerar Kurzen ensam i djungeln?",a="Nej. Han för befäl över de mänskliga legosoldater, soldater och djungelkrigare som förblev lojala mot honom efter att rebellerna brutit sig loss och tagit sig till Rebel Camp.",al={"vem arbetar kurzen för","kurzens allierade"}},{q="Vad händer om Colonel Kurzen dödas?",a="Lieutenant Doren ber Alliansens äventyrare att skilja Kurzens huvud från kroppen för att bevisa överstens död, slå sönder milisens befälskedja och återupprätta Stormwind-arméns heder.",al={"slutet på kurzen-uppdraget","doren och kurzens huvud"}}},fp="14,386,17.474.0,13.497.0,27.387.2,46.275.2,32.195.0,37.261.0,21.190.0,37.141.2,40.194.1"}
P.entries["npc:commander-mar-alith"] = {n="Commander Mar'alith",s="Commander Mar'alith är den ståndaktige militäre befälhavaren bland nattalverna som leder Cenarion Circles förtrupp vid Cenarion Hold i Silithus. Han bär tung rustning och svingar en väldig glaive, och samordnar det väpnade motståndet mot silithidsvärmarna och kultisterna i Twilight's Hammer. Under hans beslutsamma ledarskap döljer sig en djup personlig sorg över hans älskade hustru Natalias mystiska öde.",h="Commander Mar'alith är den ståndaktige militäre befälhavaren bland nattalverna som leder Cenarion Circles...",kw={"cenarion circle","cenarion hold","commander mar'alith","hive'ashi","hive'regal","hive'zora","mar'alith","natalia mar'alith","silithus"},ang={["class:Warrior"]="Mar'alith bär tung plåtrustning och svingar en väldig glaive. Han leder striderna på slagfältet i en bosättning som främst befolkas av mystiker och naturväktare.",["race:NightElf"]="Mar'alith förkroppsligar de kaldoreiska väktarnas och krigarnas hängivenhet. De står vakt sida vid sida med druiderna och försvarar Kalimdor mot forntida hot trots stora personliga uppoffringar."},sec={{t="Befälhavare vid fästet",b="Commander Mar'alith är stationerad i hjärtat av Cenarion Hold och bär det enorma ansvaret att skydda Circle:s ökenbastion. Medan druiderna försöker reda ut Silithus forntida ekologiska och kosmiska anomalier hanterar Mar'alith krigets dystra, praktiska krav. Han övervakar taktiska anfall mot de myllrande silithidkuporna i Hive'Ashi, Hive'Zora och Hive'Regal och ser till att de obevekliga insektsintrången inte övermannar expeditionens centrala fäste."},{t="Sorg i öknen",b="Trots sin strama militära hållning är Mar'alith tydligt märkt av en fruktansvärd personlig tragedi. Hans älskade hustru, Natalia Mar'alith, gav sig ut i den skiftande sanden på ett uppdrag för Circle och återvände aldrig. Befälhavaren slits mellan plikten mot Cenarionexpeditionen och en plågsam sorg, och verkar alltmer frånvarande medan han klamrar sig fast vid det lilla hopp som finns kvar och desperat väntar på besked om vad som egentligen hände henne i ödemarken."},{t="Ett tragiskt öde",b="Den fruktansvärda sanningen om Natalias försvinnande tynger befälhavaren. De som följer hennes spår upptäcker att hon föll offer för vansinne bland öknens viskningar och hjärntvättades av en Qiraji-kristall till att tjäna C'Thun. När Mar'alith får veta hennes tragiska slut blir han djupt skakad och tvingas uthärda en förödande hjärtesorg samtidigt som han fortsätter att leda försvaret av Silithus mot fasorna som hotar under jord."}},faq={{q="Vem är Commander Mar'alith?",a="Commander Mar'alith är en officer bland nattalverna och högste militäre befälhavare för Cenarion Circles styrkor vid Cenarion Hold. Han organiserar spejare, försvarsstyrkor och taktiska anfall mot silithidkuporna i Silithus.",al={"maralith","vem är commander maralith","nattalv befälhavare silithus"}},{q="Var hittar man Commander Mar'alith?",a="Han finns inne i Cenarion Hold, den främsta neutrala bosättningen som Cenarion Circle har grundat i Silithus vindpinade sand.",al={"maralith plats","var finns maralith"}},{q="Vad hände med hans hustru Natalia?",a="Natalia Mar'alith försvann i öknen under en expedition och återvände aldrig. Äventyrare som följer hennes spår genom Silithus kan ta reda på vad som hände henne.",al={"var finns natalia","älskade natalia","natalia maralith öde"}},{q="Varför verkar Mar'alith frånvarande?",a="Befälhavaren plågas av sorg och oro över sin hustrus frånvaro och öde, vilket ofta distraherar honom medan han försöker leda fästningens försvar.",al={"varför är maralith distraherad","maralith beter sig märkligt"}},{q="Vilka uppgifter ger Commander Mar'alith äventyrare?",a="Mar'alith ger stridsuppdrag där hjältar ska decimera silithidstyrkor i Hive'Ashi, Hive'Zora och Hive'Regal, bekämpa Twilight's Hammer och undersöka sin försvunna hustrus öde.",al={"maralith uppdrag","vilka uppdrag ger maralith"}},{q="Är Commander Mar'alith en druid?",a="Nej. Även om han tjänar Cenarion Circle är Mar'alith en bepansrad väktare och krigarbefälhavare som leder expeditionens väpnade försvar och taktiska operationer i stället för att utöva druidisk magi.",al={"är maralith en druid","maralith klass"}}},fp="19,402,21.489.0,19.443.0,13.455.1,27.236.0,39.137.0,35.163.1,38.186.0,58.197.0,31.204.0"}
P.entries["npc:commander-springvale"] = {n="Commander Springvale",s="Commander Springvale var en gång en hängiven paladin och befälhavare i Shadowfang Keep. Han dödades tillsammans med sina män under den vilda worgenmassakern som Archmage Arugal iscensatte. Hans hämndlystna ande dröjer kvar och hemsöker slottets salar. Även efter döden vaktar hans vålnad fästningen ursinnigt mot alla som träder in.",h="Commander Springvale var en gång en hängiven paladin och befälhavare i Shadowfang Keep.",kw={"arugal","befälhavare","spöke","paladin","shadowfang","silverlaine","silverpine","springvale","worgen"},ang={["class:Paladin"]="Springvale påminner på ett bistert sätt om hur plikt och heliga eder kan förvandlas till evig pina när en hedervärd riddare binds vid en fördärvad grav.",["faction:Alliance"]="Springvale representerar Lordaerons och Gilneas förlorade soldater, trogna försvarare som inte föll direkt för Scourge utan för de vårdslösa besvärjelser som skulle stoppa dem.",["faction:Horde"]="För Forsaken som återtar Silverpine Forest är det ytterligare ett steg i att rena området från resterna av Arugal's tragiska misslyckande att låta befälhavarens skugga finna ro."},sec={{t="Den fallne befälhavaren",b="Före Shadowfang Keeps fall var Commander Springvale en hedervärd paladin, hängiven det heliga ljuset. Han ledde garnisonen i Silverpine Forest och ansvarade för fästningens säkerhet under de oroliga dagarna efter att Lordaeron fallit för Scourge."},{t="Arugal's Folly",b="När Archmage Arugal kallade fram worgen från andra världar för att förstärka Dalarans sviktande led mot de odöda i Scourge, gled de vilda bestarna snabbt ur magikerns kontroll. Den glupska flocken vällde in i fästningen och slaktade Baron Silverlaine och hela hans vaktstyrka. Springvale dog i salarna han svurit att skydda, och hans tjänst fick ett våldsamt slut."},{t="En ändlös vakt",b="Döden gav inte Springvale någon befrielse. Hans vålnad hemsöker fästningens rådssal tillsammans med dess spektrala soldater. Han använder fortfarande paladinkrafter, däribland Holy Light och Hammer of Justice, mot inkräktare."}},faq={{q="Vem var Commander Springvale i livet?",a="Commander Springvale var en paladin av det heliga ljuset och befälhavare i Shadowfang Keep. Han dog där när Arugals worgen intog fästningen.",al={"springvales bakgrund","vem är commander springvale","är springvale en paladin"}},{q="Hur dog Commander Springvale?",a="Han dödades när Archmage Arugal kallade fram vilda worgen för att strida mot Scourge. De otämjda bestarna vände sig mot invånarna i Shadowfang Keep och massakrerade Baron Silverlaine, Springvale och garnisonen.",al={"hur dog springvale","vem dödade springvale","springvales död"}},{q="Varför hemsöker Commander Springvale Shadowfang Keep?",a="Hans ande är förvriden i döden och bunden av sina sista eder. Springvales vålnad vandrar genom salarna för att försvara ruinerna mot alla som träder in.",al={"varför är springvale ett spöke","springvales motiv","varför slåss springvale"}},{q="Vilka krafter använder Springvale?",a="Springvale behåller sina paladinförmågor i odödenheten. Han helar med Holy Light och bedövar fiender med Hammer of Justice.",al={"varför ohelig magi","springvales oheliga förmågor","fördärvad paladin"}},{q="Vem var hans herre?",a="Inga källor namnger den herre han tjänade. Han är endast känd som en befälhavare som föll när Arugals worgen intog Shadowfang Keep, Baron Silverlaines säte.",al={"springvales herre","vem tjänade springvale","springvale och silverlaine"}},{q="Var i fästningen kan man hitta honom?",a="Man stöter på Commander Springvales vålnad djupt inne i fästningen, där den hemsöker de befästa kamrarna nära slottets kapell och rådssalar.",al={"springvales plats","var finns springvale","springvales rum i shadowfang"}}},fx={ccdbb916={q="Vems sida står Commander Springvale på?",a="Commander Springvale tjänar ingen levande herre och är inte heller allierad med Archmage Arugal eller vargarna som har tagit över Shadowfang Keep. I döden hemsöker hans vålnad rådssalen i Shadowfang Keep tillsammans med sina spektrala soldater och slår ner alla levande inkräktare som kommer in i slottets salar.",al={"springvales fraktion","vem tjänar springvale","springvales lojalitet"}},["5e96515a"]={q="Vad vill Commander Springvale?",a="Även i döden är Commander Springvale bunden till Shadowfang Keep, där han föll. Fördärvad och odöd vänder han sin vrede mot alla inkräktare som vågar sätta sin fot i dess salar.",al={"springvales mål","vad försöker springvale göra","springvales motiv"}}},fp="20,197,20.258.0,14.318.0,16.197.0,37.153.0,33.176.0,53.124.0,32.115.0,19.156.0,34.122.0"}
P.entries["npc:cookie"] = {n="Cookie",s="Cookie är en elitmurloc som tjänstgör som skeppskock ombord på det jättelika skeppet, gömt djupt inne i The Deadmines. Han är en ovanlig rekryt i Defias Brotherhood och sköter besättningens kokgrytor under Captain Greenskins och Edwin VanCleefs vakande blick. Han är den enda helt valfria bossen i den underjordiska torrdockan.",h="Cookie är en elitmurloc som tjänstgör som skeppskock ombord på det jättelika skeppet, gömt djupt inne i The...",kw={"captain greenskin","kock","cookie","the deadmines","defias","edwin vancleef","ironclad cove","jätteskepp","murloc"},ang={["class:Rogue"]="VanCleefs nätverk av skurkar förlitar sig på märkliga och okonventionella resurser. Cookie visar att även brödraskapets försörjningslinjer rymmer oväntade överraskningar.",["faction:Alliance"]="Stormwinds spejare blir ofta förvånade när de hittar murlocer som arbetar aktivt inom Defias ledarskap, i stället för att bara hålla till längs Westfalls yttre stränder.",["profession:Cooking"]="Att en murloc utsetts till chefskock ombord på ett jätteskepp med laglösa vittnar om piratmatens desperata och oborstade standard."},sec={{t="Brödraskapets kock",b="Under däcken på det väldiga skeppet i Ironclad Cove faller matlagningen varken på en mänsklig spejare eller en gobliningenjör, utan på en ensam murloc som helt enkelt kallas Cookie. Hur han fick jobbet är det ingen som vet. Besättningen kanske tvivlar på att en murloc ska ansvara för ransonerna, men pirater har sällan råd att vara kräsna, och i Moonbrooks undre värld är mat mat."},{t="En bitter brygd",b="Cookie patrullerar vattenvägarna och stränderna kring piraternas flaggskepp och svingar sina köksredskap tillsammans med frätande brygder. Trots att han är isolerad från vanliga murlocstammar försvarar han sin gryta med vild häftighet och kastar frätande blandningar mot inkräktare som irrar sig in i hamnen. Eftersom hans arbetsplats ligger en bit från huvudlandgångarna går många som stormar viken förbi köket helt och hållet. Därför är han den enda valfria befälhavaren ombord på Defias jätteskepp."}},faq={{q="Varför arbetar en murloc som kock åt Defias?",a="Det finns inga uppgifter om hur Cookie började tjänstgöra ombord på jätteskeppet. Defias laglösa och goblinskeppsbyggare accepterar helt enkelt arrangemanget, eftersom piratbesättningar tar mat där de kan få tag på den, oavsett kockens art.",al={"varför murloc som kock","varför är cookie på skeppet","cookie och defias-lore"}},{q="Var hittar man Cookie i The Deadmines?",a="Cookie finns i Ironclad Cove, längst in i The Deadmines. Han patrullerar det grunda vattnet och kajerna nära aktern på det jättelika träskeppet, strax bortom rampen där Mr. Smite står vakt.",al={"var finns cookie","cookies plats i the deadmines","hitta cookie"}},{q="Måste man besegra Cookie för att klara The Deadmines?",a="Nej, Cookie är hålans enda valfria boss. Inkräktare kan gå ombord på skeppet direkt och möta Captain Greenskin och Edwin VanCleef utan att störa kockens patrull längs stranden.",al={"är cookie valfri","måste man döda cookie","hoppa över cookie"}},{q="Tillhör Cookie en särskild murlocstam?",a="Cookie är inte knuten till någon av de kända lokala murlocstammarna, till exempel dem längs Westfalls kust. Han bor och arbetar helt och hållet bland Defias Brotherhoods laglösa och skurkar.",al={"vilken stam tillhör cookie","cookies murlocstam"}},{q="Vilka vapen eller attacker använder Cookie?",a="Cookie använder köksredskap i närstrid och kan kasta frätande syra på angripare. De farliga matblandningarna bränner dem.",al={"cookies förmågor","hur slåss cookie","cookies attacker"}},{q="Vem rapporterar Cookie till ombord på jätteskeppet?",a="Cookie tjänstgör direkt under Defias Brotherhoods sjöstridskrafter, som leds av Captain Greenskin, och ytterst av Edwin VanCleef själv.",al={"cookie boss","vem leder cookie","cookie greenskin vancleef"}}},fx={f44f954f={q="Vem är Cookie?",a="Cookie är en mäktig murloc som tjänstgör som skeppskock ombord på Edwin VanCleefs järnklädda stridsfartyg, djupt inne i Deadmines. Till skillnad från de flesta vilda murlocer som strövar längs Westfalls stränder har Cookie funnit ett ovanligt hem bland mänskliga laglösa. Han lagar tvivelaktiga måltider i sin kittel åt Defias Brotherhoods piratbesättning.",al={"vem är cookie","cookies identitet","vem är murlockocken"}},c6e0c482={q="Vems sida står Cookie på?",a="Cookie är helt lojal mot Defias Brotherhood. Han är stationerad på stridsfartyget tillsammans med Captain Greenskin och Edwin VanCleef och tjänar piraterna direkt. Han försvarar skeppet ursinnigt mot alla alliansinkräktare som försöker sätta stopp för VanCleefs uppror.",al={"cookies lojalitet","är cookie med i defias","vilken fraktion tillhör cookie"}}},fp="6,253,22.348.0,13.437.0,49.210.0,43.188.0,43.192.0,46.180.0,40.148.0,44.130.0"}
P.entries["npc:corithras-moonrage"] = {n="Corithras Moonrage",s="Corithras Moonrage är en nattalvslärd och uppdragsgivare i byn Dolanaar på Teldrassil. Han hjälper nyanlända äventyrare att förstå det stora världsträdets natur och ger dem i uppdrag att vårda dess heliga månbrunnar. Genom sina lektioner visar han både Teldrassils andliga betydelse och de växande bördor som kaldorei bär.",h="Corithras Moonrage är en nattalvslärd och uppdragsgivare i byn Dolanaar på Teldrassil.",kw={"corithras moonrage","crown of the earth","dolanaar","fandral staghelm","kaldorei","månbrunn","night elf","teldrassil"},ang={["class:Druid"]="Druider känner igen hur nära Corithras uppgifter är knutna till deras kall, eftersom hans månbrunnsriter direkt följer världsträdets hälsa och de krypande sjukdomarna.",["class:Priest"]="Elunes präster hjälper Corithras att bära månbrunnarnas välsignade vatten och bevara den andliga och fysiska harmonin i vildmarken kring Dolanaar.",["race:NightElf"]="För nattalver är ett samtal med Corithras en grundläggande lektion om verkligheten efter det tredje kriget. Där möter de förlusten av den uråldriga odödligheten och den omstridda skapelsen av Teldrassil."},sec={{t="Lärd i Dolanaar",b="Corithras Moonrage bor i den skuggiga byn Dolanaar och undervisar resenärer som lämnar Shadowglens skyddade gränser. När unga kaldorei ger sig ut bland Teldrassils vidsträckta grenar ser Corithras till att de förstår sitt nya hems historia. Han lär dem att överlevnad i denna föränderliga tid kräver vaksamhet och vördnad för naturens ordning."},{t="Crown of the Earth",b="En stor del av Corithras uppgifter kretsar kring att samla månbrunnsvatten åt druiderna i Darnassus. Han ber äventyrare hämta rent vatten från månbrunnar runt om på Teldrassil i särskilt tillverkade flaskor, för leverans till Fandral Staghelm. Genom dessa prövningar håller han uppsikt över världsträdets hälsa och försöker bevara vildmarkens känsliga balans mot den krypande korruptionen."},{t="Kaldoreis börda",b="Under Corithras vägledning finns en oroande sanning om Teldrassils skapelse. Till skillnad från det uråldriga Nordrassil restes detta nya världsträd utan Drak aspekternas välsignelser, eftersom de avböjde Fandral Staghelms storslagna skapelse. Corithras begrundar förlusten av nattalvernas odödlighet och den sköra, ovissa framtid som kaldorei nu står inför under ett ovälsignat träds grenar."}},faq={{q="Vem är Corithras Moonrage?",a="Corithras Moonrage är en nattalvslärd i Dolanaar. Han berättar för äventyrare om Teldrassils historia och ger dem i uppdrag att vårda de heliga månbrunnarna och pröva världsträdets vatten.",al={"corithras moonrages roll","vem är corithras","uppdragsgivare i dolanaar"}},{q="Var hittar man Corithras Moonrage?",a="Han står utomhus i Dolanaar, byn med det centrala vägskälet i de södra delarna av Teldrassil.",al={"corithras plats","var finns corithras","hitta corithras"}},{q="Vad handlar uppdragskedjan Crown of the Earth om?",a="Uppdragen i Crown of the Earth går ut på att hämta vatten från månbrunnar runt om på Teldrassil. Corithras samlar vattnet för leverans till Fandral Staghelm i Darnassus, där druiderna behöver fylla på sin månbrunn.",al={"innebörden av crown of the earth","corithras uppdrag","månbrunnsuppdrag"}},{q="Varför oroar sig Corithras för Teldrassils ursprung?",a="Corithras berättar hur Teldrassil planterades efter det tredje kriget för att återställa nattalvernas odödlighet. Eftersom Drak aspekterna vägrade välsigna trädet är Corithras väl medveten om att det saknar gudomligt skydd och att hans folk fortfarande är dödligt.",al={"varför kaldoreis börda","aspekternas vägran","varför ingen odödlighet"}},{q="Vad lär Corithras nya äventyrare?",a="Han lär ut om de uppoffringar som gjordes under det tredje kriget, grundandet av Teldrassil och det ansvar varje kaldorei har att försvara sitt nya skogshem.",al={"corithras berättelse","dolanaars historia","vad berättar corithras"}},{q="Är Corithras knuten till Cenarion Circle eller Darnassus?",a="Han tjänar Darnassus troget som invånare och lärd i Dolanaar. Han samarbetar nära med både druider och präster för att hålla uppsikt över skogens och vattnets välmående.",al={"corithras fraktion","är corithras druid"}}},fx={a5e544f2={q="Vad vill Corithras Moonrage?",a="Corithras vill vårda och förstå hälsan hos det unga världsträdet. Genom ritualen Crown of the Earth ger han resande i uppdrag att samla livgivande vatten från heliga månbrunnar över hela Teldrassil och välsigna de mäktiga grenarna. Han strävar efter att vårda landet och förstå de bördor som tynger kaldorei.",al={"vad vill corithras","corithras moonrages mål","corithras mål"}},["35aa58f2"]={q="Varför är Corithras Moonrage i Dolanaar?",a="Corithras är stationerad i den livliga bosättningen Dolanaar och vägleder nyanlända nattalvsäventyrare som ger sig ut från Shadowglen. Från sin plats i hjärtat av Teldrassil värvar han dugliga hjälpare till viktiga ritualer och undersökningar av de växande ekologiska och andliga problemen kring världsträdet.",al={"varför är corithras här","varför är corithras i dolanaar","corithras moonrage dolanaars syfte"}}},fp="18,173,19.310.0,18.301.0,26.324.1,26.159.0,38.100.0,47.209.0,54.216.0,42.146.0,59.139.0"}
P.entries["npc:councilman-millstipe"] = {n="Councilman Millstipe",s="Councilman Millstipe är medlem av Darkshires styrande råd och bor i Duskwoods rådhus. Han hyser djup bitterhet över kungamaktens försummelse och huvudstadens inblandning i rättskipningen och söker aktivt hämnd på brottslingar som hotar den mörka regionen.",h="Councilman Millstipe är medlem av Darkshires styrande råd och bor i Duskwoods rådhus.",kw={"councilman millstipe","darkshire","dextren ward","duskwood","adelshuset","millstipe","morbent fel","stockade"},ang={["class:Rogue"]="För en agent som är villig att smyga in i den hårt bevakade The Stockade och genomföra en politisk avrättning utan tillstånd erbjuder Millstipe ett uppdrag som direkt trotsar adelshuset.",["faction:Alliance"]="Millstipe personifierar den djupa politiska sprickan mellan Stormwinds skyddade adel och Duskwoods desperata gränsbygder, som får lite hjälp men utsätts för hårdhänt inblandning från huvudstaden."},sec={{t="Rättvisa nekas av Stormwind",b="Medan Darkshire kämpar mot de odödas skugga och våldsamma bestangrepp utkämpar det lokala rådet en uppförsbacke mot Stormwind Citys byråkrati. Councilman Millstipe ger röst åt stadens växande bitterhet mot kronan. När den ökände gravplundraren Dextren Ward ertappades med att sälja nyuppgrävda lik till nekromantikern Morbent Fel dömde Darkshires ledare honom till döden. I stället ingrep Stormwinds adelshus, omvandlade Wards dödsdom och låste in honom i tryggt förvar i Stormwind Stockade."},{t="Ett budskap till adeln",b="Millstipe vägrar låta huvudstadens korrumperade politiker åsidosätta Duskwoods säkerhet och rättvisa, och ger i hemlighet äventyrare i uppdrag att slutföra arbetet. Genom att beordra en summariskt verkställd avrättning av Dextren Ward i hans cell i The Stockade vill Millstipe sända ett tydligt budskap till adelshuset: om Stormwind vägrar skydda Duskwoods folk kommer folket att skipa rättvisa på egen hand."}},faq={{q="Var hittar man Councilman Millstipe?",a="Councilman Millstipe finns i Darkshires rådhus, i den östra delen av Duskwood.",al={"millstipes plats","var finns millstipe","hitta councilman millstipe"}},{q="Varför vill Millstipe att Dextren Ward ska dö?",a="Dextren Ward var en gravplundrare som grävde upp Duskwoods döda och sålde dem till nekromantikern Morbent Fel. Lord Ebonlocke dömde honom till halshuggning, men Stormwinds adelshus skonade hans liv och kastade honom i The Stockade i stället.",al={"varför döda dextren ward","millstipe dextren ward","wards brott"}},{q="Vad har Millstipe emot Stormwind?",a="Millstipe anser att Stormwind har övergett Duskwood samtidigt som staden lägger sig i den lokala rättskipningen. Adelshuset upphävde Darkshires rättmätiga dödsdom över Dextren Ward, vilket fick den traumatiserade bosättningen att känna sig ignorerad och oskyddad av tronen.",al={"varför arg på stormwind","adelshuset darkshire","millstipes politik"}},{q="Har Millstipe någon känd familj?",a="Det finns ingen känd familj till Councilman Millstipe.",al={"millstipes släktingar","dorothea millstipe","millstipes familj"}}},fx={["2e4c6610"]={q="Vem är Councilman Millstipe?",a="Councilman Millstipe är en framstående medlem av rådet som styr Darkshire i Duskwood. Han är frustrerad över Stormwinds försummelse och byråkratiska inblandning och arbetar i stadshuset för att skydda sitt hårt prövade folk. Han trotsar bestämt avlägsna adelsmän som undergräver Duskwoods gränsrättvisa.",al={"vem är millstipe","councilman millstipe","vem är councilman millstipe"}},["926d4bb5"]={q="Vems sida står Councilman Millstipe på?",a="Millstipe är lojal mot folket i Darkshire och Duskwoods råd. Även om han formellt tillhör Grand Alliance hyser han bitter vrede mot Stormwinds korrupta House of Nobles. Han står stadigt på sin hemstads sida mot avlägsna byråkrater som vägrar skicka hjälp.",al={"millstipes fraktion","är millstipe med i alliansen","vem tjänar millstipe"}},["78c3778b"]={q="Vad vill Councilman Millstipe?",a="Millstipe vill skipa gränsrättvisa i Duskwood och sända ett tydligt budskap till House of Nobles. Han är äcklad över att adelsmännen skonade gravplundraren Dextren Ward från avrättning och kräver att Ward dödas i Stockade för att visa att Duskwood inte tolererar Stormwinds korrupta inblandning.",al={"millstipes mål","vad vill millstipe","councilman millstipes mål"}},["7f6b4a90"]={q="Varför är Councilman Millstipe här?",a="Millstipe stannar i Darkshires stadshus för att sköta sina uppgifter i rådet. Därifrån hanterar han de tilltagande farorna i Duskwood, samordnar den lokala förvaltningen och värvar självständiga kämpar för att verkställa domar som Stormwinds domare vägrar genomföra.",al={"varför är millstipe i duskwood","varför är millstipe där","vad gör millstipe i darkshire"}}},fp="20,154,27.459.0,23.323.1,40.84.0,42.222.0,45.239.0,37.43.0"}
P.entries["npc:count-remington-ridgewell"] = {n="Count Remington Ridgewell",s="I Stormwind Keep vårdar Count Remington Ridgewell en samling som anstår en adelsmans stolthet. Han är en förmögen människa i House of Nobles och samlar på sällsynta artefakter, arvegods och konst.",h="I Stormwind Keep vårdar Count Remington Ridgewell en samling som anstår en adelsmans stolthet.",kw={"house of nobles","mayara brightwing","museum","perenolde tiara","petitioner's chamber","remington ridgewell","ridgewell","stormwind keep"},ang={["faction:Alliance"]="Som legosoldat i Alliansen kan du finna Count Ridgewell en lukrativ uppdragsgivare. Han betalar bra för reliker som återfunnits i fallna nordliga kungariken och förlorade dvärgstaden.",["race:Human"]="Som människa kan du se hur Stormwinds House of Nobles värdesätter kulturell status och konstsamlande, även mitt i rikets politiska instabilitet."},sec={{t="En kännare av fornfynd",b="Count Remington Ridgewell föredrar fornfynd framför fälttåg eller lokala uppror. Hans familjs privata museum rymmer smycken och artefakter, och han använder sin förmögenhet till att samla reliker från fallna civilisationer och adelshus i Azeroth. För att fylla sitt galleri finansierar han äventyrare och skickar fältagenter som Mayara Brightwing för att hämta sällsynta föremål från farliga ruiner, från Alteracs bergsfästen till Burning Steppes vulkaniska ödemarker."}},faq={{q="Vem är Count Remington Ridgewell?",a="Count Remington Ridgewell är en mänsklig adelsman och samlare av fornfynd i Stormwind Keeps Petitioner's Chamber. Han använder sin familjeförmögenhet till reliker, juveler och konst från hela världen.",al={"vem är remington ridgewell","remington ridgewell","count ridgewell"}},{q="Vilka artefakter söker Count Ridgewell?",a="Ridgewell söker förlorade arvegods till sitt museum. Bland dem finns Perenolde Tiara från Alteracs ruiner och historiska skatter från mörka järndvärgar i Ruins of Thaurissan.",al={"ridgewells uppdrag","uppdraget med perenolde tiara","vad vill han ha"}},{q="Vem är Mayara Brightwing?",a="Mayara Brightwing är en agent som arbetar för Count Ridgewell. Han skickade henne till Burning Steppes för att leta efter fornfynd i de uråldriga Ruins of Thaurissan.",al={"mayara brightwings koppling","vem är mayara"}},{q="Var hittar man Count Remington Ridgewell?",a="Count Remington Ridgewell finns i Petitioner's Chamber inne i Stormwind Keep, bland adelsmän och dignitärer som söker audiens hos det kungliga hovet.",al={"var finns count ridgewell","ridgewells plats","adelsman i petitioner's chamber"}}},fx={["7bd2f97e"]={q="På vems sida står Count Remington Ridgewell?",a="Count Ridgewell är en lojal adelsman i kungariket Stormwind och medlem av House of Nobles. Han står stadigt på Alliansens sida och bedriver sitt stöd till societeten och sina privata angelägenheter direkt från det kungliga residenset.",al={"count ridgewells fraktion","ridgewells lojalitet","vem tjänar ridgewell"}},ecd2a567={q="Varför är Count Remington Ridgewell i Stormwind Keep?",a="Som inflytelserik aristokrat och medlem av House of Nobles närvarar Count Ridgewell vid hovet i Petitioner's Chamber i Stormwind Keep. Härifrån upprätthåller han familjens anseende, sköter hovärenden och anlitar djärva äventyrare för att återfinna dyrbara reliker runt om i Azeroth.",al={"varför är ridgewell här","varför är count ridgewell i stormwind keep","ridgewell i petitioner's chamber"}}},fp="25,174,28.437.0,33.194.0,41.170.0,25.155.0,45.167.0"}
P.entries["npc:crane-operator-bigglefuzz"] = {n="Crane Operator Bigglefuzz",s="Crane Operator Bigglefuzz är en goblinhamnarbetare som sköter de tunga maskinerna i Ratchets hamn. Efter att en överlastad kranolycka spridit lasten över kajerna försöker han desperat hitta en värdefull stulen flaska innan hans överordnade märker något.",h="Crane Operator Bigglefuzz är en goblinhamnarbetare som sköter de tunga maskinerna i Ratchets hamn.",kw={"bigglefuzz","last","kranförare","kajer","mad magglish","portvin","ratchet","steamwheedle"},ang={["class:Rogue"]="Skurkar kan förstå hur snabbt tjuvar som Mad Magglish utnyttjar förvirringen vid kajen för att lägga beslag på ovärderligt smuggelgods mitt framför nosen på en goblin.",["profession:Engineering"]="Ingenjörer kan känna igen att överlastade riggar och kranar från Steamwheedle fortfarande är den främsta orsaken till industriolyckor längs Kalimdors kuster."},sec={{t="Olycka vid kajen",b="Precis som många goblinhamnarbetare satte Crane Operator Bigglefuzz effektivitet och snabbhet före grundläggande säkerhetsmarginaler. När han försökte hissa en alldeles för tung last från ett handelsfartyg vek sig kranen och lådor kraschade ner över Ratchets kajer. I kaoset passade skrupelfria lycksökare på. Bigglefuzz fick kämpa med att städa upp röran och rädda de värdefullaste varorna innan Gazlowe eller hamnmästarna drog av på hans lön."},{t="Det stulna portvinet",b="Olyckans värsta förlust var inte det trasiga träet, utan en låda med sällsynt nittionioårigt portvin. Innan Bigglefuzz hann säkra lasten snodde en svårfångad luffare vid namn Mad Magglish en flaska och försvann i gömställena. Nu riskerar Bigglefuzz att få stå till svars för en oersättlig förlust."}},faq={{q="Vem är Crane Operator Bigglefuzz?",a="Han är en goblinkranförare vid Ratchets kajer, ansvarig för att lasta och lossa sjöfrakt åt Steamwheedle Cartel.",al={"vem är bigglefuzz","kranförare","bigglefuzz ratchet"}},{q="Vad orsakade olyckan vid kajen?",a="Bigglefuzz försökte hissa alldeles för tung last på en gång med sin kran. Maskineriet gav vika och lasten föll ut över kajen.",al={"varför tappade kranen lasten","olycka vid ratchets kaj","kranolycka"}},{q="Vem stal från Bigglefuzz?",a="En skum bråkmakare vid namn Mad Magglish utnyttjade den utspridda lasten för att snappa åt sig en värdefull flaska nittionioårigt portvin och smita iväg.",al={"vem tog portvinet","mad magglish last","vem rånade bigglefuzz"}},{q="Varför oroar sig Bigglefuzz så mycket för den stulna flaskan?",a="Det nittionioåriga portvinet är oerhört sällsynt och dyrt. Om han förlorar det genom vårdslöshet väntar stränga ekonomiska straff eller värre från cheferna i Steamwheedle Cartel.",al={"varför bryr sig bigglefuzz om vinet","orsak till problem vid kajen"}}},fx={acbd2274={q="På vems sida står Crane Operator Bigglefuzz?",a="Bigglefuzz arbetar för Steamwheedle Cartel i den neutrala hamnen Ratchet. Liksom de flesta gobliner i staden är hans främsta lojalitet riktad mot handeln och arbetsgivarna, snarare än mot Horde eller Alliance. Han välkomnar alla äventyrare som vill göra affärer eller rätta till ett kostsamt misstag.",al={"bigglefuzz fraktion","vem arbetar bigglefuzz för","crane operator bigglefuzz lojalitet"}},e72c0e10={q="Vad vill Crane Operator Bigglefuzz?",a="Bigglefuzz vill att någon hämtar flaskan med 99-Year-Old Port som försvann när hans last spilldes ut över kajerna. En goblin vid namn Mad Magglish kom över den sällsynta årgången, och Bigglefuzz är desperat att få tillbaka den innan hans överordnade upptäcker missödet.",al={"vad behöver bigglefuzz","bigglefuzz mål","vad vill bigglefuzz att du gör"}},d46df1e8={q="Varför är Crane Operator Bigglefuzz här?",a="Bigglefuzz är stationerad vid kajerna i Ratchet för att sköta den stora lastkranen och flytta gods mellan handelsfartyg och land. Tyvärr blev kranen förstörd när han försökte hissa alldeles för mycket last på en gång, och hamnens gods skingrades över kajen.",al={"varför är bigglefuzz i ratchet","bigglefuzz syfte i ratchet","varför är bigglefuzz vid kajerna"}},eaf0ddf2={q="Vilka band har Crane Operator Bigglefuzz?",a="Bigglefuzz har band till Steamwheedle Cartel och ingår i Ratchets hamnarbetare. Hans nuvarande bekymmer knyter honom direkt till tjuven Mad Magglish, som stal värdefull sprit från lasten han spillde ut.",al={"bigglefuzz kontakter","vem har bigglefuzz band till","bigglefuzz och cartel"}}},fp="25,257,19.467.0,15.303.0,33.144.0,38.138.0,26.150.0,53.175.0"}
P.entries["npc:craven-drok"] = {n="Craven Drok",s="I Orgrimmar håller sig Craven Drok till The Cleft och söker resenärer för ett känsligt ärende. Han vill att de funderar över hur Alliansen ser på Horden.",h="I Orgrimmar håller sig Craven Drok till The Cleft och söker resenärer för ett känsligt ärende.",kw={"alliansrelationer","cleft of shadow","craven drok","orgrimmar"},ang={["class:Rogue"]="Som skurk kanske du känner dig hemma i The Cleft, där de som arbetar i det fördolda samlas och knyter kontakter som Drok.",["race:Orc"]="Som ork kanske du ser Craven Droks vana att hålla till i The Cleft som en skamfläck på den heder och det mod som ditt folk värdesätter."},sec={{t="En skugga i mörkret",b="Craven Drok undviker Orgrimmars solbelysta avenyer och strövar längs de vindlande stigarna under staden. The Cleft lockar häxmästare, skurkar och utövare av mindre hedervärda yrken. Drok håller sig undan och anlitar förbipasserande för diskreta ärenden, däribland ett som rör Hordens anseende hos Alliansen."}},faq={{q="Var hittar jag Craven Drok?",a="Craven Drok strövar längs de underjordiska stigarna i The Cleft, under Orgrimmars huvudstråk.",al={"craven drok plats","var finns craven drok","drok plats orgrimmar"}},{q="Varför kallas han ”Craven”?",a="Craven Drok gör skäl för sitt namn genom att smyga omkring i mörka grottor och hålla låg profil. Han anlitar andra för att utföra uppgifter som han helst undviker, i strid med orkernas ideal om mod och krigisk ära.",al={"varför kallas han craven","craven droks namn","är craven drok feg"}},{q="Vad har han med Alliansen att göra?",a="Craven Drok inleder Alliance Relations med att lovorda Thralls visdom och kunskap om människors seder. Han skickar resenärer till Keldran, som arbetar för att hindra Alliansen från att felaktigt tro att Horden har slutit pakter med den brinnande legionen.",al={"craven drok alliansen","alliansrelationer drok"}},{q="Vem skickar Craven Drok resande till?",a="Craven Drok skickar resenärer till Keldran, en magistuderande vars koja ligger nära Orgrimmars västra utgång. Med krigshövdingens välsignelse arbetar Keldran för att Horden inte ska misstas för en bundsförvant till den brinnande legionen.",al={"vem är keldran","droks kontakter"}}},fx={bb25e48e={q="Vem är Craven Drok?",a="Craven Drok är en orch som strövar omkring i den underjordiska grottan Cleft of Shadow under Orgrimmar. Bland stadens häxmästare, skurkar och skuggmagiker erbjuder han hemliga uppdrag åt äventyrare som vill ta sig an angelägenheter som rör Alliance.",al={"vem är drok","craven drok bakgrund","vem är craven drok"}},ff4e4871={q="Varför är Craven Drok i Cleft of Shadow?",a="Cleft of Shadow erbjuder avskildhet och diskretion, långt från Thralls hedersvakts vaksamma ögon ovanför. Craven Drok rör sig här nere, där skumma affärer och känsliga frågor om Hordes underrättelsetjänst och relationer med Alliance kan skötas i tysthet.",al={"varför är craven drok här","varför är craven drok i cleft of shadow"}}},fp="11,156,24.313.0,29.105.0,26.188.0,42.229.0,39.223.0"}
P.entries["npc:cyrus-therepentous"] = {n="Cyrus Therepentous",s="Cyrus Therepentous är en mäktig svart drakspawn som håller till i Slither Rocks djupa grottor i Burning Steppes. I stället för att genast slå ner inkräktare prövar han djärva dödliga för att se om de har styrkan att tjäna den svarta drakflygelns syften.",h="Cyrus Therepentous är en mäktig svart drakspawn som håller till i Slither Rocks djupa grottor i Burning...",kw={"svarta drakflygeln","burning steppes","cyrus therepentous","drakspawn","slither rock","smak av eld"},sec={{t="Härskaren över Slither Rock",b="Cyrus Therepentous håller till i en grotta vid Slither Rock och vakar över Burning Steppes vulkaniska klippor. Liksom många av sitt slag ser han ner på dödliga resenärer och förklarar att bara dårar skulle störa hans lya. Men bakom hans vildsinta yttre döljer sig en kall beräkning: i stället för att äta upp varje inkräktare på fläcken erbjuder han dem en dödlig utmaning mot sina undersåtar och är beredd att utnyttja dem som överlever lågornas prövningar."}},faq={{q="Vem är Cyrus Therepentous?",a="Cyrus Therepentous är en intelligent svart drakspawn som håller till i en grotta vid Slither Rock i Burning Steppes. Han tjänar den svarta drakflygeln och prövar dödliga äventyrare som vågar sig in i hans lya.",al={"cyrus therepentous","vem är cyrus","drakspawn vid slither rock"}},{q="Var kan man hitta Cyrus Therepentous?",a="Han håller till djupt inne i en grotta vid Slither Rock, i den nordöstra delen av Burning Steppes.",al={"cyrus plats","var finns cyrus therepentous","cyrus grotta"}},{q="Varför anfaller inte Cyrus äventyrare direkt?",a="Han säger öppet att han överväger att äta upp inkräktare, men Cyrus vill hellre se om dödliga kan vara till nytta för honom. Han skonar dem som visar sig användbara genom att låta dem möta dödliga prövningar och undersåtar.",al={"varför är cyrus vänlig","varför dödar inte cyrus mig","prata med cyrus"}}},fp="18,283,26.477.0,26.201.0,38.105.0,46.191.0"}
P.entries["npc:dalar-dawnweaver"] = {n="Dalar Dawnweaver",s="Dalar Dawnweaver är en före detta ärkemagiker från Dalaran som nu tjänar de Förfallna vid The Sepulcher i Silverpine Forest. Han dödades när gisslet förstörde magikernas stad och befriades senare från Lich Kings kontroll. Nu använder han sitt magiska intellekt för att analysera hoten i trakten. Från gravens skuggor leder han arbetet med att förstå Dalarans kvardröjande närvaro och hejda Archmage Arugals vansinne.",h="Dalar Dawnweaver är en före detta ärkemagiker från Dalaran som nu tjänar de Förfallna vid The Sepulcher i...",kw={"ärkemagiker","arugal","dalar","dalaran","dawnweaver","de förfallna","kirin tor","the sepulcher","silverpine"},ang={["class:Mage"]="Förfallna magiker finner i Dalar en mörk spegelbild av Dalarans forna storhet. Han visar hur utbildningen i Kirin Tor kan bli ett vapen i Dark Ladys tjänst.",["faction:Horde"]="Dalar är stationerad vid The Sepulcher och säkrar Hordens västra gräns genom att samordna angrepp mot worgen från Shadowfang Keep och fientliga enklaver från Kirin Tor.",["race:Undead"]="Dalar visar hur de Förfallna har återtagit makten över sina egna liv. Han vänder kunskapen från sitt liv mot kvarlevorna av Dalaran och mot avfälliga magiker som hotar deras självbestämmande."},sec={{t="En fallen ärkemagiker",b="I livet hade Dalar Dawnweaver en hög ställning bland Kirin Tor och vandrade i Violet Citadels salar när Dalaran stod på höjden av sin magiska förmåga. Hans liv som dödlig tog slut när gisslet plundrade staden för att bereda väg för Archimondes inkallande. Dalar återuppväcktes som en viljelös träl under Lich King, men bröt sig fri tillsammans med Lady Sylvanas Windrunner när gisslets grepp försvagades. Nu är han stationerad vid The Sepulcher och använder sin skarpa ärkemagikerintellekt helt för att skydda de Förfallnas rike."},{t="Blicken mot Ambermill och Shadowfang",b="Silverpine Forest är fångat mellan flera faror, och Dalar tjänar som The Sepulchers magiska strateg. I söder håller trollkarlar från Dalaran till i Ambermill och lägger sig i sådant som Dalar vill avslöja och stoppa. Ännu närmare tornar Shadowfang Keep upp sig, med de vilda worgen som släppts lös i skogarna. Dalar känner sin tidigare kollega Archmage Arugal väl och samordnar noggrant angrepp för att oskadliggöra Arugals bestialiska skapelser innan de översvämmar trakten."}},faq={{q="Vem är Dalar Dawnweaver?",a="Dalar Dawnweaver är en Förfallen magiker som finns vid The Sepulcher i Silverpine Forest. I livet var han ärkemagiker i Kirin Tor i Dalaran. Efter att ha dött under Tredje kriget och återuppväckts av gisslet bröt han sig fri från Lich Kings kontroll och började tjäna Dark Lady.",al={"vem är dalar","dalar dawnweaver bakgrund","dalars bakgrund"}},{q="Vad hände med honom under Tredje kriget?",a="Dalar befann sig i Dalaran när Arthas Menethil och gisslet invaderade staden för att återta Book of Medivh. Han dödades under angreppet medan Kel'Thuzad kallade Archimonde till Azeroth. Dalar återuppväcktes då som en odöd tjänare åt gisslet, tills Sylvanas befriade honom.",al={"hur dog dalar","dalars död","dalar och tredje kriget"}},{q="Varför är Dalar stationerad vid The Sepulcher?",a="Han tjänar som de Förfallnas lokala auktoritet i magiska frågor i Silverpine Forest. Hans ingående kunskap om både Kirin Tors styrkor i Ambermill och hans tidigare jämlike Archmage Arugal gör honom särskilt lämpad att bemöta dessa hot.",al={"varför är dalar vid the sepulcher","dalars roll i silverpine"}},{q="Vilken koppling har Dalar till Archmage Arugal?",a="Båda var magiker i Kirin Tor i Dalaran innan stadens fall. Dalar inser hur tragiska och farliga Arugals inkallningsexperiment i Shadowfang Keep har blivit. Han ger äventyrare i uppdrag att samla reliker från Arugal's Folly och kräver till sist att den galne magikern dödas.",al={"dalar och arugal","kände dalar arugal"}},{q="Vad vill Dalar med Dalarans kvarlevor?",a="Dalar håller ett vakande öga på sitt forna hemland och de överlevande styrkorna från Kirin Tor som är stationerade i Ambermill. Han skickar agenter för att fånga upp deras meddelanden och analysera deras avsikter, så att de inte kan hota de Förfallna i Silverpine.",al={"dalar och dalaran","dalar och ambermill"}},{q="Är Dalar allierad med Kirin Tor?",a="Nej. Han var en gång ärkemagiker bland dem, men nu är han lojal mot de Förfallna och Horden. Han bekämpar aktivt de överlevande styrkorna från Kirin Tor som verkar i Silverpine Forest.",al={"tillhör dalar kirin tor","är dalar lojal mot dalaran"}}},fp="16,312,17.487.0,32.417.0,24.262.0,42.239.0,40.206.0,46.294.0,45.208.0,36.183.0"}
P.entries["npc:daphne-stilwell"] = {n="Daphne Stilwell",s="På Westfalls klippor sköter Daphne Stilwell en fruktodling ovanför Longshore. Hon och hennes make Jordan flydde från norr och hjälper nu Ljusets kyrka samtidigt som de skyddar sitt hem mot närliggande laglösa.",h="På Westfalls klippor sköter Daphne Stilwell en fruktodling ovanför Longshore.",kw={"daphne stilwell","defias brotherhood","jordan stilwell","longshore","fruktodling","pyrewood village","shadowfang keep","tome of valor","westfall"},ang={["class:Paladin"]="Som paladin visar du din hängivenhet till att skydda de oskyldiga genom att försvara Daphne Stilwell mot Defias-rövare under prövningarna i Tome of Valor.",["faction:Alliance"]="Som medlem av Alliansen delar du Stilwells börda. De är flyktingar från norr som fortfarande tjänar Alliansen och Ljusets kyrka trots farorna i Westfall."},sec={{t="Ett liv på klipporna",b="Väster om Moonbrook och utgången från The Deadmines sköter Daphne Stilwell en gård med äppelodling på klipporna. Från Longshore nedanför eller från gryfonrutterna söderut mot Stranglethorn Vale ovanför ser gården fridfull ut. Men livet där är inte tryggt. Banditer och asätare strövar omkring i närheten medan Daphne arbetar bland träden och vakar över sitt avskilda land."},{t="Flykt från norr",b="Innan Daphne och hennes make Jordan kom till Westfall bodde de i Lordaeron nära Pyrewood Village, där de arbetade i det som nu är Shadowfang Keep. Mörker och katastrof drev dem söderut tillsammans med tusentals andra mänskliga flyktingar. Nära Stormwind förde Jordans omtalade skicklighet som hantverkare och Daphnes trygga närvaro dem nära Ljusets kyrka. De stöder kyrkan och förser Silver Hand-paladiner med heliga vapen."},{t="Försvar av gården",b="Daphne Stilwell hotas av Defias Brotherhood nära The Deadmines. Jordan reser omkring eller arbetar med heliga vapen utanför huvudstaden och lämnar henne ofta ensam att sköta deras hem vid kusten. När rövare plundrade gården för att hämnas eller stjäla tog Daphne till vapen sida vid sida med blivande paladiner som katedralen skickat dit. Hon visade sig vara hårdför och skicklig i strid."}},faq={{q="Vem är Daphne Stilwell?",a="Daphne Stilwell sköter en avskild bondgård ovanför Westfalls Longshore. Hon är gift med den berömde smeden Jordan Stilwell, och tillsammans flydde de från de ödelagda nordliga kungadömena.",al={"vem är daphne","information om daphne stilwell","stilwells hustru"}},{q="Varifrån kom Daphne?",a="Daphne bodde i norr nära Pyrewood Village och arbetade i det som nu är Shadowfang Keep. Katastrofen drev henne och Jordan söderut, till områden under Stormwinds inflytande.",al={"daphnes ursprung","var kommer daphne ifrån","är daphne gilnean"}},{q="Varför angriper Defias Brotherhood hennes gård?",a="Daphnes gård blickar ut över Westfalls sydliga vatten från klipporna ovanför utgångstunnlarna från The Deadmines. Närheten till Defias fäste gör den till ett mål för laglösa som söker förråd eller vill röja undan dem som lägger sig i.",al={"varför angriper defias daphne","defias angriper gård","banditer på stilwells gård"}},{q="Vilken koppling har Daphne till paladiner?",a="Jordan hjälper Ljusets kyrka genom att smida helgade vapen. Under sina prövningar i Tome of Valor skickas Silver Hand-paladiner till Westfall för att skydda Daphne mot banditer.",al={"paladinuppdrag daphne","tome of valor daphne","varför besöker paladiner daphne"}},{q="Kan Daphne försvara sig?",a="Ja. När Defias angriper hennes fruktodling tar Daphne till vapen och slåss sida vid sida med paladinerna som försvarar gården.",al={"slåss daphne","är daphne en krigare"}},{q="Hur hittar man till hennes bondgård?",a="Daphnes gård ligger på klipptopparna i sydvästra Westfall, sydväst om Moonbrook nära den hemliga vikens utgång från The Deadmines, med utsikt över Longshore.",al={"var ligger daphnes gård","hur hittar man till stilwells gård","daphne stilwells plats"}}},fx={fe5dc862={q="På vems sida står Daphne Stilwell?",a="Daphne Stilwell står på Alliance sida och är djupt lojal mot Church of the Holy Light. Tillsammans med sin make Jordan har hon länge hjälpt Stormwinds paladiner genom att erbjuda skydd och stöd åt unga ljusets försvarare som söker upp deras avskilda gård.",al={"daphne stilwells fraktion","daphne stilwell och alliance","vem tjänar daphne stilwell"}},["5fa85e8c"]={q="Vad vill Daphne Stilwell?",a="Daphne vill helst bara sköta sin äppelodling och leva i stilla ro tillsammans med sin make Jordan. Men Defias Brotherhood strövar omkring på klipporna i Westfall och hotar hennes hem, så hon förlitar sig på besökande paladiner för att hålla banditerna borta.",al={"vad behöver daphne stilwell","daphne stilwells mål","daphne stilwells motiv"}},["57f727ad"]={q="Varför är Daphne Stilwell här?",a="Daphne slog sig ner på den här avskilda höjden med utsikt över Longshore efter att hon och hennes make flytt från Shadowfang Keep i Silverpine Forest. När mörker och vansinne tog över deras nordliga hem reste de söderut till kungariket Stormwind för att skapa ett stilla liv som bönder, långt från Scourge.",al={"varför är daphne i westfall","varför är daphne stilwell på den här gården","varför lämnade daphne shadowfang"}}},fp="15,208,20.344.0,21.442.0,18.356.1,23.186.0,27.166.0,51.220.1,40.185.0,26.121.0,31.150.0"}
P.entries["npc:darcy-parker"] = {n="Darcy",s="Darcy är servitris på Lakeshire Inn, där hon serverar drycker och varm mat. Trots de ständiga hoten mot Redridge håller hon humöret uppe genom att ta hand om de lokala försvararna, särskilt Guard Parker.",h="Darcy är servitris på Lakeshire Inn, där hon serverar drycker och varm mat.",kw={"darcy","guard parker","lakeshire","lakeshire inn","martie jainrose","redridge","servitris"},ang={["faction:Alliance"]="Darcy står för Lakeshires tåliga vardagsfolk. Hon håller humöret uppe och magarna mätta medan staden väntar på hjälp från Stormwind."},sec={{t="Ett vänligt ansikte på värdshuset",b="Bakom den livliga disken på Lakeshire Inn arbetar Darcy dag och natt för att hålla stadens utmattade milis mätt och belåten. Lakeshire är ständigt pressat av gnoller och Blackrock-orcher, vilket gör värdshuset till en av få varma platser som finns kvar i samhället. Darcy bryr sig särskilt om vakterna som posterats runt staden och ber ofta resande äventyrare att lämna varm mat och uträtta vänliga ärenden åt dem som är stationerade längs gränsen."},{t="Romantik vid vaktposten",b="Darcy visar särskilt sin värme för Guard Parker, som patrullerar vägarna nära Three Corners. Övertygad om att han arbetar för hårt på tom mage skickar hon regelbundet iväg resande med lunch så att han orkar hålla igång. Hennes känslor har inte gått obemärkta förbi: Darcy håller ett vaksamt öga på Martie Jainrose, som hon ser som en svartsjuk rival om Parkers gunst. Försvaret av Lakeshire blir därmed kuliss för en uppriktig småstadsromans."}},faq={{q="Vem är Darcy?",a="Darcy är en mänsklig servitris som arbetar på Lakeshire Inn i Redridge Mountains. Hon lagar mat åt stadens försvarare och ber regelbundet resande att hjälpa till att leverera måltider till vakter i tjänst.",al={"vem är darcy","darcy parker npc","servitris i lakeshire"}},{q="Vilken relation har Darcy till Guard Parker?",a="Darcy hyser starka känslor för Guard Parker. Hon anstränger sig för att packa färsk lunch åt honom och skickar den med resande, så att han får mat medan han patrullerar vägarna nära Three Corners.",al={"darcy och guard parker","guard parker darcy","vem gillar darcy"}},{q="Varför misstänker Darcy Martie Jainrose?",a="Darcy tror att Martie Jainrose är svartsjuk och ser henne som en romantisk rival om Guard Parkers uppmärksamhet. Det tillför en personlig rivalitet till vardagslivet i staden.",al={"darcy och martie","martie jainrose","darcy rival"}},{q="Var hittar man Darcy?",a="Hon finns på Lakeshire Inn, där hon serverar gäster. Värdshuset ligger mitt i Lakeshire, vid Lake Everstills norra strand i Redridge.",al={"darcy plats","var är darcy","hitta darcy"}}},fx={e14c1e0c={q="På vems sida står Darcy?",a="Darcy står helt på Grand Alliances och lokalbefolkningens sida i Redridge Mountains. Som servitris på Lakeshire Inn ägnar hon vardagen åt att ta hand om stadens försvarare, laga mat och ge gästfrihet åt stadsbor och besökande äventyrare från Alliance.",al={"darcys fraktion","tillhör darcy alliance","vem tjänar darcy"}},b7996d79={q="Vad vill Darcy?",a="Darcy vill hålla de lokala vakterna mätta och omhändertagna, men hon hoppas också på romantik. Hon är särskilt förtjust i Guard Parker, som är stationerad ute på vägen, och anstränger sig för att laga och skicka honom varma luncher medan hon oroar sig för tänkbara rivaler som Martie Jainrose.",al={"vad behöver darcy","darcys mål","darcys uppdragsmotiv"}},["4cbadea5"]={q="Varför är Darcy i Lakeshire?",a="Darcy bor och arbetar i Lakeshire som servitris på det lokala värdshuset. Staden utsätts ständigt för angrepp från orcher och gnoller, men någon måste hålla värdshuset igång och servera varm mat åt trötta soldater och resenärer som anländer över den stora bron.",al={"varför är darcy här","darcys roll i lakeshire","darcy på lakeshire inn"}}},fp="5,146,26.342.0,25.341.0,13.185.0,47.142.0,43.102.0,25.122.0"}
P.entries["npc:dark-cleric-beryl"] = {n="Dark Cleric Beryl",s="Dark Cleric Beryl är en prästtränare för Forsaken som håller till på Gallows' End Tavern i Brill. Han vägleder nyväckta odöda präster när de lär sig att bruka skuggmagi och anpassa sig till sin nya, oheliga tillvaro under Dark Lady.",h="Dark Cleric Beryl är en prästtränare för Forsaken som håller till på Gallows' End Tavern i Brill.",kw={"beryl","brill","dark cleric beryl","präst bland forsaken","gallows' end tavern","prästtränare","tirisfal glades"},ang={["class:Priest"]="För präster bland Forsaken som ger sig ut i Tirisfal Glades är Beryl en oumbärlig mentor i Brill. Han vägleder dem i hur de kan manipulera skuggmagi och överleva den hårda övergången till ohelig kraft.",["race:Undead"]="Beryl står för Forsakens anpassning till sitt förbannade tillstånd. De byter Lordaerons forna tros blinda hängivenhet mot en praktisk motståndskraft präglad av skuggorna."},sec={{t="En vägvisare i skuggorna",b="Dark Cleric Beryl bor på övervåningen i Gallows' End Tavern i Brill och tjänar Forsaken genom att handleda blivande präster. Beryl lär ut att en präst bland Forsaken får sin kraft från mörker och skuggor, men att man också måste känna till ljuset innan man kan bemästra mörkret. Han hjälper nyuppståndna utövare att rikta in sig på skuggor och mörka konster, och vägleder dem genom de första prövningarna, som att skapa sina Garments of Darkness och visa sitt engagemang för den nya vägen."}},faq={{q="Vem är Dark Cleric Beryl?",a="Dark Cleric Beryl är en prästtränare för Forsaken som håller till på övervåningen i Gallows' End Tavern i Brill. Han lär nyuppståndna odöda präster att utveckla sin besvärjelsekonst och omfamna skuggorna.",al={"beryls roll","vem är beryl","cleric beryl bakgrund"}},{q="Var hittar jag Dark Cleric Beryl?",a="Han håller till i Tirisfal Glades, i staden Brill. Du hittar honom på övervåningen i Gallows' End Tavern.",al={"beryls plats","var finns beryl","hitta dark cleric beryl"}},{q="Varför använder präster bland Forsaken titeln Dark Cleric?",a="Präster bland Forsaken som överger den Heliga Ljusets traditionella dogmer eller balanserar dem med mörkare läror antar titeln Dark Cleric. Deras orden lär ut att Forsaken formades i korruption och att mörkret är deras hem, men att en präst måste lära sig att använda både ljus och mörker med omdöme.",al={"vad är en dark cleric","dark clerics bland forsaken","varför dark cleric"}},{q="Vilka uppdrag erbjuder Beryl?",a="Beryl medverkar i de tidiga träningsuppdragen för präster bland Forsaken, däribland 'In Favor of Darkness' och 'Garments of Darkness'. De lär unga akoliter hur de kan hjälpa sina allierade och klä sig i dräkter som passar skuggorna.",al={"beryls uppdrag","dark cleric beryls uppdrag"}}},fx={["4c1b78a6"]={q="På vems sida står Dark Cleric Beryl?",a="Beryl är lojal mot Forsaken och den mörka damen, drottning Sylvanas Windrunner. Från Brill tjänar han Undercitys och Hordes intressen genom att undervisa nyväckta odöda som hör prästerskapets kallelse och hjälpa dem att bemästra skuggan och disciplinen i sitt folks tjänst.",al={"beryls fraktion","vem tjänar beryl","beryls lojalitet"}},fd6d5379={q="Varför är Dark Cleric Beryl i Brill?",a="Beryl är stationerad på Gallows' End Tavern i Brill för att vägleda unga Forsaken-präster som kommer från Deathknell. När nybörjarna beger sig ut i Tirisfal Glades ger han dem utbildningen och kläderna de behöver för att överleva Scourge, Scarlet Crusade och andra faror som hotar Lordaeron.",al={"varför är beryl i brill","varför är beryl här","beryl på gallows' end"}},["6191615e"]={q="Vad vill Dark Cleric Beryl?",a="Beryl vill se till att Forsakens blivande präster är rätt utrustade och disciplinerade i sitt hantverk. Han kräver att utövarna förstår sin mörka kallelse, prövar om de är redo och förser dem med kläder lämpade för att kanalisera skuggans krafter och en okuvlig vilja.",al={"vad är beryls mål","vad vill beryl","beryls motiv"}}},fp="17,215,22.403.0,25.167.0,35.90.0,50.305.0,29.189.0"}
P.entries["npc:dark-iron-ambassador"] = {n="Dark Iron Ambassador",s="Dark Iron Ambassador är ett sändebud från Dark Iron-klanen som finns djupt inne i Gnomeregan. Hans närvaro väcker frågor om klanens intresse för den förstörda gnomhuvudstaden.",h="Dark Iron Ambassador är ett sändebud från Dark Iron-klanen som finns djupt inne i Gnomeregan.",kw={"sammansvärjning","dark iron ambassador","dark iron-klanen","gnomeregan","superrigg","thaurissan","thermaplugg"},ang={["faction:Alliance"]="Alliansens utredare har skäl att undersöka Dark Irons närvaro i Gnomeregan.",["race:Dwarf"]="Närvaron av en dvärg från Dark Iron i den förstörda gnomstaden väcker uppmärksamhet hos Ironforge-allierade.",["race:Gnome"]="Ett sändebud från Dark Iron i Gnomeregan väcker oroande frågor hos gnomernas utredare."},sec={{t="Ett skuggfullt sändebud",b="Dark Iron Ambassador finns bland farorna i det bestrålade Gnomeregan. Han företräder Dark Iron-klanen, men uppdragets syfte förklaras inte."},{t="Sammansvärjningar i djupet",b="Utredare och gobliner misstänker att Dark Iron varit inblandade i Gnomeregans problem och dess mystiska superrigg. Det här förblir teorier; sändebudets närvaro fastslår inte vem som orsakade stadens fall eller villkoren för något avtal."}},faq={{q="Vem är Dark Iron Ambassador?",a="Han är ett sändebud från Dark Iron som hittas i Gnomeregan. Hans exakta diplomatiska uppdrag är okänt.",al={"vem är den här dvärgen","dark iron ambassadors identitet","vad är dark iron ambassador"}},{q="Varför befinner sig en dvärg från Dark Iron i Gnomeregan?",a="Hans syfte är inte fastslaget. Hans närvaro visar att Dark Iron-klanen är intresserad av Gnomeregan.",al={"varför är dark iron i gnomeregan","vad gör han här","syftet med dark iron-dvärgen"}},{q="Hjälpte Dark Iron till att orsaka Gnomeregans fall?",a="Det är inte fastslaget. Utredare har uttryckt misstankar, men deras teorier bevisar inte vem som orsakade katastrofen.",al={"orsakade dark iron trogginvasionen","dark iron-sammansvärjning","hjälpte thaurissan thermaplugg"}},{q="Varifrån kommer sändebudet?",a="Han tillhör Dark Iron-klanen, vars härskare är Emperor Dagran Thaurissan.",al={"varifrån kommer sändebudet","vem skickade honom","vem arbetar han för"}},{q="Är han allierad med Mekgineer Thermaplugg?",a="En allians misstänks, men hans närvaro ensam bekräftar inte något avtal.",al={"thermaplugg dark iron-allierad","är han med thermaplugg","arbetar med thermaplugg"}},{q="Var kan Dark Iron Ambassador hittas?",a="Han är ett svårfunnet, sällsynt möte som vandrar genom de förorenade tekniksektorerna och verkstadskorridorerna i Gnomeregans grotta.",al={"sändebudets plats","var dyker han upp","dark iron ambassador i gnomeregan"}}},fx={["694fcc25"]={q="På vems sida står Dark Iron Ambassador?",a="Han tillhör Dark Iron-klanen.",al={"dark iron ambassadors fraktion","vem tjänar ambassadören","dark iron ambassadors lojaliteter"}},e7a948f2={q="Vad vill Dark Iron Ambassador?",a="Hans exakta uppdrag och mål i Gnomeregan är okända.",al={"dark iron ambassadors mål","varför kom dark iron till gnomeregan","dark iron ambassadors motiv"}},["388c8a07"]={q="Vilka band har Dark Iron Ambassador?",a="Han företräder Dark Iron-klanen. Det har misstänkts att han har band till Mekgineer Thermaplugg, men arten av dessa band är inte bekräftad.",al={"dark iron ambassadors kontakter","vem rapporterar ambassadören till","dark iron ambassadors kejsare"}}},fp="20,165,15.120.0,24.273.1,32.113.0,43.92.0,53.108.0,36.69.0,40.71.0,44.129.0"}
P.entries["npc:darkmaster-gandling"] = {n="Darkmaster Gandling",s="Darkmaster Gandling är Scholomances mänsklige rektor och leder undervisningen och träningen av nekromantiker åt The Cult of the Damned. Från djupet av den förstörda borgen i Caer Darrow tjänar han Scourge genom att iscensätta makabra magiska experiment på både levande och döda.",h="Darkmaster Gandling är Scholomances mänsklige rektor och leder undervisningen och träningen av nekromantiker...",kw={"caer darrow","cult of the damned","darkmaster gandling","gandling","rektor","nekromantiker","scholomance"},ang={["class:Mage"]="Gandling är den yttersta förvanskningen av Dalarans lärdomstraditioner och har vridit akademisk noggrannhet till en fasansfull fabrik för odödlighet.",["race:Undead"]="För Forsaken är Gandling en hatad övervakare av Scourges indoktrinering som binder fria själar i evigt slaveri under Caer Darrow."},sec={{t="Rektorns domän",b="I de mörka salarna under Caer Darrow styr Darkmaster Gandling Scholomance, Scourges främsta akademi för blivande nekromantiker. Gandling är en levande människa som tjänar The Cult of the Damned och arbetade tillsammans med lich Ras Frostwhisper för att begå grymheter mot oräkneliga oskyldiga fångar från de kringliggande trakterna. Eleverna som kommer in i hans klassrum får lära sig att brygga pest, återuppväcka döda och forma kött."},{t="Relikvariets mästare",b="Djupt inne i rektorns arbetsrum befaller Gandling över de mörka relikerna och andarna som är fångna i den uråldriga skolan. Han använder förödande arkansk magi och skuggmagi tillsammans med förbjuden nekromantik. Han förbannar inkräktare och slungar dem genom skuggportaler till de förseglade kamrarna runt sitt arbetsrum, där de måste kämpa ensamma mot de återuppståndna döda medan Gandling skyddar sig från skada."}},faq={{q="Vem är Darkmaster Gandling?",a="Darkmaster Gandling är en mänsklig nekromantiker som tillhör The Cult of the Damned. Han är rektor för Scholomance, där han driver den mörka skolan och tränar nya nekromantiker att tjäna Lich King.",al={"vem är gandling","darkmaster gandling bakgrund","scholomance-boss"}},{q="Är Gandling odöd eller en levande människa?",a="Trots sin mästerliga kunskap om dödsmagi och sin trohet till Scourge är Gandling fortfarande en levande, dödlig människa. Han leder dödliga akolyter och kultister i Scholomance och tjänar Scourge frivilligt.",al={"är gandling odöd","lever gandling","gandlings folkslag"}},{q="Hur hänger han ihop med Ras Frostwhisper?",a="Ras Frostwhisper var G—andlings lärare. Tillsammans ledde den mänsklige rektorn och den mäktige lichen den mörka undervisningen i Scholomance och övervakade de fasor som drabbade oskyldiga själar, som familjen Sarkhoff, i Caer Darrow.",al={"frostwhisper gandling","ras frostwhisper lärare"}},{q="Var hittar man Darkmaster Gandling?",a="Gandling håller till i rektorns arbetsrum längst ner i Scholomance. Dit kommer man genom katakomberna under Caer Darrow i Darrowmere Lake.",al={"gandlings plats","var finns gandling","hur hittar man gandling"}}},fp="19,305,23.441.0,23.418.0,27.199.0,40.194.0,43.240.0,35.150.0"}
P.entries["npc:darn-talongrip"] = {n="Darn Talongrip",s="Darn Talongrip är en orcisk spejare stationerad vid gränsen till Stonetalon Mountains, nära Malaka'jin. Han håller uppsikt över hoten i klippområdena och hjälper till att samordna Hordens kommunikation mellan utposter och regionala befälhavare.",h="Darn Talongrip är en orcisk spejare stationerad vid gränsen till Stonetalon Mountains, nära Malaka'jin.",kw={"darn talongrip","kadrak","malakajin","orcisk spejare","stonetalon"},ang={["faction:Horde"]="Darn Talongrip håller tidig uppsikt över stigen upp mot Stonetalon och är en värdefull kontakt för Hordens äventyrare som nyligen kommit från The Barrens.",["race:Orc"]="Liksom många orciska spejare trivs Darn med gränslandets hårda förhållanden och håller vakt bland vassa klippor och fientliga vilda djur."},sec={{t="Gränsspanare i Stonetalon",b="Darn Talongrip bevakar de karga stigarna som leder in i Stonetalon från södra The Barrens. Han är stationerad i bosättningen Malaka'jin och visar rekryter vägen till Hordens nya front i Ashenvale. Hans post är en tidig kontaktpunkt för resenärer som slingrar sig upp mot de omstridda bergstopparna."},{t="Befälets ögon",b="Från sin post i Malaka'jin ser Darn till att meddelanden och rapporter från fronten når viktiga befälhavare som Kadrak, i vakttornet i norra The Barrens. Utposterna i bergen verkar under ständig press, så Darns roll som vaktpost och kurir är avgörande för att hålla Hordens förtrupp underrättad."}},faq={{q="Vem är Darn Talongrip?",a="Darn Talongrip är en orcisk spejare stationerad i Malaka'jin, i den södra delen av Stonetalon Mountains.",al={"vem är darn talongrip","darn talongrips identitet","vem är den här orcen"}},{q="Var kan Darn Talongrip hittas?",a="Han finns i trollbosättningen Malaka'jin i Stonetalon Mountains.",al={"darn talongrips plats","var finns darn talongrip","darn talongrips koordinater"}},{q="Vilken roll har han i Stonetalon?",a="Darn visar nya rekryter vägen till Kadrak i norra The Barrens, där de kan hjälpa till att försvara Hordens utposter i Ashenvale.",al={"vad gör darn talongrip","darn talongrips uppgift"}},{q="Vem är Kadrak, och varför skickar Darn resenärer till honom?",a="Kadrak är en befälhavare i Horden, stationerad i vakttornet i norra The Barrens, där han leder Hordens fälttåg i Ashenvale. Darn visar nya rekryter vägen till honom så att de kan hjälpa till att försvara Hordens nya front i Ashenvale.",al={"vem är kadrak","rapportera till kadrak"}}},fx={b53227de={q="På vems sida står Darn Talongrip?",a="Darn Talongrip står stadigt på Hordens sida. Han verkar från Stonetalon Mountains nära Malaka'jin och arbetar tillsammans med andra orcher för att säkra de karga stigarna och stärka Hordens grepp om Kalimdor.",al={"darn talongrips fraktion","är darn talongrip med horden","vem tjänar darn talongrip"}},["3e5a66b7"]={q="Vad vill Darn Talongrip?",a="Darn Talongrip vill skydda Hordens närvaro längs bergspasset och visa arbetsföra äventyrare var deras styrka behövs bäst. Särskilt skickar han resande för att hjälpa Kadrak med brådskande Hordeuppdrag i närheten.",al={"vad söker darn talongrip","darn talongrips mål","vad vill darn"}},d56f5cfb={q="Varför är Darn Talongrip här i Stonetalon?",a="Darn Talongrip är stationerad kring Malaka'jin och Stonetalon Mountains omgivande pass. Han upprätthåller Hordens närvaro vid gränsen, håller uppsikt över bergsvägarna och ser till att rapporter snabbt når fram mellan utposternas vaktposter.",al={"varför är darn talongrip i stonetalon","varför är darn här"}}},fp="14,170,28.244.0,20.273.0,22.89.0,34.95.0,31.105.0,55.183.0"}
P.entries["npc:darsok-swiftdagger"] = {n="Darsok Swiftdagger",s="Vid The Crossroads håller Darsok Swiftdagger uppsikt över de norra stigarna efter hot. Orkspejaren leder Hordens krigare mot Witchwing-harpior i The Dry Hills, vars räder hotar resenärer och bosättningar. Han är också gammal vän med Witch Doctor Jin'Zil i Malaka'jin.",h="Vid The Crossroads håller Darsok Swiftdagger uppsikt över de norra stigarna efter hot.",kw={"the barrens","bloodfeather","the crossroads","darsok","harpy","jin'zil","serena","swiftdagger","thork","witchwing"},ang={["class:Rogue"]="Som lönnmördare känner du igen Darsoks förkärlek för precisa, dödliga anfall mot fiendeledare, med målet att ta deras huvuden.",["faction:Horde"]="Som resenär för Horden kan du förlita dig på Darsoks tidiga, taktiska uppdrag för att säkra handelsvägarna vid vägskälet mot attacker från ovan.",["race:Orc"]="Som ork kan du se Darsoks fokuserade, krigiska sätt att säkra Kalimdors farliga gränsland."},sec={{t="En väktare vid The Crossroads",b="Darsok Swiftdagger håller uppsikt över den norra buskmarken från The Crossroads. Vägarna som förbinder Durotar, Mulgore och The Barrens norra utkanter hotas av plundrare och kentaurer, liksom organiserade jägare från skyn. Darsoks vrede riktas mot Witchwing-harpiorna. Deras nästen ligger i The Dry Hills, nordväst om The Forgotten Pools, där de hotar karavaner på väg norrut."},{t="Kriget mot Witchwing",b="Darsok leder anfall in i Witchwing-territorium, med början hos Harpy Raiders. Sedan skickar han erfarna krigare efter harpyornas löjtnanter och till sist deras matriark, Serena Bloodfeather. Genom att slå ut deras befäl stegvis försöker han skingra flocken över klipporna."},{t="Förbindelser i busklandet",b="Långt nordväst om The Barrens har Darsok en gammal vän: Witch Doctor Jin'Zil, en troll som bor i Malaka'jin i Stonetalon Mountains, landet som harpiorna kommer från. Darsok skickar ett brev till Jin'Zil med nyheter om kampanjen mot harpiorna. De två vännerna har inte haft kontakt på många år."}},faq={{q="Var finns Darsok Swiftdagger?",a="Darsok Swiftdagger är stationerad vid The Crossroads, Hordens centrala bosättning i The Barrens. Han varnar resenärer för hoten i norr.",al={"darsoks plats","var finns darsok swiftdagger","hitta darsok","darsok swiftdagger plats"}},{q="Varför jagar Darsok harpyor?",a="Witchwing-harpiorna har nästen i kanjonerna nordväst om The Forgotten Pools och hotar Hordens karavaner, resenärer och spejare längs The Barrens norra stigar.",al={"varför döda harpyor","darsoks agg mot harpyor","witchwing-harpyor i the barrens"}},{q="Vem är Serena Bloodfeather?",a="Serena Bloodfeather leder Witchwing-harpiorna i The Dry Hills. Darsok skickar krigare för att döda henne och slå sönder flockens befäl.",al={"serena bloodfeather","harpyornas ledare i the barrens","witchwings ledare"}},{q="Vilken koppling har Darsok till Witch Doctor Jin'Zil?",a="Witch Doctor Jin'Zil, en troll som bor i Malaka'jin i Stonetalon Mountains, är Darsoks gamla vän. Darsok skickar en resenär till Jin'Zil med ett brev om kampanjen mot harpiorna, hans första livstecken på många år.",al={"jin'zils brev","darsok och jin'zil","kopplingen till witch doctor jin'zil"}},{q="Rapporterar Darsok till Sergra Darkthorn eller Thork?",a="Darsok organiserar sin kampanj mot harpiorna från The Crossroads. Ingen Classic-källa pekar ut Sergra Darkthorn eller Thork som hans direkta överordnade.",al={"darsok och thork","vem rapporterar darsok till","the crossroads ledning"}},{q="Var bygger Witchwing-harpyorna bo?",a="Witchwing-harpiorna har nästen i The Dry Hills, ett område med karga raviner och klippor nordväst om The Forgotten Pools i norra The Barrens.",al={"witchwings plats","harpyor i the dry hills","var hittar man harpyor i the barrens"}}},fx={c43e4047={q="Vem är Darsok Swiftdagger?",a="Darsok Swiftdagger är en orchisk spejare och krigare i Horden, stationerad vid The Crossroads. Han är fast besluten att skydda The Barrens mot lokala hot och har fått ett fruktat rykte, framför allt för sin skoningslösa kamp mot Witchwing-harpiorna som hemsöker trakten.",al={"vem är darsok","vem är darsok swiftdagger","om darsok"}},cbab4453={q="På vems sida står Darsok Swiftdagger?",a="Darsok står stadigt på Hordens sida. Han verkar från The Crossroads, försvarar Kalimdor och hjälper bosättningen genom att oskadliggöra hot mot resande och handelskaravaner.",al={"darsoks fraktion","är darsok med horden","darsoks lojalitet"}},bc228dd6={q="Vad vill Darsok Swiftdagger?",a="Darsok vill utplåna hotet från Witchwing i norra The Barrens. Han värvar dugliga äventyrare för att decimera flockens plundrare, döda deras fältlöjtnanter och till sist dräpa deras grymma matriark, Serena Bloodfeather.",al={"darsoks mål","vad vill darsok","varför jagar darsok harpyor"}},aac9a722={q="Varför är Darsok Swiftdagger här?",a="Darsok är stationerad vid The Crossroads och utgör en viktig förtrupp mot farorna som hotar de norra handelsvägarna. Han är kvar här för att hålla uppsikt över de närbelägna harpiornas aggressivitet och organisera militära insatser för att driva bort dem från Hordens marker.",al={"varför är darsok vid the crossroads","varför är darsok här"}}},fp="18,271,27.375.0,24.292.1,24.287.0,36.145.0,30.153.0,27.132.0,52.215.0,48.135.0,36.129.0"}
P.entries["npc:daryl-the-youngling"] = {n="Daryl the Youngling",s="Daryl the Youngling är en mänsklig jägare som bor på Farstrider Lodge i de sydöstra kullarna i Loch Modan. Han vill visa att han kan skjuta lika bra som erfarna dvärgspårare och utmanar resande äventyrare att vässa sina färdigheter i vildmarken och mäta sig med traktens bestar.",h="Daryl the Youngling är en mänsklig jägare som bor på Farstrider Lodge i de sydöstra kullarna i Loch Modan.",kw={"vildsvinsjakt","daryl","the farstrider lodge","jägare","jägarens skryt","loch modan","youngling"},ang={["class:Hunter"]="Daryl kan allt om spårning, bestars beteende och jakt. Därför blir hans tävlingar ett naturligt prov för kringvandrande jägare som besöker Farstrider Lodge.",["race:Human"]="Att en ung människa lär sig vildmarkens hantverk djupt inne på dvärgarnas område visar den praktiska kamratskap som vuxit fram mellan Ironforge och människorikena."},sec={{t="En människa bland bergsbestigare",b="Farstrider Lodge är främst en fristad för dvärgiska bergsbestigare, spårare och erfarna friluftsmänniskor som vakar över vildmarken i Loch Modan. Daryl sticker ut som en ung människa som försöker vinna sin plats bland dessa erfarna jägare. I stället för att bara skryta söker han sig aktivt till andra resande för att mäta sina jaktinstinkter mot deras och utmanar dem att jaga de tåliga vildsvin och bestar som strövar bland klipporna och längs sjöstranden."}},faq={{q="Vem är Daryl the Youngling?",a="Daryl är en ung mänsklig jägare som är stationerad på Farstrider Lodge i Loch Modan. Omgiven av härdade dvärgiska skyttar sätter han nykomlingar på prov med jakttävlingar för att visa deras skicklighet med bestar och spårning.",al={"vem är daryl","daryls bakgrund","vem är daryl the youngling"}},{q="Var hittar man Daryl?",a="Daryl håller till på Farstrider Lodge, på de skogklädda klipporna med utsikt över sjöns sydöstra stränder i Loch Modan.",al={"daryls plats","var finns daryl the youngling","var hittar man daryl"}},{q="Varför kallas han ”the Youngling”?",a="Jämfört med de erfarna dvärgiska skyttarna och stamgästerna på lodgen, som har patrullerat Khaz Modans karga utmarker i årtionden, är Daryl relativt ung och oprövad. Han arbetar fortfarande på att bygga upp ett bestående rykte som jägare.",al={"varför youngling","daryls smeknamn"}}},fx={e75652fe={q="På vems sida står Daryl the Youngling?",a="Daryl är allierad med Alliansen och har slagit läger bland Loch Modans dvärgskyttar. Han är stationerad vid The Farstrider Lodge och samarbetar med sina bergsbestigare och friluftsmänniskor till kamrater för att säkra traktens vildmark.",al={"daryls fraktion","är daryl med alliansen","vem tjänar daryl"}},a39b90d4={q="Vad vill Daryl the Youngling?",a="Daryl vill gärna bevisa sin skicklighet som bågskytt och friluftsmänniska. Han söker dugliga äventyrare som vill pröva sina färdigheter i spårning och jakt på Loch Modans lokala djurliv. Han älskar jaktens spänning och utmaningar.",al={"vad vill daryl","daryls mål","daryls uppdrag"}},f7496387={q="Varför är Daryl the Youngling vid The Farstrider Lodge?",a="The Farstrider Lodge är en fristad för dalens skickligaste spårare och bestjägare. Daryl tillbringar sin tid här med att vässa sina färdigheter tillsammans med veteraner bland dvärgskyttarna och dra nytta av det rika villebrådet som strövar omkring i Loch Modans kullar.",al={"varför är daryl här","varför är daryl i loch modan","daryl the youngling vid the farstrider lodge"}},d22cfcb5={q="Vilka har Daryl the Youngling band till?",a="Daryl umgås med jägarna och stugvärdarna vid The Farstrider Lodge, bland andra Vyrin Swiftwind. Han delar deras hängivenhet åt jakten och hjälper dem att hantera vilddjuren som stryker omkring nära dvärgarnas utpost.",al={"daryls allierade","daryl vid the farstrider lodge","vilka är daryl med"}}},fp="19,178,26.266.0,27.176.0,25.91.0,33.193.0"}
P.entries["npc:dashel-stonefist"] = {n="Dashel Stonefist",s="I Old Town är Dashel Stonefist känd för sitt häftiga humör och sina hårda nävar. Dvärgen som kallas Fist håller till i Stormwind Citys ruffigare gränder, där farliga kontakter väcker de hemliga utredarnas intresse.",h="I Old Town är Dashel Stonefist känd för sitt häftiga humör och sina hårda nävar.",kw={"slagskämpe","dashel","defias","fist","försvunnen diplomat","old town","stonefist","stormwind"},ang={["class:Rogue"]="För skurkar som rör sig genom Old Towns kriminella nätverk visar Dashel Stonefist hur en infiltratör kan prata för mycket när käken fått sig en smäll. Att anförtro känsliga hemligheter åt råstyrka är ett dåligt vad.",["faction:Alliance"]="Dashel Stonefist står för den stillsamma förruttnelsen i Stormwinds huvudstad. Defias Brotherhoods räckvidd sträcker sig bortom Westfalls gårdar och in i den självstyrande staden.",["race:Dwarf"]="Många Ironforge-dvärgar i Stormwind arbetar som ärade smeder, bergsbestigare eller sändebud. Stonefist visar att en dvärg också kan hemfalla åt gatuhuliganism och förräderi."},sec={{t="En slagskämpe i Old Town",b="I Old Town är Dashel Stonefist känd som Fist efter gatubråken som gett honom namnet. Lokalbor och stadsvakter ser en berusad, stridslysten dvärg som är redo att slåss utanför en krog. Hans plats i stadsdelen gör honom till en knutpunkt i Stormwinds undre värld, där smugglare, ficktjuvar och politiska agitatorer utbyter mynt och rykten utom synhåll från Cathedral Square."},{t="Diplomatens försvinnande",b="En försvunnen diplomat leder kungliga hemliga utredare till Dashel Stonefist. Rykten om förräderi leder dem till dvärgen, en gatukontakt för Defias Brotherhood innanför Stormwinds murar. Han känner till kidnappningen, men vägrar tala tills utredarna slår honom till underkastelse. Det han avslöjar sträcker sig djupare in i kungarikets politik än en enkel kidnappning."}},faq={{q="Vem är Dashel Stonefist?",a="I Stormwind Citys Old Town är Dashel Stonefist en småskalig skurk och informatör i huvudstadens skumma kvarter. Dvärgen som kallas Fist har ett våldsamt rykte och en vana att slåss.",al={"vem är dashel","vem är fist","dashel stonefists bakgrund"}},{q="Var hittar jag Dashel Stonefist?",a="Du hittar Dashel Stonefist stående utomhus i Old Town, bland bakgatorna nära stadens tillhåll för skurkar och krigare.",al={"dashels plats","var finns dashel stonefist","hitta dashel"}},{q="Varför måste utredarna slåss mot honom?",a="Utredarna slåss mot Dashel Stonefist eftersom spåren i sökandet efter den försvunna kungliga diplomaten pekar ut honom som medbrottsling. Han är djupt lojal mot sina skumma uppdragsgivare, respekterar bara våld och avslöjar inte vad han vet förrän han besegrats i ett slagsmål med bara knytnävarna.",al={"varför angripa dashel","kuva dashel stonefist","slåss mot dashel"}},{q="Vad har han för koppling till Defias Brotherhood?",a="Dashel Stonefist är en infiltratör och budbärare för Defias Brotherhood i Stormwind. Han samordnar lokala kontakter och gatutränade slagskämpar för att dölja brödraskapets planer för stadsvakten.",al={"är dashel med i defias","dashel stonefist och defias","defias i stormwind"}},{q="Vem är den försvunna diplomaten som Dashel har koppling till?",a="Kungliga agenter följer spåren efter en icke namngiven diplomat som försvann på väg till Theramore.",al={"vem är den försvunna diplomaten","uppdrag om den försvunna diplomaten","kung varian försvunnen"}},{q="Är Dashel släkt med några andra kända dvärgar?",a="Inga släktingar till Dashel Stonefist finns registrerade. Hans kriminella band i Stormwind skiljer honom från det ansedda dvärgsamhället.",al={"släkting till telda stonefist","dashel stonefists familj","stonefist-familjen"}}},fx={["06e53778"]={q="På vems sida står Dashel Stonefist?",a="Dashel Stonefist balanserar på en farlig linje mellan Old Towns kriminella undre värld och öppet förräderi. Han låtsas vara ännu en råbarkad slagskämpe i stadens gränder, men hans hemliga lojalitet ligger hos Defias Brotherhood. Han förmedlar information och hjälper dem samordna sin omstörtande verksamhet mitt framför näsan på Stormwind Citys vakter.",al={"dashel stonefists fraktion","vem arbetar dashel för","är dashel med defias"}},["388c2391"]={q="Varför är Dashel Stonefist i Old Town?",a="Dashel håller sig kvar i Old Town eftersom de trånga, skuggiga gatorna ger perfekt täckmantel för olagliga affärer. Långt från Cathedral Squares eller det kungliga hovets välpolerade övervakning kan han hålla kontakt med skumma konspiratörer, arrangera affärer i gränderna och hålla koll på stadens rörelser utan att dra till sig myndigheternas uppmärksamhet i förtid.",al={"varför är dashel i stormwind","varför befinner sig dashel stonefist här","vad gör dashel i old town"}},["329088a4"]={q="Varför kallas Dashel Stonefist för Fist?",a="Folk och ligister i hela Old Town känner Dashel helt enkelt som ”Fist”, ett välförtjänt smeknamn som kommer av hans ökända humör och vilja att lösa varje dispyt med rått våld. Han har ett fruktat rykte för brutala slagsmål i gränderna, så de flesta invånare och ficktjuvar tänker sig för innan de sätter sig upp mot honom eller lägger sig i hans förehavanden.",al={"varför kallas dashel fist","dashel stonefists smeknamn","dashels rykte"}}},fp="16,209,21.350.0,28.373.1,24.188.0,34.114.0,39.225.1,49.201.1,48.88.2,45.123.0"}
P.entries["npc:david-trias"] = {n="David Trias",s="David Trias är Forsakens instruktör i tjuvkonst och är stationerad i Deathknell. Han lär nyväckta odöda konsten att smyga, agera i hemlighet och hantera klingor, för att hjälpa drottning Sylvanas och Forsaken.",h="David Trias är Forsakens instruktör i tjuvkonst och är stationerad i Deathknell.",kw={"david trias","deathknell","elling trias","encrypted scroll","forsaken","tjuvinstruktör","tirisfal glades"},ang={["class:Rogue"]="För Forsaken-tjuvar är David Trias din allra första mentor. Han hjälper dig att tyda hemliga skriftrullar och lär dig att förvandla odödhetens kalla precision till dödlig klingkonst.",["race:Undead"]="David Trias förkroppsligar Forsakens bistra verklighet: före detta människor från Lordaeron vars tidigare liv och släktband klippts av pesten och som nu i stället tjänar drottning Sylvanas."},sec={{t="En vägvisare i skuggorna",b="Bland gravstenarna och ruinerna i Deathknell har David Trias i uppgift att hitta och träna nyuppståndna odöda med fallenhet för att döda obemärkt. För de nyblivna Forsaken kräver överlevnad mer än ren vapenmakt. Den kräver precisa slag ur mörkret. Trias dechiffrerar order och lär noviser att hantera dolkar, dölja sina rörelser och förvandla sina återupplivade reflexer till dödlig precision mot de levande och Scourge."},{t="Ett välbekant namn",b="Efternamnet Trias väcker märkliga ekon över hela kontinenten. Långt söderut, i kungariket Stormwind, finns Elling Trias, en välkänd osthandlare som i hemlighet har nära band till mästertjuvar och spionmästare. David och Elling har samma efternamn, men inget släktskap mellan dem har bekräftats."}},faq={{q="Vem är David Trias?",a="David Trias är en Forsaken-instruktör i tjuvkonst som finns i Deathknell i Tirisfal Glades. Han lär nyväckta Forsaken-tjuvar deras första stridstekniker och ger dem deras första hemliga uppdrag.",al={"david trias","vem är david trias","tjuvinstruktör i deathknell"}},{q="Var hittar jag David Trias?",a="Han finns i Deathknell, Forsakens startby i Tirisfal Glades. Han står nära byns byggnader och hjälper nyuppståndna odöda.",al={"david trias plats","var finns david trias","tjuvinstruktör i deathknell"}},{q="Är David Trias släkt med Elling Trias i Stormwind?",a="Han har samma efternamn som Elling Trias från Stormwind, men inget släktskap har bekräftats.",al={"elling trias släktskap","trias-familjen","är han släkt med elling trias"}},{q="Vilken roll har han i Forsakens träning?",a="Noviser till tjuvar som kommer ut ur kryptan i Deathknell hänvisas till David Trias med en krypterad skriftrulle. Han tyder deras instruktioner, vägleder deras grundträning och leder in dem på vägen mot att bli Forsakens smygande agenter.",al={"david trias uppdrag","encrypted scroll","vad lär han ut"}}},fx={e2140548={q="På vems sida står David Trias?",a="David Trias är lojal mot Lady Sylvanas Windrunner och de Förfallna. Han är stationerad i Deathknell och ägnar sin odödlighet åt att träna nyuppväckta skurkar. Han hjälper dem bemästra smygande, list och rygghugg så att de kan försvara sin fria vilja mot Scourge och de levande.",al={"david trias fraktion","vem tjänar david trias","david trias lojaliteter"}},["2dca586e"]={q="Varför är David Trias i Deathknell?",a="Deathknell är den främsta platsen där nyväckta Förfallna vaknar. David Trias stannar här för att utvärdera nykomlingar med fallenhet för smygande och list. Han ger dem grundläggande vägledning och undervisning innan de beger sig vidare in i Tirisfal Glades.",al={"varför är david trias här","david trias i deathknell","vad för david trias till deathknell"}},["52093a30"]={q="Vad vill David Trias?",a="Trias vill att nyväckta skurkar snabbt anpassar sig till sitt odöda tillstånd och blir effektiva agenter åt den Mörka Damen. Han förväntar sig att du lär dig värdet av att slå till bakifrån och bemästrar grundläggande skurkfärdigheter, så att du kan överleva de hårda strider som väntar de Förfallna.",al={"david trias motiv","vad behöver david trias","david trias mål"}}},fp="11,147,24.425.0,15.220.1,19.172.0,29.155.0,52.101.0,44.197.0"}
P.entries["npc:dawnwatcher-selgorm"] = {n="Dawnwatcher Selgorm",s="Dawnwatcher Selgorm är en mänsklig representant för Argent Dawn, stationerad på Craftsmen's Terrace i Darnassus. Som observatör och kontaktperson i nattalvernas huvudstad håller han uppsikt över rapporter om skuggkultister och mörka hot som rör sig i norra Kalimdor.",h="Dawnwatcher Selgorm är en mänsklig representant för Argent Dawn, stationerad på Craftsmen's Terrace i...",kw={"argent dawn","blackfathom deeps","blackfathom villainy","craftsmen's terrace","darnassus","dawnwatcher selgorm","twilight's hammer"},ang={["faction:Alliance"]="För Alliance-äventyrare som utforskar norra Kalimdor är Selgorm en viktig länk mellan Darnassus och kampen mot de ondskefulla kulter som gömmer sig längs kusten.",["race:Human"]="Mänskliga resenärer som besöker Teldrassils avlägsna grenar kan finna tröst i att möta en landsman som tjänar den ädla Argent Dawn."},sec={{t="Ögon i världsträdet",b="Argent Dawn fokuserar främst på den odöda Scourge som härjar i Eastern Plaguelands, men deras vaksamhet sträcker sig dit uråldrig ondska slår rot. Dawnwatcher Selgorm håller vakt i Darnassus och överbryggar klyftan mellan de tillbakadragna nattalverna och den större kampen mot ondskan. Från Craftsmen's Terrace samlar han underrättelser om hot som växer fram i Kalimdors vildmark och värvar dugliga Alliance-resenärer för att slå till mot kultister och mörka krafter innan deras inflytande kan fördärva landet."},{t="Ett slag mot mörkret",b="Selgorm oroar sig främst för Blackfathom Deeps vid The Zoram Strand i Ashenvale. Han ser den vidriga föreningen mellan kulten Twilight's Hammer och de slingrande naga under vågorna och belönar erfarna mästare som vågar sig in i de översvämmade ruinerna. Genom att rikta in sig på kultens onda ledare och återta besmittade reliker hoppas han hejda de växande skuggor som hotar Kalimdors heliga stränder."}},faq={{q="Vem är Dawnwatcher Selgorm?",a="Dawnwatcher Selgorm är en mänsklig agent för Argent Dawn. Han är stationerad i nattalvernas huvudstad Darnassus för att hålla utkik efter ondskan som breder ut sig över Kalimdor.",al={"selgorm","vem är selgorm","dawnwatcher selgorms bakgrund"}},{q="Var hittar man Dawnwatcher Selgorm?",a="Han står utomhus på Craftsmen's Terrace i Darnassus, med utsikt över nattalvernas huvudstads livliga verkstäder.",al={"selgorms plats","var finns selgorm","selgorm i darnassus"}},{q="Varför är en medlem av Argent Dawn stationerad i Darnassus?",a="Argent Dawn är känt för sin kamp mot Scourge i Lordaeron, men orden har som mål att utrota ondska överallt. Selgorm håller uppsikt över växande kultverksamhet, som Twilight's Hammer, i norra Kalimdor.",al={"argent dawn i darnassus","varför är argent dawn här"}},{q="Vad ber Selgorm äventyrare att göra?",a="Selgorm väntar på att Alliance-hjältar ska återvända från Blackfathom Deeps i Ashenvale med huvudet av Twilight Lord Kelris, ledaren för Twilight's Hammer där. Den sårade Argent Guard Thaelrid uppmanar dem att döda honom och stoppa kultens fördärv från att sprida sig.",al={"selgorms uppdrag","uppdragsgivare för blackfathom villainy"}}},fx={["7dd87e6e"]={q="På vems sida står Dawnwatcher Selgorm?",a="Selgorm är en agent för Argent Dawn, en neutral orden som har vigt sig åt att skydda Azeroth från fördärv och mörker. Argent Dawn står utanför fraktionspolitiken, men Selgorm har slagit läger bland nattalverna i Darnassus för att söka hjälp från allianshjältar som är villiga att slå till mot vidriga kulter.",al={"selgorms fraktion","vem tjänar selgorm","är selgorm med alliansen"}},["6f2227e4"]={q="Vilka har Dawnwatcher Selgorm band till?",a="Selgorm lyder direkt under Argent Dawn. Även om han är stationerad i nattalvernas huvudstad Darnassus är hans plikt knuten till ordens globala vaksamhet, inte till Kaldoreis ledarskap. Han håller uppsikt över skuggiga hot som gror långt från ordens främsta fästen i Plaguelands.",al={"selgorm och argent dawn","vilka arbetar selgorm med","selgorms allierade"}}},fp="19,269,22.445.0,25.351.1,27.126.0,39.131.0,52.203.0,40.258.0"}
P.entries["npc:dawnwatcher-shaedlass"] = {n="Dawnwatcher Shaedlass",s="Dawnwatcher Shaedlass är en Night Elf knuten till Argent Dawn och stationerad på Craftsmen's Terrace i Darnassus. Som en diskret spanare i Kalimdor söker han nyheter om sina ordensbröder, som skickats ut på farliga spaningsuppdrag i fientliga områden.",h="Dawnwatcher Shaedlass är en Night Elf knuten till Argent Dawn och stationerad på Craftsmen's Terrace i...",kw={"argent dawn","blackfathom deeps","craftsmen's terrace","darnassus","dawnwatcher","shaedlass","thaelrid"},ang={["faction:Alliance"]="Shaedlass ger Alliance-hjältar i Darnassus en direkt länk till Blackfathom Deeps mysterier och skickar spanare för att rädda en agent långt bakom fiendens linjer.",["race:NightElf"]="Som en av få Night Elves som öppet tjänar under Argent Dawns fana förenar Shaedlass Teldrassils inåtvända politik med en världsomspännande vaksamhet mot mörkret."},sec={{t="Argent Dawns ögon",b="Argent Dawn är mest känt för sitt bittra korståg mot Scourge i Eastern Plaguelands, men dess vaksamhet sträcker sig långt bortom Lordaeron. Dawnwatcher Shaedlass håller till i Night Elf-huvudstaden Darnassus och vakar över fraktionens intressen i Kalimdor. Från sin diskreta post på Craftsmen's Terrace håller han uppsikt över hemliga expeditioner mot mörka kulter och korrumperande krafter som hotar den vidare världen."},{t="En saknad broder",b="Shaedlass största bekymmer är var Argent Guard Thaelrid befinner sig. Hans kamrat skickades söderut för att undersöka rapporter om lömsk kultverksamhet i Blackfathom Deeps, längs Ashenvales kust. Shaedlass befarar att Thaelrid råkat ut för något bland Twilight's Hammer och det gamla alviska templets vattenlevande fasor. Därför värvar han modiga Alliance-äventyrare för att ta sig in i ruinerna och ta reda på vad som hänt spanaren."}},faq={{q="Vem är Dawnwatcher Shaedlass?",a="Dawnwatcher Shaedlass är en Night Elf-agent för Argent Dawn. Han är stationerad på Craftsmen's Terrace i Darnassus och fungerar som förbindelse och kontaktperson för ordens insatser i norra Kalimdor.",al={"vem är shaedlass","dawnwatcher shaedlass bakgrund","argent dawn npc darnassus"}},{q="Varför finns en medlem av Argent Dawn i Darnassus?",a="Även om Argent Dawn främst utkämpar kriget mot Scourge i Lordaeron har orden vaksamma agenter runtom på Azeroth för att spåra korrumperande ondska. Shaedlass samordnar underrättelser och bevakar hot som växer fram i Kalimdor, däribland skuggiga kulter.",al={"varför finns argent dawn i darnassus","argent dawn night elf"}},{q="Vad ber Shaedlass äventyrare att göra?",a="Shaedlass skickar Alliance-äventyrare till det sjunkna templet Blackfathom Deeps på uppdraget 'In Search of Thaelrid'. Han ber dem hitta Argent Guard Thaelrid, en förklädd spanare som gav sig in i ruinerna för att undersöka Twilight's Hammer och aldrig återrapporterade.",al={"shaedlass uppdrag","in search of thaelrid uppdrag"}},{q="Var hittar jag Dawnwatcher Shaedlass?",a="Han finns i Darnassus på Craftsmen's Terrace, nära huvudstadens handelsmän och hantverkare.",al={"shaedlass plats","var finns dawnwatcher shaedlass"}}},fx={["87de680c"]={q="På vems sida står Dawnwatcher Shaedlass?",a="Dawnwatcher Shaedlass tjänar Argent Dawn, en neutral sammanslutning som bekämpar ondska var den än hotar Azeroth. Han är en nattalv som bor i huvudstaden Darnassus, men hans främsta lojalitet ligger hos Argent Dawn snarare än hos Alliansen. Därför kan han fokusera på större faror som kulter och Scourge.",al={"shaedlass fraktion","vem tjänar shaedlass","är shaedlass med alliansen"}},e7a15b6d={q="Vem lyder Dawnwatcher Shaedlass under?",a="Shaedlass rapporterar direkt till Argent Dawn. Han oroar sig särskilt för sin medagents öde. Argent Guard Thaelrid skickades för att undersöka den vidriga korruption som slår rot i Blackfathom Deeps längs Ashenvales kust.",al={"shaedlass förbindelser","vem arbetar shaedlass med","shaedlass band till argent dawn"}}},fp="21,185,23.347.0,17.341.1,29.171.0,42.162.0,42.200.0,39.113.0"}
P.entries["npc:dazalar"] = {n="Dazalar",s="Dazalar är en Night Elf-jägartränare i Dolanaar på Teldrassil. Han vägleder unga väktare och spejare när de finslipar sitt prickskytte och lär sig den heliga konsten att knyta band till vilddjuren i de väldiga grenverken.",h="Dazalar är en Night Elf-jägartränare i Dolanaar på Teldrassil.",kw={"dazalar","dolanaar","jägare","night elf","taming the beast","teldrassil","the hunter's path","tränare"},ang={["class:Hunter"]="Dazalar är en av de första mentorerna en Night Elf-jägare möter. Han vägleder dem genom grundläggande prövningar i att bemästra vilddjur och träna husdjur.",["race:NightElf"]="Han för traditionerna från Kaldoreis väktare och spejare vidare och lär unga Night Elves att leva i balans med naturens vilda rovdjur."},sec={{t="Lägret i Dolanaar",b="I bosättningen Dolanaar är Dazalar en av de främsta mentorerna för unga jägare som ger sig bortom Shadowglens skyddade glänta. Night Elf-samhället förlitar sig i hög grad på sina jägare och väktare för att patrullera vildmarken, och Dazalar ser till att nykomlingarna har den disciplin och det tålamod som krävs för att skydda Teldrassils känsliga ekosystem."},{t="Band till vildmarken",b="En viktig övergångsrit under Dazalars ledning är att lära sig tämja och ta hand om vilddjur. I stället för att kuva varelser med ren kraft och tvinga dem att lyda jägarens vilja, betonar Kaldoreis sed att sluta en ömsesidig pakt med skogens rovdjur, som nattetigrar, ugglor och strigidjägare, och träna dem att strida vid sina mästares sida med respekt."}},faq={{q="Vem är Dazalar?",a="Dazalar är en Night Elf-jägartränare i byn Dolanaar på Teldrassil. Han lär ut nya stridsförmågor till nybörjarjägare och vägleder dem i konsten att tämja vilddjur.",al={"vem är dazalar","dazalars bakgrund","dazalars identitet"}},{q="Var hittar jag Dazalar?",a="Han finns utomhus i Dolanaar, Teldrassils centrala knutpunkt som äventyrare når kort efter att de lämnat Shadowglens startområde.",al={"dazalars plats","var finns dazalar","jägartränare i dolanaar"}},{q="Vilken träning erbjuder Dazalar?",a="Dazalar lär ut olika avståndsattacker, fällor och överlevnadstekniker för blivande jägare. Han skickar också nybörjare på prövningar där de får bemästra konsten att tämja vilda djur.",al={"vad lär dazalar ut","dazalars färdigheter","jägarträning hos dazalar"}},{q="Erbjuder Dazalar några särskilda uppdrag?",a="Ja, Dazalar erbjuder viktiga uppdrag i jägarträningen, däribland The Hunter's Path, flerdelade Taming the Beast och Training the Beast. De lär unga jägare att knyta band till och ta hand om sina djurkamrater.",al={"dazalars uppdrag","jägaruppdrag i dolanaar","uppdraget taming the beast"}},{q="Varför förlitar sig Night Elves så mycket på jägare?",a="I årtusenden har Kaldorei levt i harmoni med Kalimdors uråldriga skogar. Bågskyttar och spejare utgör ryggraden i väktararmén och använder smygande, prickskytte och djurallierade för att skydda sina marker utan att störa naturen.",al={"night elf-jägarnas bakgrund","varför väktarna använder jägare","kaldorei-jägare"}},{q="Vilka slags vilddjur skickar Dazalar jägarna att tämja?",a="Han leder jägarna till att spåra upp Teldrassils inhemska djurliv, däribland lokala spindlar, nattetigrar och rovfåglar. Där prövas deras förmåga att närma sig och lugna vilda rovdjur.",al={"vilka vilddjur ska tämjas","tämjningsprövning i dolanaar","tämja vilddjur på teldrassil"}}},fx={["0fd37214"]={q="Vilken sida står Dazalar på?",a="Dazalar är lojal mot nattalverna i Darnassus och tjänar som en del av Alliance. Han är stationerad i Dolanaar och ägnar sitt hantverk åt att vägleda unga kaldorei-jägare i samklang med Teldrassils vildmark. På så sätt kan de försvara sitt folk och bevara balansen i sitt nya skogshem.",al={"dazalars fraktion","tillhör dazalar alliance","vem tjänar dazalar"}},["5be2ad1d"]={q="Vad vill Dazalar?",a="Dazalar vill träna blivande jägare i grunderna i spårning, skytte och överlevnad i vildmarken. Utöver vanlig stridsförmåga vill han se till att varje kaldorei-jägare behärskar konsten att knyta band till, tämja och träna de olika bestar som hör hemma i Teldrassils trädkronor.",al={"vad är dazalars mål","dazalars syfte","varför tränar dazalar jägare"}},["6e364749"]={q="Varför är Dazalar här?",a="Dazalar bor i Dolanaar eftersom bosättningen är den första större tillflyktsorten unga nattalver kommer till efter att ha lämnat Shadowglen. Eftersom han håller till precis intill skogsstigarna kan han undervisa blivande spejare, väktare och skogvaktare innan de ger sig djupare in i Teldrassils otämjda trakter.",al={"varför är dazalar i dolanaar","dazalars roll i teldrassil","varför dazalar är här"}}},fp="7,160,23.227.0,21.226.0,15.102.0,25.102.0,35.141.0,38.202.0,46.236.0,54.181.0"}
P.entries["npc:deathguard-bartholomew"] = {n="Deathguard Bartholomew",s="Deathguard Bartholomew är en vaksam Forsaken-soldat stationerad i staden Brill. Han har till uppgift att upprätthålla säkerheten i Tirisfal Glades och hjälper resenärer att hitta rätt i den pesthärjade bosättningen samt ser till att de lokala försvararna håller disciplinen.",h="Deathguard Bartholomew är en vaksam Forsaken-soldat stationerad i staden Brill.",kw={"bartholomew","brill","deathguard","forsaken","vakt","tirisfal"},ang={["faction:Horde"]="Allierade som anländer från Kalimdor kan lita på att Bartholomew hjälper dem att hitta rätt på Brills dimhöljda gator.",["race:Undead"]="För nyligen befriade Forsaken som kommer ut från Deathknell är vakter som Bartholomew i Brill det första organiserade mötet med Lady Sylvanas stående armé."},sec={{t="Brills väktare",b="Deathguard Bartholomew står vakt i Brill och utgör en del av Forsakens starka militära ryggrad. Liksom sina Deathguards-kamrater i Tirisfal Glades försvarar han återtagna områden mot kvarvarande Scourge, fanatiska Scarlet Crusaders och andra hot mot Lady Sylvanas välde. Förutom att hålla vakt visar han resenärer till rätta bland stadens inrättningar och hjälper till att upprätthålla ordningen bland de nyligen uppväckta."}},faq={{q="Vem är Deathguard Bartholomew?",a="Deathguard Bartholomew är en Forsaken-vakt stationerad i Brill i Tirisfal Glades. Han vakar över staden och visar vägfarare till sevärdheter.",al={"bartholomew","vem är bartholomew","deathguard bartholomew bakgrund"}},{q="Vilken roll har Deathguard?",a="Deathguard utgör Forsakens främsta infanteri- och försvarsstyrka. De patrullerar Lordaerons områden, försvarar bosättningar som Brill mot Scourge och Scarlet Crusade och upprätthåller ordningen på Dark Ladys vägnar.",al={"vad är deathguards","deathguard-fraktionen","forsaken-vakter"}},{q="Kan Deathguard Bartholomew visa vägen?",a="Ja. Liksom många stadsvakter runt om i Azeroth kan Bartholomew visa resenärer till viktiga inrättningar i Brill, däribland tränare, värdshuset och yrkeshandlare.",al={"var ligger värdshuset","vägbeskrivning i brill","vägbeskrivning från vakten i brill"}}},fx={["73481549"]={q="Vilken sida står Deathguard Bartholomew på?",a="Deathguard Bartholomew tjänar Forsaken och den mörka damen, drottning Sylvanas Windrunner. Som del av militärstyrkan som försvarar Tirisfal Glades är han lojal mot Horde och skyddar Brill mot Scourge, Scarlet Crusade och objudna Alliance-intränglingar.",al={"bartholomews fraktion","bartholomews lojalitet","vem tjänar bartholomew"}},d578d9b4={q="Varför är Deathguard Bartholomew här?",a="Bartholomew är stationerad i Brill som en del av den lokala garnisonen. Efter att Forsaken återtagit stadens ruiner står han fortfarande vakt för att säkra bosättningen, upprätthålla militär ordning och vägleda resenärer och nyvakna odöda som tar sig fram genom Tirisfal Glades.",al={"varför är bartholomew i brill","bartholomews uppgift","vad gör bartholomew här"}},["750c03a9"]={q="Vad vill Deathguard Bartholomew?",a="Bartholomews främsta uppgift är att hålla Brill tryggt och välordnat för Forsaken. Utöver att hålla vakt över staden och visa ankommande resenärer vägen förlitar han sig på dugliga äventyrare som kan hjälpa till med lokala hot och militära uppgifter för att hålla bosättningen befäst.",al={"bartholomews mål","vad behöver bartholomew","bartholomews motiv"}},["5978a3f3"]={q="Vem lyder Deathguard Bartholomew under?",a="Bartholomew är en svuren soldat i Deathguard, Forsakens stående militär och stadsförsvar. Han lyder under det lokala Forsaken-ledarskapet i Brill och tjänar i slutänden Undercity och Lady Sylvanas Windrunner tillsammans med sina medvakter.",al={"bartholomews allierade","bartholomews förbindelser","vem lyder bartholomew under"}}},fp="22,163,17.336.0,30.130.0,35.190.0,43.125.0"}
P.entries["npc:deathguard-burgess"] = {n="Deathguard Burgess",s="Deathguard Burgess är en Forsaken-vaktpost i staden Brill i Tirisfal Glades. Han håller vakt över bosättningen, upprätthåller ordningen och visar resenärer till viktiga tjänster i byn.",h="Deathguard Burgess är en Forsaken-vaktpost i staden Brill i Tirisfal Glades.",kw={"brill","burgess","deathguard burgess","forsaken","vakt","tirisfal glades"},ang={["faction:Horde"]="Allierade på besök från Kalimdor kan tala med Burgess för att hitta rätt i Brills främmande, pesthärjade kvarter när de söker efter försäljare av förnödenheter eller vill vila på värdshuset.",["race:Undead"]="För nyvakna Forsaken som lämnar Deathknell ger vakter som Burgess i Brill den första inblicken i Lordaerons större infrastruktur."},sec={{t="En vakt i Brill",b="I bosättningen Brill, strax norr om Undercity, är Deathguard Burgess en av stadens vakter som skyddar området mot Scourge och Scarlet Crusade. Liksom andra Deathguards i Tirisfal Glades hjälper Burgess anländande Forsaken genom att visa dem till lokala hantverkare, klassinstruktörer och samhällstjänster. Därmed håller han den utsatta utposten i gång."}},faq={{q="Vem är Deathguard Burgess?",a="Deathguard Burgess är en odöd vaktpost som tjänar Forsaken i staden Brill. Han hjälper till att upprätthålla ordningen i byn och visar besökare till lokala instruktörer och sevärdheter.",al={"burgess brill","vem är burgess","deathguard burgess historia"}},{q="Vilken roll har Deathguards i Brill?",a="Deathguard är Forsakens ordinarie militär- och polisstyrka. På platser som Brill skyddar de lokalbefolkningen mot yttre hot som Scourge och Scarlet Crusade, samtidigt som de upprätthåller den civila ordningen.",al={"vad är deathguards","deathguards roll"}},{q="Kan Deathguard Burgess visa vägen?",a="Ja. Precis som många stadsvakter runtom Azeroth kan Burgess visa resenärer till klassinstruktörer, det lokala värdshuset, yrkesmästare och andra viktiga platser i Brill.",al={"burgess visar vägen","vart ska man gå i brill"}}},fx={ff001a75={q="Vilken sida står Deathguard Burgess på?",a="Deathguard Burgess tjänar Lady Sylvanas Windrunner och Forsaken som en del av det gryende kungariket med bas i Undercity. Som vaktpost i Brill försvarar han bosättningen mot kvarvarande hot från Scourge, fientliga korsfarare från Scarlet Crusade och alla utomstående som vågar hota den mörka damens nyvunna rike.",al={"burgess fraktion","vem tjänar deathguard burgess","är burgess forsaken"}},e5a62f54={q="Vad vill Deathguard Burgess?",a="Burgess vill ha ordning, vaksamhet och trygghet i Brill. Som medlem av stadsvakten ska han bevaka vägarna, hindra fientliga hot från att ta sig över bosättningens gränser och se till att nyuppståndna Forsaken och besökare hittar rätt i Tirisfal Glades.",al={"vad är burgess mål","burgess syfte","vad gör deathguard burgess"}},a4fa6528={q="Varför är Deathguard Burgess här?",a="Burgess är stationerad i Brill eftersom det är en viktig framskjuten bosättning norr om huvudstadens ruiner och Undercity. Genom att vakta stigarna genom Tirisfal Glades ser han till att Forsakens intressen förblir skyddade mot fanatiker från Scarlet Crusade, tanklösa odöda som stryker omkring i vildmarken och annalkande bestar.",al={"varför är burgess i brill","deathguard burgess plats","varför är deathguard burgess stationerad här"}}},fp="18,149,19.269.0,26.132.0,44.106.0,42.122.0"}
P.entries["npc:deathguard-dillinger"] = {n="Deathguard Dillinger",s="Deathguard Dillinger är en Forsaken-vaktpost i Brill i Tirisfal Glades. Han bevakar stadens utkanter, visar nyanlända odöda till viktiga tjänster och ger rekryter i uppdrag att hålla de lokala resterna av Scourge på avstånd.",h="Deathguard Dillinger är en Forsaken-vaktpost i Brill i Tirisfal Glades.",kw={"ett ruttnande uppdrag","brill","deathguard","deathguard dillinger","dillinger","kvarnarna är översvämmade","tirisfal glades","ulag the cleaver"},ang={["class:Warrior"]="Blivande Forsaken-krigare arbetar ofta direkt med Dillinger för att pröva sin stridsförmåga mot de våldsamma gastar och skelettfasor som stryker omkring vid Brills utkanter.",["faction:Horde"]="Dillinger visar hur Forsaken kämpar för att skapa ett säkert fäste i norra Lordaeron. Han visar Hordens allierade det obevekliga hot som tanklösa Scourge utgör alldeles intill deras hem.",["race:Undead"]="För nybefriade Forsaken som kommer från Deathknell är Dillinger ofta den första representanten för militär myndighet de möter. Han visar dem vägen till träning och deras första uppgifter i Sylvanas tjänst."},sec={{t="Brills vaktpost",b="Som medlem av Forsakens Deathguard står Dillinger vid ingången till Brill. Han skyddar staden vid frontlinjen och visar resenärer vägen när de kommer från Deathknell. Han berättar var stadens värdshus, rådhus och tränare finns och hjälper nyväckta odöda att hitta rätt i sitt nya liv under Dark Ladys styre."},{t="Säkra gränslandet",b="Dillinger rekryterar dugliga äventyrare för att rensa de närliggande gårdarna och kvarnarna från kvarvarande tanklösa Scourge. Genom uppdrag som att döda ruttnande gastar och återta angripna anläggningar vill han skapa en säkerhetszon runt Brill. Då kan Forsakens nya bosättningar stå emot de odödas ständiga angrepp."},{t="Hålla fasorna i schack",b="Utöver vanliga patruller håller Dillinger vakt över en av Deathguards mörkare hemligheter. När Scourge svepte genom Tirisfal tillfångatog Forsaken Ulag the Cleaver, en Scourge-agent med fri vilja som ändå förblev bunden till Lich King, och förseglade honom i ett mausoleum norr om Brill. När alla försök att bryta kungens grepp misslyckades skickar Dillinger en beprövad krigare för att häva förseglingen och förgöra Ulag."}},faq={{q="Var hittar jag Deathguard Dillinger?",a="Deathguard Dillinger står vid Brills utkant i centrala Tirisfal Glades och vakar över vägen in till staden.",al={"dillingers plats","var är dillinger","deathguard dillingers koordinater"}},{q="Vilken uppgift har Deathguard?",a="Deathguard är Forsakens stående armé och ordningsmakt. Den skyddar bosättningar som Brill och Undercity mot Scourge, Scarlet Crusade och andra hot i regionen.",al={"vad är deathguard","vilka är deathguards","deathguards uppgift"}},{q="Vilka uppdrag erbjuder Deathguard Dillinger?",a="Dillinger ger äventyrare i uppdrag att dräpa tanklösa Scourge som strövar omkring på de omgivande fälten och vid kvarnarna, återta viktig lokal infrastruktur och ta itu med farliga varelser som Ulag the Cleaver.",al={"dillingers uppdrag","vilka uppdrag har dillinger"}},{q="Kan Deathguard Dillinger visa vägen?",a="Ja. Prata med Dillinger för att be om vägbeskrivning till viktiga tjänster, yrkestränare och klasstränare runtom i Brill.",al={"dillingers vägbeskrivning","be dillinger om hjälp"}},{q="Varför slåss Forsaken mot andra odöda nära Brill?",a="De tanklösa odöda som strövar omkring i Tirisfal är fortfarande slavar under Scourge och Lich King. Forsaken har brutit sig fria från den mentala kontrollen och måste därför utplåna de vilda resterna för att skydda sitt eget territorium.",al={"varför slåss mot scourge","odöda som slåss mot odöda","gastarna i brill"}},{q="Vem är Ulag the Cleaver?",a="Ulag the Cleaver är en farlig Scourge-vedervärdighet knuten till gravarna i närheten, utanför Brill. Dillinger samordnar med Forsaken-rekryter för att frammana och förgöra Ulag och hålla området säkert.",al={"ulag-uppdraget","vem är ulag","ulag the cleaver"}}},fx={["9ba09071"]={q="Vem är Deathguard Dillinger?",a="Deathguard Dillinger är en Forsaken-soldat som är stationerad för att vakta bosättningen Brill i Tirisfal Glades. Liksom resten av Deathguard var han en gång en människa från Lordaeron, som föll offer för odödhetens pest innan han bröt sig fri från Lich Kings järngrepp under drottning Sylvanas Windrunner. Nu håller han vakt vid frontlinjen för att försvara nyvakna Forsaken och skydda riket mot tanklösa Scourge som stryker omkring i utkanterna.",al={"vem är dillinger","deathguard dillinger berättelse","dillingers identitet"}},e6386dfb={q="Vilken sida står Deathguard Dillinger på?",a="Dillinger är djupt lojal mot Forsaken och bansheedrottningen Lady Sylvanas Windrunner. Som svuren väktare av Undercitys yttre försvarslinje tjänar han Horde genom att hålla stånd mot de kvarvarande resterna av Scourge och alla andra som hotar de fria odödas dyrköpta självständighet i Lordaeron.",al={"dillingers fraktion","vem tjänar dillinger","dillingers lojalitet"}},["7c69f447"]={q="Varför är Deathguard Dillinger här?",a="Dillinger är posterad utanför Brill för att upprätthålla ordningen, stå vakt och visa nyanlända Forsaken vägen efter att de kommit från kryptorna i Deathknell. Tirisfal Glades kryllar av tanklösa odöda, vilddjur och fientliga inkräktare, så erfarna Deathguards som han placeras vid vägskälen i staden för att organisera försvaret och värva dugliga resenärer till att röja undan hot i närheten.",al={"varför är dillinger i brill","vad gör dillinger här","dillingers postering"}},fe023b9f={q="Vad vill Deathguard Dillinger?",a="Dillinger vill att markerna kring Brill rensas från tanklösa Scourge och farliga vidunder. Han värvar lovande nykomlingar bland Forsaken för att minska antalet ruttnande gastar som hemsöker trakten och undanröja oregerliga hot. Då förblir Brill ett tryggt fäste för drottning Sylvanas växande nation.",al={"vad vill dillinger","dillingers mål","dillingers syfte"}},["394a16a5"]={q="Vem lyder Deathguard Dillinger under?",a="Dillinger är direkt knuten till Deathguard, den stående militärstyrka som ansvarar för att säkra Forsakens bosättningar. Han lyder under befälhavarna i Brill och magistraterna i Undercity och fungerar som en länk vid fronten mellan lokala myndigheter, som Magistrate Sevren, och ankommande äventyrare som kan utföra Forsakens militära order.",al={"dillingers förbindelser","vem lyder dillinger under","dillingers ledarskap"}}},fp="20,181,17.254.0,24.261.0,27.318.1,38.106.0,35.185.0,43.169.0,44.109.0,54.191.0,24.169.0"}
P.entries["npc:deathguard-humbert"] = {n="Deathguard Humbert",s="Deathguard Humbert är en Forsaken-vaktpost i Tarren Mill i Hillsbrad Foothills. Han ska hålla uppsikt över Alliansens framryckning, men hamnar i en pinsam situation när dvärgarna i Dun Garok stjäl hans militära utrustning.",h="Deathguard Humbert är en Forsaken-vaktpost i Tarren Mill i Hillsbrad Foothills.",kw={"deathguard humbert","dun garok","hillsbrad foothills","humbert","humbert's sword","stormpike","tarren mill"},ang={["faction:Horde"]="Att återta Humberts förlorade svärd slår tillbaka mot dvärgarnas djärva fäste i Hillsbrad och bevarar samtidigt värdigheten hos Tarren Mills garnison.",["race:Undead"]="Forsaken-soldater förväntas tjäna den mörka damen med obeveklig vaksamhet. Humberts bristande uppmärksamhet gentemot de levande är därför en pinsam fläck på Deathguard."},sec={{t="En vakt berövad sitt stål",b="Deathguard Humbert fick i uppdrag att skydda Tarren Mills gräns mot hot i trakten, men råkade ut för ett förödmjukande bakslag. High Executor Darthalia skickade honom till ett dolt läger för att hålla uppsikt över Dun Garok. En morgon gick han för att samla ved, och dvärgspanare från Dun Garok stal hans älskade svärd och annan utrustning. Nu försöker den odöda soldaten rädda sin stolthet och få tillbaka sin beväpning innan befälet får reda på vad som hänt."}},faq={{q="Vem är Deathguard Humbert?",a="Deathguard Humbert är en Forsaken-krigare som tjänstgör som spejare och vakt i Tarren Mill. Hans uppgift är att hålla ögonen på fientliga operationer från Alliansen i Hillsbrad Foothills.",al={"humberts bakgrund","vem är humbert","humbert tarren mill"}},{q="Vad hände med Humberts svärd och rustning?",a="High Executor Darthalia skickade Humbert för att hålla uppsikt över Dun Garok på avstånd. En morgon lämnade han sitt dolda läger för att samla ved. När han kom tillbaka hade dvärgspanare från Dun Garok passerat och stulit hans utrustning, däribland hans dyrbara svärd.",al={"humberts svärd stulet","vem tog humberts utrustning","varför behöver humbert hjälp"}},{q="Varför hämtar Humbert inte bara tillbaka sin utrustning själv?",a="Dun Garok är väl befäst och försvaras av disciplinerade dvärgskyttar och bergsmän. En ensam spejare utanför skyttegravarna har små chanser, och Humbert kan inte lätt lämna sin post utan att behöva förklara hur han blev av med sin utrustning.",al={"varför kan humbert inte slåss","humbert dun garok"}}},fx={["9e6e6cc1"]={q="Vilken sida står Deathguard Humbert på?",a="Deathguard Humbert tjänar Forsaken och därmed Horde. Som medlem av Deathguard är han en vaktpost och soldat som svurit att försvara Lordaeron och följa bansheedrottningen Lady Sylvanas Windrunners vilja.",al={"deathguard humberts fraktion","humberts lojalitet","vem tjänar humbert"}},f61ba0a7={q="Vad vill Deathguard Humbert?",a="Humbert vill få tillbaka sin personliga militärutrustning, särskilt sitt svärd. Dvärgiska spejare från Dun Garok stal det medan han var borta från sitt gömställe för att samla ved. Nu står han utan vapen och behöver desperat någon duglig som kan ta sig in på fiendens territorium och återta det.",al={"humberts mål","vad behöver humbert","varför ger humbert uppdrag"}},ed7fd663={q="Varför är Deathguard Humbert stationerad här?",a="Humbert är stationerad i Tarren Mill för att övervaka Alliance närvaro i Hillsbrad Foothills, särskilt dvärgstyrkorna som barrikaderat sig i Dun Garok. Hans post ser till att Forsaken-bosättningen får varning om rörelser söderifrån.",al={"varför är humbert i tarren mill","humberts uppdrag","vad gör humbert här"}}},fp="18,152,29.306.0,26.117.0,43.212.0,50.220.0"}
P.entries["npc:deathguard-linnea"] = {n="Deathguard Linnea",s="Deathguard Linnea är en Forsaken-soldat stationerad vid en Deathguard-utpost i sydöstra Tirisfal Glades. Hon hjälper till att säkra vägarna mellan Brill och de östra gränserna och håller utkik efter hot från Scarlet Crusade och kvarvarande Scourge. Äventyrare som färdas längs huvudvägarna hjälper ofta hennes enhet med patrulleringen.",h="Deathguard Linnea är en Forsaken-soldat stationerad vid en Deathguard-utpost i sydöstra Tirisfal Glades.",kw={"brill","deathguard linnea","forsaken","magistrate sevren","rear guard patrol","tirisfal glades"},ang={["faction:Horde"]="Forsakens allierade som färdas genom Tirisfal Glades kan vinna uppskattning genom att hjälpa Linnea säkra de avlägsna vägarna mot fientliga styrkor.",["race:Undead"]="För Forsaken som nyligen vaknat till liv i Deathknell är hjälpen till Deathguard Linnea vid utposten en av de första uppgifterna för att säkra det nya rikets gränser."},sec={{t="En vakt vid vägkanten",b="Deathguard Linnea står vakt vid en liten befäst post sydost om Brill. Livet – eller odöda livet – på patrull i Tirisfal Glades är förrädiskt, eftersom Forsaken måste försvara sitt spirande rike mot infiltratörer från Scarlet Crusade och tanklösa Scourge som strövar omkring i vildmarken. Linnea är stationerad tillsammans med sina medvakter och leder patrullerna längs vägen. Hon samordnar rapporter med lokala myndigheter, som Magistrate Sevren i Brill, för att hålla den östra vägen mot The Bulwark säker."}},faq={{q="Vem är Deathguard Linnea?",a="Linnea är en odöd soldat i Deathguard, den militära styrka som har i uppdrag att försvara Forsaken-territoriet. Hon är stationerad vid en Deathguard-utpost längs vägen sydost om Brill i Tirisfal Glades.",al={"linnea","deathguard linnea - bakgrund","vem är linnea"}},{q="Varför behöver hon hjälp med patrulleringen?",a="Forsakens militära resurser är hårt ansträngda över hela Tirisfal Glades. Linnea förlitar sig på förbipasserande resenärer och nyväckta hjältar för att röja undan hot i omgivningen, så att budbärare och förrådstransportörer tryggt kan resa fram och tillbaka till Brill.",al={"rear guard patrol - bakgrund","varför hjälpa linnea"}}},fp="17,242,23.342.0,25.156.0,34.199.0"}
P.entries["npc:deathguard-samsa"] = {n="Deathguard Samsa",s="Deathguard Samsa är en Forsaken-vaktpost stationerad i Tarren Mill i Hillsbrad Foothills. Han har fått i uppdrag att hålla Horde vaksamma vid en spänd gräns och skickar resande hjältar att slå till mot lokala hot som närmar sig bosättningen.",h="Deathguard Samsa är en Forsaken-vaktpost stationerad i Tarren Mill i Hillsbrad Foothills.",kw={"deathguard samsa","forsaken","hillsbrad","samsa","souvenirs of death","tarren mill"},ang={["faction:Horde"]="Resande från Horde som passerar genom Hillsbrad Foothills förlitar sig på vaktposter som Samsa för att samordna försvaret mot närliggande angrepp från Alliance i Southshore.",["race:Undead"]="För Forsaken står Deathguard Samsa för det pragmatiska och dystra försvar som krävs för att hålla Lordaerons södra gräns mot fientliga grannar."},sec={{t="Gränsvakt i Tarren Mill",b="Deathguard Samsa håller vakt i Tarren Mill och utgör en del av Forsakens försvar i det omstridda Hillsbrad Foothills. Tarren Mill är Hordes främsta utpost i regionen och utsätts för omedelbart tryck från Alliance-utposter som Southshore samt från vilda djur. Samsas uppgifter är att säkra området och skicka kapabla äventyrare att undanröja hot innan de äventyrar lägret."}},faq={{q="Vem är Deathguard Samsa?",a="Deathguard Samsa är en odöd soldat i Forsakens armé i Tarren Mill. Han vaktar staden och ger besökande äventyrare order om att hjälpa till att skydda regionen mot faror i närheten.",al={"samsa","vem är samsa","deathguard samsas roll"}},{q="Var hittar jag Deathguard Samsa?",a="Han finns i Tarren Mill, den största Horde-bosättningen i norra delen av Hillsbrad Foothills.",al={"samsas plats","var finns deathguard samsa","tarren mills vakts plats"}},{q="Vilka uppdrag ger Deathguard Samsa?",a="Samsa ger äventyrare i uppdrag att ge sig ut i Hillsbrads vildmark, bland annat för att samla in dödskallarna från Hillsbrad-människor som dödats under Hordes fälttåg mot dem.",al={"samsas uppdrag","uppdragsgivare för souvenirs of death"}}},fx={["97a7e196"]={q="Vilken sida står Deathguard Samsa på?",a="Deathguard Samsa tjänar Forsaken och Horde. Som deathguard stationerad i Tarren Mill lyder han under drottning Sylvanas Windrunner, vaktar Forsakens besittningar i Hillsbrad Foothills och skyddar området mot närliggande hot.",al={"deathguard samsas fraktion","tillhör samsa horde","vem tjänar samsa"}},fc9d92c7={q="Varför är Deathguard Samsa här i Tarren Mill?",a="Deathguard Samsa är stationerad i Tarren Mill som en del av Forsakens militära närvaro som försvarar bosättningen. Tarren Mill är en viktig nordlig bastion i Hillsbrad Foothills och behöver pålitliga vakter som bevakar staden och håller uppsikt över farliga vilda djur och fiendens rörelser i området.",al={"varför är samsa i tarren mill","deathguard samsas uppgift i hillsbrad","varför är deathguard samsa här"}}},fp="16,116,30.334.0,24.160.0,34.101.0,42.154.0"}
P.entries["npc:deathguard-simmer"] = {n="Deathguard Simmer",s="Deathguard Simmer är en förfallen soldat som är stationerad strax utanför Deathknell i Tirisfal Glades. Han bedömer nyväckta förfallna och skickar dem för att plundra människornas pumpagård västerut, som patrulleras av Scarlet Crusade, efter reagenser som apotekarna i Brill behöver.",h="Deathguard Simmer är en förfallen soldat som är stationerad strax utanför Deathknell i Tirisfal Glades.",kw={"deathguard","deathguard simmer","deathknell","tirisfal glades"},ang={["race:Undead"]="Simmer erbjuder några av de första uppdragen som riktar sig direkt mot Scarlet Crusade och markerar en odöd äventyrares examen från Deathknells krypter och inträde i Lordaerons vidare försvar."},sec={{t="Väktare utanför Deathknell",b="Deathguard Simmer är stationerad strax utanför Deathknell och företräder de förfallnas militära försvarslinje vid gränsen mellan Deathknells trygga tillflykt och Tirisfal Glades större faror. Regionen kryllar av levande människor, framför allt den fanatiska Scarlet Crusade, som ser alla odöda som styggelser som måste renas med eld och svärd. Simmer prövar nyväckta förfallna genom att skicka dem västerut till Solliden Farmstead, där Scarlet Crusade patrullerar från sitt närbelägna torn, för att stjäla tio pumpor och bära dem till Apothecary Johaan i Brill."}},faq={{q="Vem är Deathguard Simmer?",a="Deathguard Simmer är en förfallen vaktpost stationerad strax utanför Deathknell i Tirisfal Glades. Han prövar nyväckta förfallna genom att skicka dem att stjäla pumpor från en människogård som patrulleras av Scarlet Crusade.",al={"deathguard simmer","vem är simmer","simmer npc"}},{q="Var finns Deathguard Simmer?",a="Han står strax utanför Deathknell i sydvästra Tirisfal Glades, längs vägen som nyväckta förfallna tar ut ur kryptorna.",al={"deathguard simmer plats","var är simmer","hitta deathguard simmer"}},{q="Vilka hot bekämpar Deathguard Simmer?",a="Simmer avskyr de levande människor som fortfarande brukar jorden i Tirisfal och Scarlet Crusade som patrullerar i närheten. Han skickar nyväckta förfallna att plundra Solliden Farmstead på pumpor, för att lära människorna en läxa och samtidigt förse apotekarna i Brill med förnödenheter.",al={"simmers fiender","vad bekämpar simmer","uppdrag vid scarlet palisade"}}},fx={["6ef429fd"]={q="På vems sida står Deathguard Simmer?",a="Deathguard Simmer tjänar Forsaken och den mörka damen, drottning Sylvanas Windrunner. Som svuren medlem av Deathguard, Undercitys stående militärstyrka, är han hängiven åt att försvara Forsakens territorium och slå ner alla hot mot deras nyfödda kungarike.",al={"simmers fraktion","vem tjänar simmer","deathguard simmers lojalitet"}},["2af4e555"]={q="Varför är Deathguard Simmer här?",a="Deathguard Simmer är stationerad strax utanför Deathknell och bevakar vägen som nyuppståndna Forsaken tar in i Tirisfal Glades. Eftersom levande människor fortfarande brukar fälten i närheten och Scarlet Crusade patrullerar från sitt torn i väster, prövar han de nyblivna Forsaken genom att skicka dem på räder mot Solliden Farmstead.",al={"varför är deathguard simmer här","simmer calston estate","varför är simmer stationerad här"}},["08301829"]={q="Vad vill Deathguard Simmer?",a="Simmer vill att nyblivna Forsaken ska visa den mörka damen vad de går för. Han skickar dem att stjäla pumpor från människornas gård i väster, där Scarlet Crusade patrullerar, för att lära de levande en läxa och samtidigt förse Apothecary Johaan i Brill med välbehövliga reagenser.",al={"vad behöver deathguard simmer","simmers mål","vad vill simmer att du ska göra"}},["1e4cdda8"]={q="Vilka band har Deathguard Simmer?",a="Simmer tillhör Deathguard, soldaterna som försvarar Forsakens länder i Tirisfal Glades. Han samarbetar med Apothecary Johaan i Brill och skickar nyblivna Forsaken till honom med pumporna de stjäl från människornas gård i närheten.",al={"simmers kontakter","vem rapporterar simmer till","deathguard simmers band"}}},fp="17,202,27.485.0,25.198.0,35.140.0,42.256.0"}
P.entries["npc:deathstalker-faerleia"] = {n="Deathstalker Faerleia",s="Deathstalker Faerleia är en agent för Forsakens underrättelsetjänst, stationerad djupt inne på fiendens territorium i Pyrewood Village. Från byns rådhus samordnar hon hemliga angrepp mot Pyrewood Council, byns ledare som Arugal använder som marionetter.",h="Deathstalker Faerleia är en agent för Forsakens underrättelsetjänst, stationerad djupt inne på fiendens...",kw={"bakhåll","råd","deathstalker","faerleia","forsaken","pyrewood","silverpine"},ang={["class:Rogue"]="För rogues i Forsakens tjänst visar Faerleia prov på Deathstalkers främsta fältkonst: att obemärkt ta sig rakt in i fiendens maktcentrum och samordna bakhåll.",["race:Undead"]="Faerleia visar hur Deathstalkers förlitar sig på infiltration och kall beräkning för att slå ut fiender till Dark Lady utan att sätta in en hel armé."},sec={{t="Bakom fiendens linjer",b="Som agent för Deathstalkers, Undercitys hemliga underrättelse- och lönnmördargren, har Faerleia fått i uppdrag att infiltrera Pyrewood Village i södra Silverpine Forest. Den isolerade människobosättningen ruvar på mörka hemligheter, däribland en förbannelse som förvandlar invånarna under natthimlen. Från de övre våningarna i rådhuset samordnar Faerleia operationer för att störa bosättningen inifrån och kallar in Horde-agenter för att röja de inflytelserika medlemmarna av Pyrewood Council ur vägen."}},faq={{q="Vem är Deathstalker Faerleia?",a="Hon är agent för Deathstalkers, Queen Sylvanas Windrunners Forsakens avdelning för smygande och underrättelser. Hon har tagit sig in i Pyrewood Village för att föra ett hemligt krig mot dess ledare.",al={"faerleia","vem är faerleia","deathstalker faerleia"}},{q="Var hittar du Deathstalker Faerleia?",a="Faerleia håller sig gömd i rådhuset i Pyrewood Village, i södra Silverpine Forest strax norr om Greymane Wall.",al={"var finns faerleia","faerleias plats","hitta faerleia"}},{q="Vilket uppdrag ger hon?",a="Hon leder äventyrare i Pyrewood Ambush, en operation för att lönnmörda rådsherrarna som styr Pyrewood Village och försvaga bosättningens motstånd mot Forsaken.",al={"faerleias uppdrag","uppdraget pyrewood ambush"}},{q="Varför riktar Deathstalkers in sig på Pyrewood Village?",a="Arugal använder Pyrewood Council som marionetter för att hålla de förbannade byborna under sin kontroll. Faerleia tror att Arugals söner kommer att vända sig mot sin herre om rådet dödas, vilket hjälper Forsaken att ta byn och driva bort Arugal från Shadowfang Keep.",al={"varför anfalla pyrewood","deathstalkers i pyrewood"}}},fx={["72e51f96"]={q="På vems sida står Deathstalker Faerleia?",a="Faerleia är en agent i Deathstalkers, underrättelse- och lönnmördarorden som tjänar Lady Sylvanas Windrunner och Forsaken. Hon är lojal mot Undercity och Horde och stärker deras grepp om Silverpine Forest mot fientliga enklaver.",al={"faerleias fraktion","vem tjänar faerleia","faerleias lojalitet"}},["7830562d"]={q="Vad vill Deathstalker Faerleia?",a="Hon vill förinta Pyrewood Villages ledarskap. Djupt inne på fientligt territorium samordnar Faerleia ett bakhåll mot Pyrewood Council för att krossa byns organiserade motstånd och undanröja det lokala hotet.",al={"vad vill faerleia","faerleias mål","faerleias uppdrag"}},fcf28179={q="Varför är Deathstalker Faerleia i Pyrewood Village?",a="Faerleia har smugit sig förbi Pyrewoods försvarare och in i själva stadshuset. Hon befinner sig mitt i maktens centrum och ligger på lur för att slå till avgörande mot byns ledare innanför deras egna murar.",al={"varför är faerleia här","varför är faerleia i pyrewood","faerleia i silverpines stadshus"}},e3ddcd8c={q="Vilka band har Deathstalker Faerleia?",a="Faerleia lyder under Forsakens Deathstalkers och rapporterar vidare i befälskedjan till drottning Sylvanas Windrunner. I fält förlitar hon sig på betrodda Horde-spejare och äventyrare som är djärva nog att infiltrera den fördömda bosättningen och genomföra hennes bakhåll.",al={"faerleias band","faerleias kontakter","vem arbetar faerleia med"}}},fp="21,200,18.513.1,29.183.0,41.121.0,27.176.0,53.260.0"}
P.entries["npc:deathstalker-lesh"] = {n="Deathstalker Lesh",s="Deathstalker Lesh är en Forsaken-skurk som tjänstgör som framskjuten spejare vid Southpoint Tower i Hillsbrad Foothills. Direkt underställd High Executor Darthalia håller hon uppsikt över människornas gårdar i Hillsbrad Fields för att avgöra när Forsaken bör slå till.",h="Deathstalker Lesh är en Forsaken-skurk som tjänstgör som framskjuten spejare vid Southpoint Tower i Hillsbrad...",kw={"deathstalker lesh","high executor darthalia","hillsbrad fields","hillsbrad foothills","southpoint tower","tarren mill","dags att slå till"},ang={["class:Rogue"]="Deathstalker Lesh visar vilken viktig militär funktion hemliga agenter fyller i Hordens krigsinsats.",["race:Undead"]="För Forsaken står spejare som Lesh för det livsviktiga arbetet vid gränsen med att säkra Lordaeron mot Alliansens återkomst."},sec={{t="Ögon på fälten",b="Från sin utkiksplats vid Southpoint Tower, vid den södra vägen genom Hillsbrad Foothills, bevakar Deathstalker Lesh människornas bönder och stadsmilis som arbetar på närliggande Hillsbrad Fields. Som agent för Deathstalkers, Forsakens hemlighetsfulla underrättelse- och lönnmördarkår, kartlägger Lesh fiendens rörelser och antal åt High Executor Darthalia i Tarren Mill. När tiden är inne skickar Lesh ett kodat meddelande till Darthalia: ”The raven's cry from the west doth beckon”, som signalerar att Hillsbrad är moget för Forsakens anfall."}},faq={{q="Vem är Deathstalker Lesh?",a="Lesh är en Forsaken-spejare stationerad vid Southpoint Tower. Hon lyder under High Executor Darthalia i Tarren Mill och bevakar människornas aktivitet över Hillsbrad Fields.",al={"deathstalker lesh","vem är lesh","lesh hillsbrad"}},{q="Vilka är Deathstalkers?",a="Deathstalkers tjänar drottning Sylvanas Windrunner som spejare, spioner och lönnmördare. De utgör den hemliga delen av Forsakens militär och samlar underrättelser samt undanröjer viktiga måltavlor i hela Lordaeron.",al={"vad är deathstalkers","deathstalkers orden","forsaken-skurkar"}},{q="Vilken roll har Lesh vid Southpoint Tower?",a="Hon fungerar som framskjuten utkik. Från Southpoint Tower spanar hon över staden Hillsbrad, och när tiden är inne skickar hon en resenär till High Executor Darthalia i Tarren Mill med ett kodat meddelande som signalerar att Hillsbrad är moget för anfall.",al={"spejare vid southpoint tower","lesh uppdrag","varför är lesh här"}},{q="Vem rapporterar Lesh till?",a="Hon rapporterar till High Executor Darthalia, Forsaken-befälhavaren stationerad vid Tarren Mill, som leder offensiven mot människornas styrkor i Hillsbrad.",al={"lesh boss","vem befaller lesh","high executor darthalia"}}},fx={["5ae1cd6e"]={q="På vems sida står Deathstalker Lesh?",a="Deathstalker Lesh är lojal mot Lady Sylvanas Windrunner och Forsaken och tjänstgör som en del av Horde-styrkorna i Hillsbrad Foothills. Som agent stationerad vid Southpoint Tower under Tarren Mills befäl arbetar hon outtröttligt för att säkra Forsakens överhöghet i regionen.",al={"deathstalker leshs fraktion","lesh, alliance eller horde","vem tjänar lesh"}},["024a29bd"]={q="Vad vill Deathstalker Lesh?",a="Lesh vill se Hillsbrad falla till Forsaken. Som spejare vid frontlinjen spanar hon på människornas stad. När stunden är inne behöver hon en snabb budbärare som kan föra hennes kodade signal till High Executor Darthalia i Tarren Mill så att anfallet kan börja.",al={"vad vill lesh","leshs mål","deathstalker leshs uppdrag"}}},fp="17,169,18.547.0,25.155.0,27.184.0,40.257.0,24.144.0"}
P.entries["npc:deathstalker-rane-yorick"] = {n="Rane Yorick",s="Deathstalker Rane Yorick är en agent i Forsakens underrättelsegille, stationerad djupt inne i Silverpine Forest. Tillsammans med sin bror Quinn skickades hon för att spana på gårdarna i norra Silverpine och rapportera till High Executor Hadrec.",h="Deathstalker Rane Yorick är en agent i Forsakens underrättelsegille, stationerad djupt inne i Silverpine...",kw={"deathstalker","erland","forsaken","the ivar patch","rane","skurk","spanare","silverpine","yorick"},ang={["class:Rogue"]="För Forsakens skurkar visar Rane Yorick det farliga fältarbete som förväntas av Deathstalkers: att hålla sig dold och samla underrättelser under ständig fientlig press.",["faction:Horde"]="Hennes underrättelsearbete bidrar till att hålla Hordes försörjningsleder genom Silverpine fria från worgen och lokala bakhåll.",["race:Undead"]="Forsakens mästare möter Rane som en spanare vid fronten, som hindrar Silverpine Forests vilda gränsland från att åter hamna i fientliga händer."},sec={{t="Ögon i skogen",b="Deathstalkers är Lady Sylvanas Windrunners ögon, öron och klingor i hela Lordaeron. Från skuggor och gömda utposter håller agenter som Rane Yorick vildmarken under uppsikt efter hot som kan störa Forsakens herravälde. När Rane och hennes bror Quinn skickades för att spana i norra Silverpine Forest blev de omringade av vilda faror, och ett hemligt spaningsuppdrag blev en kamp för överlevnad."},{t="Instängd vid Ivar Patch",b="Rane Yorick har tagit skydd i ett förfallet boningshus vid Ivar Patch, och hennes uppdrag är röjt. Ghoul Ivar the Foul har skadat hennes bror Quinn svårt, och worgs strövar på fälten mellan henne och tryggheten i The Sepulcher. I stället för att överge sitt uppdrag ber hon resande från Horde samla in worg-hjärtan till en läkande dryck, döda Ivar och föra hennes rapport tillbaka till befälet."}},faq={{q="Vem är Deathstalker Rane Yorick?",a="Hon är agent i Deathstalkers, Forsakens skurkorden av lönnmördare och underrättelseinhämtare. Just nu är hon stationerad i ett förfallet boningshus vid Ivar Patch i Silverpine Forest.",al={"vem är rane yorick","rane yoricks bakgrund","vem är deathstalker yorick"}},{q="Vad är Deathstalkers?",a="Deathstalkers är Forsakens hemliga skurkille och lyder under Lady Sylvanas Windrunner. De utför hemlig spaning, spionage och riktade lönnmord i hela Lordaeron.",al={"vad är deathstalkers","deathstalker-fraktionen","vilka är deathstalkers"}},{q="Varför är hon instängd i ett boningshus?",a="Rane och hennes bror Quinn skickades för att spana på gårdarna i norra Silverpine Forest, men ghoul Ivar the Foul attackerade dem vid Ivar Patch och skadade Quinn svårt. Därför tvingades de ta skydd i boningshuset medan han läker.",al={"varför är rane instängd","boningshus vid ivar patch","varför gömmer hon sig"}},{q="Vem är hennes bror?",a="Hennes bror är Quinn Yorick, en annan Deathstalker på samma spaningsuppdrag. Ghoul Ivar the Foul skadade honom svårt vid Ivar Patch.",al={"rane yoricks bror","vem är erland","deathstalker erland"}},{q="Vilka hot spårar de i Silverpine?",a="Deras uppdrag var att spana på gårdarna i norra Silverpine efter hot mot Forsakens ockupation. De fann en betydligt större Scourge-närvaro än väntat, tillsammans med strövande worgs och ghoul Ivar the Foul.",al={"vad spanar de efter","vad undersöker rane"}},{q="Vart rapporterar hon sina fynd?",a="Hon rapporterar till High Executor Hadrec i The Sepulcher, som övervakar Forsakens ockupation av Silverpine Forest.",al={"vart skickas rapporterna","vem är rane underställd"}}},fx={bafbf2b7={q="På vems sida står Deathstalker Rane Yorick?",a="Deathstalker Rane Yorick är helt lojal mot Forsaken och den mörka damen. Som medlem av Deathstalkers, Forsakens hemliga spion- och lönnmördarorden, utför hon farliga spaningsuppdrag i hela Lordaeron för att skydda deras unga rike mot fiender som lurar i skuggorna.",al={"rane yoricks fraktion","vem tjänar rane yorick","är rane yorick forsaken"}},a4a724f9={q="Vad vill Deathstalker Rane Yorick?",a="Rane vill slutföra sitt spaningsuppdrag och se till att hennes rapport når Forsakens befäl. Hon och hennes följeslagare är instängda och hårt ansatta i Silverpine och behöver desperat pålitliga allierade som hjälper dem, undanröjer hot i närheten och förmedlar deras underrättelser säkert.",al={"vad behöver rane yorick","rane yoricks motiv","varför vill rane yorick ha hjälp"}}},fp="11,186,17.337.0,21.336.1,32.194.0,27.162.0,34.219.0,19.136.0,45.185.0,35.129.0"}
P.entries["npc:deathstalker-vincent"] = {n="Deathstalker Vincent",s="Deathstalker Vincent var en Forsaken-spejare som skickades tillsammans med Deathstalker Adamant för att infiltrera Shadowfang Keep. Den galne magikern Arugal dödade honom, och hans lik ligger kvar i fästningen som en dyster varning till alla som trotsar de vilda worgen där inne.",h="Deathstalker Vincent var en Forsaken-spejare som skickades tillsammans med Deathstalker Adamant för att...",kw={"arugal","deathstalker adamant","deathstalker vincent","shadowfang keep","silverpine forest","vincent","worgen"},ang={["class:Rogue"]="Vincents avrättning är en allvarlig påminnelse om riskerna som smygande agenter möter när de ensamma infiltrerar fientliga fästen.",["faction:Horde"]="När Vincent hittas besannas Forsaken-befälhavarnas värsta farhågor i Silverpine: spaningsgruppen misslyckades, och nu måste fästningen rensas med våld."},sec={{t="En spejares ödesdigra slut",b="Innan Forsaken kunde inleda ett fullskaligt anfall mot bestarna som höll Shadowfang Keep behövde de desperat information om fästningens inre. Två agenter från Deathstalkers, Forsakens underrättelsetjänst, smög förbi barrikaderna: Vincent och Adamant. Uppdraget slutade i katastrof. Adamant tillfångatogs och låstes in i en fängelsecell, medan Vincent släpades direkt inför Shadowfangs herre. Vincent vägrade böja knä eller tjäna Arugals mörka planer och avrättades på plats. Hans kropp lämnades på stengolvet för att ruttna, som ett vittnesmål om magikerns vrede."},{t="Arugals trots",b="Arugal använde Vincents död för att rikta ett skoningslöst budskap till inkräktarna i sitt fäste. Inför den tillfångatagna agenten hånade den galne magikern Forsaken och jämförde deras intrång med de misslyckade försöken från sina forna kamrater i Kirin Tor. Arugal krävde att Vincent skulle överlämna sitt svärd och sina hemligheter till sin herre. När spejaren vägrade slog Arugal ner honom och förklarade att Vincents ruttnande kvarlevor skulle varna alla som var dumdristiga nog att tränga in på hans område."}},faq={{q="Vem var Deathstalker Vincent?",a="Vincent var en Forsaken-spejare som tillhörde Deathstalkers. Han skickades tillsammans med Deathstalker Adamant för att samla in viktiga underrättelser inne i Shadowfang Keep inför Undercitys planerade anfall.",al={"vem är vincent","vincent shadowfang keep","död spion shadowfang"}},{q="Vad hände med Vincent i Shadowfang Keep?",a="Vincent tillfångatogs under sitt spaningsuppdrag och avrättades av ärkemagikern Arugal efter att ha vägrat gå över till fienden eller lämna ut information om Forsaken. Arugal lämnade hans lik där han föll för att visa sin makt.",al={"hur dog vincent","varför är vincent död","vem dödade vincent"}},{q="Var är hans partner, Deathstalker Adamant?",a="Medan Vincent avrättades öppet tillfångatogs Deathstalker Adamant levande och låstes in i en närliggande fängelsecell under en worgenvakts vaksamma blick.",al={"var är adamant","annan deathstalker","adamants plats"}},{q="Varför skickades Deathstalkers till Shadowfang Keep?",a="Silverpine Forest är ett viktigt område för Sylvanas och Forsaken, men Arugals worgen håller regionens fästning Shadowfang Keep. Vincent och Adamant skickades dit för att rekognosera området och försvaret, så att Forsaken kunde genomföra ett effektivt anfall.",al={"varför är deathstalkers i shadowfang","forsakens uppdrag i shadowfang"}}},fx={ebb4e7c7={q="På vems sida står Deathstalker Vincent?",a="Vincent är agent i Deathstalkers, den elitstyrka för spionage och lönnmord som tjänar Lady Sylvanas Windrunner och Forsaken. Han agerar på Undercitys uppdrag för att spana på fiendens fästen och undanröja hot mot deras unga kungarike.",al={"vincents fraktion","vem tjänar vincent","vincents lojalitet"}},["1f4e2f05"]={q="Vad vill Deathstalker Vincent?",a="Vincent försökte samla in viktiga underrättelser i Shadowfang Keep för att möjliggöra ett anfall från Forsaken. Han vägrade trotsigt ända till slutet Archmage Arugals krav på att förråda dem och svära sin klinga åt Arugal och hans mystiske mästare.",al={"vad försökte vincent göra","vincents mål","vincents uppdrag"}}},fp="20,213,19.401.0,17.396.1,29.188.0,44.153.0,43.103.0,51.238.0"}
P.entries["npc:deathwing"] = {n="Deathwing",s="Deathwing Förgöraren, en gång känd som Neltharion Jordens Väktare, är den fallne drakfursten över den svarta drakflocken. De gamla gudarnas mörka viskningar drev honom till vansinne, och han vände sig mot de andra drakfurstarna och kastade världen in i eld och kaos. Trots att han besegrades nära Grim Batol efter det andra kriget och troddes vara död eller försvunnen, hemsöker arvet efter hans skräckvälde fortfarande Azeroths djupaste platser.",h="Deathwing Förgöraren, en gång känd som Neltharion Jordens Väktare, är den fallne drakfursten över den svarta...",kw={"drakfurste","svarta drakflocken","deathwing","demonsjälen","förgöraren","draksjälen","jordens väktare","grim batol","neltharion","prestor"},ang={["faction:Alliance"]="Alliansens adel ryser fortfarande vid tanken på hur nära Lord Daval Prestor var att ta Alteracs krona och manipulera de sju nationernas råd för att förgöra alliansen inifrån.",["faction:Horde"]="Den gamla horden slöt en ondskefull pakt med Deathwing under det andra kriget för att få röda drakar genom Dragonmaw-klanen, en skamfläck som den nya horden vill lämna bakom sig.",["race:NightElf"]="Kaldoreiernas äldste minns Neltharions plötsliga, förödande förräderi för tiotusen år sedan under Ancients krig, en grymhet som splittrade draksläktet och beseglade deras uråldriga imperiums undergång."},sec={{t="Neltharions fall",b="Innan han blev känd som Förgöraren fick Neltharion av titanernas pantheon herravälde över jorden och Azeroths underjordiska valv. Men närheten till världens djupaste hålor utsatte honom för de fängslade gamla gudarnas lömska viskningar. Under de uråldriga Ancients krig tog vansinnet fullständigt över. Han bedrog de andra drakfurstarna och fick dem att fylla en gyllene skiva, Draksjälen, med delar av sin kraft under förevändningen att hejda den brinnande legionen. Sedan vände han det fruktansvärda vapnet mot sina allierade och släppte lös en katastrofal förödelse."},{t="Den mänsklige lordens plan",b="Efter det andra kriget försökte Deathwing störta de dödligas kungariken inifrån. Han antog den mänskliga identiteten Lord Daval Prestor, en karismatisk adelsman, och charmade kung Terenas Menethil II och Lordaerons allians höga råd medan han smidde planer på att ta Alteracs lediga tron. Samtidigt hjälpte han Dragonmaw-klanen vid Grim Batol för att hålla drottning Alexstrasza fången och ta hennes kullar. Hans intriger avslöjades när Rhonin förstörde Demonsjälen, återställde de andra drakfurstarnas stulna kraft och gjorde det möjligt för dem att driva bort Deathwing."},{t="Avkomman som blev kvar",b="I vår tid antar de dödligas kungariken till största delen att Deathwing förstördes eller drevs bort från världen för gott. Den svarta drakflocken är dock fortfarande en aktiv plåga över hela Azeroth. Svarta drakar, ledda av hans listiga avkomma, däribland dottern Onyxia och sonen Nefarian, manipulerar de dödligas politik och sprider skräck från sina bergshålor. Ärren efter den svarta drakfurstens uråldriga förräderi går djupt, och resenärer som vandrar genom karga ödemarker och djupa underjordiska tunnlar fruktar fortfarande att den stora draken ska vakna."}},faq={{q="Vem var Deathwing från början?",a="Deathwing var från början Neltharion Jordens Väktare, ledaren för den svarta drakflocken som titanerna gav kraften att vaka över Azeroths land och berg. För årtusenden sedan gjorde närheten till jordens djup honom sårbar för de gamla gudarnas lömska viskningar, som bröt ner hans förstånd.",al={"neltharions historia","vem är neltharion","jordens väktares ursprung"}},{q="Vad var Draksjälen?",a="Draksjälen, som senare blev känd som Demonsjälen, var en gyllene artefakt som Neltharion smidde under Ancients krig. Han lurade de fyra andra drakfurstarna att kanalisera sina krafter in i den och vände sedan vapnets apokalyptiska kraft mot både sina drakfränder och de dödligas försvarare.",al={"demonsjälen","vad är draksjälen","neltharions artefakt"}},{q="Vem var Lord Daval Prestor?",a="Lord Daval Prestor var en mänsklig förklädnad som Deathwing antog efter det andra kriget. Med kraftfull charm-magi och hovintriger försökte han ta Alteracs tron och manipulera Lordaerons allians inifrån, innan hans förräderi avslöjades.",al={"lord prestor","daval prestors identitet","prestor-lore"}},{q="Hur hänger Deathwing ihop med Grim Batol?",a="Deathwing gav i hemlighet orcherna i Dragonmaw Demonsjälen vid Grim Batol och såg till att den röda drakdrottningen Alexstrasza förblev fjättrad och tvingades föda ungar för kriget. Senare förstörde Rhonin artefakten med en av Deathwings fjäll. Med sina krafter återställda bekämpade de andra drakfurstarna Deathwing och drev bort honom.",al={"deathwing grim batol","vad hände vid grim batol"}},{q="Vem leder den svarta drakflocken i dag?",a="Medan Deathwing är borta och antas vara död verkar hans främsta avkomlingar på egen hand. Dottern Onyxia ruvar i sin håla i Dustwallow Marsh, medan sonen Nefarian leder svarta drakar och experimenterar med drakblod högt uppe på Blackrock Mountain.",al={"nuvarande ledare för svarta drakar","vem leder svarta drakar","nefarian och ony xia"}}},fp="9,406,22.588.0,24.571.1,21.547.0,29.287.0,25.292.0,27.265.1,45.305.0,39.252.2"}
P.entries["npc:deino"] = {n="Deino",s="I Valley of Spirits i Orgrimmar tränar Deino hordenas magiker i de arkana konsterna. Hon lär besvärjare att bemästra arkana och elementära krafter och skickar erfarna magiker över Kalimdor för att studera uråldrig magi och söka upp avlägsna läromästare.",h="I Valley of Spirits i Orgrimmar tränar Deino hordenas magiker i de arkana konsterna.",kw={"deino","laughing sisters","magtränare","orgrimmar","tabetha","trollmagiker","valley of spirits","waters of xavian","xavian"},ang={["class:Mage"]="Som magiker kan du lära dig besvärjelser och portalmagi av Deino i Orgrimmar och sedan studera i Ashenvale och Dustwallow Marsh.",["faction:Horde"]="Som medlem av Horden hittar du Deino i Orgrimmars andliga distrikt, där hon tränar fraktionens besvärjare tillsammans med dess shamaner och häxmästare.",["race:Troll"]="Som troll kan du se hur Darkspear förenar lärd arkan magi med traditionerna i Valley of Spirits."},sec={{t="Valley of Spirits arkanist",b="Deino tränar hordenas magiker i Valley of Spirits i Orgrimmar. Totemer, hyddor och stilla vatten omger de upphöjda plattformarna där hon undervisar. Trollbesvärjare förenar andlig vördnad med arkan behärskning, en väg som Deino delar med lärarkollegorna Enyo och Pephredo."},{t="Arkanans mysterier",b="Deino skickar lovande magiker bortom Durotar för att studera arkana mysterier. I Ashenvales fördärvade vildmarker samlar de förgiftat vatten från Xavian och förtrollat hår från Laughing Sisters. När en elevs krafter växer bortom Orgrimmars undervisning hänvisar Deino dem till avlägsna mästare, däribland Tabetha, en eremitisk trollkvinna i Dustwallow Marsh träskmarker."}},faq={{q="Var hittar jag Deino?",a="Deino står på upphöjda plattformar i Valley of Spirits, i sydvästra Orgrimmar. Trollmagikerna Enyo och Pephredo står vid hennes sida.",al={"deinos plats","var finns deino","deino i orgrimmar"}},{q="Vad lär Deino ut?",a="Deino lär ut arkana besvärjelser samt eld- och frostbesvärjelser, portalskapande och viktiga besvärjelsenivåer allt eftersom magikerna får mer erfarenhet.",al={"deino tränare","vilka besvärjelser lär deino ut"}},{q="Varför skickar Deino magiker till Xavian?",a="Xavian är en uråldrig stad i östra Ashenvale som nu hålls av satyrer. Vattnet sägs rymma stor magisk kraft, och Deino vill ha ett prov från botten av stadens högsta vattenfall för att studera det.",al={"uppdraget waters of xavian","varför xavian"}},{q="Vilka tränare står tillsammans med Deino?",a="Enyo och Pephredo står vid Deinos sida. De tre har namn efter systrarna Graeae i den antika myten och utgör Orgrimmars främsta krets av trollmagikernas mentorer.",al={"vem är enyo","pephredo","trollmagiker i valley of spirits"}},{q="Varför skickar Deino magiker till Dustwallow Marsh?",a="När en magiker blir skickligare skickar Deino dem till Tabetha, en mäktig och tillbakadragen mänsklig eremit djupt inne i Dustwallow Marsh. Tabetha besitter särskilda arkana hemligheter.",al={"deino tabetha","färd till träsket"}},{q="Kan andra än troll träna med Deino?",a="Ja. Hordens magiker av alla raser, däribland troll, orcher och Fördömda, kan lära sig klassbesvärjelser och få vägledning av Deino i Valley of Spirits.",al={"kan orker träna med deino","magiträning för horde"}}},fx={["6ebd5023"]={q="Vem är Deino?",a="Deino är en troll från Darkspear som tränar magiker och bor i Valley of Spirits i Orgrimmar. Även om arkana studier är ovanliga bland hennes folk har hon bemästrat konsten och samarbetar med de andra tränarna för att vägleda blivande magiker i Horde och lära dem kanalisera sin kraft ansvarsfullt.",al={"vem är deino","deinos bakgrund","deino, trollmagiker"}},c489d76d={q="På vems sida står Deino?",a="Deino är orubbligt lojal mot Darkspear-stammen och Horde. I Orgrimmar använder hon sina magiska kunskaper för att stärka Hordes besvärjare så att de bättre kan försvara sitt nya hem.",al={"deinos lojalitet","deinos fraktion","tillhör deino horde"}},d9121d13={q="Vad vill Deino?",a="Deino vill se till att Hordes magiker är väldisciplinerade och väl förberedda för Kalimdors faror. Hon skickar lovande utövare över världen för att söka rena reagenser och esoterisk kunskap hos lärda i avlägsna trakter, så att de kan förfina sin konst och tygla sina arkana förmågor.",al={"vad vill deino","deinos mål","deinos uppgift"}},c3103580={q="Varför är Deino i Orgrimmar?",a="Deino bor i Valley of Spirits för att vägleda unga troll och andra besvärjare i Horde. I hjärtat av Darkspears enklav i Orgrimmar erbjuder hon en pålitlig källa till undervisning i arkana konster i ett samhälle som annars präglas av schamanism och krigskonst.",al={"varför är deino i orgrimmar","deino i valley of spirits","varför är deino här"}}},fp="5,230,21.269.0,27.345.0,23.146.0,22.114.0,36.193.0,41.158.0,46.163.0,32.148.0"}
P.entries["npc:delgren-the-purifier"] = {n="Delgren the Purifier",s="Delgren the Purifier är en mänsklig paladin stationerad vid Maestra's Post, vid Ashenvales norra gräns. Tillsammans med sina följeslagare Balthule Shadowstrike och Feero Ironhand hjälper han nattalverna att rena gränslandet från demonisk magi och skuggmagi, med särskilt fokus på den lömska Cult of the Dark Strand.",h="Delgren the Purifier är en mänsklig paladin stationerad vid Maestra's Post, vid Ashenvales norra gräns.",kw={"althalaxx","argent dawn","ashenvale","balthule shadowstrike","cult of the dark strand","delgren","delgren the purifier","feero ironhand","maestra's post","tower of althalaxx"},ang={["class:Paladin"]="Delgren visar hur långt det heliga ljuset når på Kalimdor och hur paladiner anpassar sitt korståg mot demoner och mörk magi långt bortom Eastern Kingdoms.",["faction:Alliance"]="För Alliansens resande som färdas söderut från Darkshore ger Delgren och hans följeslagare ett tryggt militärt fäste längs den farliga vägen genom Ashenvale.",["race:NightElf"]="Även om traditionella kaldoreier ofta är skeptiska till främmande trosläror har Delgrens grupp vunnit förtroende genom sitt praktiska korståg mot de demoniska kulter som plågar uråldriga ruiner."},sec={{t="En korsfarare vid kaldoreiernas gräns",b="Mänskliga paladiner är en ovanlig syn djupt inne i Kalimdors uråldriga skogar, men Delgren the Purifier kom dit med ett uppdrag. Delgren är knuten till Argent Dawn och reste västerut med en grupp heliga krigare som ville hjälpa Alliansens nya nattalvssamarbetspartner att bekämpa de kvardröjande ondskorna från demoner och odöda lämningar efter det tredje kriget. Han är stationerad nära gränsen mellan Darkshore och Ashenvale och håller vaksam uppsikt över resande som färdas söderut från Auberdine."},{t="Rena Dark Strand",b="Delgrens omedelbara korståg riktar sig direkt mot Cult of the Dark Strand, en ondskefull sammanslutning som verkar kring Tower of Althalaxx i norra Darkshore. Tillsammans med spanaren Balthule Shadowstrike planerar Delgren räder in på kultens område, undersöker deras mörka ritualer och skickar äventyrare för att slå ner kultister, krossa deras åkallningsfokus och spåra upp korrumperade häxmästare som vågar befatta sig med demonisk skugga."},{t="Ett okonventionellt sinne",b="Trots sin hängivna tro på det heliga ljuset och sitt nitiska smeknamn har Delgren ett ovanligt perspektiv på Kalimdors invecklade politik. Till stor irritation och förakt för sina konservativa överordnade tog han sig tid att lära sig orcspråket. Den ovanliga språkkunskapen antyder ett okonventionellt sinne – ett som vill förstå fienderna och grannarna som delar denna otämjda kontinent, i stället för att enbart förlita sig på blind dogmatism."}},faq={{q="Vem är Delgren the Purifier?",a="Delgren är en mänsklig paladin stationerad vid Maestra's Post, längs vägen i norra Ashenvale. Som agent för Argent Dawn hjälper han nattalverna att försvara sina länder mot demonisk korrumption, kultister och kvardröjande skuggor efter Legionens invasion.",al={"vem är delgren","delgrens bakgrund","vem är paladinen vid maestras post"}},{q="Var hittar jag Delgren?",a="Delgren står vid Maestra's Post, en liten nattalvsk utpost i nordvästra Ashenvale, strax söder om gränsstigen som leder till Darkshore.",al={"var är delgren","delgrens plats","delgrens koordinater"}},{q="Varför är en mänsklig paladin ända borta i Ashenvale?",a="Delgren reste västerut med en grupp paladiner från Argent Dawn för att bistå Alliansens nattalvssamarbetspartner. Deras uppgift är att hjälpa till att rensa bort demoniska angrepp, odöda lämningar och mörka kulter som hotar norra Kalimdor.",al={"varför är delgren i ashenvale","varför finns det människor i ashenvale","delgrens uppdrag"}},{q="Vad har Delgren för koppling till Tower of Althalaxx?",a="Delgren och hans följeslagare håller uppsikt över den korrumperade verksamhet som utgår från Tower of Althalaxx i norra Darkshore. Han skickar äventyrare för att undersöka ruinen, jaga Cult of the Dark Strand och slå sönder deras mörka åkallningsritualer.",al={"delgren althalaxx","uppdrag vid tower of althalaxx","cult of the dark strand"}},{q="Varför lärde sig Delgren orcspråket?",a="Delgren lärde sig orcspråket för att bättre förstå situationen och invånarna i Kalimdor, ett beslut som väckte tydligt ogillande hos hans överordnade inom orden.",al={"delgren talar orcspråket","talar delgren orcspråket","delgrens orcspråk"}},{q="Vilka arbetar tillsammans med Delgren vid Maestra's Post?",a="Han arbetar tillsammans med Balthule Shadowstrike och Feero Ironhand som en samordnad grupp för att bevaka hot vid gränsen, sköta logistiken och rensa ut skuggkultister längs Ashenvales gränsland.",al={"delgrens följeslagare","vem finns vid maestras post"}}},fx={["616c1190"]={q="På vems sida står Delgren the Purifier?",a="Delgren är en mänsklig paladin som står på Argent Dawns och Alliances sida. Han och hans medpaladiner reste över havet för att hjälpa sina Night Elf-allierade att rena Kalimdor från kvardröjande ondska.",al={"delgrens fraktion","delgren, alliance eller horde","vem tjänar delgren"}},["30d7c847"]={q="Vad vill Delgren the Purifier?",a="Delgren vill rena de uråldriga länderna Ashenvale och Darkshore från demonisk smitta och odöd förvrängning. Hans främsta mål är att slå sönder Cult of the Dark Strand och stoppa deras mörka ritualer kring Tower of Althalaxx.",al={"delgrens mål","vad gör delgren","delgrens uppdrag"}}},fp="20,201,35.413.0,23.324.1,18.313.0,28.220.0,25.136.0,52.192.0,55.226.0,29.113.0,45.198.0"}
P.entries["npc:demisette-cloyce"] = {n="Demisette Cloyce",s="I Stormwinds Mage Quarter lär Demisette Cloyce ut till häxmästare under Slaughtered Lamb. Hon vägleder elever i felmagi och hänvisar dem som är redo för mer till andra besvärjare.",h="I Stormwinds Mage Quarter lär Demisette Cloyce ut till häxmästare under Slaughtered Lamb.",kw={"cloyce","demisette","mage quarter","menara voidrender","slaughtered lamb","stormwind","häxmästartränare"},ang={["class:Warlock"]="Som häxmästare i Stormwind kan du lära dig grundläggande besvärjelsekonst av Demisette. Senare visar hon dig vägen till att göra anspråk på en felhäst och binda demoniska klot.",["race:Human"]="Som människa kan du hitta Demisette under Stormwind, där hon har vänt sig från det heliga ljuset till demonisk kraft."},sec={{t="Slaughtered Lambs kryptor",b="Häxmästare samlas i källaren under Slaughtered Lamb i Stormwinds Mage Quarter, medan stadens myndigheter upprätthåller ordningen och det heliga ljuset. Demisette Cloyce bor i katakomberna därunder och undervisar dem som är villiga att studera förbjudna konster. Hon varnar för att mörka energier bara fördärvar dem som saknar disciplin nog att bemästra dem."},{t="Att knyta samman kulterna",b="Demisette vägleder häxmästare bortom Stormwind när de har nått tillräcklig skicklighet. Hon förmedlar kontakt med besvärjare som Menara Voidrender i The Barrens, där de kan söka efter mäktiga artefakter och lära sig binda formidabla felhästar."}},faq={{q="Vem är Demisette Cloyce?",a="Demisette Cloyce tränar häxmästare under Slaughtered Lamb i Stormwinds Mage Quarter. Hon lär ut demonisk besvärjelsekonst och mörka formler.",al={"vem är demisette","demisette cloyce historia","vem är demisette cloyce"}},{q="Varför gömmer hon sig i en källare på en krog?",a="Häxmästare samlas i källaren under Slaughtered Lamb, utom allmänhetens insyn. Källaren erbjuder en undanskymd plats för deras mörka ritualer.",al={"varför är hon i källaren","varför slaughtered lamb","slaughtered lambs källare"}},{q="Vilken koppling har hon till The Barrens?",a="Demisette skickar erfarna häxmästare över havet till Menara Voidrender i Ratchet, vid The Barrens kust. De söker avancerade ritualer, kraftfulla klot och bindningsriter.",al={"demisette the barrens","på jakt efter menara voidrender","menara voidrenders koppling"}},{q="Hur reagerar hon på andra än häxmästare?",a="Demisette föraktar utomstående. Om du inte följer häxmästarens väg varnar hon dig för att mörkret inte tar emot dig och befaller dig att sluta prata och gå.",al={"demisettes dialog","prata med demisette"}}},fx={["9bf7bbcc"]={q="Vilken sida står Demisette Cloyce på?",a="Demisette Cloyce står på Alliansens sida och bor tryggt i Stormwind City. Hon verkar i hemlighet i katakomberna under Slaughtered Lamb tillsammans med andra häxmästare, men hennes lojalitet ligger hos dem som tjänar Stormwind, inte hos fiendekulter eller Burning Blade.",al={"demisette cloyces fraktion","är demisette cloyce med i alliansen","vem tjänar demisette"}},["5142027a"]={q="Vad vill Demisette Cloyce?",a="Demisette vill vägleda lovande häxmästare så att de kan bemästra farlig felmagi utan att falla för korruptionen. Hon hänvisar utövare till uråldriga artefakter och mäktiga mentorer runt om i världen, ända bort till Kalimdor. Hon tror att bara viljestarka lärjungar kan använda mörk trolldom effektivt utan att gå en för tidig och förödande död till mötes.",al={"demisette cloyces motiv","demisette cloyces mål","vad vill demisette"}}},fp="16,166,34.342.0,21.235.0,24.137.0,37.139.0,38.175.0,35.171.0"}
